local Internal = {}

function Internal.Call(Function, ...)
    if type(Function) ~= "function" then return false, nil end
    return pcall(Function, ...)
end

function Internal.Replace(Body, Old, New)
    if type(Body) ~= "string" or type(Old) ~= "string" or type(New) ~= "string" then return Body, false end
    local Start, Finish = string.find(Body, Old, 1, true)
    if not Start then return Body, false end
    return string.sub(Body, 1, Start - 1) .. New .. string.sub(Body, Finish + 1), true
end

function Internal.Upvalues(Function)
    if type(Function) ~= "function" then return nil end

    if debug and type(debug.getupvalues) == "function" then
        local Success, Values = pcall(debug.getupvalues, Function)
        if Success and type(Values) == "table" then return Values end
    end

    if type(getupvalues) == "function" then
        local Success, Values = pcall(getupvalues, Function)
        if Success and type(Values) == "table" then return Values end
    end

    if debug and type(debug.getupvalue) == "function" then
        local Values = {}

        for Index = 1, 128 do
            local Success, Name, Value = pcall(debug.getupvalue, Function, Index)
            if not Success or Name == nil then break end
            Values[Name] = Value
        end

        if next(Values) then return Values end
    end
end

function Internal.Constants(Function)
    if type(Function) ~= "function" then return nil end

    if debug and type(debug.getconstants) == "function" then
        local Success, Values = pcall(debug.getconstants, Function)
        if Success and type(Values) == "table" then return Values end
    end

    if type(getconstants) == "function" then
        local Success, Values = pcall(getconstants, Function)
        if Success and type(Values) == "table" then return Values end
    end
end

function Internal.HasConstant(Function, Marker)
    local Constants = Internal.Constants(Function)
    if not Constants then return false end

    for _, Constant in next, Constants do
        if type(Constant) == "string" and string.find(Constant, Marker, 1, true) then return true end
    end

    return false
end

function Internal.ConnectionFunction(Connection)
    if not Connection then return nil end
    local Success, Function = pcall(function() return Connection.Function or Connection.Fire end)
    return Success and Function or nil
end

