function Internal.CleanupAtramentaLegacyPerformanceRuntimes()
    if type(getgc) ~= "function" then return end

    for _, Value in next, getgc(true) do
        if type(Value) == "table" then
            if rawget(Value, "RenderStepName") == "AtramentaWorldOverride" then
                rawset(Value, "Enabled", false)

                local Connection = rawget(Value, "Connection")
                if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
                rawset(Value, "Connection", nil)

                for _, Field in ipairs({"PropertyConnections", "ChildConnections"}) do
                    local Connections = rawget(Value, Field)
                    if type(Connections) == "table" then
                        for _, Item in pairs(Connections) do
                            if Item and typeof(Item) == "RBXScriptConnection" then Item:Disconnect() end
                        end
                        table.clear(Connections)
                    end
                end

                local PostConnections = rawget(Value, "PostEffectConnections")
                if type(PostConnections) == "table" then
                    for Object, Item in pairs(PostConnections) do
                        if Item and typeof(Item) == "RBXScriptConnection" then Item:Disconnect() end
                        PostConnections[Object] = nil
                    end
                end
            elseif rawget(Value, "MaxPool") == 144 and rawget(Value, "SplashLimit") == 24 and type(rawget(Value, "Pool")) == "table"
                and type(rawget(Value, "Active")) == "table" and rawget(Value, "UpdateRate") ~= nil
            then
                rawset(Value, "Enabled", false)
                rawset(Value, "Generation", (tonumber(rawget(Value, "Generation")) or 0) + 1)

                local Connection = rawget(Value, "Connection")
                if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
                rawset(Value, "Connection", nil)

                local Folder = rawget(Value, "Folder")
                if Folder and typeof(Folder) == "Instance" and Folder.Parent and Folder.Name == "AtramentaBeamWeather" then Folder:Destroy() end
                rawset(Value, "Folder", nil)
                rawset(Value, "Anchor", nil)
                table.clear(rawget(Value, "Pool"))
                table.clear(rawget(Value, "Active"))
            end
        end
    end
end

