local AtramentaRuntimeControl = {Destroyed = false, Threads = {}, Connections = {}, Cleanups = {}}
function AtramentaRuntimeControl:AddThread(Thread)
    if Thread then self.Threads[#self.Threads + 1] = Thread end
    return Thread
end
function AtramentaRuntimeControl:AddConnection(Connection)
    if Connection then self.Connections[#self.Connections + 1] = Connection end
    return Connection
end
function AtramentaRuntimeControl:AddCleanup(Function)
    if type(Function) == "function" then self.Cleanups[#self.Cleanups + 1] = Function end
    return Function
end
function AtramentaRuntimeControl:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true

    for Index = #self.Threads, 1, -1 do
        local Thread = self.Threads[Index]
        if Thread and type(task.cancel) == "function" then Internal.Call(task.cancel, Thread) end
        self.Threads[Index] = nil
    end
    for Index = #self.Connections, 1, -1 do
        local Connection = self.Connections[Index]
        if Connection and typeof(Connection) == "RBXScriptConnection" then Internal.Call(function() Connection:Disconnect() end) end
        self.Connections[Index] = nil
    end
    for Index = #self.Cleanups, 1, -1 do
        Internal.Call(self.Cleanups[Index])
        self.Cleanups[Index] = nil
    end

    if rawget(Environment, "AtramentaRuntimeControl") == self then rawset(Environment, "AtramentaRuntimeControl", nil) end
end
