        end
    end

    function AntiFlag.SetUpvalue(Function, Index, Value)
        if type(Function) ~= "function" then return false end

        if type(setupvalue) == "function" then
            local Success = pcall(setupvalue, Function, Index, Value)
            if Success then return true end
        end

        if debug and type(debug.setupvalue) == "function" then
            return pcall(debug.setupvalue, Function, Index, Value)
