                end

                if type(rawget(Object, "DTXC1")) == "function"
                    and type(rawget(Object, "AX1")) == "function"
                    and type(rawget(Object, "GP2")) == "function"
                then
                    XIIX = Object
                end
            end
        end

        if Client then
            AntiFlag.Originals.Kill = AntiFlag.Originals.Kill or Kill
            AntiFlag.Originals.Disconnect = AntiFlag.Originals.Disconnect or Disconnect
            AntiFlag.Originals.Detected = AntiFlag.Originals.Detected or Detected
            AntiFlag.Originals.RemoteSend = AntiFlag.Originals.RemoteSend or RemoteSend
            AntiFlag.Originals.Kick = AntiFlag.Originals.Kick or Kick

