        if XIIX then
            for _, Key in next, {"DTXC1", "mainUpdt", "eCheck", "Detected", "GP", "GP2", "B", "CX1", "A"} do
                local Function = rawget(XIIX, Key)
                if type(Function) == "function" and AntiFlag.Originals[Key] == nil then
