                end
            end

            rawset(XIIX, "DTXC1", AntiFlag.Null)
            rawset(XIIX, "mainUpdt", AntiFlag.Null)
            rawset(XIIX, "eCheck", AntiFlag.Null)
            rawset(XIIX, "Detected", AntiFlag.Null)
