        local Total = 0
        for _, Count in next, AntiFlag.Patched do Total += Count end
        AntiFlag.Push("Closures " .. tostring(Total))
        return Client ~= nil or XIIX ~= nil
    end

    function AntiFlag.BlockRemotes()
        if not AntiFlag.Alive or type(getconnections) ~= "function" then return false end

        local Disabled = 0

        for _, Name in next, {"TheUltimatePunishmentMyGuy", "Z_Z", "FAILEDTOLOAD101"} do
            local Remote = ReplicatedStorage:FindFirstChild(Name, true)

            if Remote and Remote:IsA("RemoteEvent") then
                local Success, Connections = pcall(getconnections, Remote.OnClientEvent)

                if Success and type(Connections) == "table" then
                    for _, Connection in next, Connections do
                        if AntiFlag.DisableConnection(Connection) then Disabled += 1 end
                    end
                end

                pcall(function() Remote:Destroy() end)
            end
        end

        local function Scan(Parent)
            local Success, Children = pcall(Parent.GetChildren, Parent)
            if not Success or type(Children) ~= "table" then return end

            for _, Child in next, Children do
                if Child:IsA("RemoteEvent") then
                    local Adonis = false
                    local Path = Child:GetFullName()

                    if string.find(Path, "Adonis", 1, true)
                        or string.find(Path, "admin", 1, true)
                        or string.find(Path, "Admin", 1, true)
                    then
                        Adonis = true
                    else
                        local SuccessConnections, Connections = pcall(getconnections, Child.OnClientEvent)

                        if SuccessConnections and type(Connections) == "table" then
                            for _, Connection in next, Connections do
                                local Function = Internal.ConnectionFunction(Connection)
                                local Source = AntiFlag.Source(Function)

                                if string.find(Source, "Adonis", 1, true)
                                    or string.find(Source, "Anti", 1, true)
                                    or string.find(Source, "\n\n\n", 1, true)
                                then
                                    Adonis = true
                                    break
                                end
                            end
                        end
                    end

                    if Adonis then
                        local SuccessConnections, Connections = pcall(getconnections, Child.OnClientEvent)

                        if SuccessConnections and type(Connections) == "table" then
                            for _, Connection in next, Connections do
                                if AntiFlag.DisableConnection(Connection) then Disabled += 1 end
                            end
                        end

                        pcall(function() Child:Destroy() end)
                    end
                elseif Child:IsA("Folder") then
                    Scan(Child)
                end
            end
        end

        pcall(Scan, ReplicatedStorage)
        return Disabled > 0
    end

    function AntiFlag.BlockLogs()
        if not AntiFlag.Alive or type(getconnections) ~= "function" then return false end

        local Disabled = 0

        local function Disable(Signal)
            local Success, Connections = pcall(getconnections, Signal)
            if not Success or type(Connections) ~= "table" then return end

            for _, Connection in next, Connections do
                local Function = Internal.ConnectionFunction(Connection)
                local Source = AntiFlag.Source(Function)

                if string.find(Source, "Adonis", 1, true)
                    or string.find(Source, "\n\n\n", 1, true)
                then
                    if AntiFlag.DisableConnection(Connection) then Disabled += 1 end
                end
            end
        end

        pcall(Disable, LogService.MessageOut)
        pcall(Disable, ScriptContext.Error)
        return Disabled > 0
    end

    function AntiFlag.GetState()
        return {
            Alive = AntiFlag.Alive,
            Patched = AntiFlag.Patched,
            Log = AntiFlag.Log
        }
    end

    function AntiFlag.Rescan()
        AntiFlag.Pass()
        AntiFlag.BlockRemotes()
        AntiFlag.BlockLogs()
        return AntiFlag.GetState()
    end

    function AntiFlag.Shutdown()
        if not AntiFlag.Alive then return end
        AntiFlag.Alive = false

        if AntiFlag.Thread then
            pcall(task.cancel, AntiFlag.Thread)
            AntiFlag.Thread = nil
        end
    end

    Environment.CriminalityAntiFlag = AntiFlag
    AtramentaRuntimeControl:AddCleanup(AntiFlag.Shutdown)

    AntiFlag.Pass()
    AntiFlag.BlockRemotes()
    AntiFlag.BlockLogs()

    AntiFlag.Thread = AtramentaRuntimeControl:AddThread(task.spawn(function()
        while AntiFlag.Alive do
            task.wait(5)
            if AntiFlag.Alive then pcall(AntiFlag.BlockRemotes) end
        end
    end))
end


