    MinimumLibrarySize = 128,
    RequiredLibraryBuild = 29
}
if type(table.freeze) == "function" then table.freeze(RuntimeConfig) end

function Internal.FailRuntime(Message) error("Atramenta.rip: " .. tostring(Message), 0) end

