function Internal.ExtractHttpBody(Response)
    if type(Response) == "string" then return Response end
    if type(Response) ~= "table" then return nil end
    local Body = Response.Body or Response.body or Response.ResponseBody or Response.responseBody or Response.Data or Response.data
    if type(Body) == "string" then return Body end
    return nil
end

function Internal.IsValidLibrarySource(Source)
    if type(Source) ~= "string" or #Source < RuntimeConfig.MinimumLibrarySize then
        return false
    end

    local Prefix = string.lower(string.sub(Source, 1, 256))

    if string.find(Prefix, "<!doctype html", 1, true)
        or string.find(Prefix, "<html", 1, true)
    then
        return false
    end

    local BuildMarker =
        "Library.Build = "
        .. tostring(RuntimeConfig.RequiredLibraryBuild)

    return string.find(Source, BuildMarker, 1, true) ~= nil
end

function Internal.RequestLibrarySource()
    local Errors = {}
    local LocalLibraryPath = "Atramenta.rip/Library.lua"

    local function Accept(Source)
        if not Internal.IsValidLibrarySource(Source) then return nil end
        if type(writefile) == "function" then Internal.Call(writefile, LocalLibraryPath, Source) end
        return Source
    end

    local RequestFunctions = {Environment and Environment.request, Environment and Environment.http_request, type(syn) == "table" and syn.request or nil,
        type(http) == "table" and http.request or nil, type(fluxus) == "table" and fluxus.request or nil}

    for _, RequestFunction in ipairs(RequestFunctions) do
        if type(RequestFunction) == "function" then
            local Success, Response = Internal.Call(RequestFunction, {Url = RuntimeConfig.LibraryUrl, Method = "GET", Headers = {
                ["Accept"] = "text/plain,*/*", ["Cache-Control"] = "no-cache", ["User-Agent"] = "Atramenta.rip"}})
            local Source = Success and Internal.ExtractHttpBody(Response) or nil
            local Valid = Accept(Source)
            if Valid then return Valid end
            Errors[#Errors + 1] = Success and ("request returned " .. typeof(Response)) or tostring(Response)
        end
    end

    local HttpGetAttempts = {
        function() return game:HttpGet(RuntimeConfig.LibraryUrl, true) end,
        function() return game.HttpGet(game, RuntimeConfig.LibraryUrl, true) end,
        function() return game:HttpGetAsync(RuntimeConfig.LibraryUrl) end
    }

    for _, Attempt in ipairs(HttpGetAttempts) do
        local Success, Response = Internal.Call(Attempt)
        local Source = Success and Internal.ExtractHttpBody(Response) or nil
        local Valid = Accept(Source)
        if Valid then return Valid end
        Errors[#Errors + 1] = Success and ("HttpGet returned " .. typeof(Response)) or tostring(Response)
    end

    local HttpService = game:GetService("HttpService")
    local Success, Response = Internal.Call(function() return HttpService:GetAsync(RuntimeConfig.LibraryUrl, true) end)
    local Source = Success and Internal.ExtractHttpBody(Response) or nil
    local Valid = Accept(Source)
    if Valid then return Valid end
    Errors[#Errors + 1] = Success and ("GetAsync returned " .. typeof(Response)) or tostring(Response)

    if type(isfile) == "function" and type(readfile) == "function" and isfile(LocalLibraryPath) then
        local ReadSuccess, LocalSource = Internal.Call(readfile, LocalLibraryPath)
        if ReadSuccess and Internal.IsValidLibrarySource(LocalSource) then
            return LocalSource
        end
        Errors[#Errors + 1] = "local Library.lua build mismatch"
    end

    return nil, table.concat(Errors, " | ")
end

function Internal.LoadAtramentaLibrary()
    local LibrarySource, RequestError = Internal.RequestLibrarySource()

    if not Internal.IsValidLibrarySource(LibrarySource) then
        Internal.FailRuntime(
            "library build mismatch; required "
            .. tostring(RuntimeConfig.RequiredLibraryBuild)
            .. ": "
            .. tostring(RequestError or "no compatible source")
        )
    end

    local LibraryChunk, CompileError =
        loadstring(
            LibrarySource,
            "@Atramenta.rip/Library.lua"
        )

    if type(LibraryChunk) ~= "function" then
        Internal.FailRuntime(
            "library compile failed: "
            .. tostring(CompileError)
        )
    end

    local ExecuteSuccess, LibraryResult =
        Internal.Call(LibraryChunk)

    LibraryChunk = nil
    LibrarySource = nil

    if not ExecuteSuccess then
        Internal.FailRuntime(
            "library execution failed: "
            .. tostring(LibraryResult)
        )
    end

    if type(LibraryResult) ~= "table" then
        LibraryResult = Environment.Library
    end

    if type(LibraryResult) ~= "table"
        or tonumber(LibraryResult.Build)
            ~= RuntimeConfig.RequiredLibraryBuild
    then
        Internal.FailRuntime(
            "library build mismatch after load"
        )
    end

    local RequiredMethods = {
        "Window",
        "Notification",
        "Watermark",
        "KeybindList",
        "PlayerList",
        "GetConfig",
        "LoadConfig"
    }

    for _, MethodName in ipairs(RequiredMethods) do
        if type(LibraryResult[MethodName]) ~= "function" then
            Internal.FailRuntime(
                "library API missing "
                .. MethodName
            )
        end
    end

    return LibraryResult
end

