if type(AtramentaRageFireRate) ~= "table" then
    AtramentaRageFireRate = {Enabled = false, MaxRate = 999999, Originals = setmetatable({}, {__mode = "k"}), Modules = setmetatable({}, {__mode = "k"}), HookVersion = 0}
    rawset(Environment, "AtramentaRageFireRate", AtramentaRageFireRate)
