local AtramentaWeaponConfigSource = rawget(Environment, "AtramentaWeaponConfigSource")
if type(AtramentaWeaponConfigSource) ~= "table" then
    AtramentaWeaponConfigSource = {Enabled = false, Originals = setmetatable({}, {__mode = "k"}), Configs = setmetatable({}, {__mode = "k"}), Settings = {}}
    rawset(Environment, "AtramentaWeaponConfigSource", AtramentaWeaponConfigSource)
else
    if type(AtramentaWeaponConfigSource.Originals) == "table" then
        for Config, Original in pairs(AtramentaWeaponConfigSource.Originals) do
            if type(Config) == "table" and type(Original) == "table" then
                local WasReadonly = type(isreadonly) == "function" and type(setreadonly) == "function" and isreadonly(Config)
                if WasReadonly then Internal.Call(setreadonly, Config, false) end
                for Field, Value in pairs(Original) do Internal.Call(function() Config[Field] = Value end) end
                if WasReadonly then Internal.Call(setreadonly, Config, true) end
            end
        end
    end
    AtramentaWeaponConfigSource.Enabled = false
    AtramentaWeaponConfigSource.Originals = setmetatable({}, {__mode = "k"})
    AtramentaWeaponConfigSource.Configs = setmetatable({}, {__mode = "k"})
    AtramentaWeaponConfigSource.Settings = {}
end

local WeaponConfigSourceFields = {"Spread", "Recoil", "ChargeTime", "FireRate", "ReloadTime", "ReloadAnimSpeed", "ReloadSlowDown", "EquipTime", "EquipAnimSpeed"}

function SetAtramentaConfigField(Config, Field, Value)
    if type(Config) ~= "table" or rawget(Config, Field) == nil then return false end
    local WasReadonly = type(isreadonly) == "function" and type(setreadonly) == "function" and isreadonly(Config)
    if WasReadonly then Internal.Call(setreadonly, Config, false) end
    local Success = Internal.Call(function() Config[Field] = Value end)
    if WasReadonly then Internal.Call(setreadonly, Config, true) end
    return Success
end

function SetAtramentaNestedConfigField(TableValue, Field, Value)
    if type(TableValue) ~= "table" or rawget(TableValue, Field) == nil then return false end
    local WasReadonly = type(isreadonly) == "function" and type(setreadonly) == "function" and isreadonly(TableValue)
    if WasReadonly then Internal.Call(setreadonly, TableValue, false) end
    local Success = Internal.Call(function() TableValue[Field] = Value end)
    if WasReadonly then Internal.Call(setreadonly, TableValue, true) end
    return Success
end

function RegisterAtramentaWeaponConfigSource(Config)
    if type(Config) ~= "table" then return false end
    local Original = AtramentaWeaponConfigSource.Originals[Config]
    if type(Original) ~= "table" then
        Original = {}
        for _, Field in ipairs(WeaponConfigSourceFields) do
            local Value = rawget(Config, Field)
            if Field == "FireRate" and type(AtramentaRageFireRate.Originals[Config]) == "number" then Value = AtramentaRageFireRate.Originals[Config] end
            if type(Value) == "number" then Original[Field] = Value end
        end
        local SlowDown = rawget(Config, "SlowDown")
        local FireSlowDown = rawget(Config, "FireSlowDown")
        local ChargeUpSettings = rawget(Config, "ChargeUpSettings")
        if type(SlowDown) == "table" and type(rawget(SlowDown, "Enabled")) == "boolean" then Original.SlowDownEnabled = rawget(SlowDown, "Enabled") end
        if type(FireSlowDown) == "table" and type(rawget(FireSlowDown, "Enabled")) == "boolean" then Original.FireSlowDownEnabled = rawget(FireSlowDown, "Enabled") end
        if type(ChargeUpSettings) == "table" then
            if type(rawget(ChargeUpSettings, "ChargeTime")) == "number" then Original.ChargeUpTime = rawget(ChargeUpSettings, "ChargeTime") end
            if type(rawget(ChargeUpSettings, "ChargeDB")) == "number" then Original.ChargeUpDB = rawget(ChargeUpSettings, "ChargeDB") end
        end
        AtramentaWeaponConfigSource.Originals[Config] = Original
    end
    if type(Original.FireRate) == "number" and AtramentaRageFireRate.Originals[Config] == nil then AtramentaRageFireRate.Originals[Config] = Original.FireRate end
    AtramentaWeaponConfigSource.Configs[Config] = true
    return true
end

function ApplyAtramentaWeaponConfigSource(Config)
    if not RegisterAtramentaWeaponConfigSource(Config) then return false end
    local Original = AtramentaWeaponConfigSource.Originals[Config]
    local Settings = AtramentaWeaponConfigSource.Settings or {}
    local Active = AtramentaWeaponConfigSource.Enabled == true

    if type(Original.Spread) == "number" then
        local Spread = Original.Spread
        if Active and Settings.NoSpread == true then Spread = 0.001
        elseif Active and Settings.CustomSpread == true then Spread = math.max(tonumber(Settings.SpreadAmount) or 0, 0) end
        SetAtramentaConfigField(Config, "Spread", Spread)
    end

    if type(Original.Recoil) == "number" then
        local Recoil = Original.Recoil
        if Active and Settings.NoRecoil == true then
            local Scale = math.clamp(tonumber(Settings.RecoilScale) or 0, 0, 1)
            Recoil = Scale <= 0.001 and (Recoil == 0 and 0 or 0.001) or Recoil * Scale
        end
        SetAtramentaConfigField(Config, "Recoil", Recoil)
    end

    if type(Original.ChargeTime) == "number" then SetAtramentaConfigField(Config, "ChargeTime", Active and Settings.InstantCharge == true and 0.01 or Original.ChargeTime) end
    if type(Original.ReloadTime) == "number" then SetAtramentaConfigField(Config, "ReloadTime", Active and Settings.InstantReload == true and 0.01 or Original.ReloadTime) end
    if type(Original.ReloadAnimSpeed) == "number" then SetAtramentaConfigField(Config, "ReloadAnimSpeed", Active and Settings.InstantReload == true and 999 or Original.ReloadAnimSpeed) end
    if type(Original.ReloadSlowDown) == "number" then SetAtramentaConfigField(Config, "ReloadSlowDown", Active and (Settings.InstantReload == true or Settings.NoSlowdown == true) and 0 or Original.ReloadSlowDown) end
    if type(Original.EquipTime) == "number" then SetAtramentaConfigField(Config, "EquipTime", Active and Settings.InstantEquip == true and 0.01 or Original.EquipTime) end
    if type(Original.EquipAnimSpeed) == "number" then SetAtramentaConfigField(Config, "EquipAnimSpeed", Active and Settings.InstantEquip == true and 999 or Original.EquipAnimSpeed) end

    local SlowDown = rawget(Config, "SlowDown")
    local FireSlowDown = rawget(Config, "FireSlowDown")
    local ChargeUpSettings = rawget(Config, "ChargeUpSettings")
    if type(SlowDown) == "table" and type(Original.SlowDownEnabled) == "boolean" then
        local Enabled = Original.SlowDownEnabled
        if Active and Settings.NoSlowdown == true then Enabled = false end
        SetAtramentaNestedConfigField(SlowDown, "Enabled", Enabled)
    end
    if type(FireSlowDown) == "table" and type(Original.FireSlowDownEnabled) == "boolean" then
        local Enabled = Original.FireSlowDownEnabled
        if Active and Settings.NoSlowdown == true then Enabled = false end
        SetAtramentaNestedConfigField(FireSlowDown, "Enabled", Enabled)
    end
    if type(ChargeUpSettings) == "table" then
        if type(Original.ChargeUpTime) == "number" then SetAtramentaNestedConfigField(ChargeUpSettings, "ChargeTime", Active and Settings.InstantCharge == true and 0.01 or Original.ChargeUpTime) end
        if type(Original.ChargeUpDB) == "number" then SetAtramentaNestedConfigField(ChargeUpSettings, "ChargeDB", Active and Settings.InstantCharge == true and 0.01 or Original.ChargeUpDB) end
    end

    if type(Original.FireRate) == "number" then
        local FireRate = Active and Settings.InstantFireRate == true and 999 or Original.FireRate
        if AtramentaRageFireRate.Enabled == true then FireRate = AtramentaRageFireRate.MaxRate end
        SetAtramentaConfigField(Config, "FireRate", FireRate)
    end

    if type(rawget(Config, "Range")) == "number" then
        if AtramentaInfiniteRange.Originals[Config] == nil then AtramentaInfiniteRange.Originals[Config] = rawget(Config, "Range") end
        local InfiniteRange = Active and Settings.InfiniteRange == true
        SetAtramentaConfigField(Config, "Range", InfiniteRange and 99999 or AtramentaInfiniteRange.Originals[Config])
    end

    return true
end

function RestoreAtramentaWeaponConfigSource()
    AtramentaWeaponConfigSource.Enabled = false
    for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
end

function SetAtramentaInfiniteRangeEnabled(Value)
    local Enabled = Value == true
    if Configuration and Configuration.NoRecoil and Configuration.NoRecoil.Settings and Configuration.NoRecoil.Settings.GunMods then
        Configuration.NoRecoil.Settings.GunMods.InfiniteRange = Enabled
    end
    AtramentaWeaponConfigSource.Settings.InfiniteRange = Enabled
    AtramentaInfiniteRange.Enabled = AtramentaWeaponConfigSource.Enabled == true and Enabled
    for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
    for Config, OriginalRange in pairs(AtramentaInfiniteRange.Originals) do
        if type(Config) == "table" and type(OriginalRange) == "number" and not AtramentaWeaponConfigSource.Configs[Config] then
            SetAtramentaConfigField(Config, "Range", AtramentaInfiniteRange.Enabled and 99999 or OriginalRange)
        end
    end
end

if PreviousRageFireRateHookVersion > 0 and PreviousRageFireRateHookVersion < 6 and type(restorefunction) == "function" then
    local Restored = Internal.Call(restorefunction, require)
    if Restored then AtramentaRageFireRate.HookVersion = 0 end
end

if AtramentaRageFireRate.HookVersion ~= 6 and type(hookfunction) == "function" and type(newcclosure) == "function" then
    local OldRequire
    OldRequire = hookfunction(require, newcclosure(function(Module)
        local Result = OldRequire(Module)
        if typeof(Module) == "Instance" and Module:IsA("ModuleScript") and Module.Name == "Config" and type(Result) == "table" then
            AtramentaRageFireRate.Modules[Module] = Result
            RegisterAtramentaWeaponConfigSource(Result)
            ApplyAtramentaWeaponConfigSource(Result)
        end
        return Result
    end))
    AtramentaRageFireRate.HookVersion = 6
    AtramentaRageFireRate.BaseRequire = OldRequire
end

function RefreshAtramentaRageFireRateTool(Tool)
    if not Tool or not Tool.Parent then return false end
    local ConfigModule = Tool:FindFirstChild("Config")
    if not ConfigModule or not ConfigModule:IsA("ModuleScript") then return false end
    local Success, Result = Internal.Call(require, ConfigModule)
    if not Success or type(Result) ~= "table" then return false end
    AtramentaRageFireRate.Modules[ConfigModule] = Result
    RegisterAtramentaWeaponConfigSource(Result)
    ApplyAtramentaWeaponConfigSource(Result)
    return AtramentaRageFireRate.Enabled == true
end

function RestoreAtramentaRageFireRate()
    AtramentaRageFireRate.Enabled = false
    for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
    for Config, OriginalFireRate in pairs(AtramentaRageFireRate.Originals) do
        if type(Config) == "table" and type(OriginalFireRate) == "number" and not AtramentaWeaponConfigSource.Configs[Config] then
            Internal.Call(function() Config.FireRate = OriginalFireRate end)
        end
    end
end

