local HitSoundPreviewSuppressedUntil = 0
local OriginalLibraryLoadConfig = type(Library.LoadConfig) == "function" and Library.LoadConfig or nil

if OriginalLibraryLoadConfig then
    Library.LoadConfig = function(Self, Source)
        local SuppressUntil = os.clock() + 0.30
        HitSoundPreviewSuppressedUntil = math.max(HitSoundPreviewSuppressedUntil, SuppressUntil)

        local Results = table.pack(OriginalLibraryLoadConfig(Self, Source))

        task.delay(0.30, function()
            if HitSoundPreviewSuppressedUntil <= SuppressUntil then HitSoundPreviewSuppressedUntil = 0 end
        end)

        return table.unpack(Results, 1, Results.n)
    end
end

