function GetVisualHeavyEspInterval(PlayerCount)
    PlayerCount = math.max(math.floor(tonumber(PlayerCount) or 0), 0)
    if PlayerCount >= 32 then return 1 / 24 end
    if PlayerCount >= 24 then return 1 / 27 end
    return 1 / 30
end

function GetVisualHeavyBatchDivisor(PlayerCount)
    PlayerCount = math.max(math.floor(tonumber(PlayerCount) or 0), 0)
    if PlayerCount >= 24 then return 3 end
    if PlayerCount >= 14 then return 2 end
    return 1
end

function GetFastVisualResolverSnapshot(Data)
    if not Data or Data.VisualResolverCharacter ~= Data.Character then return nil end
    local Snapshot = Data.VisualResolverSnapshot
    if type(Snapshot) ~= "table" then return nil end
    return Snapshot
end

VisualState.Widgets = { WatermarkScale = 1 }

local ResolveTrackedCharacter

BacktrackVisualState = {
    Enabled = false,
    Scope = "All",
    MaxDistance = 1800,
    Color = Color3.fromRGB(243, 167, 124),
    Transparency = 0.68,
    ThroughWalls = false,
    ReplicationVerification = true,
    RecordInterval = 1 / 60,
    MaxRecords = 32,
    FrameTime = 1 / 60,
    PingSeconds = 0,
    ServerTickRate = 60,
    AdaptiveDelay = 0.08,
    NextTimingUpdate = 0,
    BodyParts = {
        Head = true, Torso = true, UpperTorso = true, LowerTorso = true,
        ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
        LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
        RightUpperArm = true, RightLowerArm = true, RightHand = true,
        LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
        RightUpperLeg = true, RightLowerLeg = true, RightFoot = true
    },
    Records = setmetatable({}, {__mode = "k"}),
    Objects = setmetatable({}, {__mode = "k"}),
    PlayerSet = setmetatable({}, {__mode = "k"}),
    Players = {},
    LocalStableSnapshot = nil,
    Connection = nil,
    PlayerAddedConnection = nil,
    PlayerRemovingConnection = nil,
    Folder = nil,
    Clock = 0,
    Cursor = 1
}

function BacktrackVisualState:GetFolder()
    if self.Folder and self.Folder.Parent then return self.Folder end

    local Folder = Instance.new("Folder")
    Folder.Name = "AtramentaBacktrackPosition"
    Folder.Parent = workspace
    self.Folder = Folder
    return Folder
end

function BacktrackVisualState:NormalizeScope(Value)
    Value = tostring(Value or "All")
    if Value == "Players" or Value == "Local Player" or Value == "All" then return Value end
    return "All"
end

function BacktrackVisualState:ShouldTrack(Player)
    if not Player then return false end

    local Scope = self:NormalizeScope(self.Scope)
    if Scope == "Local Player" then return Player == LocalPlayer end
    if Scope == "Players" then return Player ~= LocalPlayer end
    return true
end

function BacktrackVisualState:SetScope(Value)
    self.Scope = self:NormalizeScope(Value)

    for Player in pairs(self.Objects) do
        if not self:ShouldTrack(Player) then self:DestroyObject(Player) end
    end

    for Player in pairs(self.Records) do
        if not self:ShouldTrack(Player) then self.Records[Player] = nil end
    end
end

function BacktrackVisualState:AddPlayer(Player)
    if not Player or self.PlayerSet[Player] then return end
    self.PlayerSet[Player] = true
    self.Players[#self.Players + 1] = Player
end

function BacktrackVisualState:RemovePlayer(Player)
    if not Player or not self.PlayerSet[Player] then return end

    self.PlayerSet[Player] = nil
    self:DestroyObject(Player)
    self.Records[Player] = nil

    for Index = #self.Players, 1, -1 do
        if self.Players[Index] == Player then
            local LastIndex = #self.Players
            self.Players[Index] = self.Players[LastIndex]
            self.Players[LastIndex] = nil
            break
        end
    end
end

function BacktrackVisualState:RebuildPlayerCache()
    table.clear(self.Players)
    self.PlayerSet = setmetatable({}, {__mode = "k"})

    for _, Player in ipairs(Players:GetPlayers()) do
        self:AddPlayer(Player)
    end
end

function BacktrackVisualState:GetServerTickRate()
    local TickRate = 60

    if type(Ragebot) == "table" and type(Ragebot.Runtime) == "table"
        and type(Ragebot.Runtime.SimulationSettings) == "table"
    then
        TickRate = tonumber(Ragebot.Runtime.SimulationSettings.ServerTickRate) or TickRate
    end

    return math.clamp(TickRate, 20, 128)
end

function BacktrackVisualState:UpdateTiming(DeltaTime, CurrentTime)
    local FrameSample = math.clamp(tonumber(DeltaTime) or 1 / 60, 1 / 360, 1 / 15)
    self.FrameTime += (FrameSample - self.FrameTime) * 0.10
    self.RecordInterval = math.clamp(self.FrameTime, 1 / 60, 1 / 20)

    if CurrentTime < (tonumber(self.NextTimingUpdate) or 0) then return end
    self.NextTimingUpdate = CurrentTime + 0.25

    local Ping = 0

    if type(ResolverGetPingSeconds) == "function" then
        Ping = ResolverGetPingSeconds()
    else
        Internal.Call(function()
            Ping = tonumber(LocalPlayer:GetNetworkPing()) or 0
        end)
    end

    self.PingSeconds = math.clamp(tonumber(Ping) or 0, 0, 1.5)
    self.ServerTickRate = self:GetServerTickRate()
end

function BacktrackVisualState:GetDelay(Player)
    local TickLength = 1 / math.clamp(tonumber(self.ServerTickRate) or 60, 20, 128) local OneWayLatency = math.clamp(tonumber(self.PingSeconds) or 0, 0, 1.5) * 0.5
    local FrameLead = math.clamp(tonumber(self.FrameTime) or 1 / 60, 1 / 360, 1 / 15)

    local Delay

    if Player == LocalPlayer then
        Delay = TickLength * 1.15 + OneWayLatency * 0.35 + FrameLead * 0.35
    else
        Delay = TickLength * 1.50 + OneWayLatency * 0.75 + FrameLead * 0.50
    end

    Delay = math.clamp(Delay, TickLength, 0.24)
    self.AdaptiveDelay = Delay
    return Delay
end

function BacktrackVisualState:GetPartReferences(Character, State)
    if not Character then return nil end

    State = type(State) == "table" and State or {}
    local References = State.PartReferences

    if type(References) == "table" and State.PartReferenceCharacter == Character then
        local Valid = true
        for _, Part in pairs(References) do
            if not Part or Part.Parent ~= Character then Valid = false break end
        end
        if Valid then return References end
    end

    References = {}
    for Name in pairs(self.BodyParts) do
        local Part = Character:FindFirstChild(Name)
        if Part and Part:IsA("BasePart") and Part.Parent == Character and Part.Size.Magnitude <= 12 then References[Name] = Part end
    end

    State.PartReferences = References
    State.PartReferenceCharacter = Character
    return References
end

function BacktrackVisualState:CaptureParts(Character, State)
    local References = self:GetPartReferences(Character, State)
    if type(References) ~= "table" then return nil end

    local Parts = {}
    for Name, Part in pairs(References) do
        if Part and Part.Parent == Character then Parts[Name] = Part.CFrame end
    end
    return next(Parts) and Parts or nil
end

function BacktrackVisualState:SetLocalStableSnapshot(Character, Root, CurrentTime)
    if not self.Enabled or not self:ShouldTrack(LocalPlayer) or not Character or not Root or not Root.Parent then return end

    self.LocalReferenceState = type(self.LocalReferenceState) == "table" and self.LocalReferenceState or {}
    local Parts = self:CaptureParts(Character, self.LocalReferenceState) if not Parts then return end

    self.LocalStableSnapshot = { Time = tonumber(CurrentTime) or os.clock(), Character = Character, RootCFrame = Root.CFrame, Parts = Parts, Source = "Invisibility" }
end

function BacktrackVisualState:GetLocalSource(Character, Root, CurrentTime)
    local NetworkModified = HideHeadEnabled == true or HideHeadController and (
            HideHeadController.FakeLagEnabled == true
            or HideHeadController.FakeDirectionEnabled == true
            or HideHeadController.FakePositionEnabled == true
        )
        or FlyEnabled == true and FlyMethod == "Velocity"

    if NetworkModified and type(GetAtramentaLocalServerReplicaSnapshot) == "function" then
        local Replica = GetAtramentaLocalServerReplicaSnapshot(CurrentTime)

        if Replica and typeof(Replica.RootCFrame) == "CFrame" and (tonumber(Replica.Age) or math.huge) <= 0.50 then
            return {
                RootCFrame = Replica.RootCFrame,
                Parts = type(Replica.Parts) == "table" and Replica.Parts or nil,
                Source = "ServerReplica",
                Sequence = Replica.Sequence,
                FakeLag = Replica.FakeLag == true,
                FakePosition = Replica.FakePosition == true,
                FakePositionMode = Replica.FakePositionMode
            }
        end
    end

    if InvisibilityEnabled == true then
        local Stable = self.LocalStableSnapshot

        if type(Stable) == "table" and Stable.Character == Character and typeof(Stable.RootCFrame) == "CFrame"
            and CurrentTime - (tonumber(Stable.Time) or 0) <= 0.20
        then
            return {
                RootCFrame = Stable.RootCFrame,
                Parts = Stable.Parts,
                Source = "Invisibility"
            }
        end
    end

    if type(GetAtramentaLocalServerReplicaSnapshot) == "function" then
        local Replica = GetAtramentaLocalServerReplicaSnapshot(CurrentTime)

        if Replica and typeof(Replica.RootCFrame) == "CFrame" and (tonumber(Replica.Age) or math.huge) <= 0.18 then
            return {
                RootCFrame = Replica.RootCFrame,
                Parts = type(Replica.Parts) == "table" and Replica.Parts or nil,
                Source = "ServerReplica",
                Sequence = Replica.Sequence
            }
        end
    end

    return {
        RootCFrame = Root.CFrame,
        Parts = self:CaptureParts(Character, self.LocalReferenceState),
        Source = "Character"
    }
end

function BacktrackVisualState:Capture(Player, Character, Root, CurrentTime)
    if not Player or not Character or not Root or not Root.Parent or not self:ShouldTrack(Player) then return end

    local State = self.Records[Player]

    if type(State) ~= "table" or State.Character ~= Character then
        State = {Character = Character, LastSample = 0, Samples = {}, StartIndex = 1, PartReferences = nil, PartReferenceCharacter = nil}
        self.Records[Player] = State
    end

    if CurrentTime - (tonumber(State.LastSample) or 0) < self.RecordInterval then return end
    State.LastSample = CurrentTime

    local RootCFrame local Parts local Source = "Character" local Sequence
    local FakeLag = false local FakePosition = false local FakePositionMode

    if Player == LocalPlayer then
        local Snapshot = self:GetLocalSource(Character, Root, CurrentTime)
        if not Snapshot or typeof(Snapshot.RootCFrame) ~= "CFrame" then return end

        RootCFrame = Snapshot.RootCFrame
        Parts = type(Snapshot.Parts) == "table" and Snapshot.Parts or nil
        Source = tostring(Snapshot.Source or "Character")
        Sequence = Snapshot.Sequence
        FakeLag = Snapshot.FakeLag == true
        FakePosition = Snapshot.FakePosition == true
        FakePositionMode = Snapshot.FakePositionMode
    else
        RootCFrame = Root.CFrame
        Parts = self:CaptureParts(Character, State)
    end

    if type(Parts) ~= "table" or next(Parts) == nil then
        Parts = {}
        local CurrentRoot = Root.CFrame
        local References = self:GetPartReferences(Character, State) or {}

        for Name, Part in pairs(References) do
            if Part and Part.Parent == Character then Parts[Name] = RootCFrame * CurrentRoot:ToObjectSpace(Part.CFrame) end
        end
    end

    if next(Parts) == nil then return end

    local Samples = State.Samples
    Samples[#Samples + 1] = {
        Time = CurrentTime,
        RootCFrame = RootCFrame,
        Parts = Parts,
        Source = Source,
        Sequence = Sequence,
        FakeLag = FakeLag,
        FakePosition = FakePosition,
        FakePositionMode = FakePositionMode
    }

    if #Samples > self.MaxRecords then table.remove(Samples, 1) end
end

function BacktrackVisualState:GetRecord(Player, CurrentTime)
    local State = self.Records[Player]
    if type(State) ~= "table" or type(State.Samples) ~= "table" or #State.Samples == 0 then return nil end

    local TargetTime = CurrentTime - self:GetDelay(Player) local Samples = State.Samples local Selected = Samples[1]

    for Index = #Samples, 1, -1 do
        local Sample = Samples[Index]

        if Sample.Time <= TargetTime then
            Selected = Sample
            break
        end
    end

    if not Selected or CurrentTime - (tonumber(Selected.Time) or 0) > 0.75 then return nil end
    return Selected
end

function BacktrackVisualState:DestroyObject(Player)
    local Object = self.Objects[Player] if not Object then return end

    if Object.Model then Object.Model:Destroy() end
    self.Objects[Player] = nil
end

function BacktrackVisualState:StripClone(Clone)
    for _, Descendant in ipairs(Clone:GetDescendants()) do
        if Descendant:IsA("JointInstance") or Descendant:IsA("Constraint") or Descendant:IsA("Attachment")
            or Descendant:IsA("Script") or Descendant:IsA("LocalScript") or Descendant:IsA("ParticleEmitter")
            or Descendant:IsA("Trail") or Descendant:IsA("Beam") or Descendant:IsA("BillboardGui")
            or Descendant:IsA("SurfaceGui") or Descendant:IsA("Decal") or Descendant:IsA("Texture")
            or Descendant:IsA("SurfaceAppearance")
        then
            Descendant:Destroy()
        elseif Descendant:IsA("SpecialMesh") then
            Descendant.TextureId = ""
        end
    end
end

function BacktrackVisualState:ApplyPartAppearance(Part)
    if not Part or not Part:IsA("BasePart") then return end

    Part.Anchored = true
    Part.CanCollide = false
    Part.CanTouch = false
    Part.CanQuery = false
    Part.CastShadow = false
    Part.Massless = true
    Part.Material = Enum.Material.ForceField
    Part.Color = self.Color
    Part.Transparency = math.clamp(tonumber(self.Transparency) or 0.68, 0.05, 0.95)

    if Part:IsA("MeshPart") then Part.TextureID = "" end
end

function BacktrackVisualState:CreateXRayAdornment(Part, Parent)
    if not Part or not Part:IsA("BasePart") then return nil end

    local Adornment = Instance.new("BoxHandleAdornment")
    Adornment.Name = "BacktrackXRay"
    Adornment.Adornee = Part
    Adornment.Size = Part.Size + Vector3.new(0.035, 0.035, 0.035)
    Adornment.AlwaysOnTop = true
    Adornment.ZIndex = 10
    Adornment.Color3 = self.Color
    Adornment.Transparency = math.clamp((tonumber(self.Transparency) or 0.68) * 0.68, 0.10, 0.82)
    Adornment.Visible = self.ThroughWalls == true
    Adornment.Parent = Parent
    return Adornment
end

function BacktrackVisualState:ApplyHighlight(Object)
    if not Object or not Object.Highlight then return end

    local Transparency = math.clamp(tonumber(self.Transparency) or 0.68, 0.05, 0.95) local Highlight = Object.Highlight

    Highlight.FillColor = self.Color
    Highlight.OutlineColor = self.Color
    Highlight.DepthMode = self.ThroughWalls and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded

    if self.ThroughWalls then
        Highlight.FillTransparency = math.clamp(Transparency * 0.62, 0.18, 0.68)
        Highlight.OutlineTransparency = math.clamp(Transparency * 0.42, 0.04, 0.52)
    else
        Highlight.FillTransparency = math.clamp(Transparency + 0.14, 0.20, 1)
        Highlight.OutlineTransparency = math.clamp(Transparency - 0.22, 0.05, 0.92)
    end
end

function BacktrackVisualState:ApplyObjectAppearance(Object)
    if not Object or type(Object.Parts) ~= "table" then return end

    if Object.LastColor == self.Color and Object.LastTransparency == self.Transparency
        and Object.LastThroughWalls == self.ThroughWalls
    then
        return
    end

    Object.LastColor = self.Color
    Object.LastTransparency = self.Transparency
    Object.LastThroughWalls = self.ThroughWalls

    for Name, Part in pairs(Object.Parts) do
        self:ApplyPartAppearance(Part)

        local Adornment = Object.XRayParts and Object.XRayParts[Name]
        if Adornment and Adornment.Parent then
            Adornment.Size = Part.Size + Vector3.new(0.035, 0.035, 0.035)
            Adornment.Color3 = self.Color
            Adornment.Transparency = math.clamp((tonumber(self.Transparency) or 0.68) * 0.68, 0.10, 0.82)
            Adornment.Visible = self.ThroughWalls == true
        end
    end

    self:ApplyHighlight(Object)
end

function BacktrackVisualState:BuildObject(Player, Character)
    self:DestroyObject(Player)
    if not Player or not Character then return nil end

    local Root = ResolverGetRoot(Character)
    if not Root then return nil end

    local Model = Instance.new("Model")
    Model.Name = "Backtrack_" .. tostring(Player.Name)

    local Parts = {}
    local XRayParts = {}

    for Name in pairs(self.BodyParts) do
        local Original = Character:FindFirstChild(Name)

        if Original and Original:IsA("BasePart") and Original.Parent == Character and Original ~= Root
            and Original.Archivable and Original.Size.Magnitude <= 12
        then
            local Clone = Original:Clone()
            self:StripClone(Clone)
            self:ApplyPartAppearance(Clone)
            Clone.Name = Name
            Clone.Parent = Model
            Parts[Name] = Clone
            XRayParts[Name] = self:CreateXRayAdornment(Clone, Model)
        end
    end

    if next(Parts) == nil then
        Model:Destroy()
        return nil
    end

    local Highlight = Instance.new("Highlight")
    Highlight.Name = "BacktrackHighlight"
    Highlight.Adornee = Model
    Highlight.Parent = Model

    Model.Parent = self:GetFolder()

    local Object = { Character = Character, Root = Root, Model = Model, Parts = Parts, XRayParts = XRayParts, Highlight = Highlight, Visible = true, Source = "Character" }

    self.Objects[Player] = Object
    self:ApplyObjectAppearance(Object)
    return Object
end

function BacktrackVisualState:SetObjectVisible(Object, Visible)
    if not Object or not Object.Model then return end

    if Visible then
        if Object.Model.Parent ~= self:GetFolder() then Object.Model.Parent = self:GetFolder() end
    elseif Object.Model.Parent then
        Object.Model.Parent = nil
    end

    Object.Visible = Visible == true
end

function BacktrackVisualState:RefreshAppearance()
    for _, Object in pairs(self.Objects) do
        if Object then
            Object.LastColor = nil
            Object.LastTransparency = nil
            Object.LastThroughWalls = nil
            self:ApplyObjectAppearance(Object)
        end
    end
end

function BacktrackVisualState:UpdatePlayer(Player, CurrentTime, LocalRoot)
    if not Player or Player.Parent ~= Players or not self:ShouldTrack(Player) then
        if Player then
            self:DestroyObject(Player)
            self.Records[Player] = nil
        end
        return
    end

    local Character = Player == LocalPlayer and LocalPlayer.Character or ResolveTrackedCharacter(Player, Player.Character) or Player.Character
    local Root = Character and ResolverGetRoot(Character)

    if not Character or not Root or not Root.Parent then
        self:DestroyObject(Player)
        self.Records[Player] = nil
        return
    end

    self:Capture(Player, Character, Root, CurrentTime)

    if Player ~= LocalPlayer and LocalRoot
        and (Root.Position - LocalRoot.Position).Magnitude > math.max(tonumber(self.MaxDistance) or 1800, 100)
    then
        local Object = self.Objects[Player]
        if Object then self:SetObjectVisible(Object, false) end
        return
    end

    local Record = self:GetRecord(Player, CurrentTime) local Object = self.Objects[Player]

    if not Record or type(Record.Parts) ~= "table" then
        if Object then self:SetObjectVisible(Object, false) end
        return
    end

    if not Object or Object.Character ~= Character or Object.Root ~= Root or not Object.Model then Object = self:BuildObject(Player, Character) end

    if not Object then return end

    self:SetObjectVisible(Object, true)
    Object.Source = tostring(Record.Source or "Character")
    Object.Sequence = Record.Sequence
    Object.FakeLag = Record.FakeLag == true
    Object.FakePosition = Record.FakePosition == true
    Object.FakePositionMode = Record.FakePositionMode

    self:ApplyObjectAppearance(Object)

    local CurrentRootCFrame = Root.CFrame

    for Name, Clone in pairs(Object.Parts) do
        local Historical = Record.Parts[Name]

        if typeof(Historical) == "CFrame" then
            Clone.CFrame = Historical
        else
            local CurrentPart = Character:FindFirstChild(Name)

            if CurrentPart and CurrentPart:IsA("BasePart") and typeof(Record.RootCFrame) == "CFrame" then
                Clone.CFrame = Record.RootCFrame * CurrentRootCFrame:ToObjectSpace(CurrentPart.CFrame)
            end
        end
    end
end

function BacktrackVisualState:Step(DeltaTime)
    if not self.Enabled then return end

    local CurrentTime = os.clock()
    self:UpdateTiming(DeltaTime, CurrentTime)

    self.Clock += math.clamp(tonumber(DeltaTime) or 0, 0, 0.10)
    if self.Clock < self.RecordInterval then return end
    self.Clock = self.Clock % self.RecordInterval

    local Character = LocalPlayer.Character local LocalRoot = Character and ResolverGetRoot(Character) local CachedPlayers = self.Players local Count = #CachedPlayers

    if Count == 0 then
        self.Cursor = 1
        return
    end

    local Divisor = Count >= 24 and 3 or Count >= 12 and 2 or 1 local BatchSize = math.max(1, math.ceil(Count / Divisor))
    local Cursor = math.clamp(math.floor(tonumber(self.Cursor) or 1), 1, Count)

    for Offset = 0, BatchSize - 1 do
        local Index = ((Cursor + Offset - 1) % Count) + 1 local Player = CachedPlayers[Index]

        if Player and Player.Parent == Players and self:ShouldTrack(Player) then self:UpdatePlayer(Player, CurrentTime, LocalRoot) end
    end

    self.Cursor = ((Cursor + BatchSize - 1) % Count) + 1
end

function BacktrackVisualState:DisconnectRuntime()
    if self.Connection then
        self.Connection:Disconnect()
        self.Connection = nil
    end

    if self.PlayerAddedConnection then
        self.PlayerAddedConnection:Disconnect()
        self.PlayerAddedConnection = nil
    end

    if self.PlayerRemovingConnection then
        self.PlayerRemovingConnection:Disconnect()
        self.PlayerRemovingConnection = nil
    end
end

function BacktrackVisualState:SetEnabled(Value)
    Value = Value == true
    if self.Enabled == Value then return end

    self.Enabled = Value

    if self.Enabled then
        self:GetFolder()
        self:RebuildPlayerCache()
        InstallAntiAimRakNetHook()

        self.PlayerAddedConnection = Players.PlayerAdded:Connect(function(Player)
            BacktrackVisualState:AddPlayer(Player)
        end)

        self.PlayerRemovingConnection = Players.PlayerRemoving:Connect(function(Player)
            BacktrackVisualState:RemovePlayer(Player)
        end)

        self.Connection = RunService.RenderStepped:Connect(function(DeltaTime)
            Internal.Call(BacktrackVisualState.Step, BacktrackVisualState, DeltaTime)
        end)
    else
        self:DisconnectRuntime()

        for Player in pairs(self.Objects) do
            self:DestroyObject(Player)
        end

        table.clear(self.Records)
        table.clear(self.Players)
        self.PlayerSet = setmetatable({}, {__mode = "k"})
        self.LocalStableSnapshot = nil
        self.LocalReferenceState = nil
        self.Clock = 0
    end
end

function BacktrackVisualState:Destroy()
    self.Enabled = false
    self:DisconnectRuntime()

    for Player in pairs(self.Objects) do
        self:DestroyObject(Player)
    end

    table.clear(self.Records)
    table.clear(self.Players)
    self.PlayerSet = setmetatable({}, {__mode = "k"})
    self.LocalStableSnapshot = nil
    self.LocalReferenceState = nil

    if self.Folder then
        self.Folder:Destroy()
        self.Folder = nil
    end
end

