function PlushieState.GetRoot()
    local Character = LocalPlayer.Character
    if not Character then return nil end
    return Character:FindFirstChild("HumanoidRootPart")
end

function PlushieState.GetVisibleBounds(Model)
    if not Model or not Model:IsA("Model") then return Vector3.zero end

    local MinX, MinY, MinZ = math.huge, math.huge, math.huge local MaxX, MaxY, MaxZ = -math.huge, -math.huge, -math.huge local Found = false

    local function IncludePart(Part, AllowInvisible)
        if not Part or not Part:IsA("BasePart") then return end
        if not AllowInvisible and Part.Transparency >= 0.98 then return end
        if Part.Size.Magnitude <= 0.001 then return end

        local Half = Part.Size * 0.5

        for X = -1, 1, 2 do
            for Y = -1, 1, 2 do
                for Z = -1, 1, 2 do
                    local Point = Part.CFrame:PointToWorldSpace(Vector3.new( Half.X * X, Half.Y * Y, Half.Z * Z ))

                    MinX = math.min(MinX, Point.X)
                    MinY = math.min(MinY, Point.Y)
                    MinZ = math.min(MinZ, Point.Z)
                    MaxX = math.max(MaxX, Point.X)
                    MaxY = math.max(MaxY, Point.Y)
                    MaxZ = math.max(MaxZ, Point.Z)
                    Found = true
                end
            end
        end
    end

    local Parts = {}

    for _, Object in ipairs(Model:GetDescendants()) do
        if Object:IsA("BasePart") then
            Parts[#Parts + 1] = Object
            IncludePart(Object, false)
        end
    end

    if not Found then
        for Index = 1, #Parts do
            IncludePart(Parts[Index], true)
        end
    end

    if not Found then return Vector3.zero end

    return Vector3.new( math.max(MaxX - MinX, 0), math.max(MaxY - MinY, 0), math.max(MaxZ - MinZ, 0))
end

function PlushieState.PrepareModel(Model)
    if not Model or not Model:IsA("Model") then return false end

    local HasPart = false

    for _, Object in ipairs(Model:GetDescendants()) do
        if Object:IsA("Script") or Object:IsA("LocalScript") or Object:IsA("ModuleScript") then
            Object:Destroy()
        elseif Object:IsA("BasePart") then
            HasPart = true
            Object.Anchored = true
            Object.CanCollide = false
            Object.CanTouch = false
            Object.CanQuery = false
            Object.Massless = true
        end
    end

    return HasPart
end

function PlushieState.DestroyTemplate()
    if PlushieState.Template then
        PlushieState.Template:Destroy()
        PlushieState.Template = nil
    end

    PlushieState.AutoScale = 1
    PlushieState.OrientationCorrection = CFrame.new()
    PlushieState.OrientationSource = "Default"
end

function PlushieState.GetNormalVector(Face)
    if Face == Enum.NormalId.Front then return Vector3.new(0, 0, -1) end
    if Face == Enum.NormalId.Back then return Vector3.new(0, 0, 1) end
    if Face == Enum.NormalId.Right then return Vector3.new(1, 0, 0) end
    if Face == Enum.NormalId.Left then return Vector3.new(-1, 0, 0) end
    if Face == Enum.NormalId.Top then return Vector3.new(0, 1, 0) end
    if Face == Enum.NormalId.Bottom then return Vector3.new(0, -1, 0) end
    return Vector3.new(0, 0, -1)
end

function PlushieState.BuildOrientationCorrection(Model, FrontWorld, UpWorld, Source)
    if not Model or typeof(FrontWorld) ~= "Vector3" or FrontWorld.Magnitude <= 0.001 then return nil end

    UpWorld = typeof(UpWorld) == "Vector3" and UpWorld or Vector3.new(0, 1, 0)

    local Pivot = Model:GetPivot() local FrontLocal = Pivot:VectorToObjectSpace(FrontWorld).Unit local UpLocal = Pivot:VectorToObjectSpace(UpWorld)

    UpLocal -= FrontLocal * UpLocal:Dot(FrontLocal)

    if UpLocal.Magnitude <= 0.001 then
        local Reference = math.abs(FrontLocal.Y) < 0.92 and Vector3.new(0, 1, 0) or Vector3.new(1, 0, 0)
        UpLocal = Reference - FrontLocal * Reference:Dot(FrontLocal)
    end

    if UpLocal.Magnitude <= 0.001 then return nil end
    UpLocal = UpLocal.Unit

    local Basis = CFrame.lookAt(Vector3.zero, FrontLocal, UpLocal).Rotation
    PlushieState.OrientationSource = Source or "Detected"

    return Basis:Inverse()
end

function PlushieState.DetectSemanticOrientation(Model)
    if not Model then return nil end

    local Pivot = Model:GetPivot()
    local Root = Model:FindFirstChild("HumanoidRootPart", true) or Model:FindFirstChild("LowerTorso", true) or Model:FindFirstChild("Torso", true)
        or Model:FindFirstChild("UpperTorso", true)

    if Root and Root:IsA("BasePart") then return PlushieState.BuildOrientationCorrection( Model, Root.CFrame.LookVector, Root.CFrame.UpVector, "Rig") end

    local Head = Model:FindFirstChild("Head", true)

    if Head and Head:IsA("BasePart") then
        for _, Child in ipairs(Head:GetChildren()) do
            if Child:IsA("Decal") and string.find(string.lower(Child.Name), "face", 1, true) then
                local LocalFront = PlushieState.GetNormalVector(Child.Face) local WorldFront = Head.CFrame:VectorToWorldSpace(LocalFront)

                return PlushieState.BuildOrientationCorrection( Model, WorldFront, Head.CFrame.UpVector, "Face")
            end
        end
    end

    local FrontNames = { "FaceFrontAttachment", "BodyFrontAttachment", "FrontAttachment", "RootFrontAttachment" }

    for Index = 1, #FrontNames do
        local Attachment = Model:FindFirstChild(FrontNames[Index], true)

        if Attachment and Attachment:IsA("Attachment") then
            local Parent = Attachment.Parent

            if Parent and Parent:IsA("BasePart") then
                local Offset = Attachment.WorldPosition - Parent.Position local Front = Offset.Magnitude > 0.001 and Offset.Unit or Attachment.WorldCFrame.LookVector

                return PlushieState.BuildOrientationCorrection( Model, Front, Parent.CFrame.UpVector, "Attachment")
            end
        end
    end

    return nil
end

function PlushieState.DetectGeometryOrientation(Model)
    PlushieState.OrientationSource = "Preset"
    return CFrame.new()
end

function PlushieState.DetectOrientation(Model)
    if not Model then
        PlushieState.OrientationSource = "Published"
        return CFrame.new()
    end

    if PlushieState.AutoOrientation == true then
        local Semantic = PlushieState.DetectSemanticOrientation(Model)

        if Semantic then return Semantic end
    end

    PlushieState.OrientationSource = "Published"
    return CFrame.new()
end

function PlushieState.GetPresetProfile()
    local Profile = PlushieState.PresetProfiles and PlushieState.PresetProfiles[PlushieState.Preset]

    return type(Profile) == "table" and Profile or { Rotation = CFrame.new(), HeightBias = 0, Tilt = 0 }
end

function PlushieState.GetPresetOrientation()
    local Profile = PlushieState.GetPresetProfile()

    return typeof(Profile.Rotation) == "CFrame" and Profile.Rotation or CFrame.new()
end

function PlushieState.GetOrientationCorrection()
    local Automatic = typeof(PlushieState.OrientationCorrection) == "CFrame" and PlushieState.OrientationCorrection or CFrame.new()

    return Automatic * PlushieState.GetPresetOrientation()
end

function PlushieState.LoadTemplate()
    if PlushieState.Template and PlushieState.Template.Parent == nil then return true end

    if PlushieState.Loading then return false end
    PlushieState.Loading = true

    PlushieState.DestroyTemplate()

    local AssetId = PlushieState.Assets[PlushieState.Preset]
    if not AssetId then
        PlushieState.Loading = false
        return false
    end

    local Objects
    local Success = Internal.Call(function()
        Objects = game:GetObjects("rbxassetid://" .. tostring(AssetId))
    end)

    if not Success or type(Objects) ~= "table" or not Objects[1] then
        PlushieState.Loading = false
        return false
    end

    local Source = Objects[1] local Model

    if Source:IsA("Model") then
        Model = Source
    else
        Model = Instance.new("Model")
        Model.Name = "AtramentaPlushieTemplate"
        Source.Parent = Model
    end

    for Index = 2, #Objects do
        local Object = Objects[Index]

        if Object then
            if Object:IsA("BasePart") or Object:IsA("Model") or Object:IsA("Accessory") or Object:IsA("Folder") then
                Object.Parent = Model
            elseif Object.Parent == nil then
                Object:Destroy()
            end
        end
    end

    Model.Name = "AtramentaPlushieTemplate"
    Model.Parent = nil

    Model:PivotTo(CFrame.new())

    if not PlushieState.PrepareModel(Model) then
        Model:Destroy()
        PlushieState.Loading = false
        return false
    end

    local Bounds = PlushieState.GetVisibleBounds(Model) local MaximumDimension = math.max(Bounds.X, Bounds.Y, Bounds.Z)

    if MaximumDimension <= 0.001 then
        Model:Destroy()
        PlushieState.Loading = false
        return false
    end

    PlushieState.AutoScale = math.clamp( PlushieState.TargetDimension / MaximumDimension, 0.005, 30)

    PlushieState.OrientationCorrection = PlushieState.DetectOrientation(Model)
    PlushieState.Template = Model
    PlushieState.Loading = false
    return true
end

function PlushieState.DestroyPets()
    for Index = #PlushieState.Pets, 1, -1 do
        local Data = PlushieState.Pets[Index]

        if Data and Data.Model then Data.Model:Destroy() end

        PlushieState.Pets[Index] = nil
    end
end

function PlushieState.ApplyPetScale(Data)
    if not Data or not Data.Model or not Data.Model.Parent then return end

    local Scale = math.clamp( PlushieState.AutoScale * math.clamp(tonumber(PlushieState.Size) or 1, 0.35, 2.25), 0.002, 50)

    Internal.Call(function()
        Data.Model:ScaleTo(Scale)
    end)
end

function PlushieState.ApplyAppearanceToPet(Data)
    if not Data or not Data.Model then return end

    local Alpha = math.clamp(tonumber(PlushieState.Transparency) or 0, 0, 0.90)

    for Part, Original in pairs(Data.OriginalAppearance) do
        if Part and Part.Parent and type(Original) == "table" then
            local OriginalTransparency = tonumber(Original.Transparency) or 0

            Part.Transparency = 1 - (1 - OriginalTransparency) * (1 - Alpha)
            Part.CastShadow = PlushieState.CastShadow == true and Original.CastShadow ~= false
            Part.Anchored = true
            Part.CanCollide = false
            Part.CanTouch = false
            Part.CanQuery = false
            Part.Massless = true
        end
    end
end

function PlushieState.ApplyAppearance()
    for Index = 1, #PlushieState.Pets do
        PlushieState.ApplyAppearanceToPet(PlushieState.Pets[Index])
    end
end

function PlushieState.ApplyScale()
    for Index = 1, #PlushieState.Pets do
        local Data = PlushieState.Pets[Index]
        PlushieState.ApplyPetScale(Data)
    end
end

function PlushieState.GetHorizontalLook(Root)
    if not Root then return Vector3.new(0, 0, -1) end

    local Look = Root.CFrame.LookVector Look = Vector3.new(Look.X, 0, Look.Z)

    if Look.Magnitude <= 0.001 then return Vector3.new(0, 0, -1) end

    return Look.Unit
end

function PlushieState.GetFormationOffset(Index, Count, Look, Right)
    local CenterIndex = Index - (Count + 1) * 0.5 local Side = tonumber(PlushieState.SideOffset) or 2.6
    local Back = tonumber(PlushieState.BackOffset) or 3.4 local Spacing = math.max(tonumber(PlushieState.Spacing) or 1.65, 0)

    if PlushieState.Formation == "Trail" then
        local Zig = Index % 2 == 0 and 1 or -1
        Side += Zig * math.min(Spacing * 0.35, 0.9)
        Back += (Index - 1) * Spacing * 0.85
    elseif PlushieState.Formation == "Arc" then
        local Angle = CenterIndex * math.rad(24) local Radius = math.max(Back, 0.5) + math.abs(CenterIndex) * Spacing * 0.18
        Side += math.sin(Angle) * Radius
        Back = math.cos(Angle) * Radius
    else
        Side += CenterIndex * Spacing
    end

    return Right * Side - Look * Back
end

function PlushieState.GetFacingDirection(Root, TargetPosition, FallbackLook)
    local Mode = tostring(PlushieState.Facing or "Forward") local Direction = FallbackLook

    if Mode == "Player" then
        Direction = Root.Position - TargetPosition
        Direction = Vector3.new(Direction.X, 0, Direction.Z)
    elseif Mode == "Camera" then
        local CameraObject = workspace.CurrentCamera

        if CameraObject then local CameraLook = CameraObject.CFrame.LookVector Direction = Vector3.new(CameraLook.X, 0, CameraLook.Z) end
    end

    if Direction.Magnitude <= 0.001 then return FallbackLook end

    return Direction.Unit
end

function PlushieState.GetFinalOrientationCorrection()
    local Base = PlushieState.GetOrientationCorrection()

    if math.abs(tonumber(PlushieState.Pitch) or 0) <= 0.001 and math.abs(tonumber(PlushieState.Yaw) or 0) <= 0.001
        and math.abs(tonumber(PlushieState.Roll) or 0) <= 0.001
    then
        return Base
    end

    return Base * CFrame.Angles( math.rad(tonumber(PlushieState.Pitch) or 0), math.rad(tonumber(PlushieState.Yaw) or 0),
        math.rad(tonumber(PlushieState.Roll) or 0))
end

function PlushieState.GetTargetTransform(Index, Count, Root, Time)
    local Look = PlushieState.GetHorizontalLook(Root) local Right = Vector3.new(-Look.Z, 0, Look.X)
    local FormationOffset = PlushieState.GetFormationOffset(Index, Count, Look, Right)

    local Phase = Time * math.pi * 2 * math.max(tonumber(PlushieState.FloatSpeed) or 0.38, 0) + (Index - 1) * 0.78

    local Float = math.sin(Phase) * math.max(tonumber(PlushieState.FloatHeight) or 0.28, 0)

    local Profile = PlushieState.GetPresetProfile() local HeightBias = tonumber(Profile.HeightBias) or 0

    local Position = Root.Position + FormationOffset + Vector3.new( 0, (tonumber(PlushieState.HeightOffset) or 1.7) + HeightBias + Float, 0)

    local Facing = PlushieState.GetFacingDirection(Root, Position, Look)
    local Rotation = CFrame.lookAt( Vector3.zero, Facing, Vector3.new(0, 1, 0) ).Rotation * PlushieState.GetFinalOrientationCorrection()

    local Tilt = math.rad(tonumber(Profile.Tilt) or 0)

    return Position, Rotation, Tilt
end

function PlushieState.EnsureRenderConnection()
    if PlushieState.RenderConnection then return end

    PlushieState.RenderConnection = RunService.RenderStepped:Connect(function(DeltaTime)
        Internal.Call(function()
        if not PlushieState.Enabled then return end

        local Root = PlushieState.GetRoot() if not Root then return end

        DeltaTime = math.min(DeltaTime, 1 / 20)
        PlushieState.Time += DeltaTime

        local Count = #PlushieState.Pets local Alive = 0

        for Index = 1, Count do
            local Data = PlushieState.Pets[Index]

            if Data and Data.Model and Data.Model.Parent then
                Alive += 1

                local TargetPosition, TargetRotation, Tilt = PlushieState.GetTargetTransform( Index, Count, Root, PlushieState.Time)

                local PositionAlpha = 1 - math.exp( -math.max(tonumber(PlushieState.FollowSpeed) or 3.2, 0.05) * DeltaTime)

                local RotationAlpha = 1 - math.exp( -math.max(tonumber(PlushieState.RotationSpeed) or 3, 0.05) * DeltaTime)

                Data.CurrentPosition = Data.CurrentPosition:Lerp(TargetPosition, PositionAlpha)
                Data.CurrentRotation = Data.CurrentRotation:Lerp(TargetRotation, RotationAlpha)

                Data.Model:PivotTo( CFrame.new(Data.CurrentPosition) * Data.CurrentRotation * CFrame.Angles(Tilt, 0, 0))
            end
        end

        if Count > 0 and Alive == 0 and not PlushieState.RebuildQueued then
            PlushieState.RebuildQueued = true

            task.defer(function()
                PlushieState.RebuildQueued = false

                if PlushieState.Enabled then PlushieState.RebuildPets() end
            end)
        end
        end)
    end)
end

function PlushieState.StopRenderConnection()
    if PlushieState.RenderConnection then
        PlushieState.RenderConnection:Disconnect()
        PlushieState.RenderConnection = nil
    end
end

function PlushieState.RebuildPets()
    PlushieState.DestroyPets()

    if not PlushieState.Enabled then return false end
    if not PlushieState.LoadTemplate() then return false end

    local Root = PlushieState.GetRoot()
    if not Root then return false end

    local Count = math.clamp(math.floor(tonumber(PlushieState.Amount) or 1), 1, 5) local Look = PlushieState.GetHorizontalLook(Root)

    PlushieState.Time = 0

    for Index = 1, Count do
        local Model = PlushieState.Template:Clone()
        Model.Name = "AtramentaPlushie_" .. PlushieState.Preset .. "_" .. tostring(Index)

        local OriginalAppearance = {}

        for _, Object in ipairs(Model:GetDescendants()) do
            if Object:IsA("BasePart") then
                OriginalAppearance[Object] = { Transparency = Object.Transparency, CastShadow = Object.CastShadow }

                Object.Anchored = true
                Object.CanCollide = false
                Object.CanTouch = false
                Object.CanQuery = false
                Object.Massless = true
            end
        end

        Model.Parent = workspace

        local Data = { Model = Model, OriginalAppearance = OriginalAppearance, CurrentPosition = Root.Position,
            CurrentRotation = CFrame.lookAt(Vector3.zero, Look, Vector3.new(0, 1, 0)).Rotation * PlushieState.GetFinalOrientationCorrection() }

        PlushieState.Pets[#PlushieState.Pets + 1] = Data

        PlushieState.ApplyPetScale(Data)
        PlushieState.ApplyAppearanceToPet(Data)

        local Position, Rotation, Tilt = PlushieState.GetTargetTransform( Index, Count, Root, 0)

        Data.CurrentPosition = Position
        Data.CurrentRotation = Rotation

        Model:PivotTo( CFrame.new(Position) * Rotation * CFrame.Angles(Tilt, 0, 0))
    end

    PlushieState.EnsureRenderConnection()
    return true
end

function PlushieState.SetEnabled(Value)
    PlushieState.Enabled = Value == true

    if PlushieState.Enabled then
        PlushieState.RebuildPets()
        PlushieState.EnsureRenderConnection()
    else
        PlushieState.DestroyPets()
        PlushieState.StopRenderConnection()
    end
end

function PlushieState.SetPreset(Value)
    if not PlushieState.Assets[Value] then return end
    if PlushieState.Preset == Value and PlushieState.Template then return end

    PlushieState.Preset = Value
    PlushieState.Pitch = 0
    PlushieState.Yaw = 0
    PlushieState.Roll = 0
    PlushieState.OrientationCorrection = CFrame.new()
    PlushieState.OrientationSource = "Published"
    PlushieState.DestroyPets()
    PlushieState.DestroyTemplate()

    if PlushieState.Enabled then PlushieState.RebuildPets() end
end

function PlushieState.SetManualOrientation(Pitch, Yaw, Roll)
    PlushieState.Pitch = math.clamp(tonumber(Pitch) or 0, -180, 180)
    PlushieState.Yaw = math.clamp(tonumber(Yaw) or 0, -180, 180)
    PlushieState.Roll = math.clamp(tonumber(Roll) or 0, -180, 180)
end

function PlushieState.BindCharacterEvents()
    if PlushieState.CharacterAddedConnection then PlushieState.CharacterAddedConnection:Disconnect() end

    if PlushieState.CharacterRemovingConnection then PlushieState.CharacterRemovingConnection:Disconnect() end

    PlushieState.CharacterRemovingConnection = LocalPlayer.CharacterRemoving:Connect(function()
        if PlushieState.Enabled then PlushieState.DestroyPets() end
    end)

    PlushieState.CharacterAddedConnection = LocalPlayer.CharacterAdded:Connect(function()
        if not PlushieState.Enabled or not PlushieState.AutoRespawn then return end

        task.delay(0.65, function()
            if PlushieState.Enabled and PlushieState.AutoRespawn then PlushieState.RebuildPets() end
        end)
    end)
end

function PlushieState.Destroy()
    PlushieState.Enabled = false
    PlushieState.DestroyPets()
    PlushieState.StopRenderConnection()

    if PlushieState.CharacterAddedConnection then
        PlushieState.CharacterAddedConnection:Disconnect()
        PlushieState.CharacterAddedConnection = nil
    end

    if PlushieState.CharacterRemovingConnection then
        PlushieState.CharacterRemovingConnection:Disconnect()
        PlushieState.CharacterRemovingConnection = nil
    end

    PlushieState.DestroyTemplate()
end

