function Internal.RageBotAddTargetPlayer(Player)
    if not Player or Player == LocalPlayer or Ragebot.Runtime.TargetPlayerSet[Player] then return end
    Ragebot.Runtime.TargetPlayerSet[Player] = true
    Ragebot.Runtime.TargetPlayers[#Ragebot.Runtime.TargetPlayers + 1] = Player
end

function Internal.RageBotRemoveTargetPlayer(Player)
    if not Player or not Ragebot.Runtime.TargetPlayerSet[Player] then return end
    Ragebot.Runtime.TargetPlayerSet[Player] = nil

    local Wallbang = Ragebot.Runtime and Ragebot.Runtime.Wallbang
    if type(Wallbang) == "table" then
        if Wallbang.ValidPair and Wallbang.ValidPair.Target == Player then Wallbang.ValidPair = nil end
        if Wallbang.LastPair and Wallbang.LastPair.Target == Player then Wallbang.LastPair = nil end
    end

    for Index = #Ragebot.Runtime.TargetPlayers, 1, -1 do
        if Ragebot.Runtime.TargetPlayers[Index] == Player then
            local LastIndex = #Ragebot.Runtime.TargetPlayers
            Ragebot.Runtime.TargetPlayers[Index] = Ragebot.Runtime.TargetPlayers[LastIndex]
            Ragebot.Runtime.TargetPlayers[LastIndex] = nil
            break
        end
    end
end

