function ClearCombatTargets()
    Ragebot.LockedTarget = nil
    Ragebot.CurrentTarget = nil

    if Ragebot.Runtime then
        Ragebot.Runtime.Target = nil
        Ragebot.Runtime.PendingShot = nil

        local Wallbang = Ragebot.Runtime.Wallbang
        if type(Wallbang) == "table" then
            Wallbang.ValidPair = nil
            Wallbang.LastPair = nil
            end
    end

    if Configuration and Configuration.AimBot then
        Configuration.AimBot.AimbotLockedTarget = nil
        Configuration.AimBot.SilentAimLockedTarget = nil
        Configuration.AimBot.CurrentTarget = nil
        Configuration.AimBot.CachedScanTarget = nil
        Configuration.AimBot.LastTargetScan = 0
        Configuration.AimBot.PositionCacheCharacter = nil
        Configuration.AimBot.PositionCacheValue = nil
    end

    if SilentAimController then
        SilentAimController.CachedPart = nil
        SilentAimController.CachedPlayer = nil
        SilentAimController.CachedCharacter = nil
        SilentAimController.CachedAimPosition = nil
    end
end

function AtramentaSetPlayerStatusRuntime(Player, Status)
    if not Player or Player == LocalPlayer then return end

    WhitelistTable[Player] = nil
    PriorityTable[Player] = nil
    EnemyTable[Player] = nil

    Status = tostring(Status or "None")

    if Status == "Whitelist" then
        WhitelistTable[Player] = true
    elseif Status == "Priority" then
        PriorityTable[Player] = true
    elseif Status == "Enemy" then
        EnemyTable[Player] = true
    end

    ClearCombatTargets()

    local PlayerState = VisualState and VisualState.Player
    local Objects = PlayerState and PlayerState.Objects
    local ChangedData = Objects and Objects[Player]

    if ChangedData then
        ChangedData.NextEspUpdate = 0
        ChangedData.NextChamsUpdate = 0
        ChangedData.VisualRenderPose = nil
        ChangedData.VisualRenderPoseTime = 0
    end

    if PlayerState and type(PlayerState.List) == "table" then
        for Index = 1, #PlayerState.List do
            local Data = PlayerState.List[Index]

            if Data then
                Data.NextEspUpdate = 0
                Data.NextChamsUpdate = 0
            end
        end
    end

    task.defer(function()
        if VisualState and VisualState.Player and VisualState.Player.Chams.Enabled
            and type(UpdatePlayerChams) == "function"
        then
            Internal.Call(UpdatePlayerChams, true)
        end
    end)
end

function AtramentaHasEnemyTargets()
    local Found = false

    for Player in pairs(EnemyTable) do
        if Player and Player.Parent == Players and Player ~= LocalPlayer then
            Found = true
        else
            EnemyTable[Player] = nil
        end
    end

    return Found
end

function IsCombatTargetAllowed(Player)
    if not Player or Player == LocalPlayer or Player.Parent ~= Players or WhitelistTable[Player] == true then return false end

    if AtramentaHasEnemyTargets() then return EnemyTable[Player] == true end

    return true
end

function GetCombatTargetPriority(Player)
    if not IsCombatTargetAllowed(Player) then return -1 end

    if EnemyTable[Player] == true then return 3 end

    if PriorityTable[Player] == true then return 2 end

    return 1
end

