            ) then
        ClearCombatTargets()
    end
end))

ResolverState = { History = setmetatable({}, { __mode = "k" }), PoseHistory = setmetatable({}, { __mode = "k" }),
    SkeletonCache = setmetatable({}, { __mode = "k" }), SafePartCache = setmetatable({}, { __mode = "k" }), TargetCache = setmetatable({}, { __mode = "k" }),
    CharacterResolveCache = setmetatable({}, { __mode = "k" }), WorldCharacterCache = { NextRefresh = 0, WorldCharacters = nil, NormalCharacters = nil },

    MovementUpdateInterval = 1 / 45, MinimumDelta = 1 / 240, MaximumDelta = 0.28, TeleportDistance = 32, MaximumAcceleration = 170,
    PartOffsetUpdateInterval = 1 / 30, SampleLimit = 9, MinimumSamples = 4, MaximumJitter = 46, MaximumPrediction = 0.46, MaximumExtrapolationTicks = 8,
    MinimumExtrapolationTicks = 1, PredictionTickRateMinimum = 20, PredictionTickRateMaximum = 128, PoseDeviation = 1.35 }

function ResolverIsFiniteNumber(Value)
    return type(Value) == "number" and Value == Value and Value > -math.huge and Value < math.huge
end

function ResolverIsFiniteVector(Value)
    return typeof(Value) == "Vector3" and ResolverIsFiniteNumber(Value.X) and ResolverIsFiniteNumber(Value.Y) and ResolverIsFiniteNumber(Value.Z)
end

function ResolverClampVector(Value, MaximumMagnitude)
    if not ResolverIsFiniteVector(Value) then return Vector3.zero end

    MaximumMagnitude = math.max( tonumber(MaximumMagnitude) or 190, 1)

    local Magnitude = Value.Magnitude

    if Magnitude > MaximumMagnitude and Magnitude > 0 then return Value.Unit * MaximumMagnitude end

    return Value
end

function ResolverMedian(Values)
    local Count = #Values
    if Count == 0 then return 0 end
    table.sort(Values)
    local Middle = math.floor((Count + 1) * 0.5)
    if Count % 2 == 1 then return Values[Middle] end
    return (Values[Middle] + Values[Middle + 1]) * 0.5
end

function ResolverGetRobustVelocity(Samples, MaximumSpeed)
    local Count = #Samples
    if Count == 0 then return Vector3.zero, 0 end

    local X, Y, Z = {}, {}, {}
    for Index = 1, Count do
        local Sample = Samples[Index]
        X[Index], Y[Index], Z[Index] = Sample.X, Sample.Y, Sample.Z
    end

    local Median = Vector3.new(ResolverMedian(X), ResolverMedian(Y), ResolverMedian(Z)) local Sum = Vector3.zero local WeightSum = 0 local Jitter = 0

    for Index = 1, Count do
        local Sample = Samples[Index] local Distance = (Sample - Median).Magnitude
        local Recency = Index / Count local Weight = (0.35 + Recency * 0.65) / (1 + Distance * 0.055)
        Sum += Sample * Weight
        WeightSum += Weight
        Jitter += Distance
    end

    local Velocity = WeightSum > 0 and Sum / WeightSum or Median
    return ResolverClampVector(Velocity, MaximumSpeed), Jitter / Count
end

function ResolverGetMotionQuality(Samples, RobustVelocity, MaximumSpeed)
    local Count = type(Samples) == "table" and #Samples or 0
    if Count == 0 then return 0, 0, 1 end

    local MeanSpeed = 0 local SpeedVariance = 0 local AlignmentSum = 0 local AlignmentCount = 0

    for Index = 1, Count do
        MeanSpeed += Samples[Index].Magnitude
    end

    MeanSpeed /= Count

    for Index = 1, Count do
        local Sample = Samples[Index] local SpeedDifference = Sample.Magnitude - MeanSpeed
        SpeedVariance += SpeedDifference * SpeedDifference

        if Sample.Magnitude > 2 and RobustVelocity.Magnitude > 2 then
            AlignmentSum += math.clamp(Sample.Unit:Dot(RobustVelocity.Unit), -1, 1)
            AlignmentCount += 1
        end
    end

    SpeedVariance = math.sqrt(SpeedVariance / Count)
    local DirectionConsistency = AlignmentCount > 0 and math.clamp((AlignmentSum / AlignmentCount + 1) * 0.5, 0, 1) or 1
    local VariancePenalty = math.clamp(SpeedVariance / math.max(MaximumSpeed * 0.18, 8), 0, 1) local Quality = math.clamp(DirectionConsistency * (1 - VariancePenalty * 0.72), 0, 1)

    return Quality, SpeedVariance, DirectionConsistency
end

function ResolverGetPingSeconds()
    local Ping = 0

    Internal.Call( function()
            local Value = tonumber( LocalPlayer:GetNetworkPing())

            if Value and Value >= 0 then Ping = math.max( Ping, Value) end
        end)

    return math.clamp( Ping, 0, 1.5)
end

function ResolverGetRoot(Character)
    if not Character then return nil end

    return Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("LowerTorso") or Character:FindFirstChild("Torso")
        or Character:FindFirstChild("UpperTorso")
end

function ResolverResetData(Data, Character, Root, CurrentTime)
    Data.Character = Character
    Data.Root = Root
    Data.LastPosition = Root and Root.Position or Vector3.new(0, 0, 0)
    Data.LastTime = CurrentTime or os.clock()
    Data.ObservedVelocity = Vector3.zero
    Data.SmoothedVelocity = Vector3.zero
    Data.ResolvedVelocity = Vector3.zero
    Data.Acceleration = Vector3.zero
    Data.LastAcceleration = Vector3.zero
    Data.Jerk = 0
    Data.VelocityVariance = 0
    Data.DirectionConsistency = 1
    Data.MotionConfidence = 0
    Data.LastReportedVelocity = Root and (Root.AssemblyLinearVelocity or Root.Velocity) or Vector3.new(0, 0, 0)
    Data.DesyncScore = 0
    Data.IsDesynced = false
    Data.Confidence = 0
    Data.Jitter = 0
    Data.DirectionChanges = 0
    Data.LastObservedVelocity = Vector3.zero
    Data.Samples = {}
    return Data
end

function ResolverGetData(Player, Character)
    if not Player then return nil end

    local Data = ResolverState.History[Player]

    if type(Data) ~= "table" then
        Data = {}
        ResolverState.History[Player] = Data
    end

    local Root = ResolverGetRoot(Character)

    if Data.Character ~= Character or Data.Root ~= Root or not Data.LastTime then ResolverResetData( Data, Character, Root, os.clock()) end

    return Data
end

function ResolverGetDirectedVelocity(Character, Root, MaximumSpeed)
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    if not Humanoid then return Vector3.zero end

    local MoveDirection = Humanoid.MoveDirection local WalkSpeed = math.max( tonumber(Humanoid.WalkSpeed) or 16, 0)
    local ReportedY = Root and ( Root.AssemblyLinearVelocity or Root.Velocity ).Y or 0

    return ResolverClampVector( Vector3.new( MoveDirection.X * WalkSpeed, ReportedY, MoveDirection.Z * WalkSpeed ), MaximumSpeed)
end

function ResolverObservePlayer(Player, Character, Settings)
    if not Player or not Character then return nil end

    local Root = ResolverGetRoot(Character)
    if not Root or not Root:IsA("BasePart") then return nil end

    local Data = ResolverGetData(Player, Character) local CurrentTime = os.clock()
    local DeltaTime = CurrentTime - (Data.LastTime or CurrentTime) local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    local RawReported = Root.AssemblyLinearVelocity or Root.Velocity or Vector3.new(0, 0, 0) local WalkSpeed = Humanoid and tonumber(Humanoid.WalkSpeed) or 16
    local PingSeconds = ResolverGetPingSeconds() local MaximumSpeed = math.clamp(math.max(84, WalkSpeed * 6.5, RawReported.Magnitude * 1.45), 84, 230)
    local Reported = ResolverClampVector(RawReported, MaximumSpeed)

    Data.LastReportedVelocity = Reported
    if DeltaTime < ResolverState.MovementUpdateInterval then return Data end

    if DeltaTime > ResolverState.MaximumDelta then return ResolverResetData(Data, Character, Root, CurrentTime) end

    local CurrentPosition = Root.Position local PositionDelta = CurrentPosition - (Data.LastPosition or CurrentPosition)
    local RawObserved = PositionDelta / math.max(DeltaTime, ResolverState.MinimumDelta)

    if PositionDelta.Magnitude > ResolverState.TeleportDistance or RawObserved.Magnitude > MaximumSpeed * 2.75 then
        ResolverResetData(Data, Character, Root, CurrentTime)
        Data.LastReportedVelocity = Reported
        Data.ResolvedVelocity = Reported
        Data.RelocatedAt = CurrentTime
        Data.RelocatedPosition = CurrentPosition
        return Data
    end

    local Observed = ResolverClampVector(RawObserved, MaximumSpeed)
    local Samples = Data.Samples or {}
    Samples[#Samples + 1] = Observed
    while #Samples > ResolverState.SampleLimit do table.remove(Samples, 1) end
    Data.Samples = Samples

    local RobustObserved, Jitter = ResolverGetRobustVelocity(Samples, MaximumSpeed) local PreviousSmoothed = Data.SmoothedVelocity or RobustObserved
    local SmoothAlpha = math.clamp(1 - math.exp(-14 * DeltaTime), 0.18, 0.82) local Smoothed = PreviousSmoothed:Lerp(RobustObserved, SmoothAlpha)
    local Directed = ResolverGetDirectedVelocity(Character, Root, MaximumSpeed) local Difference = (Smoothed - Reported).Magnitude local Alignment = 1

    if Smoothed.Magnitude > 1 and Reported.Magnitude > 1 then Alignment = Smoothed.Unit:Dot(Reported.Unit) end

    local PreviousObserved = Data.LastObservedVelocity or Vector3.new(0, 0, 0)
    if PreviousObserved.Magnitude > 5 and Observed.Magnitude > 5 and PreviousObserved.Unit:Dot(Observed.Unit) < -0.15 then
        Data.DirectionChanges = math.min((Data.DirectionChanges or 0) + 1, 8)
    else
        Data.DirectionChanges = math.max((Data.DirectionChanges or 0) - DeltaTime * 2.5, 0)
    end

    local Threshold = math.clamp(10 + PingSeconds * 70 + Jitter * 0.16, 10, 34) local ObservedMoving = Smoothed.Magnitude > 2.5
    local ReportedMoving = Reported.Magnitude > 2.5 local Suspicious = Difference > Threshold or Alignment < -0.12 or (ObservedMoving and not ReportedMoving)
        or (ReportedMoving and Smoothed.Magnitude < 0.75) or (Data.DirectionChanges or 0) >= 2

    local TargetScore = Suspicious and 1 or 0 local ScoreAlpha = math.clamp(DeltaTime * 7.5, 0.12, 0.48)
    Data.DesyncScore = (Data.DesyncScore or 0) + (TargetScore - (Data.DesyncScore or 0)) * ScoreAlpha
    Data.IsDesynced = Data.DesyncScore >= 0.38
    Data.Jitter = Jitter

    local SampleConfidence = math.clamp(#Samples / ResolverState.SampleLimit, 0, 1) local JitterPenalty = math.clamp(Jitter / math.max(ResolverState.MaximumJitter, 1), 0, 0.85)
    local MotionQuality, VelocityVariance, DirectionConsistency = ResolverGetMotionQuality(Samples, RobustObserved, MaximumSpeed)
    local DirectionPenalty = math.clamp((tonumber(Data.DirectionChanges) or 0) / 4, 0, 0.72) local ReportAgreement = 1 - math.clamp(Difference / math.max(Threshold * 1.8, 1), 0, 0.82)

    Data.VelocityVariance = VelocityVariance
    Data.DirectionConsistency = DirectionConsistency
    Data.MotionConfidence = math.clamp(
        SampleConfidence * (1 - JitterPenalty) * (1 - DirectionPenalty) * (0.42 + MotionQuality * 0.38 + ReportAgreement * 0.20),
        0, 1
    )
    Data.Confidence = Data.MotionConfidence

    local Resolved = Reported
    if #Samples >= ResolverState.MinimumSamples then
        if Data.IsDesynced then
            local DirectedWeight = Directed.Magnitude > 1 and 0.12 or 0
            Resolved = Smoothed:Lerp(Directed, DirectedWeight)
        else
            local Blend = math.clamp(0.22 + Data.Confidence * 0.42, 0.22, 0.64)
            Resolved = Reported:Lerp(Smoothed, Blend)
        end
    elseif Directed.Magnitude > 1 and Reported.Magnitude < 1 then
        Resolved = Directed
    end

    if Humanoid and Humanoid.FloorMaterial ~= Enum.Material.Air then Resolved = Vector3.new(Resolved.X, math.abs(Resolved.Y) < 10 and 0 or Resolved.Y, Resolved.Z) end

    Resolved = ResolverClampVector(Resolved, MaximumSpeed)
    local PreviousResolved = Data.ResolvedVelocity or Resolved local ResolveAlpha = Data.IsDesynced and 0.76 or 0.54
    Resolved = PreviousResolved:Lerp(Resolved, ResolveAlpha)

    local RawAcceleration = (Resolved - PreviousResolved) / math.max(DeltaTime, ResolverState.MinimumDelta) local MaximumAcceleration = math.clamp(
        ResolverState.MaximumAcceleration * (0.48 + (tonumber(Data.MotionConfidence) or 0) * 0.52),
        64, ResolverState.MaximumAcceleration
    )
    local Acceleration = ResolverClampVector(RawAcceleration, MaximumAcceleration) local PreviousAcceleration = Data.Acceleration or Vector3.zero
    local RawJerk = (Acceleration - PreviousAcceleration).Magnitude / math.max(DeltaTime, ResolverState.MinimumDelta)
    local Jerk = (tonumber(Data.Jerk) or RawJerk) + (RawJerk - (tonumber(Data.Jerk) or RawJerk)) * math.clamp(DeltaTime * 6, 0.08, 0.35)
    local JerkPenalty = math.clamp(Jerk / 1800, 0, 0.78) local AccelerationAlpha = math.clamp(0.10 + (tonumber(Data.MotionConfidence) or 0) * 0.22, 0.10, 0.32)

    Data.MotionConfidence = math.clamp((tonumber(Data.MotionConfidence) or 0) * (1 - JerkPenalty * 0.45), 0, 1)
    Data.Confidence = Data.MotionConfidence
    Data.ObservedVelocity = Observed
    Data.SmoothedVelocity = Smoothed
    Data.ResolvedVelocity = Resolved
    Data.LastAcceleration = PreviousAcceleration
    Data.Acceleration = PreviousAcceleration:Lerp(Acceleration, AccelerationAlpha)
    Data.Jerk = Jerk
    Data.LastObservedVelocity = Observed
    Data.LastPosition = CurrentPosition
    Data.LastTime = CurrentTime
    return Data
end

function ResolverGetMovementVelocity(Player, Character, Settings)
    local Root = ResolverGetRoot(Character)

    if not Root then return Vector3.zero, nil end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid") local RawReported = Root.AssemblyLinearVelocity or Root.Velocity or Vector3.new(0, 0, 0)
    local WalkSpeed = Humanoid and tonumber(Humanoid.WalkSpeed) or 16 local MaximumSpeed = math.clamp(math.max(96, WalkSpeed * 7.5, RawReported.Magnitude * 1.75), 96, 260)
    local Reported = ResolverClampVector(RawReported, MaximumSpeed)

    if not Player then return Reported, nil end

    local Data = ResolverObservePlayer( Player, Character, Settings)

    if not Data then return Reported, nil end

    return ResolverClampVector( Data.ResolvedVelocity or Reported, MaximumSpeed ), Data
end

function ResolverGetFallbackPartOffset(Character, PartName)
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    local IsR6 = Humanoid and Humanoid.RigType == Enum.HumanoidRigType.R6

    if PartName == "Head" then
        return Vector3.new( 0, IsR6 and 1.5 or 1.75, 0)
    elseif PartName == "UpperTorso" then
        return Vector3.new(0, 0.75, 0)
    elseif PartName == "LowerTorso" then
        return Vector3.new(0, -0.15, 0)
    elseif PartName == "Torso" then
        return Vector3.new(0, 0.45, 0)
    end

    return Vector3.zero
end

function ResolverGetSafePartPosition(Character, TargetPart, UseStable)
    if not Character or not TargetPart or not TargetPart:IsA("BasePart") then return nil end

    local Root = ResolverGetRoot(Character)
    if not Root or not Root:IsA("BasePart") then return TargetPart.Position end

    local RawPosition = TargetPart.Position local PartName = TargetPart.Name local RawOffset = RawPosition - Root.Position local Size = TargetPart.Size

    local IsHead = PartName == "Head" local IsTorso = string.find(string.lower(PartName), "torso", 1, true) ~= nil local MaximumOffset = IsHead and 5.25 or IsTorso and 5.75 or 8.5

    local SizeValid = ResolverIsFiniteVector(Size) and Size.X > 0.05 and Size.Y > 0.05 and Size.Z > 0.05 and Size.Magnitude < 18

    local OffsetValid = ResolverIsFiniteVector(RawOffset) and RawOffset.Magnitude <= MaximumOffset

    if IsHead then OffsetValid = OffsetValid and RawOffset.Y >= 0.45 and RawOffset.Y <= 4.60 and math.abs(RawOffset.X) <= 2.25 and math.abs(RawOffset.Z) <= 2.25 end

    local Cache = ResolverState.SafePartCache[TargetPart]
    if type(Cache) ~= "table" or Cache.Character ~= Character then
        Cache = { Character = Character, Offset = nil, LastUpdate = 0, LastRawPosition = RawPosition, BadPoseFrames = 0 }
        ResolverState.SafePartCache[TargetPart] = Cache
    end

    local CurrentTime = os.clock() local PreviousRaw = Cache.LastRawPosition
    local SuddenPose = ResolverIsFiniteVector(PreviousRaw) and (RawPosition - PreviousRaw).Magnitude > 3.25

    Cache.LastRawPosition = RawPosition

    if not SizeValid or not OffsetValid or SuddenPose then
        Cache.BadPoseFrames = math.min((tonumber(Cache.BadPoseFrames) or 0) + 1, 12)
    else
        Cache.BadPoseFrames = math.max((tonumber(Cache.BadPoseFrames) or 0) - 1, 0)
    end

    if SizeValid and OffsetValid and not SuddenPose and CurrentTime - (tonumber(Cache.LastUpdate) or 0) >= ResolverState.PartOffsetUpdateInterval then
        if ResolverIsFiniteVector(Cache.Offset) then
            local Deviation = (RawOffset - Cache.Offset).Magnitude
            if Deviation <= ResolverState.PoseDeviation * 1.35 then Cache.Offset = Cache.Offset:Lerp(RawOffset, 0.16) end
        else
            Cache.Offset = RawOffset
        end
        Cache.LastUpdate = CurrentTime
    end

    local StableOffset = ResolverIsFiniteVector(Cache.Offset) and Cache.Offset or ResolverGetFallbackPartOffset(Character, PartName)

    if IsHead then
        StableOffset = Vector3.new( math.clamp(StableOffset.X, -0.30, 0.30), math.clamp(StableOffset.Y, 1.10, 3.25),
            math.clamp(StableOffset.Z, -0.30, 0.30))
    elseif IsTorso then
        StableOffset = Vector3.new( math.clamp(StableOffset.X, -0.45, 0.45), math.clamp(StableOffset.Y, -0.50, 1.60),
            math.clamp(StableOffset.Z, -0.45, 0.45))
    end

    local ForceStable = UseStable == true or (tonumber(Cache.BadPoseFrames) or 0) >= 1 or not SizeValid or not OffsetValid

    if ForceStable then return Root.Position + StableOffset end

    return RawPosition
end

function ResolverGetAdaptiveExtrapolation(Data, Settings)
    Settings = Settings or {}

    local TickRate = math.clamp( tonumber(Settings.ServerTickRate) or 60, ResolverState. PredictionTickRateMinimum or 20, ResolverState.
                PredictionTickRateMaximum or 128)

    local TickLength = 1 / TickRate

    local MaximumTicks = math.clamp( math.floor( tonumber( Settings. MaxExtrapolationTicks ) or ResolverState. MaximumExtrapolationTicks or 8 ), 1, 8)

    local PingSeconds = ResolverGetPingSeconds()

    local SnapshotAge = Data and math.clamp( os.clock() - ( tonumber(Data.LastTime) or os.clock() ), 0, 0.12 ) or 0

    local OneWayLatency = PingSeconds * 0.5

    local ProcessingLead = TickLength

    local RequiredTime = OneWayLatency + SnapshotAge * 0.65 + ProcessingLead

    local Ticks = math.ceil( RequiredTime / TickLength)

    Ticks = math.clamp( Ticks, ResolverState. MinimumExtrapolationTicks or 1, MaximumTicks)

    if Data then
        local Jitter = tonumber(Data.Jitter) or 0

        local DirectionChanges = tonumber(Data.DirectionChanges) or 0

        if DirectionChanges >= 2 or Jitter
                >= ResolverState. MaximumJitter * 0.85 then
            Ticks = math.max( 1, math.floor( Ticks * 0.55 ))
        elseif Data.IsDesynced then
            Ticks = math.max( 1, math.floor( Ticks * 0.78 ))
        end
    end

    return Ticks, Ticks * TickLength, PingSeconds, TickLength, SnapshotAge
end

function ResolveCombatPosition(Player, Character, TargetPart, PredictionTime, Settings, Context)
    if not Character or not TargetPart or not TargetPart:IsA("BasePart") then return nil, nil, 0, 0 end

    Settings = Settings or {}
    Context = type(Context) == "table" and Context or {}

    local BaseTime = math.clamp(tonumber(PredictionTime) or 0, 0, 0.32) local Root = Context.Root or ResolverGetRoot(Character)
    local Humanoid = Context.Humanoid or Character:FindFirstChildOfClass("Humanoid")
    local RawVelocity = Root and (Root.AssemblyLinearVelocity or Root.Velocity or Vector3.zero) or Vector3.zero
    local WalkSpeed = Humanoid and tonumber(Humanoid.WalkSpeed) or 16 local MaximumSpeed = math.clamp(math.max(84, WalkSpeed * 6.5, RawVelocity.Magnitude * 1.45), 84, 230)
    local ReportedVelocity = ResolverClampVector(RawVelocity, MaximumSpeed) local RawPosition = TargetPart.Position
    local ResolvedVelocity = Context.ResolvedVelocity or ReportedVelocity local Data = Context.Data

    if not Data and Player and Settings.Resolver ~= false then ResolvedVelocity, Data = ResolverGetMovementVelocity(Player, Character, Settings) end

    local ExtrapolationTicks, TickLead, PingSeconds, TickLength, SnapshotAge = ResolverGetAdaptiveExtrapolation(Data, Settings)

    if Settings.AdaptiveExtrapolation == false then
        ExtrapolationTicks = 0
        TickLead = 0
    end

    local Confidence = Data and math.clamp(tonumber(Data.MotionConfidence) or tonumber(Data.Confidence) or 0, 0, 1) or 0 local Jitter = Data and tonumber(Data.Jitter) or 0
    local DirectionChanges = Data and tonumber(Data.DirectionChanges) or 0 local Jerk = Data and tonumber(Data.Jerk) or 0
    local RelocationAge = Data and os.clock() - (tonumber(Data.RelocatedAt) or -math.huge) or math.huge local RecentlyRelocated = RelocationAge >= 0 and RelocationAge <= 0.30
    local CurrentRoot = Root or ResolverGetRoot(Character)
    local CurrentSnapshot = CurrentRoot and {Character = Character, ResolvedRootPosition = CurrentRoot.Position} or nil
    local PhysicalPartValid = CurrentSnapshot and ResolverIsBodyPartPlausible(Character, TargetPart, CurrentSnapshot) or false

    local Stability = Confidence
    Stability *= 1 - math.clamp(Jitter / math.max(ResolverState.MaximumJitter * 1.25, 1), 0, 0.72)
    Stability *= 1 - math.clamp(DirectionChanges / 4, 0, 0.65)
    Stability *= 1 - math.clamp(Jerk / 2200, 0, 0.55)
    Stability = math.clamp(Stability, 0.08, 1)

    local ManualBias = BaseTime * (0.18 + Stability * 0.28) local NetworkLead = (TickLead + math.clamp(SnapshotAge * 0.18, 0, TickLength)) * (0.52 + Stability * 0.48)
    local TimeValue = math.clamp(ManualBias + NetworkLead, 0, ResolverState.MaximumPrediction)

    local UseStablePose = not RecentlyRelocated and Data and (Data.IsDesynced or Jitter > ResolverState.MaximumJitter * 0.65) or false

    local SafePosition = RecentlyRelocated and PhysicalPartValid and RawPosition or ResolverGetSafePartPosition(Character, TargetPart, UseStablePose) or RawPosition

    if RecentlyRelocated then
        TimeValue = math.min(TimeValue, math.max(TickLength, BaseTime * 0.14))
        Stability = math.min(Stability, 0.22)
    end

    local Acceleration = Vector3.zero

    if Data and not RecentlyRelocated and Stability >= 0.50 and not Data.IsDesynced
        and Jitter < ResolverState.MaximumJitter * 0.70 and DirectionChanges < 1.5 and Jerk < 1450
    then
        local AccelerationLimit = math.clamp(34 + Stability * 28, 34, 62)
        Acceleration = ResolverClampVector(Data.Acceleration or Vector3.zero, AccelerationLimit)
    end

    if Humanoid and Humanoid.FloorMaterial ~= Enum.Material.Air and math.abs(ResolvedVelocity.Y) < 10 then
        ResolvedVelocity = Vector3.new(ResolvedVelocity.X, 0, ResolvedVelocity.Z)
        ReportedVelocity = Vector3.new(ReportedVelocity.X, 0, ReportedVelocity.Z)
        Acceleration = Vector3.new(Acceleration.X, 0, Acceleration.Z)
    end

    local NormalPrediction = RawPosition + ReportedVelocity * TimeValue
    local ResolvedPrediction = SafePosition + ResolvedVelocity * TimeValue + Acceleration * (0.5 * TimeValue * TimeValue)

    if DirectionChanges >= 1.5 or Jitter > ResolverState.MaximumJitter * 0.72 or Jerk > 1500 then
        local Damp = math.clamp(0.36 + Stability * 0.34, 0.36, 0.70)
        ResolvedPrediction = SafePosition:Lerp(ResolvedPrediction, Damp)
    end

    local MaximumTravel = math.min(
        MaximumSpeed * TimeValue + 1.15,
        12 + PingSeconds * 18 + Stability * 4
    )

    local Travel = ResolvedPrediction - SafePosition

    if Travel.Magnitude > MaximumTravel and Travel.Magnitude > 0 then ResolvedPrediction = SafePosition + Travel.Unit * MaximumTravel end

    local ResolverStrength

    if Data and Data.IsDesynced then
        ResolverStrength = math.clamp(0.58 + Stability * 0.24, 0.58, 0.82)
    else
        ResolverStrength = math.clamp(0.38 + Stability * 0.46, 0.38, 0.84)
    end

    local Position = NormalPrediction:Lerp(ResolvedPrediction, ResolverStrength)
    return Position, Data, ExtrapolationTicks, TimeValue
end

