function Internal.IsHitFeedbackEnabled()
    local ExtendedHit = type(ExtendedVisualState) == "table" and type(ExtendedVisualState.Hit) == "table" and ExtendedVisualState.Hit or nil
    local HitParticlesActive = HitFeedbackState.HitParticlesEnabled == true or type(HitParticleState) == "table" and HitParticleState.Enabled == true
    local ExtendedHitActive = ExtendedHit and (ExtendedHit.Skeleton == true or ExtendedHit.Marker3D == true or ExtendedHit.Overlay == true) or false
    return HitFeedbackState.HitmarkerEnabled == true or HitFeedbackState.ImpactEnabled == true or HitFeedbackState.DamageIndicatorEnabled == true
        or HitParticlesActive or HitFeedbackState.HitSound ~= "None" or HitFeedbackState.FinishSound ~= "None" or ExtendedHitActive
end
function Internal.IsShotTrackingEnabled() return HitFeedbackState.BulletTracerEnabled or Internal.IsHitFeedbackEnabled() or CombatLogState.Enabled == true end

function Internal.GetPlayerFromTrackedCharacter(Character)
    if not Character then return nil end

    local Player = Players:GetPlayerFromCharacter(Character)
    if Player then return Player end

    local NamedPlayer = Players:FindFirstChild(Character.Name)
    return NamedPlayer and NamedPlayer:IsA("Player") and NamedPlayer or nil
end

function Internal.GetHumanoidCharacterFromPart(Part)
    local Current = Part
    while Current and Current ~= workspace do
        if Current:IsA("Model") and Current:FindFirstChildOfClass("Humanoid") then return Current end
        Current = Current.Parent
    end
    return nil
end

function ResolverGetCharacterContainers(CurrentTime)
    local State = ResolverState.WorldCharacterCache
    CurrentTime = tonumber(CurrentTime) or os.clock()

    if CurrentTime >= (tonumber(State.NextRefresh) or 0)
        or State.WorldCharacters and not State.WorldCharacters.Parent
        or State.NormalCharacters and not State.NormalCharacters.Parent
    then
        local WorldContainer = workspace:FindFirstChild("©")
        State.WorldCharacters = WorldContainer and WorldContainer:FindFirstChild("Characters") or nil
        State.NormalCharacters = workspace:FindFirstChild("Characters")
        State.NextRefresh = CurrentTime + 0.40
    end

    return State.WorldCharacters, State.NormalCharacters
end

ResolveTrackedCharacter = function(Player, PreferredCharacter)
    if not Player then return nil end

    local CurrentTime = os.clock() local ResolveCache = ResolverState.CharacterResolveCache[Player]

    if type(ResolveCache) == "table" and CurrentTime - (tonumber(ResolveCache.Time) or 0) <= 0.050 then
        local CachedCharacter = ResolveCache.Character local CachedHumanoid = CachedCharacter and CachedCharacter:FindFirstChildOfClass("Humanoid")

        if CachedCharacter and CachedCharacter.Parent and CachedHumanoid and CachedHumanoid.Health > 0
            and (not PreferredCharacter or PreferredCharacter == Player.Character or PreferredCharacter == CachedCharacter)
        then
            return CachedCharacter
        end
    end

    local Cache = ResolverState and ResolverState.TargetCache and ResolverState.TargetCache[Player] or nil
    local Candidates = {}
    local Seen = {}

    local function Add(Character, Priority)
        if not Character or not Character:IsA("Model") or Seen[Character] then return end
        Seen[Character] = true
        Candidates[#Candidates + 1] = { Character = Character, Priority = Priority or 0 }
    end

    local WorldCharacters, NormalCharacters = ResolverGetCharacterContainers(CurrentTime)

    Add(WorldCharacters and WorldCharacters:FindFirstChild(Player.Name), 40)
    Add(NormalCharacters and NormalCharacters:FindFirstChild(Player.Name), 35)
    Add(PreferredCharacter, 30)
    Add(Player.Character, 25)
    Add(Cache and Cache.Character, 15)

    local Best local BestScore = -math.huge

    for Index = 1, #Candidates do
        local Entry = Candidates[Index] local Character = Entry.Character
        local Root = Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")
            or Character:FindFirstChild("LowerTorso")
        local Head = Character:FindFirstChild("Head") local Humanoid = Character:FindFirstChildOfClass("Humanoid")

        local Score = Entry.Priority

        if Character:IsDescendantOf(workspace) then Score += 24 end
        if Root and Root:IsA("BasePart") then Score += 18 end
        if Head and Head:IsA("BasePart") then Score += 14 end
        if Humanoid then
            Score += 12
            if Humanoid.Health > 0 then Score += 8 else Score -= 40 end
        end

        if Character == Player.Character then Score += 3 end

        local HeadCoherent = false local Torso = Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso") or Character:FindFirstChild("LowerTorso")
        local TorsoCoherent = false

        if Root and Root:IsA("BasePart") then
            if Head and Head:IsA("BasePart") then
                local Offset = Head.Position - Root.Position
                HeadCoherent = Offset.Magnitude <= 6 and Offset.Y >= -0.75 and Offset.Y <= 5
            end

            if Torso and Torso:IsA("BasePart") then
                local Offset = Torso.Position - Root.Position
                TorsoCoherent = Offset.Magnitude <= 5.75 and Offset.Y >= -1.75 and Offset.Y <= 2.60 and math.abs(Offset.X) <= 2.60 and math.abs(Offset.Z) <= 2.60
            end
        end

        if Root and Root:IsA("BasePart") and Cache and ResolverIsFiniteVector(Cache.StableRootPosition) then
            local DriftVector = Root.Position - Cache.StableRootPosition local Drift = DriftVector.Magnitude

            if Drift <= 8 then
                Score += 18
            elseif Drift <= 20 then
                Score += 8
            elseif Drift > 40 then
                if TorsoCoherent or HeadCoherent then
                    Score += math.abs(DriftVector.Y) >= 6 and 10 or 2
                else
                    Score -= 38
                end
            end
        end

        if Head and Head:IsA("BasePart") then
            if HeadCoherent then Score += 7 else Score -= 24 end
        end

        if Torso and Torso:IsA("BasePart") then
            if TorsoCoherent then Score += 12 else Score -= 18 end
        end

        if Score > BestScore then
            BestScore = Score
            Best = Character
        end
    end

    if Best and ResolverState and ResolverState.TargetCache then
        local Data = ResolverState.TargetCache[Player]
        if type(Data) ~= "table" then
            Data = {}
            ResolverState.TargetCache[Player] = Data
        end
        Data.Character = Best
        Data.LastCharacterSeen = os.clock()
    end

    ResolverState.CharacterResolveCache[Player] = { Character = Best, Time = CurrentTime }

    return Best
end

CombatChecks = CombatChecks or {}
CombatChecks.StatusCache = CombatChecks.StatusCache or setmetatable({}, {__mode = "k"})
CombatChecks.FriendCache = CombatChecks.FriendCache or setmetatable({}, {__mode = "k"})

function CombatChecks.GetCharacters(Player, PreferredCharacter)
    local Characters = {}
    local Seen = {}

    local function Add(Character)
        if not Character or not Character:IsA("Model") or Seen[Character] then return end
        Seen[Character] = true
        Characters[#Characters + 1] = Character
    end

    Add(PreferredCharacter)
    Add(Player and Player.Character or nil)

    if Player then
        local WorldCharacters local NormalCharacters

        if type(ResolverGetCharacterContainers) == "function" then
            WorldCharacters, NormalCharacters = ResolverGetCharacterContainers(os.clock())
        else
            local WorldContainer = workspace:FindFirstChild("©")
            WorldCharacters = WorldContainer and WorldContainer:FindFirstChild("Characters") or nil
            NormalCharacters = workspace:FindFirstChild("Characters")
        end

        Add(WorldCharacters and WorldCharacters:FindFirstChild(Player.Name))
        Add(NormalCharacters and NormalCharacters:FindFirstChild(Player.Name))
    end

    return Characters
end

function CombatChecks.IsDead(Player, PreferredCharacter, Snapshot)
    local Characters = CombatChecks.GetCharacters(Player, PreferredCharacter)

    for Index = 1, #Characters do
        local Character = Characters[Index] local Humanoid = Character:FindFirstChildOfClass("Humanoid")
        if Humanoid and Character == (Player and Player.Character or nil) then return Humanoid.Health <= 0 end
    end

    local Humanoid = PreferredCharacter and PreferredCharacter:FindFirstChildOfClass("Humanoid")
    if Humanoid then return Humanoid.Health <= 0 end

    local Health = Snapshot and tonumber(Snapshot.LastHealth) or nil
    return Health ~= nil and Health <= 0
end

function CombatChecks.IsDowned(Player, PreferredCharacter)
    if not Player then return false end

    local CharStats = ReplicatedStorage:FindFirstChild("CharStats")
    local PlayerStats = CharStats and (CharStats:FindFirstChild(Player.Name) or CharStats:FindFirstChild(tostring(Player.UserId)))
    local Downed = PlayerStats and (PlayerStats:FindFirstChild("Downed") or PlayerStats:FindFirstChild("IsDowned"))

    if Downed and Downed:IsA("BoolValue") and Downed.Value == true then return true end
    if PlayerStats and (PlayerStats:GetAttribute("Downed") == true or PlayerStats:GetAttribute("IsDowned") == true) then return true end

    local Characters = CombatChecks.GetCharacters(Player, PreferredCharacter)
    for Index = 1, #Characters do
        local Character = Characters[Index]
        if Character:GetAttribute("Downed") == true or Character:GetAttribute("IsDowned") == true then return true end

        local State = Character:FindFirstChild("Downed", true) or Character:FindFirstChild("IsDowned", true)
        if State and State:IsA("BoolValue") and State.Value == true then return true end
    end

    return false
end

function CombatChecks.HasForceField(Player, PreferredCharacter)
    local Characters = CombatChecks.GetCharacters(Player, PreferredCharacter)

    for Index = 1, #Characters do
        local Character = Characters[Index]
        if Character:FindFirstChildOfClass("ForceField") then return true end

        local ForceField = Character:FindFirstChild("ForceField", true)
        if ForceField and ForceField:IsA("ForceField") then return true end
    end

    return false
end

function CombatChecks.IsFriend(Player)
    if not Player or Player == LocalPlayer then return true end
    if WhitelistTable[Player] == true then return true end
    if LocalPlayer.Team ~= nil and Player.Team ~= nil and LocalPlayer.Team == Player.Team then return true end

    local CurrentTime = os.clock() local Cached = CombatChecks.FriendCache[Player]

    if type(Cached) == "table" and CurrentTime - (tonumber(Cached.Time) or 0) <= 2 then return Cached.Value == true end

    local Success, Result = Internal.Call(function()
        return LocalPlayer:IsFriendsWith(Player.UserId)
    end)

    local Value = Success == true and Result == true
    CombatChecks.FriendCache[Player] = {Time = CurrentTime, Value = Value}
    return Value
end

function CombatChecks.IsVisible(Origin, TargetPosition, Player, PreferredCharacter)
    if typeof(Origin) ~= "Vector3" or typeof(TargetPosition) ~= "Vector3" then return false end

    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.FilterDescendantsInstances = { LocalPlayer.Character, workspace.CurrentCamera }
    Parameters.IgnoreWater = true

    local Result = workspace:Raycast(Origin, TargetPosition - Origin, Parameters)
    if not Result then return true end

    local Hit = Result.Instance
    if not Hit then return true end

    local Characters = CombatChecks.GetCharacters(Player, PreferredCharacter)
    for Index = 1, #Characters do
        if Hit:IsDescendantOf(Characters[Index]) then return true end
    end

    return false
end

function CombatChecks.Passes(Player, Character, Settings, Snapshot)
    if not Player or not Character or type(Settings) ~= "table" then return false end

    local CurrentTime = os.clock() local Cached = CombatChecks.StatusCache[Player]

    if type(Cached) ~= "table" or Cached.Character ~= Character
        or CurrentTime - (tonumber(Cached.Time) or 0) > 0.050
    then
        Cached = {
            Character = Character,
            Time = CurrentTime,
            Dead = CombatChecks.IsDead(Player, Character, Snapshot),
            Downed = CombatChecks.IsDowned(Player, Character),
            ForceField = CombatChecks.HasForceField(Player, Character)
        }
        CombatChecks.StatusCache[Player] = Cached
    end

    if Settings.DeadCheck == true and Cached.Dead then return false end
    if Settings.DownedCheck == true and Cached.Downed then return false end
    if Settings.ForceFieldCheck == true and Cached.ForceField then return false end
    if Settings.FriendCheck == true and CombatChecks.IsFriend(Player) then return false end
    return true
end

function ResolverGetRigProfile(Character)
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") local IsR6 = Humanoid and Humanoid.RigType == Enum.HumanoidRigType.R6

    if IsR6 then
        return {
            HeadOffset = Vector3.new(0, 1.50, 0),
            TorsoOffset = Vector3.new(0, 0.45, 0),
            TopOffset = 2.55,
            BottomOffset = -3.00,
            Width = 3.05
        }
    end

    return {
        HeadOffset = Vector3.new(0, 1.75, 0),
        TorsoOffset = Vector3.new(0, 0.55, 0),
        TopOffset = 2.75,
        BottomOffset = -3.10,
        Width = 3.15
    }
end

function ResolverGetPartCategory(Part)
    if not Part then return "Other" end

    local Name = string.lower(tostring(Part.Name or ""))
    if Name == "head" then return "Head" end
    if string.find(Name, "torso", 1, true) then return "Torso" end
    if Name == "humanoidrootpart" then return "Root" end

    if string.find(Name, "arm", 1, true) or string.find(Name, "hand", 1, true)
        or string.find(Name, "leg", 1, true) or string.find(Name, "foot", 1, true)
    then
        return "Limb"
    end

    return "Other"
end

function ResolverIsBodyPartPlausible(Character, Part, Snapshot)
    if not Character or not Part or not Part:IsA("BasePart") or Part.Parent ~= Character then return false end

    local Root = ResolverGetRoot(Character)
    if not Root or not Root:IsA("BasePart") then return false end
    if not ResolverIsFiniteVector(Part.Position) or not ResolverIsFiniteVector(Part.Size) then return false end
    if Part.Size.X <= 0.03 or Part.Size.Y <= 0.03 or Part.Size.Z <= 0.03 or Part.Size.Magnitude > 18 then return false end

    local RootPosition = Snapshot and ResolverIsFiniteVector(Snapshot.ResolvedRootPosition) and Snapshot.ResolvedRootPosition or Root.Position
    local Offset = Part.Position - RootPosition local Category = ResolverGetPartCategory(Part)

    if not ResolverIsFiniteVector(Offset) then return false end

    if Category == "Head" then
        return Offset.Magnitude <= 5.25 and Offset.Y >= 0.40 and Offset.Y <= 4.60 and math.abs(Offset.X) <= 2.20 and math.abs(Offset.Z) <= 2.20
    elseif Category == "Torso" then
        return Offset.Magnitude <= 5.75 and Offset.Y >= -1.75 and Offset.Y <= 2.60 and math.abs(Offset.X) <= 2.60 and math.abs(Offset.Z) <= 2.60
    elseif Category == "Root" then
        return Offset.Magnitude <= 1.25
    elseif Category == "Limb" then
        return Offset.Magnitude <= 7.50 and Offset.Y >= -5.25 and Offset.Y <= 4.75 and math.abs(Offset.X) <= 4.75 and math.abs(Offset.Z) <= 4.75
    end

    return Offset.Magnitude <= 8.50
end

function ResolverUpdateStableOffset(Cache, Key, RawOffset, FallbackOffset, Plausible, CurrentTime, MaximumDeviation)
    local Stable = ResolverIsFiniteVector(Cache[Key]) and Cache[Key] or nil

    if Plausible and ResolverIsFiniteVector(RawOffset) then
        if Stable then
            local Difference = (RawOffset - Stable).Magnitude

            if Difference <= (tonumber(MaximumDeviation) or 1.75) then Stable = Stable:Lerp(RawOffset, 0.18) end
        else
            Stable = RawOffset
        end

        Cache[Key] = Stable
        Cache.LastStablePose = CurrentTime
    end

    return ResolverIsFiniteVector(Stable) and Stable or FallbackOffset
end

function ResolverGetResolvedPartPosition(Snapshot, Part)
    if not Snapshot or not Part or not Part:IsA("BasePart") then return Part and Part.Position or nil end

    local Category = ResolverGetPartCategory(Part)

    if Snapshot.PhysicalRelocation == true
        and ResolverIsBodyPartPlausible(Snapshot.Character, Part, {Character = Snapshot.Character, ResolvedRootPosition = Snapshot.Root.Position})
    then
        return Part.Position
    end

    if Category == "Head" and ResolverIsFiniteVector(Snapshot.ResolvedHeadPosition) then
        return Snapshot.ResolvedHeadPosition
    elseif Category == "Torso" and ResolverIsFiniteVector(Snapshot.ResolvedTorsoPosition) then
        return Snapshot.ResolvedTorsoPosition
    elseif Category == "Root" and ResolverIsFiniteVector(Snapshot.ResolvedRootPosition) then
        return Snapshot.ResolvedRootPosition
    end

    if ResolverIsBodyPartPlausible(Snapshot.Character, Part, Snapshot) then return Part.Position end

    return ResolverIsFiniteVector(Snapshot.ResolvedTorsoPosition) and Snapshot.ResolvedTorsoPosition
        or ResolverIsFiniteVector(Snapshot.ResolvedRootPosition) and Snapshot.ResolvedRootPosition
        or Part.Position
end

function ResolverGetTargetSnapshot(Player, PreferredCharacter)
    if not Player then return nil end

    local Character = ResolveTrackedCharacter(Player, PreferredCharacter) local Cache = ResolverState.TargetCache[Player]

    if type(Cache) ~= "table" then
        Cache = {}
        ResolverState.TargetCache[Player] = Cache
    end

    local CurrentTime = os.clock()

    if Cache.Character == Character and type(Cache.LastSnapshot) == "table"
        and CurrentTime - (tonumber(Cache.LastSnapshotAt) or 0) < 1 / 90
    then
        return Cache.LastSnapshot
    end

    if not Character then return Cache.LastSnapshot end

    local Root = ResolverGetRoot(Character) local Head = Character:FindFirstChild("Head")
    local Torso = Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso") or Character:FindFirstChild("LowerTorso")
    local Humanoid = Character:FindFirstChildOfClass("Humanoid") local Profile = ResolverGetRigProfile(Character)

    if not Root or not Root:IsA("BasePart") then return Cache.LastSnapshot end

    if Cache.Character ~= Character or Cache.Root ~= Root then
        Cache.StableRootPosition = Root.Position
        Cache.StableHeadOffset = nil
        Cache.StableTorsoOffset = nil
        Cache.RootPosition = Root.Position
        Cache.RootTeleported = false
    end

    local RootPosition = Root.Position local PreviousRoot = ResolverIsFiniteVector(Cache.RootPosition) and Cache.RootPosition or RootPosition
    local StableRoot = ResolverIsFiniteVector(Cache.StableRootPosition) and Cache.StableRootPosition or RootPosition local RootDelta = (RootPosition - PreviousRoot).Magnitude
    local RawHeadPosition = Head and Head:IsA("BasePart") and Head.Position or nil local RawTorsoPosition = Torso and Torso:IsA("BasePart") and Torso.Position or nil

    local CurrentRootSnapshot = {Character = Character, ResolvedRootPosition = RootPosition}
    local CurrentHeadPlausible = Head and ResolverIsBodyPartPlausible(Character, Head, CurrentRootSnapshot) or false
    local CurrentTorsoPlausible = Torso and ResolverIsBodyPartPlausible(Character, Torso, CurrentRootSnapshot) or false
    local WholeBodyCoherent = CurrentHeadPlausible and CurrentTorsoPlausible local RootBodyCoherent = CurrentTorsoPlausible or CurrentHeadPlausible
    local StableRootDelta = RootPosition - StableRoot local VerticalRelocation = math.abs(StableRootDelta.Y) >= 6 and RootBodyCoherent
    local LargeRelocation = RootDelta > ResolverState.TeleportDistance or StableRootDelta.Magnitude > ResolverState.TeleportDistance * 1.25

    local RootTeleported = LargeRelocation

    if LargeRelocation and (WholeBodyCoherent or VerticalRelocation or CurrentTorsoPlausible) then
        StableRoot = RootPosition
        Cache.StableRootPosition = RootPosition
        Cache.LastStableRootSeen = CurrentTime
        Cache.PhysicalRelocationUntil = CurrentTime + 0.35
        Cache.PhysicalRelocationPosition = RootPosition
        RootTeleported = false
    elseif not RootTeleported then
        Cache.StableRootPosition = StableRoot:Lerp(RootPosition, 0.28)
        Cache.LastStableRootSeen = CurrentTime
    end

    Cache.Root = Root
    Cache.RootPosition = RootPosition
    Cache.RootTeleported = RootTeleported

    local ResolvedRootPosition = RootTeleported and StableRoot or RootPosition
    if not ResolverIsFiniteVector(ResolvedRootPosition) then ResolvedRootPosition = RootPosition end

    local RawHeadOffset = ResolverIsFiniteVector(RawHeadPosition) and RawHeadPosition - ResolvedRootPosition or nil
    local RawTorsoOffset = ResolverIsFiniteVector(RawTorsoPosition) and RawTorsoPosition - ResolvedRootPosition or nil

    local HeadPlausible = Head and ResolverIsBodyPartPlausible(Character, Head, {
        Character = Character, ResolvedRootPosition = ResolvedRootPosition
    }) or false

    local TorsoPlausible = Torso and ResolverIsBodyPartPlausible(Character, Torso, {
        Character = Character, ResolvedRootPosition = ResolvedRootPosition
    }) or false

    local StableHeadOffset = ResolverUpdateStableOffset(
        Cache, "StableHeadOffset", RawHeadOffset, Profile.HeadOffset, HeadPlausible, CurrentTime, 1.45
    )

    local StableTorsoOffset = ResolverUpdateStableOffset(
        Cache, "StableTorsoOffset", RawTorsoOffset, Profile.TorsoOffset, TorsoPlausible, CurrentTime, 1.60
    )

    StableHeadOffset = Vector3.new(
        math.clamp(StableHeadOffset.X, -0.35, 0.35),
        math.clamp(StableHeadOffset.Y, 1.05, 3.30),
        math.clamp(StableHeadOffset.Z, -0.35, 0.35)
    )

    StableTorsoOffset = Vector3.new(
        math.clamp(StableTorsoOffset.X, -0.55, 0.55),
        math.clamp(StableTorsoOffset.Y, -0.65, 1.65),
        math.clamp(StableTorsoOffset.Z, -0.55, 0.55)
    )

    local StableHeadPosition = ResolvedRootPosition + StableHeadOffset local StableTorsoPosition = ResolvedRootPosition + StableTorsoOffset
    local HeadError = ResolverIsFiniteVector(RawHeadPosition) and (RawHeadPosition - StableHeadPosition).Magnitude or math.huge
    local TorsoError = ResolverIsFiniteVector(RawTorsoPosition) and (RawTorsoPosition - StableTorsoPosition).Magnitude or math.huge

    local HeadSuspicious = not HeadPlausible or HeadError > 1.10 local TorsoSuspicious = not TorsoPlausible or TorsoError > 1.35

    local ResolvedHeadPosition = HeadSuspicious and StableHeadPosition or RawHeadPosition
    local ResolvedTorsoPosition = TorsoSuspicious and StableTorsoPosition or RawTorsoPosition

    if not ResolverIsFiniteVector(ResolvedHeadPosition) then ResolvedHeadPosition = StableHeadPosition end
    if not ResolverIsFiniteVector(ResolvedTorsoPosition) then ResolvedTorsoPosition = StableTorsoPosition end

    local BodyScan = Cache.BodyScan

    if type(BodyScan) ~= "table" or BodyScan.Character ~= Character
        or CurrentTime - (tonumber(BodyScan.Time) or 0) >= 0.050
    then
        local BodyParts = 0 local AnomalousParts = 0 local TransparentParts = 0
        local PlausibilitySnapshot = {Character = Character, ResolvedRootPosition = ResolvedRootPosition}

        for _, Part in ipairs(Character:GetChildren()) do
            if Part:IsA("BasePart") then
                BodyParts += 1

                if Part.Transparency >= 0.45 then TransparentParts += 1 end

                if Part ~= Root and not ResolverIsBodyPartPlausible(Character, Part, PlausibilitySnapshot) then AnomalousParts += 1 end
            end
        end

        BodyScan = { Character = Character, Time = CurrentTime, BodyParts = BodyParts, AnomalousParts = AnomalousParts, TransparentParts = TransparentParts }
        Cache.BodyScan = BodyScan
    end

    local BodyParts = tonumber(BodyScan.BodyParts) or 0 local AnomalousParts = tonumber(BodyScan.AnomalousParts) or 0
    local TransparentParts = tonumber(BodyScan.TransparentParts) or 0 local TransparencyRatio = BodyParts > 0 and TransparentParts / BodyParts or 0
    local AnomalyRatio = BodyParts > 0 and AnomalousParts / BodyParts or 0

    local PhysicalRelocation = CurrentTime <= (tonumber(Cache.PhysicalRelocationUntil) or 0)
    local SuspiciousPose = RootTeleported or HeadSuspicious or TorsoSuspicious or AnomalyRatio >= 0.20 or TransparencyRatio >= 0.55

    if PhysicalRelocation and CurrentTorsoPlausible then SuspiciousPose = HeadSuspicious or AnomalyRatio >= 0.34 or TransparencyRatio >= 0.72 end

    local BoxTopY = math.max(ResolvedHeadPosition.Y + 0.68, ResolvedRootPosition.Y + Profile.TopOffset) local BoxBottomY = ResolvedRootPosition.Y + Profile.BottomOffset

    local Snapshot = {
        Player = Player,
        Character = Character,
        Root = Root,
        Head = Head,
        Torso = Torso,
        Humanoid = Humanoid,
        RawHeadPosition = RawHeadPosition,
        RawTorsoPosition = RawTorsoPosition,
        StableHeadPosition = StableHeadPosition,
        StableTorsoPosition = StableTorsoPosition,
        ResolvedHeadPosition = ResolvedHeadPosition,
        ResolvedTorsoPosition = ResolvedTorsoPosition,
        StableRootPosition = Cache.StableRootPosition,
        ResolvedRootPosition = ResolvedRootPosition,
        BoxTopPosition = Vector3.new(ResolvedRootPosition.X, BoxTopY, ResolvedRootPosition.Z),
        BoxBottomPosition = Vector3.new(ResolvedRootPosition.X, BoxBottomY, ResolvedRootPosition.Z),
        BoxWidthStuds = Profile.Width,
        HeadPlausible = HeadPlausible,
        TorsoPlausible = TorsoPlausible,
        HeadSuspicious = HeadSuspicious,
        TorsoSuspicious = TorsoSuspicious,
        HeadError = HeadError,
        TorsoError = TorsoError,
        AnomalousParts = AnomalousParts,
        AnomalyRatio = AnomalyRatio,
        TransparencyRatio = TransparencyRatio,
        SuspiciousPose = SuspiciousPose,
        RootTeleported = RootTeleported,
        WholeBodyCoherent = WholeBodyCoherent,
        RootBodyCoherent = RootBodyCoherent,
        PhysicalRelocation = PhysicalRelocation,
        VerticalRelocation = VerticalRelocation,
        LastHealth = Humanoid and Humanoid.Health or tonumber(Cache.LastHealth),
        Age = 0
    }

    Cache.Character = Character
    Cache.Head = Head
    Cache.Torso = Torso
    Cache.Humanoid = Humanoid
    Cache.LastHealth = Humanoid and Humanoid.Health or Cache.LastHealth
    Cache.LastCharacterSeen = CurrentTime
    Cache.LastSnapshotAt = CurrentTime
    Cache.LastSnapshot = Snapshot

    return Snapshot
end

function CombatLogRuntime.GetDisplayName(Player)
    if not Player then return "Unknown" end

    local Name = tostring( Player.DisplayName or Player.Name or "Unknown")

    if Name == "" then Name = tostring( Player.Name or "Unknown") end

    return Name
end

function CombatLogRuntime.FormatDistance(Value)
    Value = tonumber(Value)

    if not Value or Value ~= Value or Value == math.huge or Value == -math.huge then return nil end

    if Value >= 100 then return tostring( math.floor( Value + 0.5 )) end

    return string.format( "%.1f", Value)
end

function CombatLogRuntime.ApplyLogLayout()
    if Library and type(Library.SetNotificationLayout) == "function" then Library:SetNotificationLayout(CombatLogState.Position, CombatLogState.Scale) end
end

function CombatLogRuntime.BindLibraryNotice(Notice)
    if typeof(Notice) == "Instance" then
        Notice:SetAttribute("AtramentaCombatLog", true)
        CombatLogRuntime.LibraryNotices[Notice] = true
    end
    CombatLogRuntime.ApplyLogLayout()
    return Notice
end

function CombatLogRuntime.ClearVisualLogs()
    for Notice in pairs(CombatLogRuntime.LibraryNotices) do
        CombatLogRuntime.LibraryNotices[Notice] = nil
        if Notice and Notice.Parent and Notice:GetAttribute("AtramentaCombatLog") == true then Notice:Destroy() end
    end
end

function CombatLogRuntime.MaintainRuntime(CurrentTime, Force)
    CurrentTime = tonumber(CurrentTime) or os.clock()
    if Force ~= true and CurrentTime < (tonumber(CombatLogRuntime.NextMaintenance) or 0) then return end
    CombatLogRuntime.NextMaintenance = CurrentTime + (tonumber(CombatLogRuntime.MaintenanceInterval) or 1.25)

    local FreshKeys, Count = {}, 0
    for Key, Time in pairs(CombatLogRuntime.RecentNearMissKeys) do
        if CurrentTime - (tonumber(Time) or 0) <= 1 and Count < 192 then
            FreshKeys[Key] = Time
            Count += 1
        end
    end
    CombatLogRuntime.RecentNearMissKeys = FreshKeys
    CombatLogRuntime.RecentNearMissKeyCount = Count

    for Index = #CombatLogRuntime.RecentEnemyShots, 1, -1 do
        local Entry = CombatLogRuntime.RecentEnemyShots[Index]
        if not Entry or CurrentTime - (tonumber(Entry.Time) or 0) > 1 then table.remove(CombatLogRuntime.RecentEnemyShots, Index) end
    end
    while #CombatLogRuntime.RecentEnemyShots > 48 do table.remove(CombatLogRuntime.RecentEnemyShots, 1) end

    for Notice in pairs(CombatLogRuntime.LibraryNotices) do
        if not Notice or not Notice.Parent then CombatLogRuntime.LibraryNotices[Notice] = nil end
    end
end

function CombatLogRuntime.ProcessNearMissQueue(CurrentTime)
    CurrentTime = tonumber(CurrentTime) or os.clock()

    local Queue = CombatLogRuntime.NearMissQueue
    for Index = #Queue, 1, -1 do
        local Entry = Queue[Index]
        if not Entry or CurrentTime >= (tonumber(Entry.Due) or 0) then
            table.remove(Queue, Index)
            if not Entry then continue end

            local Shot = Entry.Shot
            if type(Shot) == "table" and Shot.DamageConfirmed == true then continue end
            if CombatLogRuntime.RecentDamageAt >= (tonumber(Entry.Time) or 0) then continue end

            local Player = Entry.Player
            if not Player or not Player.Parent then continue end

            local DistanceText = CombatLogRuntime.FormatDistance(Entry.MissDistance)
            if not DistanceText then continue end

            local LocalRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            local ShooterCharacter = ResolveTrackedCharacter(Player, Player.Character)
            local ShooterRoot = ShooterCharacter and ShooterCharacter:FindFirstChild("HumanoidRootPart")
            local SourceDistance = LocalRoot and ShooterRoot and (ShooterRoot.Position - LocalRoot.Position).Magnitude or nil local Detail = tostring(Entry.PartName or "Body")
            local SourceDistanceText = CombatLogRuntime.FormatDistance(SourceDistance)

            if SourceDistanceText then Detail = Detail .. "  •  " .. SourceDistanceText .. " studs away" end
            CombatLogRuntime.Emit("NearMiss", "Near miss from [" .. CombatLogRuntime.GetDisplayName(Player) .. "]  •  " .. DistanceText .. " studs", Detail)
        end
    end
end

function CombatLogRuntime.ProcessEnemyShotQueue(CurrentTime)
    CurrentTime = tonumber(CurrentTime) or os.clock()
    local Queue = CombatLogRuntime.EnemyShotQueue
    for Index = #Queue, 1, -1 do
        local Entry = Queue[Index]
        if not Entry or CurrentTime >= (tonumber(Entry.Due) or 0) then
            table.remove(Queue, Index)
            local Object = Entry and Entry.Object
            if Object and Object.Parent then
                if Entry.IsBeam then
                    local Attachment0, Attachment1 = Object.Attachment0, Object.Attachment1
                    if Attachment0 and Attachment1 then
                        local Origin, EndPosition = Attachment0.WorldPosition, Attachment1.WorldPosition
                        if (EndPosition - Origin).Magnitude >= 2 then
                            local Player = CombatLogRuntime.ResolveEnemyShotSource(Origin, Object)
                            if Player then CombatLogRuntime.RecordEnemyShot(Player, Origin, EndPosition, Object) end
                        end
                    end
                elseif Object:IsA("BasePart") and typeof(Entry.StartPosition) == "Vector3" then
                    local EndPosition = Object.Position
                    if (EndPosition - Entry.StartPosition).Magnitude >= 1 then
                        local Player = CombatLogRuntime.ResolveEnemyShotSource(Entry.StartPosition, Object)
                        if Player then CombatLogRuntime.RecordEnemyShot(Player, Entry.StartPosition, EndPosition, Object) end
                    end
                end
            end
        end
    end
end

function CombatLogRuntime.Emit(Kind, Message, Detail)
    if CombatLogState.Enabled ~= true then return end

    Kind = tostring( Kind or "Info")

    if ( Kind == "Hit" or Kind == "Kill" ) and CombatLogState.Hits ~= true then return end

    if Kind == "Miss" and CombatLogState.Misses ~= true then return end

    if Kind == "Damage" and CombatLogState.Incoming ~= true then return end

    if Kind == "NearMiss" and CombatLogState.NearMiss ~= true then return end

    if not Library or type( Library.Notification ) ~= "function" then return end

    local Mode = Kind == "Damage" and "Danger" or ( Kind == "Miss" or Kind == "NearMiss" ) and "Warn" or "Success"

    local Description = tostring( Message or "")

    if tostring( Detail or "" ) ~= "" then Description = Description .. "  •  " .. tostring( Detail) end

    task.defer( function()
            local SetIdentity = type( setthreadidentity ) == "function" and setthreadidentity or type( setidentity ) == "function" and setidentity or nil

            if SetIdentity then SetIdentity(8) end

            if not Library or type( Library.Notification ) ~= "function" then return end

            local Notice = Library:Notification({ Title = "Atramenta", Description = Description, Duration = CombatLogState.Duration, Mode = Mode })

            CombatLogRuntime.BindLibraryNotice( Notice)
        end)
end

function CombatLogRuntime.GetShotSourceName(Shot)
    local Source = Shot and tostring( Shot.Source or "" ) or ""

    if Source == "RageBot" then
        return "Ragebot"
    elseif Source == "SilentAim" or Source == "SilentAimFallback" or Source == "Silent Aim" then
        return "Silent Aim"
    elseif Source == "Aimbot" then
        return "Aimbot"
    elseif Source == "Remote" or Source == "Manual" or Source == "Local" or Source == "ActivationFallback" then
        return "Manual"
    end

    return Source ~= "" and Source or "Weapon"
end

function CombatLogRuntime.GetShotTargetPart(Shot)
    if type(Shot) ~= "table" or not Shot.Player then return nil, nil end

    local Character = ResolveTrackedCharacter( Shot.Player, Shot.Character)

    if not Character then return nil, nil end

    local Part = Shot.PartName and Character:FindFirstChild( Shot.PartName, true ) or nil

    if not Part or not Part:IsA("BasePart") then
        Part = Character:FindFirstChild( "HumanoidRootPart", true ) or Character:FindFirstChild( "Head", true ) or Character.PrimaryPart
    end

    return Character, Part
end

function CombatLogRuntime.GetWeaponRange(Tool)
    if not Tool then return nil end

    if type(GetBulletTracerWeaponData)
        == "function" then
        local Data = GetBulletTracerWeaponData( Tool)

        if type(Data) == "table" then
            local Range = tonumber(Data.Range)

            if Range and Range > 0 then return Range end
        end
    end

    return nil
end

function CombatLogRuntime.GetPointSegmentDistance(Point, StartPosition, EndPosition)
    if typeof(Point) ~= "Vector3" or typeof(StartPosition) ~= "Vector3" or typeof(EndPosition) ~= "Vector3" then return math.huge, StartPosition, 0 end

    local Segment = EndPosition - StartPosition local LengthSquared = Segment:Dot(Segment)
    if LengthSquared <= 0.0001 then return (Point - StartPosition).Magnitude, StartPosition, 0 end

    local Alpha = math.clamp((Point - StartPosition):Dot(Segment) / LengthSquared, 0, 1) local Closest = StartPosition + Segment * Alpha
    return (Point - Closest).Magnitude, Closest, Alpha
end

function CombatLogRuntime.GetPreferredBodyParts(Character)
    if not Character then return {} end

    local CurrentTime = os.clock()

    local Cached = CombatLogRuntime. BodyPartCache[ Character ]

    if type(Cached) == "table" and CurrentTime
            < ( tonumber(Cached.RefreshAt) or 0 ) and type(Cached.Parts)
            == "table" then
        return Cached.Parts
    end

    local PreferredNames = { Head = true, HumanoidRootPart = true, UpperTorso = true, LowerTorso = true, Torso = true, ["Left Arm"] = true,
        ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true, LeftUpperArm = true, RightUpperArm = true, LeftLowerArm = true,
        RightLowerArm = true, LeftUpperLeg = true, RightUpperLeg = true, LeftLowerLeg = true, RightLowerLeg = true }

    local Parts = {}

    for _, Part in ipairs( Character:GetDescendants() ) do
        if Part:IsA("BasePart") and PreferredNames[ Part.Name ] then Parts[#Parts + 1] = Part end
    end

    CombatLogRuntime. BodyPartCache[ Character ] = { Parts = Parts, RefreshAt = CurrentTime + 1 }

    return Parts
end

function CombatLogRuntime.GetClosestBodyPartToSegment(Character, StartPosition, EndPosition)
    if not Character then return nil, math.huge, 0 end

    local BestPart, BestDistance, BestProjection = nil, math.huge, 0

    for _, Part in ipairs(CombatLogRuntime.GetPreferredBodyParts(Character)) do
        if Part and Part.Parent then
            local CenterDistance, _, Projection = CombatLogRuntime.GetPointSegmentDistance(Part.Position, StartPosition, EndPosition)
            local Radius = math.max(math.min(Part.Size.X, Part.Size.Y, Part.Size.Z) * 0.42, 0.22) local SurfaceDistance = math.max(CenterDistance - Radius, 0)

            if SurfaceDistance < BestDistance then
                BestPart = Part
                BestDistance = SurfaceDistance
                BestProjection = Projection
            end
        end
    end

    return BestPart, BestDistance, BestProjection
end

function CombatLogRuntime.ResolvePlayerFromObject(Object)
    local Current = Object

    while Current and Current ~= workspace do
        if Current:IsA("Model") then
            local Player = Players:GetPlayerFromCharacter( Current)

            if Player then return Player end

            local Named = Players:FindFirstChild( Current.Name)

            if Named and Named:IsA( "Player" ) then return Named end
        end

        Current = Current.Parent
    end

    return nil
end

function CombatLogRuntime.FindNearestEnemyToPosition(Position, MaximumDistance)
    if typeof(Position) ~= "Vector3" then return nil end

    MaximumDistance = tonumber(MaximumDistance) or 18

    local BestPlayer = nil local BestDistance = MaximumDistance

    for _, Player in ipairs( Players:GetPlayers() ) do
        if Player ~= LocalPlayer then
            local Character = ResolveTrackedCharacter( Player, Player.Character)

            local Root = Character and Character:FindFirstChild( "HumanoidRootPart")

            if Root then
                local Distance = ( Root.Position - Position ).Magnitude

                if Distance
                    < BestDistance then
                    BestDistance = Distance

                    BestPlayer = Player
                end
            end
        end
    end

    return BestPlayer
end

function CombatLogRuntime.ResolveEnemyShotSource(Origin, Object)
    local Player = CombatLogRuntime.ResolvePlayerFromObject( Object)

    if not Player and Object and Object.Parent then Player = CombatLogRuntime.ResolvePlayerFromObject( Object.Parent) end

    if not Player then Player = CombatLogRuntime.FindNearestEnemyToPosition(Origin, CombatLogRuntime.EnemyShotSourceRadius or 10) end

    if Player == LocalPlayer then return nil end

    return Player
end

function CombatLogRuntime.IsOwnVisual(Object)
    local Current = Object

    for _ = 1, 5 do
        if not Current then break end

        if string.find( string.lower( Current.Name ), "atramenta", 1, true ) then return true end

        Current = Current.Parent
    end

    return false
end

function CombatLogRuntime.IsEnemyShotTrajectoryValid(Player, Origin, EndPosition, Character)
    if not Player or Player == LocalPlayer or typeof(Origin) ~= "Vector3" or typeof(EndPosition) ~= "Vector3" then return false end

    local Segment = EndPosition - Origin
    if Segment.Magnitude < 4 then return false end

    local ShooterCharacter = ResolveTrackedCharacter(Player, Player.Character) local ShooterRoot = ShooterCharacter and ShooterCharacter:FindFirstChild("HumanoidRootPart")
    local LocalRoot = Character and Character:FindFirstChild("HumanoidRootPart")
    if not ShooterRoot or not LocalRoot then return false end

    local OriginTolerance = math.max(tonumber(CombatLogRuntime.EnemyShotOriginTolerance) or 14, 4)
    if (Origin - ShooterRoot.Position).Magnitude > OriginTolerance then return false end

    local ToLocal = LocalRoot.Position - Origin
    if ToLocal.Magnitude <= 0.001 then return false end

    local Direction = Segment.Unit local Alignment = Direction:Dot(ToLocal.Unit)
    if Alignment < 0.72 then return false end

    local _, _, Projection = CombatLogRuntime.GetPointSegmentDistance(LocalRoot.Position, Origin, EndPosition)
    return Projection >= 0.035 and Projection <= 0.985
end

function CombatLogRuntime.RecordEnemyShot(Player, Origin, EndPosition, SourceObject)
    if CombatLogState.Enabled ~= true or not Player or Player == LocalPlayer or typeof(Origin) ~= "Vector3" or typeof(EndPosition) ~= "Vector3" then return end

    local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    if not Root or not CombatLogRuntime.IsEnemyShotTrajectoryValid(Player, Origin, EndPosition, Character) then return end

    local Part, MissDistance, Projection = CombatLogRuntime.GetClosestBodyPartToSegment(Character, Origin, EndPosition)
    if not Part or MissDistance == math.huge or Projection < 0.035 or Projection > 0.985 then return end

    local CurrentTime = os.clock()
    CombatLogRuntime.MaintainRuntime(CurrentTime, false)

    local ShotEntry = {
        Time = CurrentTime, Player = Player, Origin = Origin, EndPosition = EndPosition, Part = Part,
        MissDistance = MissDistance, Projection = Projection, SourceObject = SourceObject, DamageConfirmed = false
    }

    CombatLogRuntime.RecentEnemyShots[#CombatLogRuntime.RecentEnemyShots + 1] = ShotEntry
    while #CombatLogRuntime.RecentEnemyShots > 48 do table.remove(CombatLogRuntime.RecentEnemyShots, 1) end

    if CombatLogState.NearMiss ~= true then return end

    local Radius = math.clamp(tonumber(CombatLogState.NearMissRadius) or 4, 0.5, 10)
    if MissDistance <= 0.22 or MissDistance > Radius then return end

    local Key = tostring(Player.UserId) .. ":" .. tostring(math.floor(Origin.X * 0.2)) .. ":" .. tostring(math.floor(Origin.Y * 0.2)) .. ":" .. tostring(math.floor(Origin.Z * 0.2))
    local Previous = CombatLogRuntime.RecentNearMissKeys[Key]
    if Previous and CurrentTime - Previous < 0.28 then return end

    if Previous == nil then CombatLogRuntime.RecentNearMissKeyCount = (tonumber(CombatLogRuntime.RecentNearMissKeyCount) or 0) + 1 end
    CombatLogRuntime.RecentNearMissKeys[Key] = CurrentTime
    if CombatLogRuntime.RecentNearMissKeyCount > 192 then CombatLogRuntime.MaintainRuntime(CurrentTime, true) end

    local Queue = CombatLogRuntime.NearMissQueue
    if #Queue >= (tonumber(CombatLogRuntime.NearMissQueueLimit) or 48) then table.remove(Queue, 1) end

    Queue[#Queue + 1] = {
        Due = CurrentTime + (tonumber(CombatLogRuntime.NearMissConfirmDelay) or 0.40),
        Time = CurrentTime, Player = Player, MissDistance = MissDistance, PartName = Part.Name, Shot = ShotEntry
    }
end

function CombatLogRuntime.IsEnemyShotVisualCandidate(Object)
    if not Object then return false end

    local Current = Object
    for _ = 1, 6 do
        if not Current or Current == workspace then break end

        local Name = string.lower(Current.Name)
        if string.find(Name, "bullet", 1, true) or string.find(Name, "tracer", 1, true)
            or string.find(Name, "projectile", 1, true) or string.find(Name, "gunshot", 1, true)
            or string.find(Name, "laser", 1, true)
        then
            return true
        end

        Current = Current.Parent
    end

    if Object:IsA("Beam") then
        local Attachment0, Attachment1 = Object.Attachment0, Object.Attachment1
        if not Attachment0 or not Attachment1 then return false end

        local Width = math.max(tonumber(Object.Width0) or 0, tonumber(Object.Width1) or 0) local SegmentLength = (Attachment1.WorldPosition - Attachment0.WorldPosition).Magnitude
        return Width <= 0.16 and SegmentLength >= 5
    end

    return false
end

function CombatLogRuntime.TrackEnemyShotObject(Object)
    if not Object or CombatLogRuntime.SeenEnemyShotObjects[Object] or CombatLogRuntime.IsOwnVisual(Object)
        or not CombatLogRuntime.IsEnemyShotVisualCandidate(Object)
    then
        return
    end

    local Entry
    if Object:IsA("Beam") then
        CombatLogRuntime.SeenEnemyShotObjects[Object] = true
        Entry = {Object = Object, IsBeam = true, Due = os.clock() + 0.035}
    elseif Object:IsA("BasePart") then
        CombatLogRuntime.SeenEnemyShotObjects[Object] = true
        Entry = {Object = Object, IsBeam = false, StartPosition = Object.Position, Due = os.clock() + 0.045}
    else
        return
    end

    local Queue = CombatLogRuntime.EnemyShotQueue
    if #Queue >= (tonumber(CombatLogRuntime.EnemyShotQueueLimit) or 96) then table.remove(Queue, 1) end
    Queue[#Queue + 1] = Entry
end

CombatLogRuntime.EnemyShotRoots = CombatLogRuntime.EnemyShotRoots or setmetatable({}, {__mode = "k"})
CombatLogRuntime.EnemyShotRootNames = CombatLogRuntime.EnemyShotRootNames or {
    Debris = true, Effects = true, Projectiles = true, Bullets = true, Tracers = true }

function CombatLogRuntime.BindEnemyShotRoot(Root)
    if not Root or CombatLogRuntime.EnemyShotRoots[Root] then return end
    local Connection = Root.DescendantAdded:Connect(function(Object)
        if Object:IsA("Beam") or Object:IsA("BasePart") then CombatLogRuntime.TrackEnemyShotObject(Object) end
    end)
    CombatLogRuntime.EnemyShotRoots[Root] = Connection
end

function CombatLogRuntime.RefreshEnemyShotTracking()
    local ShouldTrack = CombatLogState.Enabled == true and CombatLogState.NearMiss == true

    if ShouldTrack then
        for Name in pairs(CombatLogRuntime.EnemyShotRootNames) do
            CombatLogRuntime.BindEnemyShotRoot(workspace:FindFirstChild(Name))
        end

        if not CombatLogRuntime.EnemyShotConnection then
            CombatLogRuntime.EnemyShotConnection = workspace.ChildAdded:Connect(function(Object)
                if CombatLogRuntime.EnemyShotRootNames[Object.Name] then CombatLogRuntime.BindEnemyShotRoot(Object) end
            end)
            CombatLogRuntime.EnemyShotConnections[#CombatLogRuntime.EnemyShotConnections + 1] = CombatLogRuntime.EnemyShotConnection
        end
        return
    end

    for Root, Connection in pairs(CombatLogRuntime.EnemyShotRoots) do
        if Connection then Connection:Disconnect() end
        CombatLogRuntime.EnemyShotRoots[Root] = nil
    end
    if CombatLogRuntime.EnemyShotConnection then CombatLogRuntime.EnemyShotConnection:Disconnect() end
    CombatLogRuntime.EnemyShotConnection = nil
    table.clear(CombatLogRuntime.EnemyShotConnections)
    table.clear(CombatLogRuntime.EnemyShotQueue)
    table.clear(CombatLogRuntime.NearMissQueue)
    CombatLogRuntime.RecentNearMissKeys = {}
    CombatLogRuntime.RecentNearMissKeyCount = 0
end

function CombatLogRuntime.FindTaggedAttacker(Character, Humanoid)
    local Containers = { Character, Humanoid }

    local CharStats = ReplicatedStorage:FindFirstChild( "CharStats")

    if CharStats and LocalPlayer then Containers[ #Containers + 1 ] = CharStats:FindFirstChild( LocalPlayer.Name) end

    local Keywords = { "creator", "attacker", "damager", "damagefrom", "lastdamager", "lastattacker", "killer", "shooter", "source" }

    for _, Container in ipairs(Containers) do
        if Container then
            for _, Object in ipairs( Container:GetDescendants() ) do
                if Object:IsA("ObjectValue") and Object.Value then
                    local LowerName = string.lower( Object.Name)

                    local Matched = false

                    for _, Keyword in ipairs( Keywords ) do
                        if string.find( LowerName, Keyword, 1, true ) then
                            Matched = true
                            break
                        end
                    end

                    if Matched then
                        if Object.Value:IsA("Player") then
                            if Object.Value ~= LocalPlayer then return Object.Value end
                        else
                            local Player = CombatLogRuntime.ResolvePlayerFromObject( Object.Value)

                            if Player and Player ~= LocalPlayer then return Player end
                        end
                    end
                end
            end
        end
    end

    return nil
end

function CombatLogRuntime.GetRecentEnemyShot(MaximumAge, MaximumMissDistance)
    local CurrentTime = os.clock() local AgeLimit = math.clamp(tonumber(MaximumAge) or CombatLogRuntime.IncomingShotWindow or 0.45, 0.05, 1)
    local MissLimit = math.clamp(tonumber(MaximumMissDistance) or CombatLogRuntime.IncomingShotRadius or 1.20, 0.10, 5) local Best, BestAge

    for Index = #CombatLogRuntime.RecentEnemyShots, 1, -1 do
        local Shot = CombatLogRuntime.RecentEnemyShots[Index] local Age = Shot and CurrentTime - (tonumber(Shot.Time) or 0) or math.huge

        if not Shot or Age > 1 then
            table.remove(CombatLogRuntime.RecentEnemyShots, Index)
        elseif Age <= AgeLimit and Shot.Player and Shot.Player ~= LocalPlayer and typeof(Shot.Origin) == "Vector3"
            and typeof(Shot.EndPosition) == "Vector3" and (tonumber(Shot.MissDistance) or math.huge) <= MissLimit
        then
            if BestAge == nil or Age < BestAge then
                Best = Shot
                BestAge = Age
            end
        end
    end

    return Best
end

function CombatLogRuntime.LogIncomingDamage(Character, Humanoid, Damage)
    if CombatLogState.Enabled ~= true or CombatLogState.Incoming ~= true or not Damage or Damage <= 0 then return end

    local CurrentTime = os.clock() local TaggedAttacker = CombatLogRuntime.FindTaggedAttacker(Character, Humanoid)
    local RecentShot = CombatLogRuntime.GetRecentEnemyShot( CombatLogRuntime.IncomingShotWindow, CombatLogRuntime.IncomingShotRadius)

    if TaggedAttacker and RecentShot and RecentShot.Player ~= TaggedAttacker then RecentShot = nil end

    local LocalRoot = Character and Character:FindFirstChild("HumanoidRootPart")
    local TaggedCharacter = TaggedAttacker and ResolveTrackedCharacter(TaggedAttacker, TaggedAttacker.Character)
    local TaggedRoot = TaggedCharacter and TaggedCharacter:FindFirstChild("HumanoidRootPart")
    local TaggedDistance = LocalRoot and TaggedRoot and (LocalRoot.Position - TaggedRoot.Position).Magnitude or nil

    local TrustedTaggedMelee = TaggedAttacker ~= nil and TaggedDistance ~= nil and TaggedDistance <= math.max(tonumber(CombatLogRuntime.IncomingMeleeDistance) or 22, 1)

    local TrustedShot = RecentShot ~= nil
    if not TrustedShot and not TrustedTaggedMelee then return end

    local Attacker = TaggedAttacker or RecentShot and RecentShot.Player
    if not Attacker or Attacker == LocalPlayer then return end

    CombatLogRuntime.RecentDamageAt = CurrentTime
    if RecentShot then
        RecentShot.DamageConfirmed = true
        RecentShot.DamageConfirmedAt = CurrentTime
    end

    local AttackerCharacter = ResolveTrackedCharacter(Attacker, Attacker.Character)
    local AttackerRoot = AttackerCharacter and AttackerCharacter:FindFirstChild("HumanoidRootPart")
    local Distance = LocalRoot and AttackerRoot and (LocalRoot.Position - AttackerRoot.Position).Magnitude
        or LocalRoot and RecentShot and (LocalRoot.Position - RecentShot.Origin).Magnitude or nil

    local PartName = TrustedShot and RecentShot.Part and RecentShot.Part.Name or nil

    local RoundedDamage
    if math.abs(Damage - math.floor(Damage + 0.5)) <= 0.05 then
        RoundedDamage = math.max(math.floor(Damage + 0.5), 1)
    else
        RoundedDamage = math.max(math.floor(Damage * 10 + 0.5) / 10, 0.1)
    end

    local Message = "Damage taken: " .. tostring(RoundedDamage) .. " from [" .. CombatLogRuntime.GetDisplayName(Attacker) .. "]"

    local DetailParts = {}
    if PartName then DetailParts[#DetailParts + 1] = PartName end

    if TrustedShot then
        DetailParts[#DetailParts + 1] = "confirmed shot"
    elseif TrustedTaggedMelee then
        DetailParts[#DetailParts + 1] = "close damage"
    end

    local DistanceText = CombatLogRuntime.FormatDistance(Distance)
    if DistanceText then DetailParts[#DetailParts + 1] = DistanceText .. " studs" end

    CombatLogRuntime.Emit("Damage", Message, table.concat(DetailParts, "  •  "))
end

function CombatLogRuntime.BindLocalDamage(Character)
    if CombatLogRuntime.LocalDamageConnection then
        CombatLogRuntime.LocalDamageConnection:Disconnect()

        CombatLogRuntime.LocalDamageConnection = nil
    end

    CombatLogRuntime.LocalCharacter = Character

    local Humanoid = Character and ( Character:FindFirstChildOfClass( "Humanoid" ) or Character:WaitForChild( "Humanoid", 5 ))

    CombatLogRuntime.LocalHumanoid = Humanoid

    if not Humanoid then return end

    CombatLogRuntime.PreviousLocalHealth = Humanoid.Health
    CombatLogRuntime.DamageAccumulator = 0
    CombatLogRuntime.DamageAccumulatorVersion += 1
    CombatLogRuntime.DamageAccumulatorCharacter = Character
    CombatLogRuntime.DamageAccumulatorHumanoid = Humanoid

    CombatLogRuntime.LocalDamageConnection = Humanoid.HealthChanged:Connect(function(NewHealth)
        if CombatLogRuntime.LocalCharacter ~= Character then return end

        local PreviousHealth = CombatLogRuntime.PreviousLocalHealth
        CombatLogRuntime.PreviousLocalHealth = NewHealth
        if type(PreviousHealth) ~= "number" or type(NewHealth) ~= "number" then return end

        local Damage = PreviousHealth - NewHealth
        if Damage <= 0 then return end

        CombatLogRuntime.DamageAccumulator += Damage
        CombatLogRuntime.DamageAccumulatorCharacter = Character
        CombatLogRuntime.DamageAccumulatorHumanoid = Humanoid
        CombatLogRuntime.DamageAccumulatorVersion += 1
        local Version = CombatLogRuntime.DamageAccumulatorVersion

        task.delay(CombatLogRuntime.DamageAccumulatorWindow, function()
            if CombatLogRuntime.LocalCharacter ~= Character or CombatLogRuntime.DamageAccumulatorVersion ~= Version then return end
            local TotalDamage = CombatLogRuntime.DamageAccumulator CombatLogRuntime.DamageAccumulator = 0
            if TotalDamage > 0 then CombatLogRuntime.LogIncomingDamage(Character, Humanoid, TotalDamage) end
        end)
    end)
end

function CombatLogRuntime.ClassifyMiss(Shot)
    if type(Shot) ~= "table" or not Shot.Player then return "unconfirmed shot", nil end

    local Character, TargetPart = CombatLogRuntime.GetShotTargetPart( Shot)

    if not Character or not TargetPart then return "target lost", nil end

    local Origin = Shot.Origin

    local IntendedPosition = typeof(Shot.HitPosition) == "Vector3" and Shot.HitPosition or typeof( Shot.TargetPositionAtFire ) == "Vector3"
            and Shot.TargetPositionAtFire or TargetPart.Position

    local Distance = typeof(Origin) == "Vector3" and ( IntendedPosition - Origin ).Magnitude or nil

    local Range = CombatLogRuntime.GetWeaponRange( Shot.Tool)

    if Range and Distance and Distance > Range * 1.02 then return "distance", Distance end

    local Source = tostring(Shot.Source or "")
    local SilentShot = Source == "SilentAim" or Source == "SilentAimFallback" or Shot.SpreadBypassed == true
    local PredictedCenter = typeof(Shot.PredictedCenter) == "Vector3" and Shot.PredictedCenter or nil

    if Source == "RageBot" and PredictedCenter and typeof(Shot.DamageHitPosition) == "Vector3" and Shot.RouteOutsideHitbox ~= true then
        local PredictionError = (Shot.DamageHitPosition - PredictedCenter).Magnitude
        if PredictionError > math.max(TargetPart.Size.Magnitude * 0.72, 1.35) then return "prediction error", Distance end
    end

    if Source == "RageBot"
        and Shot.RouteValidAtFire == false
    then
        return
            "route invalid at fire",
            Distance
    end

    if Source ~= "RageBot" and not SilentShot and typeof(Origin) == "Vector3" and typeof(Shot.Direction) == "Vector3" then
        local IntendedDelta = IntendedPosition - Origin

        if IntendedDelta.Magnitude > 0.001 and Shot.Direction.Magnitude > 0.001 then
            local Dot = math.clamp( IntendedDelta.Unit:Dot( Shot.Direction.Unit ), -1, 1)

            local Angle = math.deg( math.acos( Dot ))

            local WeaponData = type(GetBulletTracerWeaponData)
                    == "function" and GetBulletTracerWeaponData( Shot.Tool ) or nil

            local Spread = WeaponData and tonumber(WeaponData.Spread) or 0

            local SpreadThreshold = math.max( Spread * 0.35, 0.55)

            if Angle > SpreadThreshold then return "spread", Distance end
        end
    end

    if typeof(Origin) == "Vector3" and typeof(IntendedPosition)
            == "Vector3" and Source ~= "RageBot" and not (SilentShot and Shot.Wallbang == true) then
        Ragebot.RefreshRaycastParameters(LocalPlayer)

        local Result = workspace:Raycast( Origin, IntendedPosition - Origin, Ragebot.RayParams)

        if Result and not Result.Instance:IsDescendantOf( Character ) then return "obstruction", Distance end
    end

    if Source == "RageBot" and Shot.PenetrationValidatedAtFire == true then
        local Safety = tonumber(Shot.WallbangSafety) or 0

        local Risk = tonumber(Shot.PenetrationRisk) or 0

        if Safety < 0.16 or Risk > 1.12 then return "penetration rejected", Distance end
    end

    if Source == "RageBot" then
        local DirectionChanges = tonumber(Shot.ResolverDirectionChanges) or 0

        local Jitter = tonumber(Shot.ResolverJitter) or 0

        local PredictionOffset = tonumber(Shot.ResolverPredictionOffset) or 0

        if DirectionChanges >= 2 or Jitter >= ResolverState.MaximumJitter * 0.88 then return "resolver jitter", Distance end

        if Distance and Distance >= 180 and PredictionOffset > 0.42 then return "prediction overshoot", Distance end
    end

    if Source == "RageBot"
        and Shot.AmmoConfirmed == true
        and Shot.SignalConfirmed == true
    then
        return
            "damage not confirmed",
            Distance
    end

    if Source == "RageBot"
        and Shot.AmmoConfirmed == true
        and Shot.RageRemoteSent == true
    then
        return
            "server hit not confirmed",
            Distance
    end

    if Shot.AmmoConfirmed == true
        and Shot.SignalConfirmed == true
    then
        return
            "damage not confirmed",
            Distance
    end

    if Source == "RageBot"
        and Shot.RageRemoteSent == true
    then
        return
            "server shot not confirmed",
            Distance
    end

    return "unconfirmed shot", Distance
end

function CombatLogRuntime.ScheduleMiss(Shot)
    if type(Shot) ~= "table" or Shot.MissScheduled then return end
    Shot.MissScheduled = true

    local TargetPosition = typeof(Shot.HitPosition) == "Vector3" and Shot.HitPosition
        or typeof(Shot.TargetPositionAtFire) == "Vector3" and Shot.TargetPositionAtFire or nil
    local Distance = typeof(Shot.Origin) == "Vector3" and typeof(TargetPosition) == "Vector3" and (TargetPosition - Shot.Origin).Magnitude or 0
    local DistanceGrace = Distance >= 1200 and 1.15 or Distance >= 800 and 0.90 or Distance >= 500 and 0.70
        or Distance >= 350 and 0.55 or Distance >= 250 and 0.38 or Distance >= 150 and 0.20 or 0
    local DamageWindow = tonumber(AttackConfirmationState.DamageWindow) or 2.25
    local ResolveAt = math.max(tonumber(CombatLogState.ResolveDelay) or 1.55, DamageWindow + 0.35 + DistanceGrace)

    task.delay(ResolveAt, function()
        if Shot.DamageConfirmed == true or Shot.MissLogged == true or not Shot.Player then return end

        local StrongFireEvidence = Shot.SignalConfirmed == true or Shot.RageRemoteSent == true
            or Shot.RemoteConfirmedAt ~= nil or Shot.Token ~= nil and tostring(Shot.Source or "") == "RageBot"
        if not StrongFireEvidence then return end

        local Reason local ShotDistance

        if Shot.AmmoConfirmed == true then
            Reason, ShotDistance = CombatLogRuntime.ClassifyMiss(Shot)
            if Ragebot and type(Ragebot.FinalizeValidationShot) == "function" then Ragebot.FinalizeValidationShot(Shot, false, nil, Reason) end
        else
            Reason = "ammo not consumed"
            ShotDistance = Distance
            if Ragebot and type(Ragebot.FinalizeValidationShot) == "function" then Ragebot.FinalizeValidationShot(Shot, nil, nil, Reason) end
        end

        if CombatLogState.Enabled ~= true or CombatLogState.Misses ~= true or Shot.AmmoConfirmed ~= true then return end

        Shot.MissLogged = true

        local DetailParts = {CombatLogRuntime.GetShotSourceName(Shot)}
        local DistanceText = CombatLogRuntime.FormatDistance(ShotDistance)
        if DistanceText then DetailParts[#DetailParts + 1] = DistanceText .. " studs" end

        if Ragebot and type(Ragebot.GetValidationLogDetail) == "function" then
            local ValidationDetail = Ragebot.GetValidationLogDetail(Shot)
            if ValidationDetail then DetailParts[#DetailParts + 1] = ValidationDetail end
        end

        CombatLogRuntime.Emit("Miss", "Miss due to " .. tostring(Reason), table.concat(DetailParts, "  •  "))
    end)
end

function Internal.CleanupAttackConfirmations()
    local CurrentTime = os.clock()
    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index] local Expired = not Shot or CurrentTime - (Shot.Time or 0) > AttackConfirmationState.Window
        local Completed = Shot and Shot.DamageConfirmed and CurrentTime - (Shot.ConfirmedAt or Shot.Time or 0) > AttackConfirmationState.MergeWindow
        if Expired or Completed then table.remove(AttackConfirmationState.Shots, Index) end
    end
    while #AttackConfirmationState.Shots > AttackConfirmationState.MaximumShots do table.remove(AttackConfirmationState.Shots, 1) end
end

function Internal.ResolveLocalAttackTarget(TargetCharacter, TargetPart)
    TargetCharacter = TargetCharacter or Internal.GetHumanoidCharacterFromPart(TargetPart)
    local TargetPlayer = Internal.GetPlayerFromTrackedCharacter(TargetCharacter)
    if not TargetPlayer or TargetPlayer == LocalPlayer or not TargetCharacter then return nil, nil, nil, nil end
    local ResolvedCharacter = ResolveTrackedCharacter(TargetPlayer, TargetCharacter)
    if ResolvedCharacter then TargetCharacter = ResolvedCharacter end
    local PartName = TargetPart and TargetPart.Name or nil
    if TargetPart and not TargetPart:IsDescendantOf(TargetCharacter) then TargetPart = PartName and TargetCharacter:FindFirstChild(PartName, true) or nil end
    if not TargetPart then TargetPart = TargetCharacter:FindFirstChild("HumanoidRootPart") or TargetCharacter:FindFirstChild("Head") or TargetCharacter.PrimaryPart end
    if not TargetPart or not TargetPart:IsA("BasePart") then return TargetPlayer, TargetCharacter, nil, PartName end
    return TargetPlayer, TargetCharacter, TargetPart, TargetPart.Name
end

local IsVerifiedLocalFirearmTool

function Internal.GetAtramentaDownedObject(Player)
    if not Player then return nil end

    local CharStats = ReplicatedStorage:FindFirstChild( "CharStats")

    local Stats = CharStats and CharStats:FindFirstChild( Player.Name)

    return Stats and Stats:FindFirstChild( "Downed" ) or nil
end

function Internal.IsAtramentaPlayerActuallyDowned(Player)
    local Downed = Internal.GetAtramentaDownedObject( Player)

    return Downed ~= nil and Downed.Value == true
end

local IsAtramentaFinishedTarget local ConfirmAtramentaFinishSound local WatchAtramentaFinishSound

function Internal.GetLocalAttackSourcePriority(Source)
    Source = tostring(Source or "")
    if Source == "RageBot" then return 100 end
    if Source == "SilentAim" then return 90 end
    if Source == "SilentAimFallback" or Source == "Silent Aim" then return 85 end
    if Source == "Aimbot" then return 80 end
    if Source == "Manual" then return 60 end
    if Source == "Remote" then return 50 end
    if Source == "ActivationFallback" then return 40 end
    if Source == "Local" then return 30 end
    return Source ~= "" and 20 or 0
end

function Internal.MergeLocalAttackSource(CurrentSource, IncomingSource)
    if IncomingSource == nil then return CurrentSource end
    if CurrentSource == nil then return IncomingSource end
    if Internal.GetLocalAttackSourcePriority(IncomingSource) >= Internal.GetLocalAttackSourcePriority(CurrentSource) then return IncomingSource end
    return CurrentSource
end

function Internal.RegisterLocalAttack(TargetCharacter, TargetPart, ShotToken, Tool, Source, OriginPosition, Direction)
    if not Tool or not Tool:IsA("Tool") or type(IsVerifiedLocalFirearmTool) ~= "function" or not IsVerifiedLocalFirearmTool(Tool) then return nil end

    local Values = Tool:FindFirstChild("Values") local ServerAmmo = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    if ServerAmmo and typeof(ServerAmmo.Value) == "number" and ServerAmmo.Value <= 0 then return nil end

    local TargetPlayer, ResolvedCharacter, ResolvedPart, PartName = Internal.ResolveLocalAttackTarget(TargetCharacter, TargetPart)
    Internal.CleanupAttackConfirmations()

    local CurrentTime = os.clock()
    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Existing = AttackConfirmationState.Shots[Index]
        if Existing and Existing.VerifiedFire then
            local Age = CurrentTime - (Existing.Time or 0) local SameToken = ShotToken ~= nil and Existing.Token ~= nil and tostring(Existing.Token) == tostring(ShotToken)
            local TargetCompatible = not TargetPlayer or not Existing.Player or Existing.Player == TargetPlayer local DirectionCompatible = true

            if typeof(Direction) == "Vector3" and Direction.Magnitude > 0.001 and typeof(Existing.Direction) == "Vector3" and Existing.Direction.Magnitude > 0.001 then
                DirectionCompatible = Direction.Unit:Dot(Existing.Direction.Unit) >= 0.985
            end

            local FallbackMerge = Existing.Tool == Tool and Age <= 0.075 and (Existing.Token == nil or ShotToken == nil) and TargetCompatible and DirectionCompatible

            if SameToken or FallbackMerge then
                Existing.Time = CurrentTime
                Existing.Token = ShotToken or Existing.Token
                Existing.Source = Internal.MergeLocalAttackSource(Existing.Source, Source)
                Existing.Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or Existing.Origin
                Existing.Direction = typeof(Direction) == "Vector3" and Direction or Existing.Direction

                if TargetPlayer and ResolvedCharacter then
                    Existing.Player = TargetPlayer
                    Existing.Character = ResolvedCharacter
                    Existing.TargetPart = ResolvedPart or Existing.TargetPart
                    Existing.TargetPositionAtFire = ResolvedPart and ResolvedPart.Position or Existing.TargetPositionAtFire
                    Existing.TargetVelocityAtFire = ResolvedPart and ResolvedPart.AssemblyLinearVelocity or Existing.TargetVelocityAtFire
                    Existing.PartName = Existing.PartName == "Head" and "Head" or PartName

                    if Internal.IsAtramentaPlayerActuallyDowned(TargetPlayer) then Existing.TargetWasDowned = true end
                end

                if type(Internal.TryConfirmBufferedDamage) == "function" then Internal.TryConfirmBufferedDamage(Existing) end
                return Existing
            end
        end
    end

    local Shot = {
        Time = CurrentTime, Player = TargetPlayer, Character = ResolvedCharacter, TargetPart = ResolvedPart, PartName = PartName,
        TargetPositionAtFire = ResolvedPart and ResolvedPart.Position or nil,
        TargetVelocityAtFire = ResolvedPart and ResolvedPart.AssemblyLinearVelocity or nil,
        Token = ShotToken, Tool = Tool, Source = Source or "Manual",
        Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or nil,
        Direction = typeof(Direction) == "Vector3" and Direction or nil,
        AmmoAtFire = ServerAmmo and tonumber(ServerAmmo.Value) or nil, VerifiedFire = true,
        TargetWasDowned = TargetPlayer and Internal.IsAtramentaPlayerActuallyDowned(TargetPlayer) or false,
        FinishSoundPlayed = false, ConfirmedAt = nil, SignalConfirmed = false, AmmoConfirmed = false,
        DamageConfirmed = false, TracerSpawned = false
    }

    AttackConfirmationState.Shots[#AttackConfirmationState.Shots + 1] = Shot
    CombatLogRuntime.ScheduleMiss(Shot)
    if type(Internal.TryConfirmBufferedDamage) == "function" then Internal.TryConfirmBufferedDamage(Shot) end
    return Shot
end

function Internal.AttachAttackTarget(Shot, TargetCharacter, TargetPart)
    if not Shot or not Shot.VerifiedFire then return false end
    local TargetPlayer, ResolvedCharacter, ResolvedPart, PartName = Internal.ResolveLocalAttackTarget(TargetCharacter, TargetPart)
    if not TargetPlayer or not ResolvedCharacter then return false end
    Shot.Player = TargetPlayer
    Shot.Character = ResolvedCharacter
    Shot.TargetPart = ResolvedPart
    Shot.TargetPositionAtFire = ResolvedPart and ResolvedPart.Position or Shot.TargetPositionAtFire
    Shot.TargetVelocityAtFire = ResolvedPart and ResolvedPart.AssemblyLinearVelocity or Shot.TargetVelocityAtFire
    Shot.PartName = Shot.PartName == "Head" and "Head" or PartName

    if Internal.IsAtramentaPlayerActuallyDowned( TargetPlayer ) then Shot.TargetWasDowned = true end
    if type(Internal.TryConfirmBufferedDamage) == "function" then Internal.TryConfirmBufferedDamage(Shot) end

    return true
end

function Internal.IsSilentTrackedShot(Shot)
    if type(Shot) ~= "table" then return false end
    local Source = tostring(Shot.Source or "")
    return Source == "SilentAim" or Source == "SilentAimFallback" or Source == "Silent Aim"
end

function Internal.GetShotDamageWindow(Shot)
    local DefaultWindow = tonumber(AttackConfirmationState.DamageWindow) or 2.25
    if not Internal.IsSilentTrackedShot(Shot) then return DefaultWindow end
    local Travel = math.max(tonumber(Shot.ProjectileTravelTime) or 0, 0)
    return math.clamp(math.max(0.48, Travel + 0.38), 0.48, 1.65)
end

function Internal.CanConfirmShotDamage(Shot, CurrentTime)
    if type(Shot) ~= "table" or Shot.VerifiedFire ~= true or Shot.DamageConfirmed == true then return false end
    CurrentTime = tonumber(CurrentTime) or os.clock()
    local Age = CurrentTime - (tonumber(Shot.Time) or CurrentTime)
    if Age < -0.08 or Age > Internal.GetShotDamageWindow(Shot) then return false end
    if not Internal.IsSilentTrackedShot(Shot) then return true end
    if Shot.PacketRewritten ~= true then return false end
    if Shot.RemoteConfirmed ~= true then return false end
    if Shot.AmmoConfirmed ~= true then return false end
    if Shot.Projectile == true then return true end
    if Shot.DamagePacketSent ~= true then return false end
    local SentAt = tonumber(Shot.DamagePacketSentAt) or tonumber(Shot.Time) or CurrentTime
    return CurrentTime - SentAt >= -0.08 and CurrentTime - SentAt <= 0.72
end

function Internal.FindAttackConfirmation(Character)
    Internal.CleanupAttackConfirmations()
    local CurrentTime = os.clock() local TargetPlayer = Internal.GetPlayerFromTrackedCharacter(Character) local BestShot, BestScore = nil, -math.huge

    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index] local MatchesTarget = Shot and (Shot.Character == Character or TargetPlayer and Shot.Player == TargetPlayer)
        if Shot and Shot.VerifiedFire and not Shot.DamageConfirmed and MatchesTarget then
            local Age = CurrentTime - (Shot.Time or 0)
            if Internal.CanConfirmShotDamage(Shot, CurrentTime) then
                local Score = -Age * 12
                if Shot.SignalConfirmed == true then Score += 4 end
                if Shot.AmmoConfirmed == true then Score += 3 end
                if Shot.RemoteConfirmedAt ~= nil then Score += 1.5 end
                if tostring(Shot.Source or "") == "RageBot" then Score += 1 end
                if Shot.Token ~= nil then Score += 0.5 end
                if Score > BestScore then BestScore, BestShot = Score, Shot end
            end
        end
    end

    if BestShot then BestShot.ConfirmedAt = CurrentTime end
    return BestShot
end

function Internal.GetActiveConfirmedCombatTarget()
    if Ragebot.Enabled and Ragebot.CurrentTarget then return Ragebot.CurrentTarget end
    local AimBot = Configuration and Configuration.AimBot
    if AimBot and AimBot.Enabled then return AimBot.CurrentTarget or AimBot.AimbotLockedTarget or AimBot.SilentAimLockedTarget end
    return nil
end

function Internal.FindTargetAwareAttackConfirmation(Player, Character)
    local Exact = Internal.FindAttackConfirmation(Character)
    if Exact then return Exact end

    Internal.CleanupAttackConfirmations()
    local CurrentTime = os.clock() local ActiveTarget = Internal.GetActiveConfirmedCombatTarget()

    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index]

        if Shot and Shot.VerifiedFire and not Shot.DamageConfirmed and Internal.CanConfirmShotDamage(Shot, CurrentTime) then
            local Source = tostring(Shot.Source or "") local TargetMatches = Shot.Player == Player or Shot.Character == Character
            local HasNoResolvedTarget = Shot.Player == nil and Shot.Character == nil
            local StrongFireEvidence = Shot.AmmoConfirmed == true or Shot.SignalConfirmed == true or Shot.Token ~= nil or Source == "Remote" or Source == "RageBot"

            local TargetedAssistShot = HasNoResolvedTarget and ActiveTarget == Player
                and (Source == "RageBot" or Source == "Aimbot" or Source == "SilentAim" or Source == "SilentAimFallback")
            local ManualFallbackShot = HasNoResolvedTarget and (Source == "Manual" or Source == "Remote" or Source == "ActivationFallback" or Source == "Local")
                and Shot.SignalConfirmed == true and Shot.Token ~= nil and CurrentTime - (Shot.Time or 0) <= math.min(AttackConfirmationState.SignalWindow, 0.55)

            if StrongFireEvidence and (TargetMatches or TargetedAssistShot or ManualFallbackShot) then
                Shot.Player = Player
                Shot.Character = Character
                Shot.PartName = Shot.PartName or (Ragebot.Settings.TargetPart or "Head")
                Shot.ConfirmedAt = CurrentTime
                return Shot
            end
        end
    end

    return nil
end

function Internal.ConfirmMergedRageShots(PrimaryShot, Player, Character)
    if not PrimaryShot or tostring(PrimaryShot.Source or "") ~= "RageBot" then return 0 end
    local PrimaryTime = tonumber(PrimaryShot.Time) or 0 local CurrentTime = os.clock() local Confirmed = 0

    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index]
        if Shot and Shot ~= PrimaryShot and not Shot.DamageConfirmed and tostring(Shot.Source or "") == "RageBot"
            and Shot.AmmoConfirmed == true and Shot.SignalConfirmed == true and (Shot.Player == Player or Shot.Character == Character) then
            local ShotTime = tonumber(Shot.Time) or 0
            if math.abs(ShotTime - PrimaryTime) <= AttackConfirmationState.MergeWindow and CurrentTime - ShotTime <= AttackConfirmationState.DamageWindow
            then
                Shot.DamageConfirmed = true
                Shot.ConfirmedAt = CurrentTime
                Shot.MergedDamageConfirmation = true

                if Ragebot and type(Ragebot.FinalizeValidationShot) == "function" then Ragebot.FinalizeValidationShot(Shot, nil, nil, "MergedDamage") end

                Confirmed += 1
            end
        end
    end

    return Confirmed
end

function Internal.GetHitFeedbackGuiParent()
    local CurrentPlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:FindFirstChild("PlayerGui") or PlayerGui
    if CurrentPlayerGui and CurrentPlayerGui.Parent then return CurrentPlayerGui end
    if type(gethui) == "function" then
        local Success, HiddenUi = Internal.Call(gethui)
        if Success and HiddenUi then return HiddenUi end
    end
    return nil
end

function GetBulletTracerWeaponData(Tool)
    if not Tool or not Tool:IsA("Tool") then return nil end

    local Cached = HitFeedbackRuntimeState.BulletTracerWeaponCache[Tool]
    if Cached and Cached.Tool == Tool and Tool.Parent then return Cached end

    local Values = Tool:FindFirstChild("Values") local AmmoValue = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    local StoredAmmo = Values and (Values:FindFirstChild("SERVER_StoredAmmo") or Values:FindFirstChild("StoredAmmo"))
    local HasAmmo = AmmoValue and (AmmoValue:IsA("IntValue") or AmmoValue:IsA("NumberValue"))
    local HasStoredAmmo = StoredAmmo and (StoredAmmo:IsA("IntValue") or StoredAmmo:IsA("NumberValue"))

    if not HasAmmo then
        for _, Object in ipairs(Tool:GetDescendants()) do
            if (Object.Name == "Ammo" or Object.Name == "SERVER_Ammo") and (Object:IsA("IntValue") or Object:IsA("NumberValue")) then
                AmmoValue = Object
                HasAmmo = true
                break
            end
        end
    end

    local Config = nil local ConfigModule = Tool:FindFirstChild("Config", true)

    if ConfigModule and ConfigModule:IsA("ModuleScript") then
        local Success, Result = Internal.Call(require, ConfigModule)
        if Success and type(Result) == "table" then Config = Result end
    end

    if not Config then
        for _, Object in ipairs(Tool:GetDescendants()) do
            if Object:IsA("ModuleScript") and (Object.Name == "WeaponConfig" or Object.Name == "GunConfig") then
                local Success, Result = Internal.Call(require, Object)
                if Success and type(Result) == "table" then
                    Config = Result
                    break
                end
            end
        end
    end

    local MagSize = Config and tonumber(rawget(Config, "MagSize")) or nil local FireRate = Config and tonumber(rawget(Config, "FireRate")) or nil
    local Spread = Config and tonumber(rawget(Config, "Spread")) or nil local Recoil = Config and tonumber(rawget(Config, "Recoil")) or nil
    local Damage = Config and tonumber(rawget(Config, "Damage")) or nil local Range = Config and tonumber(rawget(Config, "Range")) or nil
    local BulletsPerShot = Config and tonumber(rawget(Config, "BulletsPerShot")) or nil
    local HasGunScript = Tool:FindFirstChild("Client", true) ~= nil or Tool:FindFirstChildWhichIsA("LocalScript", true) ~= nil
        or Tool:FindFirstChildWhichIsA("ModuleScript", true) ~= nil

    local HasHitmarker = Tool:FindFirstChild("Hitmarker", true) ~= nil

    local ConfigFirearm = MagSize and MagSize > 0 and FireRate and FireRate > 0 and (Spread ~= nil or Recoil ~= nil) and (HasAmmo or HasGunScript or HasHitmarker)

    local FallbackFirearm = HasAmmo and (HasStoredAmmo or HasGunScript or HasHitmarker)
    if not ConfigFirearm and not FallbackFirearm then return nil end

    local Data = { Tool = Tool, Config = Config, Ammo = AmmoValue, StoredAmmo = StoredAmmo, MagSize = MagSize, FireRate = FireRate, Spread = Spread,
        Recoil = Recoil, Damage = Damage, Range = Range, BulletsPerShot = BulletsPerShot, HasConfigSignature = ConfigFirearm == true }

    HitFeedbackRuntimeState.BulletTracerWeaponCache[Tool] = Data
    return Data
end

function Internal.IsBulletTracerWeapon(Tool)
    return GetBulletTracerWeaponData(Tool) ~= nil
end

IsVerifiedLocalFirearmTool = function(Tool)
    local Character = LocalPlayer.Character
    if Tool == nil or not Tool:IsA("Tool") or Character == nil or Tool.Parent ~= Character then return false end
    if Internal.IsBulletTracerWeapon(Tool) then return true end
    local Values = Tool:FindFirstChild("Values") local Ammo = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    return Ammo ~= nil or Tool:FindFirstChild("Hitmarker", true) ~= nil
end

function Internal.IsLocalGunShotRemote(Remote)
    return typeof(Remote) == "Instance" and Remote:IsA("RemoteEvent") and Remote.Name == "GNX_S" and Remote:IsDescendantOf(ReplicatedStorage)
end

function Internal.GetBulletTracerMuzzle(Tool)
    local Cached = HitFeedbackRuntimeState.BulletTracerMuzzleCache[Tool]
    if Cached and Cached.Parent and Cached:IsDescendantOf(Tool) then return Cached end
    local BestObject = nil local BestScore = -math.huge
    for Unused, Object in ipairs(Tool:GetDescendants()) do
        if Object:IsA("Attachment") or Object:IsA("BasePart") then
            local Name = string.lower(Object.Name) local Score = 0
            if string.find(Name, "muzzle", 1, true) then Score = Score + 100 end
            if string.find(Name, "firepoint", 1, true) or string.find(Name, "fire_point", 1, true) then Score = Score + 85 end
            if string.find(Name, "barrel", 1, true) then Score = Score + 65 end
            if string.find(Name, "tip", 1, true) then Score = Score + 45 end
            if Object:IsA("Attachment") then Score = Score + 15 end
            if Object.Name == "Handle" then Score = math.max(Score, 10) end
            if Score > BestScore then
                BestScore = Score
                BestObject = Object
            end
        end
    end
    HitFeedbackRuntimeState.BulletTracerMuzzleCache[Tool] = BestObject
    return BestObject
end

function Internal.GetBulletTracerOrigin(Tool)
    local Muzzle = Internal.GetBulletTracerMuzzle(Tool)
    if Muzzle then
        if Muzzle:IsA("Attachment") then return Muzzle.WorldPosition end
        if Muzzle:IsA("BasePart") then return Muzzle.Position end
    end
    local CameraObject = Internal.GetCamera()
    if CameraObject then return CameraObject.CFrame.Position end
    local Character = LocalPlayer.Character local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
    return RootPart and RootPart.Position or nil
end

function Internal.GetBulletTracerVisualOrigin(Tool, PacketOrigin)
    local MuzzleOrigin = Tool and Internal.GetBulletTracerOrigin(Tool) or nil

    if typeof(MuzzleOrigin) == "Vector3" then return MuzzleOrigin end

    if typeof(PacketOrigin) == "Vector3" then return PacketOrigin end

    local CameraObject = Internal.GetCamera()

    if CameraObject then return CameraObject.CFrame.Position end

    local Character = LocalPlayer.Character

    local RootPart = Character and Character:FindFirstChild( "HumanoidRootPart")

    return RootPart and RootPart.Position or nil
end

function Internal.ShouldSpawnBulletTracerToken(Tool, ShotToken)
    local CurrentTime = os.clock()
    if ShotToken == nil then return ShouldSpawnBulletTracer(Tool, 0.018) end

    local Cache = HitFeedbackRuntimeState.BulletTracerTokenCache local LastRebuild = tonumber(HitFeedbackRuntimeState.BulletTracerTokenCacheRebuild) or 0
    local Count = tonumber(HitFeedbackRuntimeState.BulletTracerTokenCacheCount) or 0

    if CurrentTime - LastRebuild >= 2.5 or Count >= 256 then
        local Fresh = {}
        local FreshCount = 0
        for Key, Time in pairs(Cache) do
            if CurrentTime - (tonumber(Time) or 0) < 0.55 then
                Fresh[Key] = Time
                FreshCount += 1
            end
        end
        Cache = Fresh
        HitFeedbackRuntimeState.BulletTracerTokenCache = Fresh
        HitFeedbackRuntimeState.BulletTracerTokenCacheCount = FreshCount
        HitFeedbackRuntimeState.BulletTracerTokenCacheRebuild = CurrentTime
        Count = FreshCount
    end

    local Key = tostring(ShotToken) local Previous = Cache[Key] or 0
    if CurrentTime - Previous < 0.55 then return false end

    if Cache[Key] == nil then HitFeedbackRuntimeState.BulletTracerTokenCacheCount = Count + 1 end
    Cache[Key] = CurrentTime
    return true
end

function Internal.ResolveBulletTracerExactTarget(Tool, PacketOrigin, Direction, ShotToken)
    local Pending = Ragebot.Runtime and Ragebot.Runtime.PendingShot or nil

    if type(Pending) == "table" and ShotToken ~= nil and tostring(Pending.ShotId)
            == tostring(ShotToken) and typeof(Pending.HitPosition)
            == "Vector3" then
        return Pending.HitPosition
    end

    local Reported = Ragebot and Ragebot.ReportedShots and ShotToken ~= nil and Ragebot.ReportedShots[ ShotToken ] or nil

    if type(Reported) == "table" and typeof(Reported.HitPosition)
            == "Vector3" then
        return Reported.HitPosition
    end

    if typeof(PacketOrigin) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude <= 0.001 then return nil end

    return GetBulletTracerTargetFromDirection( PacketOrigin, Direction, Tool)
end

function Internal.GetBulletTracerTarget(OriginPosition, Tool)
    if not OriginPosition then return nil end
    local AimPosition = nil
    if Mouse then
        local Success, MouseHit = Internal.Call(function() return Mouse.Hit end)
        if Success and MouseHit then AimPosition = MouseHit.Position end
    end
    local CameraObject = Internal.GetCamera()
    if not AimPosition and CameraObject then
        local MousePosition = UserInputService:GetMouseLocation() local Ray = CameraObject:ViewportPointToRay(MousePosition.X, MousePosition.Y)
        AimPosition = Ray.Origin + Ray.Direction * AttackConfirmationState.ShotRange
    end
    if not AimPosition then return nil end
    local Difference = AimPosition - OriginPosition
    if Difference.Magnitude < 0.1 then return nil end
    local MaximumDistance = math.min(Difference.Magnitude, AttackConfirmationState.ShotRange) local RaycastParameters = RaycastParams.new()
    RaycastParameters.FilterType = Enum.RaycastFilterType.Exclude
    RaycastParameters.IgnoreWater = true
    local Excluded = {}
    if LocalPlayer.Character then Excluded[#Excluded + 1] = LocalPlayer.Character end
    if Tool then Excluded[#Excluded + 1] = Tool end
    RaycastParameters.FilterDescendantsInstances = Excluded
    local Result = workspace:Raycast(OriginPosition, Difference.Unit * MaximumDistance, RaycastParameters)
    return Result and Result.Position or OriginPosition + Difference.Unit * MaximumDistance
end

function Internal.CreateBulletTracerBeam(Parent, StartAttachment, EndAttachment, Name, Width, Transparency, Color, Texture, TextureSpeed, CurveSize)
    local Beam = Instance.new("Beam")
    Beam.Name = Name
    Beam.Attachment0 = StartAttachment
    Beam.Attachment1 = EndAttachment
    Beam.FaceCamera = true
    Beam.Enabled = true
    Beam.Segments = 4
    Beam.Width0 = Width
    Beam.Width1 = Width
    Beam.LightEmission = 1
    Beam.LightInfluence = 0
    Beam.Color = ColorSequence.new(Color)
    Beam.Transparency = NumberSequence.new(Transparency)
    Beam.CurveSize0 = CurveSize or 0
    Beam.CurveSize1 = -(CurveSize or 0)

    if Texture then
        Beam.Texture = Texture
        Beam.TextureMode = Enum.TextureMode.Wrap
        Beam.TextureLength = 0.82
        Beam.TextureSpeed = TextureSpeed or 0
    end

    Beam.Parent = Parent
    return Beam
end

function HitFeedbackRuntimeState.ConfigureTracerImpact(Attachment, Name, Color, Width, Duration, Rate, SuppressImpact)
    if not Attachment or not Attachment.Parent or SuppressImpact == true or Rate <= 0 then return nil end

    local Emitter = Instance.new("ParticleEmitter")
    Emitter.Name = Name
    Emitter.Enabled = false
    Emitter.Rate = 0
    Emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"

    local Bright = Color:Lerp(Color3.new(1, 1, 1), 0.55)
    Emitter.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Bright), ColorSequenceKeypoint.new(0.42, Color),
        ColorSequenceKeypoint.new(1, Color) })

    Emitter.LightEmission = 1
    Emitter.LightInfluence = 0
    Emitter.Lifetime = NumberRange.new(math.min(Duration * 0.22, 0.09), math.min(Duration * 0.58, 0.22))
    Emitter.Speed = NumberRange.new(2.1, 5.4)
    Emitter.Drag = 5.5
    Emitter.SpreadAngle = Vector2.new(180, 180)
    Emitter.Rotation = NumberRange.new(0, 360)
    Emitter.RotSpeed = NumberRange.new(-210, 210)
    Emitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, Width * 2.7), NumberSequenceKeypoint.new(0.28, Width * 1.45),
        NumberSequenceKeypoint.new(1, 0) })
    Emitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.04), NumberSequenceKeypoint.new(0.32, 0.18),
        NumberSequenceKeypoint.new(1, 1) })
    Emitter.Parent = Attachment
    Emitter:Emit(math.clamp(math.floor(Rate * 0.18 + 0.5), 1, 10))
    return Emitter
end

function HitFeedbackRuntimeState.GetBulletTracerLightningBasis(Direction)
    local Unit = Direction.Unit local Reference = math.abs(Unit.Y) < 0.92 and Vector3.new(0, 1, 0) or Vector3.new(1, 0, 0) local Right = Unit:Cross(Reference)
    if Right.Magnitude <= 0.001 then Right = Unit:Cross(Vector3.new(0, 0, 1)) end
    Right = Right.Magnitude > 0.001 and Right.Unit or Vector3.new(1, 0, 0)
    local Up = Right:Cross(Unit)
    Up = Up.Magnitude > 0.001 and Up.Unit or Vector3.new(0, 1, 0)
    return Unit, Right, Up
end

function HitFeedbackRuntimeState.CreateLightningTracerSegment(Parent, StartAttachment, EndAttachment, Width, Color, Glow)
    local GlowBeam = Internal.CreateBulletTracerBeam( Parent, StartAttachment, EndAttachment, "LightningGlow", Width * (1.72 + Glow * 0.23),
        math.clamp(0.64 - Glow * 0.025, 0.42, 0.68), Color, nil, 0, 0)

    GlowBeam.Segments = 1
    GlowBeam.Width0 = GlowBeam.Width0 * 0.82
    GlowBeam.Width1 = GlowBeam.Width1 * 0.68
    GlowBeam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.72),
        NumberSequenceKeypoint.new(0.18, math.clamp(0.57 - Glow * 0.022, 0.36, 0.62)),
        NumberSequenceKeypoint.new(0.82, math.clamp(0.57 - Glow * 0.022, 0.36, 0.62)), NumberSequenceKeypoint.new(1, 0.76) })

    local CoreColor = Color:Lerp(Color3.new(1, 1, 1), 0.68)
    local CoreBeam = Internal.CreateBulletTracerBeam( Parent, StartAttachment, EndAttachment, "LightningCore", math.max(Width * 0.31, 0.010), 0.08, CoreColor,
        nil, 0, 0)

    CoreBeam.Segments = 1
    CoreBeam.Width0 = CoreBeam.Width0 * 0.88
    CoreBeam.Width1 = CoreBeam.Width1 * 0.68
    CoreBeam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.22), NumberSequenceKeypoint.new(0.12, 0.04),
        NumberSequenceKeypoint.new(0.88, 0.05), NumberSequenceKeypoint.new(1, 0.30) })

    local SoftColor = Color:Lerp(Color3.new(1, 1, 1), 0.20)
    GlowBeam.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, SoftColor), ColorSequenceKeypoint.new(0.50, Color),
        ColorSequenceKeypoint.new(1, SoftColor) })

    return GlowBeam, CoreBeam
end

function HitFeedbackRuntimeState.SpawnLightningBulletTracer(OriginPosition, TargetPosition, Tool, SuppressImpact)
    local Delta = TargetPosition - OriginPosition
    if Delta.Magnitude < 0.5 then return false end

    local Terrain = workspace:FindFirstChildOfClass("Terrain")
    if not Terrain then return false end

    local Color = HitFeedbackState.BulletTracerColor
    local Duration = math.clamp(tonumber(HitFeedbackState.BulletTracerTime) or 0.32, 0.05, 2)
    local ImpactWidth = math.clamp(tonumber(HitFeedbackState.BulletTracerWidth) or 0.10, 0.01, 0.5)
    local Rate = math.clamp(tonumber(HitFeedbackState.BulletTracerRate) or 18, 0, 40)

    local StartAttachment = Instance.new("Attachment")
    StartAttachment.Name = "AtramentaBulletTracerLightningStart"
    StartAttachment.WorldPosition = OriginPosition
    StartAttachment.Parent = Terrain

    local EndAttachment = Instance.new("Attachment")
    EndAttachment.Name = "AtramentaBulletTracerLightningEnd"
    EndAttachment.WorldPosition = TargetPosition
    EndAttachment.Parent = Terrain

    HitFeedbackRuntimeState.ActiveObjects[StartAttachment] = true
    HitFeedbackRuntimeState.ActiveObjects[EndAttachment] = true

    local Beam = Instance.new("Beam")
    Beam.Name = "Lightning"
    Beam.Attachment0 = StartAttachment
    Beam.Attachment1 = EndAttachment
    Beam.Texture = "rbxassetid://7151778302"
    Beam.Brightness = 1.5
    Beam.Transparency = NumberSequence.new(0.45)
    Beam.LightEmission = 1
    Beam.LightInfluence = 0
    Beam.Segments = 10
    Beam.TextureLength = 1
    Beam.TextureMode = Enum.TextureMode.Stretch
    Beam.TextureSpeed = 1
    Beam.Width0 = 1.2
    Beam.Width1 = 1.2
    Beam.FaceCamera = true
    Beam.Color = ColorSequence.new(Color)
    Beam.Enabled = true
    Beam.Parent = StartAttachment

    HitFeedbackRuntimeState.ConfigureTracerImpact(
        EndAttachment,
        "LightningImpactVfx",
        Color,
        ImpactWidth,
        Duration,
        Rate,
        SuppressImpact
    )

    task.delay(Duration, function()
        HitFeedbackRuntimeState.ActiveObjects[StartAttachment] = nil
        HitFeedbackRuntimeState.ActiveObjects[EndAttachment] = nil

        if StartAttachment and StartAttachment.Parent then StartAttachment:Destroy() end
        if EndAttachment and EndAttachment.Parent then EndAttachment:Destroy() end

        HitFeedbackRuntimeState.ActiveBulletTracers = math.max(
            HitFeedbackRuntimeState.ActiveBulletTracers - 1,
            0
        )
    end)

    return true
end

function HitFeedbackRuntimeState.CreateChainSegment(Parent, StartAttachment, EndAttachment, Width, Color, Glow, SegmentIndex)
    local Highlight = 0.30 + ((SegmentIndex or 1) % 3) * 0.055 local EdgeColor = Color:Lerp(Color3.new(1, 1, 1), math.clamp(Highlight + Glow * 0.025, 0.28, 0.56))
    local MiddleColor = Color:Lerp(Color3.new(1, 1, 1), math.clamp(0.08 + Glow * 0.012, 0.08, 0.20)) local Transparency = math.clamp(0.12 - Glow * 0.010, 0.055, 0.13)

    local Beam = Internal.CreateBulletTracerBeam(
        Parent,
        StartAttachment,
        EndAttachment,
        "ChainLink",
        math.max(Width, 0.010),
        Transparency,
        Color,
        nil,
        0,
        0
    )

    Beam.Segments = 1
    Beam.LightEmission = 1
    Beam.Width0 = math.max(Width * 0.94, 0.010)
    Beam.Width1 = math.max(Width * 0.94, 0.010)
    Beam.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, EdgeColor), ColorSequenceKeypoint.new(0.50, MiddleColor), ColorSequenceKeypoint.new(1, EdgeColor) })
    Beam.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, math.min(Transparency + 0.08, 1)),
        NumberSequenceKeypoint.new(0.18, Transparency),
        NumberSequenceKeypoint.new(0.82, Transparency),
        NumberSequenceKeypoint.new(1, math.min(Transparency + 0.08, 1))
    })

    return Beam
end

function HitFeedbackRuntimeState.SpawnChainsBulletTracer(OriginPosition, TargetPosition, Tool, SuppressImpact)
    local Delta = TargetPosition - OriginPosition local Distance = Delta.Magnitude

    if Distance < 0.5 then return false end

    local Terrain = workspace:FindFirstChildOfClass("Terrain")
    if not Terrain then return false end

    local Color = HitFeedbackState.BulletTracerColor local Duration = math.clamp(tonumber(HitFeedbackState.BulletTracerTime) or 0.32, 0.05, 2)
    local Width = math.clamp(tonumber(HitFeedbackState.BulletTracerWidth) or 0.10, 0.01, 0.5) local Glow = math.clamp(tonumber(HitFeedbackState.BulletTracerGlow) or 2, 0, 5)
    local Rate = math.clamp(tonumber(HitFeedbackState.BulletTracerRate) or 18, 0, 40) local Direction, Right, Up = HitFeedbackRuntimeState.GetBulletTracerLightningBasis(Delta)

    local LinkCount = math.clamp(math.floor(Distance / 11 + 0.5), 5, 16) local Step = Distance / LinkCount local HalfLength = math.clamp(Step * 0.58, 0.72, 5.2) local Radius = math.clamp(
        0.14 + Width * (1.30 + Glow * 0.07) + math.min(Step, 12) * 0.012,
        0.16,
        0.52
    )
    local LinkWidth = math.clamp(Width * (0.24 + Glow * 0.012), 0.012, 0.11) local PointCount = 8
    local Attachments = {}
    local LinkCenters = table.create(LinkCount) local LinkPointSets = table.create(LinkCount) local Serial = tonumber(HitFeedbackRuntimeState.BulletTracerSerial) or 0

    for LinkIndex = 1, LinkCount do
        local Alpha = (LinkIndex - 0.5) / LinkCount local Center = OriginPosition:Lerp(TargetPosition, Alpha)
        local SideAxis = LinkIndex % 2 == 0 and Up or Right local TwistAxis = LinkIndex % 2 == 0 and Right or Up
        local Twist = ((LinkIndex + Serial) % 3 - 1) * 0.12 local EffectiveSide = (SideAxis + TwistAxis * Twist).Unit

        LinkCenters[LinkIndex] = Center

        local LinkAttachments = table.create(PointCount)
        LinkPointSets[LinkIndex] = LinkAttachments

        for PointIndex = 1, PointCount do
            local Theta = (PointIndex - 1) / PointCount * math.pi * 2 local Forward = math.cos(Theta) * HalfLength
            local Side = math.sin(Theta) * Radius local Position = Center + Direction * Forward + EffectiveSide * Side

            local Attachment = Instance.new("Attachment")
            Attachment.Name = "AtramentaBulletTracerChain" .. tostring(LinkIndex) .. "_" .. tostring(PointIndex)
            Attachment.WorldPosition = Position
            Attachment.Parent = Terrain

            LinkAttachments[PointIndex] = Attachment
            Attachments[#Attachments + 1] = Attachment
            HitFeedbackRuntimeState.ActiveObjects[Attachment] = true
        end

        for PointIndex = 1, PointCount do
            local NextIndex = PointIndex == PointCount and 1 or PointIndex + 1
            HitFeedbackRuntimeState.CreateChainSegment(
                LinkAttachments[PointIndex],
                LinkAttachments[PointIndex],
                LinkAttachments[NextIndex],
                LinkWidth,
                Color,
                Glow,
                PointIndex + LinkIndex
            )
        end
    end

    for LinkIndex = 1, LinkCount - 1 do
        local Current = LinkPointSets[LinkIndex] local Next = LinkPointSets[LinkIndex + 1]

        if Current and Next then
            local CurrentExit = Current[1] local NextEntry = Next[5]

            if CurrentExit and NextEntry then
                local Bridge = HitFeedbackRuntimeState.CreateChainSegment(
                    CurrentExit,
                    CurrentExit,
                    NextEntry,
                    math.max(LinkWidth * 0.58, 0.010),
                    Color,
                    Glow * 0.72,
                    LinkIndex
                )

                Bridge.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.36), NumberSequenceKeypoint.new(0.50, 0.16), NumberSequenceKeypoint.new(1, 0.36) })
            end
        end
    end

    local StartAttachment = Instance.new("Attachment")
    StartAttachment.Name = "AtramentaBulletTracerChainStart"
    StartAttachment.WorldPosition = OriginPosition
    StartAttachment.Parent = Terrain
    Attachments[#Attachments + 1] = StartAttachment
    HitFeedbackRuntimeState.ActiveObjects[StartAttachment] = true

    local EndAttachment = Instance.new("Attachment")
    EndAttachment.Name = "AtramentaBulletTracerChainImpact"
    EndAttachment.WorldPosition = TargetPosition
    EndAttachment.Parent = Terrain
    Attachments[#Attachments + 1] = EndAttachment
    HitFeedbackRuntimeState.ActiveObjects[EndAttachment] = true

    local FirstLink = LinkPointSets[1] local LastLink = LinkPointSets[LinkCount]

    if FirstLink and FirstLink[5] then
        local StartBridge = HitFeedbackRuntimeState.CreateChainSegment(
            StartAttachment,
            StartAttachment,
            FirstLink[5],
            math.max(LinkWidth * 0.62, 0.010),
            Color,
            Glow * 0.76,
            1
        )
        StartBridge.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.72), NumberSequenceKeypoint.new(1, 0.16) })
    end

    if LastLink and LastLink[1] then
        local EndBridge = HitFeedbackRuntimeState.CreateChainSegment(
            LastLink[1],
            LastLink[1],
            EndAttachment,
            math.max(LinkWidth * 0.62, 0.010),
            Color,
            Glow * 0.76,
            LinkCount
        )
        EndBridge.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.16), NumberSequenceKeypoint.new(1, 0.72) })
    end

    HitFeedbackRuntimeState.ConfigureTracerImpact(EndAttachment, "ChainImpactVfx", Color, Width, Duration, Rate, SuppressImpact)

    task.delay(Duration, function()
        for Index = 1, #Attachments do
            local Attachment = Attachments[Index]
            HitFeedbackRuntimeState.ActiveObjects[Attachment] = nil

            if Attachment and Attachment.Parent then Attachment:Destroy() end
        end

        HitFeedbackRuntimeState.ActiveBulletTracers = math.max(
            HitFeedbackRuntimeState.ActiveBulletTracers - 1,
            0
        )
    end)

    return true
end

function HitFeedbackRuntimeState.SpawnHelixBulletTracer(OriginPosition, TargetPosition, Tool, SuppressImpact)
    local Delta = TargetPosition - OriginPosition
    local Distance = Delta.Magnitude
    if Distance < 0.5 then return false end

    local Terrain = workspace:FindFirstChildOfClass("Terrain")
    if not Terrain then return false end

    local Color = HitFeedbackState.BulletTracerColor
    local Duration = math.clamp(tonumber(HitFeedbackState.BulletTracerTime) or 0.32, 0.05, 2)
    local Width = math.clamp(tonumber(HitFeedbackState.BulletTracerWidth) or 0.10, 0.01, 0.5)
    local Glow = math.clamp(tonumber(HitFeedbackState.BulletTracerGlow) or 2, 0, 5)
    local Rate = math.clamp(tonumber(HitFeedbackState.BulletTracerRate) or 18, 0, 40)
    local Direction, Right, Up = HitFeedbackRuntimeState.GetBulletTracerLightningBasis(Delta)

    local PointCount = math.clamp(math.floor(Distance / 8 + 0.5), 10, 22)
    local Turns = math.clamp(Distance / 28, 2.2, 7)
    local Radius = math.clamp(0.10 + Width * 1.7 + Glow * 0.025, 0.12, 0.48)
    local StrandWidth = math.clamp(Width * 0.42, 0.012, 0.12)
    local Attachments = {}

    local function BuildStrand(Phase, StrandColor)
        local Previous

        for Index = 0, PointCount do
            local Alpha = Index / PointCount
            local Theta = Alpha * math.pi * 2 * Turns + Phase
            local Fade = math.sin(Alpha * math.pi)
            local Position = OriginPosition:Lerp(TargetPosition, Alpha)
                + Right * math.cos(Theta) * Radius * Fade
                + Up * math.sin(Theta) * Radius * Fade

            local Attachment = Instance.new("Attachment")
            Attachment.Name = "AtramentaBulletTracerHelix" .. tostring(Index)
            Attachment.WorldPosition = Position
            Attachment.Parent = Terrain
            Attachments[#Attachments + 1] = Attachment
            HitFeedbackRuntimeState.ActiveObjects[Attachment] = true

            if Previous then
                local Beam = Internal.CreateBulletTracerBeam(
                    Previous,
                    Previous,
                    Attachment,
                    "Helix",
                    StrandWidth,
                    0.10,
                    StrandColor,
                    nil,
                    0,
                    0
                )

                Beam.Width0 = StrandWidth
                Beam.Width1 = StrandWidth * 0.82
                Beam.LightEmission = 1
                Beam.FaceCamera = true
            end

            Previous = Attachment
        end
    end

    BuildStrand(0, Color)
    BuildStrand(math.pi, Color:Lerp(Color3.new(1, 1, 1), 0.34))

    local EndAttachment = Attachments[#Attachments]
    if EndAttachment then
        HitFeedbackRuntimeState.ConfigureTracerImpact(EndAttachment, "HelixImpactVfx", Color, Width, Duration, Rate, SuppressImpact)
    end

    task.delay(Duration, function()
        for Index = 1, #Attachments do
            local Attachment = Attachments[Index]
            HitFeedbackRuntimeState.ActiveObjects[Attachment] = nil
            if Attachment and Attachment.Parent then Attachment:Destroy() end
        end

        HitFeedbackRuntimeState.ActiveBulletTracers = math.max(HitFeedbackRuntimeState.ActiveBulletTracers - 1, 0)
    end)

    return true
end

function Internal.SpawnBulletTracer(OriginPosition, TargetPosition, Tool, VerifiedFirearmShot, SuppressImpact)
    if not HitFeedbackState.BulletTracerEnabled or not OriginPosition or not TargetPosition then return end

    if not IsVerifiedLocalFirearmTool(Tool) then return end

    local Distance = (TargetPosition - OriginPosition).Magnitude
    if Distance < 0.5 then return end

    local Style = tostring(HitFeedbackState.BulletTracerStyle or "Energy") local ActiveLimit = Style == "Chains" and 6 or Style == "Helix" and 4 or 12

    if HitFeedbackRuntimeState.ActiveBulletTracers >= ActiveLimit then return end

    local Terrain = workspace:FindFirstChildOfClass("Terrain") if not Terrain then return end

    HitFeedbackRuntimeState.ActiveBulletTracers += 1
    HitFeedbackRuntimeState.BulletTracerSerial += 1

    local Serial = HitFeedbackRuntimeState.BulletTracerSerial
    local Color = HitFeedbackState.BulletTracerColor local Duration = math.clamp(tonumber(HitFeedbackState.BulletTracerTime) or 0.32, 0.05, 2)
    local Width = math.clamp(tonumber(HitFeedbackState.BulletTracerWidth) or 0.10, 0.01, 0.5) local Glow = math.clamp(tonumber(HitFeedbackState.BulletTracerGlow) or 2, 0, 5)
    local Rate = math.clamp(tonumber(HitFeedbackState.BulletTracerRate) or 18, 0, 40)

    if Style == "Lightning" or Style == "Chains" or Style == "Helix" then
        local Success

        if Style == "Lightning" then
            Success = HitFeedbackRuntimeState.SpawnLightningBulletTracer(OriginPosition, TargetPosition, Tool, SuppressImpact)
        elseif Style == "Chains" then
            Success = HitFeedbackRuntimeState.SpawnChainsBulletTracer(OriginPosition, TargetPosition, Tool, SuppressImpact)
        else
            Success = HitFeedbackRuntimeState.SpawnHelixBulletTracer(OriginPosition, TargetPosition, Tool, SuppressImpact)
        end

        if not Success then HitFeedbackRuntimeState.ActiveBulletTracers = math.max(HitFeedbackRuntimeState.ActiveBulletTracers - 1, 0) end
        return
    end

    local StartAttachment = Instance.new("Attachment")
    StartAttachment.Name = "AtramentaBulletTracerStart" .. tostring(Serial)
    StartAttachment.WorldPosition = OriginPosition
    StartAttachment.Parent = Terrain

    local EndAttachment = Instance.new("Attachment")
    EndAttachment.Name = "AtramentaBulletTracerEnd" .. tostring(Serial)
    EndAttachment.WorldPosition = TargetPosition
    EndAttachment.Parent = Terrain

    HitFeedbackRuntimeState.ActiveObjects[StartAttachment] = true
    HitFeedbackRuntimeState.ActiveObjects[EndAttachment] = true

    local Energy = Style == "Energy" local Pulse = Style == "Pulse" local Liquid = Style == "Liquid"
    local CoreColor = Color:Lerp(Color3.new(1, 1, 1), Energy and 0.24 or Liquid and 0.10 or 0.12)
    local CoreTexture = (Energy or Liquid) and "rbxasset://textures/particles/sparkles_main.dds" or nil
    local CoreTextureSpeed = Energy and 5.2 or Liquid and 2.2 or 0
    local CoreCurve = Pulse and math.min(Distance * 0.010, 2.15) or Liquid and math.min(Distance * 0.006, 1.25) or 0

    local Core = Internal.CreateBulletTracerBeam(StartAttachment, StartAttachment, EndAttachment, "Core", Width, Liquid and 0.10 or 0.035, CoreColor,
        CoreTexture, CoreTextureSpeed, CoreCurve)

    Core.Width0 = Width * 0.92
    Core.Width1 = Width * 0.56
    Core.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.24), NumberSequenceKeypoint.new(0.08, 0.035),
        NumberSequenceKeypoint.new(0.82, 0.055), NumberSequenceKeypoint.new(1, 0.34) })

    Core.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, CoreColor), ColorSequenceKeypoint.new(0.55, Color),
        ColorSequenceKeypoint.new(1, Color:Lerp(Color3.new(1, 1, 1), 0.18)) })

    if Liquid then
        Core.TextureLength = 0.72
        Core.TextureMode = Enum.TextureMode.Wrap
        Core.Width0 = Width * 1.18
        Core.Width1 = Width * 0.84
        Core.CurveSize0 = math.min(Distance * 0.004, 0.85)
        Core.CurveSize1 = -math.min(Distance * 0.004, 0.85)
        Core.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.42),
            NumberSequenceKeypoint.new(0.18, 0.10),
            NumberSequenceKeypoint.new(0.72, 0.08),
            NumberSequenceKeypoint.new(1, 0.48)
        })
    end

    if Glow > 0 then
        local GlowWidth = Width * (1.55 + Glow * 0.34)
        local GlowBeam = Internal.CreateBulletTracerBeam( StartAttachment, StartAttachment, EndAttachment, "Glow", GlowWidth, 0.56, Color, nil, 0,
            Pulse and -math.min(Distance * 0.007, 1.35) or 0)

        GlowBeam.Width0 = GlowWidth * 0.92
        GlowBeam.Width1 = GlowWidth * 0.58

        local MidAlpha = math.clamp(0.60 - Glow * 0.035, 0.38, 0.62)
        GlowBeam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.82), NumberSequenceKeypoint.new(0.12, MidAlpha),
            NumberSequenceKeypoint.new(0.76, MidAlpha + 0.03), NumberSequenceKeypoint.new(1, 0.90) })
    end

    if Pulse then
        local PulseBeam = Internal.CreateBulletTracerBeam( StartAttachment, StartAttachment, EndAttachment, "Pulse", math.max(Width * 0.34, 0.010), 0.10,
            Color3.new(1, 1, 1), "rbxasset://textures/particles/sparkles_main.dds", 8.5, 0)

        PulseBeam.TextureLength = 0.55
        PulseBeam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.80), NumberSequenceKeypoint.new(0.35, 0.08),
            NumberSequenceKeypoint.new(0.65, 0.08), NumberSequenceKeypoint.new(1, 0.88) })
    end

    HitFeedbackRuntimeState.ConfigureTracerImpact( EndAttachment, "ImpactVfx", Color, Width, Duration, Rate, SuppressImpact)

    task.delay(Duration, function()
        HitFeedbackRuntimeState.ActiveObjects[StartAttachment] = nil
        HitFeedbackRuntimeState.ActiveObjects[EndAttachment] = nil

        if StartAttachment.Parent then StartAttachment:Destroy() end

        if EndAttachment.Parent then EndAttachment:Destroy() end

        HitFeedbackRuntimeState.ActiveBulletTracers = math.max(HitFeedbackRuntimeState.ActiveBulletTracers - 1, 0)
    end)
end

function Internal.SpawnDirectionalBulletTracer(OriginPosition, TargetPosition, Tool, VerifiedFirearmShot, SuppressImpact)
    if not HitFeedbackState.BulletTracerEnabled or not OriginPosition or not TargetPosition then return end
    if not IsVerifiedLocalFirearmTool(Tool) then return end
    Internal.SpawnBulletTracer(OriginPosition, TargetPosition, Tool, VerifiedFirearmShot, SuppressImpact)
end

function Internal.SpawnRageRouteTracer(Shot, VisualOrigin, TargetPosition, Tool)
    if type(Shot) == "table"
        and Shot.Source == "RageBot"
        and typeof(Shot.Origin) == "Vector3"
    then
        local PacketOrigin =
            typeof(Shot.PacketOrigin) == "Vector3"
                and Shot.PacketOrigin
            or Shot.Origin

        local PacketDirection =
            typeof(Shot.PacketDirection) == "Vector3"
                and Shot.PacketDirection
            or typeof(Shot.Direction) == "Vector3"
                and Shot.Direction
            or nil

        local PacketTarget =
            typeof(Shot.HitPosition) == "Vector3"
                and Shot.HitPosition
            or PacketDirection
                and PacketDirection.Magnitude > 0.001
                and PacketOrigin + PacketDirection
            or nil

        if typeof(PacketOrigin) == "Vector3" and typeof(PacketTarget) == "Vector3" then
            Internal.SpawnDirectionalBulletTracer(
                PacketOrigin,
                PacketTarget,
                Tool,
                true,
                false
            )

            return
        end
    end

    if typeof(VisualOrigin) == "Vector3"
        and typeof(TargetPosition) == "Vector3"
    then
        Internal.SpawnDirectionalBulletTracer(
            VisualOrigin,
            TargetPosition,
            Tool,
            true
        )
    end
end
HitFeedbackRuntimeState.SpawnConfirmedTracer = function(Shot, TargetPart)
    if not HitFeedbackState.BulletTracerEnabled or not Shot or Shot.TracerSpawned then return false end

    local Tool = Shot.Tool

    if not IsVerifiedLocalFirearmTool(Tool) then return false end

    if not TargetPart or not TargetPart:IsA("BasePart") or not TargetPart.Parent then return false end

    local OriginPosition = typeof(Shot.VisualOrigin) == "Vector3" and Shot.VisualOrigin or Internal.GetBulletTracerVisualOrigin( Tool, Shot.Origin)

    local TargetPosition = typeof(Shot.HitPosition) == "Vector3" and Shot.HitPosition or TargetPart.Position

    if typeof(OriginPosition) ~= "Vector3" or typeof(TargetPosition) ~= "Vector3" or ( TargetPosition - OriginPosition ).Magnitude < 0.5 then return false end

    local Token = Shot.Token

    if Token ~= nil and not Internal.ShouldSpawnBulletTracerToken( Tool, Token ) then
        Shot.TracerSpawned = true
        return false
    end

    Shot.TracerSpawned = true

    Internal.SpawnRageRouteTracer( Shot, OriginPosition, TargetPosition, Tool)

    return true
end

function Internal.ClearBulletTracers()
    for Object in pairs(HitFeedbackRuntimeState.ActiveObjects) do
        if Object and string.find(Object.Name, "AtramentaBulletTracer", 1, true) == 1 then
            HitFeedbackRuntimeState.ActiveObjects[Object] = nil
            if Object.Parent then Object:Destroy() end
        end
    end
    HitFeedbackRuntimeState.ActiveBulletTracers = 0
    HitFeedbackRuntimeState.BulletTracerTokenCache = {}
    HitFeedbackRuntimeState.BulletTracerTokenCacheCount = 0
    HitFeedbackRuntimeState.BulletTracerTokenCacheRebuild = os.clock()
end

function ShouldSpawnBulletTracer(Tool, MinimumGap)
    if not IsVerifiedLocalFirearmTool(Tool) then return false end

    local CurrentTime = os.clock() local PreviousTime = HitFeedbackRuntimeState.BulletTracerLastSpawn[Tool] or 0
    MinimumGap = tonumber(MinimumGap) or 0.025

    if CurrentTime - PreviousTime < MinimumGap then return false end
    HitFeedbackRuntimeState.BulletTracerLastSpawn[Tool] = CurrentTime
    return true
end

function GetBulletTracerTargetFromDirection(OriginPosition, Direction, Tool)
    if typeof(OriginPosition) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude < 0.01 then return nil end

    local RaycastParameters = RaycastParams.new()
    RaycastParameters.FilterType = Enum.RaycastFilterType.Exclude
    RaycastParameters.IgnoreWater = true

    local Excluded = {}
    if LocalPlayer.Character then Excluded[#Excluded + 1] = LocalPlayer.Character end
    if Tool then Excluded[#Excluded + 1] = Tool end
    RaycastParameters.FilterDescendantsInstances = Excluded

    local DirectionMagnitude = Direction.Magnitude
    local Distance = DirectionMagnitude > 5 and math.min(DirectionMagnitude, AttackConfirmationState.ShotRange) or AttackConfirmationState.ShotRange
    local Result = workspace:Raycast(OriginPosition, Direction.Unit * Distance, RaycastParameters)
    return Result and Result.Position or OriginPosition + Direction.Unit * Distance
end

function FindBulletTracerVectorInTable(Value, Depth)
    if type(Value) ~= "table" or (Depth or 0) > 2 then return nil end

    for _, NestedValue in pairs(Value) do
        if typeof(NestedValue) == "Vector3" and NestedValue.Magnitude > 0.001 then return NestedValue end

        if type(NestedValue) == "table" then
            local Found = FindBulletTracerVectorInTable(NestedValue, (Depth or 0) + 1)
            if Found then return Found end
        end
    end

    return nil
end

function ParseBulletTracerRemoteArguments(...)
    local Arguments = table.pack(...) local MarkerIndex = nil

    for Index = 1, Arguments.n do
        if Arguments[Index] == "FDS9I83" then
            MarkerIndex = Index
            break
        end
    end

    if not MarkerIndex then return nil end

    local Tool = nil local OriginPosition = nil local Direction = nil local ShotToken = MarkerIndex >= 3 and Arguments[MarkerIndex - 2] or nil

    for Index = 1, Arguments.n do
        local Value = Arguments[Index]
        if not Tool and typeof(Value) == "Instance" and Value:IsA("Tool") then Tool = Value end
    end

    for Index = MarkerIndex + 1, Arguments.n do
        local Value = Arguments[Index]
        if not OriginPosition and typeof(Value) == "Vector3" then
            OriginPosition = Value
        elseif not Direction and type(Value) == "table" then
            Direction = FindBulletTracerVectorInTable(Value, 0)
        elseif OriginPosition and not Direction and typeof(Value) == "Vector3" then
            Direction = Value
        end
    end

    if not Tool then Tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Tool") end
    if Tool and not OriginPosition then OriginPosition = Internal.GetBulletTracerOrigin(Tool) end
    return Tool, OriginPosition, Direction, ShotToken
end

function ResolveCapturedShotTarget(OriginPosition, Direction, Tool)
    if typeof(OriginPosition) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude < 0.01 then return nil, nil end
    local RaycastParameters = RaycastParams.new()
    RaycastParameters.FilterType = Enum.RaycastFilterType.Exclude
    RaycastParameters.IgnoreWater = true
    local Excluded = {}
    if LocalPlayer.Character then Excluded[#Excluded + 1] = LocalPlayer.Character end
    if Tool then Excluded[#Excluded + 1] = Tool end
    RaycastParameters.FilterDescendantsInstances = Excluded
    local DirectionMagnitude = Direction.Magnitude
    local Distance = DirectionMagnitude > 5 and math.min(DirectionMagnitude, AttackConfirmationState.ShotRange) or AttackConfirmationState.ShotRange
    local Result = workspace:Raycast(OriginPosition, Direction.Unit * Distance, RaycastParameters)
    if not Result then return nil, nil end
    local Character = Internal.GetHumanoidCharacterFromPart(Result.Instance)
    if not Character then return nil, nil end
    return Character, Result.Instance
end

function QueueBulletTracerRemotePacket(Tool, ShotToken, OriginPosition, Direction, Shot)
    if not Tool or not Tool:IsA("Tool") or ShotToken == nil then return nil end

    local Queue = HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool]
    if type(Queue) ~= "table" then
        Queue = {}
        HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool] = Queue
    end

    local CurrentTime = os.clock()

    for Index = #Queue, 1, -1 do
        local Packet = Queue[Index]
        if type(Packet) ~= "table" or CurrentTime - (tonumber(Packet.Time) or 0) > 0.65 then
            table.remove(Queue, Index)
        elseif tostring(Packet.Token) == tostring(ShotToken) then
            Packet.Time = CurrentTime
            Packet.Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or Packet.Origin
            Packet.Direction = typeof(Direction) == "Vector3" and Direction or Packet.Direction
            Packet.Shot = type(Shot) == "table" and Shot or Packet.Shot
            return Packet
        end
    end

    local Packet = { Time = CurrentTime, Token = ShotToken, Origin = typeof(OriginPosition) == "Vector3" and OriginPosition or nil,
        Direction = typeof(Direction) == "Vector3" and Direction or nil, Shot = type(Shot) == "table" and Shot or nil }

    Queue[#Queue + 1] = Packet
    while #Queue > 12 do table.remove(Queue, 1) end
    return Packet
end

function TakeBulletTracerRemotePacket(Tool, MaximumAge)
    local Queue = Tool and HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool]
    if type(Queue) ~= "table" then return nil end

    local CurrentTime = os.clock()
    MaximumAge = tonumber(MaximumAge) or 0.45

    while #Queue > 0 do
        local Packet = table.remove(Queue, 1)
        if type(Packet) == "table" and CurrentTime - (tonumber(Packet.Time) or 0) <= MaximumAge then return Packet end
    end

    HitFeedbackRuntimeState.BulletTracerPendingRemote[Tool] = nil
    return nil
end

function SpawnConfirmedRemoteBulletTracer(Tool, Packet)
    if not HitFeedbackState.BulletTracerEnabled or type(Packet) ~= "table" or not IsVerifiedLocalFirearmTool(Tool) then return false end

    local Shot = Packet.Shot local OriginPosition = Packet.Origin local Direction = Packet.Direction local ShotToken = Packet.Token

    if typeof(OriginPosition) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude < 0.01 or ShotToken == nil then return false end

    if type(Shot) == "table" and Shot.TracerSpawned then
        Shot.AmmoConfirmed = true

        if Ragebot and type(Ragebot.MarkValidationAmmo) == "function" then Ragebot.MarkValidationAmmo(Shot) end

        return true
    end

    if type(Shot) == "table" and Internal.IsSilentTrackedShot(Shot) then
        Shot.AmmoConfirmed = true
        Shot.SilentTracerDeferred = true
        if Ragebot and type(Ragebot.MarkValidationAmmo) == "function" then Ragebot.MarkValidationAmmo(Shot) end
        if type(Internal.TryConfirmBufferedDamage) == "function" then Internal.TryConfirmBufferedDamage(Shot) end
        return true
    end

    if not Internal.ShouldSpawnBulletTracerToken(Tool, ShotToken) then return false end

    local VisualOrigin = type(Shot) == "table" and typeof(Shot.VisualOrigin) == "Vector3" and Shot.VisualOrigin or Internal.GetBulletTracerVisualOrigin(Tool, OriginPosition)

    local TargetPosition = type(Shot) == "table" and typeof(Shot.HitPosition) == "Vector3" and Shot.HitPosition or Internal.ResolveBulletTracerExactTarget( Tool,
            OriginPosition, Direction, ShotToken)

    if typeof(VisualOrigin) ~= "Vector3" or typeof(TargetPosition) ~= "Vector3" or (TargetPosition - VisualOrigin).Magnitude < 0.5 then return false end

    if type(Shot) == "table" then
        Shot.TracerSpawned = true
        Shot.AmmoConfirmed = true

        if Ragebot and type(Ragebot.MarkValidationAmmo) == "function" then Ragebot.MarkValidationAmmo(Shot) end
    end

    Internal.SpawnRageRouteTracer( Shot, VisualOrigin, TargetPosition, Tool)

    return true
end

function DispatchBulletTracerRemoteShot(Remote, ...)
    if not Internal.IsLocalGunShotRemote(Remote) then return false end

    local Tool, OriginPosition, Direction, ShotToken = ParseBulletTracerRemoteArguments(...)

    if not IsVerifiedLocalFirearmTool(Tool) or ShotToken == nil or typeof(OriginPosition) ~= "Vector3" or typeof(Direction) ~= "Vector3"
        or Direction.Magnitude < 0.01 then
        return false
    end

    local CurrentTime = os.clock()
    HitFeedbackRuntimeState.BulletTracerLastRemoteShot[Tool] = CurrentTime

    local ReportedShots = Ragebot and Ragebot.ReportedShots local Shot = type(ReportedShots) == "table" and ReportedShots[ShotToken] or nil

    if type(Shot) ~= "table" then
        local TargetCharacter, TargetPart = ResolveCapturedShotTarget( OriginPosition, Direction, Tool)
        local Source = "Manual"
        local AimBot = Configuration and Configuration.AimBot
        if AimBot and AimBot.AimbotEnabled == true and AimBot.AimActive == true then
            local CapturedPlayer = Internal.GetPlayerFromTrackedCharacter(TargetCharacter)
            local ActiveTarget = AimBot.CurrentTarget or AimBot.AimbotLockedTarget
            if not ActiveTarget or CapturedPlayer == ActiveTarget then Source = "Aimbot" end
        end

        Shot = Internal.RegisterLocalAttack( TargetCharacter, TargetPart, ShotToken, Tool, Source, OriginPosition, Direction)
    end

    if not Shot then return false end
    Shot.RemoteConfirmed = true
    Shot.RemoteConfirmedAt = CurrentTime
    if type(Internal.TryConfirmBufferedDamage) == "function" then Internal.TryConfirmBufferedDamage(Shot) end

    if Ragebot and type(Ragebot.MarkValidationRemote) == "function" then Ragebot.MarkValidationRemote(Shot) end

    if tostring(Shot.Source or "") == "RageBot" then Shot.RageRemoteSent = true end

    if typeof(Shot.VisualOrigin) ~= "Vector3" then Shot.VisualOrigin = Internal.GetBulletTracerVisualOrigin( Tool, OriginPosition) end

    if typeof(Shot.HitPosition) ~= "Vector3" then Shot.HitPosition = Internal.ResolveBulletTracerExactTarget( Tool, OriginPosition, Direction, ShotToken) end

    QueueBulletTracerRemotePacket( Tool, ShotToken, OriginPosition, Direction, Shot)

    local LastAmmoDecrease = HitFeedbackRuntimeState.BulletTracerLastAmmoDecrease[Tool] or 0

    if CurrentTime - LastAmmoDecrease <= 0.085 then
        local Packet = TakeBulletTracerRemotePacket( Tool, 0.12)

        if Packet then SpawnConfirmedRemoteBulletTracer( Tool, Packet) end
    end

    return true
end

function InstallBulletTracerFireServerHook(State)
    if type(State) == "table" then State.FireServerVersion = 0 end

    return false
end

function InstallBulletTracerShotHook()

    local State = rawget( Environment, "AtramentaBulletTracerShotHook")

    if type(State) ~= "table" or State.TrackerVersion ~= 12 then
        if type(State) == "table" then State.Enabled = false end

        State = { TrackerVersion = 12, FireServerVersion = 0, Enabled = false }

        rawset( Environment, "AtramentaBulletTracerShotHook", State)
    end

    State.TrackerVersion = 12
    State.FireServerVersion = 0
    State.Enabled = Internal.IsShotTrackingEnabled()

    if type( InstallSharedNamecallRouter ) == "function" then InstallSharedNamecallRouter() end

    return true
end

function RefreshLocalShotTracking()
    InstallBulletTracerShotHook()
    local State = Environment.AtramentaBulletTracerShotHook
    if type(State) == "table" then State.Enabled = Internal.IsShotTrackingEnabled() end
end

function SetBulletTracerShotHookEnabled(Value)
    HitFeedbackState.BulletTracerEnabled = Value == true
    RefreshLocalShotTracking()
end

function Internal.GetBulletTracerAmmoValue(Tool)
    local Data = GetBulletTracerWeaponData(Tool)
    return Data and Data.Ammo or nil
end

function Internal.BindBulletTracerAmmo(Tool, Connections)
    local AmmoValue = Internal.GetBulletTracerAmmoValue(Tool)

    if not AmmoValue or HitFeedbackRuntimeState.BulletTracerAmmoObjects[AmmoValue] then return false end

    HitFeedbackRuntimeState.BulletTracerAmmoObjects[AmmoValue] = true
    local PreviousValue = tonumber(AmmoValue.Value) or 0

    Connections[#Connections + 1] = AmmoValue.Changed:Connect(function(Value)
            local CurrentValue = tonumber(Value) or tonumber(AmmoValue.Value) or PreviousValue

            local Fired = CurrentValue < PreviousValue
            PreviousValue = CurrentValue

            if not Fired then return end

            HitFeedbackRuntimeState.BulletTracerLastAmmoDecrease[Tool] = os.clock()

            local AmmoConfirmedAt = os.clock()

            for Index = #AttackConfirmationState.Shots, 1, -1 do
                local Shot = AttackConfirmationState.Shots[ Index ]

                if Shot and Shot.Tool == Tool and not Shot.AmmoConfirmed and AmmoConfirmedAt
                        - (Shot.Time or 0)
                        <= 0.55 then
                    Shot.AmmoConfirmed = true

                    if Ragebot and type(Ragebot.MarkValidationAmmo) == "function" then Ragebot.MarkValidationAmmo(Shot, CurrentValue) end
                    if Internal.IsSilentTrackedShot(Shot) and type(Internal.TryConfirmBufferedDamage) == "function" then Internal.TryConfirmBufferedDamage(Shot) end

                    break
                end
            end

            local Packet = TakeBulletTracerRemotePacket( Tool, 0.50)

            if Packet then SpawnConfirmedRemoteBulletTracer( Tool, Packet) end
        end)

    return true
end

function Internal.GetConfirmedHitmarkerParent()
    local Holder = Library and Library.Holder local HolderInstance = Holder and (Holder.Instance or Holder)
    if typeof(HolderInstance) == "Instance" and HolderInstance:IsA("ScreenGui") and HolderInstance.Parent then return HolderInstance end

    local Existing = HitFeedbackRuntimeState.HitmarkerGui
    if Existing and Existing.Parent then return Existing end

    local Parent = Internal.GetHitFeedbackGuiParent()
    if not Parent then return nil end

    local Gui = Instance.new("ScreenGui")
    Gui.Name = "AtramentaConfirmedHitmarkerGui"
    Gui.IgnoreGuiInset = true
    Gui.ResetOnSpawn = false
    Gui.DisplayOrder = 99999
    Gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    Gui.Parent = Parent
    HitFeedbackRuntimeState.HitmarkerGui = Gui
    HitFeedbackRuntimeState.ActiveObjects[Gui] = true
    return Gui
end

function Internal.SpawnConfirmedHitmarker(IsHeadshot)
    if not HitFeedbackState.HitmarkerEnabled then return end
    local Parent = Internal.GetConfirmedHitmarkerParent() if not Parent then return end

    local Size = math.clamp(tonumber(HitFeedbackState.HitmarkerSize) or 28, 12, 60) local Duration = math.clamp(tonumber(HitFeedbackState.HitmarkerDuration) or 0.24, 0.08, 1)
    local Color = IsHeadshot and HitFeedbackState.HeadshotHitmarkerColor or HitFeedbackState.HitmarkerColor

    local Holder = Instance.new("Frame")
    Holder.Name = "AtramentaConfirmedHitmarker"
    Holder.AnchorPoint = Vector2.new(0.5, 0.5)
    Holder.Position = UDim2.fromScale(0.5, 0.5)
    Holder.Size = UDim2.fromOffset(Size * 2, Size * 2)
    Holder.BackgroundTransparency = 1
    Holder.BorderSizePixel = 0
    Holder.ZIndex = 10000
    Holder.Parent = Parent
    HitFeedbackRuntimeState.ActiveObjects[Holder] = true

    local Scale = Instance.new("UIScale")
    Scale.Scale = 0.68
    Scale.Parent = Holder

    local Thickness = math.max(math.floor(Size * 0.11 + 0.5), 2) local ArmLength = math.max(math.floor(Size * 0.48 + 0.5), 7) local Gap = math.max(math.floor(Size * 0.16 + 0.5), 3)

    local function CreateArm(Rotation, X, Y)
        local Arm = Instance.new("Frame")
        Arm.Name = "Arm"
        Arm.AnchorPoint = Vector2.new(0.5, 0.5)
        Arm.Position = UDim2.new(0.5, X * (Gap + ArmLength * 0.5), 0.5, Y * (Gap + ArmLength * 0.5))
        Arm.Size = UDim2.fromOffset(ArmLength, Thickness)
        Arm.Rotation = Rotation
        Arm.BackgroundColor3 = Color Arm.BackgroundTransparency = 0
        Arm.BorderSizePixel = 0
        Arm.ZIndex = 10001
        Arm.Parent = Holder
        return Arm
    end

    local Root = math.sqrt(0.5)
    local Arms = { CreateArm(45, Root, Root), CreateArm(45, -Root, -Root), CreateArm(-45, Root, -Root), CreateArm(-45, -Root, Root) }

    TweenService:Create(Scale, TweenInfo.new(math.min(Duration * 0.35, 0.10), Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    task.delay(math.min(Duration * 0.30, 0.08), function()
        if not Holder.Parent then return end
        TweenService:Create(Scale, TweenInfo.new(math.max(Duration * 0.70, 0.08), Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 1.16 }):Play()
        for _, Arm in ipairs(Arms) do
            TweenService:Create(Arm, TweenInfo.new(math.max(Duration * 0.70, 0.08), Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 1 }):Play()
        end
    end)

    task.delay(Duration + 0.06, function()
        HitFeedbackRuntimeState.ActiveObjects[Holder] = nil
        if Holder.Parent then Holder:Destroy() end
    end)
end

function Internal.SpawnConfirmedHitImage()
    local ImageName = tostring( HitFeedbackState.HitmarkerImage or "None")

    local ImageId = HitmarkerImages[ ImageName ]

    if type(ImageId) ~= "string" or ImageId == "" then return end

    local Parent = Internal.GetConfirmedHitmarkerParent()

    if not Parent then return end

    local Size = math.clamp( tonumber(HitFeedbackState.HitmarkerImageSize) or 120, 32, 320)

    local Duration = math.clamp( tonumber(HitFeedbackState.HitmarkerImageDuration) or 0.65, 0.10, 3)

    local BaseTransparency = math.clamp( tonumber(HitFeedbackState.HitmarkerImageTransparency) or 0, 0, 0.95)

    local Animation = tostring( HitFeedbackState.HitmarkerImageAnimation or "Fade")

    local Holder = Instance.new( "Frame")

    Holder.Name = "AtramentaConfirmedHitImage"

    Holder.AnchorPoint = Vector2.new( 0.5, 0.5)

    Holder.Position = UDim2.fromScale( 0.5, 0.5)

    Holder.Size = UDim2.fromOffset( Size, Size)

    Holder.BackgroundTransparency = 1

    Holder.BorderSizePixel = 0

    Holder.ZIndex = 10020

    Holder.Parent = Parent

    HitFeedbackRuntimeState.ActiveObjects[ Holder ] = true

    local Image = Instance.new( "ImageLabel")

    Image.Name = "Image"

    Image.AnchorPoint = Vector2.new( 0.5, 0.5)

    Image.Position = UDim2.fromScale( 0.5, 0.5)

    Image.Size = UDim2.fromScale( 1, 1)

    Image.BackgroundTransparency = 1

    Image.BorderSizePixel = 0

    Image.Image = ImageId

    Image.ImageTransparency = BaseTransparency

    Image.ScaleType = Enum.ScaleType.Fit

    Image.ZIndex = 10021

    Image.Parent = Holder

    local Scale = Instance.new( "UIScale")

    Scale.Parent = Holder

    if Animation == "Rise" then
        Scale.Scale = 0.90
    elseif Animation == "Fade" then
        Scale.Scale = 0.96
    else
        Scale.Scale = 1
    end

    if Animation == "Rise" then
        TweenService:Create( Scale, TweenInfo.new( math.min( Duration * 0.24, 0.14 ), Enum.EasingStyle.Back, Enum.EasingDirection.Out ), { Scale = 1 }
        ):Play()

        TweenService:Create( Holder, TweenInfo.new( Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out ), { Position = UDim2.new( 0.5, 0, 0.5,
                        -math.max( Size * 0.45, 36 ) ) } ):Play()

        TweenService:Create( Image, TweenInfo.new( Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.In ), { ImageTransparency = 1 } ):Play()
    elseif Animation == "Fade" then
        TweenService:Create( Scale, TweenInfo.new( math.min( Duration * 0.30, 0.16 ), Enum.EasingStyle.Back, Enum.EasingDirection.Out ), { Scale = 1 }
        ):Play()

        task.delay( math.min( Duration * 0.28, 0.14 ), function()
                if not Image.Parent then return end

                TweenService:Create( Image, TweenInfo.new( math.max( Duration * 0.72, 0.06 ), Enum.EasingStyle.Quad, Enum.EasingDirection.Out ), {
                        ImageTransparency = 1 } ):Play()
            end)
    elseif Animation == "Static" then
        task.delay( math.max( Duration - 0.10, 0 ), function()
                if not Image.Parent then return end

                TweenService:Create( Image, TweenInfo.new( math.min( Duration, 0.10 ), Enum.EasingStyle.Linear, Enum.EasingDirection.Out ), {
                        ImageTransparency = 1 } ):Play()
            end)
    end

    task.delay( Duration + 0.08, function()
            HitFeedbackRuntimeState.ActiveObjects[ Holder ] = nil

            if Holder.Parent then Holder:Destroy() end
        end)
end

function Internal.PlayConfiguredHitFeedbackSound(SoundName, Volume, PlaybackSpeed, InstanceName)
    SoundName = Internal.NormalizeHitSoundName(SoundName)
    local SoundId = HitSounds[SoundName]

    if type(SoundId) ~= "string" or SoundId == "" then return false end

    local Sound = Instance.new( "Sound")

    Sound.Name = tostring( InstanceName or "AtramentaHitSound")

    Sound.SoundId = SoundId

    Sound.Volume = math.clamp( tonumber(Volume) or 1, 0, 5)

    Sound.PlaybackSpeed = math.clamp( tonumber(PlaybackSpeed) or 1, 0.5, 2)

    Sound.Parent = SoundService

    HitFeedbackRuntimeState.ActiveObjects[ Sound ] = true

    local Finished = false local EndedConnection

    local function DestroySound()
        if Finished then return end

        Finished = true

        if EndedConnection then
            EndedConnection:Disconnect()
            EndedConnection = nil
        end

        HitFeedbackRuntimeState.ActiveObjects[ Sound ] = nil

        if Sound.Parent then Sound:Destroy() end
    end

    EndedConnection = Sound.Ended:Connect( DestroySound)

    Sound:Play()

    task.delay( 6, DestroySound)

    return true
end

function Internal.PlayConfirmedHitSound()
    return Internal.PlayConfiguredHitFeedbackSound( HitFeedbackState.HitSound, HitFeedbackState.HitSoundVolume, HitFeedbackState.HitSoundPlaybackSpeed,
        "AtramentaConfirmedHitSound")
end

function Internal.PlayConfirmedFinishSound()
    return Internal.PlayConfiguredHitFeedbackSound( HitFeedbackState.FinishSound, HitFeedbackState.FinishSoundVolume,
        HitFeedbackState.FinishSoundPlaybackSpeed, "AtramentaConfirmedStompSound")
end

IsAtramentaFinishedTarget = function( Player, Character)
    if not Player or Player.Parent ~= Players then return true end

    if not Character or not Character.Parent then return true end

    local Humanoid = Character:FindFirstChildOfClass( "Humanoid")

    if Humanoid and Humanoid.Health <= 0 then return true end

    local Downed = Internal.GetAtramentaDownedObject( Player)

    return Downed == nil or Downed.Value ~= true
end

ConfirmAtramentaFinishSound = function( Player, Character, TokenOwner)
    if not Player or not TokenOwner or TokenOwner.FinishSoundPlayed == true or TokenOwner.TargetWasDowned ~= true then return false end

    if not IsAtramentaFinishedTarget( Player, Character ) then return false end

    TokenOwner.FinishSoundPlayed = true

    TokenOwner.FinishedDownedTarget = true

    TokenOwner.FinishConfirmedAt = os.clock()

    Internal.PlayConfirmedFinishSound()

    return true
end

WatchAtramentaFinishSound = function( Player, Character, TokenOwner)
    if not Player or not TokenOwner or TokenOwner.TargetWasDowned ~= true or TokenOwner.FinishSoundPlayed == true then return end

    HitFeedbackRuntimeState.FinishSerial += 1

    local Serial = HitFeedbackRuntimeState.FinishSerial

    TokenOwner.FinishWatchSerial = Serial

    task.spawn( function()
            local Started = os.clock()

            while TokenOwner.FinishSoundPlayed ~= true and TokenOwner.FinishWatchSerial == Serial and os.clock() - Started <= 3.50 do
                if ConfirmAtramentaFinishSound( Player, Character, TokenOwner ) then return end

                task.wait( 0.045)
            end
        end)
end

function Internal.SpawnDamageIndicator(TargetPart, Damage, IsHeadshot)
    if not HitFeedbackState.DamageIndicatorEnabled or not TargetPart or not TargetPart.Parent or not TargetPart:IsA("BasePart") or Damage <= 0 then return end
    local Parent = Internal.GetHitFeedbackGuiParent() if not Parent then return end
    local Anchor = Instance.new("Part")
    Anchor.Name = "AtramentaDamageAnchor"
    Anchor.Size = Vector3.new(0.05, 0.05, 0.05)
    Anchor.Transparency = 1
    Anchor.Anchored = true
    Anchor.CanCollide = false
    Anchor.CanTouch = false
    Internal.Call(function() Anchor.CanQuery = false end)
    Anchor.CFrame = CFrame.new(TargetPart.Position)
    Anchor.Parent = workspace
    HitFeedbackRuntimeState.ActiveObjects[Anchor] = true
    local Billboard = Instance.new("BillboardGui")
    Billboard.Name = "AtramentaDamageIndicator"
    Billboard.Adornee = Anchor Billboard.AlwaysOnTop = true
    Billboard.Enabled = true
    Billboard.Size = UDim2.fromOffset(150, 52)
    Billboard.StudsOffsetWorldSpace = Vector3.new(math.random(-35, 35) / 100, 2.1, math.random(-12, 12) / 100)
    Billboard.ZIndexBehavior = Enum.ZIndexBehavior.Global
    Internal.Call(function()
        Billboard.MaxDistance = AttackConfirmationState.ShotRange
        Billboard.LightInfluence = 0
    end)
    Billboard.Parent = Parent
    HitFeedbackRuntimeState.ActiveObjects[Billboard] = true
    local Label = Instance.new("TextLabel")
    Label.Name = "Damage"
    Label.AnchorPoint = Vector2.new(0.5, 0.5)
    Label.Position = UDim2.fromScale(0.5, 0.5)
    Label.Size = UDim2.fromScale(1, 1)
    Label.BackgroundTransparency = 1
    Label.BorderSizePixel = 0
    Label.FontFace = UiFont
    Label.Text = tostring(math.max(math.floor(Damage + 0.5), 1))
    Label.TextSize = math.max(tonumber(HitFeedbackState.DamageTextSize) or 18, 10)
    Label.TextColor3 = IsHeadshot and HitFeedbackState.HeadshotDamageColor or HitFeedbackState.DamageColor
    Label.TextStrokeColor3 = Color3.new(0, 0, 0)
    Label.TextStrokeTransparency = 0.05
    Label.TextTransparency = 0
    Label.TextWrapped = false
    Label.ZIndex = 1002
    Label.Parent = Billboard
    local Scale = Instance.new("UIScale")
    Scale.Scale = 0.82
    Scale.Parent = Label
    local Duration = math.max(tonumber(HitFeedbackState.DamageDuration) or 0.85, 0.20) local Rise = math.max(tonumber(HitFeedbackState.DamageRise) or 2.8, 0)
    TweenService:Create(Scale, TweenInfo.new(math.min(Duration * 0.35, 0.18), Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    TweenService:Create(Anchor, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Position = Anchor.Position + Vector3.new(0, Rise, 0) }):Play()
    task.delay(math.min(0.12, Duration * 0.20), function()
        if not Label.Parent then return end
        TweenService:Create(Label, TweenInfo.new(math.max(Duration * 0.80, 0.12), Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { TextTransparency = 1, TextStrokeTransparency = 1 })
            :Play()
    end)
    task.delay(Duration + 0.12, function()
        HitFeedbackRuntimeState.ActiveObjects[Billboard] = nil
        HitFeedbackRuntimeState.ActiveObjects[Anchor] = nil
        if Billboard.Parent then Billboard:Destroy() end
        if Anchor.Parent then Anchor:Destroy() end
    end)
end

WorldEffectsState = { Enabled = false, Effect = "Sakura", Intensity = 70, Radius = 65, Height = 42, Wind = 8, Folder = nil, Anchor = nil,
    Connection = nil, Generation = 0, SpawnAccumulator = 0, StepAccumulator = 0, WeatherActive = 0, SplashActive = 0, SplashLimit = 24, MaxPool = 144,
    UpdateRate = 30, RainRayParams = nil, RainFilterCharacter = nil, RainFilterCamera = nil, ProfileKey = nil, Profile = nil, Pool = {}, Active = {} }

HitParticleState = { Enabled = false, Style = "Sparks", Color = Color3.fromRGB(95, 255, 180), Count = 18, Lifetime = 0.55, Size = 0.22 }

local WorldEffectTextures = { Sakura = "rbxassetid://243660364", Rain = "rbxassetid://241876196", Snow = "rbxassetid://8158344433",
    Embers = "rbxassetid://1266170131", Fireflies = "rbxassetid://296874871" }

function Internal.ReleaseWorldBeamNode(Node)
    if not Node then return end
    if Node.IsSplash then
        WorldEffectsState.SplashActive = math.max((WorldEffectsState.SplashActive or 0) - 1, 0)
    else
        WorldEffectsState.WeatherActive = math.max((WorldEffectsState.WeatherActive or 0) - 1, 0)
    end
    Node.Active = false
    Node.IsSplash = false
    Node.Effect = nil
    Node.ImpactPosition = nil
    Node.ImpactNormal = nil
    Node.SurfacePoint = nil
    Node.SurfaceNormal = nil
    Node.Gravity = nil
    Node.Drag = nil
    Node.Bounces = nil
    Node.BaseCoreWidth = nil
    Node.BaseGlowWidth = nil
    if Node.Core then Node.Core.Enabled = false end
    if Node.Glow then Node.Glow.Enabled = false end
    if Node.A0 then Node.A0.Position = Vector3.new(0, -10000, 0) end
    if Node.A1 then Node.A1.Position = Vector3.new(0, -10000, 0) end
    if #WorldEffectsState.Pool < (WorldEffectsState.MaxPool or 144) then WorldEffectsState.Pool[#WorldEffectsState.Pool + 1] = Node end
end

function Internal.DestroyWorldEffects()
    WorldEffectsState.Generation += 1
    if WorldEffectsState.Connection then Internal.Call(function() WorldEffectsState.Connection:Disconnect() end) end
    WorldEffectsState.Connection = nil
    WorldEffectsState.Active = {}
    WorldEffectsState.Pool = {}
    if WorldEffectsState.Folder then Internal.Call(function() WorldEffectsState.Folder:Destroy() end) end
    WorldEffectsState.Folder = nil
    WorldEffectsState.Anchor = nil
    WorldEffectsState.SpawnAccumulator = 0
    WorldEffectsState.StepAccumulator = 0
    WorldEffectsState.WeatherActive = 0
    WorldEffectsState.SplashActive = 0
    WorldEffectsState.ProfileKey = nil
    WorldEffectsState.Profile = nil
    WorldEffectsState.RainFilterCharacter = nil
    WorldEffectsState.RainFilterCamera = nil
end

function CreateWorldBeamNode(Anchor)
    local A0 = Instance.new("Attachment")
    A0.Name = "Beam0"
    A0.Position = Vector3.new(0, -10000, 0)
    A0.Parent = Anchor local A1 = Instance.new("Attachment")
    A1.Name = "Beam1"
    A1.Position = Vector3.new(0, -10000, 0)
    A1.Parent = Anchor local Core = Instance.new("Beam")
    Core.Name = "Core"
    Core.Attachment0 = A0
    Core.Attachment1 = A1
    Core.Enabled = false
    Core.FaceCamera = true
    Core.LightInfluence = 0
    Core.LightEmission = 0.65
    Core.Brightness = 1
    Core.Segments = 1
    Core.Width0 = 0.04
    Core.Width1 = 0.01
    Core.Transparency = NumberSequence.new(0.15)
    Core.Parent = Anchor local Glow = Instance.new("Beam")
    Glow.Name = "Glow"
    Glow.Attachment0 = A0
    Glow.Attachment1 = A1
    Glow.Enabled = false
    Glow.FaceCamera = true
    Glow.LightInfluence = 0
    Glow.LightEmission = 1
    Glow.Brightness = 0.55
    Glow.Segments = 1
    Glow.Width0 = 0.10
    Glow.Width1 = 0.025
    Glow.Transparency = NumberSequence.new(0.82)
    Glow.Parent = Anchor return { A0 = A0, A1 = A1, Core = Core, Glow = Glow, Active = false }
end

function Internal.AcquireWorldBeamNode(Anchor)
    local Node = table.remove(WorldEffectsState.Pool)
    if not Node or not Node.A0 or not Node.A0.Parent then Node = CreateWorldBeamNode(Anchor) end
    Node.Active = true
    Node.Core.Enabled = true
    Node.Glow.Enabled = true
    return Node
end

function GetWorldEffectRainRayParams(CameraObject)
    local Params = WorldEffectsState.RainRayParams

    if not Params then
        Params = RaycastParams.new()
        Params.FilterType = Enum.RaycastFilterType.Exclude
        Params.IgnoreWater = false
        WorldEffectsState.RainRayParams = Params
    end

    local Character = LocalPlayer.Character

    if WorldEffectsState.RainFilterCharacter
            ~= Character or WorldEffectsState.RainFilterCamera
            ~= CameraObject then
        WorldEffectsState.RainFilterCharacter = Character

        WorldEffectsState.RainFilterCamera = CameraObject

        local Ignore = { WorldEffectsState.Folder }

        if Character then Ignore[#Ignore + 1] = Character end

        if CameraObject then Ignore[#Ignore + 1] = CameraObject end

        Params.FilterDescendantsInstances = Ignore
    end

    return Params
end

function GetWorldEffectProfile()
    local Effect = tostring( WorldEffectsState.Effect or "Sakura")

    local Intensity = math.clamp( tonumber(WorldEffectsState.Intensity) or 70, 5, 250)

    local Key = Effect .. ":" .. tostring( math.floor( Intensity * 10 + 0.5 ))

    if WorldEffectsState.ProfileKey
            == Key and type( WorldEffectsState.Profile ) == "table" then
        return WorldEffectsState.Profile
    end

    local Rate = Effect == "Rain" and math.clamp( Intensity * 0.36, 6, 88 ) or Effect == "Snow" and math.clamp( Intensity * 0.16, 3, 40)
        or Effect == "Sakura" and math.clamp( Intensity * 0.10, 2, 26 ) or Effect == "Embers" and math.clamp( Intensity * 0.10, 2, 26 ) or math.clamp(
            Intensity * 0.045, 1, 12)

    local ActiveLimit = Effect == "Rain" and 72 or Effect == "Snow" and 64 or Effect == "Sakura" and 52 or Effect == "Embers" and 48 or 36

    local Profile = { Effect = Effect, Intensity = Intensity, Rate = Rate, ActiveLimit = ActiveLimit }

    WorldEffectsState.ProfileKey = Key

    WorldEffectsState.Profile = Profile

    return Profile
end

function Internal.ConfigureWorldBeamNode(Node, Effect, CameraObject)
    local Radius = math.max(tonumber(WorldEffectsState.Radius) or 65, 15) local Height = math.max(tonumber(WorldEffectsState.Height) or 42, 12)
    local Wind = tonumber(WorldEffectsState.Wind) or 0 local CameraFrame = CameraObject.CFrame
    local CameraPosition = CameraFrame.Position local Forward = Vector3.new(CameraFrame.LookVector.X, 0, CameraFrame.LookVector.Z)
    if Forward.Magnitude <= 0.05 then Forward = Vector3.new(0, 0, -1) else Forward = Forward.Unit end
    local Right = Vector3.new(-Forward.Z, 0, Forward.X) local Side = (math.random() * 2 - 1) * Radius local Front = (math.random() ^ 0.72) * Radius + 5 local Phase = math.random() * math.pi * 2
    Node.Effect = Effect
    Node.IsSplash = false
    Node.Age = 0
    Node.Phase = Phase
    Node.ImpactPosition = nil
    Node.ImpactNormal = nil
    Node.Curve = 0
    Node.Sway = Right * (0.4 + math.random() * 1.2) + Forward * (math.random() * 0.5 - 0.25)
    Node.Frequency = 0.8 + math.random() * 2.8
    Node.Position = CameraPosition + Forward * Front + Right * Side
    Node.Core.Texture = ""
    Node.Glow.Texture = ""
    Node.Core.CurveSize0 = 0
    Node.Core.CurveSize1 = 0
    Node.Glow.CurveSize0 = 0
    Node.Glow.CurveSize1 = 0
    Node.Core.Brightness = 1
    Node.Glow.Brightness = 0.52
    if Effect == "Rain" then
        Node.Position += Vector3.new(0, Height * (0.55 + math.random() * 0.75), 0)
        Node.Velocity = Vector3.new(Wind * 0.72, -(88 + math.random() * 52), Wind * 0.10)
        Node.Length = 4.5 + math.random() * 5.5
        Node.Lifetime = 1.2 + math.random() * 0.65
        Node.Core.Segments = 1
        Node.Glow.Segments = 1
        Node.Core.Width0, Node.Core.Width1 = 0.028, 0.004
        Node.Glow.Width0, Node.Glow.Width1 = 0.085, 0.012
        Node.Core.Color = ColorSequence.new(Color3.fromRGB(188, 220, 255), Color3.fromRGB(238, 248, 255))
        Node.Glow.Color = ColorSequence.new(Color3.fromRGB(95, 165, 255), Color3.fromRGB(210, 235, 255))
        Node.Core.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.06), NumberSequenceKeypoint.new(0.82, 0.24), NumberSequenceKeypoint.new(1, 0.92) })
        Node.Glow.Transparency = NumberSequence.new(0.87)
        if math.random() < 0.22 and (WorldEffectsState.SplashLimit or 0) > 0 then
            local Parameters = GetWorldEffectRainRayParams( CameraObject)

            local Direction = Node.Velocity.Unit * math.min(Node.Velocity.Magnitude * Node.Lifetime, 190) local Result = workspace:Raycast(Node.Position, Direction, Parameters)
            if Result then
                Node.Lifetime = math.max(Result.Distance / math.max(Node.Velocity.Magnitude, 1), 0.08)
                Node.ImpactPosition = Result.Position
                Node.ImpactNormal = Result.Normal
            end
        end
    elseif Effect == "Sakura" then
        Node.Position += Vector3.new(0, math.random() * Height * 0.90 - Height * 0.08, 0)
        Node.Velocity = Vector3.new(Wind * 0.28, -(3.2 + math.random() * 4.3), Wind * 0.06)
        Node.Length = 0.52 + math.random() * 0.55
        Node.Lifetime = 5.2 + math.random() * 4.2
        Node.Sway *= 1.8
        Node.Core.Segments = 7
        Node.Glow.Segments = 7
        Node.Core.Width0, Node.Core.Width1 = 0.18, 0.018
        Node.Glow.Width0, Node.Glow.Width1 = 0.29, 0.035
        Node.Core.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 126, 190)), ColorSequenceKeypoint.new(0.55, Color3.fromRGB(255, 218, 237)), ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 160, 210)) })
        Node.Glow.Color = ColorSequence.new(Color3.fromRGB(255, 118, 193), Color3.fromRGB(255, 225, 242))
        Node.Core.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.10), NumberSequenceKeypoint.new(0.62, 0.04), NumberSequenceKeypoint.new(1, 0.90) })
        Node.Glow.Transparency = NumberSequence.new(0.88)
    elseif Effect == "Snow" then
        Node.Position += Vector3.new(0, math.random() * Height, 0)
        Node.Velocity = Vector3.new(Wind * 0.11, -(2.1 + math.random() * 3.4), Wind * 0.03)
        Node.Length = 0.14 + math.random() * 0.26
        Node.Lifetime = 6.5 + math.random() * 5.5
        Node.Sway *= 1.35
        Node.Core.Segments = 3
        Node.Glow.Segments = 3
        Node.Core.Width0, Node.Core.Width1 = 0.075, 0.018
        Node.Glow.Width0, Node.Glow.Width1 = 0.15, 0.035
        Node.Core.Color = ColorSequence.new(Color3.fromRGB(235, 246, 255), Color3.fromRGB(255, 255, 255))
        Node.Glow.Color = ColorSequence.new(Color3.fromRGB(180, 220, 255), Color3.fromRGB(255, 255, 255))
        Node.Core.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.04), NumberSequenceKeypoint.new(1, 0.72) })
        Node.Glow.Transparency = NumberSequence.new(0.88)
    elseif Effect == "Embers" then
        Node.Position += Vector3.new(0, math.random() * math.min(Height, 14) - 3, 0)
        Node.Velocity = Vector3.new(Wind * 0.12, 5.5 + math.random() * 10.5, Wind * 0.025)
        Node.Length = 0.35 + math.random() * 0.85
        Node.Lifetime = 2.1 + math.random() * 3.0
        Node.Sway *= 0.85
        Node.Core.Segments = 4
        Node.Glow.Segments = 4
        Node.Core.Width0, Node.Core.Width1 = 0.052, 0.004
        Node.Glow.Width0, Node.Glow.Width1 = 0.16, 0.012
        Node.Core.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 250, 155)), ColorSequenceKeypoint.new(0.45, Color3.fromRGB(255, 154, 38)), ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 45, 8)) })
        Node.Glow.Color = ColorSequence.new(Color3.fromRGB(255, 205, 70), Color3.fromRGB(255, 55, 10))
        Node.Core.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 0.90) })
        Node.Glow.Transparency = NumberSequence.new(0.78)
        Node.Core.Brightness = 1.35
        Node.Glow.Brightness = 0.85
    elseif Effect == "Fireflies" then
        Node.Position += Vector3.new(0, math.random() * math.min(Height, 24) - 4, 0)
        Node.Velocity = Vector3.new(Wind * 0.018, math.random() * 0.5 - 0.25, 0)
        Node.Length = 0.07 + math.random() * 0.10
        Node.Lifetime = 4.0 + math.random() * 5.0
        Node.Sway *= 0.72
        Node.Core.Segments = 2
        Node.Glow.Segments = 2
        Node.Core.Width0, Node.Core.Width1 = 0.11, 0.055
        Node.Glow.Width0, Node.Glow.Width1 = 0.32, 0.16
        Node.Core.Color = ColorSequence.new(Color3.fromRGB(255, 255, 190), Color3.fromRGB(155, 255, 74))
        Node.Glow.Color = ColorSequence.new(Color3.fromRGB(225, 255, 95), Color3.fromRGB(115, 255, 45))
        Node.Core.Transparency = NumberSequence.new(0.04)
