function GameVisualState:GetRoot()
    if self.Root and self.Root.Parent then return self.Root end
    local Parent = Internal.GetHitFeedbackGuiParent()
    if not Parent then return nil end
    local Root = Instance.new("Folder")
    Root.Name = "AtramentaGameVisuals"
    Root.Parent = Parent
    self.Root = Root
    return Root
end

function GameVisualState:GetPart(Object)
    if not Object then return nil end
    if Object:IsA("BasePart") then return Object end
    if Object:IsA("Model") then
        return Object.PrimaryPart or Object:FindFirstChild("WeaponHandle", true) or Object:FindFirstChild("Handle", true) or Object:FindFirstChildWhichIsA("BasePart", true)
    end
    return Object:FindFirstChildWhichIsA("BasePart", true)
end

function GameVisualState:CreateBillboard(Part, Color, Width)
    local Root = self:GetRoot()
    if not Root or not Part then return nil end
    local Gui = Instance.new("BillboardGui")
    Gui.Name = "AtramentaObjectESP"
    Gui.Adornee = Part
    Gui.AlwaysOnTop = true
    Gui.LightInfluence = 0
    Gui.MaxDistance = 5000
    Gui.Size = UDim2.fromOffset(Width or 190, 52)
    Gui.StudsOffsetWorldSpace = Vector3.new(0, 2.35, 0)
    Gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    Gui.Parent = Root
    local Frame = Instance.new("Frame")
    Frame.Name = "Frame"
    Frame.Size = UDim2.fromScale(1, 1)
    Frame.BackgroundColor3 = Color3.fromRGB(10, 13, 14)
    Frame.BackgroundTransparency = 0.18
    Frame.BorderSizePixel = 0
    Frame.Parent = Gui
    local Corner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(0, 7)
    Corner.Parent = Frame
    local Stroke = Instance.new("UIStroke")
    Stroke.Color = Color Stroke.Thickness = 1.25
    Stroke.Transparency = 0.15
    Stroke.Parent = Frame
    local NameLabel = Instance.new("TextLabel")
    NameLabel.Name = "Name"
    NameLabel.BackgroundTransparency = 1
    NameLabel.Position = UDim2.fromOffset(8, 3)
    NameLabel.Size = UDim2.new(1, -16, 0, 22)
    NameLabel.FontFace = UiFont
    NameLabel.TextColor3 = Color NameLabel.TextSize = 13
    NameLabel.TextStrokeTransparency = 0.45
    NameLabel.TextXAlignment = Enum.TextXAlignment.Left
    NameLabel.Parent = Frame
