    return { Gui = Gui, Frame = Frame, Stroke = Stroke, Name = NameLabel, Info = InfoLabel }
end

function GameVisualState:GetThrowableDefinition(Object)
    if not Object then return nil end
    local Search = string.lower(Object.Name)
    for _, Descendant in ipairs(Object:GetDescendants()) do
        Search = Search .. " " .. string.lower(Descendant.Name)
    end
    for _, Definition in ipairs(self.ThrowableDefinitions) do
        if string.find(Search, Definition.Key, 1, true) then return Definition end
    end
    return nil
end

function GameVisualState:IsExcludedDebris(Object)
    local Name = string.lower(Object.Name)
    return string.find(Name, "bullethole", 1, true) ~= nil or string.find(Name, "magpart", 1, true) ~= nil or Name == "nparts" or Name == "vparts"
        or Name == "toclear" or Name == "bloodinstances"
end

function GameVisualState:RemoveObject(Object)
    local Entry = self.Grenades.Objects[Object] or self.Dropped.Objects[Object] if not Entry then return end
    if Entry.Connection then Entry.Connection:Disconnect() end
    if Entry.Gui and Entry.Gui.Parent then Entry.Gui:Destroy() end
    if Entry.Highlight and Entry.Highlight.Parent then Entry.Highlight:Destroy() end
    if Entry.Trail and Entry.Trail.Parent then Entry.Trail:Destroy() end
    if Entry.A0 and Entry.A0.Parent then Entry.A0:Destroy() end
    if Entry.A1 and Entry.A1.Parent then Entry.A1:Destroy() end
    if Entry.Zone and Entry.Zone.Parent then Entry.Zone:Destroy() end
    self.Grenades.Objects[Object] = nil
    self.Dropped.Objects[Object] = nil
end

function GameVisualState:CreateMolotovZone(Object, Part)
    if not self.Grenades.MolotovZone then return nil end
    local Zone = Instance.new("Part")
    Zone.Name = "AtramentaMolotovZone"
    Zone.Anchored = true
    Zone.CanCollide = false
    Zone.CanTouch = false
    Zone.CanQuery = false
    Zone.CastShadow = false
    Zone.Material = Enum.Material.Neon
    Zone.Shape = Enum.PartType.Cylinder
    Zone.Color = self.Grenades.MolotovColor Zone.Transparency = 0.78
    Zone.Size = Vector3.new(0.035, math.max(Part.Size.X, 20), math.max(Part.Size.Z, 20))
    Zone.CFrame = Part.CFrame * CFrame.Angles(0, 0, math.rad(90))
    Zone.Parent = workspace
    local Highlight = Instance.new("Highlight")
    Highlight.Name = "AtramentaMolotovZoneGlow"
    Highlight.Adornee = Zone
    Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    Highlight.FillColor = self.Grenades.MolotovColor Highlight.FillTransparency = 0.82
    Highlight.OutlineColor = Color3.fromRGB(255, 202, 98)
    Highlight.OutlineTransparency = 0.12
    Highlight.Parent = Zone
    return Zone
end

function GameVisualState:TrackGrenade(Object)
    if not self.Grenades.Enabled or not Object or not Object.Parent or self.Grenades.Objects[Object] or self:IsExcludedDebris(Object) then return end
    local Part = self:GetPart(Object) if not Part then return end
    local IsMolotovArea = Object.Name == "MolotovExplosion" or Part.Name == "MolotovExplosion" local Definition = self:GetThrowableDefinition(Object)
    if IsMolotovArea then
        Definition = { Name = "MOLOTOV FIRE", Fuse = 23.36, Color = self.Grenades.MolotovColor }
    elseif not Definition then
        local Speed = Part.AssemblyLinearVelocity.Magnitude
        if Speed < 24 or Part.Size.Magnitude > 14 then return end
        Definition = { Name = "THROWABLE", Fuse = 3, Color = self.Grenades.Color }
    end
    local Visual = self:CreateBillboard(Part, Definition.Color, 190) if not Visual then return end
    Visual.Name.Text = Definition.Name
    local Entry = { Object = Object, Part = Part, Gui = Visual.Gui, Name = Visual.Name, Info = Visual.Info, Stroke = Visual.Stroke, Started = os.clock(),
        Fuse = Definition.Fuse, Color = Definition.Color, Kind = IsMolotovArea and "MolotovArea" or "Projectile" }
    if IsMolotovArea then
        Entry.Zone = self:CreateMolotovZone(Object, Part)
    else
        local Highlight = Instance.new("Highlight")
        Highlight.Name = "AtramentaGrenadeHighlight"
        Highlight.Adornee = Object
        Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        Highlight.FillColor = Definition.Color Highlight.FillTransparency = 0.58
        Highlight.OutlineColor = Color3.new(1, 1, 1)
        Highlight.OutlineTransparency = 0.12
        Highlight.Parent = Object
        Entry.Highlight = Highlight
        if self.Grenades.Trail then
            local A0 = Instance.new("Attachment")
            A0.Position = Vector3.new(0, 0, -0.22)
            A0.Parent = Part
            local A1 = Instance.new("Attachment")
            A1.Position = Vector3.new(0, 0, 0.22)
            A1.Parent = Part
            local Trail = Instance.new("Trail")
            Trail.Name = "AtramentaGrenadeTrail"
            Trail.Attachment0 = A0
            Trail.Attachment1 = A1
            Trail.FaceCamera = true
            Trail.LightEmission = 1
            Trail.Lifetime = 0.45
            Trail.MinLength = 0.05
            Trail.Color = ColorSequence.new(Definition.Color, Color3.new(1, 1, 1))
            Trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.10), NumberSequenceKeypoint.new(1, 1) })
            Trail.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.42), NumberSequenceKeypoint.new(1, 0) })
            Trail.Parent = Part
            Entry.A0 = A0
            Entry.A1 = A1
            Entry.Trail = Trail
        end
    end
    Entry.Connection = Object.AncestryChanged:Connect(function(_, Parent)
        if not Parent then self:RemoveObject(Object) end
    end)
    self.Grenades.Objects[Object] = Entry
end

function GameVisualState:BindGrenadeFolder()
    local Folder = workspace:FindFirstChild("Debbris")
    if Folder == self.Grenades.Folder and self.Grenades.Connection then return end
    if self.Grenades.Connection then self.Grenades.Connection:Disconnect() end
    self.Grenades.Connection = nil
    self.Grenades.Folder = Folder
    if not Folder then return end
    self.Grenades.Connection = Folder.ChildAdded:Connect(function(Object)
        task.delay(0.08, function() self:TrackGrenade(Object) end)
    end)
    for _, Object in ipairs(Folder:GetChildren()) do
        task.defer(function() self:TrackGrenade(Object) end)
    end
end

function GameVisualState:GetDroppedName(Object, Kind)
    if Kind == "Pile" then return Object.Name == "S2" and "LOOT PILE S2" or "LOOT PILE S1" end
    if Kind == "Bread" then return "CASH" end
    if Object:FindFirstChild("Shiv", true) then return "SHIV" end
    if Object:FindFirstChild("Slide", true) and Object:FindFirstChild("Barrel", true) and Object:FindFirstChild("MagPart", true) then return "FIREARM" end
    if Object:FindFirstChild("HandleMeshPart", true) then return "MELEE" end
    if Object:FindFirstChild("WeaponHandle", true) and Object:FindFirstChild("Barrel", true) then return "FIREARM" end
    if Object.Name ~= "Model" and Object.Name ~= "S1" and Object.Name ~= "S2" then return string.upper(Object.Name) end
    return "DROPPED WEAPON"
end

function GameVisualState:TrackDropped(Object, Kind)
    if not Object or not Object.Parent or self.Dropped.Objects[Object] then return end
    if Kind == "Weapon" and not self.Dropped.Weapons then return end
    if Kind == "Pile" and not self.Dropped.Piles then return end
    if Kind == "Bread" and not self.Dropped.Bread then return end
    local Part = self:GetPart(Object) if not Part then return end
    local Color = Kind == "Weapon" and self.Dropped.WeaponColor or Kind == "Pile" and self.Dropped.PileColor or self.Dropped.BreadColor
    local Visual = self:CreateBillboard(Part, Color, 180) if not Visual then return end
    local Name = self:GetDroppedName(Object, Kind)
    Visual.Name.Text = Name
    local Highlight = Instance.new("Highlight")
    Highlight.Name = "AtramentaDroppedHighlight"
    Highlight.Adornee = Object
    Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    Highlight.FillColor = Color Highlight.FillTransparency = 0.72
    Highlight.OutlineColor = Color Highlight.OutlineTransparency = 0.08
    Highlight.Parent = Object
    local Entry = { Object = Object, Part = Part, Gui = Visual.Gui, Name = Visual.Name, Info = Visual.Info, Stroke = Visual.Stroke, Highlight = Highlight,
        Kind = Kind, DisplayName = Name }
    Entry.Connection = Object.AncestryChanged:Connect(function(_, Parent)
        if not Parent then self:RemoveObject(Object) end
    end)
    self.Dropped.Objects[Object] = Entry
end

function GameVisualState:BindDroppedFolder(Folder, Kind)
    if not Folder then return end
    local Existing = self.Dropped.FolderConnections[Folder]
    if Existing then
        for _, Object in ipairs(Folder:GetChildren()) do self:TrackDropped(Object, Kind) end
        return
    end

    self.Dropped.Folders[Folder] = Kind
    local Connections = {}
    self.Dropped.FolderConnections[Folder] = Connections
    Connections[1] = Folder.ChildAdded:Connect(function(Object) task.defer(function() self:TrackDropped(Object, Kind) end) end)
    Connections[2] = Folder.ChildRemoved:Connect(function(Object) self:RemoveObject(Object) end)
    for _, Object in ipairs(Folder:GetChildren()) do self:TrackDropped(Object, Kind) end
end

function GameVisualState:RefreshDroppedFolders()
    for Folder, Connections in pairs(self.Dropped.FolderConnections) do
        if not Folder or not Folder.Parent then
            for _, Connection in ipairs(Connections) do if Connection then Connection:Disconnect() end end
            self.Dropped.FolderConnections[Folder] = nil
            self.Dropped.Folders[Folder] = nil
        end
    end

    local Filter = workspace:FindFirstChild("Filter") if not Filter then return end
    self:BindDroppedFolder(Filter:FindFirstChild("SpawnedTools"), "Weapon")
    self:BindDroppedFolder(Filter:FindFirstChild("SpawnedPiles"), "Pile")
    self:BindDroppedFolder(Filter:FindFirstChild("SpawnedBread"), "Bread")
end

function GameVisualState:ClearDroppedKind(Kind)
    local Objects = {}
    for Object, Entry in pairs(self.Dropped.Objects) do
        if not Kind or Entry.Kind == Kind then Objects[#Objects + 1] = Object end
    end
    for _, Object in ipairs(Objects) do self:RemoveObject(Object) end
end

function GameVisualState:IsNeeded()
    return self.Grenades.Enabled == true or self.Dropped.Weapons == true or self.Dropped.Piles == true or self.Dropped.Bread == true
end

function GameVisualState:StopIfIdle()
    if self.Dropped.Weapons ~= true and self.Dropped.Piles ~= true and self.Dropped.Bread ~= true then
        for Folder, Connections in pairs(self.Dropped.FolderConnections) do
            for _, Connection in ipairs(Connections) do if Connection then Connection:Disconnect() end end
            self.Dropped.FolderConnections[Folder] = nil
            self.Dropped.Folders[Folder] = nil
        end
    end

    if self:IsNeeded() then return false end

    if self.Connection then
        self.Connection:Disconnect()
        self.Connection = nil
    end

    self.Clock = 0
    self.FolderClock = 0
    return true
end

function GameVisualState:SetGrenadesEnabled(Value)
    Value = Value == true
    if self.Grenades.Enabled == Value then
        if Value then self:Start() end
        return
    end

    self.Grenades.Enabled = Value

    if Value then
        self:BindGrenadeFolder()
        self:Start()
        Internal.Call(self.UpdateObjects, self)
        return
    end

    if self.Grenades.Connection then
        self.Grenades.Connection:Disconnect()
        self.Grenades.Connection = nil
    end
    self.Grenades.Folder = nil

    local Objects = {}
    for Object in pairs(self.Grenades.Objects) do Objects[#Objects + 1] = Object end
    for Index = 1, #Objects do self:RemoveObject(Objects[Index]) end

    self:StopIfIdle()
end

function GameVisualState:UpdateObjects()
    local Character = LocalPlayer.Character local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
    local Position = RootPart and RootPart.Position local CurrentTime = os.clock()
    local GrenadeObjects = {}
    for Object, Entry in pairs(self.Grenades.Objects) do
        if not Object.Parent or not Entry.Part or not Entry.Part.Parent or not Entry.Gui or not Entry.Gui.Parent
            or not Entry.Info or not Entry.Info.Parent or not Entry.Stroke or not Entry.Stroke.Parent
        then
            GrenadeObjects[#GrenadeObjects + 1] = Object
        else
            local Distance = Position and (Position - Entry.Part.Position).Magnitude or 0
            local Remaining = Entry.Fuse and math.max(Entry.Fuse - (CurrentTime - Entry.Started), 0) or nil
            Entry.Gui.Enabled = self.Grenades.Enabled and Distance <= self.Grenades.MaxDistance
            Entry.Info.Text = Remaining and string.format("%.1fs   %.0f studs", Remaining, Distance) or string.format("%.0f studs", Distance)
            local Pulse = 0.18 + (math.sin(CurrentTime * 8) + 1) * 0.17
            Entry.Stroke.Transparency = Pulse
            if Entry.Zone then
                Entry.Zone.CFrame = Entry.Part.CFrame * CFrame.Angles(0, 0, math.rad(90))
                Entry.Zone.Transparency = 0.74 + (math.sin(CurrentTime * 5) + 1) * 0.06
                local FireValue = Object:FindFirstChild("FireV")
                if FireValue and FireValue:IsA("BoolValue") and not FireValue.Value then GrenadeObjects[#GrenadeObjects + 1] = Object end
            end
        end
    end
    for _, Object in ipairs(GrenadeObjects) do self:RemoveObject(Object) end
    local DroppedObjects = {}
    for Object, Entry in pairs(self.Dropped.Objects) do
        if not Object.Parent or not Entry.Part or not Entry.Part.Parent or not Entry.Gui or not Entry.Gui.Parent
            or not Entry.Info or not Entry.Info.Parent or not Entry.Highlight or not Entry.Highlight.Parent
        then
            DroppedObjects[#DroppedObjects + 1] = Object
        else
            local Distance = Position and (Position - Entry.Part.Position).Magnitude or 0
            local Enabled = Entry.Kind == "Weapon" and self.Dropped.Weapons or Entry.Kind == "Pile" and self.Dropped.Piles or Entry.Kind == "Bread" and self.Dropped.Bread
            Entry.Gui.Enabled = Enabled and Distance <= self.Dropped.MaxDistance
            Entry.Highlight.Enabled = Entry.Gui.Enabled
            Entry.Info.Text = string.format("%.0f studs", Distance)
        end
    end
    for _, Object in ipairs(DroppedObjects) do self:RemoveObject(Object) end
end

function GameVisualState:Start()
    if self.Connection then return end
    self.Destroyed = false
    local Previous = rawget(Environment, "AtramentaGameVisualRuntime")
    if Previous and Previous ~= self and type(Previous.Destroy) == "function" then Internal.Call(function() Previous:Destroy() end) end
    rawset(Environment, "AtramentaGameVisualRuntime", self)
    self.Connection = RunService.Heartbeat:Connect(function(DeltaTime)
        if not self:IsNeeded() then
            self:StopIfIdle()
            return
        end

        DeltaTime = math.clamp(tonumber(DeltaTime) or 0, 0, 0.10)
        self.Clock += DeltaTime
        self.FolderClock += DeltaTime

        if self.FolderClock >= 1 then
            self.FolderClock = self.FolderClock % 1
            if self.Grenades.Enabled then self:BindGrenadeFolder() end
            if self.Dropped.Weapons or self.Dropped.Piles or self.Dropped.Bread then self:RefreshDroppedFolders() end
        end

        if self.Clock < 0.1 then return end
        self.Clock = self.Clock % 0.1
        self:UpdateObjects()
    end)
end

function GameVisualState:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    if self.Connection then self.Connection:Disconnect() self.Connection = nil end
    if self.Grenades.Connection then self.Grenades.Connection:Disconnect() self.Grenades.Connection = nil end
    for _, Connection in ipairs(self.Dropped.Connections) do Connection:Disconnect() end
    self.Dropped.Connections = {}
    for Folder, Connections in pairs(self.Dropped.FolderConnections) do
        for _, Connection in ipairs(Connections) do if Connection then Connection:Disconnect() end end
        self.Dropped.FolderConnections[Folder] = nil
    end
    self.Dropped.FolderConnections = setmetatable({}, {__mode = "k"})
    self.Dropped.Folders = setmetatable({}, { __mode = "k" })
    local Objects = {}
    for Object in pairs(self.Grenades.Objects) do Objects[#Objects + 1] = Object end
    for Object in pairs(self.Dropped.Objects) do Objects[#Objects + 1] = Object end
    for _, Object in ipairs(Objects) do self:RemoveObject(Object) end
    if self.Root then self.Root:Destroy() self.Root = nil end
    if rawget(Environment, "AtramentaGameVisualRuntime") == self then rawset(Environment, "AtramentaGameVisualRuntime", nil) end
end

