function ExtendedVisualState:DestroyAura()
    if self.Aura.Attachment then self.Aura.Attachment:Destroy() end
    self.Aura.Attachment = nil
    self.Aura.Emitter = nil
    self.Aura.Character = nil
end

function ExtendedVisualState:CreateAura()
    if not self.Aura.Enabled then
        self:DestroyAura()
        return
    end

    local Character = LocalPlayer.Character local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")

    if not RootPart then return end

    if self.Aura.Character == Character and self.Aura.Attachment and self.Aura.Attachment.Parent == RootPart and self.Aura.Emitter
        and self.Aura.Emitter.Parent == self.Aura.Attachment
    then
        return
    end

    self:DestroyAura()

    for _, Object in ipairs(RootPart:GetChildren()) do
        if Object:IsA("Attachment") and Object.Name == "AtramentaParticleAura" then Object:Destroy() end
    end

    local Preset = self.AuraPresets[self.Aura.Preset] or self.AuraPresets.Heavenly

    local Attachment = Instance.new("Attachment")
    Attachment.Name = "AtramentaParticleAura"
    Attachment.Parent = RootPart

    local Emitter = Instance.new("ParticleEmitter")
    Emitter.Name = "Aura"
    Emitter.Texture = Preset.Texture
    Emitter.Rate = self.Aura.Rate or Preset.Rate
    Emitter.Speed = Preset.Speed
    Emitter.Lifetime = Preset.Lifetime
    Emitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, Preset.Size), NumberSequenceKeypoint.new(0.75, Preset.Size),
        NumberSequenceKeypoint.new(1, 0) })
    Emitter.Rotation = NumberRange.new(0, 360)
    Emitter.RotSpeed = NumberRange.new(-100, 100)
    Emitter.SpreadAngle = Vector2.new(180, 180)
    Emitter.LightEmission = Preset.LightEmission
    Emitter.Color = ColorSequence.new( self.Aura.Color, Color3.new(1, 1, 1))
    Emitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.08), NumberSequenceKeypoint.new(1, 1) })
    Emitter.Parent = Attachment

    self.Aura.Attachment = Attachment
    self.Aura.Emitter = Emitter
    self.Aura.Character = Character
end

function ExtendedVisualState:DestroyTrail()
    for _, Object in ipairs(self.Trail.Objects) do if Object and Object.Parent then Object:Destroy() end end
    self.Trail.Objects = {}
    self.Trail.Character = nil
end

function ExtendedVisualState:CreateTrail()
    if not self.Trail.Enabled then
        self:DestroyTrail()
        return
    end

    local Character = LocalPlayer.Character local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")

    if not RootPart then return end

    if self.Trail.Character == Character and #self.Trail.Objects > 0 and self.Trail.Objects[1] and self.Trail.Objects[1].Parent == RootPart then return end

    self:DestroyTrail()

    for _, Object in ipairs(RootPart:GetChildren()) do
        local Name = Object.Name

        if Name == "AtramentaCharacterTrail" or Name == "AtramentaMovementTrail" or Name == "AtramentaMovementTrail0"
            or Name == "AtramentaMovementTrail1"
        then
            Object:Destroy()
        end
    end

    local A0 = Instance.new("Attachment")
    A0.Name = "AtramentaMovementTrail0"
    A0.Position = Vector3.new(-0.8, -1.8, 0.45)
    A0.Parent = RootPart

    local A1 = Instance.new("Attachment")
    A1.Name = "AtramentaMovementTrail1"
    A1.Position = Vector3.new(0.8, -1.8, 0.45)
    A1.Parent = RootPart

    local Trail = Instance.new("Trail")
    Trail.Name = "AtramentaMovementTrail"
    Trail.Attachment0 = A0
    Trail.Attachment1 = A1
    Trail.FaceCamera = true
    Trail.LightEmission = 1
    Trail.Lifetime = self.Trail.Lifetime
    Trail.MinLength = 0.05
    Trail.Color = ColorSequence.new( self.Trail.Color, self.Trail.GradientColor)
    Trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.06), NumberSequenceKeypoint.new(1, 1) })
    Trail.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) })
    Trail.Parent = RootPart

    self.Trail.Objects = {Trail, A0, A1}
    self.Trail.Character = Character
end

function ExtendedVisualState:DestroyJumpCircles()
    for Index = #self.JumpCircles.Active, 1, -1 do
        local Entry = self.JumpCircles.Active[Index]
        if Entry and Entry.Holder and Entry.Holder.Parent then Entry.Holder:Destroy() end
        table.remove(self.JumpCircles.Active, Index)
    end

    self.JumpCircles.LastFloor = nil
    self.JumpCircles.Character = nil
    self.JumpCircles.WasAirborne = false
    self.JumpCircles.JumpArmed = false
    self.JumpCircles.JumpStartedAt = 0
end

function ExtendedVisualState:EmitJumpCircle(Position)
    if not self.JumpCircles.Enabled or typeof(Position) ~= "Vector3" then return end

    local Holder = Instance.new("Part")
    Holder.Name = "AtramentaJumpCircle"
    Holder.Anchored = true
    Holder.CanCollide = false
    Holder.CanTouch = false
    Holder.CanQuery = false
    Holder.CastShadow = false
    Holder.Transparency = 1
    Holder.Size = Vector3.new(0.1, 0.1, 0.1)
    Holder.CFrame = CFrame.new(Position + Vector3.new(0, 0.035, 0))
    Holder.Parent = workspace

    local Segments = math.clamp(math.floor(tonumber(self.JumpCircles.Segments) or 28), 12, 48) local Attachments = table.create(Segments)
    local Beams = table.create(Segments) local StartRadius = 0.65

    for Index = 1, Segments do
        local Angle = ((Index - 1) / Segments) * math.pi * 2 local Attachment = Instance.new("Attachment")
        Attachment.Name = "Point" .. tostring(Index)
        Attachment.Position = Vector3.new( math.cos(Angle) * StartRadius, 0, math.sin(Angle) * StartRadius)
        Attachment.Parent = Holder
        Attachments[Index] = Attachment
    end

    for Index = 1, Segments do
        local Beam = Instance.new("Beam")
        Beam.Name = "Segment" .. tostring(Index)
        Beam.Attachment0 = Attachments[Index]
        Beam.Attachment1 = Attachments[Index % Segments + 1]
        Beam.FaceCamera = true
        Beam.LightEmission = 1
        Beam.LightInfluence = 0
        Beam.Width0 = self.JumpCircles.Width
        Beam.Width1 = self.JumpCircles.Width
        Beam.Color = ColorSequence.new(self.JumpCircles.Color)
        Beam.Transparency = NumberSequence.new(0.06)
        Beam.Parent = Holder
        Beams[Index] = Beam
    end

    self.JumpCircles.Active[#self.JumpCircles.Active + 1] = { Holder = Holder, Attachments = Attachments, Beams = Beams, Time = 0, Segments = Segments,
        StartRadius = StartRadius }
end

function ExtendedVisualState:GetJumpCircleLandingPosition(Character, RootPart)
    if not Character or not RootPart then return nil end

    local Params = RaycastParams.new()
    Params.FilterType = Enum.RaycastFilterType.Exclude
    Params.FilterDescendantsInstances = {Character}
    Params.IgnoreWater = false

    local Result = workspace:Raycast( RootPart.Position + Vector3.new(0, 0.6, 0), Vector3.new(0, -8, 0), Params)

    if Result then return Result.Position + Result.Normal * 0.035 end
    return RootPart.Position - Vector3.new(0, 2.85, 0)
end

function ExtendedVisualState:UpdateJumpCircles(DeltaTime)
    local Circles = self.JumpCircles local Character = LocalPlayer.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")

    if Circles.Enabled and Humanoid and RootPart then
        local FloorMaterial = Humanoid.FloorMaterial local State = Humanoid:GetState() local Grounded = FloorMaterial ~= Enum.Material.Air

        if Circles.Character ~= Character then
            Circles.Character = Character
            Circles.LastFloor = FloorMaterial Circles.WasAirborne = not Grounded
            Circles.JumpArmed = false
            Circles.JumpStartedAt = 0
        else
            local PreviousGrounded = Circles.LastFloor ~= nil and Circles.LastFloor ~= Enum.Material.Air local TookOff = PreviousGrounded and not Grounded
            local Landed = not PreviousGrounded and Grounded

            if TookOff then
                local Jumping = State == Enum.HumanoidStateType.Jumping or RootPart.AssemblyLinearVelocity.Y > 2.2

                Circles.WasAirborne = true
                Circles.JumpArmed = Jumping
                Circles.JumpStartedAt = Jumping and os.clock() or 0
            elseif not Grounded then
                Circles.WasAirborne = true

                if not Circles.JumpArmed and State == Enum.HumanoidStateType.Jumping and RootPart.AssemblyLinearVelocity.Y > 1.2 then
                    Circles.JumpArmed = true
                    Circles.JumpStartedAt = os.clock()
                end
            end

            if Landed then
                local ValidJump = Circles.WasAirborne == true and Circles.JumpArmed == true and os.clock() - (tonumber(Circles.JumpStartedAt) or 0) <= 3.5

                if ValidJump then
                    local LandingPosition = self:GetJumpCircleLandingPosition(Character, RootPart)
                    if LandingPosition then self:EmitJumpCircle(LandingPosition) end
                end

                Circles.WasAirborne = false
                Circles.JumpArmed = false
                Circles.JumpStartedAt = 0
            end

            Circles.LastFloor = Floor end
    else
        if not Character or not Circles.Enabled then
            Circles.Character = Character
            Circles.LastFloor = Humanoid and Humanoid.FloorMaterial or nil
            Circles.WasAirborne = false
            Circles.JumpArmed = false
            Circles.JumpStartedAt = 0
        end
    end

    local Duration = math.max(tonumber(Circles.Duration) or 0.48, 0.08) local MaximumRadius = math.max(tonumber(Circles.Radius) or 7, 1)
    local Width = math.max(tonumber(Circles.Width) or 0.075, 0.01)

    for Index = #Circles.Active, 1, -1 do
        local Entry = Circles.Active[Index]

        if not Entry or not Entry.Holder or not Entry.Holder.Parent then
            table.remove(Circles.Active, Index)
        else
            Entry.Time += DeltaTime
            local Alpha = math.clamp(Entry.Time / Duration, 0, 1) local Ease = 1 - (1 - Alpha) ^ 3
            local Radius = Entry.StartRadius + (MaximumRadius - Entry.StartRadius) * Ease local Transparency = math.clamp(0.04 + Alpha ^ 1.35 * 0.96, 0, 1)
            local BeamWidth = Width * (1 - Alpha * 0.45)

            for PointIndex = 1, Entry.Segments do
                local Attachment = Entry.Attachments[PointIndex]
                if Attachment and Attachment.Parent then
                    local Angle = ((PointIndex - 1) / Entry.Segments) * math.pi * 2
                    Attachment.Position = Vector3.new( math.cos(Angle) * Radius, 0, math.sin(Angle) * Radius)
                end

                local Beam = Entry.Beams[PointIndex]
                if Beam and Beam.Parent then
                    Beam.Color = ColorSequence.new(Circles.Color)
                    Beam.Width0 = BeamWidth
                    Beam.Width1 = BeamWidth
                    Beam.Transparency = NumberSequence.new(Transparency)
                end
            end

            if Alpha >= 1 then
                Entry.Holder:Destroy()
                table.remove(Circles.Active, Index)
            end
        end
    end
end

function ExtendedVisualState:DestroyCrosshair()
    if self.Crosshair.Gui then self.Crosshair.Gui:Destroy() end
    self.Crosshair.Gui = nil
    self.Crosshair.Holder = nil
    self.Crosshair.Lines = {}
end

function ExtendedVisualState:CreateCrosshair()
    if not self.Crosshair.Enabled then self:DestroyCrosshair() return end
    if self.Crosshair.Gui and self.Crosshair.Gui.Parent then return end
    local Parent = Internal.GetHitFeedbackGuiParent() if not Parent then return end
    local Gui = Instance.new("ScreenGui")
    Gui.Name = "AtramentaCustomCrosshair"
    Gui.IgnoreGuiInset = true
    Gui.ResetOnSpawn = false
    Gui.DisplayOrder = 990
    Gui.Parent = Parent
    local Holder = Instance.new("Frame")
    Holder.AnchorPoint = Vector2.new(0.5, 0.5)
    Holder.BackgroundTransparency = 1
    Holder.Size = UDim2.fromOffset(100, 100)
    Holder.Parent = Gui
    local Lines = {}
    for Index, Rotation in ipairs({ 0, 90, 180, 270 }) do
        local Outline = Instance.new("Frame")
        Outline.AnchorPoint = Vector2.new(0.5, 0.5)
        Outline.BackgroundColor3 = Color3.fromRGB(10, 10, 10)
        Outline.BorderSizePixel = 0
        Outline.Rotation = Rotation
        Outline.Parent = Holder
        local Line = Instance.new("Frame")
        Line.AnchorPoint = Vector2.new(0.5, 0.5)
        Line.Position = UDim2.fromScale(0.5, 0.5)
        Line.BorderSizePixel = 0
        Line.Parent = Outline
        Lines[Index] = { Outline = Outline, Line = Line, Rotation = Rotation }
    end
    self.Crosshair.Gui = Gui
    self.Crosshair.Holder = Holder
    self.Crosshair.Lines = Lines
end

function ExtendedVisualState:UpdateCrosshair()
    if not self.Crosshair.Enabled then return end
    self:CreateCrosshair()
    if not self.Crosshair.Holder then return end
    local CameraObject = workspace.CurrentCamera local Viewport = CameraObject and CameraObject.ViewportSize or Vector2.new(1920, 1080)
    local Location = tostring(self.Crosshair.Location or "Center")
    local Position

    if Location == "Mouse" then
        Position = Vector2.new(Mouse.X, Mouse.Y)
    elseif Location == "Target" and CameraObject then
        local Character = self:ResolveTarget()
        local Part = Character and (Character:FindFirstChild("Head") or Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso"))

        if Part and Part:IsA("BasePart") then
            local Screen = CameraObject:WorldToViewportPoint(Part.Position)
            if Screen.Z > 0 then Position = Vector2.new(Screen.X, Screen.Y) end
        end
    elseif Location == "Barrel" and CameraObject then
        local Character = LocalPlayer.Character
        local Tool = Character and Character:FindFirstChildOfClass("Tool")
        local Muzzle = Tool and Internal.GetBulletTracerMuzzle(Tool)
        local WorldPosition

        if Muzzle and Muzzle:IsA("Attachment") then
            WorldPosition = Muzzle.WorldPosition
        elseif Muzzle and Muzzle:IsA("BasePart") then
            WorldPosition = Muzzle.Position
        end

        if typeof(WorldPosition) == "Vector3" then
            local Screen = CameraObject:WorldToViewportPoint(WorldPosition)
            if Screen.Z > 0 then Position = Vector2.new(Screen.X, Screen.Y) end
        end
    end

    Position = Position or Viewport / 2
    self.Crosshair.Holder.Position = UDim2.fromOffset(Position.X, Position.Y)
    local Time = os.clock() local Extra = 0
    if self.Crosshair.Animation == "Expand" then Extra = (math.sin(Time * self.Crosshair.Speed) + 1) * 3
    elseif self.Crosshair.Animation == "Ripple" then Extra = Time * self.Crosshair.Speed % 1 * 7
    elseif self.Crosshair.Animation == "Glitch" then Extra = math.random(-2, 4)
    elseif self.Crosshair.Animation == "Spiral" then self.Crosshair.Holder.Rotation = Time * math.max(self.Crosshair.RotationSpeed, 100) end
    if self.Crosshair.Animation ~= "Spiral" then self.Crosshair.Holder.Rotation = Time * self.Crosshair.RotationSpeed end
    local CrosshairColor = self:ResolveTarget() and self.Crosshair.TargetColor or self.Crosshair.Color for _, Data in ipairs(self.Crosshair.Lines) do
        local Direction = Vector2.new(math.sin(math.rad(Data.Rotation)), -math.cos(math.rad(Data.Rotation)))
        Data.Outline.Size = UDim2.fromOffset(self.Crosshair.Thickness + 2, self.Crosshair.Size + 2)
        Data.Line.Size = UDim2.fromOffset(self.Crosshair.Thickness, self.Crosshair.Size)
        Data.Line.BackgroundColor3 = CrosshairColor
        Data.Outline.Position = UDim2.fromOffset(50 + Direction.X * (self.Crosshair.Gap + self.Crosshair.Size / 2 + Extra), 50 + Direction.Y * (self.Crosshair.Gap + self.Crosshair.Size / 2 + Extra))
    end
end

function ExtendedVisualState:EmitSkeleton(Character)
    if not self.Hit.Skeleton or not Character then return end
    local Folder = Instance.new("Folder")
    Folder.Name = "AtramentaHitSkeleton"
    Folder.Parent = workspace
    local PairsList = { { "Head", "UpperTorso" }, { "Head", "Torso" }, { "UpperTorso", "LowerTorso" }, { "Torso", "HumanoidRootPart" }, { "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" }, { "LeftLowerArm", "LeftHand" }, { "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" }, { "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" }, { "LowerTorso", "RightUpperLeg" }, { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" }, { "Torso", "Left Arm" }, { "Torso", "Right Arm" }, { "Torso", "Left Leg" }, { "Torso", "Right Leg" } }
    for _, Pair in ipairs(PairsList) do
        local A = Character:FindFirstChild(Pair[1]) local B = Character:FindFirstChild(Pair[2])
        if A and B and A:IsA("BasePart") and B:IsA("BasePart") then
            local Distance = (B.Position - A.Position).Magnitude local Bone = Instance.new("Part")
            Bone.Anchored = true
            Bone.CanCollide = false
            Bone.CanTouch = false
            Bone.CanQuery = false
            Bone.Material = Enum.Material.Neon
            Bone.Color = self.Hit.SkeletonColor Bone.Size = Vector3.new(0.07, 0.07, Distance)
            Bone.CFrame = CFrame.lookAt((A.Position + B.Position) / 2, B.Position)
            Bone.Parent = Folder
            TweenService:Create(Bone, TweenInfo.new(self.Hit.SkeletonDuration), { Transparency = 1 }):Play()
        end
    end
    task.delay(self.Hit.SkeletonDuration + 0.05, function() if Folder.Parent then Folder:Destroy() end end)
end

function ExtendedVisualState:EmitMarker3D(Position, IsHeadshot)
    if not self.Hit.Marker3D or typeof(Position) ~= "Vector3" then return end
    local Anchor = Instance.new("Part")
    Anchor.Anchored = true
    Anchor.CanCollide = false
    Anchor.CanTouch = false
    Anchor.CanQuery = false
    Anchor.Transparency = 1
    Anchor.Size = Vector3.new(0.05, 0.05, 0.05)
    Anchor.Position = Position
    Anchor.Parent = workspace
    local Gui = Instance.new("BillboardGui")
    Gui.AlwaysOnTop = true
    Gui.LightInfluence = 0
    Gui.Size = UDim2.fromOffset(44, 44)
    Gui.Adornee = Anchor Gui.Parent = Anchor for _, Rotation in ipairs({ 45, -45, 135, -135 }) do
        local Line = Instance.new("Frame")
        Line.AnchorPoint = Vector2.new(0.5, 0.5)
        Line.Position = UDim2.fromScale(0.5, 0.5)
        Line.Size = UDim2.fromOffset(2, 14)
        Line.Rotation = Rotation
        Line.BorderSizePixel = 0
        Line.BackgroundColor3 = IsHeadshot and Color3.fromRGB(255, 82, 82) or self.Hit.Marker3DColor Line.Parent = Gui
        TweenService:Create(Line, TweenInfo.new(0.55), { BackgroundTransparency = 1 }):Play()
    end
    task.delay(0.6, function() if Anchor.Parent then Anchor:Destroy() end end)
end

function ExtendedVisualState:EmitOverlay()
    if not self.Hit.Overlay then return end
    local Parent = Internal.GetHitFeedbackGuiParent() if not Parent then return end
    local Gui = Instance.new("ScreenGui")
    Gui.Name = "AtramentaHitOverlay"
    Gui.IgnoreGuiInset = true
    Gui.ResetOnSpawn = false
    Gui.DisplayOrder = 1000
    Gui.Parent = Parent
    local Sizes = { { UDim2.new(1, 0, 0, 46), UDim2.new(0, 0, 0, 0) }, { UDim2.new(1, 0, 0, 46), UDim2.new(0, 0, 1, -46) }, { UDim2.new(0, 46, 1, 0), UDim2.new(0, 0, 0, 0) }, { UDim2.new(0, 46, 1, 0), UDim2.new(1, -46, 0, 0) } }
    for _, Data in ipairs(Sizes) do
        local Frame = Instance.new("Frame")
        Frame.Size = Data[1]
        Frame.Position = Data[2]
        Frame.BorderSizePixel = 0
        Frame.BackgroundColor3 = self.Hit.OverlayColor Frame.BackgroundTransparency = 0.38
        Frame.Parent = Gui
        TweenService:Create(Frame, TweenInfo.new(self.Hit.OverlayDuration), { BackgroundTransparency = 1 }):Play()
    end
    task.delay(self.Hit.OverlayDuration + 0.05, function() if Gui.Parent then Gui:Destroy() end end)
end

function ExtendedVisualState:OnHit(TargetPart, Character, IsHeadshot)
    self:EmitSkeleton(Character)
    self:EmitMarker3D(TargetPart and TargetPart.Position, IsHeadshot)
    self:EmitOverlay()
end

function ExtendedVisualState:ResolveTarget()
    local Value = Ragebot.Runtime and Ragebot.Runtime.Target or Ragebot.LockedTarget or Configuration.AimBot.CurrentTarget or Configuration.AimBot.AimbotLockedTarget or Configuration.AimBot.SilentAimLockedTarget
    if typeof(Value) ~= "Instance" then return nil end
    if Value:IsA("Player") then return Value.Character end
    if Value:IsA("Model") then return Value end
    if Value:IsA("BasePart") then return Value:FindFirstAncestorOfClass("Model") end
    return nil
end

function ExtendedVisualState:DestroyTarget()
    if self.Target.Gui then self.Target.Gui:Destroy() end
    if self.Target.HighlightObject then self.Target.HighlightObject:Destroy() end
    self.Target.Gui = nil
    self.Target.CircleFrame = nil
    self.Target.BoxFrame = nil
    self.Target.TracerFrame = nil
    self.Target.HighlightObject = nil
    self.Target.Current = nil
end

function ExtendedVisualState:CreateTarget()
    if not self.Target.Enabled then self:DestroyTarget() return end
    if self.Target.Gui and self.Target.Gui.Parent then return end
    local Parent = Internal.GetHitFeedbackGuiParent() if not Parent then return end
    local Gui = Instance.new("ScreenGui")
    Gui.Name = "AtramentaTargetVisualization"
    Gui.IgnoreGuiInset = true
    Gui.ResetOnSpawn = false
    Gui.DisplayOrder = 940
    Gui.Parent = Parent
    local Circle = Instance.new("Frame")
    Circle.AnchorPoint = Vector2.new(0.5, 0.5)
    Circle.BackgroundTransparency = 1
    Circle.Size = UDim2.fromOffset(42, 42)
    Circle.Visible = false
    Circle.Parent = Gui
    local Corner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(1, 0)
    Corner.Parent = Circle
    local CircleStroke = Instance.new("UIStroke")
    CircleStroke.Color = self.Target.Color CircleStroke.Thickness = 2
    CircleStroke.Parent = Circle
    local Box = Instance.new("Frame")
    Box.BackgroundTransparency = 1
    Box.BorderSizePixel = 0
    Box.Visible = false
    Box.Parent = Gui
    local BoxStroke = Instance.new("UIStroke")
    BoxStroke.Color = self.Target.Color BoxStroke.Thickness = 1.5
    BoxStroke.Parent = Box
    local Tracer = Instance.new("Frame")
    Tracer.AnchorPoint = Vector2.new(0, 0.5)
    Tracer.BorderSizePixel = 0
    Tracer.BackgroundColor3 = self.Target.Color Tracer.Visible = false
    Tracer.Parent = Gui
    self.Target.Gui = Gui
    self.Target.CircleFrame = Circle
    self.Target.CircleStroke = CircleStroke
    self.Target.BoxFrame = Box
    self.Target.BoxStroke = BoxStroke
    self.Target.TracerFrame = Tracer
end

function ExtendedVisualState:UpdateTarget()
    if not self.Target.Enabled then return end

    self:CreateTarget()
    if not self.Target.Gui then return end

    local Character = self:ResolveTarget() local Player = Character and Internal.GetPlayerFromTrackedCharacter(Character) or nil
    local RootPart = Character and (Character:FindFirstChild("HumanoidRootPart") or Character.PrimaryPart) local CameraObject = workspace.CurrentCamera

    if not Character or not RootPart or not CameraObject then
        self.Target.CircleFrame.Visible = false
        self.Target.BoxFrame.Visible = false
        self.Target.TracerFrame.Visible = false
        if self.Target.HighlightObject then self.Target.HighlightObject.Enabled = false end
        return
    end

    local Snapshot = Player and type(ResolverGetTargetSnapshot) == "function" and ResolverGetTargetSnapshot(Player, Character) or nil

    local RootPosition = Snapshot and ResolverIsFiniteVector(Snapshot.ResolvedRootPosition) and Snapshot.ResolvedRootPosition or RootPart.Position
    local TopPosition = Snapshot and ResolverIsFiniteVector(Snapshot.BoxTopPosition) and Snapshot.BoxTopPosition or RootPosition + Vector3.new(0, 2.75, 0)
    local BottomPosition = Snapshot and ResolverIsFiniteVector(Snapshot.BoxBottomPosition) and Snapshot.BoxBottomPosition or RootPosition - Vector3.new(0, 3.10, 0)

    if self.Target.Current ~= Character then
        if self.Target.HighlightObject then
            self.Target.HighlightObject:Destroy()
            self.Target.HighlightObject = nil
        end
        self.Target.Current = Character
    end

    if self.Target.Highlight then
        local Highlight = self.Target.HighlightObject
        if not Highlight or not Highlight.Parent or Highlight.Adornee ~= Character then
            if Highlight then Highlight:Destroy() end
            Highlight = Instance.new("Highlight")
            Highlight.Name = "AtramentaTargetHighlight"
            Highlight.Adornee = Character
            Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            Highlight.FillTransparency = 0.72
            Highlight.OutlineColor = Color3.new(1, 1, 1)
            Highlight.OutlineTransparency = 0.15
            Highlight.Parent = Character
            self.Target.HighlightObject = Highlight
        end
        Highlight.Enabled = true
        Highlight.FillColor = self.Target.Color
    elseif self.Target.HighlightObject then
        self.Target.HighlightObject:Destroy()
        self.Target.HighlightObject = nil
    end

    if self.Target.CircleStroke.Color ~= self.Target.Color then self.Target.CircleStroke.Color = self.Target.Color end
    if self.Target.BoxStroke.Color ~= self.Target.Color then self.Target.BoxStroke.Color = self.Target.Color end
    if self.Target.TracerFrame.BackgroundColor3 ~= self.Target.Color then self.Target.TracerFrame.BackgroundColor3 = self.Target.Color end

    local RootScreen, OnScreen = CameraObject:WorldToViewportPoint(RootPosition) local TopScreen = CameraObject:WorldToViewportPoint(TopPosition)
    local BottomScreen = CameraObject:WorldToViewportPoint(BottomPosition)

    if not OnScreen or RootScreen.Z <= 0 or TopScreen.Z <= 0 or BottomScreen.Z <= 0 then
        self.Target.CircleFrame.Visible = false
        self.Target.BoxFrame.Visible = false
        self.Target.TracerFrame.Visible = false
        return
    end

    local Point = Vector2.new(RootScreen.X, RootScreen.Y)
    self.Target.CircleFrame.Position = UDim2.fromOffset(Point.X, Point.Y)
    self.Target.CircleFrame.Rotation = os.clock() * 75
    self.Target.CircleFrame.Visible = self.Target.Circle

    local Height = math.max(math.abs(BottomScreen.Y - TopScreen.Y), 8) local Width = Height * 0.55
    self.Target.BoxFrame.Position = UDim2.fromOffset(RootScreen.X - Width * 0.5, TopScreen.Y)
    self.Target.BoxFrame.Size = UDim2.fromOffset(Width, Height)
    self.Target.BoxFrame.Visible = self.Target.Box

    local Origin = Vector2.new(CameraObject.ViewportSize.X * 0.5, CameraObject.ViewportSize.Y) local Delta = Point - Origin
    self.Target.TracerFrame.Position = UDim2.fromOffset(Origin.X, Origin.Y)
    self.Target.TracerFrame.Size = UDim2.fromOffset(Delta.Magnitude, 2)
    self.Target.TracerFrame.Rotation = math.deg(math.atan2(Delta.Y, Delta.X))
    self.Target.TracerFrame.Visible = self.Target.Tracer
end

function ExtendedVisualState:DisconnectSkyboxSignals()
    if self.World.SkyConnection then self.World.SkyConnection:Disconnect(); self.World.SkyConnection = nil end
    if self.World.SkyRemovedConnection then self.World.SkyRemovedConnection:Disconnect(); self.World.SkyRemovedConnection = nil end
    if self.World.SkyPropertyConnection then self.World.SkyPropertyConnection:Disconnect(); self.World.SkyPropertyConnection = nil end
    self.World.SkyRepairQueued = false
end

function ExtendedVisualState:DestroySavedSkyClones()
    self.World.SavedSkies = type(self.World.SavedSkies) == "table" and self.World.SavedSkies or {}

    for Index = #self.World.SavedSkies, 1, -1 do
        local Saved = self.World.SavedSkies[Index]
        self.World.SavedSkies[Index] = nil

        if Saved and Saved.Parent == nil then Saved:Destroy() end
    end
end

function ExtendedVisualState:DestroySkyTemplateCache()
    self.World.SkyTemplateCache = type(self.World.SkyTemplateCache) == "table" and self.World.SkyTemplateCache or {}

    for Name, Template in pairs(self.World.SkyTemplateCache) do
        self.World.SkyTemplateCache[Name] = nil

        if Template and Template.Parent == nil then Template:Destroy() end
    end
end

function ExtendedVisualState:CaptureSkyboxState()
    self.World.SavedSkies = type(self.World.SavedSkies) == "table" and self.World.SavedSkies or {}
    if self.World.SkyCaptured then return end

    self:DestroySavedSkyClones()

    for _, Object in ipairs(Lighting:GetChildren()) do
        if Object:IsA("Sky") and Object ~= self.World.AppliedSky then
            local Clone = Object:Clone()
            Clone.Parent = nil
            self.World.SavedSkies[#self.World.SavedSkies + 1] = Clone
        end
    end

    self.World.SkyCaptured = true
end

function ExtendedVisualState:RestoreSavedSkies()
    self.World.SavedSkies = type(self.World.SavedSkies) == "table" and self.World.SavedSkies or {}

    self.World.SkyMutating = true

    for _, Object in ipairs(Lighting:GetChildren()) do
        if Object:IsA("Sky") then Object:Destroy() end
    end

    for Index = 1, #self.World.SavedSkies do
        local Saved = self.World.SavedSkies[Index]

        if Saved then
            local Clone = Saved:Clone()
            Clone.Parent = Lighting

            if Saved.Parent == nil then Saved:Destroy() end

            self.World.SavedSkies[Index] = nil
        end
    end

    self.World.SkyMutating = false
    table.clear(self.World.SavedSkies)
    self.World.SkyCaptured = false
end

function ExtendedVisualState:QueueSkyboxRepair()
    if self.World.SkyRepairQueued or not self.World.Skybox or self.Destroyed then return end
    self.World.SkyRepairQueued = true

    task.defer(function()
        self.World.SkyRepairQueued = false
        if self.World.Skybox and not self.Destroyed then self:ApplySkybox(true) end
    end)
end

function ExtendedVisualState:FindSky(Object)
    if not Object then return nil end
    if Object:IsA("Sky") then return Object end

    for _, Child in ipairs(Object:GetChildren()) do
        local Sky = self:FindSky(Child)
        if Sky then return Sky end
    end

    return nil
end

function ExtendedVisualState:ValidateSky(Sky)
    if not Sky or not Sky:IsA("Sky") then return false end

    local Faces = { Sky.SkyboxBk, Sky.SkyboxDn, Sky.SkyboxFt, Sky.SkyboxLf, Sky.SkyboxRt, Sky.SkyboxUp }

    local Unique = {}

    for Index = 1, 6 do
        local Texture = Faces[Index]

        if type(Texture) ~= "string" or Texture == "" then return false end

        Unique[Texture] = true
    end

    local UniqueCount = 0

    for _ in pairs(Unique) do
        UniqueCount += 1
    end

    return UniqueCount >= 5
end

function ExtendedVisualState:LoadSkyTemplate(PresetName)
    self.World.SkyTemplateCache = type(self.World.SkyTemplateCache) == "table" and self.World.SkyTemplateCache or {}

    local Cached = self.World.SkyTemplateCache[PresetName]
    if Cached and Cached:IsA("Sky") and self:ValidateSky(Cached) then return Cached end

    local Data = self.SkyPresets[PresetName]
    if type(Data) ~= "table" then return nil end

    local Faces = Data.Faces
    if type(Faces) == "table" then
        local Template = Instance.new("Sky")
        Template.Name = "AtramentaSkyTemplate"
        for Property, Texture in pairs(Faces) do
            if type(Property) == "string" and type(Texture) == "string" then Template[Property] = Texture end
        end
        if not self:ValidateSky(Template) then
            Template:Destroy()
            return nil
        end
        Template.Parent = nil
        self.World.SkyTemplateCache[PresetName] = Template
        return Template
    end

    local AssetId = tonumber(Data.AssetId)
    if not AssetId then return nil end

    local Objects
    local Success = Internal.Call(function()
        Objects = game:GetObjects("rbxassetid://" .. tostring(AssetId))
    end)

    if not Success or type(Objects) ~= "table" then return nil end

    local FoundSky

    for _, Object in ipairs(Objects) do
        FoundSky = self:FindSky(Object)
        if FoundSky then break end
    end

    local Template

    if FoundSky and self:ValidateSky(FoundSky) then
        Template = FoundSky:Clone()
        Template.Name = "AtramentaSkyTemplate"
        Template.Parent = nil
        self.World.SkyTemplateCache[PresetName] = Template
    end

    for _, Object in ipairs(Objects) do
        if Object and Object.Parent == nil then
            Internal.Call(function()
                Object:Destroy()
            end)
        end
    end

    return Template
end

function ExtendedVisualState:ProtectSky(NewSky)
    if self.World.SkyPropertyConnection then
        self.World.SkyPropertyConnection:Disconnect()
        self.World.SkyPropertyConnection = nil
    end

    if not NewSky then return end

    self.World.SkyPropertyConnection = NewSky.Changed:Connect(function()
        if not self.World.Skybox or self.World.SkyMutating then return end
        if NewSky ~= self.World.AppliedSky then return end
        self:QueueSkyboxRepair()
    end)

    if not self.World.SkyConnection then
        self.World.SkyConnection = Lighting.ChildAdded:Connect(function(Object)
            if not self.World.Skybox or self.World.SkyMutating then return end

            if Object:IsA("Sky") and Object ~= self.World.AppliedSky then
                self.World.SkyMutating = true
                Object:Destroy()
                self.World.SkyMutating = false
                self:QueueSkyboxRepair()
            end
        end)
    end

    if not self.World.SkyRemovedConnection then
        self.World.SkyRemovedConnection = Lighting.ChildRemoved:Connect(function(Object)
            if not self.World.Skybox or self.World.SkyMutating then return end

            if Object == self.World.AppliedSky then
                self.World.AppliedSky = nil
                self:QueueSkyboxRepair()
            end
        end)
    end
end

function ExtendedVisualState:ApplySkybox(Repair)
    self.World.SavedSkies = type(self.World.SavedSkies) == "table" and self.World.SavedSkies or {}

    if not self.World.Skybox then
        self:DisconnectSkyboxSignals()
        self.World.SkyMutating = true

        for _, Object in ipairs(Lighting:GetChildren()) do
            if Object:IsA("Sky") and Object.Name == "AtramentaSkybox" then Object:Destroy() end
        end

        self.World.AppliedSky = nil
        self.World.AppliedSkyPreset = nil
        self.World.SkyMutating = false
        self:RestoreSavedSkies()
        return
    end

    self:CaptureSkyboxState()

    local PresetName = tostring(self.World.SkyPreset or "Galaxy")
    if PresetName == "Default" then
        PresetName = "Day"
        self.World.SkyPreset = "Day"
    end

    local Template = self:LoadSkyTemplate(PresetName)
    if not Template then return false end

    if self.World.AppliedSky and self.World.AppliedSky.Parent == Lighting and self.World.AppliedSkyPreset == PresetName
        and self:ValidateSky(self.World.AppliedSky)
    then
        return true
    end

    self.World.SkyMutating = true

    for _, Object in ipairs(Lighting:GetChildren()) do
        if Object:IsA("Sky") then Object:Destroy() end
    end

    local NewSky = Template:Clone()
    NewSky.Name = "AtramentaSkybox"
    NewSky.Parent = Lighting

    self.World.AppliedSky = NewSky
    self.World.AppliedSkyPreset = PresetName
    self.World.SkyMutating = false

    self:ProtectSky(NewSky)
    return true
end

function ExtendedVisualState:ApplyNoise()
    if not self.World.Noise then
        if self.World.Sound then
            self.World.Sound:Destroy()
            self.World.Sound = nil
        end

        for _, Object in ipairs(SoundService:GetChildren()) do
            if Object:IsA("Sound") and Object.Name == "AtramentaBackgroundNoise" then Object:Destroy() end
        end

        return
    end

    if not self.World.Sound or not self.World.Sound.Parent then
        local Existing

        for _, Object in ipairs(SoundService:GetChildren()) do
            if Object:IsA("Sound") and Object.Name == "AtramentaBackgroundNoise" then
                if not Existing then
                    Existing = Object
                else
                    Object:Destroy()
                end
            end
        end

        if Existing then
            self.World.Sound = Existing
        else
            local Sound = Instance.new("Sound")
            Sound.Name = "AtramentaBackgroundNoise"
            Sound.Looped = true
            Sound.Parent = SoundService
            self.World.Sound = Sound
        end
    end

    local SoundId = self.NoisePresets[self.World.NoisePreset] or self.NoisePresets.Night

    if self.World.Sound.SoundId ~= SoundId then self.World.Sound.SoundId = SoundId end

    if self.World.Sound.Volume ~= self.World.NoiseVolume then self.World.Sound.Volume = self.World.NoiseVolume end

    if not self.World.Sound.IsPlaying then self.World.Sound:Play() end
end

function ExtendedVisualState:IsArm(Part)
    local Name = Part.Name
    return Name == "LeftHand" or Name == "LeftLowerArm" or Name == "LeftUpperArm" or Name == "RightHand" or Name == "RightLowerArm" or Name == "RightUpperArm" or Name == "Left Arm" or Name == "Right Arm"
end

function ExtendedVisualState:IsHeadlessPart(Part)
    return Part and Part:IsA("BasePart") and Part.Name == "Head"
end

function ExtendedVisualState:IsKorbloxPart(Part)
    if not Part or not Part:IsA("BasePart") then return false end
    local Name = Part.Name
    return Name == "RightLowerLeg" or Name == "RightFoot" or Name == "Right Leg"
end

function ExtendedVisualState:SaveCharacterAppearance(Part)
    if not Part or not Part.Parent or self.Character.SavedParts[Part] then return end
    self.Character.SavedParts[Part] = {Color = Part.Color, Material = Part.Material, Reflectance = Part.Reflectance}
end

function ExtendedVisualState:RestoreCharacterAppearancePart(Part)
    local Data = Part and self.Character.SavedParts[Part] if not Data then return end
    if Part.Parent then
        Part.Color = Data.Color Part.Material = Data.Material
        Part.Reflectance = Data.Reflectance
    end
    self.Character.SavedParts[Part] = nil
end

function ExtendedVisualState:HideCharacterPart(Part)
    if not Part or not Part.Parent then return end
    local Data = self.Character.HiddenParts[Part]
    if not Data then
        local Transparency = Part.Transparency
        if InvisibilityEnabled and Transparency < 1 then Transparency = 0 end
        Data = {Transparency = Transparency}
        self.Character.HiddenParts[Part] = Data
    end
    Part.Transparency = 1
end

function ExtendedVisualState:RestoreHiddenCharacterPart(Part)
    local Data = Part and self.Character.HiddenParts[Part] if not Data then return end
    if Part.Parent then
        local Transparency = tonumber(Data.Transparency)
        if Transparency == nil then Transparency = 0 end
        if InvisibilityEnabled and Transparency < 1 then Transparency = 0.5 end
        Part.Transparency = math.clamp(Transparency, 0, 1)
    end
    self.Character.HiddenParts[Part] = nil
end

function ExtendedVisualState:RestoreCharacterParts()
    for Part in pairs(self.Character.SavedParts) do self:RestoreCharacterAppearancePart(Part) end
    for Part in pairs(self.Character.HiddenParts) do self:RestoreHiddenCharacterPart(Part) end
    self.Character.SavedParts = setmetatable({}, {__mode = "k"})
    self.Character.HiddenParts = setmetatable({}, {__mode = "k"})
end

function ExtendedVisualState:NormalizeCharacterTransparency(Character)
    if InvisibilityEnabled then return end
    Character = Character or LocalPlayer.Character
    if not Character then return end
    local BodyNames = { Head = true, Torso = true, UpperTorso = true, LowerTorso = true,
        ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
        LeftUpperArm = true, LeftLowerArm = true, LeftHand = true, RightUpperArm = true, RightLowerArm = true, RightHand = true,
        LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true, RightUpperLeg = true, RightLowerLeg = true, RightFoot = true }
    for _, Part in ipairs(Character:GetDescendants()) do
        if Part:IsA("BasePart") and BodyNames[Part.Name] and math.abs(Part.Transparency - 0.5) <= 0.001 then Part.Transparency = 0 end
    end
end

function ExtendedVisualState:ClearCharacterObjectCache()
    if self.Character.ObjectConnection then
        self.Character.ObjectConnection:Disconnect()
        self.Character.ObjectConnection = nil
    end
    if self.Character.ObjectRemovingConnection then
        self.Character.ObjectRemovingConnection:Disconnect()
        self.Character.ObjectRemovingConnection = nil
    end
    self.Character.CachedObjects = {}
    self.Character.CachedObjectSet = setmetatable({}, {__mode = "k"})
end

function ExtendedVisualState:AddCharacterCachedObject(Object)
    if not Object or self.Character.CachedObjectSet[Object] then return end
    if not Object:IsA("BasePart") or Object:FindFirstAncestorOfClass("Tool") then return end

    self.Character.CachedObjectSet[Object] = true
    self.Character.CachedObjects[#self.Character.CachedObjects + 1] = Object
end

function ExtendedVisualState:RemoveCharacterCachedObject(Object)
    if not Object or not self.Character.CachedObjectSet[Object] then return end
    self.Character.CachedObjectSet[Object] = nil

    local CachedObjects = self.Character.CachedObjects
    for Index = #CachedObjects, 1, -1 do
        if CachedObjects[Index] == Object then
            local LastIndex = #CachedObjects
            CachedObjects[Index] = CachedObjects[LastIndex]
            CachedObjects[LastIndex] = nil
            return
        end
    end
end

function ExtendedVisualState:BindCharacterObjectCache(Character)
    self:ClearCharacterObjectCache()
    if not Character then return end

    for _, Object in ipairs(Character:GetDescendants()) do self:AddCharacterCachedObject(Object) end

    self.Character.ObjectConnection = Character.DescendantAdded:Connect(function(Object)
        if self.Character.ActiveCharacter == Character then self:AddCharacterCachedObject(Object) end
    end)

    self.Character.ObjectRemovingConnection = Character.DescendantRemoving:Connect(function(Object)
        if self.Character.ActiveCharacter == Character then self:RemoveCharacterCachedObject(Object) end
    end)
end

function ExtendedVisualState:RestoreCharacter()
    self:ClearCharacterObjectCache()
    self:RestoreCharacterParts()
    self.Character.ActiveCharacter = nil
end

function ExtendedVisualState:UpdateCharacter()
    local Character = LocalPlayer.Character if not Character then return end

    if self.Character.ActiveCharacter ~= Character then
        self:RestoreCharacterParts()
        self:NormalizeCharacterTransparency(Character)
        self.Character.ActiveCharacter = Character
        self.Character.SavedParts = setmetatable({}, {__mode = "k"})
        self.Character.HiddenParts = setmetatable({}, {__mode = "k"})

        self:BindCharacterObjectCache(Character)
    end

    local BodyEffects = self.Character.MaterialEnabled or self.Character.Headless or self.Character.Korblox

    if not BodyEffects and (next(self.Character.SavedParts) or next(self.Character.HiddenParts)) then self:RestoreCharacterParts() end
    if not BodyEffects then return end

    local CameraObject = workspace.CurrentCamera local FirstPerson = CameraObject and (CameraObject.CFrame.Position - CameraObject.Focus.Position).Magnitude <= 1.25
    local Material = Enum.Material[self.Character.Material] or Enum.Material.Neon

    local CachedObjects = self.Character.CachedObjects
    if type(CachedObjects) ~= "table" or #CachedObjects == 0 then
        self:BindCharacterObjectCache(Character)
        CachedObjects = self.Character.CachedObjects
    end

    local DeadObjects = 0
    for _, Object in ipairs(CachedObjects) do
        if not Object or not Object.Parent or not Object:IsDescendantOf(Character) then
            DeadObjects += 1
        elseif Object:IsA("BasePart") and not Object:FindFirstAncestorOfClass("Tool") then
            if self.Character.MaterialEnabled and not FirstPerson then
                self:SaveCharacterAppearance(Object)
                Object.Color = self.Character.Color Object.Material = Material
                Object.Reflectance = 0
            else
                self:RestoreCharacterAppearancePart(Object)
            end

            local ShouldHide = self.Character.Headless and self:IsHeadlessPart(Object) or self.Character.Korblox and self:IsKorbloxPart(Object)
            if ShouldHide then self:HideCharacterPart(Object) else self:RestoreHiddenCharacterPart(Object) end
        end
    end

    if DeadObjects > 0 then
        local WriteIndex = 1 local CachedSet = self.Character.CachedObjectSet

        for ReadIndex = 1, #CachedObjects do
            local Object = CachedObjects[ReadIndex]

            if Object and Object.Parent and Object:IsDescendantOf(Character) and CachedSet[Object] then
                CachedObjects[WriteIndex] = Object
                WriteIndex += 1
            elseif Object then
                CachedSet[Object] = nil
            end
        end

        for Index = #CachedObjects, WriteIndex, -1 do
            CachedObjects[Index] = nil
        end
    end
end

function ExtendedVisualState:IsRuntimeNeeded()
    return self.Crosshair.Enabled == true or self.Target.Enabled == true or self.Aura.Enabled == true or self.Trail.Enabled == true
        or self.JumpCircles.Enabled == true or #self.JumpCircles.Active > 0 or self.Character.MaterialEnabled == true
        or self.Character.Headless == true or self.Character.Korblox == true
        or next(self.Character.SavedParts) ~= nil or next(self.Character.HiddenParts) ~= nil
end

function ExtendedVisualState:StopRuntimeIfIdle()
    if self:IsRuntimeNeeded() then return false end

    local Connection = self.Connection
    self.Connection = nil
    self.CharacterClock = 0
    self.StaticClock = 0

    if Connection then Connection:Disconnect() end

    return true
end

function ExtendedVisualState:RefreshRuntime()
    if self:IsRuntimeNeeded() then
        self:Start()
    else
        self:StopRuntimeIfIdle()
    end
end

function ExtendedVisualState:Start()
    if self.Connection then return end

    if not self:IsRuntimeNeeded() then return end

    self.Destroyed = false

    local Previous = rawget(Environment, "AtramentaExtendedVisualRuntime")

    if Previous and Previous ~= self and type(Previous.Destroy) == "function" then
        Internal.Call(function()
            Previous:Destroy()
        end)
    end

    self:NormalizeCharacterTransparency( LocalPlayer.Character)

    rawset(Environment, "AtramentaExtendedVisualRuntime", self)

    self.StaticClock = 0
    self.CharacterClock = 0

    self.Connection = RunService.RenderStepped:Connect(function(DeltaTime)
        if self.Destroyed then
            local Connection = self.Connection
            self.Connection = nil

            if Connection then Connection:Disconnect() end

            return
        end

        if not self:IsRuntimeNeeded() then
            self:StopRuntimeIfIdle()
            return
        end

        DeltaTime = math.clamp( tonumber(DeltaTime) or 0, 0, 0.05)

        if self.Crosshair.Enabled then Internal.Call(self.UpdateCrosshair, self) end

        if self.Target.Enabled then Internal.Call(self.UpdateTarget, self) end

        self.StaticClock += DeltaTime

        if self.StaticClock >= 0.20 then
            self.StaticClock = self.StaticClock % 0.20

            if self.Aura.Enabled then Internal.Call(self.CreateAura, self) end

            if self.Trail.Enabled then Internal.Call(self.CreateTrail, self) end
        end

        if self.JumpCircles.Enabled or #self.JumpCircles.Active > 0 then Internal.Call(self.UpdateJumpCircles, self, DeltaTime) end

        local CharacterEffects = self.Character.MaterialEnabled or self.Character.Headless or self.Character.Korblox
            or next(self.Character.SavedParts) ~= nil or next(self.Character.HiddenParts) ~= nil

        if CharacterEffects then
            self.CharacterClock += DeltaTime

            if self.CharacterClock >= 0.12 then
                self.CharacterClock = self.CharacterClock % 0.12

                Internal.Call(self.UpdateCharacter, self)
            end
        else
            self.CharacterClock = 0
        end
    end)
end

function ExtendedVisualState:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    if self.Connection then self.Connection:Disconnect() self.Connection = nil end
    self:DestroyAura()
    self:DestroyTrail()
    self:DestroyJumpCircles()
    self:DestroyCrosshair()
    self:DestroyTarget()
    self.World.Skybox = false
    self.World.Noise = false
    self:ApplySkybox()
    self:ApplyNoise()
    self:DestroySavedSkyClones()
    self:DestroySkyTemplateCache()
    self:RestoreCharacter()
    if rawget(Environment, "AtramentaExtendedVisualRuntime") == self then rawset(Environment, "AtramentaExtendedVisualRuntime", nil) end
end

RespawnSafetyState = { Generation = 0, RemovingConnection = nil, AddedConnection = nil, DiedConnection = nil, Cleaning = false, Suspended = false, CurrentCharacter = nil, Preserved = nil, RespawnRequestedFor = nil, LastRespawnRequest = 0 }
local DestroyHitFeedbackRuntime

function Internal.ClearRespawnTransientState(Character)
    Character = Character or RespawnSafetyState.CurrentCharacter or LocalPlayer.Character
    if RespawnSafetyState.Suspended then return end
    RespawnSafetyState.Suspended = true
    RespawnSafetyState.Cleaning = true
    RespawnSafetyState.Generation += 1
    local Generation = RespawnSafetyState.Generation
    RespawnSafetyState.CurrentCharacter = Character
    RespawnSafetyState.Preserved = {
        Rage = Ragebot.Enabled == true, Arms = ArmsChamsEnabled == true, Weapon = WeaponChamsEnabled == true, WeaponShader = WeaponShaderSettings.Enabled == true, World = WorldEffectsState.Enabled == true,
        Fly = FlyEnabled == true, Noclip = NoclipEnabled == true, Invis = InvisibilityEnabled == true, Stamina = InfStaminaEnabled == true, NoFall = NoFallDamageEnabled == true,
        Bunny = BunnyHopEnabled == true, Strafe = AutoStrafeEnabled == true, Air = AirControlEnabled == true }
    Internal.Call(function() if Ragebot.Enabled and Ragebot and type(Ragebot.Disable) == "function" then Ragebot.Disable() end end)
    Internal.Call(function() if FlyEnabled and type(FlyDisable) == "function" then FlyDisable() end end)
    Internal.Call(function() if NoclipEnabled and type(NoclipDisable) == "function" then NoclipDisable() end end)
    Internal.Call(function() if InvisibilityEnabled and type(InvisibilityDisable) == "function" then InvisibilityDisable() end end)
    Internal.Call(function() if InfStaminaEnabled and type(InfStaminaDisable) == "function" then InfStaminaDisable() end end)
    Internal.Call(function() if NoFallDamageEnabled and type(NoFallDamageDisable) == "function" then NoFallDamageDisable() end end)
    Internal.Call(function() if type(DisableMovementAssist) == "function" then DisableMovementAssist() end end)
    if type(ResetMovementDriver) == "function" then ResetMovementDriver() end
    Internal.Call(function() if WeaponChamsEnabled and type(WeaponChamsDisable) == "function" then WeaponChamsDisable() else RestoreWeaponChams() end end)
    Internal.Call(function() ClearWeaponShaders() end)
    Internal.Call(function() if ArmsChamsEnabled and type(ArmsChamsDisable) == "function" then ArmsChamsDisable() else RestoreArmsChams() end end)
    Internal.Call(function() Internal.DestroyWorldEffects() end)
    Internal.Call(function() Internal.ClearBulletTracers() end)
    Internal.Call(function() ResetHitFeedbackForRespawn() end)
    Internal.Call(function() if WeaponChamsSettings then WeaponChamsSettings.ActiveTool = nil; WeaponChamsSettings.ActiveViewModel = nil end end)
    Internal.Call(function()
        if type(Ragebot.Runtime) == "table" then
            Ragebot.Runtime.PendingShot = nil
            Ragebot.Runtime.Target = nil
        end
    end)

    Internal.Call(function()
        if type(Ragebot) == "table" then Ragebot.ReportedShots = {} end
        if type(CombatLogRuntime) == "table" and type(CombatLogRuntime.ApplyLogLayout) == "function" then CombatLogRuntime.ApplyLogLayout() end
        Ragebot.Runtime.NextShot = 0
    end)

    Internal.Call(function()
        if type(ResolverState) == "table" then
            ResolverState.History = setmetatable({}, { __mode = "k" })

            ResolverState.PoseHistory = setmetatable({}, { __mode = "k" })

            ResolverState.SkeletonCache = setmetatable({}, { __mode = "k" })
            ResolverState.TargetCache = setmetatable({}, { __mode = "k" })
        end
    end)
    task.defer(function() if Generation == RespawnSafetyState.Generation then RespawnSafetyState.Cleaning = false end end)
end

function Internal.BindRespawnSafety(Character)
    RespawnSafetyState.CurrentCharacter = Character
    RespawnSafetyState.RespawnRequestedFor = nil
    if RespawnSafetyState.DiedConnection then Internal.Call(function() RespawnSafetyState.DiedConnection:Disconnect() end) end
    RespawnSafetyState.DiedConnection = nil
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    if Humanoid then RespawnSafetyState.DiedConnection = Humanoid.Died:Connect(function() Internal.ClearRespawnTransientState(Character) end) end
end

function Internal.SpawnGhostVisual(HitPosition, TargetCharacterValue)
    Internal.SpawnHitParticles(HitPosition, TargetCharacterValue)
    if not HitFeedbackState.ImpactEnabled then return end
    local Duration = math.clamp(tonumber(HitFeedbackState.ImpactDuration) or 2, 0.1, 5) local Animation = HitFeedbackState.ImpactAnimation or "Rise"
    local Material = Enum.Material[HitFeedbackState.ImpactMaterial] or Enum.Material.Neon
    if HitFeedbackState.ImpactStyle == "Character" and TargetCharacterValue and TargetCharacterValue:IsA("Model") then
        local Ghost = TargetCharacterValue:Clone() if not Ghost then return end
        local GhostParts = {}
        for Unused, DescendantObject in ipairs(Ghost:GetDescendants()) do
            if DescendantObject:IsA("BasePart") then
                GhostParts[#GhostParts + 1] = DescendantObject
                DescendantObject.Transparency = HitFeedbackState.ImpactTransparency
                DescendantObject.Color = HitFeedbackState.ImpactColor DescendantObject.Material = Material
                DescendantObject.CanCollide = false
                DescendantObject.Anchored = true
            elseif DescendantObject:IsA("Humanoid") or DescendantObject:IsA("Script") or DescendantObject:IsA("LocalScript") or DescendantObject:IsA("ModuleScript") then
                DescendantObject:Destroy()
            end
        end
        local PrimaryPart = Ghost.PrimaryPart or Ghost:FindFirstChild("HumanoidRootPart") or Ghost:FindFirstChild("Torso")
        if PrimaryPart then
            Ghost.PrimaryPart = PrimaryPart
            Ghost:PivotTo(CFrame.new(HitPosition - Vector3.new(0, 2.5, 0)))
        else
            Ghost:MoveTo(HitPosition)
        end
        Ghost.Parent = workspace
        local BasePosition = PrimaryPart and PrimaryPart.Position or HitPosition
        task.spawn(function()
            local Steps = 24
            for Index = 1, Steps do
                if not Ghost or not Ghost.Parent then break end
                if Animation ~= "Static" then
                    local Transparency = HitFeedbackState.ImpactTransparency + (Index / Steps) * (1 - HitFeedbackState.ImpactTransparency)
                    for PartIndex = 1, #GhostParts do
                        local PartObject = GhostParts[PartIndex]
                        if PartObject and PartObject.Parent then PartObject.Transparency = Transparency end
                    end
                end
                if Animation == "Rise" and PrimaryPart and PrimaryPart.Parent then
                    local NewPosition = BasePosition + Vector3.new(0, Index * 0.28, 0)
                    Ghost:PivotTo(CFrame.new(NewPosition) * PrimaryPart.CFrame.Rotation)
                end
                task.wait(Duration / Steps)
            end
            if Ghost then Ghost:Destroy() end
        end)
    else
        local GhostPart = Instance.new("Part")
        if HitFeedbackState.ImpactStyle == "Ball" then
            GhostPart.Shape = Enum.PartType.Ball
        elseif HitFeedbackState.ImpactStyle == "Cylinder" then
            GhostPart.Shape = Enum.PartType.Cylinder
        else
            GhostPart.Shape = Enum.PartType.Block
        end
        GhostPart.Size = Vector3.new(1.5, 1.5, 1.5)
        GhostPart.Anchored = true
        GhostPart.CanCollide = false
        GhostPart.Position = HitPosition
        GhostPart.Material = Material
        GhostPart.Color = HitFeedbackState.ImpactColor GhostPart.Transparency = HitFeedbackState.ImpactTransparency
        GhostPart.Parent = workspace
        local Goal = {}
        if Animation == "Rise" then Goal.Position = HitPosition + Vector3.new(0, 7, 0) Goal.Size = Vector3.new(0.5, 3, 0.5) end
        if Animation ~= "Static" then Goal.Transparency = 1 end
        if next(Goal) then TweenService:Create(GhostPart, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), Goal):Play() end
        task.delay(Duration, function()
            if GhostPart and GhostPart.Parent then GhostPart:Destroy() end
        end)
    end
end

HitVisualConnections = {}
HitVisualToolConnections = setmetatable({}, { __mode = "k" })
HitVisualPlayerConnections = setmetatable({}, { __mode = "k" })
HitVisualContainerConnections = setmetatable({}, { __mode = "k" })
local HitVisualLocalCharacterContainer = nil local HitVisualWorldCharactersConnection = nil local HitVisualWorldContainerConnection = nil
HitVisualBoundSignals = setmetatable({}, { __mode = "k" })
HitVisualHumanoidConnections = {}
HitVisualPreviousHealth = {}
HitVisualTrackedCharacters = {}
local HitVisualWorldCharacters = nil local HitVisualWorldContainer = nil local QueueConfirmedDamage

function Internal.DisconnectConnection(Connection)
    if Connection then Internal.Call(function() Connection:Disconnect() end) end
end

function Internal.DisconnectConnectionList(Connections)
    if not Connections then return end
    for Unused, Connection in pairs(Connections) do Internal.DisconnectConnection(Connection) end
    table.clear(Connections)
end

function Internal.DisconnectHitVisualContainer(Container)
    if not Container then return end
    local Connection = HitVisualContainerConnections[Container]
    if Connection then Internal.DisconnectConnection(Connection) end
    HitVisualContainerConnections[Container] = nil
end

function Internal.DisconnectHitVisualPlayer(Player)
    if not Player then return end
    local Connection = HitVisualPlayerConnections[Player]
    if Connection then Internal.DisconnectConnection(Connection) end
    HitVisualPlayerConnections[Player] = nil
end

function Internal.FindHitTargetInValue(Value, Visited, Depth)
    if typeof(Value) == "Instance" then
        if Value:IsA("BasePart") then return Internal.GetHumanoidCharacterFromPart(Value), Value end
        if Value:IsA("Humanoid") then
            local Character = Value.Parent
            if Character and Character:IsA("Model") then return Character, Character:FindFirstChild("Head") or Character:FindFirstChild("HumanoidRootPart") or Character.PrimaryPart end
        end
        if Value:IsA("Model") and Value:FindFirstChildOfClass("Humanoid") then return Value, Value:FindFirstChild("Head") or Value:FindFirstChild("HumanoidRootPart") or Value.PrimaryPart end
        return nil, nil
    end
    if type(Value) ~= "table" or Depth >= 3 or Visited[Value] then return nil, nil end
    Visited[Value] = true
    for Key, NestedValue in pairs(Value) do
        local Character, Part = Internal.FindHitTargetInValue(NestedValue, Visited, Depth + 1)
        if Character and Part then return Character, Part end
        Character, Part = Internal.FindHitTargetInValue(Key, Visited, Depth + 1)
        if Character and Part then return Character, Part end
    end
    return nil, nil
end

function Internal.ResolveHitSignalTarget(...)
    local Arguments = table.pack(...)
    local Visited = {}
    for Index = 1, Arguments.n do
        local Character, Part = Internal.FindHitTargetInValue(Arguments[Index], Visited, 0)
        if Character and Part then return Character, Part end
    end
    return nil, nil
end

function Internal.SpawnConfirmedWorldHitmarker(TargetPart, IsHeadshot)
    if not HitFeedbackState.HitmarkerEnabled or not TargetPart or not TargetPart:IsA("BasePart") or not TargetPart.Parent then return end

    local MarkerPart = Instance.new( "Part")

    MarkerPart.Name = "AtramentaWorldHitmarker"

    MarkerPart.Size = Vector3.new( 0.08, 0.08, 0.08)

    MarkerPart.Transparency = 1

    MarkerPart.Anchored = true

    MarkerPart.CanCollide = false

    MarkerPart.CanQuery = false

    MarkerPart.CanTouch = false

    MarkerPart.CFrame = CFrame.new( TargetPart.Position)

    MarkerPart.Parent = workspace

    local Billboard = Instance.new( "BillboardGui")

    Billboard.Name = "Marker"

    Billboard.AlwaysOnTop = true

    Billboard.LightInfluence = 0

    Billboard.Size = UDim2.fromOffset( 34, 34)

    Billboard.Adornee = MarkerPart

    Billboard.Parent = MarkerPart

    local Color = IsHeadshot and HitFeedbackState.HeadshotHitmarkerColor or HitFeedbackState.HitmarkerColor

    local Rotations = { 45, -45, 45, -45 }

    local Positions = { UDim2.new(0.5, 7, 0.5, 7), UDim2.new(0.5, 7, 0.5, -7), UDim2.new(0.5, -7, 0.5, -7), UDim2.new(0.5, -7, 0.5, 7) }

    for Index = 1, 4 do
        local Arm = Instance.new( "Frame")

        Arm.AnchorPoint = Vector2.new( 0.5, 0.5)

        Arm.Position = Positions[Index]

        Arm.Size = UDim2.fromOffset( 10, 2)

        Arm.Rotation = Rotations[Index]

        Arm.BackgroundColor3 = Color

        Arm.BorderSizePixel = 0

        Arm.Parent = Billboard

        TweenService:Create( Arm, TweenInfo.new( 0.20, Enum.EasingStyle.Quad, Enum.EasingDirection.Out ), { BackgroundTransparency = 1 } ):Play()
    end

    task.delay( 0.24, function()
            if MarkerPart.Parent then MarkerPart:Destroy() end
        end)
end

QueueConfirmedDamage = function(Player, Character, Damage, IsHeadshot, PartName, Shot)
    if not Player or not Character or not Character.Parent or not Damage or Damage <= 0 then return end

    if Shot and Ragebot and type(Ragebot.FinalizeValidationShot) == "function" then Ragebot.FinalizeValidationShot(Shot, true, Damage, "DamageConfirmed") end
    local TargetPart = PartName and Character:FindFirstChild(PartName, true) or IsHeadshot and Character:FindFirstChild("Head", true) or
        Character:FindFirstChild("HumanoidRootPart", true) or Character.PrimaryPart or Character:FindFirstChildWhichIsA("BasePart", true)
    if not TargetPart or not TargetPart:IsA("BasePart") then return end
    if type(HitFeedbackRuntimeState.SpawnConfirmedTracer) == "function" then HitFeedbackRuntimeState.SpawnConfirmedTracer( Shot, TargetPart) end

    Internal.SpawnConfirmedWorldHitmarker( TargetPart, IsHeadshot)

    Internal.SpawnConfirmedHitmarker(IsHeadshot)
    Internal.SpawnConfirmedHitImage()
    Internal.PlayConfirmedHitSound()

    if Shot and Shot.TargetWasDowned == true and Shot.FinishSoundPlayed ~= true then WatchAtramentaFinishSound( Player, Character, Shot) end

    Internal.SpawnGhostVisual(TargetPart.Position, Character)
    Internal.SpawnDamageIndicator(TargetPart, Damage, IsHeadshot)
    ExtendedVisualState:OnHit(TargetPart, Character, IsHeadshot)

    if CombatLogState.Enabled and CombatLogState.Hits then
        local PlayerName = CombatLogRuntime.GetDisplayName( Player)

        local RoundedDamage = math.max( math.floor( Damage + 0.5 ), 1)

        local Message

        local ReliablePartName = Shot and Shot.SignalConfirmed == true and PartName or nil

        if ReliablePartName and tostring(ReliablePartName) ~= "" then
            Message = "Hit [" .. PlayerName .. "] in " .. tostring(ReliablePartName) .. " for " .. tostring(RoundedDamage) .. " damage"
        else
            Message = "Hit [" .. PlayerName .. "] for " .. tostring(RoundedDamage) .. " damage"
        end

        local DetailParts = {}

        if Shot then DetailParts[ #DetailParts + 1 ] = CombatLogRuntime.GetShotSourceName( Shot) end

        local LocalRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild( "HumanoidRootPart")

        local TargetRoot = Character:FindFirstChild( "HumanoidRootPart")

        local Distance = LocalRoot and TargetRoot and ( LocalRoot.Position - TargetRoot.Position ).Magnitude or nil

        local DistanceText = CombatLogRuntime.FormatDistance( Distance)

        if DistanceText then DetailParts[ #DetailParts + 1 ] = DistanceText .. " studs" end

        if Shot and Ragebot and type(Ragebot.GetValidationLogDetail) == "function" then
            local ValidationDetail = Ragebot.GetValidationLogDetail(Shot)
            if ValidationDetail then DetailParts[#DetailParts + 1] = ValidationDetail end
        end

        CombatLogRuntime.Emit( "Hit", Message, table.concat( DetailParts, "  •  " ))

        local Humanoid = Character:FindFirstChildOfClass( "Humanoid")

        if Humanoid and Humanoid.Health <= 0 and ( not Shot or Shot.KillLogged ~= true ) then
            if Shot then Shot.KillLogged = true end

            CombatLogRuntime.Emit( "Kill", "Eliminated [" .. PlayerName .. "]", PartName and tostring(PartName) or "")
        end
    end
end

function Internal.BufferUnconfirmedDamage(Player, Character, Damage)
    local CurrentTime = os.clock() local Buffered = AttackConfirmationState.BufferedDamage[Player]
    if not Buffered or Buffered.Character ~= Character or CurrentTime - Buffered.Time > AttackConfirmationState.SignalWindow then
        Buffered = { Character = Character, Damage = 0, Time = CurrentTime, Version = 0 }
        AttackConfirmationState.BufferedDamage[Player] = Buffered
    end
    Buffered.Damage = Buffered.Damage + Damage
    Buffered.Time = CurrentTime
    Buffered.Version = Buffered.Version + 1
    local Version = Buffered.Version
    task.delay(AttackConfirmationState.SignalWindow, function()
        local Current = AttackConfirmationState.BufferedDamage[Player]
        if Current == Buffered and Current.Version == Version and os.clock() - Current.Time >= AttackConfirmationState.SignalWindow then
            AttackConfirmationState.BufferedDamage[Player] = nil
        end
    end)
end

function Internal.TryConfirmBufferedDamage(Shot)
    if not Shot or not Shot.Player then return false end
    local Buffered = AttackConfirmationState.BufferedDamage[Shot.Player]
    local CurrentTime = os.clock()
    if not Buffered or CurrentTime - Buffered.Time > AttackConfirmationState.SignalWindow or Buffered.Time < (tonumber(Shot.Time) or CurrentTime) - 0.08
        or not(Buffered.Character == Shot.Character or Internal.GetPlayerFromTrackedCharacter(Buffered.Character) == Shot.Player) then
        return false
    end
    if not Internal.CanConfirmShotDamage(Shot, Buffered.Time) then return false end
    AttackConfirmationState.BufferedDamage[Shot.Player] = nil
    Shot.DamageConfirmed = true
    Shot.ConfirmedAt = os.clock()
    Internal.ConfirmMergedRageShots(Shot, Shot.Player, Buffered.Character)
    QueueConfirmedDamage(Shot.Player, Buffered.Character, Buffered.Damage, Shot.PartName == "Head", Shot.PartName, Shot)
    return true
end

function Internal.FindRecentToolShot(Tool)
    local CurrentTime = os.clock()
    for Index = #AttackConfirmationState.Shots, 1, -1 do
        local Shot = AttackConfirmationState.Shots[Index]
        if Shot and Shot.VerifiedFire and Shot.Tool == Tool and not Shot.DamageConfirmed and CurrentTime - (Shot.Time or 0) <= AttackConfirmationState.DamageWindow then return Shot end
    end
    return nil
end

function Internal.HandleConfirmedHitSignal(Tool, ...)
    local Shot = Internal.FindRecentToolShot(Tool) if not Shot then return end
    local TargetCharacter, TargetPart = Internal.ResolveHitSignalTarget(...)
    if not TargetCharacter or not TargetPart then
        local MouseTarget = Mouse and Mouse.Target
        TargetPart = MouseTarget
        TargetCharacter = Internal.GetHumanoidCharacterFromPart(MouseTarget)
    end
    if TargetCharacter and TargetPart then Internal.AttachAttackTarget(Shot, TargetCharacter, TargetPart) end
    Shot.SignalConfirmed = true
    Internal.TryConfirmBufferedDamage(Shot)
end

function Internal.BindToolHitSignal(Tool, SignalObject)
    if not SignalObject or HitVisualBoundSignals[SignalObject] then return end
    local Signal
    if SignalObject:IsA("BindableEvent") then
        Signal = SignalObject.Event
    elseif SignalObject:IsA("RemoteEvent") then
        Signal = SignalObject.OnClientEvent
    end
    if not Signal then return end
    HitVisualBoundSignals[SignalObject] = true
    local Connections = HitVisualToolConnections[Tool] if not Connections then return end
    Connections[#Connections + 1] = Signal:Connect(function(...) Internal.HandleConfirmedHitSignal(Tool, ...) end)
end

function Internal.RegisterAttackTool(Tool)
    if not Tool or not Tool:IsA("Tool") or HitVisualToolConnections[Tool] then return end
    local Connections = {}
    HitVisualToolConnections[Tool] = Connections
    Connections[#Connections + 1] = Tool.ChildAdded:Connect(function(Child)
        HitFeedbackRuntimeState.BulletTracerWeaponCache[Tool] = nil
        HitFeedbackRuntimeState.BulletTracerMuzzleCache[Tool] = nil
        if Child.Name == "Hitmarker" then
            Internal.BindToolHitSignal(Tool, Child)
        elseif Child.Name == "Values" or Child.Name == "Config" then
            task.defer(Internal.BindBulletTracerAmmo, Tool, Connections)
        end
    end)
    Connections[#Connections + 1] = Tool.AncestryChanged:Connect(function()
        if Tool.Parent then return end
        Internal.DisconnectConnectionList(HitVisualToolConnections[Tool])
        HitVisualToolConnections[Tool] = nil
    end)
    Internal.BindToolHitSignal(Tool, Tool:FindFirstChild("Hitmarker"))
    Internal.BindBulletTracerAmmo(Tool, Connections)
    Connections[#Connections + 1] = Tool.Activated:Connect(function()
        if not Internal.IsShotTrackingEnabled() or not IsVerifiedLocalFirearmTool(Tool) then return end
        local ActivatedAt = os.clock()
        AttackConfirmationState.LastLocalActivationAt = ActivatedAt
        AttackConfirmationState.LastLocalActivationTool = Tool
        task.delay(0.03, function()
            if not Tool.Parent or not IsVerifiedLocalFirearmTool(Tool) then return end
            local LastRemote = HitFeedbackRuntimeState.BulletTracerLastRemoteShot[Tool] or 0
            if LastRemote >= ActivatedAt - 0.01 then return end

            local OriginPosition = Internal.GetBulletTracerOrigin(Tool)
            if typeof(OriginPosition) ~= "Vector3" then return end
            local TargetPlayer, TargetCharacter, TargetPart local TargetPosition local Source = "ActivationFallback"

            if Configuration and Configuration.AimBot and Configuration.AimBot.SilentEnabled and type(GetSilentAimTarget) == "function" then
                TargetPlayer, TargetCharacter, TargetPart = GetSilentAimTarget()
                if TargetPart then
                    TargetPosition = type(GetTargetPosition) == "function" and GetTargetPosition(TargetCharacter, TargetPlayer, "Silent Aim") or TargetPart.Position
                    Source = "SilentAimFallback"
                end
            elseif Configuration and Configuration.AimBot and Configuration.AimBot.AimbotEnabled and Configuration.AimBot.CurrentTarget then
                TargetPlayer = Configuration.AimBot.CurrentTarget
                TargetCharacter = TargetPlayer.Character
                TargetPart = TargetCharacter and (TargetCharacter:FindFirstChild(Configuration.AimBot.TargetPart) or TargetCharacter:FindFirstChild("Head") or TargetCharacter:FindFirstChild("HumanoidRootPart"))
                if TargetPart and TargetPart:IsA("BasePart") then
                    TargetPosition = type(GetTargetPosition) == "function" and GetTargetPosition(TargetCharacter, TargetPlayer, "Aimbot") or TargetPart.Position
                    Source = "Aimbot"
                end
            end

            TargetPosition = TargetPosition or Internal.GetBulletTracerTarget(OriginPosition, Tool)
            if typeof(TargetPosition) ~= "Vector3" then return end
            local Delta = TargetPosition - OriginPosition
            if Delta.Magnitude <= 0.01 then return end
            local Direction = Delta.Unit
            Internal.RegisterLocalAttack( TargetCharacter, TargetPart, nil, Tool, Source, OriginPosition, Direction)
        end)
    end)
end

function Internal.RegisterToolContainer(Container)
    if not Container or HitVisualContainerConnections[Container] then return end
    for _, Child in ipairs(Container:GetChildren()) do Internal.RegisterAttackTool(Child) end
    HitVisualContainerConnections[Container] = Container.ChildAdded:Connect(Internal.RegisterAttackTool)
end

function Internal.RegisterLocalCharacter(Character)
    if not Character then return end
    if HitVisualLocalCharacterContainer and HitVisualLocalCharacterContainer ~= Character then Internal.DisconnectHitVisualContainer(HitVisualLocalCharacterContainer) end
    HitVisualLocalCharacterContainer = Character
    Internal.RegisterToolContainer(Character)
    CombatLogRuntime.BindLocalDamage(Character)
end

function Internal.RegisterTargetCharacter(Player, Character)
    if Player == LocalPlayer or not Player then return end
    Character = ResolveTrackedCharacter(Player, Character)
    if not Character then return end
    local Humanoid = Character:FindFirstChildOfClass("Humanoid") or Character:WaitForChild("Humanoid", 5) if not Humanoid then return end
    if HitVisualTrackedCharacters[Player] == Character and HitVisualHumanoidConnections[Player] then return end
    Internal.DisconnectConnection(HitVisualHumanoidConnections[Player])
    AttackConfirmationState.PendingDamage[Player] = nil
    AttackConfirmationState.BufferedDamage[Player] = nil
    HitVisualTrackedCharacters[Player] = Character
    HitVisualPreviousHealth[Player] = Humanoid.Health
    HitVisualHumanoidConnections[Player] = Humanoid.HealthChanged:Connect(function(NewHealth)
        if HitVisualTrackedCharacters[Player] ~= Character then return end
        local PreviousHealth = HitVisualPreviousHealth[Player]
        HitVisualPreviousHealth[Player] = NewHealth
        if type(PreviousHealth) ~= "number" then return end
        local Damage = PreviousHealth - NewHealth
        if Damage <= 0 or not Internal.IsShotTrackingEnabled() then return end
        if #AttackConfirmationState.Shots == 0 then
            if os.clock() - (tonumber(AttackConfirmationState.LastLocalActivationAt) or 0) <= AttackConfirmationState.SignalWindow then
                Internal.BufferUnconfirmedDamage(Player, Character, Damage)
            end
            return
        end
        local Confirmation = Internal.FindTargetAwareAttackConfirmation(Player, Character)
        if not Confirmation then
            Internal.BufferUnconfirmedDamage(Player, Character, Damage)
            return
        end
        Confirmation.DamageConfirmed = true
        Confirmation.ConfirmedAt = os.clock()
        Internal.ConfirmMergedRageShots(Confirmation, Player, Character)
        QueueConfirmedDamage(Player, Character, Damage, Confirmation.PartName == "Head", Confirmation.PartName, Confirmation)
    end)
end

