DestroyHitFeedbackRuntime = function()
    if CombatLogRuntime.LocalDamageConnection then
        CombatLogRuntime.LocalDamageConnection:Disconnect()
        CombatLogRuntime.LocalDamageConnection = nil
    end

    for _, Connection in ipairs( CombatLogRuntime.EnemyShotConnections ) do
        if Connection then Connection:Disconnect() end
    end

    table.clear( CombatLogRuntime.EnemyShotConnections)

    CombatLogRuntime.EnemyShotConnection = nil
    CombatLogRuntime.RecentEnemyShots = {}
    CombatLogRuntime.RecentNearMissKeys = {}

    for Unused, Connection in ipairs(HitVisualConnections) do Internal.DisconnectConnection(Connection) end
    table.clear(HitVisualConnections)
    for Player in pairs(HitVisualPlayerConnections) do Internal.DisconnectHitVisualPlayer(Player) end
    for Container in pairs(HitVisualContainerConnections) do Internal.DisconnectHitVisualContainer(Container) end
    if HitVisualWorldCharactersConnection then Internal.DisconnectConnection(HitVisualWorldCharactersConnection); HitVisualWorldCharactersConnection = nil end
    if HitVisualWorldContainerConnection then Internal.DisconnectConnection(HitVisualWorldContainerConnection); HitVisualWorldContainerConnection = nil end
    HitVisualWorldCharacters = nil
    HitVisualWorldContainer = nil
    for Tool, Connections in pairs(HitVisualToolConnections) do
        Internal.DisconnectConnectionList(Connections)
        HitVisualToolConnections[Tool] = nil
    end
    for Player, Connection in pairs(HitVisualHumanoidConnections) do
        Internal.DisconnectConnection(Connection)
        HitVisualHumanoidConnections[Player] = nil
    end
    table.clear(HitVisualPreviousHealth)
    table.clear(HitVisualTrackedCharacters)
    table.clear(AttackConfirmationState.Shots)
    table.clear(AttackConfirmationState.PendingDamage)
    table.clear(AttackConfirmationState.BufferedDamage)
    AttackConfirmationState.LastLocalActivationAt = 0
    AttackConfirmationState.LastLocalActivationTool = nil
    for Object in pairs(HitFeedbackRuntimeState.ActiveObjects) do
        Internal.Call(function()
            if Object and Object.Parent then Object:Destroy() end
        end)
    end
    table.clear(HitFeedbackRuntimeState.ActiveObjects)
    table.clear(HitFeedbackRuntimeState.BulletTracerMuzzleCache)
    table.clear(HitFeedbackRuntimeState.BulletTracerAmmoObjects)
    table.clear(HitFeedbackRuntimeState.BulletTracerAmmoSuppression)
    table.clear(HitFeedbackRuntimeState.BulletTracerWeaponCache)
    table.clear(HitFeedbackRuntimeState.BulletTracerLastSpawn)
    table.clear(HitFeedbackRuntimeState.BulletTracerLastRemoteShot)
    local ShotHookState = Environment.AtramentaBulletTracerShotHook
    if type(ShotHookState) == "table" then ShotHookState.Enabled = false end
    HitFeedbackRuntimeState.ActiveBulletTracers = 0
end

function Internal.QueueTargetCharacterRegistration(Player, Character)
    task.spawn(function()
        local Deadline = os.clock() + 10 local ResolvedCharacter = ResolveTrackedCharacter(Player, Character)
        while Player and Player.Parent and os.clock() < Deadline and(not ResolvedCharacter or not ResolvedCharacter:FindFirstChildOfClass("Humanoid")) do
            task.wait(0.10)
            ResolvedCharacter = ResolveTrackedCharacter(Player, Character)
        end
        Internal.RegisterTargetCharacter(Player, ResolvedCharacter)
    end)
end

function Internal.RegisterTargetPlayer(Player)
    if Player == LocalPlayer or HitVisualPlayerConnections[Player] then return end
    Internal.QueueTargetCharacterRegistration(Player, Player.Character)
    HitVisualPlayerConnections[Player] = Player.CharacterAdded:Connect(function(Character) Internal.QueueTargetCharacterRegistration(Player, Character) end)
end

function Internal.BindWorldCharacterContainer(Characters)
    if not Characters or HitVisualWorldCharacters == Characters then return end
    if HitVisualWorldCharactersConnection then Internal.DisconnectConnection(HitVisualWorldCharactersConnection) end
    HitVisualWorldCharacters = Characters
    for _, Character in ipairs(Characters:GetChildren()) do
        local Player = Players:FindFirstChild(Character.Name)
        if Player and Player:IsA("Player") then Internal.QueueTargetCharacterRegistration(Player, Character) end
    end
    HitVisualWorldCharactersConnection = Characters.ChildAdded:Connect(function(Character)
        local Player = Players:FindFirstChild(Character.Name)
        if Player and Player:IsA("Player") then Internal.QueueTargetCharacterRegistration(Player, Character) end
    end)
end

local function BindWorldContainer(WorldContainer)
    if not WorldContainer or HitVisualWorldContainer == WorldContainer then return end
    if HitVisualWorldContainerConnection then Internal.DisconnectConnection(HitVisualWorldContainerConnection) end
    HitVisualWorldContainer = WorldContainer
    local Characters = WorldContainer:FindFirstChild("Characters")
    if Characters then Internal.BindWorldCharacterContainer(Characters) end
    HitVisualWorldContainerConnection = WorldContainer.ChildAdded:Connect(function(Child)
        if Child.Name == "Characters" then Internal.BindWorldCharacterContainer(Child) end
    end)
end

