HitFeedbackRuntimeState.RuntimeClock = 0
HitVisualConnections[#HitVisualConnections + 1] = RunService.Heartbeat:Connect(function(DeltaTime)
    HitFeedbackRuntimeState.RuntimeClock = (HitFeedbackRuntimeState.RuntimeClock or 0) + math.min(math.max(DeltaTime, 0), 0.05)
    HitFeedbackRuntimeState.ReconcileClock = (HitFeedbackRuntimeState.ReconcileClock or 0) + DeltaTime

    if HitFeedbackRuntimeState.RuntimeClock >= 1 / 30 then
        HitFeedbackRuntimeState.RuntimeClock = 0
        local CurrentTime = os.clock()
        CombatLogRuntime.ProcessEnemyShotQueue(CurrentTime)
        CombatLogRuntime.ProcessNearMissQueue(CurrentTime)
        CombatLogRuntime.MaintainRuntime(CurrentTime, false)
    end

    if HitFeedbackRuntimeState.ReconcileClock < 3 then return end
    HitFeedbackRuntimeState.ReconcileClock = 0
    if not Internal.IsShotTrackingEnabled() then return end

    for _, Player in ipairs(Players:GetPlayers()) do
        if Player ~= LocalPlayer then
            local Character = ResolveTrackedCharacter(Player, Player.Character) local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
            if Character and Humanoid and (HitVisualTrackedCharacters[Player] ~= Character or not HitVisualHumanoidConnections[Player]) then
                Internal.RegisterTargetCharacter(Player, Character)
            end
        end
    end
end)

