    Data.NextChamsUpdate = 0
    Data.LastEspDistance = 0
    Data.LastDistanceTextValue = nil
    Data.LastHealthTextValue = nil
    Data.LastAmmoText = nil
    Data.DisplayNameText = nil
    Data.LastEspAdaptiveColor = nil
    Data.LastEspAdaptiveOutline = nil
    Data.LastEspVisibilityState = "Visible"
    Data.NextVisibilityUpdate = 0
    Data.DisplayedHealthPercent = nil
    Data.DelayedHealthPercent = nil
    Data.LastHealthTargetPercent = nil
    Data.HealthDamageHoldUntil = 0
    Data.LastHealthVisualAt = 0
    Data.NextForcefieldUpdate = 0
    Data.CachedForcefield = false
    Data.VisualHidden = true
    if type(Internal.ResetPlayerEspBounds) == "function" then Internal.ResetPlayerEspBounds(Data) end
    if type(Data.Chams) == "table" then
        for _, Entry in pairs(Data.Chams) do
            if typeof(Entry) == "Instance" then
                if Entry.Parent then Entry:Destroy() end
            elseif type(Entry) == "table" then
                for _, Object in pairs(Entry) do
                    if typeof(Object) == "Instance" and Object.Parent then Object:Destroy() end
                end
            end
        end
    end

    if type(Data.ChamConnections) == "table" then
        for _, Connection in pairs(Data.ChamConnections) do
            if Connection and typeof(Connection)
                    == "RBXScriptConnection" then
                Connection:Disconnect()
            end
        end
    end

    if Data.ChamsGlow and Data.ChamsGlow.Parent then Data.ChamsGlow:Destroy() end

    if Data.ChamsHolder and Data.ChamsHolder.Parent then Data.ChamsHolder:Destroy() end

    Data.Chams = {}
    Data.ChamProxies = {}
    Data.ChamProxyList = {}
    Data.ChamsOutlineShells = {}
    Data.ChamsGlowShells = {}
    Data.ChamsSoftGlowShells = {}
    Data.ChamConnections = {}
    Data.ChamsHolder = nil
    Data.ChamsGlow = nil
    Data.ChamsCharacter = nil

    if VisualState.Player.Chams.Enabled then
        task.defer(function()
            if Data.Character == Character then ApplyPlayerChamData(Data) end
        end)
    end
end

