function Internal.RefreshPlayerEspOffsetCache()
    local PlayerState = VisualState.Player
    local Frame = tonumber(VisualState.Performance.ProjectionFrame) or 0
    local Cache = PlayerState.OffsetCache

    if type(Cache) ~= "table" then
        Cache = {}
        PlayerState.OffsetCache = Cache
    end

    if PlayerState.OffsetCacheFrame == Frame then return Cache end

    local Flags = type(Library) == "table" and type(Library.Flags) == "table" and Library.Flags or nil

    for Index = 1, #PlayerEspOffsetNames do
        local Name = PlayerEspOffsetNames[Index]
        local Value = Flags and Flags["Player ESP " .. Name .. " Offset"] or nil

        if typeof(Value) ~= "Vector2" then Value = Vector2.zero end
        if Name == "Health Bar" then Value = Vector2.new(Value.X, 0) end

        Cache[Name] = Value
    end

    PlayerState.OffsetCacheFrame = Frame
    return Cache
end

function GetPlayerESPPreviewOffset(Name)
    if type(Name) ~= "string" then return Vector2.zero end

    local Cache = Internal.RefreshPlayerEspOffsetCache()
    local Value = Cache and Cache[Name]

    return typeof(Value) == "Vector2" and Value or Vector2.zero
end
function ApplyPlayerESPPreviewOffset(BasePosition, Name)
    if typeof(BasePosition) ~= "Vector2" then return BasePosition end

    return BasePosition + GetPlayerESPPreviewOffset( Name)
end

function GetPlayerEspHealthColor(HealthPercent)
    local Alpha = math.clamp(tonumber(HealthPercent) or 0, 0, 1)
    local Low = VisualState.Player.HealthLowColor
    local Mid = VisualState.Player.HealthMidColor
    local High = VisualState.Player.HealthHighColor

    if Alpha <= 0.5 then return Low:Lerp(Mid, Alpha * 2) end
    return Mid:Lerp(High, (Alpha - 0.5) * 2)
end

function UpdatePlayerHealthAnimation(Data, TargetPercent, CurrentTime)
    if not Data then return math.clamp(tonumber(TargetPercent) or 0, 0, 1), math.clamp(tonumber(TargetPercent) or 0, 0, 1) end

    TargetPercent = math.clamp(tonumber(TargetPercent) or 0, 0, 1)
    CurrentTime = tonumber(CurrentTime) or os.clock()

    local Health = VisualState.Player.Health
    local LastTime = tonumber(Data.LastHealthVisualAt) or CurrentTime
    local DeltaTime = math.clamp(CurrentTime - LastTime, 0, 0.10)
    Data.LastHealthVisualAt = CurrentTime

    local Displayed = tonumber(Data.DisplayedHealthPercent)
    local Delayed = tonumber(Data.DelayedHealthPercent)
    local PreviousTarget = tonumber(Data.LastHealthTargetPercent)

    if Displayed == nil then Displayed = TargetPercent end
    if Delayed == nil then Delayed = TargetPercent end
    if PreviousTarget == nil then PreviousTarget = TargetPercent end

    if DeltaTime > 0 then
        local SmoothSpeed = math.max(tonumber(Health.SmoothSpeed) or 12, 0.1)
        local Alpha = 1 - math.exp(-SmoothSpeed * DeltaTime)
        Displayed += (TargetPercent - Displayed) * Alpha
        if math.abs(TargetPercent - Displayed) <= 0.001 then Displayed = TargetPercent end
    end

    if TargetPercent > PreviousTarget + 0.001 then
        Delayed = math.max(Delayed, Displayed, TargetPercent)
        Data.HealthDamageHoldUntil = CurrentTime
    elseif TargetPercent < PreviousTarget - 0.001 then
        Data.HealthDamageHoldUntil = CurrentTime + math.max(tonumber(Health.DelayHold) or 0.12, 0)
    end

    Delayed = math.max(Delayed, Displayed)

    if Health.Delayed ~= true then
        Delayed = Displayed
    elseif CurrentTime >= (tonumber(Data.HealthDamageHoldUntil) or 0) and Delayed > Displayed and DeltaTime > 0 then
        local DelaySpeed = math.max(tonumber(Health.DelaySpeed) or 7.5, 0.1)
        local Alpha = 1 - math.exp(-DelaySpeed * DeltaTime)
        Delayed += (Displayed - Delayed) * Alpha
        if Delayed - Displayed <= 0.001 then Delayed = Displayed end
    end

    Displayed = math.clamp(Displayed, 0, 1)
    Delayed = math.clamp(math.max(Delayed, Displayed), 0, 1)

    Data.DisplayedHealthPercent = Displayed
    Data.DelayedHealthPercent = Delayed
    Data.LastHealthTargetPercent = TargetPercent

    return Displayed, Delayed
end

function RequestAtramentaProfileData(Url)
    if type(Url) ~= "string" or Url == "" then return nil end

    local RequestFunctions = { Environment and Environment.request, Environment and Environment.http_request, type(syn) == "table" and syn.request or nil,
        type(http) == "table" and http.request or nil, type(fluxus) == "table" and fluxus.request or nil }

    for Index = 1, #RequestFunctions do
        local RequestFunction = RequestFunctions[Index]

        if type(RequestFunction) == "function" then
            local Success, Response = Internal.Call( RequestFunction, { Url = Url, Method = "GET", Headers = { ["Accept"] = "*/*",
                        ["User-Agent"] = "Atramenta.rip" } })

            local Body = Success and Internal.ExtractHttpBody(Response) or nil
            if type(Body) == "string" and #Body > 24 then return Body end
        end
    end

    local Success, Body = Internal.Call(function()
        return game:HttpGet(Url, true)
    end)

    if Success and type(Body) == "string" and #Body > 24 then return Body end
    return nil
end

function FetchAtramentaProfilePicture(UserId)
    UserId = tonumber(UserId)
    if not UserId or UserId <= 0 then return nil end

    local ApiUrl = "https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=" .. tostring(math.floor(UserId)) .. "&size=180x180&format=Png&isCircular=false"

    local Json = RequestAtramentaProfileData(ApiUrl)
    if type(Json) ~= "string" then return nil end

    local DecodeSuccess, Decoded = Internal.Call(function()
        return game:GetService("HttpService"):JSONDecode(Json)
    end)

    if not DecodeSuccess or type(Decoded) ~= "table" or type(Decoded.data) ~= "table" or type(Decoded.data[1]) ~= "table" then return nil end

    local ImageUrl = Decoded.data[1].imageUrl
    if type(ImageUrl) ~= "string" or ImageUrl == "" then return nil end

    local Data = RequestAtramentaProfileData(ImageUrl)
    if type(Data) ~= "string" or #Data <= 64 then return nil end
    return Data
end

function QueueAtramentaProfilePicture(Data)
    if type(Data) ~= "table" or not Data.Player then return end

    local UserId = tonumber(Data.Player.UserId)
    if not UserId or UserId <= 0 then return end

    local Cache = VisualState.Player.ProfilePictureCache local Entry = Cache[UserId] local CurrentTime = os.clock()

    if type(Entry) == "table" then
        if type(Entry.Data) == "string" and #Entry.Data > 64 then
            Data.ProfilePictureData = Entry.Data
            return
        end

        if Entry.Loading == true then return end
        if CurrentTime < (tonumber(Entry.RetryAt) or 0) then return end
    else
        Entry = {}
        Cache[UserId] = Entry
    end

    Entry.Loading = true

    task.spawn(function()
        local PictureData = FetchAtramentaProfilePicture(UserId)

        Entry.Loading = false
        Entry.Time = os.clock()

        if type(PictureData) == "string" and #PictureData > 64 then
            Entry.Data = PictureData
            Entry.RetryAt = 0

            if Data.Player and Data.Player.Parent then
                Data.ProfilePictureData = PictureData
                Data.ProfilePictureApplied = false
            end
        else
            Entry.RetryAt = os.clock() + 30
        end
    end)
end

function Internal.CreatePlayerVisual(Player, WithDrawings)
    local Data = VisualState.Player.Objects[Player]
    if not Data then
        Data = { Player = Player, Character = nil, Humanoid = nil, Root = nil, Head = nil, ToolName = nil, NextToolScan = 0, LevelValue = nil, NextLevelScan = 0,
            ProfilePictureData = nil, ProfilePictureApplied = false, NextEspUpdate = 0, LastEspDistance = 0, LastDistanceTextValue = nil, LastHealthTextValue = nil,
            LastEspAdaptiveColor = nil, LastEspVisibilityState = "Visible", NextVisibilityUpdate = 0, DisplayedHealthPercent = nil, DelayedHealthPercent = nil, LastHealthTargetPercent = nil, HealthDamageHoldUntil = 0, LastHealthVisualAt = 0, LastAmmoText = nil,
            DisplayNameText = nil, VisualHidden = true, VisualResolverSnapshot = nil, VisualResolverAt = 0, VisualResolverCharacter = nil, EspEligible = false,
            VisualRenderPose = nil, VisualRenderPoseFrame = -1, VisualRenderPoseTime = 0,
            SkeletonCacheCharacter = nil, SkeletonConnectionCache = nil, SkeletonProjectionCache = nil,
            CachedAmmoTool = nil, CachedAmmoValues = nil, CachedAmmoCurrentObject = nil, CachedAmmoStoredObject = nil, CachedAmmoMaximum = nil,
            CachedAmmoCurrent = nil, CachedAmmoStored = nil, NextAmmoBindingScan = 0, NextWallbangVisibilityUpdate = 0, CachedWallbangable = false,
            NextFastDetailUpdate = 0, LastProjectionHealthAt = 0,
            NextForcefieldUpdate = 0, CachedForcefield = false,
            NextChamsUpdate = 0, ChamTier = 0, ChamsRenderActive = false, LastChamDistance = 0, LastChamExpansion = -1, ChamsCharacter = nil, ChamsHolder = nil, ChamsGlow = nil,
            Chams = {}, ChamProxies = {}, ChamProxyList = {}, ChamsOutlineShells = {}, ChamsGlowShells = {}, ChamsSoftGlowShells = {}, ChamConnections = {},
            CharacterAddedConnection = nil, CharacterRemovingConnection = nil, CharacterGeneration = 0, Drawings = {}, CornerOutlines = {}, Corners = {}, TracerCurves = {}, DrawingsReady = false,
            UiEsp = nil, UiThumbnailRequested = false, CornersReady = false, ListIndex = 0 }
        VisualState.Player.Objects[Player] = Data
        Data.ListIndex = #VisualState.Player.List + 1
        VisualState.Player.List[Data.ListIndex] = Data
        Data.CharacterAddedConnection = Player.CharacterAdded:Connect(function(Character)
            Data.CharacterGeneration = (tonumber(Data.CharacterGeneration) or 0) + 1
            local Generation = Data.CharacterGeneration
            task.spawn(function()
                local Deadline = os.clock() + 8 local Resolved = ResolveTrackedCharacter(Player, Character)
                while Player.Parent and Data.CharacterGeneration == Generation and os.clock() < Deadline do
                    Resolved = ResolveTrackedCharacter(Player, Character)
                    if Resolved and Resolved:FindFirstChildOfClass("Humanoid") and(Resolved:FindFirstChild("HumanoidRootPart") or Resolved:FindFirstChild("Torso") or Resolved:FindFirstChild("UpperTorso")) then break end
                    task.wait(0.12)
                end
                if not Player.Parent or Data.CharacterGeneration ~= Generation then return end
                Internal.RefreshPlayerCharacter(Data, Resolved or Character)
            end)
        end)
        Internal.Call(function()
            Data.CharacterRemovingConnection = Player.CharacterRemoving:Connect(function(Character)
                if Player.Character and Player.Character ~= Character then return end
                if Data.Character == Character or(Data.Character and Data.Character.Name == Character.Name) then
                    Data.CharacterGeneration = (tonumber(Data.CharacterGeneration) or 0) + 1
                    local Generation = Data.CharacterGeneration
                    if type(Internal.HidePlayerVisual) == "function" then Internal.HidePlayerVisual(Data) end
                    Data.EspEligible = false
                    task.delay(0.35, function()
                        if not Player.Parent or Data.CharacterGeneration ~= Generation then return end
                        local Resolved = ResolveTrackedCharacter(Player, Player.Character)
                        if Resolved and Resolved ~= Character then
                            Internal.RefreshPlayerCharacter(Data, Resolved)
                        else
                            Internal.RefreshPlayerCharacter(Data, nil)
                        end
                    end)
                end
            end)
        end)
        Data.CharacterGeneration = (tonumber(Data.CharacterGeneration) or 0) + 1
        local InitialGeneration = Data.CharacterGeneration
        task.spawn(function()
            local Deadline = os.clock() + 6 local Resolved = ResolveTrackedCharacter(Player, Player.Character)
            while Player.Parent and Data.CharacterGeneration == InitialGeneration and os.clock() < Deadline and(not Resolved or not Resolved:FindFirstChildOfClass("Humanoid")) do
                task.wait(0.15)
                Resolved = ResolveTrackedCharacter(Player, Player.Character)
            end
            if not Player.Parent or Data.CharacterGeneration ~= InitialGeneration then return end
            Internal.RefreshPlayerCharacter(Data, Resolved or Player.Character)
        end)
    end
    if not WithDrawings or Data.DrawingsReady then return Data end
    Data.DrawingsReady = true
    local function Add(Name, DrawingType, Properties)
        local Object = Internal.CreateDrawing(DrawingType, Properties)
        Data.Drawings[Name] = Object
        return Object
    end
    Add("Fill", "Square", { Visible = false, Filled = true, Thickness = 1, Transparency = 0.18, ZIndex = 1 })
    Add("BoxOutline", "Square", { Visible = false, Filled = false, Thickness = 2, Color = Color3.new(0, 0, 0), Transparency = 0.95, ZIndex = 2 })
    Add("Box", "Square", { Visible = false, Filled = false, Thickness = 1, Transparency = 1, ZIndex = 3 })
    local DrawingFont = Internal.GetDrawingTextFont()
    Add("Name", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("Forcefield", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 6 })
    Add("Weapon", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("Distance", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("Level", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Add("HealthBack", "Square", { Visible = false, Filled = true, Color = Color3.new(0, 0, 0), Transparency = 0.86, ZIndex = 3 })
    Add("HealthDelayed", "Square", { Visible = false, Filled = true, Transparency = 0.95, ZIndex = 3 })
    Add("Health", "Square", { Visible = false, Filled = true, Transparency = 1, ZIndex = 4 })
    Add("HealthText", "Text", { Visible = false, Center = true, Outline = true, Font = DrawingFont, Transparency = 1, ZIndex = 5 })
    Data.SkeletonLines = Data.SkeletonLines or {}
    return Data
end

