function Internal.GetPlayerVisualResolverSnapshot(Data, CurrentTime, RefreshInterval)
    if not Data or not Data.Player or not Data.Character then return nil end

    CurrentTime = tonumber(CurrentTime) or os.clock()
    RefreshInterval = math.clamp(tonumber(RefreshInterval) or 1 / 45, 1 / 60, 0.10)

    if Data.VisualResolverCharacter == Data.Character and type(Data.VisualResolverSnapshot) == "table"
        and CurrentTime - (tonumber(Data.VisualResolverAt) or 0) < RefreshInterval
    then
        return Data.VisualResolverSnapshot
    end

    local Snapshot = type(ResolverGetTargetSnapshot) == "function" and ResolverGetTargetSnapshot(Data.Player, Data.Character) or nil

    Data.VisualResolverSnapshot = Snapshot
    Data.VisualResolverAt = CurrentTime
    Data.VisualResolverCharacter = Data.Character
    return Snapshot
end

