function GetEquippedToolAndAmmo(Data, CurrentTime)
    if not Data then return nil, nil, nil, nil end
    CurrentTime = tonumber(CurrentTime) or os.clock()

    local Character = Data.Character
    if not Character then return nil, nil, nil, nil end

    local Tool = Data.CachedAmmoTool
    if not Tool or not Tool.Parent or Tool.Parent ~= Character or CurrentTime >= (tonumber(Data.NextAmmoBindingScan) or 0) then
        Tool = Character:FindFirstChildOfClass("Tool")
        Data.NextAmmoBindingScan = CurrentTime + 0.20

        if Tool ~= Data.CachedAmmoTool then
            Data.CachedAmmoTool = Tool
            Data.CachedAmmoValues = nil
            Data.CachedAmmoCurrentObject = nil
            Data.CachedAmmoStoredObject = nil
            Data.CachedAmmoMaximum = nil
            Data.MaxObservedAmmo = nil
        end

        if Tool then
            local Values = Tool:FindFirstChild("Values")
            Data.CachedAmmoValues = Values
            Data.CachedAmmoCurrentObject = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo")) or nil
            Data.CachedAmmoStoredObject = Values and (Values:FindFirstChild("SERVER_StoredAmmo") or Values:FindFirstChild("StoredAmmo")) or nil

            local Config = Ragebot and type(Ragebot.GetWeaponConfig) == "function" and Ragebot.GetWeaponConfig(Tool) or nil
            Data.CachedAmmoMaximum = type(Config) == "table" and tonumber(rawget(Config, "MagSize")) or nil
        end
    end

    if not Tool then
        Data.CachedAmmoCurrent = nil
        Data.CachedAmmoStored = nil
        return nil, nil, nil, nil
    end

    local CurrentObject = Data.CachedAmmoCurrentObject local StoredObject = Data.CachedAmmoStoredObject
    local Current = CurrentObject and CurrentObject.Parent and tonumber(CurrentObject.Value) or nil
    local Stored = StoredObject and StoredObject.Parent and tonumber(StoredObject.Value) or nil local Maximum = tonumber(Data.CachedAmmoMaximum)

    if not Maximum and type(Current) == "number" then
        Data.MaxObservedAmmo = math.max(tonumber(Data.MaxObservedAmmo) or 0, Current)
        Maximum = tonumber(Data.MaxObservedAmmo)
    end

    Data.CachedAmmoCurrent = Current
    Data.CachedAmmoStored = Stored
    Data.CachedAmmoMaximum = Maximum
    return Tool, Current, Maximum, Stored
end

function GetPlayerVisibilityState(Data, LocalRoot, CurrentTime)
    local Settings = VisualState.Player.Visibility
    if not Settings.Enabled or not Data or not Data.Root or not LocalRoot then return "Visible" end
    if CurrentTime < (tonumber(Data.NextVisibilityUpdate) or 0) and type(Data.LastEspVisibilityState) == "string" then return Data.LastEspVisibilityState end

    local PlayerCount = math.max(tonumber(VisualState.Performance.PlayerCount) or 0, 0)
    local VisibilityInterval = math.max(tonumber(Settings.CacheInterval) or 0.12, PlayerCount >= 28 and 0.16 or PlayerCount >= 18 and 0.14 or 0.10)
    Data.NextVisibilityUpdate = CurrentTime + VisibilityInterval

    local TargetPart = Data.Head or Data.Root local CameraObject = Internal.GetCamera()
    local Origin = CameraObject and CameraObject.CFrame.Position or LocalRoot.Position local Params = VisualPerformanceRuntime.VisibilityParams
    local LocalCharacter = LocalPlayer.Character

    if VisualPerformanceRuntime.VisibilityCharacter ~= LocalCharacter then
        VisualPerformanceRuntime.VisibilityCharacter = LocalCharacter
        Params.FilterDescendantsInstances = LocalCharacter and {LocalCharacter} or {}
    end

    local Result = workspace:Raycast(Origin, TargetPart.Position - Origin, Params)
    local Visible = Result == nil or Result.Instance and Result.Instance:IsDescendantOf(Data.Character) local State = "Visible"

    if not Visible then
        local Wallbangable = Data.CachedWallbangable == true
        if CurrentTime >= (tonumber(Data.NextWallbangVisibilityUpdate) or 0) then
            local WallbangInterval = PlayerCount >= 28 and 0.34 or PlayerCount >= 18 and 0.28 or 0.22
            Data.NextWallbangVisibilityUpdate = CurrentTime + WallbangInterval
            Wallbangable = false
            if Ragebot and type(Ragebot.RayCheck) == "function" then
                local Success, CanPenetrate = Internal.Call(Ragebot.RayCheck, LocalRoot.Position, TargetPart.Position, TargetPart)
                Wallbangable = Success and CanPenetrate == true
            end
            Data.CachedWallbangable = Wallbangable
        end
        State = Wallbangable and "Wallbang" or "Hidden"
    else
        Data.CachedWallbangable = false
    end

    Data.LastEspVisibilityState = State
    return State
end

function GetAdaptiveEspColor(Data, LocalRoot, CurrentTime)
    local Settings = VisualState.Player.Visibility local BoxColor = VisualState.Player.BoxColor local OutlineColor = VisualState.Player.OutlineColor

    if Settings.Enabled then
        local State = GetPlayerVisibilityState(Data, LocalRoot, CurrentTime)
        if State == "Hidden" then
            BoxColor = Settings.HiddenColor
        elseif State == "Wallbang" then
            BoxColor = Settings.WallbangColor
        else
            BoxColor = Settings.VisibleColor
        end
    end

    local ActiveTarget = VisualState.Performance.ActiveTarget or Internal.GetActiveConfirmedCombatTarget()
    if ActiveTarget and Data.Player == ActiveTarget then BoxColor = Settings.TargetColor or BoxColor end

    Data.LastEspAdaptiveColor = BoxColor
    return BoxColor, OutlineColor
end

function UpdateOffscreenArrow(Data, CameraObject, WorldPosition, Distance, Color)
    local Settings = VisualState.Player.Offscreen
    if not Settings.Enabled or not Data or not WorldPosition then
        HideOffscreenArrowDrawings(Data)
        return
    end
    if not EnsureOffscreenDrawings(Data) then return end

    local ScreenPosition, OnScreen = CameraObject:WorldToViewportPoint(WorldPosition) local Viewport = CameraObject.ViewportSize
    if OnScreen and ScreenPosition.Z > 0 and ScreenPosition.X >= 0 and ScreenPosition.X <= Viewport.X and ScreenPosition.Y >= 0 and ScreenPosition.Y <= Viewport.Y then
        HideOffscreenArrowDrawings(Data)
        return
    end

    local Center = Viewport * 0.5 local Delta = Vector2.new(ScreenPosition.X - Center.X, ScreenPosition.Y - Center.Y)
    if ScreenPosition.Z <= 0 then Delta = -Delta end
    if Delta.Magnitude <= 0.001 then Delta = Vector2.new(0, -1) end
    local Unit = Delta.Unit local Radius = math.max(math.min(Viewport.X, Viewport.Y) * math.clamp(tonumber(Settings.Radius) or 0.88, 0.45, 0.94) * 0.5, 24)
    local Size = math.max(tonumber(Settings.Size) or 16, 8) local Tip = Center + Unit * Radius
    local Base = Center + Unit * (Radius - Size) local Perpendicular = Vector2.new(-Unit.Y, Unit.X) * (Size * 0.55)
    local Left = Base + Perpendicular local Right = Base - Perpendicular
    local Points = {{Tip, Left}, {Tip, Right}, {Left, Right}}

    for Index = 1, 3 do
        local Outline = Data.Drawings["OffscreenOutline" .. Index] local Line = Data.Drawings["Offscreen" .. Index] local Pair = Points[Index]
        SetLine(Outline, Pair[1], Pair[2], Settings.OutlineColor, true, 3, 0.95)
        SetLine(Line, Pair[1], Pair[2], Color or Settings.Color, true, 1.5, 1)
    end

    if Data.Drawings.OffscreenDistance then
        Data.Drawings.OffscreenDistance.Visible = Settings.ShowDistance == true
        if Settings.ShowDistance == true then
            Data.Drawings.OffscreenDistance.Color = Color or Settings.Color
            Data.Drawings.OffscreenDistance.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
            Data.Drawings.OffscreenDistance.Text = tostring(math.floor((tonumber(Distance) or 0) + 0.5)) .. "m"
            Data.Drawings.OffscreenDistance.Position = Base + Unit * (Size + 10)
        end
    end
end

function GetSkeletonConnectionCache(Data)
    if not Data or not Data.Character then return nil end
    if Data.SkeletonCacheCharacter == Data.Character and type(Data.SkeletonConnectionCache) == "table" then return Data.SkeletonConnectionCache end

    local Cache = {}
    for Index = 1, #PlayerSkeletonConnections do
        local Entry = PlayerSkeletonConnections[Index]
        local From = GetFirstCharacterPart(Data.Character, {Entry[1], Entry[3], Entry[4]})
        local To = GetFirstCharacterPart(Data.Character, {Entry[2], Entry[3], Entry[4]})
        Cache[Index] = {From, To}
    end

    Data.SkeletonCacheCharacter = Data.Character
    Data.SkeletonConnectionCache = Cache
    Data.SkeletonProjectionCache = Data.SkeletonProjectionCache or {}
    return Cache
end

function UpdateSkeletonEsp(Data, CameraObject, Color)
    local Settings = VisualState.Player.Skeleton

    if not Settings.Enabled or not Data or not Data.Character then
        HideSkeletonDrawings(Data)
        return
    end

    if not EnsureSkeletonDrawings(Data) then return end

    local Connections = GetSkeletonConnectionCache(Data)

    if not Connections then
        HideSkeletonDrawings(Data)
        return
    end

    local Pose = GetPlayerVisualRenderPose(Data, os.clock())
    local Offset = Pose and Pose.Offset or Vector3.zero
    local ProjectionCache = Data.SkeletonProjectionCache or {}

    Data.SkeletonProjectionCache = ProjectionCache
    table.clear(ProjectionCache)

    local Thickness = math.max(tonumber(Settings.Thickness) or 1.5, 1)
    local Transparency = 1 - math.clamp(tonumber(Settings.Transparency) or 0.05, 0, 0.95)
    local LineColor = Color or Settings.Color

    for Index = 1, #Connections do
        local Line = Data.SkeletonLines and Data.SkeletonLines[Index] or nil
        if not Line then continue end

        local Pair = Connections[Index]
        local From = Pair and Pair[1] or nil
        local To = Pair and Pair[2] or nil

        if not From or not To or not From.Parent or not To.Parent then
            Line.Visible = false
            continue
        end

        local FromProjection = ProjectionCache[From]

        if not FromProjection then
            local Screen, Visible = CameraObject:WorldToViewportPoint(From.Position + Offset)
            FromProjection = {Screen, Visible and Screen.Z > 0}
            ProjectionCache[From] = FromProjection
        end

        local ToProjection = ProjectionCache[To]

        if not ToProjection then
            local Screen, Visible = CameraObject:WorldToViewportPoint(To.Position + Offset)
            ToProjection = {Screen, Visible and Screen.Z > 0}
            ProjectionCache[To] = ToProjection
        end

        local Visible = FromProjection[2] and ToProjection[2]
        Line.Visible = Visible

        if Visible then
            local FromScreen = FromProjection[1]
            local ToScreen = ToProjection[1]

            Line.From = Vector2.new(FromScreen.X, FromScreen.Y)
            Line.To = Vector2.new(ToScreen.X, ToScreen.Y)
            Line.Color = LineColor
            Line.Thickness = Thickness
            Line.Transparency = Transparency
        end
    end
end
function UpdateLookLine(Data, CameraObject, Color)
    local Settings = VisualState.Player.Look
    local Line = Settings.Enabled and EnsureLookDrawing(Data) or Data and Data.Drawings and Data.Drawings.LookLine or nil

    if not Settings.Enabled or not Line or not Data or not Data.Head or not Data.Head.Parent then
        if Line then Line.Visible = false end
        return
    end

    local Pose = GetPlayerVisualRenderPose(Data, os.clock())
    local Offset = Pose and Pose.Offset or Vector3.zero
    local Start = Data.Head.Position + Offset
    local Finish = Start + Data.Head.CFrame.LookVector * math.max(tonumber(Settings.Length) or 6, 1)

    local StartScreen, StartVisible = CameraObject:WorldToViewportPoint(Start)
    local EndScreen, EndVisible = CameraObject:WorldToViewportPoint(Finish)

    if not StartVisible or not EndVisible or StartScreen.Z <= 0 or EndScreen.Z <= 0 then
        Line.Visible = false
        return
    end

    Line.Visible = true
    Line.From = Vector2.new(StartScreen.X, StartScreen.Y)
    Line.To = Vector2.new(EndScreen.X, EndScreen.Y)
    Line.Color = Color or Settings.Color
    Line.Thickness = math.max(tonumber(Settings.Thickness) or 1, 1)
    Line.Transparency = 1
end
function BuildPlayerFlagsText(Data, Distance, AmmoCurrent, AmmoMaximum)
    if not VisualState.Player.Flags.Enabled then return nil end
    local Entries = {}
    if Internal.IsAtramentaPlayerActuallyDowned and Internal.IsAtramentaPlayerActuallyDowned(Data.Player) then Entries[#Entries + 1] = "DOWN" end
    if Data.CachedForcefield == true then Entries[#Entries + 1] = "FF" end
    local ActiveTarget = Internal.GetActiveConfirmedCombatTarget()
    if ActiveTarget and Data.Player == ActiveTarget then Entries[#Entries + 1] = "TARGET" end
    if VisualState.Player.Flags.ShowAmmo and type(AmmoCurrent) == "number" and type(AmmoMaximum) == "number" and AmmoMaximum > 0 then
        Entries[#Entries + 1] = string.format("AMMO %d/%d", math.floor(AmmoCurrent + 0.5), math.floor(AmmoMaximum + 0.5))
    end
    if VisualState.Player.Flags.ShowVelocity and Data.Root then Entries[#Entries + 1] = string.format("SPD %.0f", Data.Root.AssemblyLinearVelocity.Magnitude) end
    if VisualState.Player.Flags.ShowDistance then Entries[#Entries + 1] = string.format("%.0fm", tonumber(Distance) or 0) end
    if Data.LastEspVisibilityState == "Wallbang" then Entries[#Entries + 1] = "WB" end
    return #Entries > 0 and table.concat(Entries, "\n") or nil
end

function UpdatePredictionMarker(Data, CameraObject)
    local Settings = VisualState.Player.Prediction

    if Settings.Enabled then EnsurePredictionDrawings(Data) end

    local Marker = Data and Data.Drawings and Data.Drawings.PredictionMarker or nil
    local Outline = Data and Data.Drawings and Data.Drawings.PredictionOutline or nil

    if not Settings.Enabled or not Marker or not Outline or not Data then
        if Marker then Marker.Visible = false end
        if Outline then Outline.Visible = false end
        return
    end

    local ActiveTarget = Internal.GetActiveConfirmedCombatTarget()

    if ActiveTarget ~= Data.Player then
        Marker.Visible = false
        Outline.Visible = false
        return
    end

    local TargetPart = Data.Head or Data.Root

    if not TargetPart then
        Marker.Visible = false
        Outline.Visible = false
        return
    end

    local Pose = GetPlayerVisualRenderPose(Data, os.clock())
    local Offset = Pose and Pose.Offset or Vector3.zero
    local Lead = math.max(tonumber(Settings.Lead) or 0.12, 0)
    local Position = TargetPart.Position + Offset + TargetPart.AssemblyLinearVelocity * Lead
    local ScreenPosition, Visible = CameraObject:WorldToViewportPoint(Position)

    if not Visible or ScreenPosition.Z <= 0 then
        Marker.Visible = false
        Outline.Visible = false
        return
    end

    local Point = Vector2.new(ScreenPosition.X, ScreenPosition.Y)
    local Radius = math.max(tonumber(Settings.Radius) or 4, 2)

    Marker.Visible = true
    Marker.Position = Point
    Marker.Radius = Radius
    Marker.Color = Settings.Color

    Outline.Visible = true
    Outline.Position = Point
    Outline.Radius = Radius + 1
end
function UpdateBoxGlow(Data, Position, Size, Color)
    local Settings = VisualState.Player.BoxGlow
    if Settings.Enabled then EnsureBoxGlowDrawings(Data) end
    for Index = 1, 3 do
        local Box = Data.Drawings["GlowBox" .. Index]
        if not Box then continue end
        local Visible = Settings.Enabled and VisualState.Player.Boxes
        Box.Visible = Visible
        if Visible then
            local Expansion = Index * 2
            Box.Position = Position - Vector2.new(Expansion, Expansion)
            Box.Size = Size + Vector2.new(Expansion * 2, Expansion * 2)
            Box.Color = Color or Settings.Color
            Box.Transparency = 1 - math.clamp((1 - (tonumber(Settings.Transparency) or 0.78)) / Index, 0.02, 0.95)
            Box.Thickness = 1
        end
    end
end

function GetPlayerUiEspRoot()
    local Root = VisualState.Player.UiRoot
    if Root and Root.Parent then return Root end

    local Parent = Internal.GetHitFeedbackGuiParent()
    if not Parent then return nil end

    Root = Instance.new("ScreenGui")
    Root.Name = "AtramentaPlayerESP"
    Root.IgnoreGuiInset = true
    Root.ResetOnSpawn = false
    Root.DisplayOrder = 95
    Root.ZIndexBehavior = Enum.ZIndexBehavior.Global
    Root.Parent = Parent
    VisualState.Player.UiRoot = Root
    return Root
end

