function EnsurePlayerUiEsp(Data)
    if not Data then return nil end
    local Existing = Data.UiEsp
    if Existing and Existing.Root and Existing.Root.Parent then return Existing end

    local Screen = GetPlayerUiEspRoot()
    if not Screen then return nil end

    local Root = Instance.new("Frame")
    Root.Name = tostring(Data.Player and Data.Player.UserId or "Player")
    Root.BackgroundTransparency = 1
    Root.BorderSizePixel = 0
    Root.ClipsDescendants = false
    Root.Visible = false
    Root.ZIndex = 4
    Root.Parent = Screen

    local Fill = Instance.new("Frame")
    Fill.Name = "Fill"
    Fill.BorderSizePixel = 0
    Fill.BackgroundColor3 = VisualState.Player.FillColor
    Fill.BackgroundTransparency = VisualState.Player.FillTransparency
    Fill.Size = UDim2.fromScale(1, 1)
    Fill.ZIndex = 4
    Fill.Parent = Root

    local BoxOutline = Instance.new("Frame")
    BoxOutline.Name = "BoxOutline"
    BoxOutline.BackgroundTransparency = 1
    BoxOutline.BorderSizePixel = 0
    BoxOutline.Size = UDim2.fromScale(1, 1)
    BoxOutline.ZIndex = 5
    BoxOutline.Parent = Root
    local BoxOutlineStroke = Instance.new("UIStroke")
    BoxOutlineStroke.Name = "Stroke"
    BoxOutlineStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    BoxOutlineStroke.Color = VisualState.Player.OutlineColor
    BoxOutlineStroke.Thickness = 2
    BoxOutlineStroke.Transparency = 0.05
    BoxOutlineStroke.Parent = BoxOutline

    local Box = Instance.new("Frame")
    Box.Name = "Box"
    Box.BackgroundTransparency = 1
    Box.BorderSizePixel = 0
    Box.Size = UDim2.fromScale(1, 1)
    Box.ZIndex = 6
    Box.Parent = Root
    local BoxStroke = Instance.new("UIStroke")
    BoxStroke.Name = "Stroke"
    BoxStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    BoxStroke.Color = VisualState.Player.BoxColor
    BoxStroke.Thickness = 1
    BoxStroke.Transparency = 0
    BoxStroke.Parent = Box

    local Corners = {}
    for Index = 1, 8 do Corners[Index] = CreatePlayerUiLine("Corner" .. Index, Root) end

    local Name = CreatePlayerUiText("Name", Root) local Forcefield = CreatePlayerUiText("Forcefield", Root)
    local Weapon = CreatePlayerUiText("Weapon", Root) local Distance = CreatePlayerUiText("Distance", Root)
    local Level = CreatePlayerUiText("Level", Root) local HealthText = CreatePlayerUiText("HealthText", Root)
    local AmmoText = CreatePlayerUiText("AmmoText", Root) local Flags = CreatePlayerUiText("Flags", Root, Enum.TextXAlignment.Left)
    Flags.TextYAlignment = Enum.TextYAlignment.Top

    local HealthBack = Instance.new("Frame")
    HealthBack.Name = "HealthBack"
    HealthBack.BorderSizePixel = 0
    HealthBack.BackgroundColor3 = Color3.new(0, 0, 0)
    HealthBack.BackgroundTransparency = 0.14
    HealthBack.ZIndex = 5
    HealthBack.Parent = Root

    local HealthDelayed = Instance.new("Frame")
    HealthDelayed.Name = "HealthDelayed"
    HealthDelayed.BorderSizePixel = 0
    HealthDelayed.BackgroundColor3 = VisualState.Player.Health.DelayedColor
    HealthDelayed.BackgroundTransparency = 0.05
    HealthDelayed.ZIndex = 6
    HealthDelayed.Parent = Root

    local Health = Instance.new("Frame")
    Health.Name = "Health"
    Health.BorderSizePixel = 0
    Health.BackgroundColor3 = VisualState.Player.HealthHighColor
    Health.BackgroundTransparency = 0
    Health.ZIndex = 7
    Health.Parent = Root

    local AmmoBack = Instance.new("Frame")
    AmmoBack.Name = "AmmoBack"
    AmmoBack.BorderSizePixel = 0
    AmmoBack.BackgroundColor3 = VisualState.Player.Ammo.BackColor
    AmmoBack.BackgroundTransparency = 0.16
    AmmoBack.ZIndex = 5
    AmmoBack.Parent = Root

    local Ammo = Instance.new("Frame")
    Ammo.Name = "Ammo"
    Ammo.BorderSizePixel = 0
    Ammo.BackgroundColor3 = VisualState.Player.Ammo.Color
    Ammo.BackgroundTransparency = 0
    Ammo.ZIndex = 6
    Ammo.Parent = Root

    local AvatarBack = Instance.new("Frame")
    AvatarBack.Name = "AvatarBack"
    AvatarBack.BorderSizePixel = 0
    AvatarBack.BackgroundColor3 = Color3.new(0, 0, 0)
    AvatarBack.BackgroundTransparency = 0.08
    AvatarBack.ZIndex = 6
    AvatarBack.Parent = Root

    local Avatar = Instance.new("ImageLabel")
    Avatar.Name = "Avatar"
    Avatar.BackgroundTransparency = 1
    Avatar.BorderSizePixel = 0
    Avatar.ZIndex = 7
    Avatar.Parent = AvatarBack

    Existing = {
        Root = Root, Fill = Fill, BoxOutline = BoxOutline, BoxOutlineStroke = BoxOutlineStroke, Box = Box, BoxStroke = BoxStroke, Corners = Corners,
        Name = Name, Forcefield = Forcefield, Weapon = Weapon, Distance = Distance, Level = Level, HealthBack = HealthBack, HealthDelayed = HealthDelayed,
        Health = Health, HealthText = HealthText, AmmoBack = AmmoBack, Ammo = Ammo, AmmoText = AmmoText, Flags = Flags, AvatarBack = AvatarBack, Avatar = Avatar
    }
    Data.UiEsp = Existing
    return Existing
