function DestroyPlayerUiEsp(Data)
    if not Data then return end
    local Ui = Data.UiEsp
    if Ui and Ui.Root then Ui.Root:Destroy() end
    Data.UiEsp = nil
    Data.UiThumbnailRequested = false
end

function HidePlayerUiEsp(Data)
    if Data and Data.UiEsp and Data.UiEsp.Root then Internal.Call(function() Data.UiEsp.Root.Visible = false end) end
end

function HidePlayerDrawingCore(Data)
    if not Data or type(Data.Drawings) ~= "table" then return end
    local Names = {"Fill", "BoxOutline", "Box", "Name", "Forcefield", "Weapon", "Distance", "Level", "HealthBack", "HealthDelayed", "Health", "HealthText", "Flags", "AmmoBack", "AmmoBar", "AmmoText", "ProfilePicture", "ProfilePictureBack"}
    for Index = 1, #Names do
        local Object = Data.Drawings[Names[Index]]
        if Object then Internal.Call(function() Object.Visible = false end) end
    end
    if type(Data.CornerOutlines) == "table" then
        for Index = 1, #Data.CornerOutlines do
            local Object = Data.CornerOutlines[Index]
            if Object then Internal.Call(function() Object.Visible = false end) end
        end
    end
    if type(Data.Corners) == "table" then
        for Index = 1, #Data.Corners do
            local Object = Data.Corners[Index]
            if Object then Internal.Call(function() Object.Visible = false end) end
        end
    end
end

function UpdatePlayerUiCorners(Ui, Width, Height, Color, OutlineColor, Visible)
    if not Ui or type(Ui.Corners) ~= "table" then return end
    local CornerWidth = math.max(Width * 0.28, 4) local CornerHeight = math.max(Height * 0.20, 5)
    local Segments = {
        {0, 0, CornerWidth, 1}, {0, 0, 1, CornerHeight},
        {Width - CornerWidth, 0, CornerWidth, 1}, {Width - 1, 0, 1, CornerHeight},
        {0, Height - 1, CornerWidth, 1}, {0, Height - CornerHeight, 1, CornerHeight},
        {Width - CornerWidth, Height - 1, CornerWidth, 1}, {Width - 1, Height - CornerHeight, 1, CornerHeight}
    }
    for Index = 1, 8 do
        local Line = Ui.Corners[Index] local Segment = Segments[Index]
        Line.Visible = Visible
        if Visible then
            Line.Position = UDim2.fromOffset(Segment[1], Segment[2])
            Line.Size = UDim2.fromOffset(Segment[3], Segment[4])
            Line.BackgroundColor3 = Color
            local Stroke = Line:FindFirstChild("Outline")
            if Stroke then Stroke.Color = OutlineColor end
        end
    end
end

function UpdatePlayerUiThumbnail(Data, Ui)
    if not VisualState.Player.ProfilePicture or not Ui or not Ui.Avatar then return end
    if Ui.Avatar.Image ~= "" or Data.UiThumbnailRequested then return end
    Data.UiThumbnailRequested = true
    task.spawn(function()
        local Success, Image = Internal.Call(function()
            return Players:GetUserThumbnailAsync(Data.Player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100)
        end)
        Data.UiThumbnailRequested = false
        if Success and type(Image) == "string" and Data.UiEsp == Ui and Ui.Avatar and Ui.Avatar.Parent then Ui.Avatar.Image = Image end
    end)
end

function UpdatePlayerUiEsp(Data, Position, Size, DistanceValue, ToolName, HealthPercent, HealthColor, AmmoCurrent, AmmoMaximum, CurrentTime, AdaptiveColor, AdaptiveOutline)
    local Ui = EnsurePlayerUiEsp(Data) if not Ui then return end

    Ui.Root.Visible = true
    local TextSize = math.clamp(tonumber(VisualState.Player.TextSize) or 12, 10, 20) local LineHeight = TextSize + 3
    local FullBox = VisualState.Player.Boxes and VisualState.Player.BoxStyle == "Full" local CornerBox = VisualState.Player.Boxes and VisualState.Player.BoxStyle == "Corners"

    Ui.BoxOutline.Visible = FullBox
    Ui.Box.Visible = FullBox
    Ui.BoxOutlineStroke.Color = AdaptiveOutline
    Ui.BoxStroke.Color = AdaptiveColor
    UpdatePlayerUiCorners(Ui, Size.X, Size.Y, AdaptiveColor, AdaptiveOutline, CornerBox)

    Ui.Fill.Visible = VisualState.Player.Fill
    Ui.Fill.BackgroundColor3 = VisualState.Player.FillColor
    Ui.Fill.BackgroundTransparency = math.clamp(VisualState.Player.FillTransparency, 0, 1)

    local NameOffset = GetPlayerESPPreviewOffset("Name")
    Ui.Name.Visible = VisualState.Player.Names
    Ui.Name.Text = Data.DisplayNameText or Data.Player.Name
    Ui.Name.TextSize = TextSize
    Ui.Name.TextColor3 = VisualState.Player.TextColor
    Ui.Name.AnchorPoint = Vector2.new(0.5, 1)
    Ui.Name.Position = UDim2.new(0.5, NameOffset.X, 0, -2 + NameOffset.Y)
    Ui.Name.Size = UDim2.fromOffset(math.max(Size.X + 100, 120), LineHeight)

    local ForcefieldOffset = GetPlayerESPPreviewOffset("Forcefield")
    Ui.Forcefield.Visible = VisualState.Player.Forcefield.Enabled and Data.CachedForcefield == true
    Ui.Forcefield.Text = "[Forcefield]"
    Ui.Forcefield.TextSize = math.max(TextSize - 1, 9)
    Ui.Forcefield.TextColor3 = VisualState.Player.Forcefield.Color
    Ui.Forcefield.AnchorPoint = Vector2.new(0.5, 1)
    Ui.Forcefield.Position = UDim2.new(0.5, ForcefieldOffset.X, 0, -(VisualState.Player.Names and LineHeight + 3 or 2) + ForcefieldOffset.Y)
    Ui.Forcefield.Size = UDim2.fromOffset(math.max(Size.X + 100, 120), LineHeight)

    local BottomOffset = 3
    local function PlaceBottom(Label, Enabled, Text, Color, OffsetName, FontSize)
        Label.Visible = Enabled
        if not Enabled then return end
        local Offset = GetPlayerESPPreviewOffset(OffsetName)
        Label.Text = Text
        Label.TextColor3 = Color
        Label.TextSize = FontSize
        Label.AnchorPoint = Vector2.new(0.5, 0)
        Label.Position = UDim2.new(0.5, Offset.X, 1, BottomOffset + Offset.Y)
        Label.Size = UDim2.fromOffset(math.max(Size.X + 120, 140), LineHeight)
        BottomOffset += LineHeight
    end

    PlaceBottom(Ui.Weapon, VisualState.Player.Weapon and ToolName ~= nil, ToolName or "", VisualState.Player.TextColor, "Weapon", math.max(TextSize - 1, 9))
    PlaceBottom(Ui.Distance, VisualState.Player.Distance, tostring(math.floor(DistanceValue + 0.5)) .. "m", VisualState.Player.TextColor, "Distance", math.max(TextSize - 2, 9))

    local LevelValue = VisualState.Player.Level and type(GetCachedPlayerLevel) == "function" and GetCachedPlayerLevel(Data, CurrentTime) or nil
    PlaceBottom(Ui.Level, LevelValue ~= nil, LevelValue and ("Level " .. tostring(LevelValue)) or "", VisualState.Player.LevelColor, "Level", math.max(TextSize - 1, 9))

    local HealthOffset = GetPlayerESPPreviewOffset("Health Bar") local HealthBackX = -8 + HealthOffset.X
    Ui.HealthBack.Visible = VisualState.Player.HealthBar
    Ui.HealthBack.Position = UDim2.fromOffset(HealthBackX, HealthOffset.Y)
    Ui.HealthBack.Size = UDim2.new(0, 4, 1, 0)

    local DelayedPercent = math.clamp(Data.DelayedHealthPercent or HealthPercent, 0, 1)
    Ui.HealthDelayed.Visible = VisualState.Player.HealthBar and VisualState.Player.Health.Delayed
    Ui.HealthDelayed.BackgroundColor3 = VisualState.Player.Health.DelayedColor
    Ui.HealthDelayed.Position = UDim2.new(0, HealthBackX + 1, 1 - DelayedPercent, HealthOffset.Y)
    Ui.HealthDelayed.Size = UDim2.new(0, 2, DelayedPercent, 0)

    Ui.Health.Visible = VisualState.Player.HealthBar
    Ui.Health.BackgroundColor3 = HealthColor
    Ui.Health.Position = UDim2.new(0, HealthBackX + 1, 1 - HealthPercent, HealthOffset.Y)
    Ui.Health.Size = UDim2.new(0, 2, HealthPercent, 0)

    local HealthTextOffset = GetPlayerESPPreviewOffset("Health Value")
    Ui.HealthText.Visible = VisualState.Player.HealthText
    if Ui.HealthText.Visible then
        Ui.HealthText.Text = tostring(math.floor(Data.Humanoid.Health + 0.5))
        Ui.HealthText.TextSize = math.max(TextSize - 2, 9)
        Ui.HealthText.TextColor3 = HealthColor
        Ui.HealthText.AnchorPoint = Vector2.new(1, 0.5)
        Ui.HealthText.Position = UDim2.new(0, HealthBackX - 3 + HealthTextOffset.X, 1 - HealthPercent, HealthTextOffset.Y)
        Ui.HealthText.Size = UDim2.fromOffset(34, 16)
    end

    local PictureSize = math.clamp(tonumber(VisualState.Player.ProfilePictureSize) or 28, 16, 48)
    local AvatarOffset = GetPlayerESPPreviewOffset("Avatar")
    local AvatarStackY = VisualState.Player.ProfilePicture and (PictureSize + 6) or 0
    local FlagText = BuildPlayerFlagsText(Data, DistanceValue, AmmoCurrent, AmmoMaximum) local FlagsOffset = GetPlayerESPPreviewOffset("Flags")
    Ui.Flags.Visible = FlagText ~= nil
    if FlagText then
        Ui.Flags.Text = FlagText
        Ui.Flags.TextSize = math.max(TextSize - 2, 9)
        Ui.Flags.TextColor3 = VisualState.Player.Flags.Color
        Ui.Flags.Position = UDim2.new(1, 5 + FlagsOffset.X, 0, AvatarStackY + FlagsOffset.Y)
        Ui.Flags.Size = UDim2.fromOffset(150, math.max(Size.Y, 40))
    end

    local ShowAmmo = VisualState.Player.Ammo.Enabled and type(AmmoCurrent) == "number" and type(AmmoMaximum) == "number" and AmmoMaximum > 0
    local AmmoOffset = GetPlayerESPPreviewOffset("Ammo")
    Ui.AmmoBack.Visible = ShowAmmo
    Ui.Ammo.Visible = ShowAmmo
    Ui.AmmoText.Visible = ShowAmmo and VisualState.Player.Ammo.Text == true
    if ShowAmmo then
        local Ratio = math.clamp(AmmoCurrent / math.max(AmmoMaximum, 1), 0, 1)
        Ui.AmmoBack.Position = UDim2.new(0, AmmoOffset.X, 1, BottomOffset + 2 + AmmoOffset.Y)
        Ui.AmmoBack.Size = UDim2.new(1, 0, 0, 3)
        Ui.AmmoBack.BackgroundColor3 = VisualState.Player.Ammo.BackColor
        Ui.Ammo.Position = UDim2.new(0, AmmoOffset.X, 1, BottomOffset + 2 + AmmoOffset.Y)
        Ui.Ammo.Size = UDim2.new(Ratio, 0, 0, 3)
        Ui.Ammo.BackgroundColor3 = VisualState.Player.Ammo.Color
        if Ui.AmmoText.Visible then
            Ui.AmmoText.Text = string.format("%d/%d", math.floor(AmmoCurrent + 0.5), math.floor(AmmoMaximum + 0.5))
            Ui.AmmoText.TextSize = math.max(TextSize - 3, 8)
            Ui.AmmoText.TextColor3 = VisualState.Player.Ammo.Color
            Ui.AmmoText.AnchorPoint = Vector2.new(0.5, 0)
            Ui.AmmoText.Position = UDim2.new(0.5, AmmoOffset.X, 1, BottomOffset + 7 + AmmoOffset.Y)
            Ui.AmmoText.Size = UDim2.fromOffset(80, 14)
        end
    end

    Ui.AvatarBack.Visible = VisualState.Player.ProfilePicture == true
    Ui.AvatarBack.Position = UDim2.new(1, 5 + AvatarOffset.X, 0, AvatarOffset.Y)
    Ui.AvatarBack.Size = UDim2.fromOffset(PictureSize + 2, PictureSize + 2)
    Ui.Avatar.Position = UDim2.fromOffset(1, 1)
    Ui.Avatar.Size = UDim2.fromOffset(PictureSize, PictureSize)
    if Ui.AvatarBack.Visible then UpdatePlayerUiThumbnail(Data, Ui) end
end

function UpdateCornerProjectionOnly(Data, Position, Size)
    if not Data or Data.CornersReady ~= true then return end
    local Width = Size.X local Height = Size.Y local CornerWidth = math.max(Width * 0.28, 4) local CornerHeight = math.max(Height * 0.20, 5)
    local X = Position.X local Y = Position.Y local Right = X + Width local Bottom = Y + Height
    local Points = {
        {X, Y, X + CornerWidth, Y}, {X, Y, X, Y + CornerHeight},
        {Right, Y, Right - CornerWidth, Y}, {Right, Y, Right, Y + CornerHeight},
        {X, Bottom, X + CornerWidth, Bottom}, {X, Bottom, X, Bottom - CornerHeight},
        {Right, Bottom, Right - CornerWidth, Bottom}, {Right, Bottom, Right, Bottom - CornerHeight}
    }
    for Index = 1, 8 do
        local Point = Points[Index] local From = Vector2.new(Point[1], Point[2]) local To = Vector2.new(Point[3], Point[4]) local Outline = Data.CornerOutlines[Index]
        local Corner = Data.Corners[Index]
        if Outline and Outline.Visible then
            Outline.From = From
            Outline.To = To
        end
        if Corner and Corner.Visible then
            Corner.From = From
            Corner.To = To
        end
    end
end

function UpdateGlowProjectionOnly(Data, Position, Size)
    if not Data or not Data.Drawings then return end
    for Index = 1, 3 do
        local Box = Data.Drawings["GlowBox" .. Index]
        if Box and Box.Visible then
            local Expansion = Index * 2
            Box.Position = Position - Vector2.new(Expansion, Expansion)
            Box.Size = Size + Vector2.new(Expansion * 2, Expansion * 2)
        end
    end
end

function GetFastDetailInterval(Data)
    local Count = math.max(tonumber(VisualState.Performance.PlayerCount) or 0, 0) local Distance = math.max(tonumber(Data and Data.LastEspDistance) or 0, 0)
    if Count >= 32 then
        if Distance >= 900 then return 1 / 24 end
        if Distance >= 500 then return 1 / 36 end
        return 1 / 45
    end
    if Count >= 20 then
        if Distance >= 900 then return 1 / 30 end
        if Distance >= 500 then return 1 / 45 end
        return 1 / 60
    end
    if Distance >= 1000 then return 1 / 36 end
    if Distance >= 650 then return 1 / 50 end
    return 1 / 60
end

function UpdatePlayerDrawingProjection(Data, CameraObject, Position, Size, RootScreen, HeadScreen, FeetScreen, CurrentTime)
    if not Data or not Data.DrawingsReady then return end

    local Drawings = Data.Drawings local Color = Data.LastEspAdaptiveColor or VisualState.Player.BoxColor
    local OutlineColor = Data.LastEspAdaptiveOutline or VisualState.Player.OutlineColor local FullBox = VisualState.Player.Boxes and VisualState.Player.BoxStyle == "Full"
    local CornerBox = VisualState.Player.Boxes and VisualState.Player.BoxStyle == "Corners"
    local TextSize = Internal.GetDrawingTextSize(VisualState.Player.TextSize, false)
    local LineHeight = TextSize + 3 local CenterX = Position.X + Size.X * 0.5

    if Drawings.BoxOutline then
        Drawings.BoxOutline.Visible = FullBox
        Drawings.BoxOutline.Position = Position
        Drawings.BoxOutline.Size = Size
        Drawings.BoxOutline.Color = OutlineColor
        Drawings.BoxOutline.Thickness = 2
    end
    if Drawings.Box then
        Drawings.Box.Visible = FullBox
        Drawings.Box.Position = Position
        Drawings.Box.Size = Size
        Drawings.Box.Color = Color
        Drawings.Box.Thickness = 1
    end
    UpdateCornerBox(Data, Position, Size, Color, OutlineColor, CornerBox)
    UpdateBoxGlow(Data, Position, Size, Color)

    if Drawings.Fill then
        Drawings.Fill.Visible = VisualState.Player.Fill
        Drawings.Fill.Position = Position
        Drawings.Fill.Size = Size
        Drawings.Fill.Color = VisualState.Player.FillColor
        Drawings.Fill.Transparency = 1 - math.clamp(VisualState.Player.FillTransparency, 0, 1)
    end

    if Drawings.Name then
        Drawings.Name.Visible = VisualState.Player.Names
        Drawings.Name.Position = ApplyPlayerESPPreviewOffset(Vector2.new(CenterX, Position.Y - LineHeight), "Name")
    end

    local PictureSize = math.clamp(tonumber(VisualState.Player.ProfilePictureSize) or 28, 16, 48)
    local AvatarOffset = GetPlayerESPPreviewOffset("Avatar")
    if Drawings.ProfilePicture and Drawings.ProfilePicture.Visible then
        local PicturePosition = Vector2.new(Position.X + Size.X + 5, Position.Y) + AvatarOffset
        Drawings.ProfilePicture.Position = PicturePosition
        Drawings.ProfilePicture.Size = Vector2.new(PictureSize, PictureSize)
        if Drawings.ProfilePictureBack and Drawings.ProfilePictureBack.Visible then
            Drawings.ProfilePictureBack.Position = PicturePosition - Vector2.new(1, 1)
            Drawings.ProfilePictureBack.Size = Vector2.new(PictureSize + 2, PictureSize + 2)
        end
    end

    if Drawings.Forcefield and Drawings.Forcefield.Visible then
        local Up = VisualState.Player.Names and LineHeight or 0
        Drawings.Forcefield.Position = ApplyPlayerESPPreviewOffset(Vector2.new(CenterX, Position.Y - LineHeight - Up), "Forcefield")
    end

    local BottomY = Position.Y + Size.Y + 3 local BottomIndex = 0
    local function PlaceBottom(Object, OffsetName)
        if not Object or not Object.Visible then return end
        Object.Position = ApplyPlayerESPPreviewOffset(Vector2.new(CenterX, BottomY + BottomIndex * LineHeight), OffsetName)
        BottomIndex += 1
    end
    PlaceBottom(Drawings.Weapon, "Weapon")
    PlaceBottom(Drawings.Distance, "Distance")
    PlaceBottom(Drawings.Level, "Level")

    local Humanoid = Data.Humanoid
    local TargetHealthPercent = Humanoid and math.clamp(Humanoid.Health / math.max(Humanoid.MaxHealth, 1), 0, 1) or 0
    local HealthPercent, DelayedHealthPercent = UpdatePlayerHealthAnimation(Data, TargetHealthPercent, CurrentTime)

    local HealthOffset = GetPlayerESPPreviewOffset("Health Bar") local HealthBackX = Position.X - 8 + HealthOffset.X local HealthTopY = Position.Y
    if Drawings.HealthBack then
        Drawings.HealthBack.Visible = VisualState.Player.HealthBar
        Drawings.HealthBack.Position = Vector2.new(HealthBackX, HealthTopY)
        Drawings.HealthBack.Size = Vector2.new(4, Size.Y)
    end
    if Drawings.HealthDelayed then
        local Percent = math.clamp(DelayedHealthPercent or HealthPercent, 0, 1) local Height = Size.Y * Percent
        Drawings.HealthDelayed.Visible = VisualState.Player.HealthBar and VisualState.Player.Health.Delayed
        Drawings.HealthDelayed.Position = Vector2.new(HealthBackX + 1, HealthTopY + Size.Y - Height)
        Drawings.HealthDelayed.Size = Vector2.new(2, Height)
    end
    if Drawings.Health then
        local Height = Size.Y * HealthPercent
        Drawings.Health.Visible = VisualState.Player.HealthBar
        Drawings.Health.Position = Vector2.new(HealthBackX + 1, HealthTopY + Size.Y - Height)
        Drawings.Health.Size = Vector2.new(2, Height)
        Drawings.Health.Color = GetPlayerEspHealthColor(HealthPercent)
    end
    if Drawings.HealthText and Drawings.HealthText.Visible then
        local HealthValueOffset = GetPlayerESPPreviewOffset("Health Value")
        Drawings.HealthText.Position = Vector2.new(HealthBackX - 5, HealthTopY + Size.Y * (1 - HealthPercent) - 5) + HealthValueOffset
    end

    if Drawings.Flags and Drawings.Flags.Visible then
        local AvatarStackY = VisualState.Player.ProfilePicture and (PictureSize + 6) or 0
        Drawings.Flags.Position = ApplyPlayerESPPreviewOffset(Vector2.new(Position.X + Size.X + 5, Position.Y + AvatarStackY), "Flags")
    end

    if Drawings.AmmoBack and Drawings.AmmoBar and Drawings.AmmoBack.Visible then
        local CurrentObject = Data.CachedAmmoCurrentObject
        if CurrentObject and CurrentObject.Parent then
            local LiveCurrent = tonumber(CurrentObject.Value)
            if LiveCurrent ~= nil then Data.CachedAmmoCurrent = LiveCurrent end
        end
        local Current = tonumber(Data.CachedAmmoCurrent) local Maximum = tonumber(Data.CachedAmmoMaximum)
        local Ratio = Current and Maximum and Maximum > 0 and math.clamp(Current / Maximum, 0, 1) or 0 local AmmoOffset = GetPlayerESPPreviewOffset("Ammo")
        local BarY = BottomY + BottomIndex * LineHeight + 2 local BarPosition = Vector2.new(Position.X, BarY) + AmmoOffset local BarWidth = math.max(Size.X, 2)
        Drawings.AmmoBack.Position = BarPosition
        Drawings.AmmoBack.Size = Vector2.new(BarWidth, 3)
        Drawings.AmmoBar.Position = BarPosition
        Drawings.AmmoBar.Size = Vector2.new(math.max(BarWidth * Ratio, 1), 3)
        if Drawings.AmmoText and Drawings.AmmoText.Visible then Drawings.AmmoText.Position = Vector2.new(CenterX, BarY + 6) + AmmoOffset end
    end

    UpdateSkeletonEsp(Data, CameraObject, Color)
    UpdateLookLine(Data, CameraObject, Color)
    UpdateTracer(Data, CameraObject.ViewportSize, Position, Size, RootScreen, HeadScreen, FeetScreen)
    UpdatePredictionMarker(Data, CameraObject)
end

function UpdatePlayerUiDynamicProjection(Data, Ui, CurrentTime)
    if not Data or not Ui then return end
    local Humanoid = Data.Humanoid if not Humanoid then return end

    local TargetHealthPercent = math.clamp(Humanoid.Health / math.max(Humanoid.MaxHealth, 1), 0, 1)
    local HealthPercent, DelayedHealthPercent = UpdatePlayerHealthAnimation(Data, TargetHealthPercent, CurrentTime)

    local HealthOffset = GetPlayerESPPreviewOffset("Health Bar") local HealthBackX = -8 + HealthOffset.X
    if Ui.HealthBack and Ui.HealthBack.Visible then
        Ui.HealthBack.Position = UDim2.fromOffset(HealthBackX, 0)
        Ui.HealthBack.Size = UDim2.new(0, 4, 1, 0)
    end
    if Ui.Health and Ui.Health.Visible then
        Ui.Health.Position = UDim2.new(0, HealthBackX + 1, 1 - HealthPercent, 0)
        Ui.Health.Size = UDim2.new(0, 2, HealthPercent, 0)
        Ui.Health.BackgroundColor3 = GetPlayerEspHealthColor(HealthPercent)
    end
    if Ui.HealthDelayed and Ui.HealthDelayed.Visible then
        local DelayedPercent = math.clamp(DelayedHealthPercent or HealthPercent, 0, 1)
        Ui.HealthDelayed.Position = UDim2.new(0, HealthBackX + 1, 1 - DelayedPercent, 0)
        Ui.HealthDelayed.Size = UDim2.new(0, 2, DelayedPercent, 0)
    end
    if Ui.HealthText and Ui.HealthText.Visible then
        local Offset = GetPlayerESPPreviewOffset("Health Value")
        Ui.HealthText.Position = UDim2.new(0, HealthBackX - 3 + Offset.X, 1 - HealthPercent, Offset.Y)
    end

    local CurrentObject = Data.CachedAmmoCurrentObject
    if CurrentObject and CurrentObject.Parent then
        local Current = tonumber(CurrentObject.Value)
        if Current ~= nil then Data.CachedAmmoCurrent = Current end
    end
    if Ui.Ammo and Ui.Ammo.Visible then
        local Current = tonumber(Data.CachedAmmoCurrent) local Maximum = tonumber(Data.CachedAmmoMaximum)
        if Current and Maximum and Maximum > 0 then Ui.Ammo.Size = UDim2.new(math.clamp(Current / Maximum, 0, 1), 0, 0, 3) end
    end
end

function UpdatePlayerUiProjection()
    if VisualState.Player.Enabled ~= true then return end

    local CameraObject = Internal.GetCamera() local LocalCharacter = LocalPlayer.Character local LocalRoot = LocalCharacter and LocalCharacter:FindFirstChild("HumanoidRootPart")
    if not CameraObject or not LocalRoot then
        for _, Data in ipairs(VisualState.Player.List) do Internal.HidePlayerVisual(Data) end
        return
    end

    local CurrentTime = os.clock() local MaximumDistance = math.max(tonumber(VisualState.Player.MaxDistance) or 1200, 1)
    local MaximumDistanceSquared = MaximumDistance * MaximumDistance local Renderer = VisualState.Player.Renderer local HasEnemyTargets = AtramentaHasEnemyTargets()
    VisualState.Performance.ProjectionFrame += 1
    Internal.RefreshPlayerEspOffsetCache()

    for Index = 1, #VisualState.Player.List do
        local Data = VisualState.Player.List[Index]
        if not Data then continue end

        local Character = Data.Character local Humanoid = Data.Humanoid local TargetRoot = Data.Root
        if not Character or not Character.Parent or not Humanoid or not Humanoid.Parent or Humanoid.Health <= 0 or not TargetRoot or not TargetRoot.Parent then
            Internal.HidePlayerVisual(Data)
            Data.EspEligible = false
            continue
        end

        if HasEnemyTargets == true and EnemyTable[Data.Player] ~= true then
            Internal.HidePlayerVisual(Data)
            Data.EspEligible = false
            continue
        end

        if VisualState.Player.TeamCheck and LocalPlayer.Team and Data.Player.Team == LocalPlayer.Team then
            Internal.HidePlayerVisual(Data)
            Data.EspEligible = false
            continue
        end

        local Pose = GetPlayerVisualRenderPose(Data, CurrentTime)

        if VisualState.Player.Chams.Enabled
            and Pose
            and Data.ChamsHolder
            and Data.ChamsHolder.Parent
            and Data.ChamsRenderActive == true
        then
            UpdatePlayerChamRenderPose(Data, Pose)
        end

        local ResolvedRootPosition = Pose and Pose.RenderRootPosition or TargetRoot.Position
        local Delta = ResolvedRootPosition - LocalRoot.Position
        local DistanceSquared = Delta:Dot(Delta)
        if DistanceSquared > MaximumDistanceSquared then
            Internal.HidePlayerVisual(Data)
            continue
        end

        local Position, Size, RootScreen, HeadScreen, FeetScreen = GetPlayerBox(CameraObject, Data, false, Pose)
        if not Position or not Size then
            if Data.VisualHidden ~= true then Internal.HidePlayerVisual(Data) end
            if VisualState.Player.Offscreen.Enabled then
                UpdateOffscreenArrow(Data, CameraObject, ResolvedRootPosition, math.sqrt(DistanceSquared), Data.LastEspAdaptiveColor or VisualState.Player.Offscreen.Color)
            else
                HideOffscreenArrowDrawings(Data)
            end
            continue
        end

        local WasHidden = Data.VisualHidden == true
        HideOffscreenArrowDrawings(Data)
        Data.VisualHidden = false
        if WasHidden then Data.NextEspUpdate = 0 end

        if Renderer == "Roblox UI" then
            local Ui = Data.UiEsp local Root = Ui and Ui.Root
            if Root and Root.Parent then
                local Success = Internal.Call(function()
                    local X = Position.X local Y = Position.Y local Width = math.max(Size.X, 1) local Height = math.max(Size.Y, 1)
                    Root.Position = UDim2.fromOffset(X, Y)
                    Root.Size = UDim2.fromOffset(Width, Height)
                    Root.Visible = true
                    Data.UiProjectedWidth = Width
                    Data.UiProjectedHeight = Height
                    UpdatePlayerUiDynamicProjection(Data, Ui, CurrentTime)
                    local OverlayColor = Data.LastEspAdaptiveColor or VisualState.Player.BoxColor
                    UpdateBoxGlow(Data, Position, Size, OverlayColor)
                    UpdateSkeletonEsp(Data, CameraObject, OverlayColor)
                    UpdateLookLine(Data, CameraObject, OverlayColor)
                    UpdateTracer(Data, CameraObject.ViewportSize, Position, Size, RootScreen, HeadScreen, FeetScreen)
                    UpdatePredictionMarker(Data, CameraObject)
                end)
                if not Success then
                    Data.NextEspUpdate = 0
                    Data.EspEligible = false
                    Internal.HidePlayerVisual(Data)
                end
            else
                Data.NextEspUpdate = 0
                Internal.HidePlayerVisual(Data)
            end
        else
            HidePlayerUiEsp(Data)
            local Success = Internal.Call(UpdatePlayerDrawingProjection, Data, CameraObject, Position, Size, RootScreen, HeadScreen, FeetScreen, CurrentTime)
            if not Success then
                Data.NextEspUpdate = 0
                Data.EspEligible = false
                Internal.HidePlayerVisual(Data)
            end
        end
    end
end

function RefreshPlayerUiProjection()
    local Needed = VisualState.Player.Enabled == true
    if Needed then
        if VisualState.Player.UiProjectionBound == true then return end
        RunService:UnbindFromRenderStep("AtramentaPlayerUiProjection")
        VisualState.Player.UiProjectionBound = true
        RunService:BindToRenderStep("AtramentaPlayerUiProjection", Enum.RenderPriority.Camera.Value + 1, function()
            local Success = Internal.Call(UpdatePlayerUiProjection)
            if not Success then
                for _, Data in ipairs(VisualState.Player.List) do Internal.HidePlayerVisual(Data) end
            end
        end)
        return
    end

    RunService:UnbindFromRenderStep("AtramentaPlayerUiProjection")
    VisualState.Player.UiProjectionBound = false
    for _, Data in ipairs(VisualState.Player.List) do
        HidePlayerUiEsp(Data)
    end
end

function Internal.DestroyPlayerVisual(Player)
    local Data = VisualState.Player.Objects[Player] if not Data then return end

    local UserId = Player and tonumber(Player.UserId) or nil
    if UserId then VisualState.Player.ProfilePictureCache[UserId] = nil end
    Data.ProfilePictureData = nil
    Data.ProfilePictureApplied = false
    Internal.DisconnectVisualConnection(Data.CharacterAddedConnection)
    Internal.DisconnectVisualConnection(Data.CharacterRemovingConnection)
    for Unused, Object in pairs(Data.Drawings) do Internal.RemoveDrawing(Object) end
    DestroyPlayerUiEsp(Data)
    DestroyChams(Data)
    local List = VisualState.Player.List
    local Index = math.floor(tonumber(Data.ListIndex) or 0)
    if Index < 1 or List[Index] ~= Data then
        Index = 0
        for SearchIndex = 1, #List do
            if List[SearchIndex] == Data then Index = SearchIndex break end
        end
    end
    if Index > 0 then
        local LastIndex = #List
        local Last = List[LastIndex]
        if Index ~= LastIndex then
            List[Index] = Last
            if Last then Last.ListIndex = Index end
        end
        List[LastIndex] = nil
    end
    Data.ListIndex = 0
    VisualState.Player.Objects[Player] = nil
end

function Internal.ReconcilePlayerVisualCache()
    local ActivePlayers, StalePlayers = VisualState.ReconcileActive, VisualState.ReconcileStale
    table.clear(ActivePlayers)
    table.clear(StalePlayers)

    for _, Player in ipairs(Players:GetPlayers()) do
        if Player ~= LocalPlayer then
            ActivePlayers[Player] = true
            local Data = VisualState.Player.Objects[Player]
            if not Data then Data = Internal.CreatePlayerVisual(Player, false) end
            local Resolved = ResolveTrackedCharacter(Player, Player.Character)
            if Data then
                local NeedsRefresh = Resolved and Data.Character ~= Resolved
                if not NeedsRefresh and Resolved and (not Data.Root or not Data.Root.Parent or not Data.Humanoid or not Data.Humanoid.Parent) then NeedsRefresh = true end
                if NeedsRefresh then Internal.RefreshPlayerCharacter(Data, Resolved) end
            end
        end
    end

    for Player in pairs(VisualState.Player.Objects) do
        if not ActivePlayers[Player] or Player.Parent ~= Players then StalePlayers[#StalePlayers + 1] = Player end
    end
    for Index = 1, #StalePlayers do Internal.DestroyPlayerVisual(StalePlayers[Index]) end
end

function Internal.EnsurePlayerCache()
    VisualState.Initialized = true
    Internal.ReconcilePlayerVisualCache()
    if not VisualState.PlayerAddedConnection then
        VisualState.PlayerAddedConnection = Players.PlayerAdded:Connect(function(Player) if Player ~= LocalPlayer then Internal.CreatePlayerVisual(Player, false) end end)
    end
    if not VisualState.PlayerRemovingConnection then
        VisualState.PlayerRemovingConnection = Players.PlayerRemoving:Connect(function(Player) Internal.DestroyPlayerVisual(Player) end)
    end

    if not VisualState.WorldRootConnection then
        local function BindWorldCharactersFolder(Folder)
            if Folder == VisualState.BoundWorldCharacters then return end
            if VisualState.WorldCharactersConnection then VisualState.WorldCharactersConnection:Disconnect(); VisualState.WorldCharactersConnection = nil end
            VisualState.BoundWorldCharacters = Folder
            if not Folder then return end

            for _, Character in ipairs(Folder:GetChildren()) do
                local Player = Players:FindFirstChild(Character.Name)
                if Player and Player:IsA("Player") and Player ~= LocalPlayer then
                    local Data = VisualState.Player.Objects[Player] or Internal.CreatePlayerVisual(Player, false)
                    if Data then Internal.RefreshPlayerCharacter(Data, Character) end
                end
            end
            VisualState.WorldCharactersConnection = Folder.ChildAdded:Connect(function(Character)
                local Player = Players:FindFirstChild(Character.Name)
                if Player and Player:IsA("Player") and Player ~= LocalPlayer then
                    task.defer(function()
                        local Data = VisualState.Player.Objects[Player] or Internal.CreatePlayerVisual(Player, false)
                        if Data then Internal.RefreshPlayerCharacter(Data, Character) end
                    end)
                end
            end)
        end

        local function BindWorldContainer(Container)
            if Container == VisualState.BoundWorldContainer then return end
            if VisualState.WorldContainerConnection then VisualState.WorldContainerConnection:Disconnect(); VisualState.WorldContainerConnection = nil end
            VisualState.BoundWorldContainer = Container
            if not Container then BindWorldCharactersFolder(nil); return end
            BindWorldCharactersFolder(Container:FindFirstChild("Characters"))
            VisualState.WorldContainerConnection = Container.ChildAdded:Connect(function(Child) if Child.Name == "Characters" then BindWorldCharactersFolder(Child) end end)
        end

        BindWorldContainer(workspace:FindFirstChild("©"))
        VisualState.WorldRootConnection = workspace.ChildAdded:Connect(function(Child) if Child.Name == "©" then BindWorldContainer(Child) end end)
    end
end

function Internal.GetCachedToolName(Data, CurrentTime)
    if CurrentTime < Data.NextToolScan then return Data.ToolName end
    Data.NextToolScan = CurrentTime + 0.25
    local Tool = Data.Character and Data.Character:FindFirstChildOfClass("Tool")
    Data.ToolName = Tool and Tool.Name or nil
    return Data.ToolName
end

function Internal.ReadPlayerLevelObject(Object)
    if not Object then return nil end
    if Object:IsA("IntValue") or Object:IsA("NumberValue") or Object:IsA("StringValue") then
        local Value = tonumber(Object.Value)
        if Value and Value >= 0 then return math.floor(Value + 0.5) end
    end
    return nil
end

function Internal.FindPlayerLevelInContainer(Container)
    if not Container then return nil end
    local Names = {"Level", "LEVEL", "Lvl", "LVL", "level"}
    for Index = 1, #Names do
        local Value = Internal.ReadPlayerLevelObject(Container:FindFirstChild(Names[Index]))
        if Value ~= nil then return Value end
    end
    for Index = 1, #Names do
        local Attribute = tonumber(Container:GetAttribute(Names[Index]))
        if Attribute and Attribute >= 0 then return math.floor(Attribute + 0.5) end
    end
    return nil
end

function GetCachedPlayerLevel(Data, CurrentTime)
    if not Data or not Data.Player then return nil end
    if CurrentTime < (Data.NextLevelScan or 0) then return Data.LevelValue end
    Data.NextLevelScan = CurrentTime + 0.50

    local Player = Data.Player
    local Level = Internal.FindPlayerLevelInContainer(Player:FindFirstChild("leaderstats")) or Internal.FindPlayerLevelInContainer(Player:FindFirstChild("PlayerbaseData2"))
        or Internal.FindPlayerLevelInContainer(Player:FindFirstChild("Data")) or Internal.FindPlayerLevelInContainer(Player:FindFirstChild("Values"))
        or Internal.FindPlayerLevelInContainer(Player)

    if Level == nil then
        local ReplicatedData = ReplicatedStorage:FindFirstChild("PlayerbaseData2")
        Level = Internal.FindPlayerLevelInContainer(ReplicatedData and (ReplicatedData:FindFirstChild(Player.Name) or ReplicatedData:FindFirstChild(tostring(Player.UserId))))
    end

    if Level == nil then
        local CharStats = ReplicatedStorage:FindFirstChild("CharStats")
        Level = Internal.FindPlayerLevelInContainer(CharStats and (CharStats:FindFirstChild(Player.Name) or CharStats:FindFirstChild(tostring(Player.UserId))))
    end

    Data.LevelValue = Level
    return Level
end

local EspBoundsPartNames = { Head = true, Torso = true, ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true }

EspR6CanonicalPartSizes = {
    Head = Vector3.new(2, 1, 1),
    Torso = Vector3.new(2, 2, 1),
    ["Left Arm"] = Vector3.new(1, 2, 1),
    ["Right Arm"] = Vector3.new(1, 2, 1),
    ["Left Leg"] = Vector3.new(1, 2, 1),
    ["Right Leg"] = Vector3.new(1, 2, 1)
}

function GetEspR6CanonicalPartSize(Part)
    if not Part or not Part:IsA("BasePart") then return nil end
    return EspR6CanonicalPartSizes[Part.Name]
end

function Internal.ResetPlayerEspBounds(Data)
    if not Data then return end
    Data.EspBoundsCharacter = nil
    Data.EspBoundsMinimum = nil
    Data.EspBoundsMaximum = nil
end

function Internal.BuildPlayerEspLocalBounds(Data)
    local Character = Data and Data.Character local Root = Data and Data.Root
    if not Character or not Root or not Root.Parent then return nil end

    if Data.EspBoundsCharacter ~= Character
        or typeof(Data.EspBoundsMinimum) ~= "Vector3"
        or typeof(Data.EspBoundsMaximum) ~= "Vector3"
    then
        Data.EspBoundsCharacter = Character
        Data.EspBoundsMinimum = Vector3.new(-2.05, -3.05, -1.05)
        Data.EspBoundsMaximum = Vector3.new(2.05, 2.05, 1.05)
    end

    return Data.EspBoundsMinimum, Data.EspBoundsMaximum
end

function GetPlayerVisualRenderPose(Data, CurrentTime)
    if not Data then return nil end

    local Root = Data.Root
    local Head = Data.Head

    if not Root or not Root.Parent or not Root:IsA("BasePart") then
        Data.VisualRenderPose = nil
        return nil
    end

    local RootCFrame = Root.CFrame
    local RootPosition = RootCFrame.Position

    if not ResolverIsFiniteVector(RootPosition) then
        Data.VisualRenderPose = nil
        return nil
    end

    local Velocity = Root.AssemblyLinearVelocity
    if not ResolverIsFiniteVector(Velocity) then Velocity = Vector3.zero end

    local HeadPosition = Head and Head.Parent and Head:IsA("BasePart") and Head.Position or nil
    local Pose = Data.VisualRenderPose

    if type(Pose) ~= "table" or Pose.Character ~= Data.Character then
        Pose = {}
        Data.VisualRenderPose = Pose
    end

    Pose.Character = Data.Character
    Pose.RawRootPosition = RootPosition
    Pose.RawRootCFrame = RootCFrame
    Pose.RenderRootPosition = RootPosition
    Pose.RenderRootCFrame = RootCFrame
    Pose.RawPosition = RootPosition
    Pose.HeadPosition = ResolverIsFiniteVector(HeadPosition) and HeadPosition or nil
    Pose.Offset = Vector3.zero
    Pose.PreviousVelocity = Pose.Velocity or Velocity
    Pose.Velocity = Velocity
    Pose.LastUpdate = tonumber(CurrentTime) or os.clock()

    Data.VisualRenderPoseTime = Pose.LastUpdate
    return Pose
end
function GetPlayerBox(CameraObject, Data, Snapshot, LivePose)
    local Character = Data and Data.Character
    local Root = Data and Data.Root

    if not Character or not Root or not Root.Parent then
        Internal.RefreshPlayerCharacter(Data, Data and Data.Player and Data.Player.Character)
        Character = Data and Data.Character
        Root = Data and Data.Root
    end

    if not CameraObject or not Character or not Root or not Root.Parent then return nil end

    local Minimum, Maximum = Internal.BuildPlayerEspLocalBounds(Data)
    if not Minimum or not Maximum then return nil end

    local Pose = type(LivePose) == "table" and LivePose or GetPlayerVisualRenderPose(Data, os.clock())
    local RootPosition = Pose and Pose.RenderRootPosition or Root.Position

    if not ResolverIsFiniteVector(RootPosition) then return nil end

    local HeightStuds = math.max(Maximum.Y - Minimum.Y, 0.001)
    local HalfWidth = math.min(math.max(math.abs(Minimum.X), math.abs(Maximum.X)), HeightStuds * 0.275)
    local TopWorld = RootPosition + Vector3.new(0, Maximum.Y, 0)
    local BottomWorld = RootPosition + Vector3.new(0, Minimum.Y, 0)
    local Right = CameraObject.CFrame.RightVector * HalfWidth

    local TopLeft = CameraObject:WorldToViewportPoint(TopWorld - Right)
    local TopRight = CameraObject:WorldToViewportPoint(TopWorld + Right)
    local BottomLeft = CameraObject:WorldToViewportPoint(BottomWorld - Right)
    local BottomRight = CameraObject:WorldToViewportPoint(BottomWorld + Right)

    if TopLeft.Z <= 0.05 or TopRight.Z <= 0.05 or BottomLeft.Z <= 0.05 or BottomRight.Z <= 0.05 then return nil end

    local MinX = math.min(TopLeft.X, TopRight.X, BottomLeft.X, BottomRight.X) - 0.5
    local MaxX = math.max(TopLeft.X, TopRight.X, BottomLeft.X, BottomRight.X) + 0.5
    local MinY = math.min(TopLeft.Y, TopRight.Y, BottomLeft.Y, BottomRight.Y) - 0.5
    local MaxY = math.max(TopLeft.Y, TopRight.Y, BottomLeft.Y, BottomRight.Y) + 0.5
    local Viewport = CameraObject.ViewportSize

    if MaxX < 0 or MinX > Viewport.X or MaxY < 0 or MinY > Viewport.Y then return nil end

    local Position = Vector2.new(MinX, MinY)
    local Size = Vector2.new(math.max(MaxX - MinX, 2), math.max(MaxY - MinY, 2))
    local RootProjection = CameraObject:WorldToViewportPoint(RootPosition)
    local HeadWorld = RootPosition + Vector3.new(0, math.min(Maximum.Y - 0.45, 1.65), 0)
    local HeadProjection = CameraObject:WorldToViewportPoint(HeadWorld)
    local FeetProjection = CameraObject:WorldToViewportPoint(BottomWorld)

    return Position, Size, RootProjection,
        Vector2.new(HeadProjection.X, HeadProjection.Y),
        Vector2.new(FeetProjection.X, FeetProjection.Y)
end
function SetLine(Line, From, To, Color, Visible, Thickness, Transparency)
    if not Line then return end
    Line.Visible = Visible
    if not Visible then return end
    Line.From = From
    Line.To = To
    Line.Color = Color if Thickness then Line.Thickness = Thickness end
    if Transparency then Line.Transparency = Transparency end
end

function Internal.ApplyCornerPair(Data, Index, X1, Y1, X2, Y2, Color, OutlineColor, Visible)
    local From, To = Vector2.new(X1, Y1), Vector2.new(X2, Y2)
    SetLine(Data.CornerOutlines[Index], From, To, OutlineColor, Visible, 2, 0.95)
    SetLine(Data.Corners[Index], From, To, Color, Visible, 1, 1)
end

function UpdateCornerBox(Data, Position, Size, Color, OutlineColor, Visible)
    if not Visible then
        if Data.CornersReady then
            for Index = 1, 8 do
                local Outline = Data.CornerOutlines[Index] local Corner = Data.Corners[Index]
                if Outline then Outline.Visible = false end
                if Corner then Corner.Visible = false end
            end
        end
        return
    end

    if not Internal.EnsureCornerBoxDrawings(Data) then return end

    local Width, Height = Size.X, Size.Y local CornerWidth, CornerHeight = math.max(Width * 0.28, 4), math.max(Height * 0.20, 5)
    local X, Y = Position.X, Position.Y local Right, Bottom = X + Width, Y + Height

    Internal.ApplyCornerPair(Data, 1, X, Y, X + CornerWidth, Y, Color, OutlineColor, Visible)
    Internal.ApplyCornerPair(Data, 2, X, Y, X, Y + CornerHeight, Color, OutlineColor, Visible)
    Internal.ApplyCornerPair(Data, 3, Right, Y, Right - CornerWidth, Y, Color, OutlineColor, Visible)
    Internal.ApplyCornerPair(Data, 4, Right, Y, Right, Y + CornerHeight, Color, OutlineColor, Visible)
    Internal.ApplyCornerPair(Data, 5, X, Bottom, X + CornerWidth, Bottom, Color, OutlineColor, Visible)
    Internal.ApplyCornerPair(Data, 6, X, Bottom, X, Bottom - CornerHeight, Color, OutlineColor, Visible)
    Internal.ApplyCornerPair(Data, 7, Right, Bottom, Right - CornerWidth, Bottom, Color, OutlineColor, Visible)
    Internal.ApplyCornerPair(Data, 8, Right, Bottom, Right, Bottom - CornerHeight, Color, OutlineColor, Visible)
end

function Internal.GetTracerOrigin(ViewportSize)
    local Origin = VisualState.Player.TracerOrigin
    if Origin == "Top" then return Vector2.new(ViewportSize.X * 0.5, 2) end
    if Origin == "Center" then return Vector2.new(ViewportSize.X * 0.5, ViewportSize.Y * 0.5) end
    return Vector2.new(ViewportSize.X * 0.5, ViewportSize.Y - 2)
end

function Internal.GetTracerEnd(Position, Size, RootScreen, HeadScreen, FeetScreen)
    local EndMode = VisualState.Player.TracerEnd
    if EndMode == "Head" then return HeadScreen end
    if EndMode == "Body" then return Vector2.new(RootScreen.X, Position.Y + Size.Y * 0.52) end
    return FeetScreen
end

function Internal.QuadraticBezier(A, B, C, T)
    local Inverse = 1 - T
    return A * (Inverse * Inverse) + B * (2 * Inverse * T) + C * (T * T)
end

function UpdateTracer(Data, ViewportSize, Position, Size, RootScreen, HeadScreen, FeetScreen)
    local Drawings = Data.Drawings
    if not VisualState.Player.Tracers then
        Internal.HideTracerDrawings(Data)
        return
    end
    EnsureTracerDrawing(Data)
    local From = Internal.GetTracerOrigin(ViewportSize) local To = Internal.GetTracerEnd(Position, Size, RootScreen, HeadScreen, FeetScreen)
    local Color = VisualState.Player.TracerColor local Thickness = VisualState.Player.TracerThickness local Transparency = 1 - VisualState.Player.TracerTransparency
    if VisualState.Player.TracerStyle == "Straight" then
        SetLine(Drawings.Tracer, From, To, Color, true, Thickness, Transparency)
        for Index = 1, 10 do
            local Segment = Drawings["TracerCurve" .. Index]
            if Segment then Segment.Visible = false end
        end
        return
    end
    if Drawings.Tracer then Drawings.Tracer.Visible = false end
    Internal.EnsureCurvedTracerDrawings(Data)
    local Delta = To - From local Direction = Delta.X >= 0 and 1 or -1
    local Control = Vector2.new(From.X + Delta.X * 0.46 + Direction * math.min(math.abs(Delta.Y) * 0.12, 90), From.Y + Delta.Y * 0.42) local Previous = From
    for Index = 1, 10 do
        local T = Index / 10 local Current = Internal.QuadraticBezier(From, Control, To, T)
        SetLine(Drawings["TracerCurve" .. Index], Previous, Current, Color, true, Thickness, Transparency)
        Previous = Current
    end
end

function HideTargetSnapline()
    local State = VisualState.Snapline

    if State.Line then State.Line.Visible = false end
    for _, Segment in ipairs(State.Curve) do
        if Segment then Segment.Visible = false end
    end
end

function EnsureTargetSnaplineDrawings()
    local State = VisualState.Snapline

    if not State.Line then
        State.Line = Internal.CreateDrawing("Line", { Visible = false, Thickness = State.Thickness, Transparency = 1 - State.Transparency, Color = State.Color,
            ZIndex = 8 })
    end

    if #State.Curve == 0 then
        for Index = 1, 12 do
            State.Curve[Index] = Internal.CreateDrawing("Line", { Visible = false, Thickness = State.Thickness, Transparency = 1 - State.Transparency,
                Color = State.Color, ZIndex = 8 })
        end
    end
end

function IsTargetSnaplinePlayerValid(Player)
    if not Player or Player == LocalPlayer or not Player.Parent then return false end

    local Data = VisualState.Player.Objects[Player] local Character = Data and Data.Character or Player.Character
    local Humanoid = Data and Data.Humanoid or Character and Character:FindFirstChildOfClass("Humanoid")
    local Root = Data and Data.Root or Character and Character:FindFirstChild("HumanoidRootPart")

    if not Character or not Humanoid or Humanoid.Health <= 0 or not Root then return false end

    if VisualState.Player.TeamCheck and LocalPlayer.Team and Player.Team == LocalPlayer.Team then return false end

    local LocalRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if LocalRoot and (Root.Position - LocalRoot.Position).Magnitude > VisualState.Player.MaxDistance then return false end

    return true
end

function GetClosestSnaplinePlayerToCursor()
    local CameraObject = Internal.GetCamera()
    if not CameraObject then return nil end

    local MousePosition = UserInputService:GetMouseLocation() local BestPlayer = nil local BestDistance = math.huge local List = VisualState.Player.List

    for Index = 1, #List do
        local Data = List[Index] local Player = Data and Data.Player

        if Player and IsTargetSnaplinePlayerValid(Player) then
            local Character = Data.Character or Player.Character
            local Part = Data.Head or Data.Root or Character and (Character:FindFirstChild("Head") or Character:FindFirstChild("HumanoidRootPart"))

            if Part then
                local ScreenPosition, OnScreen = CameraObject:WorldToViewportPoint(Part.Position)

                if OnScreen and ScreenPosition.Z > 0 then
                    local Distance = (Vector2.new(ScreenPosition.X, ScreenPosition.Y) - MousePosition).Magnitude

                    if Distance < BestDistance then
                        BestDistance = Distance
                        BestPlayer = Player
                    end
                end
            end
        end
    end

    return BestPlayer
end

function GetTargetSnaplinePlayer()
    local State = VisualState.Snapline

    if State.Source == "Closest to Cursor" then return GetClosestSnaplinePlayerToCursor() end

    if Ragebot.Enabled and IsTargetSnaplinePlayerValid(Ragebot.CurrentTarget) then return Ragebot.CurrentTarget end

    local AimTarget = Configuration and Configuration.AimBot and (Configuration.AimBot.CurrentTarget or Configuration.AimBot.AimbotLockedTarget or Configuration.AimBot.SilentAimLockedTarget)
    if Configuration and Configuration.AimBot and Configuration.AimBot.Enabled and IsTargetSnaplinePlayerValid(AimTarget) then return AimTarget end

    return nil
end

function GetTargetSnaplineWorldPosition(Character)
    if not Character then return nil end

    local TargetPart = VisualState.Snapline.TargetPart

    if TargetPart == "Head" then
        local Head = Character:FindFirstChild("Head")
        return Head and Head.Position or nil
    end

    if TargetPart == "Body" then
        local Body = Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("UpperTorso") or Character:FindFirstChild("Torso")

        return Body and Body.Position or nil
    end

    local Root = Character:FindFirstChild("HumanoidRootPart") local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Root then return nil end

    return Root.Position - Vector3.new(0, Humanoid and Humanoid.HipHeight + 1.7 or 3.2, 0)
end

function UpdateTargetSnapline()
    local State = VisualState.Snapline

    if not State.Enabled then
        HideTargetSnapline()
        return
    end

    EnsureTargetSnaplineDrawings()

    local CameraObject = Internal.GetCamera() local Target = GetTargetSnaplinePlayer()
    local Character = Target and Target.Character local WorldPosition = GetTargetSnaplineWorldPosition(Character)

    if not CameraObject or not WorldPosition then
        HideTargetSnapline()
        return
    end

    local ScreenPosition, OnScreen = CameraObject:WorldToViewportPoint(WorldPosition)
    if not OnScreen or ScreenPosition.Z <= 0 then
        HideTargetSnapline()
        return
    end

    local From = UserInputService:GetMouseLocation() local To = Vector2.new(ScreenPosition.X, ScreenPosition.Y) local Transparency = 1 - math.clamp(State.Transparency, 0, 1)

    if State.Style == "Straight" then
        SetLine(State.Line, From, To, State.Color, true, State.Thickness, Transparency)

        for _, Segment in ipairs(State.Curve) do
            if Segment then Segment.Visible = false end
        end

        return
    end

    if State.Line then State.Line.Visible = false end

    local Delta = To - From local Direction = Delta.X >= 0 and 1 or -1
    local Control = Vector2.new( From.X + Delta.X * 0.5 + Direction * math.min(math.abs(Delta.Y) * 0.18, 80), From.Y + Delta.Y * 0.42)

    local Previous = From

    for Index = 1, 12 do
        local Current = Internal.QuadraticBezier(From, Control, To, Index / 12)
        SetLine(State.Curve[Index], Previous, Current, State.Color, true, State.Thickness, Transparency)
        Previous = Current
    end
end

function Internal.ShouldRenderPlayer(Data, LocalRoot, HasEnemyTargets, Snapshot)
    if not Data.Character or not Data.Humanoid or not Data.Root or Data.Humanoid.Health <= 0 then return false end

    if HasEnemyTargets == true and EnemyTable[Data.Player] ~= true then return false end

    if VisualState.Player.TeamCheck and LocalPlayer.Team and Data.Player.Team
            == LocalPlayer.Team then
        return false
    end

    Snapshot = type(Snapshot) == "table" and Snapshot or Internal.GetPlayerVisualResolverSnapshot(Data, os.clock(), VisualState.Player.UpdateInterval)

    local TargetRootPosition = Snapshot and ResolverIsFiniteVector(Snapshot.ResolvedRootPosition) and Snapshot.ResolvedRootPosition or Data.Root.Position
    local Delta = TargetRootPosition - LocalRoot.Position

    local DistanceSquared = Delta:Dot(Delta)

    local MaximumDistance = math.max( tonumber(VisualState.Player.MaxDistance) or 1200, 1)

    if DistanceSquared
        > MaximumDistance * MaximumDistance then
        return false
    end

    return true, math.sqrt( DistanceSquared)
end

function Internal.UpdatePlayerESPData(Data, CameraObject, LocalRoot, CurrentTime, HasEnemyTargets, MaximumDistanceSquared)
    if not Data then return end
    if not Data.DrawingsReady then Internal.CreatePlayerVisual(Data.Player, true) end

    if not Data.Root or not Data.Root.Parent or not Data.Humanoid or not Data.Humanoid.Parent or not Data.Character or not Data.Character.Parent then
        Internal.RefreshPlayerCharacter(Data, Data.Player and Data.Player.Character)
        Internal.ResetPlayerEspBounds(Data)
    end

    if not Data.Character or not Data.Root or not Data.Humanoid or Data.Humanoid.Health <= 0
        or HasEnemyTargets and EnemyTable[Data.Player] ~= true
        or VisualState.Player.TeamCheck and LocalPlayer.Team and Data.Player.Team == LocalPlayer.Team
    then
        Data.EspEligible = false
        Internal.HidePlayerVisual(Data)
        return
    end

    local Pose = GetPlayerVisualRenderPose(Data, CurrentTime)
    local RenderRootPosition = Pose and Pose.RenderRootPosition or Data.Root.Position
    local Delta = RenderRootPosition - LocalRoot.Position
    local DistanceSquared = Delta:Dot(Delta)
    if DistanceSquared > MaximumDistanceSquared then
        Data.EspEligible = false
        Internal.HidePlayerVisual(Data)
        return
    end

    local Distance = math.sqrt(DistanceSquared)
    Data.LastEspDistance = Distance
    Data.EspEligible = true
    local DrawingCoreVisible = VisualState.Player.Renderer == "Drawing API" and Data.VisualHidden ~= true
    local AdaptiveColor, AdaptiveOutline = GetAdaptiveEspColor(Data, LocalRoot, CurrentTime)
    Data.LastEspAdaptiveColor = AdaptiveColor
    Data.LastEspAdaptiveOutline = AdaptiveOutline
    local Drawings = Data.Drawings

    if Data.DisplayNameText == nil then
        Data.DisplayNameText = Data.Player.DisplayName ~= Data.Player.Name and (Data.Player.DisplayName .. " [" .. Data.Player.Name .. "]") or Data.Player.Name
    end
    if Drawings.Name then
        Drawings.Name.Visible = DrawingCoreVisible and VisualState.Player.Names
        Drawings.Name.Text = Data.DisplayNameText
        Drawings.Name.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, false)
        Drawings.Name.Color = VisualState.Player.TextColor
    end

    if VisualState.Player.ProfilePicture and not Drawings.ProfilePicture then Internal.EnsureProfilePictureDrawings(Data) end
    if Drawings.ProfilePicture then
        if VisualState.Player.ProfilePicture and type(Data.ProfilePictureData) ~= "string" then QueueAtramentaProfilePicture(Data) end
        if VisualState.Player.ProfilePicture and type(Data.ProfilePictureData) == "string" and #Data.ProfilePictureData > 64 then
            if Data.ProfilePictureApplied ~= true then
                Data.ProfilePictureApplied = Internal.Call(function() Drawings.ProfilePicture.Data = Data.ProfilePictureData end) == true
            end
            Drawings.ProfilePicture.Visible = DrawingCoreVisible and Data.ProfilePictureApplied == true
            if Drawings.ProfilePictureBack then Drawings.ProfilePictureBack.Visible = DrawingCoreVisible and Data.ProfilePictureApplied == true end
        else
            Drawings.ProfilePicture.Visible = false
            if Drawings.ProfilePictureBack then Drawings.ProfilePictureBack.Visible = false end
        end
    end

    if CurrentTime >= (tonumber(Data.NextForcefieldUpdate) or 0) then
        Data.NextForcefieldUpdate = CurrentTime + 0.30
        Data.CachedForcefield = VisualState.Player.Forcefield.Enabled and CombatChecks.HasForceField(Data.Player, Data.Character) == true or false
    end
    if Drawings.Forcefield then
        Drawings.Forcefield.Visible = DrawingCoreVisible and VisualState.Player.Forcefield.Enabled and Data.CachedForcefield == true
        Drawings.Forcefield.Text = "[Forcefield]"
        Drawings.Forcefield.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
        Drawings.Forcefield.Color = VisualState.Player.Forcefield.Color
    end

    local ToolName = VisualState.Player.Weapon and Internal.GetCachedToolName(Data, CurrentTime) or nil
    if Drawings.Weapon then
        Drawings.Weapon.Visible = DrawingCoreVisible and VisualState.Player.Weapon and ToolName ~= nil
        if ToolName then Drawings.Weapon.Text = ToolName end
        Drawings.Weapon.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
        Drawings.Weapon.Color = VisualState.Player.TextColor
    end
    if Drawings.Distance then
        Drawings.Distance.Visible = DrawingCoreVisible and VisualState.Player.Distance
        if Drawings.Distance.Visible then Drawings.Distance.Text = tostring(math.floor(Distance + 0.5)) .. "m" end
        Drawings.Distance.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
        Drawings.Distance.Color = VisualState.Player.TextColor
    end

    local LevelValue = VisualState.Player.Level and GetCachedPlayerLevel(Data, CurrentTime) or nil
    if Drawings.Level then
        Drawings.Level.Visible = DrawingCoreVisible and LevelValue ~= nil
        if LevelValue ~= nil then Drawings.Level.Text = "Level " .. tostring(LevelValue) end
        Drawings.Level.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
        Drawings.Level.Color = VisualState.Player.LevelColor
    end

    local TargetHealthPercent = math.clamp(Data.Humanoid.Health / math.max(Data.Humanoid.MaxHealth, 1), 0, 1)
    local HealthPercent = UpdatePlayerHealthAnimation(Data, TargetHealthPercent, CurrentTime)
    local HealthColor = GetPlayerEspHealthColor(HealthPercent)
    if Drawings.HealthBack then Drawings.HealthBack.Visible = DrawingCoreVisible and VisualState.Player.HealthBar end
    if Drawings.HealthDelayed then
        Drawings.HealthDelayed.Visible = DrawingCoreVisible and VisualState.Player.HealthBar and VisualState.Player.Health.Delayed
        Drawings.HealthDelayed.Color = VisualState.Player.Health.DelayedColor
    end
    if Drawings.Health then Drawings.Health.Visible = DrawingCoreVisible and VisualState.Player.HealthBar; Drawings.Health.Color = HealthColor end
    if Drawings.HealthText then
        Drawings.HealthText.Visible = DrawingCoreVisible and VisualState.Player.HealthText
        Drawings.HealthText.Text = tostring(math.floor(Data.Humanoid.Health + 0.5))
        Drawings.HealthText.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
        Drawings.HealthText.Color = HealthColor
    end

    local EquippedTool, AmmoCurrent, AmmoMaximum = GetEquippedToolAndAmmo(Data, CurrentTime)
    if VisualState.Player.Flags.Enabled and not Drawings.Flags then EnsureFlagsDrawing(Data) end
    if VisualState.Player.Ammo.Enabled and not Drawings.AmmoBack then EnsureAmmoDrawings(Data) end
    if Drawings.Flags then
        local FlagText = BuildPlayerFlagsText(Data, Distance, AmmoCurrent, AmmoMaximum)
        Drawings.Flags.Visible = DrawingCoreVisible and FlagText ~= nil
        if FlagText then Drawings.Flags.Text = FlagText end
        Drawings.Flags.Color = VisualState.Player.Flags.Color
        Drawings.Flags.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
    end
    if Drawings.AmmoBack and Drawings.AmmoBar and Drawings.AmmoText then
        local ShowAmmo = DrawingCoreVisible and VisualState.Player.Ammo.Enabled and type(AmmoCurrent) == "number" and type(AmmoMaximum) == "number" and AmmoMaximum > 0
        Drawings.AmmoBack.Visible = ShowAmmo
        Drawings.AmmoBar.Visible = ShowAmmo
        Drawings.AmmoText.Visible = ShowAmmo and VisualState.Player.Ammo.Text == true
        Drawings.AmmoBack.Color = VisualState.Player.Ammo.BackColor
        Drawings.AmmoBar.Color = VisualState.Player.Ammo.Color
        Drawings.AmmoText.Color = VisualState.Player.Ammo.Color
        Drawings.AmmoText.Size = Internal.GetDrawingTextSize(VisualState.Player.TextSize, true)
        if ShowAmmo and Drawings.AmmoText.Visible then Drawings.AmmoText.Text = string.format("%d/%d", math.floor(AmmoCurrent + 0.5), math.floor(AmmoMaximum + 0.5)) end
    end

    if VisualState.Player.Renderer == "Roblox UI" then
        HidePlayerDrawingCore(Data)
        local Position, Size = GetPlayerBox(CameraObject, Data, false, Pose)
        if Position and Size then
            UpdatePlayerUiEsp(Data, Position, Size, Distance, ToolName, HealthPercent, HealthColor, AmmoCurrent, AmmoMaximum, CurrentTime, AdaptiveColor, AdaptiveOutline)
        end
    else
        HidePlayerUiEsp(Data)
    end
end

function Internal.UpdatePlayerESP()
    local CameraObject = Internal.GetCamera() local LocalRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    local List = VisualState.Player.List local Count = #List
    if not CameraObject or not LocalRoot then
        for _, Data in ipairs(List) do Internal.HidePlayerVisual(Data) end
        return
    end
    if Count == 0 then
        VisualState.Performance.EspCursor = 1
        return
    end

    local CurrentTime = os.clock() local HasEnemyTargets = AtramentaHasEnemyTargets()
    local MaximumDistance = math.max(tonumber(VisualState.Player.MaxDistance) or 1200, 1) local MaximumDistanceSquared = MaximumDistance * MaximumDistance
    VisualState.Performance.ActiveTarget = Internal.GetActiveConfirmedCombatTarget()
    local BatchDivisor = GetVisualHeavyBatchDivisor(Count) local BatchSize = math.max(1, math.ceil(Count / BatchDivisor))
    local Cursor = math.clamp(math.floor(tonumber(VisualState.Performance.EspCursor) or 1), 1, Count)

    for BatchOffset = 0, BatchSize - 1 do
        local Index = ((Cursor + BatchOffset - 1) % Count) + 1 local Data = List[Index]
        if Data then
            local Success = Internal.Call(Internal.UpdatePlayerESPData, Data, CameraObject, LocalRoot, CurrentTime, HasEnemyTargets, MaximumDistanceSquared)
            if not Success then
                Data.EspEligible = false
                Data.NextEspUpdate = 0
                Internal.HidePlayerVisual(Data)
            end
        end
    end

    VisualState.Performance.EspCursor = ((Cursor + BatchSize - 1) % Count) + 1
    VisualState.Performance.ActiveTarget = nil
end

ChamsGlowRuntime = ChamsGlowRuntime or { Bloom = nil }

function UpdateChamsBloom()
    local Bloom = ChamsGlowRuntime and ChamsGlowRuntime.Bloom
    if Bloom and Bloom.Parent then Bloom:Destroy() end
    if ChamsGlowRuntime then ChamsGlowRuntime.Bloom = nil end
end

function DisconnectNiggahackChamConnection(Connection)
    if Connection and typeof(Connection)
            == "RBXScriptConnection" then
        Connection:Disconnect()
    end
end

function DestroyNiggahackChamObject(Object)
    if Object and Object.Parent then Object:Destroy() end
end

function DestroyChams(Data)
    if not Data then return end

    if type(Data.Chams) == "table" then
        for _, Object in pairs(Data.Chams) do
            DestroyNiggahackChamObject(Object)
        end
    end

    if type(Data.ChamConnections) == "table" then
        for _, Connection in pairs(Data.ChamConnections) do
            DisconnectNiggahackChamConnection(Connection)
        end
    end

    if Data.ChamsGlow and Data.ChamsGlow.Parent then Data.ChamsGlow:Destroy() end

    if type(Data.ChamsOutlineShells) == "table" then
        for _, Shell in pairs(Data.ChamsOutlineShells) do
            if Shell and Shell.Parent then Shell:Destroy() end
        end
    end

    if type(Data.ChamsGlowShells) == "table" then
        for _, Shell in pairs(Data.ChamsGlowShells) do
            if Shell and Shell.Parent then Shell:Destroy() end
        end
    end

    if type(Data.ChamsSoftGlowShells) == "table" then
        for _, Shell in pairs(Data.ChamsSoftGlowShells) do
            if Shell and Shell.Parent then Shell:Destroy() end
        end
    end

    if type(Data.ChamProxies) == "table" then
        for _, Proxy in pairs(Data.ChamProxies) do
            if Proxy and Proxy.Parent then Proxy:Destroy() end
        end
    end

    if Data.ChamsHolder and Data.ChamsHolder.Parent then Data.ChamsHolder:Destroy() end

    Data.Chams = {}
    Data.ChamProxies = {}
    Data.ChamProxyList = {}
    Data.ChamConnections = {}
    Data.ChamsHolder = nil
    Data.ChamsGlow = nil
    Data.ChamsOutlineShells = {}
    Data.ChamsGlowShells = {}
    Data.ChamsSoftGlowShells = {}
    Data.ChamsCharacter = nil
    Data.ChamsRenderActive = false
end
function MakeNiggahackAdornment(Data, Part)
    if not Data or not Part or not Part:IsA("BasePart") or not EspBoundsPartNames[Part.Name] then return end
    if not Data.ChamsHolder or not Data.ChamsHolder.Parent or Data.Chams[Part] then return end

    Data.ChamProxies = Data.ChamProxies or {}
    Data.ChamProxyList = Data.ChamProxyList or {}

    local Proxy = Instance.new("Part")
    Proxy.Name = "AtramentaChamProxy"
    Proxy.Anchored = true
    Proxy.Massless = true
    Proxy.CanCollide = false
    Proxy.CanTouch = false
    Proxy.CanQuery = false
    Proxy.CastShadow = false
    Proxy.Transparency = 1
    Proxy.Size = GetEspR6CanonicalPartSize(Part) or Part.Size
    Proxy.CFrame = Part.CFrame
    Proxy.Parent = Data.ChamsHolder
    Data.ChamProxies[Part] = Proxy
    Data.ChamProxyList[#Data.ChamProxyList + 1] = {Part = Part, Proxy = Proxy}

    local Inner

    if Part.Name == "Head" then
        Inner = Instance.new("CylinderHandleAdornment")
        Inner.Adornee = Proxy
        Inner.ZIndex = 2
        Inner.Height = 0.87
        Inner.Radius = 0.5
        Inner.CFrame = CFrame.new(Vector3.new(), Vector3.new(0, 1, 0))
    else
        Inner = Instance.new("BoxHandleAdornment")
        Inner.Adornee = Proxy
        Inner.ZIndex = 2
        local BaseSize = GetEspR6CanonicalPartSize(Part) or Part.Size
        Inner.Size = BaseSize + Vector3.new(-0.05, -0.05, -0.05)
    end

    local Mode = tostring(VisualState.Player.Chams.Mode or "Overlay")
    Inner.AlwaysOnTop = true
    Inner.ZIndex = Mode == "Overlay" and 2 or 0
    Inner.Visible = false
    Inner.Parent = Data.ChamsHolder
    Data.Chams[Part] = Inner
end
function MakePlayerChamOutlineShell(Data, Part)
    if not Data or not Part or not Part:IsA("BasePart") or not EspBoundsPartNames[Part.Name] then return nil end

    Data.ChamsOutlineShells = type(Data.ChamsOutlineShells) == "table" and Data.ChamsOutlineShells or {}

    local Existing = Data.ChamsOutlineShells[Part]
    if Existing and Existing.Parent and Existing:IsA("BoxHandleAdornment") then return Existing end
    if Existing and Existing.Parent then Existing:Destroy() end

    local Shell = Instance.new("BoxHandleAdornment")
    Shell.Name = "AtramentaPlayerOutline"
    Shell.Adornee = Data.ChamProxies and Data.ChamProxies[Part] or Part
    Shell.AlwaysOnTop = false
    Shell.ZIndex = 0
    Shell.Visible = false
    Shell.Parent = Data.ChamsHolder
    Data.ChamsOutlineShells[Part] = Shell
    return Shell
end

function MakePlayerChamGlowShell(Data, Part, Soft)
    if not Data or not Part or not Part:IsA("BasePart") or not EspBoundsPartNames[Part.Name] then return nil end

    local Table = Soft and Data.ChamsSoftGlowShells or Data.ChamsGlowShells
    if type(Table) ~= "table" then
        Table = {}
        if Soft then Data.ChamsSoftGlowShells = Table else Data.ChamsGlowShells = Table end
    end

    local Existing = Table[Part]
    if Existing and Existing.Parent then return Existing end

    local Shell
    if Part.Name == "Head" then
        Shell = Instance.new("CylinderHandleAdornment")
        Shell.CFrame = CFrame.new(Vector3.zero, Vector3.new(0, 1, 0))
    else
        Shell = Instance.new("BoxHandleAdornment")
    end

    Shell.Name = Soft and "AtramentaPlayerSoftGlow" or "AtramentaPlayerTightGlow"
    Shell.Adornee = Data.ChamProxies and Data.ChamProxies[Part] or Part
    Shell.AlwaysOnTop = true
    Shell.Visible = false
    Shell.Parent = Data.ChamsHolder
    Table[Part] = Shell
    return Shell
end

function GetPlayerChamDistanceExpansion(Data)
    return 0
end

function UpdatePlayerChamOutlineShell(Data, Part, Shell, DistanceExpansion)
    if not Part or not Part.Parent or not Shell or not Shell.Parent then return end

    local Settings = VisualState.Player.Chams
    local Enabled = Settings.Enabled and Settings.OutlineEnabled
    local Mode = tostring(Settings.Mode or "Overlay")
    local OutlineColor = Settings.OutlineColor or Color3.fromRGB(255, 0, 105)
    local Transparency = math.clamp(tonumber(Settings.OutlineTransparency) or 0.21, 0, 1)
    local Scale = math.clamp(tonumber(Settings.OutlineSize) or 1.75, 1, 2.5)
    local Expansion = 0.025 + (Scale - 1) * 0.055 + math.max(tonumber(DistanceExpansion) or 0, 0) * 0.04

    if Shell.Color3 ~= OutlineColor then Shell.Color3 = OutlineColor end
    local AlwaysOnTop = Mode == "Overlay"
    if Shell.AlwaysOnTop ~= AlwaysOnTop then Shell.AlwaysOnTop = AlwaysOnTop end
    local ZIndex = Mode == "Overlay" and 1 or 0
    if Shell.ZIndex ~= ZIndex then Shell.ZIndex = ZIndex end
    if Shell.Transparency ~= Transparency then Shell.Transparency = Transparency end
    if Shell.Visible ~= Enabled then Shell.Visible = Enabled end

    local BaseSize = GetEspR6CanonicalPartSize(Part) or Part.Size

    if Shell:IsA("BoxHandleAdornment") then
        local Size = BaseSize + Vector3.new(Expansion, Expansion, Expansion)
        if Shell.Size ~= Size then Shell.Size = Size end
    end
end

function UpdatePlayerChamGlowShell(Data, Part, Shell, SoftShell, DistanceExpansion)
    if not Part or not Part.Parent then return end

    local Settings = VisualState.Player.Chams local GlowSize = math.clamp(tonumber(Settings.GlowSize) or 28, 8, 56)
    local GlowStrength = math.clamp(tonumber(Settings.GlowIntensity) or 1.35, 0.2, 3) local UserTransparency = math.clamp(tonumber(Settings.GlowTransparency) or 0.12, 0, 1)
    local SizeAlpha = (GlowSize - 8) / 48 local Distance = math.max(tonumber(DistanceExpansion) or 0, 0)
    local Mode = tostring(Settings.Mode or "Overlay") local Visible = Settings.Enabled and Settings.GlowEnabled

    local TightExpansion = 0.025 + SizeAlpha * 0.13 + Distance * 0.30 local SoftExpansion = 0.10 + SizeAlpha * 0.46 + Distance * 0.55
    local TightTransparency = math.clamp(0.76 - GlowStrength * 0.105 + UserTransparency * 0.24, 0.34, 0.86)
    local SoftTransparency = math.clamp(0.94 - GlowStrength * 0.035 + UserTransparency * 0.15, 0.76, 0.975)

    if Shell and Shell.Parent then
        local GlowColor = Data and Data.LastEspAdaptiveColor and VisualState.Player.Visibility.Enabled and VisualState.Player.Visibility.ApplyToChams and Data.LastEspAdaptiveColor or Settings.GlowColor
        if Shell.Color3 ~= GlowColor then Shell.Color3 = GlowColor end
        if Shell.AlwaysOnTop ~= true then Shell.AlwaysOnTop = true end
        local ZIndex = Mode == "Overlay" and 2 or 0
        if Shell.ZIndex ~= ZIndex then Shell.ZIndex = ZIndex end
        if Shell.Transparency ~= TightTransparency then Shell.Transparency = TightTransparency end
        if Shell.Visible ~= Visible then Shell.Visible = Visible end

        if Shell:IsA("BoxHandleAdornment") then
            local BaseSize = GetEspR6CanonicalPartSize(Part) or Part.Size local Size = BaseSize + Vector3.new(TightExpansion, TightExpansion, TightExpansion)
            if Shell.Size ~= Size then Shell.Size = Size end
        elseif Shell:IsA("CylinderHandleAdornment") then
            local Height = 0.90 + TightExpansion * 0.74 local Radius = 0.515 + TightExpansion * 0.38
            if Shell.Height ~= Height then Shell.Height = Height end
            if Shell.Radius ~= Radius then Shell.Radius = Radius end
        end
    end

    if SoftShell and SoftShell.Parent then
        local GlowColor = Data and Data.LastEspAdaptiveColor and VisualState.Player.Visibility.Enabled and VisualState.Player.Visibility.ApplyToChams and Data.LastEspAdaptiveColor or Settings.GlowColor
        if SoftShell.Color3 ~= GlowColor then SoftShell.Color3 = GlowColor end
        if SoftShell.AlwaysOnTop ~= true then SoftShell.AlwaysOnTop = true end
        local ZIndex = Mode == "Overlay" and 1 or 0
        if SoftShell.ZIndex ~= ZIndex then SoftShell.ZIndex = ZIndex end
        if SoftShell.Transparency ~= SoftTransparency then SoftShell.Transparency = SoftTransparency end
        if SoftShell.Visible ~= Visible then SoftShell.Visible = Visible end

        if SoftShell:IsA("BoxHandleAdornment") then
            local BaseSize = GetEspR6CanonicalPartSize(Part) or Part.Size local Size = BaseSize + Vector3.new(SoftExpansion, SoftExpansion, SoftExpansion)
            if SoftShell.Size ~= Size then SoftShell.Size = Size end
        elseif SoftShell:IsA("CylinderHandleAdornment") then
            local Height = 0.90 + SoftExpansion * 0.70 local Radius = 0.515 + SoftExpansion * 0.36
            if SoftShell.Height ~= Height then SoftShell.Height = Height end
            if SoftShell.Radius ~= Radius then SoftShell.Radius = Radius end
        end
    end
end

function BindNiggahackChams(Data)
    if not Data then return end

    local Character = Data.Character

    if not Character or not Character.Parent then
        DestroyChams(Data)
        return
    end

    if Data.ChamsCharacter == Character and Data.ChamsHolder and Data.ChamsHolder.Parent then return end

    DestroyChams(Data)

    Data.Chams = {}
    Data.ChamProxies = {}
    Data.ChamProxyList = {}
    Data.ChamsOutlineShells = {}
    Data.ChamsGlowShells = {}
    Data.ChamsSoftGlowShells = {}
    Data.ChamConnections = {}
    Data.ChamsCharacter = Character

    local Holder = Instance.new("Folder")
    Holder.Name = "Chams"
    Holder.Parent = workspace.CurrentCamera or workspace
    Data.ChamsHolder = Holder

    for _, Part in ipairs( Character:GetChildren() ) do
        if Part:IsA("BasePart") and EspBoundsPartNames[Part.Name] then MakeNiggahackAdornment(Data, Part) end
    end

    if Data.ChamsGlow and Data.ChamsGlow.Parent then
        Data.ChamsGlow:Destroy()
        Data.ChamsGlow = nil
    end

    Data.ChamConnections.ChildAdded = Character.ChildAdded:Connect( function(Child)
                if Child:IsA("BasePart") and EspBoundsPartNames[Child.Name] then MakeNiggahackAdornment(Data, Child) end
            end)

    Data.ChamConnections.ChildRemoved = Character.ChildRemoved:Connect( function(Child)
                if not Child:IsA("BasePart") then return end

                local Object = Data.Chams[Child]

                if Object then
                    DestroyNiggahackChamObject(Object)
                    Data.Chams[Child] = nil
                end

                local Proxy = Data.ChamProxies and Data.ChamProxies[Child]
                if Proxy then
                    DestroyNiggahackChamObject(Proxy)
                    Data.ChamProxies[Child] = nil
                end

                if type(Data.ChamProxyList) == "table" then
                    for Index = #Data.ChamProxyList, 1, -1 do
                        local Entry = Data.ChamProxyList[Index]
                        if not Entry or Entry.Part == Child then table.remove(Data.ChamProxyList, Index) end
                    end
                end

                local OutlineShell = Data.ChamsOutlineShells and Data.ChamsOutlineShells[Child]
                if OutlineShell then
                    DestroyNiggahackChamObject(OutlineShell)
                    Data.ChamsOutlineShells[Child] = nil
                end

                local GlowShell = Data.ChamsGlowShells and Data.ChamsGlowShells[Child]
                if GlowShell then
                    DestroyNiggahackChamObject(GlowShell)
                    Data.ChamsGlowShells[Child] = nil
                end

                local SoftGlowShell = Data.ChamsSoftGlowShells and Data.ChamsSoftGlowShells[Child]
                if SoftGlowShell then
                    DestroyNiggahackChamObject(SoftGlowShell)
                    Data.ChamsSoftGlowShells[Child] = nil
                end

            end)
end

function RepairNiggahackChams(Data)
    if not Data or not Data.Character or not Data.Character.Parent
        or not Data.ChamsHolder or not Data.ChamsHolder.Parent
    then
        return
    end

    Data.Chams = type(Data.Chams) == "table" and Data.Chams or {}
    Data.ChamProxies = type(Data.ChamProxies) == "table" and Data.ChamProxies or {}
    Data.ChamProxyList = type(Data.ChamProxyList) == "table" and Data.ChamProxyList or {}

    for _, Part in ipairs(Data.Character:GetChildren()) do
        if Part:IsA("BasePart") and EspBoundsPartNames[Part.Name] then
            local Object = Data.Chams[Part]
            local Proxy = Data.ChamProxies[Part]

            if not Object or not Object.Parent or not Proxy or not Proxy.Parent then
                if Object then DestroyNiggahackChamObject(Object) end
                if Proxy then DestroyNiggahackChamObject(Proxy) end

                Data.Chams[Part] = nil
                Data.ChamProxies[Part] = nil

                for Index = #Data.ChamProxyList, 1, -1 do
                    local Entry = Data.ChamProxyList[Index]
                    if not Entry or Entry.Part == Part then table.remove(Data.ChamProxyList, Index) end
                end

                MakeNiggahackAdornment(Data, Part)
            end
        end
    end
end

function UpdatePlayerChamRenderPose(Data, Pose)
    if not Data or Data.ChamsRenderActive ~= true then return end

    local List = Data.ChamProxyList
    if type(List) ~= "table" or #List == 0 then return end

    Pose = type(Pose) == "table" and Pose or GetPlayerVisualRenderPose(Data, os.clock())

    if not Pose
        or typeof(Pose.RawRootCFrame) ~= "CFrame"
        or typeof(Pose.RenderRootCFrame) ~= "CFrame"
    then
        return
    end

    local Correction = Pose.RenderRootCFrame * Pose.RawRootCFrame:Inverse()
    local Repair = false

    for Index = #List, 1, -1 do
        local Entry = List[Index]
        local Part = Entry and Entry.Part
        local Proxy = Entry and Entry.Proxy

        if Part and Part.Parent and Proxy and Proxy.Parent then
            Proxy.CFrame = Correction * Part.CFrame
        else
            table.remove(List, Index)

            if Part and Data.ChamProxies then
                Data.ChamProxies[Part] = nil
                Repair = Part.Parent ~= nil
            end
        end
    end

    if Repair then RepairNiggahackChams(Data) end
end
function UpdatePlayerVisualRenderPoses(CurrentTime)
    local List = VisualState.Player.List
    local ChamsEnabled = VisualState.Player.Chams.Enabled == true

    for Index = 1, #List do
        local Data = List[Index]

        if Data and Data.Root and Data.Root.Parent then
            local Pose = GetPlayerVisualRenderPose(Data, CurrentTime)

            if ChamsEnabled and Pose and Data.ChamsHolder and Data.ChamsHolder.Parent then
                UpdatePlayerChamRenderPose(Data, Pose)
            end
        end
    end
end

function GetPlayerChamPerformanceTier(Data)
    if not Data or not Data.Root or not Data.Root.Parent then return 0, math.huge end

    local LocalRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if not LocalRoot then return 0, math.huge end

    local Pose = GetPlayerVisualRenderPose(Data, os.clock())
    local RootPosition = Pose and Pose.RenderRootPosition or Data.Root.Position
    local Delta = RootPosition - LocalRoot.Position
    local DistanceSquared = Delta:Dot(Delta)
    local MaximumDistance = math.max(tonumber(VisualState.Player.MaxDistance) or 1200, 1)

    if DistanceSquared > MaximumDistance * MaximumDistance then
        return 0, math.sqrt(DistanceSquared)
    end

    local Distance = math.sqrt(DistanceSquared)
    local Count = math.max(#VisualState.Player.List, 1)
    local Fps = tonumber(VisualState.Performance.EstimatedFps) or 60
    local NearDistance
    local MidDistance

    if Count >= 24 then
        NearDistance, MidDistance = 180, 420
    elseif Count >= 18 then
        NearDistance, MidDistance = 240, 520
    elseif Count >= 12 then
        NearDistance, MidDistance = 320, 700
    else
        NearDistance, MidDistance = 450, 900
    end

    if Fps < 32 then
        NearDistance *= 0.65
        MidDistance *= 0.72
    elseif Fps < 45 then
        NearDistance *= 0.82
        MidDistance *= 0.86
    end

    VisualState.Performance.ChamNearDistance = NearDistance
    VisualState.Performance.ChamMidDistance = MidDistance

    if Distance <= NearDistance then return 3, Distance end
    if Distance <= MidDistance then return 2, Distance end
    return 1, Distance
end
function SetNiggahackChamsVisible(Data, Visible, Tier)
    if not Data then return end

    Tier = math.max(math.floor(tonumber(Tier) or tonumber(Data.ChamTier) or 0), 0)
    local CoreVisible = Visible == true and Tier >= 1
    local TightVisible = CoreVisible and Tier >= 2 and VisualState.Player.Chams.GlowEnabled
    local SoftVisible = CoreVisible and Tier >= 3 and VisualState.Player.Chams.GlowEnabled

    Data.ChamsRenderActive = CoreVisible

    if type(Data.Chams) == "table" then
        for _, Object in pairs(Data.Chams) do
            if Object and Object.Visible ~= CoreVisible then Object.Visible = CoreVisible end
        end
    end

    if Data.ChamsGlow and Data.ChamsGlow.Enabled ~= false then Data.ChamsGlow.Enabled = false end

    if type(Data.ChamsOutlineShells) == "table" then
        local OutlineVisible = CoreVisible and VisualState.Player.Chams.OutlineEnabled
        for _, Shell in pairs(Data.ChamsOutlineShells) do
            if Shell and Shell.Visible ~= OutlineVisible then Shell.Visible = OutlineVisible end
        end
    end

    if type(Data.ChamsGlowShells) == "table" then
        for _, Shell in pairs(Data.ChamsGlowShells) do
            if Shell and Shell.Visible ~= TightVisible then Shell.Visible = TightVisible end
        end
    end

    if type(Data.ChamsSoftGlowShells) == "table" then
        for _, Shell in pairs(Data.ChamsSoftGlowShells) do
            if Shell and Shell.Visible ~= SoftVisible then Shell.Visible = SoftVisible end
        end
    end
end
function ApplyPlayerChamData(Data, SkipBloom)
    if not Data then return end

    local Settings = VisualState.Player.Chams local Character = Data.Character local Humanoid = Data.Humanoid local PlayerObject = Data.Player
    local CurrentTime = os.clock()

    if CurrentTime < (tonumber(Data.NextChamsUpdate) or 0) then return end

    local TeamBlocked = VisualState.Player.TeamCheck and PlayerObject and PlayerObject.Team ~= nil and PlayerObject.Team == LocalPlayer.Team
    local EnemyBlocked = AtramentaHasEnemyTargets() and EnemyTable[PlayerObject] ~= true

    if not Settings.Enabled then
        if Data.ChamsHolder or next(Data.Chams) or next(Data.ChamConnections) then DestroyChams(Data) end
        return
    end

    if not Character or not Character.Parent or not Humanoid or not Humanoid.Parent or Humanoid.Health <= 0 or TeamBlocked or EnemyBlocked then
        Data.ChamTier = 0
        Data.NextChamsUpdate = CurrentTime + 0.20
        SetNiggahackChamsVisible(Data, false, 0)
        return
    end

    local Tier, Distance = GetPlayerChamPerformanceTier(Data)
    Data.ChamTier = Tier
    Data.LastChamDistance = Distance

    if Tier <= 0 then
        Data.NextChamsUpdate = CurrentTime + 0.18
        SetNiggahackChamsVisible(Data, false, 0)
        return
    end

    local PlayerCount = math.max(tonumber(VisualState.Performance.PlayerCount) or 0, 0)
    local ChamsScale = PlayerCount >= 28 and 1.55 or PlayerCount >= 18 and 1.30 or PlayerCount >= 10 and 1.15 or 1
    Data.NextChamsUpdate = CurrentTime + ((Tier >= 3 and 0.10 or Tier == 2 and 0.16 or 0.28) * ChamsScale)

    if Data.ChamsGlow and Data.ChamsGlow.Parent then
        Data.ChamsGlow:Destroy()
        Data.ChamsGlow = nil
    end

    BindNiggahackChams(Data)

    local CameraObject = workspace.CurrentCamera
    if Data.ChamsHolder and Data.ChamsHolder.Parent and CameraObject and Data.ChamsHolder.Parent ~= CameraObject then
        Data.ChamsHolder.Parent = CameraObject
    end

    RepairNiggahackChams(Data)
    SetNiggahackChamsVisible(Data, true, Tier)

    local Mode = tostring(Settings.Mode or "Overlay") local DistanceExpansion = Mode == "Overlay" and GetPlayerChamDistanceExpansion(Data) or 0
    local NormalTransparency = math.clamp(tonumber(Settings.NormalTransparency) or 0.62, 0, 1) local ResolverSnapshot

    if PlayerObject and Tier >= 2 then
        local SnapshotAge = Tier >= 3 and 0.12 or 0.22

        if Data.VisualResolverCharacter == Character and type(Data.VisualResolverSnapshot) == "table"
            and CurrentTime - (tonumber(Data.VisualResolverAt) or 0) <= SnapshotAge
        then
            ResolverSnapshot = Data.VisualResolverSnapshot
        else
            ResolverSnapshot = Internal.GetPlayerVisualResolverSnapshot(Data, CurrentTime, SnapshotAge)
        end
    end

    for Part, Object in pairs(Data.Chams) do
        if Object and Object.Parent and Part and Part.Parent then
            local PartPlausible = Tier == 1 or type(ResolverIsBodyPartPlausible) ~= "function" or ResolverIsBodyPartPlausible(Character, Part, ResolverSnapshot)

            if Object.Visible ~= PartPlausible then Object.Visible = PartPlausible end

            local OutlineShell = Data.ChamsOutlineShells and Data.ChamsOutlineShells[Part]
            if OutlineShell then
                local Visible = PartPlausible and Settings.OutlineEnabled
                if OutlineShell.Visible ~= Visible then OutlineShell.Visible = Visible end
            end

            local GlowShell = Data.ChamsGlowShells and Data.ChamsGlowShells[Part]
            if GlowShell then
                local Visible = PartPlausible and Tier >= 2 and Settings.GlowEnabled
                if GlowShell.Visible ~= Visible then GlowShell.Visible = Visible end
            end

            local SoftGlowShell = Data.ChamsSoftGlowShells and Data.ChamsSoftGlowShells[Part]
            if SoftGlowShell then
                local Visible = PartPlausible and Tier >= 3 and Settings.GlowEnabled
                if SoftGlowShell.Visible ~= Visible then SoftGlowShell.Visible = Visible end
            end

            if not PartPlausible then continue end

            local ChamColor = Settings.NormalColor
            if VisualState.Player.Visibility.Enabled and VisualState.Player.Visibility.ApplyToChams and Data.LastEspAdaptiveColor then ChamColor = Data.LastEspAdaptiveColor end
            if Object.Color3 ~= ChamColor then Object.Color3 = ChamColor end
            if Object.Transparency ~= NormalTransparency then Object.Transparency = NormalTransparency end
            if Object.AlwaysOnTop ~= true then Object.AlwaysOnTop = true end

            local DesiredZIndex = Mode == "Overlay" and 2 or 0
            if Object.ZIndex ~= DesiredZIndex then Object.ZIndex = DesiredZIndex end

            if Object:IsA("BoxHandleAdornment") then
                local Expansion = DistanceExpansion local BaseSize = GetEspR6CanonicalPartSize(Part) or Part.Size local DesiredSize = BaseSize + Vector3.new(
                    0.01 + Expansion * 0.35,
                    0.01 + Expansion * 0.35,
                    0.01 + Expansion * 0.35
                )

                DesiredSize = Vector3.new(
                    math.max(DesiredSize.X, 0.05),
                    math.max(DesiredSize.Y, 0.05),
                    math.max(DesiredSize.Z, 0.05)
                )

                if Object.Size ~= DesiredSize then Object.Size = DesiredSize end
            elseif Object:IsA("CylinderHandleAdornment") then
                local Height = 0.90 + DistanceExpansion * 0.28 local Radius = 0.515 + DistanceExpansion * 0.16

                if Object.Height ~= Height then Object.Height = Height end
                if Object.Radius ~= Radius then Object.Radius = Radius end
            end
        end
    end

    Data.ChamsOutlineShells = Data.ChamsOutlineShells or {}
    Data.ChamsGlowShells = Data.ChamsGlowShells or {}
    Data.ChamsSoftGlowShells = Data.ChamsSoftGlowShells or {}

    for Part in pairs(Data.Chams) do
        local OutlineShell = Settings.OutlineEnabled and MakePlayerChamOutlineShell(Data, Part) or Data.ChamsOutlineShells[Part]
        local TightShell local SoftShell

        if Tier >= 2 and Settings.GlowEnabled then
            TightShell = MakePlayerChamGlowShell(Data, Part, false)
        else
            TightShell = Data.ChamsGlowShells[Part]
        end

        if Tier >= 3 and Settings.GlowEnabled then
            SoftShell = MakePlayerChamGlowShell(Data, Part, true)
        else
            SoftShell = Data.ChamsSoftGlowShells[Part]
        end

        UpdatePlayerChamOutlineShell(Data, Part, OutlineShell, DistanceExpansion)
        UpdatePlayerChamGlowShell(Data, Part, TightShell, SoftShell, DistanceExpansion)

        if OutlineShell and not Settings.OutlineEnabled and OutlineShell.Visible then OutlineShell.Visible = false end
        if TightShell and Tier < 2 and TightShell.Visible then TightShell.Visible = false end
        if SoftShell and Tier < 3 and SoftShell.Visible then SoftShell.Visible = false end
    end

    Data.LastChamExpansion = DistanceExpansion
    if not SkipBloom then UpdateChamsBloom() end
end

function UpdatePlayerChams(ForceAll)
    local List = VisualState.Player.List local Count = #List

    if Count == 0 then
        VisualState.ChamsCursor = 1
        return
    end

    if ForceAll ~= false then
        for Index = 1, Count do
            local Data = List[Index]
            if Data then
                Data.NextChamsUpdate = 0
                ApplyPlayerChamData(Data, true)
            end
        end

        VisualState.ChamsCursor = 1
        UpdateChamsBloom()
        return
    end

    local Cursor = math.clamp(math.floor(tonumber(VisualState.ChamsCursor) or 1), 1, Count) local Divisor = Count >= 24 and 10 or Count >= 16 and 8 or 6
    local BatchSize = math.max(1, math.ceil(Count / Divisor)) local Updated = 0

    while Updated < BatchSize do
        local Data = List[Cursor]
        if Data then ApplyPlayerChamData(Data, true) end

        Cursor += 1
        if Cursor > Count then Cursor = 1 end
        Updated += 1
    end

    VisualState.ChamsCursor = Cursor
end

function Internal.IsWorldPostEffect(Object)
    return Object and (Object:IsA("ColorCorrectionEffect") or Object:IsA("BloomEffect") or Object:IsA("SunRaysEffect")
        or Object:IsA("DepthOfFieldEffect") or Object:IsA("BlurEffect"))
end

function Internal.IsAtramentaWorldEffect(Object)
    return Object == VisualState.World.ColorCorrection or Object == VisualState.World.BloomEffect or Object == VisualState.World.SunRaysEffect
        or Object == VisualState.World.DepthOfFieldEffect or Object == VisualState.World.BlurEffect
        or Object and (Object.Name == "AtramentaWorldColor" or Object.Name == "AtramentaWorldBloom" or Object.Name == "AtramentaWorldSunRays"
            or Object.Name == "AtramentaWorldDepthOfField" or Object.Name == "AtramentaWorldBlur")
end

function Internal.SaveWorldOriginal()
    if VisualState.World.Original then return end

    local Atmospheres = {}
    local PostEffects = setmetatable({}, {__mode = "k"})

    for _, Object in ipairs(Lighting:GetChildren()) do
        if Object:IsA("Atmosphere") and Object ~= VisualState.World.Atmosphere then
            Atmospheres[#Atmospheres + 1] = { Object = Object, Density = Object.Density, Offset = Object.Offset, Color = Object.Color, Decay = Object.Decay,
                Glare = Object.Glare, Haze = Object.Haze }
        elseif Internal.IsWorldPostEffect(Object) and not Internal.IsAtramentaWorldEffect(Object) then
            PostEffects[Object] = {Enabled = Object.Enabled}
        end
    end

    VisualState.World.Original = { Ambient = Lighting.Ambient, OutdoorAmbient = Lighting.OutdoorAmbient, ColorShiftTop = Lighting.ColorShift_Top,
        ColorShiftBottom = Lighting.ColorShift_Bottom, Brightness = Lighting.Brightness, ClockTime = Lighting.ClockTime,
        ExposureCompensation = Lighting.ExposureCompensation, GlobalShadows = Lighting.GlobalShadows,
        ShadowSoftness = Lighting.ShadowSoftness, EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale, EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale,
        FogColor = Lighting.FogColor, FogStart = Lighting.FogStart, FogEnd = Lighting.FogEnd, Atmospheres = Atmospheres, PostEffects = PostEffects }
end

function Internal.SetWorldProperty(Object, Property, Value)
    if Object and Object[Property] ~= Value then Object[Property] = Value end
end

function SaveWorldAtmosphere(Object)
    if not Object or not Object:IsA("Atmosphere") or Object == VisualState.World.Atmosphere then return end
    Internal.SaveWorldOriginal()

    local Original = VisualState.World.Original
    Original.Atmospheres = type(Original.Atmospheres) == "table" and Original.Atmospheres or {}

    for _, Entry in ipairs(Original.Atmospheres) do
        if Entry.Object == Object then return end
    end

    Original.Atmospheres[#Original.Atmospheres + 1] = { Object = Object, Density = Object.Density, Offset = Object.Offset, Color = Object.Color,
        Decay = Object.Decay, Glare = Object.Glare, Haze = Object.Haze }
end

function SuppressWorldAtmospheres()
    Internal.SaveWorldOriginal()

    for _, Object in ipairs(Lighting:GetChildren()) do
        if Object:IsA("Atmosphere") and Object ~= VisualState.World.Atmosphere then
            SaveWorldAtmosphere(Object)
            Internal.SetWorldProperty(Object, "Density", 0)
            Internal.SetWorldProperty(Object, "Haze", 0)
            Internal.SetWorldProperty(Object, "Glare", 0)
        end
    end

    VisualState.World.AtmospheresSuppressed = true
end

function RestoreAtramentaAtmospheres()
    local Atmosphere = VisualState.World.Atmosphere
    if Atmosphere then Atmosphere:Destroy() end
    VisualState.World.Atmosphere = nil
    VisualState.World.AtmospheresSuppressed = false

    local Original = VisualState.World.Original local Entries = Original and Original.Atmospheres
    if type(Entries) ~= "table" then return end

    for _, Entry in ipairs(Entries) do
        local Object = Entry.Object
        if Object and Object.Parent then
            Internal.Call(function()
                Object.Density = Entry.Density
                Object.Offset = Entry.Offset
                Object.Color = Entry.Color Object.Decay = Entry.Decay
                Object.Glare = Entry.Glare
                Object.Haze = Entry.Haze
            end)
        end
    end
end

function SaveWorldPostEffect(Object)
    if not Internal.IsWorldPostEffect(Object) or Internal.IsAtramentaWorldEffect(Object) then return end
    Internal.SaveWorldOriginal()

    local Original = VisualState.World.Original
    Original.PostEffects = type(Original.PostEffects) == "table" and Original.PostEffects or setmetatable({}, {__mode = "k"})
    if Original.PostEffects[Object] == nil then Original.PostEffects[Object] = {Enabled = Object.Enabled} end
end

function SuppressWorldPostEffects()
    for _, Object in ipairs(Lighting:GetChildren()) do
        if Internal.IsWorldPostEffect(Object) and not Internal.IsAtramentaWorldEffect(Object) then
            SaveWorldPostEffect(Object)
            Internal.SetWorldProperty(Object, "Enabled", false)
        end
    end
end

function RestoreWorldPostEffects()
    local Original = VisualState.World.Original local Entries = Original and Original.PostEffects
    if type(Entries) ~= "table" then return end

    for Object, Entry in pairs(Entries) do
        if Object and Object.Parent and type(Entry) == "table" then Internal.Call(function() Object.Enabled = Entry.Enabled == true end) end
    end
end

function EnsureAtramentaAtmosphere()
    if not VisualState.World.FogEnabled then
        RestoreAtramentaAtmospheres()
        return
    end

    SuppressWorldAtmospheres()

    local Atmosphere = VisualState.World.Atmosphere
    if not Atmosphere or not Atmosphere.Parent then
        Atmosphere = Instance.new("Atmosphere")
        Atmosphere.Name = "AtramentaFogAtmosphere"
        VisualState.World.Atmosphere = Atmosphere
        Atmosphere.Parent = Lighting
    end

    Internal.SetWorldProperty(Atmosphere, "Density", math.clamp(tonumber(VisualState.World.FogDensity) or 0.42, 0, 1))
    Internal.SetWorldProperty(Atmosphere, "Offset", math.clamp(tonumber(VisualState.World.FogOffset) or 0, -1, 1))
    Internal.SetWorldProperty(Atmosphere, "Color", VisualState.World.FogColor)
    Internal.SetWorldProperty(Atmosphere, "Decay", VisualState.World.FogDecay)
    Internal.SetWorldProperty(Atmosphere, "Glare", math.clamp(tonumber(VisualState.World.FogGlare) or 0.12, 0, 10))
    Internal.SetWorldProperty(Atmosphere, "Haze", math.clamp(tonumber(VisualState.World.FogHaze) or 2.4, 0, 10))
end

function WorldPostOverrideActive()
    local World = VisualState.World
    return World.ColorCorrectionEnabled == true or World.Bloom == true or World.SunRays == true or World.DepthOfField == true or World.Blur == true
end

function EnsureWorldEffects()
    if WorldPostOverrideActive() then SuppressWorldPostEffects() else RestoreWorldPostEffects() end

    local ColorCorrection = VisualState.World.ColorCorrection
    if VisualState.World.ColorCorrectionEnabled then
        if not ColorCorrection or not ColorCorrection.Parent then
            ColorCorrection = Instance.new("ColorCorrectionEffect")
            ColorCorrection.Name = "AtramentaWorldColor"
            VisualState.World.ColorCorrection = ColorCorrection
            ColorCorrection.Parent = Lighting
        end
        Internal.SetWorldProperty(ColorCorrection, "Enabled", true)
        Internal.SetWorldProperty(ColorCorrection, "Brightness", math.clamp(tonumber(VisualState.World.ColorCorrectionBrightness) or 0, -1, 1))
        Internal.SetWorldProperty(ColorCorrection, "Saturation", math.clamp(tonumber(VisualState.World.Saturation) or 0, -1, 1))
        Internal.SetWorldProperty(ColorCorrection, "Contrast", math.clamp(tonumber(VisualState.World.Contrast) or 0, -1, 1))
        Internal.SetWorldProperty(ColorCorrection, "TintColor", VisualState.World.TintColor)
    elseif ColorCorrection then
        ColorCorrection:Destroy()
        VisualState.World.ColorCorrection = nil
    end

    local Bloom = VisualState.World.BloomEffect
    if VisualState.World.Bloom then
        if not Bloom or not Bloom.Parent then
            Bloom = Instance.new("BloomEffect")
            Bloom.Name = "AtramentaWorldBloom"
            VisualState.World.BloomEffect = Bloom
            Bloom.Parent = Lighting
        end
        Internal.SetWorldProperty(Bloom, "Enabled", true)
        Internal.SetWorldProperty(Bloom, "Intensity", math.clamp(tonumber(VisualState.World.BloomIntensity) or 0.15, 0, 10))
        Internal.SetWorldProperty(Bloom, "Size", math.clamp(tonumber(VisualState.World.BloomSize) or 8.4, 0, 56))
        Internal.SetWorldProperty(Bloom, "Threshold", math.clamp(tonumber(VisualState.World.BloomThreshold) or 0.25, 0, 10))
    elseif Bloom then
        Bloom:Destroy()
        VisualState.World.BloomEffect = nil
    end

    local SunRays = VisualState.World.SunRaysEffect
    if VisualState.World.SunRays then
        if not SunRays or not SunRays.Parent then
            SunRays = Instance.new("SunRaysEffect")
            SunRays.Name = "AtramentaWorldSunRays"
            VisualState.World.SunRaysEffect = SunRays
            SunRays.Parent = Lighting
        end
        Internal.SetWorldProperty(SunRays, "Enabled", true)
        Internal.SetWorldProperty(SunRays, "Intensity", math.clamp(tonumber(VisualState.World.SunRaysIntensity) or 0.14, 0, 1))
        Internal.SetWorldProperty(SunRays, "Spread", math.clamp(tonumber(VisualState.World.SunRaysSpread) or 1, 0, 1))
    elseif SunRays then
        SunRays:Destroy()
        VisualState.World.SunRaysEffect = nil
    end

    local DepthOfField = VisualState.World.DepthOfFieldEffect
    if VisualState.World.DepthOfField then
        if not DepthOfField or not DepthOfField.Parent then
            DepthOfField = Instance.new("DepthOfFieldEffect")
            DepthOfField.Name = "AtramentaWorldDepthOfField"
            VisualState.World.DepthOfFieldEffect = DepthOfField
            DepthOfField.Parent = Lighting
        end
        Internal.SetWorldProperty(DepthOfField, "Enabled", true)
        Internal.SetWorldProperty(DepthOfField, "FarIntensity", math.clamp(tonumber(VisualState.World.DepthOfFieldFarIntensity) or 0.15, 0, 1))
        Internal.SetWorldProperty(DepthOfField, "FocusDistance", math.max(tonumber(VisualState.World.DepthOfFieldFocusDistance) or 50, 0))
        Internal.SetWorldProperty(DepthOfField, "InFocusRadius", math.max(tonumber(VisualState.World.DepthOfFieldInFocusRadius) or 50, 0))
        Internal.SetWorldProperty(DepthOfField, "NearIntensity", math.clamp(tonumber(VisualState.World.DepthOfFieldNearIntensity) or 0.15, 0, 1))
    elseif DepthOfField then
        DepthOfField:Destroy()
        VisualState.World.DepthOfFieldEffect = nil
    end

    local Blur = VisualState.World.BlurEffect
    if VisualState.World.Blur then
        if not Blur or not Blur.Parent then
            Blur = Instance.new("BlurEffect")
            Blur.Name = "AtramentaWorldBlur"
            VisualState.World.BlurEffect = Blur
            Blur.Parent = Lighting
        end
        Internal.SetWorldProperty(Blur, "Enabled", true)
        Internal.SetWorldProperty(Blur, "Size", math.clamp(tonumber(VisualState.World.BlurSize) or 8, 0, 56))
    elseif Blur then
        Blur:Destroy()
        VisualState.World.BlurEffect = nil
    end

    EnsureAtramentaAtmosphere()
end

function ApplyWorldLightingCore()
    if not VisualState.World.Enabled then return end

    local Original = VisualState.World.Original

    if VisualState.World.AmbienceEnabled then
        Internal.SetWorldProperty(Lighting, "Ambient", VisualState.World.Ambient)
        Internal.SetWorldProperty(Lighting, "OutdoorAmbient", VisualState.World.OutdoorAmbient)
    elseif Original then
        Internal.SetWorldProperty(Lighting, "Ambient", Original.Ambient)
        Internal.SetWorldProperty(Lighting, "OutdoorAmbient", Original.OutdoorAmbient)
    end

    if VisualState.World.ColorShiftEnabled then
        Internal.SetWorldProperty(Lighting, "ColorShift_Top", VisualState.World.ColorShiftTop)
        Internal.SetWorldProperty(Lighting, "ColorShift_Bottom", VisualState.World.ColorShiftBottom)
    elseif Original then
        Internal.SetWorldProperty(Lighting, "ColorShift_Top", Original.ColorShiftTop)
        Internal.SetWorldProperty(Lighting, "ColorShift_Bottom", Original.ColorShiftBottom)
    end

    Internal.SetWorldProperty(Lighting, "Brightness", VisualState.World.Brightness)
    if VisualState.World.TimeLock then Internal.SetWorldProperty(Lighting, "ClockTime", VisualState.World.ClockTime) end

    if VisualState.World.ExposureEnabled then
        Internal.SetWorldProperty(Lighting, "ExposureCompensation", math.clamp(tonumber(VisualState.World.ExposureCompensation) or 0, -5, 5))
    elseif Original then
        Internal.SetWorldProperty(Lighting, "ExposureCompensation", Original.ExposureCompensation)
    end
    Internal.SetWorldProperty(Lighting, "GlobalShadows", VisualState.World.GlobalShadows == true)
    Internal.SetWorldProperty(Lighting, "ShadowSoftness", math.clamp(tonumber(VisualState.World.ShadowSoftness) or 0.5, 0, 1))
    Internal.SetWorldProperty(Lighting, "EnvironmentDiffuseScale", math.clamp(tonumber(VisualState.World.EnvironmentDiffuseScale) or 1, 0, 1))
    Internal.SetWorldProperty(Lighting, "EnvironmentSpecularScale", math.clamp(tonumber(VisualState.World.EnvironmentSpecularScale) or 1, 0, 1))

    if VisualState.World.FogEnabled then
        local FogDistance = math.max(tonumber(VisualState.World.FogDistance) or 900, 25)
        local FogStart = math.clamp(tonumber(VisualState.World.FogStart) or 20, 0, math.max(FogDistance - 1, 0))
        Internal.SetWorldProperty(Lighting, "FogColor", VisualState.World.FogColor)
        Internal.SetWorldProperty(Lighting, "FogStart", FogStart)
        Internal.SetWorldProperty(Lighting, "FogEnd", FogDistance)
    elseif Original then
        Internal.SetWorldProperty(Lighting, "FogColor", Original.FogColor)
        Internal.SetWorldProperty(Lighting, "FogStart", Original.FogStart)
        Internal.SetWorldProperty(Lighting, "FogEnd", Original.FogEnd)
    end
end

function ApplyWorldVisuals()
    if not VisualState.World.Enabled or VisualState.World.Applying then return end

    VisualState.World.Applying = true
    local Success = Internal.Call(function()
        Internal.SaveWorldOriginal()
        ApplyWorldLightingCore()
        EnsureWorldEffects()
        VisualState.World.Dirty = false
    end)
    VisualState.World.Applying = false
    return Success
end

local WorldVisualApplyGeneration = 0

function StopStandaloneWorldEffects()
    local Connection = VisualState.World.StandaloneEffectConnection
    if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
    VisualState.World.StandaloneEffectConnection = nil
    VisualState.World.StandaloneEffectAccumulator = 0
end

function RefreshStandaloneWorldEffects()
    if VisualState.World.Enabled or not WorldPostOverrideActive() then
        StopStandaloneWorldEffects()
        return
    end
    if VisualState.World.StandaloneEffectConnection then return end

    VisualState.World.StandaloneEffectAccumulator = 0
    VisualState.World.StandaloneEffectConnection = RunService.Heartbeat:Connect(function(DeltaTime)
        if VisualState.World.Enabled or not WorldPostOverrideActive() then
            StopStandaloneWorldEffects()
            return
        end

        VisualState.World.StandaloneEffectAccumulator += math.clamp(tonumber(DeltaTime) or 0, 0, 0.10)
        if VisualState.World.StandaloneEffectAccumulator < 0.20 then return end
        VisualState.World.StandaloneEffectAccumulator %= 0.20

        if VisualState.World.Applying then return end
        VisualState.World.Applying = true
        Internal.Call(EnsureWorldEffects)
        VisualState.World.Applying = false
    end)
end

function QueueWorldPostApply()
    if VisualState.World.Enabled then
        VisualState.World.Dirty = true
        ApplyWorldVisuals()
        return
    end

    Internal.SaveWorldOriginal()
    if VisualState.World.Applying then return end

    VisualState.World.Applying = true
    Internal.Call(EnsureWorldEffects)
    VisualState.World.Applying = false
    RefreshStandaloneWorldEffects()
end

function QueueWorldVisualApply()
    if not VisualState.World.Enabled then return end
    VisualState.World.Dirty = true
    ApplyWorldVisuals()
end

function DisconnectWorldAtmosphereSignals(Object)
    local Connections = VisualState.World.AtmosphereConnections and VisualState.World.AtmosphereConnections[Object]
    if type(Connections) == "table" then
        for Index = 1, #Connections do
            local Connection = Connections[Index]
            if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
        end
    end
    if VisualState.World.AtmosphereConnections then VisualState.World.AtmosphereConnections[Object] = nil end
end

function DisconnectWorldPostEffectSignal(Object)
    local Connection = VisualState.World.PostEffectConnections and VisualState.World.PostEffectConnections[Object]
    if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
    if VisualState.World.PostEffectConnections then VisualState.World.PostEffectConnections[Object] = nil end
end

function DisconnectWorldOverrideSignals()
    if type(VisualState.World.PropertyConnections) == "table" then
        for _, Connection in ipairs(VisualState.World.PropertyConnections) do
            if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
        end
    end
    table.clear(VisualState.World.PropertyConnections)

    if type(VisualState.World.ChildConnections) == "table" then
        for _, Connection in ipairs(VisualState.World.ChildConnections) do
            if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
        end
    end
    table.clear(VisualState.World.ChildConnections)

    if type(VisualState.World.AtmosphereConnections) == "table" then
        for _, Connections in pairs(VisualState.World.AtmosphereConnections) do
            if type(Connections) == "table" then
                for Index = 1, #Connections do
                    local Connection = Connections[Index]
                    if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
                end
            end
        end
    end
    VisualState.World.AtmosphereConnections = setmetatable({}, {__mode = "k"})

    if type(VisualState.World.PostEffectConnections) == "table" then
        for _, Connection in pairs(VisualState.World.PostEffectConnections) do
            if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
        end
    end
    VisualState.World.PostEffectConnections = setmetatable({}, {__mode = "k"})
end

function QueueWorldOverrideCorrection()
    if not VisualState.World.Enabled or VisualState.World.Applying or VisualState.World.CorrectionQueued then return end
    VisualState.World.CorrectionQueued = true

    task.defer(function()
        VisualState.World.CorrectionQueued = false
        if not VisualState.World.Enabled or VisualState.World.Applying then return end

        VisualState.World.Applying = true
        Internal.Call(function()
            ApplyWorldLightingCore()
            if VisualState.World.Dirty then EnsureWorldEffects(); VisualState.World.Dirty = false end
        end)
        VisualState.World.Applying = false
    end)
end

function BindWorldAtmosphereSignals(Object)
    if not Object or not Object:IsA("Atmosphere") or Object == VisualState.World.Atmosphere then return end
    DisconnectWorldAtmosphereSignals(Object)

    local Connections = {}
    VisualState.World.AtmosphereConnections[Object] = Connections
    local Properties = {"Density", "Offset", "Color", "Decay", "Glare", "Haze"}

    for Index = 1, #Properties do
        Connections[Index] = Object:GetPropertyChangedSignal(Properties[Index]):Connect(function()
            if VisualState.World.Enabled and not VisualState.World.Applying then
                VisualState.World.Dirty = true
                QueueWorldOverrideCorrection()
            end
        end)
    end
end

function BindWorldPostEffectSignal(Object)
    if not Internal.IsWorldPostEffect(Object) or Internal.IsAtramentaWorldEffect(Object) then return end
    DisconnectWorldPostEffectSignal(Object)
    SaveWorldPostEffect(Object)

    VisualState.World.PostEffectConnections[Object] = Object:GetPropertyChangedSignal("Enabled"):Connect(function()
        if not VisualState.World.Enabled or VisualState.World.Applying or Internal.IsAtramentaWorldEffect(Object) or not WorldPostOverrideActive() then return end
        VisualState.World.Applying = true
        Internal.SetWorldProperty(Object, "Enabled", false)
        VisualState.World.Applying = false
    end)
end

function BindWorldOverrideSignals()
    DisconnectWorldOverrideSignals()

    local Properties = {"Ambient", "OutdoorAmbient", "ColorShift_Top", "ColorShift_Bottom", "Brightness", "ExposureCompensation", "GlobalShadows", "ShadowSoftness", "EnvironmentDiffuseScale", "EnvironmentSpecularScale", "FogColor", "FogStart", "FogEnd"}
    for Index = 1, #Properties do
        VisualState.World.PropertyConnections[Index] = Lighting:GetPropertyChangedSignal(Properties[Index]):Connect(function()
            QueueWorldOverrideCorrection()
        end)
    end

    for _, Object in ipairs(Lighting:GetChildren()) do
        if Object:IsA("Atmosphere") and Object ~= VisualState.World.Atmosphere then BindWorldAtmosphereSignals(Object) end
        if Internal.IsWorldPostEffect(Object) and not Internal.IsAtramentaWorldEffect(Object) then BindWorldPostEffectSignal(Object) end
    end

    VisualState.World.ChildConnections[1] = Lighting.ChildAdded:Connect(function(Object)
        if not VisualState.World.Enabled or VisualState.World.Applying then return end

        if Object:IsA("Atmosphere") and Object ~= VisualState.World.Atmosphere then
            SaveWorldAtmosphere(Object)
            BindWorldAtmosphereSignals(Object)
            VisualState.World.Dirty = true
            QueueWorldOverrideCorrection()
            return
        end

        if Internal.IsWorldPostEffect(Object) and not Internal.IsAtramentaWorldEffect(Object) then
            SaveWorldPostEffect(Object)
            BindWorldPostEffectSignal(Object)
            if WorldPostOverrideActive() then
                VisualState.World.Applying = true
                Internal.SetWorldProperty(Object, "Enabled", false)
                VisualState.World.Applying = false
            end
        end
    end)

    VisualState.World.ChildConnections[2] = Lighting.ChildRemoved:Connect(function(Object)
        if Object:IsA("Atmosphere") then DisconnectWorldAtmosphereSignals(Object) end
        if Internal.IsWorldPostEffect(Object) then DisconnectWorldPostEffectSignal(Object) end
        if not VisualState.World.Enabled or VisualState.World.Applying then return end

        if Object == VisualState.World.Atmosphere then VisualState.World.Atmosphere = nil end
        if Object == VisualState.World.ColorCorrection then VisualState.World.ColorCorrection = nil end
        if Object == VisualState.World.BloomEffect then VisualState.World.BloomEffect = nil end
        if Object == VisualState.World.SunRaysEffect then VisualState.World.SunRaysEffect = nil end
        if Object == VisualState.World.DepthOfFieldEffect then VisualState.World.DepthOfFieldEffect = nil end
        if Object == VisualState.World.BlurEffect then VisualState.World.BlurEffect = nil end

        if Object:IsA("Atmosphere") or Internal.IsWorldPostEffect(Object) then
            VisualState.World.Dirty = true
            QueueWorldOverrideCorrection()
        end
    end)
end

function StartWorldOverride()
    Internal.SaveWorldOriginal()
    StopStandaloneWorldEffects()

    Internal.Call(function()
        RunService:UnbindFromRenderStep( VisualState.World.RenderStepName)
    end)

    if VisualState.World.Connection then
        Internal.Call(function()
            VisualState.World.Connection:Disconnect()
        end)
        VisualState.World.Connection = nil
    end

    DisconnectWorldOverrideSignals()

    VisualState.World.Accumulator = 0
    VisualState.World.EffectAccumulator = 0
    VisualState.World.CorrectionQueued = false
    VisualState.World.Bound = true
    VisualState.World.Dirty = true

    ApplyWorldVisuals()
    BindWorldOverrideSignals()

    VisualState.World.Connection = RunService.Heartbeat:Connect(function(DeltaTime)
            if not VisualState.World.Enabled then return end

            DeltaTime = math.clamp( tonumber(DeltaTime) or 0, 0, 0.10)

            VisualState.World.Accumulator += DeltaTime
            VisualState.World.EffectAccumulator += DeltaTime

            if VisualState.World.Accumulator >= 0.25 then
                VisualState.World.Accumulator = VisualState.World.Accumulator % 0.25

                if VisualState.World.Dirty then
                    ApplyWorldVisuals()
                elseif not VisualState.World.Applying then
                    VisualState.World.Applying = true
                    Internal.Call( ApplyWorldLightingCore)
                    VisualState.World.Applying = false
                end
            end

            if VisualState.World.EffectAccumulator >= 0.20 then
                VisualState.World.EffectAccumulator = VisualState.World.EffectAccumulator % 0.20

                if not VisualState.World.Dirty and not VisualState.World.Applying then
                    VisualState.World.Applying = true
                    Internal.Call( EnsureWorldEffects)
                    VisualState.World.Applying = false
                end
            end
        end)
end

function RestoreWorldVisuals(Full)
    Internal.Call(function() RunService:UnbindFromRenderStep(VisualState.World.RenderStepName) end)
    DisconnectWorldOverrideSignals()

    if VisualState.World.Connection then
        Internal.Call(function() VisualState.World.Connection:Disconnect() end)
        VisualState.World.Connection = nil
    end

    VisualState.World.Accumulator = 0
    VisualState.World.EffectAccumulator = 0
    VisualState.World.CorrectionQueued = false
    VisualState.World.Bound = false

    local Original = VisualState.World.Original
    if Original then
        Internal.Call(function()
            Lighting.Ambient = Original.Ambient
            Lighting.OutdoorAmbient = Original.OutdoorAmbient
            Lighting.ColorShift_Top = Original.ColorShiftTop
            Lighting.ColorShift_Bottom = Original.ColorShiftBottom
            Lighting.Brightness = Original.Brightness
            Lighting.ClockTime = Original.ClockTime
            Lighting.ExposureCompensation = Original.ExposureCompensation
            Lighting.GlobalShadows = Original.GlobalShadows
            Lighting.ShadowSoftness = Original.ShadowSoftness
            Lighting.EnvironmentDiffuseScale = Original.EnvironmentDiffuseScale
            Lighting.EnvironmentSpecularScale = Original.EnvironmentSpecularScale
            Lighting.FogColor = Original.FogColor Lighting.FogStart = Original.FogStart
            Lighting.FogEnd = Original.FogEnd
        end)
    end

    RestoreAtramentaAtmospheres()

    if VisualState.World.ColorCorrection then
        VisualState.World.ColorCorrection:Destroy()
        VisualState.World.ColorCorrection = nil
    end
    if VisualState.World.BloomEffect then
        VisualState.World.BloomEffect:Destroy()
        VisualState.World.BloomEffect = nil
    end
    if VisualState.World.SunRaysEffect then
        VisualState.World.SunRaysEffect:Destroy()
        VisualState.World.SunRaysEffect = nil
    end
    if VisualState.World.DepthOfFieldEffect then
        VisualState.World.DepthOfFieldEffect:Destroy()
        VisualState.World.DepthOfFieldEffect = nil
    end
    if VisualState.World.BlurEffect then
        VisualState.World.BlurEffect:Destroy()
        VisualState.World.BlurEffect = nil
    end

    RestoreWorldPostEffects()
    StopStandaloneWorldEffects()
    VisualState.World.Original = nil
    VisualState.World.Applying = false
    VisualState.World.Dirty = false

    if Full ~= true and WorldPostOverrideActive() then
        QueueWorldPostApply()
    end
end

function VisualState.World.StopTimeLock()
    local Connection = VisualState.World.TimeLockConnection
    if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
    VisualState.World.TimeLockConnection = nil
    VisualState.World.TimeLockApplying = false
end

function VisualState.World.ApplyLockedTime()
    if VisualState.World.Enabled ~= true or VisualState.World.TimeLock ~= true or VisualState.World.TimeLockApplying then return end

    local DesiredTime = math.clamp(tonumber(VisualState.World.ClockTime) or Lighting.ClockTime, 0, 24)
    if math.abs(Lighting.ClockTime - DesiredTime) <= 0.001 then return end

    VisualState.World.TimeLockApplying = true
    Lighting.ClockTime = DesiredTime
    VisualState.World.TimeLockApplying = false
end

function VisualState.World.RefreshTimeLock()
    VisualState.World.StopTimeLock()
    if VisualState.World.Enabled ~= true or VisualState.World.TimeLock ~= true then return end

    VisualState.World.ClockTime = math.clamp(tonumber(VisualState.World.ClockTime) or Lighting.ClockTime, 0, 24)
    VisualState.World.ApplyLockedTime()

    VisualState.World.TimeLockConnection = Lighting:GetPropertyChangedSignal("ClockTime"):Connect(function()
        if VisualState.World.Enabled ~= true or VisualState.World.TimeLock ~= true or VisualState.World.TimeLockApplying then return end
        VisualState.World.ApplyLockedTime()
    end)
end

VisualState.World.StopTimeLock()

function GetWorldAdornee(Object)
    if Object:IsA("BasePart") then return Object end
    if Object:IsA("Model") then return Object.PrimaryPart or Object:FindFirstChildWhichIsA("BasePart", true) end
    return Object:FindFirstChildWhichIsA("BasePart", true)
end

function GetWorldObjectBrokenState(Object)
    local Values = Object and Object:FindFirstChild("Values") local Broken = Values and Values:FindFirstChild("Broken")
    if Broken and Broken:IsA("ValueBase") then return Broken.Value == true, true end
    return false, false
end

function GetWorldObjectColor(Object, Kind)
    local IsBroken = GetWorldObjectBrokenState(Object)
    if IsBroken then return VisualState.WorldESP.BrokenColor end
    if Kind == "SAFE" then return VisualState.WorldESP.SafeColor end
    return VisualState.WorldESP.CashColor end

function Internal.GetSafeDisplayName(Object)
    local Name = string.lower(Object.Name)
    if string.find(Name, "register", 1, true) then return "Register" end
    if string.find(Name, "small", 1, true) then return "Small Safe" end
    if string.find(Name, "medium", 1, true) then return "Medium Safe" end
    if string.find(Name, "large", 1, true) then return "Large Safe" end
    return "Safe"
end

function GetWorldObjectText(Object, Kind)
    if Kind == "SAFE" then return Internal.GetSafeDisplayName(Object) end
    return "Cash"
end

function CreateWorldLabel(Object, Kind)
    local Adornee = GetWorldAdornee(Object)
    if not Adornee then return nil end
    local Billboard = Instance.new("BillboardGui")
    Billboard.Name = "AtramentaWorld" .. Kind
    Billboard.AlwaysOnTop = true
    Billboard.Size = UDim2.fromOffset(164, 20)
    Billboard.StudsOffset = Vector3.new(0, 2.25, 0)
    Billboard.MaxDistance = VisualState.WorldESP.MaxDistance
    local CurrentPlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or PlayerGui
    if not CurrentPlayerGui then
        Billboard:Destroy()
        return nil
    end

    Billboard.Adornee = Adornee
    Billboard.Parent = CurrentPlayerGui
    local Label = Instance.new("TextLabel")
    Label.Name = "Label"
    Label.Size = UDim2.new(1, 0, 1, 0)
    Label.BackgroundTransparency = 1
    Label.FontFace = UiFont
    Label.TextScaled = false
    Label.TextWrapped = false
    Label.TextSize = 12
    Label.TextStrokeTransparency = 0.18
    Label.TextColor3 = GetWorldObjectColor(Object, Kind)
    Label.Parent = Billboard
    local Data = { Object = Object, Kind = Kind, Billboard = Billboard, Label = Label, Adornee = Adornee, LastColor = Label.TextColor3, LastText = nil, LastMaxDistance = VisualState.WorldESP.MaxDistance }
    VisualState.WorldESP.Objects[Object] = Data
    return Data
end

function GetWorldObjects()
    local Objects = {}
    if VisualState.WorldESP.Safes then
        local Map = workspace:FindFirstChild("Map") local Folder = Map and Map:FindFirstChild("BredMakurz")
        if Folder then
            for Unused, Object in ipairs(Folder:GetChildren()) do
                local Name = string.lower(Object.Name)
                if string.find(Name, "safe", 1, true) or string.find(Name, "register", 1, true) then Objects[Object] = "SAFE" end
            end
        end
    end
    if VisualState.WorldESP.Cash then
        local Filter = workspace:FindFirstChild("Filter") local Folder = Filter and Filter:FindFirstChild("SpawnedBread")
        if Folder then
            for Unused, Object in ipairs(Folder:GetChildren()) do Objects[Object] = "CASH" end
        end
    end
    return Objects
end

function ClearWorldESPLabels()
    for Object, Data in pairs(VisualState.WorldESP.Objects) do
        if Data and Data.Billboard and Data.Billboard.Parent then Data.Billboard:Destroy() end
        VisualState.WorldESP.Objects[Object] = nil
    end
end

function RefreshWorldESP(Force)
    if Force == true then
        VisualState.WorldESP.LastScan = 0
        VisualState.WorldClock = 0
    end

    if VisualState.WorldESP.Safes or VisualState.WorldESP.Cash then
        UpdateWorldESP()
    elseif next(VisualState.WorldESP.Objects) then
        ClearWorldESPLabels()
    end
end

function UpdateWorldESP()
    local CurrentTime = os.clock()
    if CurrentTime - VisualState.WorldESP.LastScan < 0.20 then return end
    VisualState.WorldESP.LastScan = CurrentTime

    local Current = GetWorldObjects()

    for Object, Data in pairs(VisualState.WorldESP.Objects) do
        local ShouldRemove = not Current[Object] or not Object or not Object.Parent

        if not ShouldRemove then
            local Adornee = GetWorldAdornee(Object)
            ShouldRemove = not Adornee or not Adornee.Parent or not Data or not Data.Billboard or not Data.Billboard.Parent or not Data.Label
                or not Data.Label.Parent or Data.Adornee ~= Adornee or Data.Billboard.Adornee ~= Adornee
        end

        if ShouldRemove then
            if Data and Data.Billboard and Data.Billboard.Parent then Data.Billboard:Destroy() end
            VisualState.WorldESP.Objects[Object] = nil
        end
    end

    for Object, Kind in pairs(Current) do
        local Data = VisualState.WorldESP.Objects[Object]

        if not Data then Data = CreateWorldLabel(Object, Kind) end

        if Data and Data.Billboard and Data.Billboard.Parent and Data.Label and Data.Label.Parent then
            local Adornee = GetWorldAdornee(Object)

            if Adornee and Adornee.Parent then
                if Data.Adornee ~= Adornee or Data.Billboard.Adornee ~= Adornee then
                    Data.Adornee = Adornee
                    Data.Billboard.Adornee = Adornee
                end

                local MaximumDistance = VisualState.WorldESP.MaxDistance
                if Data.LastMaxDistance ~= MaximumDistance then
                    Data.Billboard.MaxDistance = MaximumDistance
                    Data.LastMaxDistance = MaximumDistance
                end

                local Color = GetWorldObjectColor(Object, Kind)
                if Data.LastColor ~= Color then
                    Data.Label.TextColor3 = Color Data.LastColor = Color end

                local LabelText = GetWorldObjectText(Object, Kind)
                if Data.LastText ~= LabelText then
                    Data.Label.Text = LabelText
                    Data.LastText = LabelText
                end
            else
                if Data.Billboard and Data.Billboard.Parent then Data.Billboard:Destroy() end
                VisualState.WorldESP.Objects[Object] = nil
            end
        end
    end
end

function IsPlayerVisualCacheNeeded()
    return VisualState.Player.Enabled == true or VisualState.Player.Chams.Enabled == true
end

function ShutdownPlayerVisualCache()
    if VisualState.Player.UiProjectionBound == true then
        VisualState.Player.UiProjectionBound = false
        RunService:UnbindFromRenderStep("AtramentaPlayerUiProjection")
    end
    if VisualState.PlayerAddedConnection then VisualState.PlayerAddedConnection:Disconnect(); VisualState.PlayerAddedConnection = nil end
    if VisualState.PlayerRemovingConnection then VisualState.PlayerRemovingConnection:Disconnect(); VisualState.PlayerRemovingConnection = nil end
    if VisualState.WorldCharactersConnection then VisualState.WorldCharactersConnection:Disconnect(); VisualState.WorldCharactersConnection = nil end
    if VisualState.WorldContainerConnection then VisualState.WorldContainerConnection:Disconnect(); VisualState.WorldContainerConnection = nil end
    if VisualState.WorldRootConnection then VisualState.WorldRootConnection:Disconnect(); VisualState.WorldRootConnection = nil end

    VisualState.BoundWorldCharacters = nil
    VisualState.BoundWorldContainer = nil

    for Index = #VisualState.Player.List, 1, -1 do
        local Data = VisualState.Player.List[Index]
        if Data and Data.Player then Internal.DestroyPlayerVisual(Data.Player) end
    end

    table.clear(VisualState.Player.List)
    table.clear(VisualState.Player.Objects)
    table.clear(VisualState.Player.ProfilePictureCache)
    if VisualState.Player.UiRoot and VisualState.Player.UiRoot.Parent then VisualState.Player.UiRoot:Destroy() end
    VisualState.Player.UiRoot = nil
    VisualState.Initialized = false
end

function IsVisualEngineNeeded()
    return VisualState.Player.Enabled == true or VisualState.Player.Chams.Enabled == true or VisualState.Snapline.Enabled == true
        or VisualState.WorldESP.Safes == true or VisualState.WorldESP.Cash == true
end

function EnsureVisualEngine()
    RefreshPlayerUiProjection()
    local PlayerCacheNeeded = IsPlayerVisualCacheNeeded()
    if PlayerCacheNeeded then
        Internal.EnsurePlayerCache()
    elseif VisualState.Initialized then
        ShutdownPlayerVisualCache()
    end

    if not IsVisualEngineNeeded() then
        if VisualState.Connection then
            VisualState.Connection:Disconnect()
            VisualState.Connection = nil
        end
        VisualState.PlayerClock = 0
        VisualState.ChamsClock = 0
        VisualState.CacheClock = 0
        VisualState.WorldClock = 0
        VisualState.ChamsCursor = 1
        VisualState.Performance.EspCursor = 1
        VisualState.Performance.LastEspCameraCFrame = nil
        return
    end

    if VisualState.ChamsRenderConnection then
        VisualState.ChamsRenderConnection:Disconnect()
        VisualState.ChamsRenderConnection = nil
    end
    if VisualState.Connection then return end

    VisualState.Connection = RunService.RenderStepped:Connect(function(DeltaTime)
        DeltaTime = math.clamp(DeltaTime, 0, 0.05)

        local Performance = VisualState.Performance
        Performance.SmoothedDelta += (DeltaTime - Performance.SmoothedDelta) * math.clamp(DeltaTime * 4, 0, 1)
        Performance.EstimatedFps = 1 / math.max(Performance.SmoothedDelta, 1 / 240)
        Performance.PlayerCount = #VisualState.Player.List

        if not IsVisualEngineNeeded() then
            local Connection = VisualState.Connection
            VisualState.Connection = nil
            if Connection then Connection:Disconnect() end
            return
        end

        local PlayerRuntimeActive = VisualState.Player.Enabled or VisualState.Player.Chams.Enabled
        if PlayerRuntimeActive then
            if VisualState.Player.Chams.Enabled and not VisualState.Player.Enabled then
                Internal.Call(UpdatePlayerVisualRenderPoses, os.clock())
            end

            VisualState.CacheClock += DeltaTime
            local ReconcileInterval = Performance.PlayerCount >= 18 and 5 or 3

            if VisualState.CacheClock >= ReconcileInterval then
                VisualState.CacheClock = 0
                Internal.ReconcilePlayerVisualCache()
            end
        else
            VisualState.CacheClock = 0
        end

        if VisualState.Player.Enabled then
            VisualState.PlayerClock += DeltaTime
            local HeavyInterval = GetVisualHeavyEspInterval(Performance.PlayerCount)
            Performance.HeavyEspInterval = HeavyInterval
            if VisualState.PlayerClock >= HeavyInterval then
                VisualState.PlayerClock = VisualState.PlayerClock % HeavyInterval
                Internal.Call(Internal.UpdatePlayerESP)
            end
        else
            VisualState.PlayerClock = 0
        end

        if VisualState.Snapline.Enabled then
            VisualState.Snapline.Clock = 0
            Internal.Call(UpdateTargetSnapline)
        else
            VisualState.Snapline.Clock = 0
        end

        if VisualState.Player.Chams.Enabled then
            VisualState.ChamsClock += DeltaTime

            local ChamsInterval = Performance.PlayerCount >= 32 and 0.14
                or Performance.PlayerCount >= 24 and 0.12
                or Performance.PlayerCount >= 16 and 0.10
                or Performance.PlayerCount >= 10 and 0.075
                or 0.06

            if VisualState.ChamsClock >= ChamsInterval then
                VisualState.ChamsClock = VisualState.ChamsClock % ChamsInterval
                Internal.Call(UpdatePlayerChams, false)
            end
        else
            VisualState.ChamsClock = 0
            VisualState.ChamsCursor = 1
        end

        VisualState.WorldClock += DeltaTime
        if VisualState.WorldClock >= 0.50 then
            VisualState.WorldClock = 0
            if VisualState.WorldESP.Safes or VisualState.WorldESP.Cash then
                Internal.Call(UpdateWorldESP)
            elseif next(VisualState.WorldESP.Objects) then
                Internal.Call(ClearWorldESPLabels)
            end
        end
    end)
end

AtramentaRuntimeControl:AddConnection(LocalPlayer.CharacterAdded:Connect(function(Character)
    if SafeFarmRuntime and SafeFarmRuntime.RouteAtlas then
        local Atlas = SafeFarmRuntime.RouteAtlas
        Atlas.Generation = (tonumber(Atlas.Generation) or 0) + 1
        Atlas.Building = false
        Atlas.Ready = false
        Atlas.Status = "Respawn"
        Atlas.Nodes = {}
        Atlas.NodeBySafe = setmetatable({}, {__mode = "k"})
        Atlas.Edges = {}
        Atlas.Distances = {}
        Atlas.Next = {}
        SafeFarmRuntime.LastSafe = nil
        SafeFarmRuntime.LastGroundedCFrame = nil
        SafeFarmRuntime.LastGroundedAt = 0
        SafeFarmRuntime.VerticalPortalScanAt = 0
        SafeFarmRuntime.VerticalPortals = {}

        if SafeFarmEnabled then
            task.delay(1.5, function()
                if Character == LocalPlayer.Character and SafeFarmEnabled and type(SafeFarmEnsureRouteAtlas) == "function" then SafeFarmEnsureRouteAtlas() end
            end)
        end
    end

    VisualState.PlayerClock = 0
    VisualState.ChamsClock = 0
    VisualState.CacheClock = 0
    VisualState.WorldClock = 0
    VisualState.WorldESP.LastScan = 0

    ClearWorldESPLabels()

    task.defer(function()
        Internal.ReconcilePlayerVisualCache()
        if Character == LocalPlayer.Character then RefreshWorldESP(true) end
    end)

    task.delay(0.30, function()
        if Character == LocalPlayer.Character then RefreshWorldESP(true) end
    end)

    task.delay(0.90, function()
        if Character == LocalPlayer.Character then RefreshWorldESP(true) end
    end)
end))

AutoPickupCashController = {
    Runtime = {
        Enabled = false, Generation = 0, Character = nil, Humanoid = nil, Root = nil,
        Filter = nil, Folder = nil, Remote = nil, InFlight = nil, LastFolderScan = 0,
        Items = setmetatable({}, {__mode = "k"}), Connections = {}
    },
    MaximumDistance = 22,
    RetryDelay = 0.12,
    SuccessDelay = 0.04,
    IdleDelay = 0.03,
    RescanDelay = 0.12
}

function AutoPickupCashController.Disconnect(Name)
    local Runtime = AutoPickupCashController.Runtime local Connection = Runtime.Connections[Name]
    if Connection and Connection.Connected then Connection:Disconnect() end
    Runtime.Connections[Name] = nil
end

function AutoPickupCashController.DisconnectItem(State)
    if type(State) ~= "table" or type(State.Connections) ~= "table" then return end
    for Name, Connection in pairs(State.Connections) do
        if Connection and Connection.Connected then Connection:Disconnect() end
        State.Connections[Name] = nil
    end
end

function AutoPickupCashController.BindPrompt(State, Prompt)
    if type(State) ~= "table" or not Prompt or not Prompt:IsA("ProximityPrompt") then return end
    if State.Prompt == Prompt then return end
    local Existing = State.Connections.Triggered
    if Existing and Existing.Connected then Existing:Disconnect() end
    State.Prompt = Prompt
    State.Triggered = false
    State.Connections.Triggered = Prompt.Triggered:Connect(function(Player)
        if Player == nil or Player == LocalPlayer then State.Triggered = true end
    end)
end

function AutoPickupCashController.RefreshItem(State)
    if type(State) ~= "table" then return end
    local Item = State.Item
    if not Item or not Item.Parent then return end
    local Prompt = Item:FindFirstChildWhichIsA("ProximityPrompt", true)
    if Prompt then AutoPickupCashController.BindPrompt(State, Prompt) end
end

function AutoPickupCashController.AddItem(Item)
    local Runtime = AutoPickupCashController.Runtime
    if not Runtime.Folder or not Item or Item.Parent ~= Runtime.Folder or not Item:IsA("BasePart") then return end
    if Runtime.Items[Item] then
        AutoPickupCashController.RefreshItem(Runtime.Items[Item])
        return
    end
    local State = {Item = Item, Prompt = nil, RetryAt = 0, Triggered = false, InFlight = false, Connections = {}}
    Runtime.Items[Item] = State
    AutoPickupCashController.RefreshItem(State)
    State.Connections.DescendantAdded = Item.DescendantAdded:Connect(function(Descendant)
        if Descendant:IsA("ProximityPrompt") then AutoPickupCashController.BindPrompt(State, Descendant) end
    end)
    State.Connections.AncestryChanged = Item.AncestryChanged:Connect(function()
        if Item.Parent ~= Runtime.Folder then AutoPickupCashController.RemoveItem(Item) end
    end)
end

function AutoPickupCashController.RemoveItem(Item)
    local Runtime = AutoPickupCashController.Runtime local State = Item and Runtime.Items[Item]
    if not State then return end
    if Runtime.InFlight == Item then Runtime.InFlight = nil end
    AutoPickupCashController.DisconnectItem(State)
    Runtime.Items[Item] = nil
end

function AutoPickupCashController.RefreshFolderItems(Force)
    local Runtime = AutoPickupCashController.Runtime local Folder = Runtime.Folder
    if not Folder or not Folder.Parent then return end
    local CurrentTime = os.clock()
    if not Force and CurrentTime - Runtime.LastFolderScan < AutoPickupCashController.RescanDelay then return end
    Runtime.LastFolderScan = CurrentTime
    for _, Item in ipairs(Folder:GetChildren()) do
        if Item:IsA("BasePart") then AutoPickupCashController.AddItem(Item) end
    end
    for Item in pairs(Runtime.Items) do
        if not Item or Item.Parent ~= Folder then AutoPickupCashController.RemoveItem(Item) end
    end
end

function AutoPickupCashController.BindFolder(Folder)
    local Runtime = AutoPickupCashController.Runtime
    if Runtime.Folder == Folder then
        AutoPickupCashController.RefreshFolderItems(true)
        return
    end
    AutoPickupCashController.Disconnect("FolderAdded")
    AutoPickupCashController.Disconnect("FolderRemoved")
    for Item, State in pairs(Runtime.Items) do
        AutoPickupCashController.DisconnectItem(State)
        Runtime.Items[Item] = nil
    end
    Runtime.Folder = Folder
    Runtime.InFlight = nil
    Runtime.LastFolderScan = 0
    if not Folder then return end
    AutoPickupCashController.RefreshFolderItems(true)
    Runtime.Connections.FolderAdded = Folder.ChildAdded:Connect(function(Item)
        if Item:IsA("BasePart") then AutoPickupCashController.AddItem(Item) end
        task.defer(AutoPickupCashController.RefreshFolderItems, true)
    end)
    Runtime.Connections.FolderRemoved = Folder.ChildRemoved:Connect(function(Item)
        AutoPickupCashController.RemoveItem(Item)
    end)
end

function AutoPickupCashController.BindFilter(Filter)
    local Runtime = AutoPickupCashController.Runtime
    if Runtime.Filter == Filter then
        local Folder = Filter and Filter:FindFirstChild("SpawnedBread")
        if Runtime.Folder ~= Folder then AutoPickupCashController.BindFolder(Folder) end
        return
    end
    AutoPickupCashController.Disconnect("FilterAdded")
    AutoPickupCashController.Disconnect("FilterRemoved")
    Runtime.Filter = Filter
    if not Filter then
        AutoPickupCashController.BindFolder(nil)
        return
    end
    AutoPickupCashController.BindFolder(Filter:FindFirstChild("SpawnedBread"))
    Runtime.Connections.FilterAdded = Filter.ChildAdded:Connect(function(Object)
        if Object.Name == "SpawnedBread" then AutoPickupCashController.BindFolder(Object) end
    end)
    Runtime.Connections.FilterRemoved = Filter.ChildRemoved:Connect(function(Object)
        if Object == Runtime.Folder then AutoPickupCashController.BindFolder(nil) end
    end)
end

function AutoPickupCashController.BindCharacter(Character)
    local Runtime = AutoPickupCashController.Runtime
    AutoPickupCashController.Disconnect("CharacterChildAdded")
    AutoPickupCashController.Disconnect("CharacterChildRemoved")
    Runtime.Character = Character
    Runtime.Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") or nil
    Runtime.Root = Character and Character:FindFirstChild("HumanoidRootPart") or nil
    if not Character then return end
    Runtime.Connections.CharacterChildAdded = Character.ChildAdded:Connect(function(Object)
        if Object:IsA("Humanoid") then
            Runtime.Humanoid = Object
        elseif Object.Name == "HumanoidRootPart" and Object:IsA("BasePart") then
            Runtime.Root = Object
        end
    end)
    Runtime.Connections.CharacterChildRemoved = Character.ChildRemoved:Connect(function(Object)
        if Object == Runtime.Humanoid then Runtime.Humanoid = nil end
        if Object == Runtime.Root then Runtime.Root = nil end
    end)
end

function AutoPickupCashController.ResolveReferences()
    local Runtime = AutoPickupCashController.Runtime local Filter = workspace:FindFirstChild("Filter")
    if Runtime.Filter ~= Filter then AutoPickupCashController.BindFilter(Filter) end
    local Character = LocalPlayer.Character
    if Runtime.Character ~= Character then AutoPickupCashController.BindCharacter(Character) end
    local Events = ReplicatedStorage:FindFirstChild("Events") local Remote = Events and Events:FindFirstChild("CZDPZUS") or nil
    Runtime.Remote = Remote and Remote:IsA("RemoteEvent") and Remote or nil
    AutoPickupCashController.RefreshFolderItems(false)
end

function AutoPickupCashController.IsValid(State, CurrentTime)
    if type(State) ~= "table" or State.InFlight then return false end
    local Runtime = AutoPickupCashController.Runtime local Item = State.Item local Humanoid = Runtime.Humanoid local Root = Runtime.Root
    if not Item or Item.Parent ~= Runtime.Folder or not Item:IsA("BasePart") then return false end
    if Item.Transparency >= 1 then return false end
    if not Humanoid or Humanoid.Health <= 0 or not Root or not Root.Parent then return false end
    if CurrentTime < (State.RetryAt or 0) then return false end
    return (Item.Position - Root.Position).Magnitude <= AutoPickupCashController.MaximumDistance
end

function AutoPickupCashController.GetNearestState()
    local Runtime = AutoPickupCashController.Runtime local Root = Runtime.Root
    if not Root or not Root.Parent then return nil end
    local CurrentTime = os.clock() local RootPosition = Root.Position local BestState, BestDistanceSquared
    for Item, State in pairs(Runtime.Items) do
        if not Item or Item.Parent ~= Runtime.Folder then
            AutoPickupCashController.RemoveItem(Item)
        elseif AutoPickupCashController.IsValid(State, CurrentTime) then
            local Offset = Item.Position - RootPosition local DistanceSquared = Offset:Dot(Offset)
            if not BestDistanceSquared or DistanceSquared < BestDistanceSquared then
                BestState = State
                BestDistanceSquared = DistanceSquared
            end
        end
    end
    return BestState
end

function AutoPickupCashController.Attempt(State, Generation)
    local Runtime = AutoPickupCashController.Runtime
    if type(State) ~= "table" or Runtime.InFlight or not AutoPickupCashController.IsValid(State, os.clock()) then return false end
    local Item = State.Item
    Runtime.InFlight = Item
    State.InFlight = true
    State.Triggered = false
    local Sent = false local Remote = Runtime.Remote
    if Remote and Remote.Parent then
        Remote:FireServer(Item, nil)
        Sent = true
    end
    local FirstDeadline = os.clock() + 0.16
    while Runtime.Enabled and Runtime.Generation == Generation and os.clock() < FirstDeadline do
        if not Item.Parent or Item.Parent ~= Runtime.Folder then break end
        wait(0.015)
    end
    if Item.Parent == Runtime.Folder then
        AutoPickupCashController.RefreshItem(State)
        local Prompt = State.Prompt
        if Prompt and Prompt.Parent and Prompt.Enabled ~= false and type(fireproximityprompt) == "function" then
            fireproximityprompt(Prompt)
            Sent = true
        end
    end
    local Deadline = os.clock() + 0.24
    while Runtime.Enabled and Runtime.Generation == Generation and os.clock() < Deadline do
        if not Item.Parent or Item.Parent ~= Runtime.Folder or State.Triggered then break end
        wait(0.015)
    end
    local Success = not Item.Parent or Item.Parent ~= Runtime.Folder or State.Triggered
    State.InFlight = false
    if Runtime.InFlight == Item then Runtime.InFlight = nil end
    if Success then
        wait(AutoPickupCashController.SuccessDelay)
    elseif Item.Parent == Runtime.Folder then
        State.RetryAt = os.clock() + (Sent and AutoPickupCashController.RetryDelay or 0.25)
    end
    return Success
end

function AutoPickupCashController.Run(Generation)
    local Runtime = AutoPickupCashController.Runtime
    while Runtime.Enabled and Runtime.Generation == Generation do
        AutoPickupCashController.ResolveReferences()
        local State = AutoPickupCashController.GetNearestState()
        if State then
            AutoPickupCashController.Attempt(State, Generation)
        else
            wait(AutoPickupCashController.IdleDelay)
        end
    end
end

function AutoPickupCashController.CollectFor(Duration)
    local Runtime = AutoPickupCashController.Runtime local Deadline = os.clock() + math.max(tonumber(Duration) or 0, 0)
    while Runtime.Enabled and os.clock() < Deadline do
        AutoPickupCashController.ResolveReferences()
        AutoPickupCashController.RefreshFolderItems(true)
        if Runtime.InFlight == nil and AutoPickupCashController.GetNearestState() == nil then break end
        wait(0.04)
    end
end

function AutoPickupCashController.SetEnabled(Enabled)
    local Runtime = AutoPickupCashController.Runtime
    Enabled = Enabled == true
    if Runtime.Enabled == Enabled then return end
    Runtime.Enabled = Enabled
    AutoPickupMoneyEnabled = Enabled
    Runtime.Generation += 1
    if not Enabled then
        for Name in pairs(Runtime.Connections) do AutoPickupCashController.Disconnect(Name) end
        for Item, ItemState in pairs(Runtime.Items) do
            AutoPickupCashController.DisconnectItem(ItemState)
            Runtime.Items[Item] = nil
        end
        Runtime.Character = nil
        Runtime.Humanoid = nil
        Runtime.Root = nil
        Runtime.Filter = nil
        Runtime.Folder = nil
        Runtime.Remote = nil
        Runtime.InFlight = nil
        Runtime.LastFolderScan = 0
        return
    end
    AutoPickupCashController.ResolveReferences()
    Runtime.Connections.CharacterAdded = LocalPlayer.CharacterAdded:Connect(function(Character)
        AutoPickupCashController.BindCharacter(Character)
    end)
    Runtime.Connections.CharacterRemoving = LocalPlayer.CharacterRemoving:Connect(function(Character)
        if Character == Runtime.Character then AutoPickupCashController.BindCharacter(nil) end
    end)
    Runtime.Connections.WorkspaceAdded = workspace.ChildAdded:Connect(function(Object)
        if Object.Name == "Filter" then AutoPickupCashController.BindFilter(Object) end
    end)
    Runtime.Connections.WorkspaceRemoved = workspace.ChildRemoved:Connect(function(Object)
        if Object == Runtime.Filter then AutoPickupCashController.BindFilter(nil) end
    end)
    local Generation = Runtime.Generation
    task.spawn(AutoPickupCashController.Run, Generation)
end

function AutoPickupMoneyEnable()
    AutoPickupCashController.SetEnabled(true)
end

function AutoPickupMoneyDisable()
    AutoPickupCashController.SetEnabled(false)
end

function FastPickupBindPrompt(PromptObject)
    if not PromptObject or not PromptObject:IsA("ProximityPrompt") then return end

    local Existing = FastPickupPromptConnections[PromptObject]
    if Existing and Existing.Connected then
        if FastPickupRuntimeState.Enabled and PromptObject.HoldDuration ~= 0 then PromptObject.HoldDuration = 0 end
        return
    end

    if Existing then FastPickupPromptConnections[PromptObject] = nil end
    if FastPickupRuntimeState.Enabled and PromptObject.HoldDuration ~= 0 then PromptObject.HoldDuration = 0 end

    FastPickupPromptConnections[PromptObject] = PromptObject:GetPropertyChangedSignal("HoldDuration"):Connect(function()
        if not FastPickupRuntimeState.Enabled or not PromptObject.Parent then return end
        if PromptObject.HoldDuration ~= 0 then PromptObject.HoldDuration = 0 end
    end)
end

function FastPickupEnable()
    if FastPickupRuntimeState.Enabled then return end
    FastPickupRuntimeState.Enabled = true
    FastPickupEnabled = false

    for PromptObject, Connection in pairs(FastPickupPromptConnections) do
        if not PromptObject or not PromptObject.Parent or not Connection or not Connection.Connected then
            if Connection and Connection.Connected then Connection:Disconnect() end
            FastPickupPromptConnections[PromptObject] = nil
        end
    end

    for _, PromptObject in ipairs(workspace:GetDescendants()) do
        if PromptObject:IsA("ProximityPrompt") then FastPickupBindPrompt(PromptObject) end
    end

    if FastPickupConnection then FastPickupConnection:Disconnect() end
    FastPickupConnection = game.DescendantAdded:Connect(function(AddedDescendant)
        if FastPickupRuntimeState.Enabled and AddedDescendant:IsA("ProximityPrompt") then FastPickupBindPrompt(AddedDescendant) end
    end)
end

function FastPickupDisable()
    FastPickupRuntimeState.Enabled = false
    FastPickupEnabled = false

    if FastPickupConnection then
        FastPickupConnection:Disconnect()
        FastPickupConnection = nil
    end

    for PromptObject, Connection in pairs(FastPickupPromptConnections) do
        if Connection and Connection.Connected then Connection:Disconnect() end
        FastPickupPromptConnections[PromptObject] = nil
    end
end

function NoFailLockpickEnable()
    if NoFailLockpickEnabled then return end
    NoFailLockpickEnabled = true
    LockpickAddedConnection = PlayerGui.ChildAdded:Connect(function(ItemObject)
        if ItemObject.Name == "LockpickGUI" then
            Internal.Call(function()
                local MainFrame = ItemObject:WaitForChild("MF", 10) if not MainFrame then return end
                local LockpickFrame = MainFrame:WaitForChild("LP_Frame", 10) if not LockpickFrame then return end
                local FramesFolder = LockpickFrame:WaitForChild("Frames", 10) if not FramesFolder then return end
                for Unused, ButtonName in ipairs({ "B1", "B2", "B3" }) do
                    local ButtonItem = FramesFolder:FindFirstChild(ButtonName)
                    if ButtonItem and ButtonItem:FindFirstChild("Bar") and ButtonItem.Bar:FindFirstChild("UIScale") then ButtonItem.Bar.UIScale.Scale = 10 end
                end
            end)
        end
    end)
end

function NoFailLockpickDisable()
    if not NoFailLockpickEnabled then return end
    NoFailLockpickEnabled = false
    if LockpickAddedConnection then
        LockpickAddedConnection:Disconnect()
        LockpickAddedConnection = nil
    end
    Internal.Call(function()
        local LockpickGUI = PlayerGui:FindFirstChild("LockpickGUI") if not LockpickGUI then return end
        local MainFrame = LockpickGUI:FindFirstChild("MF") if not MainFrame then return end
        local LockpickFrame = MainFrame:FindFirstChild("LP_Frame") if not LockpickFrame then return end
        local FramesFolder = LockpickFrame:FindFirstChild("Frames") if not FramesFolder then return end
        for Unused, ButtonName in ipairs({ "B1", "B2", "B3" }) do
            local ButtonItem = FramesFolder:FindFirstChild(ButtonName)
            if ButtonItem and ButtonItem:FindFirstChild("Bar") and ButtonItem.Bar:FindFirstChild("UIScale") then ButtonItem.Bar.UIScale.Scale = 1 end
        end
    end)
end

function NearbyDoorInteractionLoop()
    while OpenNearbyDoorsEnabled or UnlockNearbyDoorsEnabled do
        local CharacterModel = LocalPlayer.Character local RootPart = CharacterModel and CharacterModel:FindFirstChild("HumanoidRootPart")
        local HumanoidInstance = CharacterModel and CharacterModel:FindFirstChildOfClass("Humanoid")
        if RootPart and HumanoidInstance and HumanoidInstance.Health > 0 then
            local DoorsFolder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Doors")
            if DoorsFolder then
                for Unused, DoorInstance in ipairs(DoorsFolder:GetChildren()) do
                    local DoorBase = DoorInstance:FindFirstChild("DoorBase") local ValuesFolder = DoorInstance:FindFirstChild("Values")
                    local EventsFolder = DoorInstance:FindFirstChild("Events")
                    if DoorBase and ValuesFolder and EventsFolder then
                        if(RootPart.Position - DoorBase.Position).Magnitude <= 6 then
                            local ToggleEvent = EventsFolder:FindFirstChild("Toggle")
                            if not ToggleEvent then continue end
                            if UnlockNearbyDoorsEnabled then
                                local LockedValue = ValuesFolder:FindFirstChild("Locked") local LockArg = DoorInstance:FindFirstChild("Lock")
                                if LockedValue and LockArg and LockedValue.Value == true then ToggleEvent:FireServer("Unlock", LockArg) end
                            end
                            if OpenNearbyDoorsEnabled then
                                local OpenValue = ValuesFolder:FindFirstChild("Open")
                                local KnobArg = DoorInstance:FindFirstChild("Knob2") or DoorInstance:FindFirstChild("Knob")
                                if OpenValue and KnobArg and OpenValue.Value == false then
                                    local IsLocked = ValuesFolder:FindFirstChild("Locked")
                                    if not IsLocked or IsLocked.Value == false then ToggleEvent:FireServer("Open", KnobArg) end
                                end
                            end
                        end
                    end
                end
            end
        end
        task.wait(math.random(30, 50) / 100)
    end
    NearbyDoorInteractionCoroutine = nil
end

function StartStopDoorLoop()
    if(OpenNearbyDoorsEnabled or UnlockNearbyDoorsEnabled) and not NearbyDoorInteractionCoroutine then NearbyDoorInteractionCoroutine = task.spawn(NearbyDoorInteractionLoop) end
end

function OpenNearbyDoorsEnable()
    if OpenNearbyDoorsEnabled then return end
    OpenNearbyDoorsEnabled = true
    StartStopDoorLoop()
end

function OpenNearbyDoorsDisable()
    if not OpenNearbyDoorsEnabled then return end
    OpenNearbyDoorsEnabled = false
end

function UnlockNearbyDoorsEnable()
    if UnlockNearbyDoorsEnabled then return end
    UnlockNearbyDoorsEnabled = true
    StartStopDoorLoop()
end

function UnlockNearbyDoorsDisable()
    if not UnlockNearbyDoorsEnabled then return end
    UnlockNearbyDoorsEnabled = false
end

function GetMovementAssistInput(HumanoidObject)
    local CameraObject = Internal.GetCamera()
    if not CameraObject then return Vector3.new(), Vector3.new(), Vector3.new(), 0, 0 end

    local Forward = Vector3.new(CameraObject.CFrame.LookVector.X, 0, CameraObject.CFrame.LookVector.Z)
    local Right = Vector3.new(CameraObject.CFrame.RightVector.X, 0, CameraObject.CFrame.RightVector.Z)
    if Forward.Magnitude > 0.001 then Forward = Forward.Unit end
    if Right.Magnitude > 0.001 then Right = Right.Unit end

    local ForwardMove = 0 local SideMove = 0
    if UserInputService:IsKeyDown(Enum.KeyCode.W) then ForwardMove = ForwardMove + 1 end
    if UserInputService:IsKeyDown(Enum.KeyCode.S) then ForwardMove = ForwardMove - 1 end
    if UserInputService:IsKeyDown(Enum.KeyCode.D) then SideMove = SideMove + 1 end
    if UserInputService:IsKeyDown(Enum.KeyCode.A) then SideMove = SideMove - 1 end

    local Direction = Forward * ForwardMove + Right * SideMove
    if Direction.Magnitude <= 0.001 and HumanoidObject then
        local MoveDirection = HumanoidObject.MoveDirection
        if typeof(MoveDirection) == "Vector3" then Direction = Vector3.new(MoveDirection.X, 0, MoveDirection.Z) end
    end

    return Direction.Magnitude > 0.001 and Direction.Unit or Vector3.new(), Forward, Right, ForwardMove, SideMove
end

function IsMovementAssistGrounded(HumanoidObject)
    if not HumanoidObject or HumanoidObject.FloorMaterial == Enum.Material.Air then return false end
    local State = HumanoidObject:GetState()
    return State ~= Enum.HumanoidStateType.Freefall and State ~= Enum.HumanoidStateType.Jumping and State ~= Enum.HumanoidStateType.FallingDown
end

function RefreshPixelSurfRayParams(CharacterObject)
    local Compact = {}
    local Characters = workspace:FindFirstChild("Characters") local DebrisFolder = workspace:FindFirstChild("Debris")

    if CharacterObject then Compact[#Compact + 1] = CharacterObject end
    if Characters then Compact[#Compact + 1] = Characters end
    if DebrisFolder then Compact[#Compact + 1] = DebrisFolder end

    PixelSurfRayParams.FilterDescendantsInstances = Compact
    return PixelSurfRayParams
end

function GetPixelSurfFootPosition(CharacterObject, RootPart, HumanoidObject)
    if not CharacterObject or not RootPart then return nil end

    local Samples = {}
    local Names = {"LeftFoot", "RightFoot", "Left Leg", "Right Leg", "LeftLowerLeg", "RightLowerLeg"}

    for Index = 1, #Names do
        local Part = CharacterObject:FindFirstChild(Names[Index])

        if Part and Part:IsA("BasePart") then
            local Offset = Part.Position - RootPart.Position

            if Offset.Magnitude <= 6.25 and math.abs(Offset.X) <= 3.6 and math.abs(Offset.Z) <= 3.6 then
                Samples[#Samples + 1] = { X = Part.Position.X, Z = Part.Position.Z, Bottom = Part.Position.Y - Part.Size.Y * 0.5 }
            end
        end
    end

    if #Samples > 0 then
        table.sort(Samples, function(A, B) return A.Bottom < B.Bottom end)

        local Lowest = Samples[1].Bottom local SumX = 0 local SumZ = 0 local Count = 0

        for Index = 1, #Samples do
            local Sample = Samples[Index]

            if Sample.Bottom <= Lowest + 0.42 then
                SumX += Sample.X
                SumZ += Sample.Z
                Count += 1
            end
        end

        if Count > 0 then return Vector3.new(SumX / Count, Lowest + 0.09, SumZ / Count) end
    end

    local HipHeight = tonumber(HumanoidObject and HumanoidObject.HipHeight) or 0 local RootHalf = RootPart.Size.Y * 0.5
    local Offset = math.clamp(HipHeight + RootHalf + 0.84, 1.80, 3.20)

    return Vector3.new(RootPart.Position.X, RootPart.Position.Y - Offset, RootPart.Position.Z)
end

function GetPixelSurfWish(InputDirection, Horizontal)
    local Wish = typeof(InputDirection) == "Vector3" and Vector3.new(InputDirection.X, 0, InputDirection.Z) or Vector3.zero

    if Wish.Magnitude <= 0.001 and typeof(Horizontal) == "Vector3" then Wish = Vector3.new(Horizontal.X, 0, Horizontal.Z) end

    return Wish.Magnitude > 0.001 and Wish.Unit or Vector3.zero
end

function GetPixelSurfMedian(Values)
    local Count = #Values
    if Count == 0 then return nil end

    table.sort(Values)

    if Count % 2 == 1 then return Values[(Count + 1) // 2] end

    return (Values[Count // 2] + Values[Count // 2 + 1]) * 0.5
end

function GetPixelSurfSideContact(FootPosition, SupportHeight, Inward, Params)
    if typeof(FootPosition) ~= "Vector3" or typeof(Inward) ~= "Vector3" or Inward.Magnitude <= 0.001 then return nil end

    local HorizontalInward = Vector3.new(Inward.X, 0, Inward.Z)
    if HorizontalInward.Magnitude <= 0.001 then return nil end
    HorizontalInward = HorizontalInward.Unit

    local Distance = math.clamp(tonumber(MovementAssistSettings.PixelSurfSideProbeDistance) or 2.15, 1.20, 3.0)
    local Heights = {0.10, 0.34, 0.62}
    local Best

    for Index = 1, #Heights do
        local Origin = Vector3.new(FootPosition.X, SupportHeight + Heights[Index], FootPosition.Z) - HorizontalInward * 0.14
        local Result = workspace:Raycast(Origin, HorizontalInward * Distance, Params)

        if Result and Result.Instance and Result.Instance:IsA("BasePart") and Result.Instance.CanCollide == true then
            local HorizontalNormal = Vector3.new(Result.Normal.X, 0, Result.Normal.Z)

            if HorizontalNormal.Magnitude >= 0.35 then
                local Candidate = { Result = Result, Normal = HorizontalNormal.Unit, Distance = Result.Distance }

                if not Best or Candidate.Distance < Best.Distance then Best = Candidate end
            end
        end
    end

    return Best
end

function ScanPixelSurfRing(FootPosition, Radius, SampleCount, ProbeDepth, Phase, Params)
    local Supports = table.create(SampleCount)
    local Drops = {}
    local WeightedDirection = Vector3.zero local WeightedNormal = Vector3.zero local WeightedPosition = Vector3.zero local WeightSum = 0
    local SupportCount = 0 local BestSupport local BestDrop = math.huge local MinimumNormalY = 0.60
    local MaximumDrop = math.clamp(tonumber(MovementAssistSettings.PixelSurfMaximumDrop) or 0.94, 0.30, 1.30) local OriginLift = 0.13

    for Index = 1, SampleCount do
        local Angle = ((Index - 1) / SampleCount) * math.pi * 2 + Phase local Direction = Vector3.new(math.cos(Angle), 0, math.sin(Angle))
        local Origin = FootPosition + Direction * Radius + Vector3.new(0, OriginLift, 0)
        local Result = workspace:Raycast(Origin, Vector3.new(0, -(ProbeDepth + OriginLift), 0), Params) local Support

        if Result and Result.Instance and Result.Instance:IsA("BasePart") and Result.Instance.CanCollide == true
            and Result.Normal.Y >= MinimumNormalY
        then
            local Drop = FootPosition.Y - Result.Position.Y

            if Drop >= -0.10 and Drop <= MaximumDrop then
                local HeightQuality = 1 - math.clamp(math.abs(Drop - 0.07) / math.max(MaximumDrop, 0.10), 0, 0.92)
                local NormalQuality = math.clamp((Result.Normal.Y - MinimumNormalY) / (1 - MinimumNormalY), 0, 1) local Weight = 0.30 + HeightQuality * 0.52 + NormalQuality * 0.18

                Support = { Direction = Direction, Position = Result.Position, Normal = Result.Normal, Part = Result.Instance, Drop = Drop, Weight = Weight }

                SupportCount += 1
                Drops[#Drops + 1] = Drop
                WeightedDirection += Direction * Weight
                WeightedNormal += Result.Normal * Weight
                WeightedPosition += Result.Position * Weight
                WeightSum += Weight

                if Drop < BestDrop then
                    BestDrop = Drop
                    BestSupport = Support
                end
            end
        end

        Supports[Index] = Support
    end

    local Transitions = 0

    if SampleCount > 1 then
        for Index = 1, SampleCount do
            local NextIndex = Index == SampleCount and 1 or Index + 1 local A = Supports[Index] ~= nil local B = Supports[NextIndex] ~= nil

            if A ~= B then Transitions += 1 end
        end
    end

    return {
        Supports = Supports,
        SupportCount = SupportCount,
        Fraction = SupportCount / SampleCount,
        Drops = Drops,
        Direction = WeightSum > 0 and WeightedDirection / WeightSum or Vector3.zero,
        Normal = WeightSum > 0 and WeightedNormal / WeightSum or Vector3.new(0, 1, 0),
        Position = WeightSum > 0 and WeightedPosition / WeightSum or FootPosition,
        Weight = WeightSum,
        Best = BestSupport,
        Transitions = Transitions
    }
end

function BuildPixelSurfCandidate(CharacterObject, HumanoidObject, RootPart, InputDirection, FootPosition, Velocity, Phase)
    local Params = RefreshPixelSurfRayParams(CharacterObject) local Horizontal = Vector3.new(Velocity.X, 0, Velocity.Z)
    local Wish = GetPixelSurfWish(InputDirection, Horizontal) local RootRadius = math.max(math.min(RootPart.Size.X, RootPart.Size.Z) * 0.5, 0.70)
    local RadiusScale = math.clamp(tonumber(MovementAssistSettings.PixelSurfProbeRadiusScale) or 1.03, 0.82, 1.30) local OuterRadius = math.clamp(RootRadius * RadiusScale, 0.78, 1.55)
    local InnerScale = math.clamp(tonumber(MovementAssistSettings.PixelSurfInnerRadiusScale) or 0.56, 0.35, 0.78)
    local ProbeDepth = math.clamp(tonumber(MovementAssistSettings.PixelSurfProbeDepth) or 1.02, 0.55, 1.40)
    local OuterSamples = math.clamp(math.floor(tonumber(MovementAssistSettings.PixelSurfOuterSamples) or 16), 10, 24)
    local InnerSamples = math.clamp(math.floor(tonumber(MovementAssistSettings.PixelSurfInnerSamples) or 10), 6, 16)

    local Outer = ScanPixelSurfRing(FootPosition, OuterRadius, OuterSamples, ProbeDepth, Phase, Params)
    local Inner = ScanPixelSurfRing(FootPosition, OuterRadius * InnerScale, InnerSamples, ProbeDepth, Phase * 0.63, Params)

    if Outer.SupportCount == 0 or not Outer.Best then return nil end
    if Outer.Fraction >= 0.84 and Inner.Fraction >= 0.82 then return nil end
    if Outer.Fraction <= 0.06 and Inner.Fraction <= 0.08 then return nil end
    if Outer.Direction.Magnitude <= 0.035 then return nil end

    local Drops = {}

    for Index = 1, #Outer.Drops do Drops[#Drops + 1] = Outer.Drops[Index] end
    for Index = 1, #Inner.Drops do Drops[#Drops + 1] = Inner.Drops[Index] end

    local MedianDrop = GetPixelSurfMedian(Drops)
    if not MedianDrop then return nil end

    local Inward = Vector3.new(Outer.Direction.X, 0, Outer.Direction.Z)
    if Inward.Magnitude <= 0.001 then return nil end
    Inward = Inward.Unit

    local SupportHeight = Outer.Position.Y local Side = GetPixelSurfSideContact(FootPosition, SupportHeight, Inward, Params)

    if Side then
        local SideInward = -Side.Normal local Blend = Inward:Lerp(SideInward, 0.58)

        if Blend.Magnitude > 0.001 then Inward = Blend.Unit end
    end

    local Tangent = Vector3.new(-Inward.Z, 0, Inward.X)
    if Tangent.Magnitude <= 0.001 then return nil end
    Tangent = Tangent.Unit

    local Reference = Wish.Magnitude > 0.001 and Wish or Horizontal.Magnitude > 0.001 and Horizontal.Unit or Tangent

    if Tangent:Dot(Reference) < 0 then Tangent = -Tangent end

    local TargetCoverage = math.clamp(tonumber(MovementAssistSettings.PixelSurfTargetCoverage) or 0.46, 0.25, 0.68) local CoverageError = TargetCoverage - Outer.Fraction
    local BalanceQuality = 1 - math.clamp(math.abs(CoverageError) / math.max(TargetCoverage, 0.15), 0, 1) local TransitionQuality = Outer.Transitions == 2 and 1
        or Outer.Transitions == 4 and 0.72
        or Outer.Transitions == 0 and 0.18
        or math.clamp(1 - math.abs(Outer.Transitions - 2) * 0.13, 0.18, 0.70)
    local RingDifference = math.abs(Inner.Fraction - Outer.Fraction) local RingQuality = math.clamp(1 - RingDifference * 1.45, 0, 1)
    local SideQuality = Side and math.clamp(1 - Side.Distance / math.max((tonumber(MovementAssistSettings.PixelSurfSideProbeDistance) or 2.15), 0.1), 0.20, 1) or 0
    local TangentQuality = math.abs(Tangent:Dot(Reference)) local PartStability = Outer.Best.Part == MovementAssistSettings.PixelSurfLastPart and 1 or 0
    local PreviousTangent = MovementAssistSettings.PixelSurfLastTangent local PreviousInward = MovementAssistSettings.PixelSurfLastInward local TemporalQuality = 0

    if typeof(PreviousTangent) == "Vector3" and PreviousTangent.Magnitude > 0.001 then TemporalQuality += math.abs(Tangent:Dot(PreviousTangent.Unit)) * 0.55 end

    if typeof(PreviousInward) == "Vector3" and PreviousInward.Magnitude > 0.001 then TemporalQuality += math.max(Inward:Dot(PreviousInward.Unit), 0) * 0.45 end

    local Confidence = BalanceQuality * 0.23
        + TransitionQuality * 0.18
        + RingQuality * 0.12
        + TangentQuality * 0.16
        + SideQuality * 0.13
        + TemporalQuality * 0.12
        + PartStability * 0.06

    if Inner.Fraction > Outer.Fraction + 0.34 then Confidence *= 0.82 end
    if MedianDrop > 0.62 then Confidence *= 0.84 end

    return {
        Tangent = Tangent,
        Inward = Inward,
        Position = Outer.Best.Position,
        Normal = Outer.Normal.Magnitude > 0.001 and Outer.Normal.Unit or Outer.Best.Normal,
        Part = Outer.Best.Part,
        Drop = math.max(MedianDrop, 0),
        Coverage = Outer.Fraction,
        InnerCoverage = Inner.Fraction,
        CoverageError = CoverageError,
        Confidence = math.clamp(Confidence, 0, 1),
        Transitions = Outer.Transitions,
        SideContact = Side ~= nil,
        SideDistance = Side and Side.Distance or nil,
        FootPosition = FootPosition,
        ProbeRadius = OuterRadius
    }
end

function GetPixelSurfCandidate(CharacterObject, HumanoidObject, RootPart, InputDirection, Velocity, SubtickDelta)
    if not CharacterObject or not HumanoidObject or not RootPart then return nil end

    local Foot = GetPixelSurfFootPosition(CharacterObject, RootPart, HumanoidObject)
    if not Foot then return nil end

    Velocity = typeof(Velocity) == "Vector3" and Velocity or RootPart.AssemblyLinearVelocity
    local Horizontal = Vector3.new(Velocity.X, 0, Velocity.Z) local Step = math.max(tonumber(SubtickDelta) or 1 / 240, 1 / 360)
    local Speed = Horizontal.Magnitude local AdaptiveLead = math.clamp(Speed * Step / 18, 0, 1)
    local Horizons = {0, Step * (0.70 + AdaptiveLead * 0.45), Step * (1.65 + AdaptiveLead * 0.70)}
    local BasePhase = (tonumber(MovementAssistSettings.PixelSurfPhase) or 0) * 0.38196601125 local Best

    for Index = 1, #Horizons do
        local Horizon = Horizons[Index] local PredictedFoot = Foot + Horizontal * Horizon local Candidate = BuildPixelSurfCandidate(
            CharacterObject, HumanoidObject, RootPart, InputDirection, PredictedFoot, Velocity,
            BasePhase + (Index - 1) * 0.17320508075
        )

        if Candidate then
            local HorizonPenalty = Index == 1 and 0 or (Index - 1) * 0.025 local Score = Candidate.Confidence - HorizonPenalty

            if not Best or Score > Best.Score then
                Candidate.Score = Score
                Candidate.Horizon = Horizon
                Best = Candidate
            end
        end
    end

    MovementAssistSettings.PixelSurfPhase = (tonumber(MovementAssistSettings.PixelSurfPhase) or 0) + 1
    return Best
end

function DestroyPixelSurfHold()
    local Force = MovementAssistSettings.PixelSurfHoldForce local Attachment = MovementAssistSettings.PixelSurfHoldAttachment

    if Force then Force:Destroy() end
    if Attachment then Attachment:Destroy() end

    MovementAssistSettings.PixelSurfHoldForce = nil
    MovementAssistSettings.PixelSurfHoldAttachment = nil
    MovementAssistSettings.PixelSurfHoldRoot = nil
end

function EnsurePixelSurfHold(RootPart)
    if not RootPart or not RootPart:IsA("BasePart") then
        DestroyPixelSurfHold()
        return nil
    end

    local ExistingRoot = MovementAssistSettings.PixelSurfHoldRoot local Force = MovementAssistSettings.PixelSurfHoldForce
    local Attachment = MovementAssistSettings.PixelSurfHoldAttachment

    if ExistingRoot ~= RootPart or not Force or not Force.Parent or not Attachment or not Attachment.Parent then
        DestroyPixelSurfHold()

        Attachment = Instance.new("Attachment")
        Attachment.Name = "AtramentaPixelSurfHold"
        Attachment.Parent = RootPart

        Force = Instance.new("VectorForce")
        Force.Name = "AtramentaPixelSurfForce"
        Force.Attachment0 = Attachment
        Force.RelativeTo = Enum.ActuatorRelativeTo.World
        Force.ApplyAtCenterOfMass = true
        Force.Force = Vector3.zero
        Force.Parent = RootPart

        MovementAssistSettings.PixelSurfHoldAttachment = Attachment
        MovementAssistSettings.PixelSurfHoldForce = Force
        MovementAssistSettings.PixelSurfHoldRoot = RootPart
    end

    return Force
end

function UpdatePixelSurfGravityHold(RootPart, HeightError, VelocityY)
    local Force = EnsurePixelSurfHold(RootPart) if not Force then return end

    local Mass = math.max(tonumber(RootPart.AssemblyMass) or 0, 0.01) local VerticalVelocity = tonumber(VelocityY)

    if not VerticalVelocity then VerticalVelocity = RootPart.AssemblyLinearVelocity.Y end

    local Kp = math.clamp(tonumber(MovementAssistSettings.PixelSurfHoldKp) or 108, 25, 150) local Kd = math.clamp(tonumber(MovementAssistSettings.PixelSurfHoldKd) or 27, 8, 42)
    local MaximumAcceleration = math.clamp(tonumber(MovementAssistSettings.PixelSurfMaximumVerticalAcceleration) or 84, 30, 110)
    local Error = math.clamp(tonumber(HeightError) or 0, -0.70, 0.70) local Correction = math.clamp(-Error * Kp - VerticalVelocity * Kd, -MaximumAcceleration, MaximumAcceleration)
    local RiskSpeed = math.max(tonumber(MovementAssistSettings.PixelSurfRiskVerticalSpeed) or 2.35, 0.5)

    if math.abs(VerticalVelocity) > RiskSpeed then Correction *= math.clamp(RiskSpeed / math.abs(VerticalVelocity), 0.24, 1) end

    Force.Force = Vector3.new(0, Mass * ((tonumber(workspace.Gravity) or 196.2) + Correction), 0)
end

function ResetPixelSurfSubtickEngine()
    MovementAssistSettings.PixelSurfSubtickAccumulator = 0
    MovementAssistSettings.PixelSurfSubtickIndex = 0
    MovementAssistSettings.PixelSurfScanAccumulator = 0
    MovementAssistSettings.PixelSurfCachedCandidate = nil
    MovementAssistSettings.PixelSurfCachedCandidateAt = 0
end

function RunPixelSurfSubticks(DeltaTime, Callback)
    local Rate = math.clamp(tonumber(MovementAssistSettings.PixelSurfSubtickRate) or 240, 120, 360) local Step = 1 / Rate
    local MaximumSubticks = math.clamp(math.floor(tonumber(MovementAssistSettings.PixelSurfMaximumSubticks) or 5), 2, 8) local FrameDelta = math.clamp(tonumber(DeltaTime) or 0, 0, 0.05)
    local Accumulator = math.min(
        (tonumber(MovementAssistSettings.PixelSurfSubtickAccumulator) or 0) + FrameDelta,
        Step * MaximumSubticks * 1.75
    )

    local Count = math.min(math.floor(Accumulator / Step), MaximumSubticks)

    if Count <= 0 then
        MovementAssistSettings.PixelSurfSubtickAccumulator = Accumulator
        return 0, Step
    end

    for Index = 1, Count do
        MovementAssistSettings.PixelSurfSubtickIndex = (tonumber(MovementAssistSettings.PixelSurfSubtickIndex) or 0) + 1
        Callback(Step, MovementAssistSettings.PixelSurfSubtickIndex, Index, Count)
        Accumulator -= Step
    end

    if Accumulator >= Step * MaximumSubticks then Accumulator %= Step end

    MovementAssistSettings.PixelSurfSubtickAccumulator = math.max(Accumulator, 0)
    return Count, Step
end

function ResolvePixelSurfCandidate(CharacterObject, HumanoidObject, RootPart, InputDirection, Velocity, SubtickDelta, CurrentTime)
    MovementAssistSettings.PixelSurfScanAccumulator =
        (tonumber(MovementAssistSettings.PixelSurfScanAccumulator) or 0) + SubtickDelta

    local ScanInterval = math.clamp(tonumber(MovementAssistSettings.PixelSurfScanInterval) or 1 / 120, 1 / 180, 1 / 60)
    local Cached = MovementAssistSettings.PixelSurfCachedCandidate local CachedAt = tonumber(MovementAssistSettings.PixelSurfCachedCandidateAt) or 0

    if MovementAssistSettings.PixelSurfScanAccumulator >= ScanInterval or not Cached then
        MovementAssistSettings.PixelSurfScanAccumulator %= ScanInterval
        Cached = GetPixelSurfCandidate(CharacterObject, HumanoidObject, RootPart, InputDirection, Velocity, SubtickDelta)
        MovementAssistSettings.PixelSurfCachedCandidate = Cached
        MovementAssistSettings.PixelSurfCachedCandidateAt = CurrentTime
        CachedAt = CurrentTime
    end

    if Cached and CurrentTime - CachedAt <= math.max(ScanInterval * 2.5, 0.035) then return Cached end

    return nil
end

function AcceptPixelSurfCandidate(Candidate, CurrentTime, SubtickDelta)
    if not Candidate then return nil end

    local MinimumConfidence = math.clamp(tonumber(MovementAssistSettings.PixelSurfMinimumConfidence) or 0.42, 0.20, 0.75)
    local Active = MovementAssistSettings.PixelSurfActive == true local SamePart = Candidate.Part == MovementAssistSettings.PixelSurfLastPart
    local RequiredConfidence = Active and SamePart and MinimumConfidence * 0.72 or MinimumConfidence

    if Candidate.Confidence < RequiredConfidence then return nil end

    local Tangent = Candidate.Tangent local Inward = Candidate.Inward
    local PreviousTangent = MovementAssistSettings.PixelSurfLastTangent local PreviousInward = MovementAssistSettings.PixelSurfLastInward
    local TangentRate = SamePart and 20 or 30 local InwardRate = SamePart and 17 or 26
    local TangentAlpha = 1 - math.exp(-TangentRate * SubtickDelta) local InwardAlpha = 1 - math.exp(-InwardRate * SubtickDelta)

    if Active and typeof(PreviousTangent) == "Vector3" and PreviousTangent.Magnitude > 0.001 then
        if Tangent:Dot(PreviousTangent.Unit) < 0 then Tangent = -Tangent end

        local Blend = PreviousTangent.Unit:Lerp(Tangent, TangentAlpha)
        if Blend.Magnitude > 0.001 then Tangent = Blend.Unit end
    end

    if Active and typeof(PreviousInward) == "Vector3" and PreviousInward.Magnitude > 0.001 then
        local Blend = PreviousInward.Unit:Lerp(Inward, InwardAlpha)
        if Blend.Magnitude > 0.001 then Inward = Blend.Unit end
    end

    Candidate.Tangent = Tangent
    Candidate.Inward = Inward
    MovementAssistSettings.PixelSurfLastContact = CurrentTime
    MovementAssistSettings.PixelSurfLastTangent = Tangent
    MovementAssistSettings.PixelSurfLastInward = Inward
    MovementAssistSettings.PixelSurfLastPart = Candidate.Part
    MovementAssistSettings.PixelSurfLastPoint = Candidate.Position
    MovementAssistSettings.PixelSurfConfidence = Candidate.Confidence
    MovementAssistSettings.PixelSurfLastCoverage = Candidate.Coverage
    MovementAssistSettings.PixelSurfLastDrop = Candidate.Drop

    return Candidate
end

function GetPixelSurfFallbackCandidate(CurrentTime)
    if MovementAssistSettings.PixelSurfActive ~= true then return nil end

    local Grace = math.clamp(tonumber(MovementAssistSettings.PixelSurfGrace) or 0.095, 0.03, 0.16) local LastContact = tonumber(MovementAssistSettings.PixelSurfLastContact) or 0

    if CurrentTime - LastContact > Grace then return nil end

    local Tangent = MovementAssistSettings.PixelSurfLastTangent local Inward = MovementAssistSettings.PixelSurfLastInward

    if typeof(Tangent) ~= "Vector3" or Tangent.Magnitude <= 0.001
        or typeof(Inward) ~= "Vector3" or Inward.Magnitude <= 0.001
    then
        return nil
    end

    return {
        Tangent = Tangent.Unit,
        Inward = Inward.Unit,
        Position = MovementAssistSettings.PixelSurfLastPoint,
        Part = MovementAssistSettings.PixelSurfLastPart,
        Drop = tonumber(MovementAssistSettings.PixelSurfLastDrop) or 0.06,
        Coverage = tonumber(MovementAssistSettings.PixelSurfLastCoverage) or 0.46,
        CoverageError = (tonumber(MovementAssistSettings.PixelSurfTargetCoverage) or 0.46) - (tonumber(MovementAssistSettings.PixelSurfLastCoverage) or 0.46),
        Confidence = math.max((tonumber(MovementAssistSettings.PixelSurfConfidence) or 0) * 0.90, 0.20),
        Fallback = true
    }
end

function ResetPixelSurfState()
    DestroyPixelSurfHold()
    ResetPixelSurfSubtickEngine()
    MovementAssistSettings.PixelSurfActive = false
    MovementAssistSettings.PixelSurfLastContact = 0
    MovementAssistSettings.PixelSurfLastTangent = Vector3.zero
    MovementAssistSettings.PixelSurfLastInward = Vector3.zero
    MovementAssistSettings.PixelSurfLastPart = nil
    MovementAssistSettings.PixelSurfLastPoint = nil
    MovementAssistSettings.PixelSurfTravelDirection = Vector3.zero
    MovementAssistSettings.PixelSurfConfidence = 0
    MovementAssistSettings.PixelSurfLastCoverage = 0
    MovementAssistSettings.PixelSurfLastDrop = tonumber(MovementAssistSettings.PixelSurfTargetDrop) or 0.06
end

function UpdatePixelSurfAssist(CharacterObject, HumanoidObject, RootPart, InputDirection, Grounded, CurrentTime, DeltaTime)
    if PixelSurfEnabled ~= true or not CharacterObject or not HumanoidObject or not RootPart then
        ResetPixelSurfState()
        return false
    end

    if FlyEnabled or InvisibilityEnabled or NoclipEnabled or Configuration and Configuration.Freecam and Configuration.Freecam.Enabled then
        ResetPixelSurfState()
        return false
    end

    local InitialVelocity = RootPart.AssemblyLinearVelocity local InitialHorizontal = Vector3.new(InitialVelocity.X, 0, InitialVelocity.Z)
    local MinimumSpeed = math.max(tonumber(MovementAssistSettings.PixelSurfMinimumSpeed) or 6, 1)

    if InitialHorizontal.Magnitude < MinimumSpeed or InitialVelocity.Y > 1.80 then
        ResetPixelSurfState()
        return false
    end

    if Grounded and MovementAssistSettings.PixelSurfActive ~= true then
        local Candidate = GetPixelSurfCandidate(CharacterObject, HumanoidObject, RootPart, InputDirection, InitialVelocity, 1 / 240)

        if not Candidate or Candidate.Confidence < math.clamp(tonumber(MovementAssistSettings.PixelSurfMinimumConfidence) or 0.42, 0.20, 0.75) then return false end
    end

    local VirtualVelocity = InitialVelocity local LastCandidate local LastHeightError local AnyActive = false

    local SubtickCount = RunPixelSurfSubticks(DeltaTime, function(SubtickDelta, SubtickIndex)
        local SubtickTime = CurrentTime - math.max(DeltaTime, 0) + SubtickIndex * SubtickDelta local Horizontal = Vector3.new(VirtualVelocity.X, 0, VirtualVelocity.Z)
        local Candidate = ResolvePixelSurfCandidate(
            CharacterObject, HumanoidObject, RootPart, InputDirection, VirtualVelocity, SubtickDelta, SubtickTime
        )

        Candidate = AcceptPixelSurfCandidate(Candidate, SubtickTime, SubtickDelta) or GetPixelSurfFallbackCandidate(SubtickTime)

        if not Candidate then return end

        local Tangent = Candidate.Tangent local Inward = Candidate.Inward

        if typeof(Tangent) ~= "Vector3" or Tangent.Magnitude <= 0.001
            or typeof(Inward) ~= "Vector3" or Inward.Magnitude <= 0.001
        then
            return
        end

        Tangent = Tangent.Unit
        Inward = Inward.Unit

        local Wish = GetPixelSurfWish(InputDirection, Horizontal)

        if Wish.Magnitude > 0.001 and Tangent:Dot(Wish) < 0 then
            Tangent = -Tangent
        elseif Wish.Magnitude <= 0.001 and Horizontal.Magnitude > 0.001 and Tangent:Dot(Horizontal.Unit) < 0 then
            Tangent = -Tangent
        end

        local Travel = MovementAssistSettings.PixelSurfTravelDirection

        if typeof(Travel) ~= "Vector3" or Travel.Magnitude <= 0.001 then
            Travel = Tangent
        else
            Travel = Travel.Unit

            if Tangent:Dot(Travel) < 0 then Tangent = -Tangent end

            local FollowAlpha = 1 - math.exp(-15 * SubtickDelta) local Follow = Travel:Lerp(Tangent, FollowAlpha)

            if Follow.Magnitude > 0.001 then Travel = Follow.Unit end

            if Wish.Magnitude > 0.001 and Wish:Dot(Travel) <= -0.74 then Travel = -Travel end
        end

        MovementAssistSettings.PixelSurfTravelDirection = Travel

        local MaximumSpeed = math.max(tonumber(MovementAssistSettings.PixelSurfMaximumSpeed) or 60, MinimumSpeed)
        local TargetSpeed = math.clamp(tonumber(MovementAssistSettings.PixelSurfSpeed) or 28, MinimumSpeed, MaximumSpeed)
        local TangentialAcceleration = math.clamp(tonumber(MovementAssistSettings.PixelSurfTangentialAcceleration) or 150, 40, 260) local CurrentAlong = Horizontal:Dot(Travel)
        local SpeedDelta = math.clamp(TargetSpeed - CurrentAlong, -TangentialAcceleration * SubtickDelta, TangentialAcceleration * SubtickDelta)
        local TangentialSpeed = CurrentAlong + SpeedDelta

        if TangentialSpeed < MinimumSpeed * 0.55 then TangentialSpeed = MinimumSpeed * 0.55 end

        local CurrentNormalSpeed = Horizontal:Dot(Inward) local CoverageError = math.clamp(tonumber(Candidate.CoverageError) or 0, -0.50, 0.50)
        local NormalAcceleration = math.clamp(tonumber(MovementAssistSettings.PixelSurfNormalAcceleration) or 46, 12, 90)
        local NormalDamping = math.clamp(tonumber(MovementAssistSettings.PixelSurfNormalDamping) or 11, 3, 22) local DesiredNormalSpeed = math.clamp(CoverageError * 5.4, -1.15, 1.35)
        local NormalDelta = (DesiredNormalSpeed - CurrentNormalSpeed) * NormalDamping
        local NormalStep = math.clamp(NormalDelta * SubtickDelta, -NormalAcceleration * SubtickDelta, NormalAcceleration * SubtickDelta)
        local NormalSpeed = math.clamp(CurrentNormalSpeed + NormalStep, -1.30, 1.50)

        local NewHorizontal = Travel * TangentialSpeed + Inward * NormalSpeed

        if NewHorizontal.Magnitude > MaximumSpeed then NewHorizontal = NewHorizontal.Unit * MaximumSpeed end

        local TargetDrop = math.clamp(tonumber(MovementAssistSettings.PixelSurfTargetDrop) or 0.06, 0.025, 0.16)
        local HeightError = math.clamp((tonumber(Candidate.Drop) or TargetDrop) - TargetDrop, -0.45, 0.72) local NewY = VirtualVelocity.Y

        if math.abs(HeightError) <= 0.018 then
            NewY *= math.exp(-24 * SubtickDelta)
        elseif HeightError > 0 then
            NewY = math.max(NewY, -0.42)
        else
            NewY = math.min(NewY, 0.42)
        end

        NewY = math.clamp(NewY, -0.62, 0.62)
        VirtualVelocity = Vector3.new(NewHorizontal.X, NewY, NewHorizontal.Z)
        LastCandidate = Candidate
        LastHeightError = HeightError
        AnyActive = true
    end)

    if SubtickCount == 0 then return MovementAssistSettings.PixelSurfActive == true end

    if not AnyActive or not LastCandidate then
        if not GetPixelSurfFallbackCandidate(CurrentTime) then ResetPixelSurfState() end
        return false
    end

    RootPart.AssemblyLinearVelocity = VirtualVelocity
    UpdatePixelSurfGravityHold(RootPart, LastHeightError or 0, VirtualVelocity.Y)

    local Wish = GetPixelSurfWish(InputDirection, Vector3.new(VirtualVelocity.X, 0, VirtualVelocity.Z)) local Travel = MovementAssistSettings.PixelSurfTravelDirection

    if Wish.Magnitude > 0.001 and typeof(Travel) == "Vector3" and Travel.Magnitude > 0.001 then HumanoidObject:Move(Travel.Unit, false) end

    MovementAssistSettings.PixelSurfActive = true
    return true
end

function ResetMovementDriver()
    MovementDriverState.SimPosition = nil
    MovementDriverState.LastPacketTime = 0
    MovementDriverState.Character = nil
    MovementDriverState.LastRealPosition = nil
    MovementDriverState.LastOutputPosition = nil
    MovementDriverState.OutputVelocity = Vector3.zero
    MovementDriverState.Confidence = 0
    MovementDriverState.LastDeltaTime = 0
    MovementDriverState.LastLagDistance = 0
    MovementDriverState.RewriteCount = 0
end

function IsMovementDriverActive()
    return MovementDriverEnabled == true
end

function GetMovementDriverWalkSpeed()
    return math.max( tonumber(MovementDriverState.HorizontalSpeed) or 17.5, 1)
end

function StepMovementDriverPosition(RealPosition)
    if typeof(RealPosition) ~= "Vector3" then return RealPosition end

    local Character = LocalPlayer.Character local CurrentTime = os.clock()

    local function ResetTo(Position)
        MovementDriverState.Character = Character
        MovementDriverState.SimPosition = Position
        MovementDriverState.LastRealPosition = Position
        MovementDriverState.LastOutputPosition = Position
        MovementDriverState.OutputVelocity = Vector3.zero
        MovementDriverState.Confidence = 1
        MovementDriverState.LastDeltaTime = 0
        MovementDriverState.LastLagDistance = 0
        MovementDriverState.LastPacketTime = CurrentTime
        return Position
    end

    if MovementDriverState.Character ~= Character then return ResetTo(RealPosition) end

    local PreviousTime = tonumber(MovementDriverState.LastPacketTime) or 0
    local PreviousOutput = typeof(MovementDriverState.LastOutputPosition) == "Vector3" and MovementDriverState.LastOutputPosition or RealPosition

    MovementDriverState.LastPacketTime = CurrentTime

    if PreviousTime <= 0 or typeof(MovementDriverState.SimPosition) ~= "Vector3" then return ResetTo(RealPosition) end

    local DeltaTime = math.clamp(CurrentTime - PreviousTime, 1 / 240,
        math.max(tonumber(MovementDriverState.MaximumDeltaTime) or 0.075, 1 / 120))

    local SimPosition = MovementDriverState.SimPosition local Delta = RealPosition - SimPosition local Distance = Delta.Magnitude

    MovementDriverState.LastRealPosition = RealPosition
    MovementDriverState.LastDeltaTime = DeltaTime

    if Distance <= 0.0005 then
        MovementDriverState.SimPosition = RealPosition
        MovementDriverState.LastOutputPosition = RealPosition
        MovementDriverState.OutputVelocity = Vector3.zero
        MovementDriverState.Confidence = 1
        MovementDriverState.LastLagDistance = 0
        return RealPosition
    end

    local TeleportResetDistance = math.max(tonumber(MovementDriverState.TeleportResetDistance) or 110, 30)
    if Distance >= TeleportResetDistance then return ResetTo(RealPosition) end

    local HorizontalDelta = Vector3.new(Delta.X, 0, Delta.Z) local VerticalDelta = Delta.Y
    local HorizontalDistance = HorizontalDelta.Magnitude local HorizontalSpeed = math.max(tonumber(MovementDriverState.HorizontalSpeed) or 17.5, 1)
    local VerticalSpeed = math.max(tonumber(MovementDriverState.VerticalSpeed) or 5.5, 0.5) local CatchupDistance = math.max(tonumber(MovementDriverState.CatchupDistance) or 7, 1)

    if Distance > CatchupDistance then
        HorizontalSpeed = math.max(HorizontalSpeed, tonumber(MovementDriverState.CatchupHorizontalSpeed) or 23)
        VerticalSpeed = math.max(VerticalSpeed, tonumber(MovementDriverState.CatchupVerticalSpeed) or 8)
    end

    local MaximumHorizontalStep = HorizontalSpeed * DeltaTime local MaximumVerticalStep = VerticalSpeed * DeltaTime local HorizontalStep = Vector3.zero

    if HorizontalDistance > 0.0005 then HorizontalStep = HorizontalDelta.Unit * math.min(HorizontalDistance, MaximumHorizontalStep) end

    local VerticalStep = math.clamp(VerticalDelta, -MaximumVerticalStep, MaximumVerticalStep) local NextPosition = SimPosition + HorizontalStep + Vector3.new(0, VerticalStep, 0)

    local MaximumLagDistance = math.max(tonumber(MovementDriverState.MaximumLagDistance) or 12, 2) local LagDelta = RealPosition - NextPosition
    local LagDistance = LagDelta.Magnitude

    if LagDistance > MaximumLagDistance then
        NextPosition = RealPosition - LagDelta.Unit * MaximumLagDistance
        LagDistance = MaximumLagDistance
    end

    local InstantVelocity = (NextPosition - PreviousOutput) / math.max(DeltaTime, 1 / 240)
    if InstantVelocity.Magnitude > 160 then InstantVelocity = InstantVelocity.Unit * 160 end

    local PreviousVelocity = typeof(MovementDriverState.OutputVelocity) == "Vector3" and MovementDriverState.OutputVelocity or Vector3.zero

    MovementDriverState.OutputVelocity = PreviousVelocity:Lerp(InstantVelocity, 0.34)
    MovementDriverState.Confidence = math.clamp(1 - LagDistance / math.max(MaximumLagDistance, 0.001), 0.15, 1)
    MovementDriverState.LastLagDistance = LagDistance
    MovementDriverState.SimPosition = NextPosition
    MovementDriverState.LastOutputPosition = NextPosition

    return NextPosition
end

function IsMovementReplicationPacket(Packet)
    if type(Packet) ~= "table" then return false end

    local Movement = Packet[1]

    if type(Movement) ~= "table" then return false end

    local Position = Movement[2]

    if typeof(Position) ~= "Vector3" then return false end

    local Direction = Movement[3]

    if Direction ~= nil and typeof(Direction) ~= "Vector3" then return false end

    return true
end

function FindMovementReplicationPacket(Arguments)
    if type(Arguments) ~= "table" then return nil, nil end

    local Count = math.max( math.floor( tonumber(Arguments.n) or #Arguments ), 0)

    for Index = 1, Count do
        local Value = Arguments[Index]

        if IsMovementReplicationPacket( Value ) then return Value, Index end
    end

    return nil, nil
end

function CloneNamecallArguments(Arguments)
    if type(Arguments) ~= "table" then return nil end

    local Count = math.max( math.floor( tonumber(Arguments.n) or #Arguments ), 0)

    local Output = { n = Count }

    for Index = 1, Count do
        Output[Index] = Arguments[Index]
    end

    return Output
end

function NamecallArgumentTypesMatch(Original, Modified)
    if type(Original) ~= "table" or type(Modified) ~= "table" then return false end

    local OriginalCount = math.max( math.floor( tonumber(Original.n) or #Original ), 0)

    local ModifiedCount = math.max( math.floor( tonumber(Modified.n) or #Modified ), 0)

    if OriginalCount ~= ModifiedCount then return false end

    for Index = 1, OriginalCount do
        if typeof( Original[Index] ) ~= typeof( Modified[Index] ) then return false end
    end

    return true
end

function ApplyMovementDriverPacket(Packet)
    if not IsMovementDriverActive() or not IsMovementReplicationPacket( Packet ) then return nil, false end

    local Movement = Packet[1]

    local RealPosition = Movement[2]

    local SimPosition = StepMovementDriverPosition( RealPosition)

    if typeof(SimPosition) ~= "Vector3" then return nil, false end

    if ( SimPosition
        - RealPosition ).Magnitude <= 0.0005
    then
        return nil, false
    end

    local NewPacket = table.clone( Packet)

    local NewMovement = table.clone( Movement)

    NewMovement[2] = SimPosition

    NewPacket[1] = NewMovement

    MovementDriverState.RewriteCount = ( tonumber(MovementDriverState.RewriteCount) or 0 ) + 1

    return NewPacket, true
end

function SetMovementDriverEnabled(Value)
    MovementDriverEnabled = Value == true
    ResetMovementDriver()

    if MovementDriverEnabled and type( InstallSharedNamecallRouter ) == "function" then InstallSharedNamecallRouter() end

    return MovementDriverEnabled
end

function UpdateMovementAssist(DeltaTime)
    if FlyEnabled or InvisibilityEnabled or Configuration and Configuration.Freecam and Configuration.Freecam.Enabled then return end

    local CharacterObject = LocalPlayer.Character local HumanoidObject = CharacterObject and CharacterObject:FindFirstChildOfClass("Humanoid")
    local RootPart = CharacterObject and CharacterObject:FindFirstChild("HumanoidRootPart")
    if not HumanoidObject or not RootPart or HumanoidObject.Health <= 0 then return end

    local State = HumanoidObject:GetState()
    if State == Enum.HumanoidStateType.Dead or State == Enum.HumanoidStateType.Seated or State == Enum.HumanoidStateType.Swimming or State == Enum.HumanoidStateType.Climbing then return end

    local RawDelta = math.clamp(tonumber(DeltaTime) or 0, 1 / 360, 0.05) local InputDirection, CameraForward = GetMovementAssistInput(HumanoidObject)
    local Grounded = IsMovementAssistGrounded(HumanoidObject) local CurrentTime = os.clock()

    local PixelSurfActive = false

    if PixelSurfEnabled then
        PixelSurfActive = UpdatePixelSurfAssist(
            CharacterObject, HumanoidObject, RootPart, InputDirection, Grounded, CurrentTime, RawDelta
        )
    elseif MovementAssistSettings.PixelSurfActive then
        ResetPixelSurfState()
    end

    if PixelSurfActive then return end

    local TickInterval = math.clamp(tonumber(MovementAssistSettings.TickInterval) or 1 / 90, 1 / 120, 1 / 30)
    MovementAssistSettings.TickAccumulator = (tonumber(MovementAssistSettings.TickAccumulator) or 0) + RawDelta
    if MovementAssistSettings.TickAccumulator < TickInterval then return end

    local FrameTime = math.min(MovementAssistSettings.TickAccumulator, TickInterval * 2)
    MovementAssistSettings.TickAccumulator = MovementAssistSettings.TickAccumulator % TickInterval
    MovementAssistSettings.TickIndex = (tonumber(MovementAssistSettings.TickIndex) or 0) + 1

    local SpaceHeld = UserInputService:IsKeyDown(Enum.KeyCode.Space) local Velocity = RootPart.AssemblyLinearVelocity
    local Horizontal = Vector3.new(Velocity.X, 0, Velocity.Z) local CurrentSpeed = Horizontal.Magnitude

    if Grounded then
        MovementAssistSettings.GroundTicks = (tonumber(MovementAssistSettings.GroundTicks) or 0) + 1
        MovementAssistSettings.AirTicks = 0
        MovementAssistSettings.TakeoffSpeed = CurrentSpeed
    else
        MovementAssistSettings.AirTicks = (tonumber(MovementAssistSettings.AirTicks) or 0) + 1
        MovementAssistSettings.GroundTicks = 0
        MovementAssistSettings.JumpArmed = true
        if MovementAssistSettings.WasGrounded then MovementAssistSettings.TakeoffSpeed = math.max(CurrentSpeed, HumanoidObject.WalkSpeed) end
    end

    if not SpaceHeld then MovementAssistSettings.JumpArmed = true end

    local TickGap = MovementAssistSettings.TickIndex - (tonumber(MovementAssistSettings.LastJumpTick) or -1000)
    local StableLanding = Grounded and (tonumber(MovementAssistSettings.GroundTicks) or 0) >= 2
    local JumpReady = CurrentTime - (tonumber(MovementAssistSettings.LastJump) or 0) >= math.max(tonumber(MovementAssistSettings.JumpCooldown) or 0.1, TickInterval * 5)
    if BunnyHopEnabled and SpaceHeld and StableLanding and MovementAssistSettings.JumpArmed and JumpReady and TickGap >= 5 then
        MovementAssistSettings.LastJump = CurrentTime
        MovementAssistSettings.LastJumpTick = MovementAssistSettings.TickIndex
        MovementAssistSettings.JumpArmed = false
        MovementAssistSettings.GroundTicks = 0
        HumanoidObject.Jump = true
        HumanoidObject:ChangeState(Enum.HumanoidStateType.Jumping)
    end

    MovementAssistSettings.WasGrounded = Grounded

    local CameraObject = Internal.GetCamera() local DeltaYaw = 0
    if CameraObject then
        local Look = CameraObject.CFrame.LookVector local Yaw = math.atan2(-Look.X, -Look.Z) local LastYaw = MovementAssistSettings.LastYaw
        MovementAssistSettings.LastYaw = Yaw
        if LastYaw then DeltaYaw = math.atan2(math.sin(Yaw - LastYaw), math.cos(Yaw - LastYaw)) end
    end

    if Grounded or not AutoStrafeEnabled and not AirControlEnabled then return end

    local Strength = math.clamp(tonumber(MovementAssistSettings.StrafeStrength) or 0.7, 0, 1)
    local Control = math.clamp(tonumber(MovementAssistSettings.AirControlStrength) or 0.5, 0, 1) local WalkSpeed = math.max(tonumber(HumanoidObject.WalkSpeed) or 16, 1)
    local UserCap = math.max(tonumber(MovementAssistSettings.MaxAirSpeed) or 32, WalkSpeed) local SafeCap = math.min(UserCap, WalkSpeed * 2.25) local WishDirection = InputDirection

    if WishDirection.Magnitude <= 0.001 and AutoStrafeEnabled then
        local BaseDirection = CurrentSpeed > 0.05 and Horizontal.Unit or CameraForward
        if math.abs(DeltaYaw) > 0.00002 then
            local Side = DeltaYaw > 0 and 1 or -1 local Lateral = Vector3.new(-BaseDirection.Z, 0, BaseDirection.X) * Side local TurnAmount = math.clamp(math.abs(DeltaYaw) * 80, 0.2, 1)
            WishDirection = BaseDirection * (0.72 - TurnAmount * 0.32) + Lateral * (0.28 + TurnAmount * 0.72)
        else
            WishDirection = BaseDirection
        end
    end

    if WishDirection.Magnitude <= 0.001 then return end
    WishDirection = WishDirection.Unit
    MovementAssistSettings.LastWishDirection = WishDirection

    local NewHorizontal = Horizontal
    if AirControlEnabled and InputDirection.Magnitude > 0.001 then
        local PreserveSpeed = math.clamp(math.max(CurrentSpeed, WalkSpeed), WalkSpeed, SafeCap) local DesiredHorizontal = WishDirection * PreserveSpeed
        local TurnRate = 2.5 + Control * 11.5 local TurnAlpha = 1 - math.exp(-TurnRate * FrameTime)
        NewHorizontal = Horizontal:Lerp(DesiredHorizontal, math.clamp(TurnAlpha, 0, 0.42 + Control * 0.36))
    end

    if AutoStrafeEnabled then
        local AirAcceleration = WalkSpeed * (3.5 + Strength * 8.5) local CurrentAlongWish = NewHorizontal:Dot(WishDirection) local AddSpeed = SafeCap - CurrentAlongWish
        if AddSpeed > 0 then
            local AccelSpeed = math.min(AddSpeed, AirAcceleration * FrameTime)
            NewHorizontal = NewHorizontal + WishDirection * AccelSpeed
        end
    elseif AirControlEnabled and NewHorizontal.Magnitude < WalkSpeed then
        NewHorizontal = NewHorizontal + WishDirection * math.min(WalkSpeed - NewHorizontal.Magnitude, WalkSpeed * Control * FrameTime * 3)
    end

    local NewSpeed = NewHorizontal.Magnitude
    if NewSpeed > SafeCap then NewHorizontal = NewHorizontal.Unit * SafeCap end

    RootPart.AssemblyLinearVelocity = Vector3.new(NewHorizontal.X, Velocity.Y, NewHorizontal.Z)
    if InputDirection.Magnitude > 0.001 then HumanoidObject:Move(InputDirection, false) end
end

function UpdateMovementAssistConnection()
    local ShouldRun = AutoStrafeEnabled or BunnyHopEnabled or AirControlEnabled or PixelSurfEnabled
    if ShouldRun and not MovementAssistConnection then
        MovementAssistConnection = (RunService.PreSimulation or RunService.Heartbeat):Connect(UpdateMovementAssist)
    elseif not ShouldRun and MovementAssistConnection then
        MovementAssistConnection:Disconnect()
        MovementAssistConnection = nil
        MovementAssistSettings.LastJump = 0
        MovementAssistSettings.LastJumpTick = -1000
        MovementAssistSettings.TickAccumulator = 0
        MovementAssistSettings.TickIndex = 0
        MovementAssistSettings.GroundTicks = 0
        MovementAssistSettings.AirTicks = 0
        MovementAssistSettings.JumpArmed = true
        MovementAssistSettings.LastYaw = nil
        ResetPixelSurfState()
        ResetPixelSurfSubtickEngine()
    end
end

function DisableMovementAssist()
    AutoStrafeEnabled = false
    BunnyHopEnabled = false
    AirControlEnabled = false
    PixelSurfEnabled = false
    if MovementAssistConnection then
        MovementAssistConnection:Disconnect()
        MovementAssistConnection = nil
    end
    MovementAssistSettings.LastJump = 0
    MovementAssistSettings.LastJumpTick = -1000
    MovementAssistSettings.TickAccumulator = 0
    MovementAssistSettings.TickIndex = 0
    MovementAssistSettings.GroundTicks = 0
    MovementAssistSettings.AirTicks = 0
    MovementAssistSettings.JumpArmed = true
    MovementAssistSettings.LastYaw = nil
    ResetPixelSurfState()
    ResetPixelSurfSubtickEngine()
    ResetMovementDriver()
end

function GetFlyInputVelocity(CameraObject, Speed, IncludeVertical)
    local Velocity = Vector3.new(0, 0, 0)

    if UserInputService:IsKeyDown(Enum.KeyCode.W) then Velocity += CameraObject.CFrame.LookVector * Speed end
    if UserInputService:IsKeyDown(Enum.KeyCode.S) then Velocity -= CameraObject.CFrame.LookVector * Speed end
    if UserInputService:IsKeyDown(Enum.KeyCode.A) then Velocity -= CameraObject.CFrame.RightVector * Speed end
    if UserInputService:IsKeyDown(Enum.KeyCode.D) then Velocity += CameraObject.CFrame.RightVector * Speed end

    if IncludeVertical then
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then Velocity += Vector3.new(0, Speed, 0) end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then Velocity -= Vector3.new(0, Speed, 0) end
    end

    if Velocity.Magnitude > Speed then Velocity = Velocity.Unit * Speed end

    return Velocity
end

local FlySetIdentity = type(setthreadidentity) == "function" and setthreadidentity or type(setidentity) == "function" and setidentity or nil
local FlyGetIdentity = type(getthreadidentity) == "function" and getthreadidentity or type(getidentity) == "function" and getidentity or nil
FlyState = type(FlyState) == "table" and FlyState or {Root = nil, Humanoid = nil, Position = nil, Rotation = nil, AutoRotate = nil}

function WriteFlyCFrame(Part, Value)
    if not Part or not Part.Parent or typeof(Value) ~= "CFrame" then return false end
    local Identity = 2
    if FlyGetIdentity then
        local CurrentIdentity = FlyGetIdentity()
        if type(CurrentIdentity) == "number" then Identity = CurrentIdentity end
    end
    if FlySetIdentity then FlySetIdentity(8) end
    Part.CFrame = Value
    if FlySetIdentity then FlySetIdentity(Identity) end
    return true
end

function GetFlyCFrameVelocity(CameraObject)
    if not CameraObject then return Vector3.zero end
    local Look = CameraObject.CFrame.LookVector
    local Right = CameraObject.CFrame.RightVector
    local Forward = Vector3.new(Look.X, 0, Look.Z)
    local Side = Vector3.new(Right.X, 0, Right.Z)
    Forward = Forward.Magnitude > 0.001 and Forward.Unit or Vector3.new(0, 0, -1)
    Side = Side.Magnitude > 0.001 and Side.Unit or Vector3.new(1, 0, 0)
    local Horizontal = Vector3.zero
    if UserInputService:IsKeyDown(Enum.KeyCode.W) then Horizontal += Forward end
    if UserInputService:IsKeyDown(Enum.KeyCode.S) then Horizontal -= Forward end
    if UserInputService:IsKeyDown(Enum.KeyCode.A) then Horizontal -= Side end
    if UserInputService:IsKeyDown(Enum.KeyCode.D) then Horizontal += Side end
    if Horizontal.Magnitude > 1 then Horizontal = Horizontal.Unit end
    local Vertical = 0
    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then Vertical += 1 end
    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl) then Vertical -= 1 end
    local Speed = math.clamp(tonumber(FlySpeed) or 40, 5, 180)
    local VerticalSpeed = math.clamp(tonumber(FlyVerticalSpeed) or Speed, 5, 180)
    local Velocity = Horizontal * Speed + Vector3.new(0, Vertical * VerticalSpeed, 0)
    local Limit = math.max(Speed, VerticalSpeed)
    if Velocity.Magnitude > Limit then Velocity = Velocity.Unit * Limit end
    return Velocity
end

function BindFlyCharacter(Character)
    local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    if not RootPart then return nil, nil end
    if FlyState.Humanoid and FlyState.Humanoid ~= Humanoid and FlyState.Humanoid.Parent and FlyState.AutoRotate ~= nil then
        FlyState.Humanoid.AutoRotate = FlyState.AutoRotate
    end
    FlyState.Root = RootPart
    FlyState.Humanoid = Humanoid
    FlyState.Position = RootPart.Position
    FlyState.Rotation = RootPart.CFrame - RootPart.Position
    FlyState.AutoRotate = Humanoid and Humanoid.AutoRotate or nil
    if Humanoid then Humanoid.AutoRotate = false end
    return RootPart, Humanoid
end

function FlyEnable()
    if FlyEnabled then return end
    FlyEnabled = true
    if FlyConnection then FlyConnection:Disconnect(); FlyConnection = nil end
    if FlyMethod == "Velocity" then
        BindFlyCharacter(LocalPlayer.Character)
    end
    local ConnectEvent = FlyMethod == "Velocity" and RunService.Heartbeat or (RunService.PreSimulation or RunService.Heartbeat)
    FlyConnection = ConnectEvent:Connect(function(DeltaTime)
        if not FlyEnabled then return end
        local Character = LocalPlayer.Character
        if not Character then return end
        local RootPart = Character:FindFirstChild("HumanoidRootPart")
        local Humanoid = Character:FindFirstChildOfClass("Humanoid")
        local CameraObject = Internal.GetCamera()
        if not RootPart or not RootPart.Parent or not CameraObject then return end
        if FlyMethod == "Ragdoll" then
            local CurrentFlySpeed = math.clamp(tonumber(FlySpeed) or 40, 5, 180)
            local AppliedVelocity = GetFlyInputVelocity(CameraObject, CurrentFlySpeed, false)
            RootPart.Velocity = AppliedVelocity
            RootPart.AssemblyLinearVelocity = AppliedVelocity
            RootPart.AssemblyAngularVelocity = Vector3.zero
            Internal.Call(function() RootPart.RotVelocity = Vector3.zero end)
            local Events = ReplicatedStorage:FindFirstChild("Events")
            local RagdollRemote = Events and Events:FindFirstChild("__RZDONL")
            if RagdollRemote and RagdollRemote:IsA("RemoteEvent") then
                if type(HoldAngelWingsForRagdoll) == "function" then HoldAngelWingsForRagdoll(0.12) end
                RagdollRemote:FireServer("__---r", Vector3.zero, RootPart.CFrame, true)
            end
            AntiAimRakNetState.FlyStatus = "RAG:" .. tostring(math.floor(AppliedVelocity.Magnitude + 0.5))
            return
        end
        if FlyState.Root ~= RootPart or FlyState.Humanoid ~= Humanoid or typeof(FlyState.Position) ~= "Vector3" or typeof(FlyState.Rotation) ~= "CFrame" then
            RootPart, Humanoid = BindFlyCharacter(Character)
            if not RootPart then return end
        end
        if Humanoid and Humanoid.AutoRotate then Humanoid.AutoRotate = false end
        local Dt = math.clamp(tonumber(DeltaTime) or 1 / 60, 1 / 240, 1 / 20)
        local Velocity = GetFlyCFrameVelocity(CameraObject)
        local CurrentPosition = RootPart.Position
        if (CurrentPosition - FlyState.Position).Magnitude > math.max(math.clamp(tonumber(FlySpeed) or 40, 5, 180) * 0.75, 24) then
            FlyState.Position = CurrentPosition
            FlyState.Rotation = RootPart.CFrame - CurrentPosition
        end
        FlyState.Position += Velocity * Dt
        WriteFlyCFrame(RootPart, CFrame.new(FlyState.Position) * FlyState.Rotation)
        AntiAimRakNetState.FlyAppliedVelocity = Velocity
        AntiAimRakNetState.FlyLastVector = Velocity
        AntiAimRakNetState.FlyLastLocalStep = os.clock()
        AntiAimRakNetState.FlyStatus = "CF:" .. tostring(math.floor(Velocity.Magnitude + 0.5))
    end)
end

function FlyDisable()
    if not FlyEnabled then return end
    FlyEnabled = false
    if FlyConnection then FlyConnection:Disconnect(); FlyConnection = nil end
    if FlyState.Humanoid and FlyState.Humanoid.Parent and FlyState.AutoRotate ~= nil then FlyState.Humanoid.AutoRotate = FlyState.AutoRotate end
    if FlyMethod == "Ragdoll" then
        local Character = LocalPlayer.Character
        local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
        if RootPart then
            RootPart.Velocity = Vector3.zero
            RootPart.AssemblyLinearVelocity = Vector3.zero
            RootPart.AssemblyAngularVelocity = Vector3.zero
            Internal.Call(function() RootPart.RotVelocity = Vector3.zero end)
        end
    end
    FlyState.Root = nil
    FlyState.Humanoid = nil
    FlyState.Position = nil
    FlyState.Rotation = nil
    FlyState.AutoRotate = nil
    AntiAimRakNetState.FlyAppliedVelocity = Vector3.zero
    AntiAimRakNetState.FlyLastVector = Vector3.zero
    AntiAimRakNetState.FlyPreviousPosition = nil
    AntiAimRakNetState.FlyPreviousTime = 0
    AntiAimRakNetState.FlyLastLocalStep = 0
    AntiAimRakNetState.FlyStatus = "OFF"
end

function WalkSpeed.BackingFrom(Value)
    local Success, Default, Run, Crouch = pcall(function()
        return Value.DefaultWalkSpeed, Value.RunWalkSpeed, Value.CrouchWalkSpeed
    end)

    if not Success or type(Default) ~= "number" or type(Run) ~= "number" or type(Crouch) ~= "number"
        or type(getrawmetatable) ~= "function"
    then
        return nil
    end

    local MetaSuccess, Meta = pcall(getrawmetatable, Value)
    if not MetaSuccess or type(Meta) ~= "table" then return nil end

    local Backing = rawget(Meta, "__index")
    if type(Backing) ~= "table"
        or type(rawget(Backing, "DefaultWalkSpeed")) ~= "number"
        or type(rawget(Backing, "RunWalkSpeed")) ~= "number"
        or type(rawget(Backing, "CrouchWalkSpeed")) ~= "number"
    then
        return nil
    end

    return Backing
end

function WalkSpeed.Inspect(Function)
    local Values = Internal.Upvalues(Function)
    if not Values then return nil, nil end

    for _, Value in next, Values do
        local Backing = WalkSpeed.BackingFrom(Value)
        if Backing then return Value, Backing end
    end
end

function WalkSpeed.FromHeartbeat()
    if type(getconnections) ~= "function" then return nil, nil end

    local Success, Connections = pcall(getconnections, RunService.Heartbeat)
    if not Success or type(Connections) ~= "table" then return nil, nil end

    for _, Connection in next, Connections do
        local Proxy, Backing = WalkSpeed.Inspect(Internal.ConnectionFunction(Connection))
        if Proxy and Backing then return Proxy, Backing end
    end
end

function WalkSpeed.FromGC()
    if type(getgc) ~= "function" then return nil, nil end

    local Success, Objects = pcall(getgc, true)
    if not Success or type(Objects) ~= "table" then return nil, nil end

    for _, Object in next, Objects do
        if type(Object) == "function" then
            local Proxy, Backing = WalkSpeed.Inspect(Object)
            if Proxy and Backing then return Proxy, Backing end
        end
    end
end

function WalkSpeed.Resolve(AllowGC)
    if WalkSpeed.Backing then return true end

    WalkSpeed.Proxy, WalkSpeed.Backing = WalkSpeed.FromHeartbeat()

    if not WalkSpeed.Backing and AllowGC then
        WalkSpeed.Proxy, WalkSpeed.Backing = WalkSpeed.FromGC()
    end

    if WalkSpeed.Backing and not WalkSpeed.Original then
        WalkSpeed.Original = {
            Default = rawget(WalkSpeed.Backing, "DefaultWalkSpeed"),
            Run = rawget(WalkSpeed.Backing, "RunWalkSpeed"),
            Crouch = rawget(WalkSpeed.Backing, "CrouchWalkSpeed")
        }
    end

    return WalkSpeed.Backing ~= nil
end

function WalkSpeed.Apply()
    if not WalkSpeed.Alive or not WalkSpeed.Enabled then return false end
    if not WalkSpeed.Backing and not WalkSpeed.Resolve(WalkSpeed.Attempts == 0) then return false end

    rawset(WalkSpeed.Backing, "DefaultWalkSpeed", WalkSpeed.Speed)
    rawset(WalkSpeed.Backing, "RunWalkSpeed", WalkSpeed.Speed)
    rawset(WalkSpeed.Backing, "CrouchWalkSpeed", WalkSpeed.Speed)
    return true
end

function WalkSpeed.Restore()
    if not WalkSpeed.Backing or not WalkSpeed.Original then return end

    rawset(WalkSpeed.Backing, "DefaultWalkSpeed", WalkSpeed.Original.Default)
    rawset(WalkSpeed.Backing, "RunWalkSpeed", WalkSpeed.Original.Run)
    rawset(WalkSpeed.Backing, "CrouchWalkSpeed", WalkSpeed.Original.Crouch)
end

function WalkSpeed.StartResolve()
    if WalkSpeed.Thread then return end

    WalkSpeed.Thread = task.spawn(function()
        while WalkSpeed.Alive and WalkSpeed.Enabled and not WalkSpeed.Backing and WalkSpeed.Attempts < 10 do
            WalkSpeed.Attempts += 1
            if WalkSpeed.Apply() then break end
            task.wait(1.5)
        end

        WalkSpeed.Thread = nil
    end)
end

function WalkSpeed.SetSpeed(Value)
    WalkSpeed.Speed = math.clamp(math.floor((tonumber(Value) or WalkSpeed.Speed) + 0.5), 24, 32)

    rawset(Environment, "CriminalityWalkSpeedValue", WalkSpeed.Speed)

    WalkSpeed.Apply()
    return WalkSpeed.Speed
end

function WalkSpeed.SetEnabled(Value)
    local Enabled = Value == true
    if WalkSpeed.Enabled == Enabled then return Enabled end

    WalkSpeed.Enabled = Enabled

    if Enabled then
        if not WalkSpeed.Resolve(true) then WalkSpeed.StartResolve() end
        WalkSpeed.Apply()
    else
        WalkSpeed.Restore()
    end

    return Enabled
end

function WalkSpeed.Rescan()
    WalkSpeed.Restore()
    WalkSpeed.Proxy = nil
    WalkSpeed.Backing = nil
    WalkSpeed.Original = nil
    WalkSpeed.Attempts = 0

    local Resolved = WalkSpeed.Resolve(true)
    WalkSpeed.Apply()
    return Resolved
end

function WalkSpeed.GetState()
    local Character = LocalPlayer.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    return {
        Enabled = WalkSpeed.Enabled,
        Speed = WalkSpeed.Speed,
        Actual = Humanoid and Humanoid.WalkSpeed or nil,
        Resolved = WalkSpeed.Backing ~= nil,
        CrouchPatched = WalkSpeed.Backing ~= nil,
        Method = "XIIX Default/Run/Crouch config"
    }
end

function WalkSpeed.Shutdown()
    if not WalkSpeed.Alive then return end

    WalkSpeed.SetEnabled(false)
    WalkSpeed.Alive = false

    if WalkSpeed.Thread then
        pcall(task.cancel, WalkSpeed.Thread)
        WalkSpeed.Thread = nil
    end
end

do
    local Previous = rawget(Environment, "CriminalityWalkSpeed")

    if type(Previous) == "table" and type(Previous.Shutdown) == "function" then
        pcall(Previous.Shutdown)
    end

    WalkSpeed.Speed = math.clamp(math.floor((tonumber(rawget(Environment, "CriminalityWalkSpeedValue")) or 32) + 0.5), 24, 32)
    rawset(Environment, "CriminalityWalkSpeedValue", WalkSpeed.Speed)
    rawset(Environment, "CriminalityWalkSpeed", WalkSpeed)
end

function Jump.Character()
    return LocalPlayer.Character
end

function Jump.Humanoid()
    local Character = Jump.Character()
    return Character and Character:FindFirstChildOfClass("Humanoid")
end

function Jump.Stats()
    local GVF = rawget(_G, "GVF")

    if type(GVF) == "function" then
        local Success, Stats = pcall(GVF, LocalPlayer.Name)
        if Success and typeof(Stats) == "Instance" then return Stats end
    end

    local CharStats = ReplicatedStorage:FindFirstChild("CharStats")
    return CharStats and CharStats:FindFirstChild(LocalPlayer.Name)
end

function Jump.Currents()
    local Stats = Jump.Stats()
    return Stats and Stats:FindFirstChild("Currents")
end

function Jump.ClearModifiers()
    for Index = 1, #Jump.Modifiers do
        local Modifier = Jump.Modifiers[Index]
        if Modifier and Modifier.Parent then Modifier:Destroy() end
    end

    table.clear(Jump.Modifiers)

    local Currents = Jump.Currents()

    if Currents then
        for _, Child in next, Currents:GetChildren() do
            if string.sub(Child.Name, 1, #Jump.Prefix) == Jump.Prefix then Child:Destroy() end
        end
    end
end

function Jump.BasePower(Humanoid, Stats)
    if Humanoid:GetState() == Enum.HumanoidStateType.Swimming then return 50 end

    local Crouching = Stats and Stats:FindFirstChild("Crouching")
    if Crouching and Crouching.Value then return 0 end

    local Sprinting = Stats and Stats:FindFirstChild("Sprinting")
    return Sprinting and Sprinting.Value and 45 or 40
end

function Jump.ApplyPower(Humanoid)
    if not Jump.Power then
        if #Jump.Modifiers > 0 then Jump.ClearModifiers() end
        return false
    end

    local Stats = Jump.Stats()
    local Currents = Stats and Stats:FindFirstChild("Currents")
    if not Currents then return false end

    local Remaining = math.max(Jump.JumpPower - Jump.BasePower(Humanoid, Stats), 0)
    local Needed = math.ceil(Remaining / 30)

    while #Jump.Modifiers > Needed do
        local Modifier = table.remove(Jump.Modifiers)
        if Modifier and Modifier.Parent then Modifier:Destroy() end
    end

    for Index = 1, Needed do
        local Modifier = Jump.Modifiers[Index]

        if not Modifier or Modifier.Parent ~= Currents then
            local Existing = Currents:FindFirstChild(Jump.Prefix .. Index)

            if Existing and Existing:IsA("NumberValue") then
                Modifier = Existing
            else
                if Existing then Existing:Destroy() end
                Modifier = Instance.new("NumberValue")
                Modifier.Name = Jump.Prefix .. Index
                Modifier.Parent = Currents
            end

            Jump.Modifiers[Index] = Modifier
        end

        local Amount = math.min(Remaining, 30)
        Modifier.Value = -Amount
        Remaining -= Amount
    end

    return true
end

function Jump.HasHipConstants(Function)
    local Constants = Internal.Constants(Function)
    if not Constants then return false end

    local HasJump, HasHip = false, false

    for _, Value in next, Constants do
        if Value == "JumpPower" then
            HasJump = true
        elseif Value == "HipHeight" then
            HasHip = true
        end
    end

    return HasJump and HasHip
end

function Jump.FindExpected(Function, Humanoid)
    if type(Function) ~= "function" or not Jump.HasHipConstants(Function) then return nil end

    local Source = ""

    pcall(function()
        Source = debug.info(Function, "s") or ""
    end)

    if not string.find(Source, "XIIX", 1, true) then return nil end

    local Values = Internal.Upvalues(Function)
    if not Values then return nil end

    local OwnsHumanoid = false

    for _, Value in next, Values do
        if rawequal(Value, Humanoid) then
            OwnsHumanoid = true
            break
        end
    end

    if not OwnsHumanoid then return nil end

    local Best, Difference = nil, math.huge

    for _, Value in next, Values do
        if typeof(Value) == "Instance" and Value:IsA("NumberValue") and Value.Parent == nil then
            local Delta = math.abs(Value.Value - Humanoid.HipHeight)

            if Delta < Difference then
                Best = Value
                Difference = Delta
            end
        end
    end

    return Best
end

function Jump.DisconnectHip()
    for Index = 1, #Jump.HipConnections do
        local Connection = Jump.HipConnections[Index]
        if Connection then pcall(function() Connection:Disconnect() end) end
    end

    table.clear(Jump.HipConnections)

    if Jump.ExpectedConnection then
        pcall(function() Jump.ExpectedConnection:Disconnect() end)
        Jump.ExpectedConnection = nil
    end

    Jump.HipHumanoid = nil
end

function Jump.BindExpected(Expected, Humanoid)
    if not Expected or not Expected:IsA("NumberValue") then return end

    if Jump.ExpectedConnection then
        pcall(function() Jump.ExpectedConnection:Disconnect() end)
        Jump.ExpectedConnection = nil
    end

    Jump.ExpectedConnection = Expected:GetPropertyChangedSignal("Value"):Connect(function()
        if not Jump.Alive or not Jump.Hip or Jump.ApplyingHip then return end
        if Jump.Expected ~= Expected or Jump.ExpectedHumanoid ~= Humanoid then return end
        task.defer(Jump.ApplyHip, Humanoid)
    end)
end

function Jump.ResolveHip(Humanoid)
    if Jump.Expected and Jump.ExpectedHumanoid == Humanoid then return Jump.Expected end

    Jump.Expected = nil
    Jump.ExpectedHumanoid = Humanoid

    if type(getconnections) == "function" then
        local Success, Connections = pcall(getconnections, Humanoid.Changed)

        if Success and type(Connections) == "table" then
            for _, Connection in next, Connections do
                Jump.Expected = Jump.FindExpected(Internal.ConnectionFunction(Connection), Humanoid)
                if Jump.Expected then break end
            end
        end
    end

    if Jump.Expected then
        if Jump.OriginalExpected == nil then Jump.OriginalExpected = Jump.Expected.Value end
        Jump.BindExpected(Jump.Expected, Humanoid)
    end

    if Jump.OriginalHip == nil then Jump.OriginalHip = Humanoid.HipHeight end
    return Jump.Expected
end

function Jump.BindHip(Humanoid)
    if not Humanoid or Jump.HipHumanoid == Humanoid then return end

    Jump.DisconnectHip()
    Jump.HipHumanoid = Humanoid

    Jump.HipConnections[#Jump.HipConnections + 1] = Humanoid:GetPropertyChangedSignal("HipHeight"):Connect(function()
        if not Jump.Alive or not Jump.Hip or Jump.ApplyingHip then return end
        task.defer(Jump.ApplyHip, Humanoid)
    end)

    Jump.HipConnections[#Jump.HipConnections + 1] = Humanoid.StateChanged:Connect(function()
        if not Jump.Alive or not Jump.Hip then return end
        task.defer(function()
            if Jump.Alive and Jump.Hip and Humanoid.Parent then Jump.ApplyHip(Humanoid) end
        end)
    end)
end

function Jump.ApplyHip(Humanoid)
    if not Jump.Alive or not Jump.Hip or not Humanoid or not Humanoid.Parent or Humanoid.Health <= 0 then return false end

    Jump.BindHip(Humanoid)
    local Expected = Jump.ResolveHip(Humanoid)

    Jump.ApplyingHip = true

    local Success = pcall(function()
        if Expected and math.abs(Expected.Value - Jump.HipHeight) > 0.0001 then
            Expected.Value = Jump.HipHeight
        end

        if math.abs(Humanoid.HipHeight - Jump.HipHeight) > 0.0001 then
            Humanoid.HipHeight = Jump.HipHeight
        end
    end)

    Jump.ApplyingHip = false
    return Success
end

function Jump.RestoreHip()
    local Humanoid = Jump.Humanoid()
    Jump.ApplyingHip = true

    pcall(function()
        if Jump.Expected and type(Jump.OriginalExpected) == "number" then
            Jump.Expected.Value = Jump.OriginalExpected
        end

        if Humanoid and type(Jump.OriginalHip) == "number" then
            Humanoid.HipHeight = Jump.OriginalHip
        end
    end)

    Jump.ApplyingHip = false
    Jump.DisconnectHip()
    Jump.Expected = nil
    Jump.ExpectedHumanoid = nil
    Jump.OriginalHip = nil
    Jump.OriginalExpected = nil
end

function Jump.Apply()
    if not Jump.Alive then return end

    local Humanoid = Jump.Humanoid()
    if not Humanoid or Humanoid.Health <= 0 then return end

    Jump.ApplyPower(Humanoid)

    if Jump.Hip then
        Jump.BindHip(Humanoid)
        Jump.ApplyHip(Humanoid)
    end
end

function Jump.SetInfinite(Value)
    Jump.Infinite = Value == true
    Environment.CriminalityInfiniteJump = Jump.Infinite
    return Jump.Infinite
end

function Jump.SetPowerEnabled(Value)
    Jump.Power = Value == true

    if Jump.Power then
        Jump.Apply()
    else
        Jump.ClearModifiers()
    end

    return Jump.Power
end

function Jump.SetHipEnabled(Value)
    Jump.Hip = Value == true

    if Jump.Hip then
        local Humanoid = Jump.Humanoid()
        if Humanoid then Jump.BindHip(Humanoid) end
        Jump.Apply()
    else
        Jump.RestoreHip()
    end

    return Jump.Hip
end

function Jump.SetPower(Value)
    Jump.JumpPower = math.clamp(math.floor((tonumber(Value) or Jump.JumpPower) + 0.5), 40, 160)
    Environment.CriminalityJumpPower = Jump.JumpPower

    if Jump.Power then Jump.Apply() end
    return Jump.JumpPower
end

function Jump.SetHip(Value)
    Jump.HipHeight = math.clamp(math.floor((tonumber(Value) or Jump.HipHeight) * 10 + 0.5) / 10, -2, 10)
    Environment.CriminalityHipHeight = Jump.HipHeight

    if Jump.Hip then Jump.Apply() end
    return Jump.HipHeight
end

function Jump.GetState()
    local Humanoid = Jump.Humanoid()

    return {
        InfiniteJump = Jump.Infinite,
        JumpPower = Jump.Power,
        JumpPowerValue = Jump.JumpPower,
        HipHeight = Jump.Hip,
        HipHeightValue = Jump.HipHeight,
        ActualJumpPower = Humanoid and Humanoid.JumpPower or nil,
        ActualHipHeight = Humanoid and Humanoid.HipHeight or nil,
        ExpectedHipResolved = Jump.Expected ~= nil,
        JumpModifierCount = #Jump.Modifiers
    }
end

function Jump.ResetCharacter()
    Jump.ClearModifiers()
    Jump.DisconnectHip()
    Jump.Expected = nil
    Jump.ExpectedHumanoid = nil
    Jump.OriginalHip = nil
    Jump.OriginalExpected = nil
    Jump.ApplyingHip = false
end

function Jump.Shutdown()
    if not Jump.Alive then return end

    Jump.SetInfinite(false)
    Jump.SetPowerEnabled(false)
    Jump.SetHipEnabled(false)
    Jump.Alive = false

    for Index = 1, #Jump.Connections do
        local Connection = Jump.Connections[Index]
        if Connection then pcall(function() Connection:Disconnect() end) end
    end

    table.clear(Jump.Connections)
end

do
    local Previous = rawget(Environment, "CriminalityJumpHip")

    if type(Previous) == "table" and type(Previous.Shutdown) == "function" then
        pcall(Previous.Shutdown)
    end

    Jump.JumpPower = math.clamp(math.floor((tonumber(rawget(Environment, "CriminalityJumpPower")) or 100) + 0.5), 40, 160)
    Jump.HipHeight = math.clamp(math.floor((tonumber(rawget(Environment, "CriminalityHipHeight")) or 4) * 10 + 0.5) / 10, -2, 10)

    Environment.CriminalityJumpPower = Jump.JumpPower
    Environment.CriminalityHipHeight = Jump.HipHeight
    Environment.CriminalityInfiniteJump = false
    Environment.CriminalityJumpHip = Jump
end

Jump.Connections[#Jump.Connections + 1] = RunService.Heartbeat:Connect(Jump.Apply)

Jump.Connections[#Jump.Connections + 1] = UserInputService.JumpRequest:Connect(function()
    if not Jump.Alive or not Jump.Infinite then return end

    local Now = os.clock()
    if Now - Jump.LastJump < Jump.Debounce then return end
    Jump.LastJump = Now

    local Humanoid = Jump.Humanoid()

    if Humanoid and Humanoid.Health > 0
        and Humanoid:GetState() ~= Enum.HumanoidStateType.Dead
        and Humanoid.FloorMaterial == Enum.Material.Air
    then
        Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
    end
end)

Jump.Connections[#Jump.Connections + 1] = LocalPlayer.CharacterAdded:Connect(function()
