end)

function Noclip.Disconnect(Connection)
    if Connection then pcall(function() Connection:Disconnect() end) end
end

function Noclip.Patch()
    if type(getgc) ~= "function" or type(hookfunction) ~= "function" then return 0 end

    local Success, Objects = pcall(getgc, true)
    if not Success or type(Objects) ~= "table" then return 0 end

    local Count = 0

    for _, Object in next, Objects do
        if type(Object) == "function" and not Noclip.Functions[Object] then
            local Source, Name = "", ""

            pcall(function()
                Source = debug.info(Object, "s") or ""
                Name = debug.info(Object, "n") or ""
            end)

            local XIIX = string.find(Source, "XIIX", 1, true)
                and (Name == "mainUpdt" or Internal.HasConstant(Object, "InitialCFrame") and Internal.HasConstant(Object, "BulkMoveTo"))

            local Adonis = string.find(Source, ".Plugins.Anti_Cheat", 1, true)
                and (Name == "HumanoidState" or Internal.HasConstant(Object, "NoClipping"))

            if XIIX or Adonis then
                local Hooked = pcall(hookfunction, Object, Noclip.Null)

                if Hooked then
                    Noclip.Functions[Object] = true
                    Count += 1
                end
            end
        end
    end

    Noclip.Patches += Count
    return Count
end

function Noclip.Track(Part)
    if not Part or not Part:IsA("BasePart") then return end

    if Noclip.Parts[Part] == nil then
        Noclip.Parts[Part] = Part.CanCollide
    end

    if Part.CanCollide then Part.CanCollide = false end
end

function Noclip.RestoreParts()
    for Part, CanCollide in next, Noclip.Parts do
        if Part and Part.Parent then pcall(function() Part.CanCollide = CanCollide end) end
    end

    table.clear(Noclip.Parts)
end

function Noclip.RemoveExemptions()
    if Noclip.NWO and Noclip.NWO.Parent then Noclip.NWO:Destroy() end
    Noclip.NWO = nil

    if Noclip.AddedCTP and Noclip.Humanoid and Noclip.Humanoid.Parent then
        pcall(Noclip.CollectionService.RemoveTag, Noclip.CollectionService, Noclip.Humanoid, "CTP")
    end

    Noclip.AddedCTP = false
end

function Noclip.Restore()
    Noclip.RestoreParts()
    Noclip.RemoveExemptions()
    Noclip.Character = nil
    Noclip.Humanoid = nil
end

function Noclip.Exempt(Humanoid)
    if not Noclip.CollectionService:HasTag(Humanoid, "CTP") then
        Noclip.CollectionService:AddTag(Humanoid, "CTP")
        Noclip.AddedCTP = true
    end

    local Existing = Humanoid:FindFirstChild("NWO")

    if not Existing then
        Noclip.NWO = Instance.new("BoolValue")
        Noclip.NWO.Name = "NWO"
        Noclip.NWO.Value = true
        Noclip.NWO.Parent = Humanoid
    elseif Existing ~= Noclip.NWO then
        Noclip.NWO = nil
    end
end

function Noclip.Apply(Character)
    if not Noclip.Alive or not Noclip.Enabled or not Character or not Character.Parent then return false end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Humanoid or Humanoid.Health <= 0 then return false end

    if Noclip.Character ~= Character then
        Noclip.Restore()
        Noclip.Character = Character
        Noclip.Humanoid = Humanoid
    end

    Noclip.Exempt(Humanoid)

    for _, Descendant in next, Character:GetDescendants() do
        Noclip.Track(Descendant)
    end

    return true
end

function Noclip.ApplyCurrent()
    if Noclip.Alive and Noclip.Enabled then Noclip.Apply(LocalPlayer.Character) end
end

function Noclip.Set(Value)
    local Enabled = Value == true
    if Noclip.Enabled == Enabled then return Enabled end

    Noclip.Enabled = Enabled
    NoclipEnabled = Enabled

    if Enabled then
        if Noclip.Patches == 0 then Noclip.Patch() end
        Noclip.ApplyCurrent()
    else
        Noclip.Restore()
    end

    return Enabled
end

function Noclip.GetState()

    return {
        Enabled = Noclip.Enabled,
        Character = Noclip.Character,
        CTP = Noclip.Humanoid and Noclip.CollectionService:HasTag(Noclip.Humanoid, "CTP") or false,
        NWO = Noclip.Humanoid and Noclip.Humanoid:FindFirstChild("NWO") ~= nil or false,
        LocalPatches = Noclip.Patches
    }
end

function Noclip.Shutdown()
    if not Noclip.Alive then return end

    Noclip.Set(false)
    Noclip.Alive = false

    for Index = 1, #Noclip.Connections do
        Noclip.Disconnect(Noclip.Connections[Index])
    end

    table.clear(Noclip.Connections)
end

function NoclipEnable()
    Noclip.Set(true)
end

function NoclipDisable()
    Noclip.Set(false)
end

do
    local Previous = rawget(Environment, "CriminalityNoclip")

    if type(Previous) == "table" and type(Previous.Shutdown) == "function" then
        pcall(Previous.Shutdown)
    end

    rawset(Environment, "CriminalityNoclip", Noclip)
end

Noclip.Connections[#Noclip.Connections + 1] = LocalPlayer.CharacterAdded:Connect(function(Character)
    Noclip.Restore()
    if Noclip.Enabled then task.defer(Noclip.Apply, Character) end
end)

Noclip.Connections[#Noclip.Connections + 1] = LocalPlayer.CharacterRemoving:Connect(function(Character)
    if Character == Noclip.Character then Noclip.Restore() end
end)

Noclip.Connections[#Noclip.Connections + 1] = RunService.Stepped:Connect(Noclip.ApplyCurrent)

InvisibilityController = {}
;(function()
    repeat task.wait() until game:IsLoaded()

    local CloneRef = cloneref or function(...)
            return ... end

    local Service = setmetatable( {}, { __index = function( Unused, KeyValue)
                    return CloneRef( game:GetService( KeyValue ))
                end })

    local Player = Service.Players.LocalPlayer

    local CharacterModel = Player.Character

    local Humanoid local HumanoidRootPart
    local CharacterParts = {}

    local InvisEnabled = false local PendingEnable = false local NextReadyRetry = 0 local RigWarningShown = false
    local Track = nil

    local Anim = Instance.new("Animation")

    Anim.AnimationId = "rbxassetid://215384594"

    local InvisFixed = true

    local HUD = Instance.new("ScreenGui")

    HUD.Name = "InvisWarning"
    HUD.Parent = Service.CoreGui

    local Warn = Instance.new( "TextLabel", HUD)

    Warn.Text = "⚠️ You are visible ⚠️"

    Warn.Visible = false
    Warn.Size = UDim2.new( 0, 200, 0, 30)

    Warn.Position = UDim2.new( 0.5, -100, 0.85, 0)

    Warn.BackgroundTransparency = 1
    Warn.FontFace = UiFont
    Warn.TextSize = 24
    Warn.TextColor3 = Color3.fromRGB( 255, 255, 0)

    Warn.TextStrokeTransparency = 0.5
    Warn.ZIndex = 10

    local function Refresh()
        CharacterModel = Player.Character
        table.clear(CharacterParts)

        if CharacterModel then
            HumanoidRootPart = CharacterModel:FindFirstChild( "HumanoidRootPart")

            Humanoid = CharacterModel:FindFirstChildOfClass( "Humanoid")

            for _, DescendantObject
            in ipairs( CharacterModel:GetDescendants())
            do
                if DescendantObject:IsA("BasePart") then CharacterParts[ #CharacterParts + 1 ] = DescendantObject end
            end
        else
            HumanoidRootPart = nil
            Humanoid = nil
        end
    end

    local function GetReadyState()
        Refresh()

        if not CharacterModel or not CharacterModel.Parent or not Humanoid or not HumanoidRootPart then return false, "Loading" end

        if Humanoid.RigType
            ~= Enum.HumanoidRigType.R6 then
            return false, "Rig"
        end

        if not CharacterModel:FindFirstChild("Torso") then return false, "Loading" end

        return true, nil
    end

    local function LoadTrack()
        if Track then
            Internal.Call(function()
                Track:Stop()
            end)

            Track = nil
        end

        if Humanoid then
            local Success, Result = Internal.Call(function()
                    return Humanoid:LoadAnimation(Anim)
                end)

            if Success and Result then
                Track = Result
                Track.Priority = Enum.AnimationPriority.Action4
            end
        end
    end

    local function Activate()
        local Ready, Reason = GetReadyState()

        if not Ready then
            if Reason == "Rig" then
                PendingEnable = false
                InvisEnabled = false
                InvisibilityEnabled = false
                InvisFixed = false

                if not RigWarningShown then
                    RigWarningShown = true

                    Internal.Call(function()
                        game:GetService( "StarterGui" ):SetCore( "SendNotification", { Title = "Invisibility FAILED",

                                Text = "Requires R6 Avatar",

                                Duration = 5 })
                    end)
                end
            end

            return false
        end

        RigWarningShown = false
        InvisFixed = true
        PendingEnable = false
        InvisEnabled = true
        InvisibilityEnabled = true

        local CameraObject = Internal.GetCamera()

        if CameraObject then CameraObject.CameraSubject = HumanoidRootPart end

        LoadTrack()
        return true
    end

    function InvisibilityController.Enable()
        if InvisEnabled then
            InvisibilityEnabled = true
            return true
        end

        PendingEnable = true
        InvisibilityEnabled = true
        NextReadyRetry = 0

        return Activate()
    end

    function InvisibilityController.Disable()
        PendingEnable = false
        NextReadyRetry = 0

        if not InvisEnabled then
            InvisibilityEnabled = false
            Warn.Visible = false
            return true
        end

        InvisEnabled = false
        InvisibilityEnabled = false

        if Track then
            Internal.Call(function()
                Track:Stop()
            end)

            Track = nil
        end

        if Humanoid then
            local CameraObject = Internal.GetCamera()

            if CameraObject then CameraObject.CameraSubject = Humanoid end
        end

        if CharacterModel then
            for _, ValueItem
            in ipairs(CharacterParts)
            do
                if ValueItem.Parent and ValueItem.Transparency
                        == 0.5 then
                    ValueItem.Transparency = 0
                end
            end
        end

        Warn.Visible = false
        return true
    end

    InvisibilityController.IsEnabled = function()
            return InvisEnabled
        end

    Player.CharacterAdded:Connect(function(Character)
            CharacterModel = Character

            if Track then
                Internal.Call(function()
                    Track:Stop()
                end)

                Track = nil
            end

            NextReadyRetry = 0
            RigWarningShown = false

            task.spawn(function()
                for _ = 1, 50 do
                    local Ready, Reason = GetReadyState()

                    if Ready then
                        if PendingEnable or InvisibilityEnabled then Activate() end

                        return
                    end

                    if Reason == "Rig" then
                        if PendingEnable or InvisibilityEnabled then Activate() end

                        return
                    end

                    task.wait(0.12)
                end
            end)
        end)

    Player.CharacterRemoving:Connect(function()
            if Track then
                Internal.Call(function()
                    Track:Stop()
                end)

                Track = nil
            end

            CharacterModel = nil
            Humanoid = nil
            HumanoidRootPart = nil
            Warn.Visible = false

            if InvisibilityEnabled then PendingEnable = true end
        end)

    Service.RunService.Heartbeat:Connect(function(DeltaTime)
            if PendingEnable and not InvisEnabled and os.clock()
                    >= NextReadyRetry then
                NextReadyRetry = os.clock() + 0.30

                Activate()
            end

            if not InvisEnabled or not InvisFixed then
                if not InvisEnabled and CharacterModel then
                    for _, ValueItem
                    in ipairs( CharacterParts)
                    do
                        if ValueItem.Parent and ValueItem.Transparency
                                == 0.5 then
                            ValueItem.Transparency = 0
                        end
                    end
                end

                Warn.Visible = false
                return
            end

            if not CharacterModel or not Humanoid or not HumanoidRootPart or not Humanoid:IsDescendantOf(workspace) or Humanoid.Health <= 0 then
                Warn.Visible = false

                if InvisibilityEnabled then
                    PendingEnable = true
                    InvisEnabled = false
                    NextReadyRetry = 0
                end

                return
            end

            if SafeFarmTeleportLock then
                Warn.Visible = false

                if CharacterModel then
                    for _, ValueItem in ipairs(CharacterParts) do
                        if ValueItem.Parent and ValueItem.Transparency ~= 1 then ValueItem.Transparency = 0.5 end
                    end
                end

                return
            end

            Warn.Visible = not ( Humanoid and Humanoid:IsDescendantOf(workspace) and Humanoid.FloorMaterial
                        ~= Enum.Material.Air)

            local CharacterControlLocked = Configuration and Configuration.Freecam
                and Configuration.Freecam.Enabled == true
                or ProjectileController and ProjectileController.CurrentObject ~= nil
            local MovementSpeed = 12

            if not CharacterControlLocked and Humanoid.MoveDirection.Magnitude > 0 then
                HumanoidRootPart.CFrame = HumanoidRootPart.CFrame + Humanoid.MoveDirection * MovementSpeed * DeltaTime
            end

            if BacktrackVisualState and BacktrackVisualState.Enabled
                and type(BacktrackVisualState.SetLocalStableSnapshot) == "function"
            then
                BacktrackVisualState:SetLocalStableSnapshot(CharacterModel, HumanoidRootPart, os.clock())
            end

            local PreviousRootCFrame = HumanoidRootPart.CFrame local PreviousCameraOffset = Humanoid.CameraOffset

            local CameraObject = Internal.GetCamera()

            local Unused, YValue

            if CameraObject then
                Unused, YValue = CameraObject.CFrame:ToOrientation()
            else
                YValue = 0
            end

            HumanoidRootPart.CFrame = CFrame.new(HumanoidRootPart.Position) * CFrame.fromOrientation( 0, YValue, 0) * CFrame.Angles( math.rad(90), 0, 0)

            Humanoid.CameraOffset = Vector3.new( 0, 1.44, 0)

            if Track then
                Internal.Call(function()
                    if not Track.IsPlaying then Track:Play() end

                    Track:AdjustSpeed(0)
                    Track.TimePosition = 0.3
                end)
            else
                LoadTrack()
            end

            Service.RunService.RenderStepped:Wait()

            if Humanoid and Humanoid:IsDescendantOf(workspace) then Humanoid.CameraOffset = PreviousCameraOffset end

            if HumanoidRootPart and HumanoidRootPart:IsDescendantOf(workspace) then HumanoidRootPart.CFrame = PreviousRootCFrame end

            if Track then
                Internal.Call(function()
                    Track:Stop()
                end)
            end

            if not CharacterControlLocked and HumanoidRootPart and HumanoidRootPart:IsDescendantOf(workspace) and CameraObject then
                local LookDirection = CameraObject.CFrame.LookVector local FlatDirection = Vector3.new(LookDirection.X, 0, LookDirection.Z)

                if FlatDirection.Magnitude > 0.001 then
                    FlatDirection = FlatDirection.Unit
                    HumanoidRootPart.CFrame = CFrame.new(HumanoidRootPart.Position, HumanoidRootPart.Position + FlatDirection)
                end
            end

            if CharacterModel then
                for _, ValueItem
                in ipairs(CharacterParts)
                do
                    if ValueItem.Parent and ValueItem.Transparency
                            ~= 1 then
                        ValueItem.Transparency = 0.5
                    end
                end
            end
        end)
end)()

function InvisibilityEnable()
    if InvisibilityEnabled then return end
    InvisibilityController.Enable()
end

function InvisibilityDisable()
    if not InvisibilityEnabled then return end
    InvisibilityController.Disable()
