    AntiAimRakNetState.FakeLagLastAction = "WAIT"

    AntiAimRakNetState.FakeLagLastActionTime = CurrentTime

    AntiAimRakNetState.FakeLagLastSlot = 0
end

function UpdateAtramentaFakeLagTelemetry(Action, Protected, Slot, CurrentTime)
    CurrentTime = tonumber(CurrentTime) or os.clock()

    local Start = tonumber(AntiAimRakNetState.FakeLagWindowStart) or 0

    if Start <= 0 then
        Start = CurrentTime

        AntiAimRakNetState.FakeLagWindowStart = Start
    end

    AntiAimRakNetState.FakeLagWindowSeen = ( tonumber(AntiAimRakNetState.FakeLagWindowSeen) or 0 ) + 1

    if Action == "HOLD" then
        AntiAimRakNetState.FakeLagWindowBlocked = ( tonumber(AntiAimRakNetState.FakeLagWindowBlocked) or 0 ) + 1
    else
        AntiAimRakNetState.FakeLagWindowSent = ( tonumber(AntiAimRakNetState.FakeLagWindowSent) or 0 ) + 1
    end

    if Protected == true then AntiAimRakNetState.FakeLagWindowProtected = ( tonumber(AntiAimRakNetState.FakeLagWindowProtected) or 0 ) + 1 end

    AntiAimRakNetState.FakeLagLastAction = tostring( Action or "WAIT")

    AntiAimRakNetState.FakeLagLastActionTime = CurrentTime

    AntiAimRakNetState.FakeLagLastSlot = math.max( math.floor( tonumber(Slot) or 0 ), 0)

    local Elapsed = CurrentTime - Start

    if Elapsed >= 0.50 then
        AntiAimRakNetState.FakeLagSeenRate = ( tonumber(AntiAimRakNetState.FakeLagWindowSeen) or 0 ) / Elapsed

        AntiAimRakNetState.FakeLagBlockedRate = ( tonumber(AntiAimRakNetState.FakeLagWindowBlocked) or 0 ) / Elapsed

        AntiAimRakNetState.FakeLagSentRate = ( tonumber(AntiAimRakNetState.FakeLagWindowSent) or 0 ) / Elapsed

        AntiAimRakNetState.FakeLagProtectedRate = ( tonumber(AntiAimRakNetState.FakeLagWindowProtected) or 0 ) / Elapsed

        AntiAimRakNetState.FakeLagWindowStart = CurrentTime

        AntiAimRakNetState.FakeLagWindowSeen = 0

        AntiAimRakNetState.FakeLagWindowBlocked = 0

        AntiAimRakNetState.FakeLagWindowSent = 0

        AntiAimRakNetState.FakeLagWindowProtected = 0
    end
end

function GetAtramentaFakeLagTelemetryText()
    local Limit = math.clamp( math.floor( tonumber(HideHeadController.FakeLagLimit) or 2 ), 1, 8)

    local Action = tostring( AntiAimRakNetState.FakeLagLastAction or "WAIT")

    local LastTime = tonumber(AntiAimRakNetState.FakeLagLastActionTime) or 0

    if LastTime <= 0 or os.clock() - LastTime > 0.45 then Action = "IDLE" end

    local Slot = math.clamp( math.floor( tonumber(AntiAimRakNetState.FakeLagLastSlot) or 0 ), 0, Limit + 1)

    local BlockedRate = math.max( tonumber(AntiAimRakNetState.FakeLagBlockedRate) or 0, 0)

    local SentRate = math.max( tonumber(AntiAimRakNetState.FakeLagSentRate) or 0, 0)

    local ProtectedRate = math.max( tonumber(AntiAimRakNetState.FakeLagProtectedRate) or 0, 0)

    local TotalRate = BlockedRate + SentRate

    local ChokePercent = TotalRate > 0.001 and math.floor( BlockedRate / TotalRate * 100 + 0.5 ) or 0

    local Text = "Lag:" .. Action .. " " .. tostring( Slot ) .. "/" .. tostring( Limit + 1 ) .. " · " .. string.format( "%.1fb/%.1fs", BlockedRate,
            SentRate ) .. " · " .. tostring( ChokePercent ) .. "%"

    if ProtectedRate >= 0.1 then Text ..= " · P" .. string.format( "%.1f", ProtectedRate) end

    return Text
end

function GetAntiAimMode()
    local Mode = tostring( HideHeadController.Mode or "Manual")

    if Mode ~= "Manual" and Mode ~= "Down" and Mode ~= "Spin" then Mode = "Manual" end

    return Mode
end

function NormalizeManualAntiAimDirection(Direction)
    Direction = tostring( Direction or "Back")

    if Direction ~= "Left" and Direction ~= "Right" and Direction ~= "Back" and Direction ~= "Forward" then Direction = "Back" end

    return Direction
end

function GetManualAntiAimYaw()
    local Direction = NormalizeManualAntiAimDirection( HideHeadController.ManualDirection)

    local Yaw = Direction == "Left" and 90 or Direction == "Right" and -90 or Direction == "Forward" and 0 or 180

    Yaw += math.clamp( tonumber(HideHeadController.ManualOffset) or 0, -45, 45)

    return Yaw, Direction
end

function SetManualAntiAimDirection(Direction, Active)
    Direction = NormalizeManualAntiAimDirection( Direction)

    if Active == false and HideHeadController.ManualDirection
            == Direction
    then
        HideHeadController.ManualDirection = "Back"
    else
        HideHeadController.ManualDirection = Direction
    end

    HideHeadController.Mode = "Manual"

    HideHeadController.Pitch = 0

    ResetAntiAimNetworkState()

    return HideHeadController.ManualDirection
end

function GetAntiAimAngles()
    local Mode = GetAntiAimMode()

    if Mode == "Manual" then
        local ManualYaw = GetManualAntiAimYaw()

        return 0, ManualYaw
    end

    local BaseYaw = math.clamp( tonumber(HideHeadController.YawOffset) or 180, -180, 180)

    local Pitch = math.clamp( tonumber(HideHeadController.Pitch) or 0, -89, 89)

    local Speed = math.clamp( tonumber(HideHeadController.Speed) or 180, 1, 720)

    local Yaw = BaseYaw

    if Mode == "Spin" then
        Yaw += ( os.clock() * Speed ) % 360
    elseif Mode == "Down" then
        Pitch = -math.max( math.abs(Pitch), 78)
    end

    return Pitch, Yaw
end

function GetAtramentaVelocityFlyNetworkDirection()
    local Velocity = AntiAimRakNetState.FlyAppliedVelocity

    if typeof(Velocity) ~= "Vector3" then return Vector3.zero end

    local Horizontal = Vector3.new( Velocity.X, 0, Velocity.Z)

    if Horizontal.Magnitude <= 0.001 then return Vector3.zero end

    return Horizontal.Unit
end

function ResetAtramentaVelocityFlyNetworkAssist()
    AntiAimRakNetState.FlyMovementSeen = 0

    AntiAimRakNetState.FlyMovementPatched = 0

    AntiAimRakNetState.FlyLastVector = Vector3.zero

    AntiAimRakNetState.FlyAppliedVelocity = Vector3.zero

    AntiAimRakNetState.FlyLastPacketTime = 0

    AntiAimRakNetState.FlyPreviousPosition = nil

    AntiAimRakNetState.FlyPreviousTime = 0

    AntiAimRakNetState.FlyCorrectionScale = 1

    AntiAimRakNetState.FlyCorrectionUntil = 0

    AntiAimRakNetState.FlyCorrectionCount = 0

    AntiAimRakNetState.FlyLastCorrectionError = 0

    AntiAimRakNetState.FlyLastLocalStep = 0

    AntiAimRakNetState.FlyStatus = "READY"
end

function UpdateAtramentaVelocityFlyCorrection(RootPart, CurrentTime)
    if not RootPart or not RootPart:IsA("BasePart") then return end

    local PreviousPosition = AntiAimRakNetState.FlyPreviousPosition

    local PreviousTime = tonumber(AntiAimRakNetState.FlyPreviousTime) or 0

    local AppliedVelocity = AntiAimRakNetState.FlyAppliedVelocity

    local CurrentPosition = RootPart.Position

    AntiAimRakNetState.FlyPreviousPosition = CurrentPosition

    AntiAimRakNetState.FlyPreviousTime = CurrentTime

    if typeof(PreviousPosition) ~= "Vector3" or PreviousTime <= 0 or typeof(AppliedVelocity) ~= "Vector3" then return end

    local DeltaTime = CurrentTime - PreviousTime

    if DeltaTime <= 0 or DeltaTime > 0.18 then return end

    local ExpectedPosition = PreviousPosition + AppliedVelocity * DeltaTime

    local ErrorDistance = ( CurrentPosition - ExpectedPosition ).Magnitude

    AntiAimRakNetState.FlyLastCorrectionError = ErrorDistance

    local ActualDelta = CurrentPosition - PreviousPosition

    local Moving = AppliedVelocity.Magnitude
        >= 4

    local OppositeSnap = Moving and ActualDelta.Magnitude >= 1 and ActualDelta:Dot( AppliedVelocity ) < 0

    if ErrorDistance >= 4.25 or OppositeSnap then
        AntiAimRakNetState.FlyCorrectionCount = ( tonumber(AntiAimRakNetState.FlyCorrectionCount) or 0 ) + 1

        AntiAimRakNetState.FlyCorrectionScale = math.max( ( tonumber(AntiAimRakNetState.FlyCorrectionScale) or 1 ) * 0.78, 0.42)

        AntiAimRakNetState.FlyCorrectionUntil = CurrentTime + 0.38
    elseif CurrentTime >= ( tonumber(AntiAimRakNetState.FlyCorrectionUntil) or 0 ) then
        AntiAimRakNetState.FlyCorrectionScale = math.min( ( tonumber(AntiAimRakNetState.FlyCorrectionScale) or 1 ) + DeltaTime * 0.12, 1)
    end
end

function GetAtramentaVelocityFlyTarget(CameraObject)
    local Scale = math.clamp( tonumber(AntiAimRakNetState.FlyCorrectionScale) or 1, 0.42, 1)

    local Speed = math.clamp( tonumber(FlySpeed) or 40, 5, 180 ) * Scale

    return GetFlyInputVelocity( CameraObject, Speed, true)
end

function IsAtramentaRawMovementRecord(Data)
    if type(Data) ~= "string" or #Data < 23 then return false end

    return string.byte(Data, 1) == 0x83 and string.byte(Data, 2) == 0x03 and string.byte(Data, 3) == 0x01 and string.byte(Data, 7) == 0x03
        and string.byte(Data, 8) == 0xFE and string.byte(Data, 9) == 0x0D and string.byte(Data, 10) == 0x00
end

function PackAtramentaRawVector3(Value)
    if typeof(Value) ~= "Vector3" then return nil end

    if type(buffer) == "table" and type(buffer.create) == "function" and type(buffer.writef32) == "function" and type(buffer.tostring) == "function"
    then
        local Data = buffer.create( 12)

        buffer.writef32( Data, 0, Value.X)

        buffer.writef32( Data, 4, Value.Y)

        buffer.writef32( Data, 8, Value.Z)

        AntiAimRakNetState.RawPackReady = true

        return buffer.tostring( Data)
    end

    if type(string.pack) == "function" then
        AntiAimRakNetState.RawPackReady = true

        return string.pack( "<fff", Value.X, Value.Y, Value.Z)
    end

    AntiAimRakNetState.RawPackReady = false

    return nil
end

function GetAtramentaRawFakeDirection()
    local Camera = workspace.CurrentCamera

    local Character = LocalPlayer.Character

    local Root = Character and Character:FindFirstChild( "HumanoidRootPart")

    local Humanoid = Character and Character:FindFirstChildOfClass( "Humanoid")

    local Look = Camera and Camera.CFrame.LookVector or Root and Root.CFrame.LookVector or Vector3.new( 0, 0, -1)

    local Flat = Vector3.new( Look.X, 0, Look.Z)

    if Flat.Magnitude <= 0.001 then
        Flat = Vector3.new( 0, 0, -1)
    else
        Flat = Flat.Unit
    end

    local Right = Vector3.new( -Flat.Z, 0, Flat.X)

    local Mode = tostring( HideHeadController.FakePositionMode or "Alternate")

    local CurrentTime = os.clock()

    local Interval = math.clamp( tonumber(HideHeadController.FakePositionInterval) or 0.14, 0.06, 0.35)

    if HideHeadController.PredictionBreaker and CurrentTime
            - ( tonumber(AntiAimRakNetState.RawFlipTime) or 0 ) >= Interval
    then
        AntiAimRakNetState.RawFlipTime = CurrentTime

        AntiAimRakNetState.RawFlipSign = -( tonumber(AntiAimRakNetState.RawFlipSign) or 1)
    end

    local Sign = tonumber(AntiAimRakNetState.RawFlipSign) or 1

    local FakeDirection

    if Mode == "Back" then
        FakeDirection = -Flat
    elseif Mode == "Manual" then
        local Direction = NormalizeManualAntiAimDirection( HideHeadController.ManualDirection)

        if Direction == "Left" then
            FakeDirection = -Right
        elseif Direction == "Right" then
            FakeDirection = Right
        elseif Direction == "Forward" then
            FakeDirection = Flat
        else
            FakeDirection = -Flat
        end
    else
        FakeDirection = Right * Sign
    end

    local RealDirection = Humanoid and Humanoid.MoveDirection or Vector3.zero

    RealDirection = Vector3.new( RealDirection.X, 0, RealDirection.Z)

    local Strength = math.clamp( tonumber(HideHeadController.RawDirectionStrength) or 0.90, 0, 1)

    local Result

    if RealDirection.Magnitude > 0.001 and Strength < 0.999 then
        Result = RealDirection.Unit * ( 1 - Strength ) + FakeDirection * Strength
    else
        Result = FakeDirection
    end

    if Result.Magnitude <= 0.001 then Result = FakeDirection end

    Result = Vector3.new( Result.X, 0, Result.Z)

    if Result.Magnitude > 1 then Result = Result.Unit end

    AntiAimRakNetState.RawLastDirection = Result

    return Result
end

function RewriteAtramentaRawMovementRecord(Packet, Data)
    if not IsAtramentaRawMovementRecord( Data ) then return false end

    local VelocityFly = FlyEnabled == true and FlyMethod == "Velocity"

    local Direction

    if VelocityFly then
        AntiAimRakNetState.FlyMovementSeen = ( tonumber(AntiAimRakNetState.FlyMovementSeen) or 0 ) + 1

        Direction = GetAtramentaVelocityFlyNetworkDirection()
    elseif HideHeadController.FakeDirectionEnabled then
        Direction = GetAtramentaRawFakeDirection()
    else
        return false
    end

    local Packed = PackAtramentaRawVector3( Direction)

    if type(Packed) ~= "string" or #Packed ~= 12 then
        AntiAimRakNetState.RawSetDataFailures = ( tonumber(AntiAimRakNetState.RawSetDataFailures) or 0 ) + 1

        if VelocityFly then AntiAimRakNetState.FlyStatus = "PACK-FAIL" end

        return false
    end

    local SetData = Packet and Packet.SetData

    if type(SetData) ~= "function" then
        AntiAimRakNetState.RawSetDataFailures = ( tonumber(AntiAimRakNetState.RawSetDataFailures) or 0 ) + 1

        if VelocityFly then AntiAimRakNetState.FlyStatus = "NO-SETDATA" end

        return false
    end

    local NewData = string.sub( Data, 1, 10 ) .. Packed .. string.sub( Data, 23)

    if #NewData ~= #Data then
        if VelocityFly then AntiAimRakNetState.FlyStatus = "SIZE-FAIL" end

        return false
    end

    SetData( Packet, NewData)

    AntiAimRakNetState.RawSetDataReady = true

    AntiAimRakNetState.RawMovementPatched = ( tonumber(AntiAimRakNetState.RawMovementPatched) or 0 ) + 1

    AntiAimRakNetState.FakePackets = ( tonumber(AntiAimRakNetState.FakePackets) or 0 ) + 1

    if VelocityFly then
        AntiAimRakNetState.FlyMovementPatched = ( tonumber(AntiAimRakNetState.FlyMovementPatched) or 0 ) + 1

        AntiAimRakNetState.FlyLastPacketTime = os.clock()

        AntiAimRakNetState.FlyStatus = "NET:" .. tostring( AntiAimRakNetState.FlyMovementPatched)
    end

    return true
end

function IsAtramentaPhysicsPacket(Packet, Data)
    if type(Data) ~= "string" or #Data < 22 then return false end

    local PacketId = Packet and Packet.PacketId

    if PacketId ~= 161 then return false end

    return string.byte( Data, 1 ) == 0xA1
end

function GetAtramentaPhysicsPacketHeaderLength(Data)
    if type(Data) ~= "string" or #Data < 22 or string.byte(Data, 1) ~= 0xA1 then return nil end

    return 17
end

function GetAtramentaPhysicsPacketSignature(Data)
    local HeaderLength = GetAtramentaPhysicsPacketHeaderLength( Data)

    if not HeaderLength then return nil end

    local CountBytes = #Data >= 9 and string.sub( Data, 6, 9 ) or ""

    local FirstEntry = #Data >= 22 and string.sub( Data, 18, 22 ) or ""

    return CountBytes .. FirstEntry
end

function PushAtramentaPhysicsPacket(Data, CurrentTime, Snapshot)
    local HeaderLength = GetAtramentaPhysicsPacketHeaderLength( Data)

    if not HeaderLength then return nil end

    local History = AntiAimRakNetState.PhysicsPacketHistory

    if type(History) ~= "table" then
        History = {}

        AntiAimRakNetState.PhysicsPacketHistory = History
    end

    local Entry = { Time = CurrentTime, Data = Data, Body = string.sub( Data, HeaderLength + 1 ), Size = #Data, HeaderLength = HeaderLength,
        Signature = GetAtramentaPhysicsPacketSignature( Data ), Snapshot = CloneAtramentaReplicaSnapshot( Snapshot, CurrentTime ) }

    History[#History + 1] = Entry

    while #History > 96 do
        table.remove( History, 1)
    end

    local MinimumTime = CurrentTime - 1.35

    while #History > 2 do
        local First = History[1]

        if type(First) ~= "table" or ( tonumber(First.Time) or math.huge ) >= MinimumTime then break end

        table.remove( History, 1)
    end

    AntiAimRakNetState.PhysicsPacketSeen = ( tonumber(AntiAimRakNetState.PhysicsPacketSeen) or 0 ) + 1

    return Entry
end

function GetAtramentaDelayedPhysicsPacket(CurrentEntry, CurrentTime, Delay)
    if type(CurrentEntry) ~= "table" then return nil end

    local History = AntiAimRakNetState.PhysicsPacketHistory

    if type(History) ~= "table" or #History < 2 then return nil end

    local WantedTime = CurrentTime - math.clamp( tonumber(Delay) or 0.22, 0.03, 0.80)

    local Signature = CurrentEntry.Signature

    local ExactSize

    local SignatureMatch

    for Index = #History - 1, 1, -1 do
        local Entry = History[Index]

        if type(Entry) == "table" and ( tonumber(Entry.Time) or math.huge ) <= WantedTime then
            if Entry.Signature == Signature then
                if Entry.Size
                    == CurrentEntry.Size
                then
                    ExactSize = Entry

                    break
                end

                SignatureMatch = SignatureMatch or Entry
            end
        end
    end

    return ExactSize or SignatureMatch
end

