    AntiAimRakNetState.PhysicsJitterSequence = 0

    AntiAimRakNetState.PhysicsJitterSign = 1

    AntiAimRakNetState.PhysicsJitterDelay = 0

    AntiAimRakNetState.PhysicsAnchorEntry = nil

    AntiAimRakNetState.LocalServerReplica = nil

    AntiAimRakNetState.LocalServerReplicaSequence = 0

    AntiAimRakNetState.LocalServerReplicaLastSend = 0

    AntiAimRakNetState.LocalServerReplicaLastBlock = 0

    AntiAimRakNetState.LocalServerReplicaBlocked = 0

    AntiAimRakNetState.PhysicsEntityKey = nil

    AntiAimRakNetState.LastSentPhysicsPayload = nil

    AntiAimRakNetState.LastSentPhysicsPosition = nil

