    AntiAimRakNetState.ReceivePhysicsHits = 0

    AntiAimRakNetState.ReceivePayloadMatches = 0

    AntiAimRakNetState.ReceiveCorrections = 0

    AntiAimRakNetState.LastReceiveTime = 0

    AntiAimRakNetState.LastVerifiedSequence = 0

    AntiAimRakNetState.LastCorrectionSequence = 0

    AntiAimRakNetState.PreviousLocalPosition = nil

    AntiAimRakNetState.PreviousLocalVelocity = nil

    AntiAimRakNetState.PreviousLocalCorrectionTime = 0

    AntiAimRakNetState.PhysicsPositionOffset = 0

    AntiAimRakNetState.PhysicsPositionConfidence = 0

    AntiAimRakNetState.PhysicsPositionSamples = 0

    AntiAimRakNetState.PhysicsPositionMisses = 0

    AntiAimRakNetState.PhysicsPositionValidated = false

    AntiAimRakNetState.PhysicsOriginalPayload = nil

    AntiAimRakNetState.PhysicsStrategy = "Calibrating"

    AntiAimRakNetState.PhysicsReplayOffset = 16

    AntiAimRakNetState.PhysicsReplaySeen = 0

    AntiAimRakNetState.PhysicsReplayPatched = 0

    AntiAimRakNetState.PhysicsRawPatched = 0

    if type( AntiAimRakNetState.PhysicsPacketHistory ) == "table" then
        table.clear( AntiAimRakNetState.PhysicsPacketHistory)
    else
