    AntiAimRakNetState.PhysicsForceRealNext = false

    AntiAimRakNetState.PhysicsProtectCurrent = false

    AntiAimRakNetState.PhysicsRealRestoreCount = 0
end

function UnpackAtramentaRawVector3(Payload)
    if type(Payload) ~= "string" or #Payload < 12 then return nil end

    if type(buffer) == "table" and type(buffer.fromstring) == "function" and type(buffer.readf32) == "function" then
        local DataBuffer = buffer.fromstring( string.sub( Payload, 1, 12 ))

        local X = buffer.readf32( DataBuffer, 0)

        local Y = buffer.readf32( DataBuffer, 4)

        local Z = buffer.readf32( DataBuffer, 8)

        if X == X and Y == Y and Z == Z and math.abs(X) < 1000000 and math.abs(Y) < 1000000 and math.abs(Z) < 1000000 then return Vector3.new( X, Y, Z) end

        return nil
    end

    if type(string.unpack) == "function" then
        local X, Y, Z = string.unpack( "<fff", Payload)

        if X == X and Y == Y and Z == Z and math.abs(X) < 1000000 and math.abs(Y) < 1000000 and math.abs(Z) < 1000000 then return Vector3.new( X, Y, Z) end
    end

    return nil
end

function GetAtramentaReplicaVerification(Sequence, CurrentTime)
    local Verification = AntiAimRakNetState.ReplicaVerification

    if type(Verification) ~= "table" then return "Outbound", "send", 0, nil end

    local Entry = Verification[ tonumber(Sequence) or -1 ]

    if type(Entry) ~= "table" then return "Outbound", "send", 0, nil end

    local Now = tonumber(CurrentTime) or os.clock()

    local Age = math.max( 0, Now - ( tonumber(Entry.Time) or 0 ))

    local Status = tostring( Entry.Status or "Outbound")

    local Source = Entry.Source

    if Status == "Outbound" and Age >= 0.30 then
        Status = "Sent"

        Source = "send-no-ack"
    end

    if ( Status == "Outbound" or Status == "Sent" or Status == "PatchedSent" or Status == "ReplaySent" ) and Age >= 0.85 and (
            tonumber(AntiAimRakNetState.ReceiveSeen) or 0 ) > 0 and ( tonumber(AntiAimRakNetState.ReceivePayloadMatches) or 0 ) <= 0
    then
        Status = "NoEcho"

        Source = "receive-no-self-echo"
    end

    return Status, Source, Age, Entry.ReceivePosition
end

function RegisterAtramentaPendingReplica(Sequence, Payload, Position, CurrentTime, Status)
    if type(Payload) ~= "string" or #Payload ~= 12 or typeof(Position) ~= "Vector3" then return end

    local Pending = AntiAimRakNetState.ReplicaPending

    if type(Pending) ~= "table" then
        Pending = {}

        AntiAimRakNetState.ReplicaPending = Pending
    end

    Pending[#Pending + 1] = { Sequence = Sequence, Payload = Payload, Position = Position, Time = CurrentTime }

    while #Pending > 28 do
        table.remove( Pending, 1)
    end

    local Verification = AntiAimRakNetState.ReplicaVerification

    if type(Verification) ~= "table" then
        Verification = {}

        AntiAimRakNetState.ReplicaVerification = Verification
    end

    Verification[Sequence] = { Status = tostring( Status or "Outbound" ), Source = Status == "PatchedSent" and "setdata-send" or "send",
        Time = CurrentTime, ReceivePosition = nil }

    local MinimumSequence = math.max( 0, Sequence - 48)

    for StoredSequence in pairs( Verification ) do
        if type(StoredSequence) == "number" and StoredSequence < MinimumSequence then Verification[ StoredSequence ] = nil end
    end
end

function MarkAtramentaReplicaVerification(Sequence, Status, Source, ReceivePosition, CurrentTime)
    Sequence = tonumber(Sequence)

    if not Sequence then return end

    local Verification = AntiAimRakNetState.ReplicaVerification

    if type(Verification) ~= "table" then
        Verification = {}

        AntiAimRakNetState.ReplicaVerification = Verification
    end

    Verification[Sequence] = { Status = tostring( Status or "Outbound" ), Source = Source, Time = tonumber(CurrentTime) or os.clock(),
        ReceivePosition = ReceivePosition }

    if Status == "Confirmed" then
        AntiAimRakNetState.LastVerifiedSequence = math.max( tonumber(AntiAimRakNetState.LastVerifiedSequence) or 0, Sequence)
    elseif Status == "Correction" or Status == "Mismatch" then
        AntiAimRakNetState.LastCorrectionSequence = math.max( tonumber(AntiAimRakNetState.LastCorrectionSequence) or 0, Sequence)

        AntiAimRakNetState.ReceiveCorrections = ( tonumber(AntiAimRakNetState.ReceiveCorrections) or 0 ) + 1
    end
end

function FindAtramentaPendingReplicaByPosition(Position, CurrentTime)
    if typeof(Position) ~= "Vector3" then return nil, math.huge end

    local Pending = AntiAimRakNetState.ReplicaPending

    if type(Pending) ~= "table" then return nil, math.huge end

    local Best local BestDistance = math.huge

    for Index = #Pending, 1, -1 do
        local Entry = Pending[Index]

        if type(Entry) == "table" then
            local Age = CurrentTime - ( tonumber(Entry.Time) or 0)

            if Age > 1.50 then break end

            if typeof(Entry.Position)
                == "Vector3"
            then
                local Distance = ( Entry.Position - Position ).Magnitude

                if Distance < BestDistance then
                    BestDistance = Distance

                    Best = Entry
                end
            end
        end
    end

    return Best, BestDistance
end

function ProcessAtramentaReceiveVerification(Packet)
    local Controller = AntiAimRakNetState

    local Data = Packet and Packet.AsString

    if type(Data) ~= "string" then return end

    Controller.ReceiveSeen = ( tonumber(Controller.ReceiveSeen) or 0 ) + 1

    local CurrentTime = os.clock()

    Controller.LastReceiveTime = CurrentTime

    local Pending = Controller.ReplicaPending

    if type(Pending) == "table" then
        for Index = #Pending, 1, -1 do
            local Entry = Pending[Index]

            if type(Entry) == "table" then
                local Age = CurrentTime - ( tonumber(Entry.Time) or 0)

                if Age > 1.50 then break end

                if type(Entry.Payload) == "string" and #Entry.Payload == 12 and string.find( Data, Entry.Payload, 1, true ) then
                    Controller.ReceivePayloadMatches = ( tonumber(Controller.ReceivePayloadMatches) or 0 ) + 1

                    MarkAtramentaReplicaVerification( Entry.Sequence, "Confirmed", "receive-exact-anywhere", Entry.Position, CurrentTime)

                    break
                end
            end
        end
    end

    if string.byte( Data, 1 ) == 0xA1 then return end

    local EntityKey = Controller.PhysicsEntityKey

    if type(EntityKey) ~= "string" or #EntityKey ~= 4 then return end

    local KeyPosition = string.find( Data, EntityKey, 1, true)

    if not KeyPosition then return end

    Controller.ReceiveEntityHits = ( tonumber(Controller.ReceiveEntityHits) or 0 ) + 1

    local Header = string.char( 0x83, 0x05, 0x06 ) .. EntityKey

    local SearchFrom = 1

    while true do
        local RecordStart = string.find( Data, Header, SearchFrom, true)

        if not RecordStart then break end

        Controller.ReceivePhysicsHits = ( tonumber(Controller.ReceivePhysicsHits) or 0 ) + 1

        local PayloadStart = RecordStart + 15

        local PayloadEnd = PayloadStart + 11

        if PayloadEnd <= #Data then
            local ReceivePayload = string.sub( Data, PayloadStart, PayloadEnd)

            local ReceivePosition = UnpackAtramentaRawVector3( ReceivePayload)

            if ReceivePosition then
                local Pending, Distance = FindAtramentaPendingReplicaByPosition( ReceivePosition, CurrentTime)

                if Pending and Distance <= 0.85 then
                    Controller.ReceivePayloadMatches = ( tonumber(Controller.ReceivePayloadMatches) or 0 ) + 1

                    local ExactPayload = type(Pending.Payload)
                            == "string" and ReceivePayload
                            == Pending.Payload

                    MarkAtramentaReplicaVerification( Pending.Sequence, "Confirmed", ExactPayload and "receive-exact" or "receive-position",
                        ReceivePosition, CurrentTime)
                else
                    local Latest = Controller.LocalServerReplica

                    local LatestPosition = Latest and typeof( Latest.RawPosition ) == "Vector3" and Latest.RawPosition or Latest and typeof(
                                Latest.RootCFrame ) == "CFrame" and Latest.RootCFrame.Position or nil

                    local Character = LocalPlayer.Character

                    local Root = Character and ResolverGetRoot( Character)

                    local LivePosition = Root and Root.Position or nil

                    if Latest and Latest.Sequence and typeof(LatestPosition)
                            == "Vector3" and ( ReceivePosition
                            - LatestPosition ).Magnitude > 1.50
                    then
                        local ReceiveNearLive = typeof(LivePosition)
                                == "Vector3" and ( ReceivePosition
                                - LivePosition ).Magnitude <= 1.25

                        local FakeSeparated = typeof(LivePosition)
                                == "Vector3" and ( LatestPosition
                                - LivePosition ).Magnitude >= 1.25

                        if ReceiveNearLive and FakeSeparated then
                            MarkAtramentaReplicaVerification( Latest.Sequence, "Correction", "receive", ReceivePosition, CurrentTime)
                        end
                    end
                end
            end
        end

        SearchFrom = RecordStart + 1
    end
end

function UpdateAtramentaLocalCorrectionVerification()
    if not BacktrackVisualState or BacktrackVisualState.ReplicationVerification
            ~= true
    then
        return
    end

    local Character = LocalPlayer.Character

    local Root = Character and ResolverGetRoot( Character)

    if not Root or not Root.Parent then
        AntiAimRakNetState.PreviousLocalPosition = nil

        AntiAimRakNetState.PreviousLocalVelocity = nil

        return
    end

    local CurrentTime = os.clock()

    local CurrentPosition = Root.Position

    local CurrentVelocity = Root.AssemblyLinearVelocity

    local PreviousPosition = AntiAimRakNetState.PreviousLocalPosition

    local PreviousVelocity = AntiAimRakNetState.PreviousLocalVelocity

    local PreviousTime = tonumber(AntiAimRakNetState.PreviousLocalCorrectionTime) or 0

    AntiAimRakNetState.PreviousLocalPosition = CurrentPosition

    AntiAimRakNetState.PreviousLocalVelocity = CurrentVelocity

    AntiAimRakNetState.PreviousLocalCorrectionTime = CurrentTime

    if typeof(PreviousPosition) ~= "Vector3" or typeof(PreviousVelocity) ~= "Vector3" or PreviousTime <= 0 then return end

    local DeltaTime = math.clamp( CurrentTime - PreviousTime, 0, 0.10)

    if DeltaTime <= 0 then return end

    local Expected = PreviousPosition + PreviousVelocity * DeltaTime

    local CorrectionDistance = ( CurrentPosition - Expected ).Magnitude

    if CorrectionDistance < 2.25 then return end

    local Replica = AntiAimRakNetState.LocalServerReplica

    if type(Replica) ~= "table" or not Replica.Sequence or CurrentTime
            - ( tonumber(AntiAimRakNetState.LocalServerReplicaLastSend) or 0 ) > 0.45
    then
        return
    end

    local ReplicaPosition = typeof(Replica.RawPosition)
            == "Vector3" and Replica.RawPosition or typeof(Replica.RootCFrame)
            == "CFrame" and Replica.RootCFrame.Position or nil

    if typeof(ReplicaPosition) ~= "Vector3" then return end

    local BeforeDistance = ( PreviousPosition - ReplicaPosition ).Magnitude

    local AfterDistance = ( CurrentPosition - ReplicaPosition ).Magnitude

    if AfterDistance + 0.75
        < BeforeDistance
    then
        MarkAtramentaReplicaVerification( Replica.Sequence, "Confirmed", "local-correction", CurrentPosition, CurrentTime)
    end
end

function FindAtramentaPhysicsPositionField(Data, RootPosition)
    if type(Data) ~= "string" or #Data < 12 or typeof(RootPosition) ~= "Vector3" then return nil, nil end

    local Controller = AntiAimRakNetState

    Controller.PhysicsPositionSamples = ( tonumber(Controller.PhysicsPositionSamples) or 0 ) + 1

    local CachedOffset = math.floor( tonumber(Controller.PhysicsPositionOffset) or 0)

    local function ReadAt(Offset)
        if Offset < 1 or Offset + 11 > #Data then return nil end

        return UnpackAtramentaRawVector3( string.sub( Data, Offset, Offset + 11 ))
    end

    if CachedOffset > 0 then
        local CachedPosition = ReadAt( CachedOffset)

        if typeof(CachedPosition) == "Vector3" then
            local Error = ( CachedPosition - RootPosition ).Magnitude

            if Error <= 1.35 then
                Controller.PhysicsPositionConfidence = math.min( ( tonumber(Controller.PhysicsPositionConfidence) or 0 ) + 1, 120)

                Controller.PhysicsPositionValidated = Controller.PhysicsPositionConfidence
                        >= 3

                return CachedOffset, CachedPosition
            end
        end
    end

    local BestOffset local BestPosition local BestError = math.huge

    local MaximumOffset = math.min( #Data - 11, 240)

    for Offset = 1, MaximumOffset do
        local Position = ReadAt( Offset)

        if typeof(Position) == "Vector3" then
            local Error = ( Position - RootPosition ).Magnitude

            if Error < BestError then
                BestError = Error

                BestOffset = Offset

                BestPosition = Position
            end
        end
    end

    if BestOffset and BestError <= 0.85 then
        if BestOffset
            == CachedOffset
        then
            Controller.PhysicsPositionConfidence = math.min( ( tonumber(Controller.PhysicsPositionConfidence) or 0 ) + 1, 120)
        else
            Controller.PhysicsPositionOffset = BestOffset

            Controller.PhysicsPositionConfidence = 1
        end

        Controller.PhysicsPositionValidated = Controller.PhysicsPositionConfidence
                >= 3

        return BestOffset, BestPosition
    end

    Controller.PhysicsPositionMisses = ( tonumber(Controller.PhysicsPositionMisses) or 0 ) + 1

    Controller.PhysicsPositionConfidence = math.max( ( tonumber(Controller.PhysicsPositionConfidence) or 0 ) - 1, 0)

    if Controller.PhysicsPositionConfidence <= 0 then
        Controller.PhysicsPositionOffset = 0

        Controller.PhysicsPositionValidated = false
    end

    return nil, nil
end

function CaptureAtramentaLocalReplicaSnapshot(CurrentTime)
    local Character = LocalPlayer.Character

    local Root = Character and ResolverGetRoot( Character)

    if not Character or not Root or not Root.Parent then return nil end

    local Parts = {}

    if BacktrackVisualState and type( BacktrackVisualState.BodyParts ) == "table" then
        for Name in pairs( BacktrackVisualState.BodyParts ) do
            local Part = Character:FindFirstChild( Name)

            if Part and Part:IsA("BasePart") and Part.Parent == Character and Part.Size.Magnitude <= 12 then Parts[Name] = Part.CFrame end
        end
    end

    return { Time = CurrentTime, Character = Character, RootCFrame = Root.CFrame, Parts = Parts }
end

function CloneAtramentaReplicaSnapshot(Snapshot, CurrentTime)
    if type(Snapshot) ~= "table" or typeof(Snapshot.RootCFrame)
            ~= "CFrame"
    then
        return nil
    end

    local Parts = {}

    if type(Snapshot.Parts) == "table" then
        for Name, PartCFrame in pairs( Snapshot.Parts ) do
            if typeof(PartCFrame)
                == "CFrame"
            then
                Parts[Name] = PartCFrame
            end
        end
    end

    return { Time = tonumber(CurrentTime) or os.clock(), Character = Snapshot.Character, RootCFrame = Snapshot.RootCFrame, Parts = Parts }
end

function CommitAtramentaLocalServerReplica(Snapshot, CurrentTime, Payload, WasPatched, Strategy)
    local Copy = CloneAtramentaReplicaSnapshot( Snapshot, CurrentTime)

    if not Copy then return false end

    AntiAimRakNetState.LocalServerReplicaSequence = ( tonumber(AntiAimRakNetState.LocalServerReplicaSequence) or 0 ) + 1

    Copy.Sequence = AntiAimRakNetState.LocalServerReplicaSequence

    Copy.FakeLag = HideHeadController.FakeLagEnabled
            == true

    Copy.FakePosition = HideHeadController.FakePositionEnabled
            == true

    Copy.FakePositionMode = tostring( HideHeadController.FakePositionMode or "Backtrack")

    Copy.FakePositionDelay = HideHeadController.FakePositionDelay

    Copy.FakePositionJitterRange = HideHeadController.FakePositionJitterRange

    Copy.FakePositionJitterSign = tonumber(AntiAimRakNetState.PhysicsJitterSign) or 1

    Copy.BlockedBeforeSend = tonumber(AntiAimRakNetState.LocalServerReplicaBlocked) or 0

    Copy.RawPayload = type(Payload) == "string" and #Payload == 12 and Payload or nil

    Copy.RawPosition = Copy.RootCFrame.Position

    Copy.PhysicsStrategy = tostring( Strategy or ( WasPatched and "OpaqueReplay" or "Real" ))

    AntiAimRakNetState.LocalServerReplica = Copy

    AntiAimRakNetState.LocalServerReplicaLastSend = tonumber(CurrentTime) or os.clock()

    AntiAimRakNetState.LocalServerReplicaBlocked = 0

    if Copy.RawPayload and typeof(Copy.RawPosition)
            == "Vector3"
    then
        AntiAimRakNetState.LastSentPhysicsPayload = Copy.RawPayload

        AntiAimRakNetState.LastSentPhysicsPosition = Copy.RawPosition

        AntiAimRakNetState.LastSentPhysicsTime = tonumber(CurrentTime) or os.clock()

        RegisterAtramentaPendingReplica( Copy.Sequence, Copy.RawPayload, Copy.RawPosition, tonumber(CurrentTime) or os.clock(), WasPatched == true
                and ( ( Copy.PhysicsStrategy == "RawXYZ" and "PatchedSent" or "ReplaySent" ) ) or "Outbound")
    end

    return true
end

function GetAtramentaLocalServerReplicaSnapshot(CurrentTime)
    local Snapshot = AntiAimRakNetState.LocalServerReplica

    if type(Snapshot) ~= "table" or typeof(Snapshot.RootCFrame)
            ~= "CFrame"
    then
        return nil
    end

    local Copy = CloneAtramentaReplicaSnapshot( Snapshot, Snapshot.Time)

    if not Copy then return nil end

    Copy.Sequence = Snapshot.Sequence

    Copy.FakeLag = Snapshot.FakeLag

    Copy.FakePosition = Snapshot.FakePosition

    Copy.FakePositionMode = Snapshot.FakePositionMode

    Copy.FakePositionDelay = Snapshot.FakePositionDelay

    Copy.FakePositionJitterRange = Snapshot.FakePositionJitterRange

    Copy.FakePositionJitterSign = Snapshot.FakePositionJitterSign

    Copy.BlockedBeforeSend = Snapshot.BlockedBeforeSend

    Copy.RawPayload = Snapshot.RawPayload

    Copy.RawPosition = Snapshot.RawPosition

    local VerificationStatus, VerificationSource, VerificationAge, VerificationReceivePosition = GetAtramentaReplicaVerification( Snapshot.Sequence,
            CurrentTime)

    Copy.VerificationStatus = VerificationStatus

    Copy.VerificationSource = VerificationSource

    Copy.VerificationAge = VerificationAge

    Copy.VerificationReceivePosition = VerificationReceivePosition

    Copy.Age = math.max( 0, ( tonumber(CurrentTime) or os.clock()) - ( tonumber(Snapshot.Time) or 0 ))

    return Copy
end

function PushAtramentaPhysicsPayload(Payload, CurrentTime, Snapshot, Offset, Strategy)
    if type(Payload) ~= "string" or #Payload ~= 12 then return nil end

    local History = AntiAimRakNetState.PhysicsHistory

    if type(History) ~= "table" then
        History = {}

        AntiAimRakNetState.PhysicsHistory = History
    end

    local Entry = { Time = CurrentTime, Payload = Payload, Offset = tonumber(Offset), Strategy = tostring( Strategy or "OpaqueReplay" ), Snapshot =
            CloneAtramentaReplicaSnapshot( Snapshot, CurrentTime ) }

    History[#History + 1] = Entry

    local MinimumTime = CurrentTime - 0.85

    while #History > 72 do
        table.remove( History, 1)
    end

    while #History > 2 and ( tonumber( History[1].Time ) or 0 ) < MinimumTime do
        table.remove( History, 1)
    end

    return Entry
end

function GetAtramentaDelayedPhysicsEntry(CurrentTime, Delay, Offset, Strategy)
    local History = AntiAimRakNetState.PhysicsHistory

    if type(History) ~= "table" or #History < 2 then return nil end

    local WantedTime = CurrentTime - math.clamp( tonumber(Delay) or 0.16, 0.05, 0.40)

    for Index = #History, 1, -1 do
        local Entry = History[Index]

        if type(Entry) == "table" and type(Entry.Payload) == "string" and ( Offset == nil or tonumber(Entry.Offset)
                    == tonumber(Offset) ) and ( Strategy == nil or tostring(Entry.Strategy)
                    == tostring(Strategy) ) and ( tonumber(Entry.Time) or math.huge ) <= WantedTime
        then
            return Entry
        end
    end

    return nil
end

function GetAtramentaDelayedPhysicsPayload(CurrentTime, Delay)
    local Entry = GetAtramentaDelayedPhysicsEntry( CurrentTime, Delay, nil, nil)

    return Entry and Entry.Payload or nil
end

function RewriteAtramentaPhysicsPacket(Packet, Data, CurrentEntry)
    local CurrentSnapshot = type(CurrentEntry) == "table" and CurrentEntry.Snapshot or nil

    if not HideHeadController.FakePositionEnabled or not IsAtramentaPhysicsPacket( Packet, Data ) or type(CurrentEntry) ~= "table"
        or type(CurrentEntry.Body) ~= "string"
    then
        return false, CurrentSnapshot, nil, nil
    end

    local CurrentTime = os.clock()

    AntiAimRakNetState.PhysicsProtectCurrent = false

    if AntiAimRakNetState.PhysicsForceRealNext == true then
        AntiAimRakNetState.PhysicsForceRealNext = false

        AntiAimRakNetState.PhysicsProtectCurrent = true

        AntiAimRakNetState.PhysicsRealRestoreCount = ( tonumber(AntiAimRakNetState.PhysicsRealRestoreCount) or 0 ) + 1

        return false, CurrentSnapshot, "A1RealRestore", nil
    end

    local Mode = tostring( HideHeadController.FakePositionMode or "Backtrack")

    local LastRewrite = tonumber(AntiAimRakNetState.PhysicsPacketLastRewrite) or 0

    local Interval = math.clamp( tonumber(AntiAimRakNetState.PhysicsPacketRewriteInterval) or 0.09, 0.05, 0.25)

    if Mode == "Jitter" then Interval = math.clamp( tonumber(HideHeadController.FakePositionInterval) or 0.12, 0.06, 0.25) end

    if CurrentTime - LastRewrite < Interval then return false, CurrentSnapshot, "A1Wait", nil end

    local ReplacementEntry

    local ReplacementStrategy = "A1SafeReplay"

    if Mode == "Jitter" then
        AntiAimRakNetState.PhysicsJitterSequence = ( tonumber(AntiAimRakNetState.PhysicsJitterSequence) or 0 ) + 1

        local Sequence = AntiAimRakNetState.PhysicsJitterSequence

        local Sign = Sequence % 2 == 0 and 1 or -1

        AntiAimRakNetState.PhysicsJitterSign = Sign

        local BaseDelay = math.clamp( tonumber(HideHeadController.FakePositionDelay) or 0.22, 0.05, 0.40)

        local JitterRange = math.clamp( tonumber(HideHeadController.FakePositionJitterRange) or 0.08, 0.02, 0.18)

        local JitterDelay = math.clamp( BaseDelay + Sign * JitterRange, 0.05, 0.40)

        AntiAimRakNetState.PhysicsJitterDelay = JitterDelay

        ReplacementEntry = GetAtramentaDelayedPhysicsPacket( CurrentEntry, CurrentTime, JitterDelay)

        if type(ReplacementEntry) ~= "table" then ReplacementEntry = GetAtramentaDelayedPhysicsPacket( CurrentEntry, CurrentTime, BaseDelay) end

        ReplacementStrategy = Sign > 0 and "A1JitterFar" or "A1JitterNear"
    elseif Mode == "Freeze" then
        local Anchor = AntiAimRakNetState.PhysicsPacketAnchor

        if type(Anchor) ~= "table" or Anchor.Signature ~= CurrentEntry.Signature or Anchor.Size ~= CurrentEntry.Size then
            AntiAimRakNetState.PhysicsPacketAnchor = CurrentEntry

            Anchor = CurrentEntry
        end

        ReplacementEntry = Anchor else
        local Delayed = GetAtramentaDelayedPhysicsPacket( CurrentEntry, CurrentTime, HideHeadController.FakePositionDelay)

        if Mode == "Pulse" then
            local PulseInterval = math.clamp( tonumber(HideHeadController.FakePositionInterval) or 0.16, 0.06, 0.50)

            if CurrentTime
                - ( tonumber(AntiAimRakNetState.PhysicsPulseTime) or 0 ) >= PulseInterval
            then
                AntiAimRakNetState.PhysicsPulseTime = CurrentTime

                AntiAimRakNetState.PhysicsPulseState = not AntiAimRakNetState.PhysicsPulseState
            end

            if AntiAimRakNetState.PhysicsPulseState then ReplacementEntry = Delayed end
        else
            ReplacementEntry = Delayed
        end
    end

    if type(ReplacementEntry) ~= "table" or type(ReplacementEntry.Body) ~= "string" or ReplacementEntry == CurrentEntry
        or ReplacementEntry.Size ~= CurrentEntry.Size or ReplacementEntry.HeaderLength ~= CurrentEntry.HeaderLength
    then
        return false, CurrentSnapshot, "A1Wait", nil
    end

    local HeaderLength = tonumber(CurrentEntry.HeaderLength)

    if not HeaderLength or HeaderLength < 1 or HeaderLength >= #Data then return false, CurrentSnapshot, "A1Wait", nil end

    local CurrentBody = string.sub( Data, HeaderLength + 1)

    if #ReplacementEntry.Body ~= #CurrentBody or ReplacementEntry.Body == CurrentBody then return false, CurrentSnapshot, "A1Wait", nil end

    local SetData = Packet and Packet.SetData

    if type(SetData) ~= "function" then return false, CurrentSnapshot, "A1NoSetData", nil end

    local NewData = string.sub( Data, 1, HeaderLength ) .. ReplacementEntry.Body

    if #NewData ~= #Data then return false, CurrentSnapshot, "A1Wait", nil end

    SetData( Packet, NewData)

    AntiAimRakNetState.PhysicsPacketLastRewrite = CurrentTime

    AntiAimRakNetState.PhysicsForceRealNext = true

    AntiAimRakNetState.PhysicsProtectCurrent = true

    AntiAimRakNetState.PhysicsPatched = ( tonumber(AntiAimRakNetState.PhysicsPatched) or 0 ) + 1

    AntiAimRakNetState.PhysicsReplayPatched = ( tonumber(AntiAimRakNetState.PhysicsReplayPatched) or 0 ) + 1

    AntiAimRakNetState.PhysicsPacketPatched = ( tonumber(AntiAimRakNetState.PhysicsPacketPatched) or 0 ) + 1

    AntiAimRakNetState.PhysicsStrategy = ReplacementStrategy

    local EffectiveSnapshot = type(ReplacementEntry.Snapshot) == "table" and CloneAtramentaReplicaSnapshot( ReplacementEntry.Snapshot, CurrentTime) or CurrentSnapshot

    return true, EffectiveSnapshot, ReplacementStrategy, HeaderLength + 1
end

function InstallAntiAimRakNetHook()
    local State = rawget(Environment, "AtramentaAntiAimRakNet")

    if type(State) ~= "table" then
        State = { Installed = false, ReceiveInstalled = false, Controller = AntiAimRakNetState }
        rawset(Environment, "AtramentaAntiAimRakNet", State)
    end

    State.Controller = AntiAimRakNetState

    local RakNetObject = rawget( Environment, "raknet" ) or rawget( _G, "raknet")

    local AddSendHook = type(RakNetObject) == "table" and RakNetObject.add_send_hook or nil

    local AddReceiveHook = type(RakNetObject) == "table" and RakNetObject.add_receive_hook or nil

    if type(AddSendHook) ~= "function" then return false end

    if not State.Installed then
        State.Installed = true

        AddSendHook( function(Packet)
                local Controller = State.Controller

                if type(Controller) ~= "table" then return Packet end

                local Data = Packet and Packet.AsString

                if type(Data) ~= "string" then return Packet end

                Controller.SeenPackets = ( tonumber(Controller.SeenPackets) or 0 ) + 1

                Controller.LastPacketTime = os.clock()

                Controller.LastPacketSize = #Data

                local NetworkEnabled = HideHeadEnabled or HideHeadController.FakeLagEnabled or HideHeadController.FakeDirectionEnabled
                    or HideHeadController.FakePositionEnabled or ( FlyEnabled == true and FlyMethod == "Velocity")

                if not NetworkEnabled then return Packet end

                local IsMovement = IsAtramentaRawMovementRecord( Data)

                local IsPhysics = IsAtramentaPhysicsPacket( Packet, Data)

                if IsMovement then
                    Controller.RawMovementSeen = ( tonumber(Controller.RawMovementSeen) or 0 ) + 1

                    Controller.MatchedPackets = Controller.RawMovementSeen

                    Controller.RawLastPacketSize = #Data

                    Controller.RawLastPacketTime = os.clock()

                    RewriteAtramentaRawMovementRecord( Packet, Data)

                    Data = Packet.AsString or Data
                end

                local PhysicsCurrentEntry local PhysicsEffectiveSnapshot local PhysicsEffectiveOffset local PhysicsEffectiveStrategy
                local PhysicsWasPatched = false

                if IsPhysics then
                    local PhysicsTime = os.clock()

                    Controller.PhysicsSeen = ( tonumber(Controller.PhysicsSeen) or 0 ) + 1

                    Controller.PhysicsLastPacketTime = PhysicsTime

                    local CurrentSnapshot = CaptureAtramentaLocalReplicaSnapshot( PhysicsTime)

                    PhysicsCurrentEntry = PushAtramentaPhysicsPacket( Data, PhysicsTime, CurrentSnapshot)

                    PhysicsWasPatched, PhysicsEffectiveSnapshot, PhysicsEffectiveStrategy, PhysicsEffectiveOffset = RewriteAtramentaPhysicsPacket(
                            Packet, Data, PhysicsCurrentEntry)

                    PhysicsEffectiveSnapshot = PhysicsEffectiveSnapshot or CurrentSnapshot

                    PhysicsEffectiveStrategy = PhysicsEffectiveStrategy or "A1Current"

                    PhysicsEffectiveOffset = PhysicsEffectiveOffset or 18

                    Data = Packet.AsString or Data
                end

                local PhysicsWasBlocked = false

                if HideHeadController.FakeLagEnabled then
                    local Block = Packet and Packet.Block

                    if type(Block) == "function" then
                        local Limit = math.clamp( math.floor( tonumber(HideHeadController.FakeLagLimit) or 2 ), 1, 8)

                        local ShouldBlock = false

                        local Protected = IsPhysics and Controller.PhysicsProtectCurrent == true

                        local Slot = 0

                        if IsMovement and #Data <= 96 then
                            Controller.RawLagSequence = ( tonumber(Controller.RawLagSequence) or 0 ) + 1

                            Slot = Controller.RawLagSequence % ( Limit + 1)

                            ShouldBlock = Slot ~= 0
                        elseif IsPhysics then
                            Controller.PhysicsLagSequence = ( tonumber(Controller.PhysicsLagSequence) or 0 ) + 1

                            Slot = Controller.PhysicsLagSequence % ( Limit + 1)

                            ShouldBlock = not Protected and Slot ~= 0
                        end

                        if IsMovement or IsPhysics then
                            UpdateAtramentaFakeLagTelemetry( ShouldBlock and "HOLD" or ( Protected and "PASS" or "SEND" ), Protected, Slot, os.clock()
)
                        end

                        if ShouldBlock then
                            Block( Packet)

                            if IsPhysics then
                                PhysicsWasBlocked = true

                                Controller.LocalServerReplicaLastBlock = os.clock()

                                Controller.LocalServerReplicaBlocked = ( tonumber(Controller.LocalServerReplicaBlocked) or 0 ) + 1

                                Controller.PhysicsBlocked = ( tonumber(Controller.PhysicsBlocked) or 0 ) + 1

                                local HeldReplica = Controller.LocalServerReplica

                                if type(HeldReplica) == "table" and HeldReplica.Sequence then
                                    MarkAtramentaReplicaVerification( HeldReplica.Sequence, "ChokeHold", "packet-block", HeldReplica.RawPosition,
                                        os.clock())
                                end
                            else
                                Controller.RawMovementBlocked = ( tonumber(Controller.RawMovementBlocked) or 0 ) + 1
                            end

                            Controller.BlockedPackets = ( tonumber(Controller.PhysicsBlocked) or 0 ) + ( tonumber(Controller.RawMovementBlocked) or 0
)
                        else
                            Controller.RealSyncPackets = ( tonumber(Controller.RealSyncPackets) or 0 ) + 1
                        end
                    end
                end

                if IsPhysics and not PhysicsWasBlocked and PhysicsEffectiveSnapshot then
                    local FinalData = Packet.AsString or Data

                    local FingerprintOffset = math.max( math.floor( tonumber(PhysicsEffectiveOffset) or 18 ), 1)

                    local FinalPayload = type(FinalData) == "string" and FingerprintOffset + 11
                            <= #FinalData and string.sub( FinalData, FingerprintOffset, FingerprintOffset + 11 ) or nil

                    CommitAtramentaLocalServerReplica( PhysicsEffectiveSnapshot, os.clock(), FinalPayload, PhysicsWasPatched, PhysicsEffectiveStrategy
)
                end

                return Packet
            end)
    end

    if type(AddReceiveHook) == "function" and not State.ReceiveInstalled then
        State.ReceiveInstalled = true

        AntiAimRakNetState.ReceiveInstalled = true

        AddReceiveHook( function(Packet)
                if State.Controller
                    == AntiAimRakNetState
                then
                    ProcessAtramentaReceiveVerification( Packet)
                end

                return Packet
            end)
    end

    return true
end

function GetHideHeadNeck(Character)
    if not Character then return nil end

    local Neck = Character:FindFirstChild( "Neck", true)

    return Neck and Neck:IsA( "Motor6D" ) and Neck or nil
end

function UpdateManualAntiAimIndicator()
    local Visible = HideHeadController.ManualIndicator == true and HideHeadEnabled == true

    local Indicator = HideHeadController.ManualIndicatorObject

    if not Indicator or type(Indicator) ~= "table" or not Indicator.Root or not Indicator.Root.Parent then
        if type(Library) ~= "table" or type(Library.AntiAimIndicator) ~= "function" then return end

        Indicator = Library:AntiAimIndicator({ Visible = false, Player = LocalPlayer, Mode = GetAntiAimMode(),
                Profile = NormalizeManualAntiAimDirection( HideHeadController.ManualDirection ), Network = "Normal", Yaw = 0 })

        HideHeadController.ManualIndicatorObject = Indicator end

    if not Indicator then return end

    if type(Indicator.SetVisibility) == "function" then Indicator:SetVisibility( Visible) end

    if not Visible then return end

    local Mode = GetAntiAimMode()

    local Profile

    if Mode == "Manual" then
        Profile = NormalizeManualAntiAimDirection( HideHeadController.ManualDirection)
    elseif Mode == "Down" then
        Profile = "Down"
    else
        Profile = "Spin"
    end

    local _, Yaw = GetAntiAimAngles()

    local Network = {}

    if HideHeadController.FakeLagEnabled then Network[#Network + 1] = GetAtramentaFakeLagTelemetryText() end

    if HideHeadController.FakePositionEnabled then
        local PhysicsPatched = tonumber(AntiAimRakNetState.PhysicsPatched) or 0

        local Strategy = tostring( AntiAimRakNetState.PhysicsStrategy or "Calibrating")

        if Strategy == "A1JitterNear" or Strategy == "A1JitterFar" then
            Network[#Network + 1] = "Pos:JIT:" .. ( Strategy == "A1JitterFar" and "F" or "N" ) .. ":" .. string.format( "%.2f",
                    tonumber(AntiAimRakNetState.PhysicsJitterDelay) or 0 ) .. "/" .. tostring( tonumber(AntiAimRakNetState.PhysicsPacketPatched) or 0
                ) .. "/R:" .. tostring( tonumber(AntiAimRakNetState.PhysicsRealRestoreCount) or 0)
        elseif Strategy == "A1SafeReplay" then
            Network[#Network + 1] = "Pos:SAFE:" .. tostring( tonumber(AntiAimRakNetState.PhysicsPacketPatched) or 0 ) .. "/R:" .. tostring(
                    tonumber(AntiAimRakNetState.PhysicsRealRestoreCount) or 0)
        elseif ( tonumber(AntiAimRakNetState.PhysicsPacketSeen) or 0 ) > 0 then
            Network[#Network + 1] = "Pos:A1WAIT:" .. tostring( tonumber(AntiAimRakNetState.PhysicsPacketSeen) or 0)
        else
            Network[#Network + 1] = "Pos:NO-A1"
        end
    end

    if HideHeadController.FakeDirectionEnabled then Network[#Network + 1] = "Dir:" .. tostring( tonumber(AntiAimRakNetState.RawMovementPatched) or 0) end

    if FlyEnabled == true and FlyMethod == "Velocity" then
        Network[#Network + 1] = "Fly:" .. tostring( AntiAimRakNetState.FlyStatus or "VEL" ) .. "/NET:" .. tostring(
                tonumber(AntiAimRakNetState.FlyMovementPatched) or 0)
    end

    if BacktrackVisualState and BacktrackVisualState.ReplicationVerification == true and type( AntiAimRakNetState.LocalServerReplica ) == "table" then
        local Replica = AntiAimRakNetState.LocalServerReplica

        local Status = GetAtramentaReplicaVerification( Replica.Sequence, os.clock())

        Network[#Network + 1] = Status == "Confirmed" and "ACK" or ( Status == "Correction" or Status == "Mismatch" ) and "REJECT"
            or Status == "ChokeHold" and "HOLD" or Status == "PatchedSent" and "PATCHED" or Status == "ReplaySent" and "REPLAY" or Status == "Sent"
                and "SENT" or Status == "NoEcho" and "NO-ECHO" or "WAIT"
    end

    if type(Indicator.SetMode) == "function" then Indicator:SetMode( Mode) end

    if type(Indicator.SetProfile) == "function" then Indicator:SetProfile( Profile) end

    if type(Indicator.SetPlayer) == "function" then Indicator:SetPlayer( LocalPlayer) end

    if type(Indicator.SetNetwork) == "function" then Indicator:SetNetwork( #Network > 0 and table.concat( Network, " + " ) or "Normal") end

    if type(Indicator.SetYaw) == "function" then Indicator:SetYaw( Yaw) end
end

function StepRakNetOnlyAntiAim()
    UpdateAtramentaLocalCorrectionVerification()
    UpdateManualAntiAimIndicator()

    if not HideHeadEnabled then return end

    local Character = LocalPlayer.Character

    local Humanoid = Character and Character:FindFirstChildOfClass( "Humanoid")

    local Root = Character and Character:FindFirstChild( "HumanoidRootPart")

    if not Character or not Humanoid or Humanoid.Health <= 0 or not Root or not Root:IsA("BasePart") then return end

    if AntiAimRakNetState.OriginalAutoRotate == nil then AntiAimRakNetState.OriginalAutoRotate = Humanoid.AutoRotate end

    Humanoid.AutoRotate = false

    local CurrentTime = os.clock()

    if CurrentTime
        - ( tonumber(AntiAimRakNetState.LastLocalStep) or 0 ) >= 1 / 30
    then
        AntiAimRakNetState.LastLocalStep = CurrentTime

        AntiAimRakNetState.LocalSequence = ( tonumber(AntiAimRakNetState.LocalSequence) or 0 ) + 1

        HideHeadController.Sequence = AntiAimRakNetState.LocalSequence
    end

    local Pitch, Yaw = GetAntiAimAngles()

    local Camera = workspace.CurrentCamera

    local BaseLook = Camera and Camera.CFrame.LookVector or Root.CFrame.LookVector

    local FlatLook = Vector3.new( BaseLook.X, 0, BaseLook.Z)

    if FlatLook.Magnitude <= 0.001 then FlatLook = Vector3.new( Root.CFrame.LookVector.X, 0, Root.CFrame.LookVector.Z) end

    if FlatLook.Magnitude <= 0.001 then
        FlatLook = Vector3.new( 0, 0, -1)
    else
        FlatLook = FlatLook.Unit
    end

    local RotatedLook = CFrame.fromAxisAngle( Vector3.yAxis, math.rad( Yaw ) ):VectorToWorldSpace( FlatLook)

    RotatedLook = Vector3.new( RotatedLook.X, 0, RotatedLook.Z)

    if RotatedLook.Magnitude <= 0.001 then return end

    RotatedLook = RotatedLook.Unit

    HideHeadController.LastPitch = Pitch

    HideHeadController.LastYaw = Yaw

    HideHeadController.LastDirection = RotatedLook

    AntiAimRakNetState.LastNetworkYaw = Yaw

    local Position = Root.Position

    Root.CFrame = CFrame.lookAt( Position, Position + RotatedLook, Vector3.yAxis)

    Root.AssemblyAngularVelocity = Vector3.zero

    local Neck = GetHideHeadNeck( Character)

    if Neck then
        if HideHeadController.Neck ~= Neck then
            HideHeadController.Neck = Neck

            HideHeadController.OriginalC0 = Neck.C0

            HideHeadController.OriginalTransform = Neck.Transform
        end

        if typeof( HideHeadController.OriginalTransform ) == "CFrame" then
            Neck.Transform = HideHeadController.OriginalTransform * CFrame.Angles( -math.rad(Pitch) * math.clamp(
                            tonumber(HideHeadController.LocalVisualScale) or 1, 0, 1 ), 0, 0)
        end
    end
end

function ApplyHideHeadLocalPreview()
    StepRakNetOnlyAntiAim()
end

function RestoreHideHeadLocalPreview()
    local Character = LocalPlayer.Character

    local Humanoid = Character and Character:FindFirstChildOfClass( "Humanoid")

    if Humanoid and AntiAimRakNetState.OriginalAutoRotate ~= nil then Humanoid.AutoRotate = AntiAimRakNetState.OriginalAutoRotate end

    AntiAimRakNetState.OriginalAutoRotate = nil

    local Neck = HideHeadController.Neck

    if Neck and Neck.Parent then
        if typeof( HideHeadController.OriginalC0 ) == "CFrame" then Neck.C0 = HideHeadController.OriginalC0 end

        if typeof( HideHeadController.OriginalTransform ) == "CFrame" then Neck.Transform = HideHeadController.OriginalTransform end
    end

    HideHeadController.Neck = nil
        HideHeadController.OriginalC0 = nil
    HideHeadController.OriginalTransform = nil

    if HideHeadController.ManualIndicatorObject and type(HideHeadController.ManualIndicatorObject.SetVisibility) == "function" then
        HideHeadController.ManualIndicatorObject:SetVisibility( false)
    end
end

function BindHideHeadCharacter(Character)
    HideHeadController.Character = Character

    HideHeadController.Neck = nil
        HideHeadController.OriginalC0 = nil
    HideHeadController.OriginalTransform = nil

    task.defer( function()
            for _ = 1, 30 do
                if Character
                        ~= LocalPlayer.Character or not Character.Parent
                then
                    return
                end

                local Neck = GetHideHeadNeck( Character)

                if Neck then
                    HideHeadController.Neck = Neck

                    HideHeadController.OriginalC0 = Neck.C0

                    HideHeadController.OriginalTransform = Neck.Transform

                    return
                end

                task.wait( 0.05)
            end
        end)
end

function BindHideHeadLocalPreview()
    if HideHeadController.PreviewConnection then
        HideHeadController.PreviewConnection:Disconnect()
        HideHeadController.PreviewConnection = nil
    end

    local BindName = HideHeadController.PreviewBindName or "AtramentaAntiAimLocalPreview"

    RunService:UnbindFromRenderStep( BindName)

    RunService:BindToRenderStep( BindName, Enum.RenderPriority.Last.Value, ApplyHideHeadLocalPreview)

    HideHeadController.PreviewBound = true
end

function UnbindHideHeadLocalPreview()
    local BindName = HideHeadController.PreviewBindName or "AtramentaAntiAimLocalPreview"

    RunService:UnbindFromRenderStep( BindName)

    HideHeadController.PreviewBound = false

    if HideHeadController.PreviewConnection then
        HideHeadController.PreviewConnection:Disconnect()
        HideHeadController.PreviewConnection = nil
    end
end

function SetHideHeadEnabled(Value)
    HideHeadEnabled = Value == true

    HideHeadController.Enabled = HideHeadEnabled

    ResetAntiAimNetworkState()

    if not HideHeadController.CharacterConnection then
        HideHeadController.CharacterConnection = LocalPlayer.CharacterAdded:Connect( function(Character)
                    if HideHeadEnabled then
                        ResetAntiAimNetworkState()
                        BindHideHeadCharacter( Character)
                    end
                end)
    end

    if HideHeadEnabled then
        InstallAntiAimRakNetHook()

        if LocalPlayer.Character then BindHideHeadCharacter( LocalPlayer.Character) end

        BindHideHeadLocalPreview()
    else
        UnbindHideHeadLocalPreview()
        RestoreHideHeadLocalPreview()
    end

    UpdateManualAntiAimIndicator()

    return HideHeadEnabled
end

function AntiAFKEnable()
    if AntiAFKEnabled then return end
    AntiAFKEnabled = true

    if AntiAFKThread then
        task.cancel(AntiAFKThread)
        AntiAFKThread = nil
    end

    AntiAFKThread = task.spawn(function()
        while AntiAFKEnabled do
            task.wait(120)
            if AntiAFKEnabled then SendKeyPress(Enum.KeyCode.W, 0.1) end
        end
    end)
end

function AntiAFKDisable()
    if not AntiAFKEnabled then return end
    AntiAFKEnabled = false

    if AntiAFKThread then
        task.cancel(AntiAFKThread)
        AntiAFKThread = nil
    end
end

local SharedAuraTick = 0

function MeleeAuraEnable()
    if MeleeAuraEnabled then return end

    MeleeAuraEnabled = true

    MeleeAuraCoroutine = task.spawn(function()
        while MeleeAuraEnabled do
            if tick() - SharedAuraTick > 0.15 then
                local CharacterModel = LocalPlayer.Character

                if CharacterModel then
                    local RootPart = CharacterModel:FindFirstChild( "HumanoidRootPart")

                    local ToolObject = CharacterModel:FindFirstChildOfClass( "Tool")

                    if RootPart and ToolObject then
                        local Events = ReplicatedStorage:FindFirstChild( "Events")

                        local PrimaryRemote = Events and Events:FindFirstChild( "XMHH.2")

                        local SecondaryRemote = Events and Events:FindFirstChild( "XMHH2.2")

                        if PrimaryRemote and SecondaryRemote then
                            local BestPlayer = nil local BestCharacter = nil local BestHead = nil local BestDistance = math.huge
                            local BestTier = -1 local MaximumDistance = math.clamp( tonumber(MeleeAuraDistance) or 15, 1, 15)

                            for _, PlayerObject in ipairs( Players:GetPlayers() ) do
                                if not IsCombatTargetAllowed( PlayerObject ) then continue end

                                local TargetCharacter = PlayerObject.Character

                                local TargetRootPart = TargetCharacter and TargetCharacter:FindFirstChild( "HumanoidRootPart")

                                local TargetHead = TargetCharacter and TargetCharacter:FindFirstChild( "Head")

                                local TargetHum = TargetCharacter and TargetCharacter:FindFirstChildOfClass( "Humanoid")

                                if TargetRootPart and TargetHead and TargetHum and TargetHum.Health > 0 and not TargetCharacter:FindFirstChildOfClass(
                                            "ForceField" ) then
                                    local DistanceValue = ( RootPart.Position - TargetRootPart.Position ).Magnitude

                                    local Tier = GetCombatTargetPriority( PlayerObject)

                                    if DistanceValue <= MaximumDistance and ( Tier > BestTier or Tier == BestTier and DistanceValue < BestDistance ) then
                                        BestTier = Tier
                                        BestDistance = DistanceValue
                                        BestPlayer = PlayerObject
                                        BestCharacter = TargetCharacter
                                        BestHead = TargetHead
                                    end
                                end
                            end

                            if BestPlayer and BestCharacter and BestHead then
                                SharedAuraTick = tick()

                                local FirstArgument = { [1] = "🍞", [2] = tick(), [3] = ToolObject, [4] = "43TRFWX", [5] = "Normal", [6] = tick(), [7] = true
                                }

                                local Success1, OperationResult = Internal.Call( function()
                                            return PrimaryRemote:InvokeServer( unpack( FirstArgument ))
                                        end)

                                if Success1 then
                                    local Handle = ToolObject:FindFirstChild( "WeaponHandle" ) or ToolObject:FindFirstChild( "Handle" ) or CharacterModel:FindFirstChild( "Right Arm")

                                    if Handle then
                                        local SecondArgument = { [1] = "🍞", [2] = tick(), [3] = ToolObject, [4] = "2389ZFX34", [5] = OperationResult,
                                            [6] = false, [7] = Handle, [8] = BestHead, [9] = BestCharacter, [10] = RootPart.Position,
                                            [11] = BestHead.Position }

                                        Internal.Call( function()
                                                SecondaryRemote:FireServer( unpack( SecondArgument ))
                                            end)
                                    end
                                end
                            end
                        end
                    end
                end
            end

            task.wait(0.1)
        end
    end)
end

function MeleeAuraDisable()
    MeleeAuraEnabled = false
    if MeleeAuraCoroutine then
        task.cancel(MeleeAuraCoroutine)
        MeleeAuraCoroutine = nil
    end
end

function WeaponPerspectiveVisualsActive()
    return WeaponShaderSettings.Enabled == true
        or WeaponChamsEnabled == true
        or ArmsChamsEnabled == true
        or type(GunMaterialChamsState) == "table"
            and GunMaterialChamsState.Enabled == true
end

function WeaponPerspectiveRefreshParts(Tool, Force)
    local State = WeaponPerspectiveState
    local CurrentTime = os.clock()

    if not Tool or not Tool.Parent then
        State.Parts = {}
        State.PartsTool = nil
        State.NextPartsRefresh = 0
        return State.Parts
    end

    if not Force
        and State.PartsTool == Tool
        and CurrentTime < (tonumber(State.NextPartsRefresh) or 0)
    then
        return State.Parts
    end

    local Parts = {}

    for _, Object in ipairs(Tool:GetDescendants()) do
        if Object:IsA("BasePart") then Parts[#Parts + 1] = Object end
    end

    State.Parts = Parts
    State.PartsTool = Tool
    State.NextPartsRefresh = CurrentTime + 0.18
    return Parts
end

function WeaponPerspectiveRepairThirdPerson(Tool)
    if InvisibilityEnabled == true or not Tool or not Tool.Parent then return end

    local Parts = WeaponPerspectiveRefreshParts(Tool, false)

    for Index = 1, #Parts do
        local Part = Parts[Index]

        if Part
            and Part.Parent
            and Part:IsDescendantOf(Tool)
            and Part.LocalTransparencyModifier ~= 0
        then
            Part.LocalTransparencyModifier = 0
        end
    end
end

function WeaponPerspectiveStep()
    if not WeaponPerspectiveVisualsActive() then return end

    local State = WeaponPerspectiveState
    local CurrentTime = os.clock()

    if CurrentTime - (tonumber(State.LastStep) or 0) < 0.035 then return end
    State.LastStep = CurrentTime

    local FirstPerson = IsViewModelFirstPerson()
    local Tool = GetWeaponShaderTarget()
    local PerspectiveChanged = State.LastFirstPerson ~= nil
        and State.LastFirstPerson ~= FirstPerson

    if PerspectiveChanged and FirstPerson == false then
        State.RepairUntil = CurrentTime + 0.72
        WeaponPerspectiveRefreshParts(Tool, true)

        WeaponShaderSettings.Dirty = true
        WeaponShaderSettings.NextRootCheck = 0

        task.defer(function()
            if WeaponShaderSettings.Enabled then RefreshWeaponShaders(true) end

            if type(GunMaterialChamsState) == "table"
                and GunMaterialChamsState.Enabled
                and type(GunMaterialChamsRefreshRoots) == "function"
            then
                GunMaterialChamsRefreshRoots()
            end
        end)
    elseif not FirstPerson and Tool ~= State.LastTool then
        State.RepairUntil = CurrentTime + 0.45
        WeaponPerspectiveRefreshParts(Tool, true)
    end

    State.LastFirstPerson = FirstPerson
    State.LastTool = Tool

    if not FirstPerson and CurrentTime <= (tonumber(State.RepairUntil) or 0) then
        WeaponPerspectiveRepairThirdPerson(Tool)
    end
end

function EnsureWeaponPerspectiveFix()
    local State = WeaponPerspectiveState

    if not WeaponPerspectiveVisualsActive() then
        if State.Connection then
            State.Connection:Disconnect()
            State.Connection = nil
        end

        State.LastFirstPerson = nil
        State.LastTool = nil
        State.RepairUntil = 0
        State.Parts = {}
        State.PartsTool = nil
        return
    end

    if State.Connection then return end

    State.LastFirstPerson = IsViewModelFirstPerson()
    State.LastTool = nil
    State.LastStep = 0

    State.Connection = RunService.Heartbeat:Connect(function()
        Internal.Call(WeaponPerspectiveStep)
    end)
end

function GetWeaponShaderTarget()
    local Character = LocalPlayer.Character
    if not Character then return nil end

    local Equipped = nil

    for _, Object in ipairs(Character:GetChildren()) do
        if Object:IsA("Tool") then
            Equipped = Object
            break
        end
    end

    return Equipped
end

function ScoreCameraViewModelCandidate(Object)
    if not Object or not Object.Parent or ( not Object:IsA("Model") and not Object:IsA("Folder") ) then return -math.huge end

    local Name = string.lower( tostring(Object.Name))

    local Score = 0

    if Name == "viewmodel" or Name == "view model" then
        Score += 100
    elseif Name == "arms" or Name == "armmodel" or Name == "viewarms" then
        Score += 78
    elseif Name:find( "viewmodel", 1, true ) then
        Score += 72
    elseif Name:find( "arms", 1, true ) then
        Score += 48
    end

    local BasePartCount = 0 local ArmCount = 0 local HolderCount = 0 local WeaponLikeCount = 0

    for _, Descendant in ipairs( Object:GetDescendants() ) do
        if Descendant:IsA("BasePart") then
            BasePartCount += 1

            local DescendantName = string.lower( Descendant.Name)

            if DescendantName == "right arm" or DescendantName == "left arm" or DescendantName == "rightarm" or DescendantName == "leftarm" then ArmCount += 1 end

            if DescendantName == "rarmholder" or DescendantName == "larmholder" then HolderCount += 1 end

            if DescendantName:find( "handle", 1, true ) or DescendantName:find( "receiver", 1, true ) or DescendantName:find( "barrel", 1, true)
                or DescendantName:find( "slide", 1, true ) or DescendantName:find( "mag", 1, true ) then
                WeaponLikeCount += 1
            end
        end
    end

    Score += math.min( BasePartCount, 18 ) * 0.75

    Score += ArmCount * 12 + HolderCount * 14 + math.min( WeaponLikeCount, 8 ) * 2.5

    if ArmCount == 0 and HolderCount == 0 and WeaponLikeCount == 0 and Score < 60 then return -math.huge end

    return Score
end

function GetArmsViewModel()
    local CameraObject = Internal.GetCamera()

    if not CameraObject then return nil end

    local Direct = CameraObject:FindFirstChild( "ViewModel" ) or CameraObject:FindFirstChild( "viewmodel" ) or CameraObject:FindFirstChild( "Viewmodel")

    if Direct and ( Direct:IsA("Model") or Direct:IsA("Folder") ) then return Direct end

    local Best = nil local BestScore = -math.huge

    for _, Object in ipairs( CameraObject:GetChildren() ) do
        if Object ~= LocalPlayer.Character and ( Object:IsA("Model") or Object:IsA("Folder") ) then
            local Score = ScoreCameraViewModelCandidate( Object)

            if Score > BestScore then
                BestScore = Score
                Best = Object
            end
        end
    end

    if Best and BestScore >= 48 then return Best end

    return nil
end

function IsViewModelFirstPerson()
    local CameraObject = Internal.GetCamera()
    if not CameraObject then return false end
    if LocalPlayer.CameraMode == Enum.CameraMode.LockFirstPerson then return true end

    local Character = LocalPlayer.Character local Head = Character and Character:FindFirstChild("Head")
    if Head and Head:IsA("BasePart") then
        local HeadDistance = (CameraObject.CFrame.Position - Head.Position).Magnitude
        if HeadDistance <= 1.65 then return true end
    end

    local FocusDistance = (CameraObject.CFrame.Position - CameraObject.Focus.Position).Magnitude
    return FocusDistance <= 1.25
end

function IsViewModelArmPart(Part)
    if not Part or not Part:IsA("BasePart") then return false end

    local Name = Part.Name

    return Name == "Right Arm" or Name == "Left Arm" or Name == "RightArm" or Name == "LeftArm"
end

function IsViewModelExcludedPart(Part, ViewModel)
    if not Part or not Part:IsA("BasePart") then return true end

    local Name = Part.Name

    if Name == "HumanoidRootPart" or Name == "RArmHolder" or Name == "LArmHolder" then return true end

    local Parent = Part.Parent

    while Parent and Parent ~= ViewModel do
        local ParentName = Parent.Name

        if ParentName == "RArmHolder" or ParentName == "LArmHolder" then return true end

        Parent = Parent.Parent
    end

    return false
end

function IsViewModelWeaponPart(Part, ViewModel)
    return Part and Part:IsA("BasePart") and not IsViewModelArmPart(Part) and not IsViewModelExcludedPart( Part, ViewModel)
end

function StoreViewModelPartOriginal(Part)
    if ViewModelChamsRuntime.Original[Part] then return end

    local Mesh = Part:FindFirstChildOfClass("SpecialMesh")

    ViewModelChamsRuntime.Original[Part] = {
        Material = Part.Material,
        Color = Part.Color,
        Transparency = Part.Transparency,
        LocalTransparencyModifier = Part.LocalTransparencyModifier,
        TextureID = Part:IsA("MeshPart") and Part.TextureID or nil,
        SpecialMesh = Mesh,
        SpecialMeshTexture = Mesh and Mesh.TextureId or nil
    }
end

function RestoreViewModelPart(Part)
    local Original = ViewModelChamsRuntime.Original[Part]

    if Original and Part and Part.Parent then
        Part.Material = Original.Material
        Part.Color = Original.Color
        Part.Transparency = Original.Transparency
        Part.LocalTransparencyModifier = Original.LocalTransparencyModifier

        if Part:IsA("MeshPart") and Original.TextureID ~= nil then Part.TextureID = Original.TextureID end

        local Mesh = Original.SpecialMesh
        if Mesh and Mesh.Parent == Part and Original.SpecialMeshTexture ~= nil then Mesh.TextureId = Original.SpecialMeshTexture end
    end

    local Textures = ViewModelChamsRuntime.AnimationTextures[Part]
    if type(Textures) == "table" then
        for Index = 1, #Textures do
            local Texture = Textures[Index]
            if Texture and Texture.Parent then Texture:Destroy() end
        end
    end

    local Highlight = ViewModelChamsRuntime.Highlights[Part]
    if Highlight and Highlight.Parent then Highlight:Destroy() end

    local GlowShell = ViewModelChamsRuntime.GlowShells[Part]
    if GlowShell and GlowShell.Parent then GlowShell:Destroy() end

    local SoftGlowShell = ViewModelChamsRuntime.SoftGlowShells[Part]
    if SoftGlowShell and SoftGlowShell.Parent then SoftGlowShell:Destroy() end

    ViewModelChamsRuntime.Original[Part] = nil
    ViewModelChamsRuntime.Highlights[Part] = nil
    ViewModelChamsRuntime.GlowShells[Part] = nil
    ViewModelChamsRuntime.SoftGlowShells[Part] = nil
    ViewModelChamsRuntime.AnimationTextures[Part] = nil
    ViewModelChamsRuntime.AnimationState[Part] = nil
    ViewModelChamsRuntime.Categories[Part] = nil
end

function RestoreViewModelChams(Category)
    local Parts = {}

    for Part, CurrentCategory in pairs( ViewModelChamsRuntime.Categories ) do
        if not Category or CurrentCategory == Category then Parts[#Parts + 1] = Part end
    end

    for _, Part in ipairs(Parts) do
        RestoreViewModelPart(Part)
    end

    if not Category then ViewModelChamsRuntime.ViewModel = nil end
end

function EnsureViewModelHighlight(Part, ViewModel)
    local Highlight = ViewModelChamsRuntime.Highlights[ Part ]

    if Highlight and Highlight.Parent and Highlight.Adornee == Part then return Highlight end

    if Highlight and Highlight.Parent then Highlight:Destroy() end

    Highlight = Instance.new("Highlight")
    Highlight.Name = "AtramentaViewModelCham"

    Highlight.Adornee = Part
    Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    Highlight.Enabled = true
    Highlight.Parent = ViewModel

    ViewModelChamsRuntime.Highlights[ Part ] = Highlight

    return Highlight
end

function GetWeaponGlow(Part, ViewModel, Soft)
    local Shells = Soft and ViewModelChamsRuntime.SoftGlowShells or ViewModelChamsRuntime.GlowShells local Existing = Shells[Part]

    if Existing and Existing.Parent and Existing.Adornee == Part then return Existing end

    if Existing and Existing.Parent then Existing:Destroy() end

    local Shell = Instance.new("BoxHandleAdornment")
    Shell.Name = Soft and "AtramentaWeaponSoftGlow" or "AtramentaWeaponTightGlow"
    Shell.Adornee = Part
    Shell.AlwaysOnTop = true
    Shell.ZIndex = Soft and 0 or 1
    Shell.Visible = false
    Shell.Parent = ViewModel

    Shells[Part] = Shell
    return Shell
end

function UpdateWeaponGlow(Part, ViewModel, Category, Settings)
    local Tight = ViewModelChamsRuntime.GlowShells[Part] local Soft = ViewModelChamsRuntime.SoftGlowShells[Part]

    if Category ~= "Weapon" or Settings.GlowEnabled ~= true then
        if Tight and Tight.Parent then Tight.Visible = false end
        if Soft and Soft.Parent then Soft.Visible = false end
        return
    end

    Tight = GetWeaponGlow(Part, ViewModel, false)
    Soft = GetWeaponGlow(Part, ViewModel, true)

    local GlowSize = math.clamp(tonumber(Settings.GlowSize) or 28, 8, 56) local GlowIntensity = math.clamp(tonumber(Settings.GlowIntensity) or 1.35, 0.2, 3)
    local GlowTransparency = math.clamp(tonumber(Settings.GlowTransparency) or 0.12, 0, 1) local SizeAlpha = (GlowSize - 8) / 48

    local BaseSize = Part.Size local SmallestAxis = math.max(math.min(BaseSize.X, BaseSize.Y, BaseSize.Z), 0.025)

    local TightScale = 1.014 + SizeAlpha * 0.034 + GlowIntensity * 0.004 local SoftScale = 1.040 + SizeAlpha * 0.074 + GlowIntensity * 0.009
    local TightAdd = math.clamp(0.010 + SmallestAxis * (0.020 + SizeAlpha * 0.020), 0.010, 0.065)
    local SoftAdd = math.clamp(0.030 + SmallestAxis * (0.050 + SizeAlpha * 0.045), 0.028, 0.150)

    local TightTransparency = math.clamp(
        0.72 - GlowIntensity * 0.095 + GlowTransparency * 0.24,
        0.34,
        0.86
    )

    local SoftTransparency = math.clamp(
        0.93 - GlowIntensity * 0.040 + GlowTransparency * 0.16,
        0.72,
        0.975
    )

    local GlowColor = Settings.GlowColor or Settings.Color

    Tight.Color3 = GlowColor
    Tight.Transparency = TightTransparency
    Tight.Size = BaseSize * TightScale + Vector3.new(TightAdd, TightAdd, TightAdd)
    Tight.AlwaysOnTop = true
    Tight.ZIndex = 1
    Tight.Visible = true

    Soft.Color3 = GlowColor
    Soft.Transparency = SoftTransparency
    Soft.Size = BaseSize * SoftScale + Vector3.new(SoftAdd, SoftAdd, SoftAdd)
    Soft.AlwaysOnTop = true
    Soft.ZIndex = 0
    Soft.Visible = true
end

function ClearViewModelChamAnimationTextures(Part)
    local Textures = ViewModelChamsRuntime.AnimationTextures[Part]

    if type(Textures) == "table" then
        for Index = 1, #Textures do
            local Texture = Textures[Index]
            if Texture and Texture.Parent then Texture:Destroy() end
        end
    end

    ViewModelChamsRuntime.AnimationTextures[Part] = nil
end

function ApplyViewModelChamAnimation(Part, Settings)
    local Original = ViewModelChamsRuntime.Original[Part]
    if not Original then return end

    local Name = tostring(Settings.Animation or "Disabled")
    local Asset = ViewModelChamsAnimations[Name] or ""
    local Previous = ViewModelChamsRuntime.AnimationState[Part]
    local Textures = ViewModelChamsRuntime.AnimationTextures[Part]

    if Asset == "" then
        ClearViewModelChamAnimationTextures(Part)

        if Part:IsA("MeshPart") and Original.TextureID ~= nil then Part.TextureID = Original.TextureID end

        local Mesh = Original.SpecialMesh
        if Mesh and Mesh.Parent == Part and Original.SpecialMeshTexture ~= nil then Mesh.TextureId = Original.SpecialMeshTexture end

        ViewModelChamsRuntime.AnimationState[Part] = ""
        return
    end

    if Part:IsA("MeshPart") then Part.TextureID = "" end

    local Mesh = Original.SpecialMesh
    if Mesh and Mesh.Parent == Part then Mesh.TextureId = "" end

    if type(Textures) ~= "table" or #Textures ~= 6 or Previous ~= Asset then
        ClearViewModelChamAnimationTextures(Part)
        Textures = {}

        local Faces = {
            Enum.NormalId.Front,
            Enum.NormalId.Back,
            Enum.NormalId.Left,
            Enum.NormalId.Right,
            Enum.NormalId.Top,
            Enum.NormalId.Bottom
        }

        for Index = 1, #Faces do
            local Texture = Instance.new("Texture")
            Texture.Name = "AtramentaChamAnimation"
            Texture.Face = Faces[Index]
            Texture.Texture = Asset
            Texture.Color3 = Settings.Color
            Texture.Transparency = math.clamp(tonumber(Settings.Transparency) or 0.30, 0, 0.95)
            Texture.StudsPerTileU = 2
            Texture.StudsPerTileV = 2
            Texture.Parent = Part
            Textures[#Textures + 1] = Texture
        end

        ViewModelChamsRuntime.AnimationTextures[Part] = Textures
    else
        for Index = 1, #Textures do
            local Texture = Textures[Index]
            if Texture and Texture.Parent then
                Texture.Texture = Asset
                Texture.Color3 = Settings.Color
                Texture.Transparency = math.clamp(tonumber(Settings.Transparency) or 0.30, 0, 0.95)
            end
        end
    end

    ViewModelChamsRuntime.AnimationState[Part] = Asset
end

function UpdateViewModelChamAnimationScroll(DeltaTime)
    if next(ViewModelChamsRuntime.AnimationTextures) == nil then return end

    ViewModelChamsRuntime.AnimationClock += math.max(tonumber(DeltaTime) or 0, 0)
    if ViewModelChamsRuntime.AnimationClock < ViewModelChamsRuntime.AnimationInterval then return end

    local Step = ViewModelChamsRuntime.AnimationClock
    ViewModelChamsRuntime.AnimationClock = 0

    for Part, Textures in pairs(ViewModelChamsRuntime.AnimationTextures) do
        if not Part or not Part.Parent or type(Textures) ~= "table" then
            ViewModelChamsRuntime.AnimationTextures[Part] = nil
        else
            local Category = ViewModelChamsRuntime.Categories[Part]
            local Settings = Category == "Arms" and ArmsChamsSettings or Category == "Weapon" and WeaponChamsSettings or nil
            local Speed = Settings and math.clamp(tonumber(Settings.AnimationSpeed) or 1, 0, 4) or 0

            if Speed > 0 then
                for Index = 1, #Textures do
                    local Texture = Textures[Index]
                    if Texture and Texture.Parent then
                        Texture.OffsetStudsV = (Texture.OffsetStudsV + Step * Speed) % 2
                    end
                end
            end
        end
    end
end

function ApplyViewModelChamPart(Part, ViewModel, Category, Settings)
    StoreViewModelPartOriginal(Part)

    ViewModelChamsRuntime.Categories[ Part ] = Category

    Part.Material = Enum.Material.ForceField
    Part.Color = Settings.Color
    Part.Transparency = math.clamp(tonumber(Settings.Transparency) or 0.30, 0, 0.95)
    Part.LocalTransparencyModifier = 0

    ApplyViewModelChamAnimation(Part, Settings)

    local Highlight = EnsureViewModelHighlight(Part, ViewModel)

    Highlight.FillColor = Settings.Color

    Highlight.FillTransparency = math.clamp( tonumber(Settings.HighlightTransparency) or 0.30, 0, 1)

    Highlight.OutlineColor = Settings.OutlineColor

    Highlight.OutlineTransparency = math.clamp( tonumber(Settings.OutlineTransparency) or 0.05, 0, 1)

    Highlight.Enabled = true

    UpdateWeaponGlow(Part, ViewModel, Category, Settings)
end

function SuspendViewModelArms()
    local Runtime = ViewModelChamsRuntime
    local Stale = {}

    for Part, Category in pairs(Runtime.Categories) do
        if Category == "Arms" then
            if not Part or not Part.Parent then
                Stale[#Stale + 1] = Part
            else
                ClearViewModelChamAnimationTextures(Part)
                Runtime.AnimationState[Part] = nil

                local Highlight = Runtime.Highlights[Part]
                if Highlight and Highlight.Parent then Highlight:Destroy() end
                Runtime.Highlights[Part] = nil

                local Tight = Runtime.GlowShells[Part]
                if Tight and Tight.Parent then Tight:Destroy() end
                Runtime.GlowShells[Part] = nil

                local Soft = Runtime.SoftGlowShells[Part]
                if Soft and Soft.Parent then Soft:Destroy() end
                Runtime.SoftGlowShells[Part] = nil

                local Original = Runtime.Original[Part]
                if type(Original) == "table" then
                    Part.Material = Original.Material
                    Part.Color = Original.Color

                    if Part:IsA("MeshPart") and Original.TextureID ~= nil then
                        Part.TextureID = Original.TextureID
                    end

                    local Mesh = Original.SpecialMesh
                    if Mesh and Mesh.Parent == Part and Original.SpecialMeshTexture ~= nil then
                        Mesh.TextureId = Original.SpecialMeshTexture
                    end
                end

                Part.Transparency = 1
                Part.LocalTransparencyModifier = 1
            end
        end
    end

    for Index = 1, #Stale do
        RestoreViewModelPart(Stale[Index])
    end
end

function UpdateViewModelChams()
    local Runtime = ViewModelChamsRuntime
    local FirstPerson = IsViewModelFirstPerson()
    local Changed = Runtime.LastFirstPerson ~= nil and Runtime.LastFirstPerson ~= FirstPerson
    Runtime.LastFirstPerson = FirstPerson

    if not FirstPerson then
        if ArmsChamsEnabled then SuspendViewModelArms() else RestoreViewModelChams("Arms") end
        if WeaponChamsEnabled then RestoreViewModelChams("Weapon") end

        if Changed then
            Runtime.AnimationClock = 0
        end

        if not ArmsChamsEnabled and not WeaponChamsEnabled and Runtime.ViewModel then
            RestoreViewModelChams()
        end

        return
    end

    local ViewModel = GetArmsViewModel()

    if not ViewModel or not ViewModel.Parent then
        if ViewModelChamsRuntime.ViewModel then RestoreViewModelChams() end

        return
    end

    if ViewModelChamsRuntime.ViewModel
        ~= ViewModel then
        RestoreViewModelChams()
        ViewModelChamsRuntime.ViewModel = ViewModel
    end

    local Active = setmetatable( {}, { __mode = "k" })

    for _, Part in ipairs( ViewModel:GetDescendants() ) do
        if Part:IsA("BasePart") then
            local Category local Settings

            if ArmsChamsEnabled and IsViewModelArmPart( Part ) then
                Category = "Arms"
                Settings = ArmsChamsSettings
            elseif WeaponChamsEnabled and IsViewModelWeaponPart( Part, ViewModel ) then
                Category = "Weapon"
                Settings = WeaponChamsSettings
            end

            if Category then
                ApplyViewModelChamPart( Part, ViewModel, Category, Settings)

                Active[Part] = true
            end
        end
    end

    local Stale = {}

    for Part in pairs( ViewModelChamsRuntime.Categories ) do
        if not Active[Part] or not Part or not Part.Parent or not Part:IsDescendantOf( ViewModel ) then Stale[#Stale + 1] = Part end
    end

    for _, Part in ipairs(Stale) do
        RestoreViewModelPart(Part)
    end
end

function EnsureViewModelChamsRender()
    local Enabled = ArmsChamsEnabled or WeaponChamsEnabled

    local RenderName = ViewModelChamsRuntime.RenderName

    if not Enabled then
        if RenderName then
            Internal.Call( function()
                    RunService:UnbindFromRenderStep( RenderName)
                end)
        end

        ViewModelChamsRuntime.RenderName = nil
        ViewModelChamsRuntime.LastFirstPerson = nil

        RestoreViewModelChams()
        return
    end

    if RenderName then return end

    RenderName = "AtramentaViewModelChams_" .. tostring( LocalPlayer.UserId)

    ViewModelChamsRuntime.RenderName = RenderName

    Internal.Call( function()
            RunService:UnbindFromRenderStep( RenderName)
        end)

    RunService:BindToRenderStep( RenderName, Enum.RenderPriority.Last.Value + 200, function(DeltaTime)
            if not ArmsChamsEnabled and not WeaponChamsEnabled then return end

            Internal.Call(UpdateViewModelChams)
            Internal.Call(UpdateViewModelChamAnimationScroll, DeltaTime)
        end)
end

function ApplyArmsChams()
    EnsureViewModelChamsRender()
    UpdateViewModelChams()
end

function RestoreArmsChams()
    RestoreViewModelChams( "Arms")
end

function ArmsChamsEnable()
    ArmsChamsEnabled = true
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
    EnsureWeaponPerspectiveFix()
    UpdateViewModelChams()
end

function ArmsChamsDisable()
    ArmsChamsEnabled = false
    ViewModelChamsRuntime.LastFirstPerson = nil
    RestoreArmsChams()
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
    EnsureWeaponPerspectiveFix()
end

function RestoreWeaponShaderMesh(Object)
    local Original = WeaponShaderSettings.MeshOriginal[Object]
    if Original == nil then return end
    if Object and Object.Parent then
        if Object:IsA("MeshPart") then Object.TextureID = Original
        elseif Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then Object.TextureId = Original end
    end
    WeaponShaderSettings.MeshOriginal[Object] = nil
    WeaponShaderSettings.MeshActive[Object] = nil
end

function RestoreWeaponShaderSurface(Surface)
    local Original = WeaponShaderSettings.SurfaceOriginal[Surface]
    if Original == nil then return end
    if Surface and Surface.Parent then
        Internal.Call(function() Surface.ColorMap = Original.ColorMap end)
        Internal.Call(function() Surface.NormalMap = Original.NormalMap end)
        Internal.Call(function() Surface.MetalnessMap = Original.MetalnessMap end)
        Internal.Call(function() Surface.RoughnessMap = Original.RoughnessMap end)
        if Original.AlphaMode ~= nil then Internal.Call(function() Surface.AlphaMode = Original.AlphaMode end) end
    end
    WeaponShaderSettings.SurfaceOriginal[Surface] = nil
    WeaponShaderSettings.SurfaceActive[Surface] = nil
end

function DisconnectWeaponShaderCharacterSignals()
    for _, Connection in ipairs( WeaponShaderSettings.CharacterConnections ) do
        if Connection and typeof(Connection)
                == "RBXScriptConnection" then
            Connection:Disconnect()
        end
    end

    WeaponShaderSettings.CharacterConnections = {}
end

function BindWeaponShaderCharacterSignals(Character)
    DisconnectWeaponShaderCharacterSignals()

    if not Character then return end

    local function DirtyCharacter()
        if not WeaponShaderSettings.Enabled then return end

        WeaponShaderSettings.Dirty = true
        WeaponShaderSettings.NextRootCheck = 0
    end

    WeaponShaderSettings.CharacterConnections[1] = Character.ChildAdded:Connect(function(Object)
                if Object:IsA("Tool") or Object:IsA("BasePart") then DirtyCharacter() end
            end)

    WeaponShaderSettings.CharacterConnections[2] = Character.ChildRemoved:Connect(function(Object)
                if Object:IsA("Tool") or Object:IsA("BasePart") then DirtyCharacter() end
            end)
end

function DisconnectWeaponShaderCameraSignals()
    if WeaponShaderSettings.CameraAddedConnection then
        WeaponShaderSettings.CameraAddedConnection:Disconnect()

        WeaponShaderSettings.CameraAddedConnection = nil
    end

    if WeaponShaderSettings.CameraRemovedConnection then
        WeaponShaderSettings.CameraRemovedConnection:Disconnect()

        WeaponShaderSettings.CameraRemovedConnection = nil
    end

    WeaponShaderSettings.BoundCamera = nil
end

function BindWeaponShaderCameraSignals(CameraObject)
    if WeaponShaderSettings.BoundCamera
            == CameraObject and WeaponShaderSettings.CameraAddedConnection and WeaponShaderSettings.CameraRemovedConnection then
        return
    end

    DisconnectWeaponShaderCameraSignals()

    if not CameraObject then return end

    WeaponShaderSettings.BoundCamera = CameraObject

    local function DirtyCamera(Object)
        if not WeaponShaderSettings.Enabled then return end

        if Object:IsA("Model") or Object:IsA("Folder") or Object:IsA("Tool") or Object:IsA("BasePart") then
            WeaponShaderSettings.Dirty = true
            WeaponShaderSettings.NextRootCheck = 0

            task.defer(function()
                if WeaponShaderSettings.Enabled and CameraObject
                        == Internal.GetCamera() then
                    RefreshWeaponShaders(true)
                end
            end)
        end
    end

    WeaponShaderSettings.CameraAddedConnection = CameraObject.ChildAdded:Connect(DirtyCamera)

    WeaponShaderSettings.CameraRemovedConnection = CameraObject.ChildRemoved:Connect(DirtyCamera)
end

function ResetWeaponShaderRespawnState()
    WeaponShaderSettings.RespawnSerial += 1

    DisconnectWeaponShaderRoots()
    DisconnectWeaponShaderCharacterSignals()

    local Textures = {}
    local Meshes = {}
    local Surfaces = {}

    for Texture in pairs( WeaponShaderSettings.Textures ) do
        Textures[#Textures + 1] = Texture
    end

    for Object in pairs( WeaponShaderSettings.MeshOriginal ) do
        Meshes[#Meshes + 1] = Object
    end

    for Surface in pairs( WeaponShaderSettings.SurfaceOriginal ) do
        Surfaces[#Surfaces + 1] = Surface
    end

    for _, Texture in ipairs( Textures ) do
        if Texture and Texture.Parent then Texture:Destroy() end
    end

    for _, Object in ipairs( Meshes ) do
        RestoreWeaponShaderMesh( Object)
    end

    for _, Surface in ipairs( Surfaces ) do
        RestoreWeaponShaderSurface( Surface)
    end

    WeaponShaderSettings.Textures = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.MeshOriginal = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.MeshActive = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.SurfaceOriginal = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.SurfaceActive = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.FaceTextures = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.IndexedParts = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.IndexedMeshes = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.IndexedSurfaces = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.LastFirstPerson = nil
    WeaponShaderSettings.LastCamera = nil
    WeaponShaderSettings.Dirty = true
    WeaponShaderSettings.NextRootCheck = 0
    WeaponShaderSettings.LastAnimate = 0
end

function RebindWeaponShadersAfterRespawn(Character)
    if not WeaponShaderSettings.Enabled or not Character then return end

    local Serial = WeaponShaderSettings.RespawnSerial

    BindWeaponShaderCharacterSignals( Character)

    BindWeaponShaderCameraSignals( Internal.GetCamera())

    EnsureWeaponShaderRender()

    local Delays = { 0, 0.04, 0.10, 0.20, 0.38, 0.65, 1.00 }

    for _, Delay in ipairs(Delays) do
        task.delay( Delay, function()
                if not WeaponShaderSettings.Enabled or Serial
                        ~= WeaponShaderSettings.RespawnSerial or Character
                        ~= LocalPlayer.Character then
                    return
                end

                BindWeaponShaderCameraSignals( Internal.GetCamera())

                local Roots = GetWeaponShaderRoots()

                if not WeaponShaderRootsEqual( Roots, WeaponShaderSettings.Roots ) then BindWeaponShaderRoots( Roots) end

                WeaponShaderSettings.NextRootCheck = 0

                if WeaponShaderSettings.Dirty then RefreshWeaponShaders( true) end
            end)
    end
end

function DisconnectWeaponShaderLifecycle()
    if WeaponShaderSettings.CharacterAddedConnection then
        WeaponShaderSettings.CharacterAddedConnection:Disconnect()

        WeaponShaderSettings.CharacterAddedConnection = nil
    end

    if WeaponShaderSettings.CharacterRemovingConnection then
        WeaponShaderSettings.CharacterRemovingConnection:Disconnect()

        WeaponShaderSettings.CharacterRemovingConnection = nil
    end

    DisconnectWeaponShaderCharacterSignals()
    DisconnectWeaponShaderCameraSignals()
end

function BindWeaponShaderLifecycle()
    DisconnectWeaponShaderLifecycle()

    WeaponShaderSettings.CharacterAddedConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
                if not WeaponShaderSettings.Enabled then return end

                ResetWeaponShaderRespawnState()
                RebindWeaponShadersAfterRespawn( Character)
            end)

    WeaponShaderSettings.CharacterRemovingConnection = LocalPlayer.CharacterRemoving:Connect(function()
                if not WeaponShaderSettings.Enabled then return end

                ResetWeaponShaderRespawnState()
            end)

    if LocalPlayer.Character then BindWeaponShaderCharacterSignals( LocalPlayer.Character) end

    BindWeaponShaderCameraSignals( Internal.GetCamera())
end

function DisconnectWeaponShaderRoots()
    for _, Connection in ipairs( WeaponShaderSettings.RootConnections ) do
        if Connection then Connection:Disconnect() end
    end

    WeaponShaderSettings.RootConnections = {}
    WeaponShaderSettings.Roots = {}

    WeaponShaderSettings.IndexedParts = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.IndexedMeshes = setmetatable( {}, { __mode = "k" })

    WeaponShaderSettings.IndexedSurfaces = setmetatable( {}, { __mode = "k" })
end

function IndexWeaponShaderObject(Object, RootData)
    if not Object or not RootData or not RootData.Root then return end

    if Object:IsA("BasePart") then
        if IsWeaponShaderPartAllowed( Object, RootData ) then WeaponShaderSettings.IndexedParts[ Object ] = RootData end

        return
    end

    if Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then
        local Part = Object:FindFirstAncestorWhichIsA( "BasePart")

        if Part and IsWeaponShaderPartAllowed( Part, RootData ) then WeaponShaderSettings.IndexedMeshes[ Object ] = RootData end

        return
    end

    if Object:IsA("SurfaceAppearance") then
        local Part = Object:FindFirstAncestorWhichIsA( "BasePart")

        if Part and IsWeaponShaderPartAllowed( Part, RootData ) then WeaponShaderSettings.IndexedSurfaces[ Object ] = RootData end
    end
end

function UnindexWeaponShaderObject(Object)
    WeaponShaderSettings.IndexedParts[ Object ] = nil

    WeaponShaderSettings.IndexedMeshes[ Object ] = nil

    WeaponShaderSettings.IndexedSurfaces[ Object ] = nil
end

function GetWeaponShaderRoots()
    local Roots = {}
    local Tool = GetWeaponShaderTarget()

    if IsViewModelFirstPerson() then
        local ViewModel = GetArmsViewModel()
        if ViewModel and ViewModel.Parent then Roots[#Roots + 1] = {Root = ViewModel, ViewModel = true} end
        if Tool and Tool.Parent and (not ViewModel or not Tool:IsDescendantOf(ViewModel)) then Roots[#Roots + 1] = {Root = Tool, ViewModel = false} end
        return Roots
    end

    if Tool and Tool.Parent then Roots[1] = {Root = Tool, ViewModel = false} end
    return Roots
end

function WeaponShaderRootsEqual(A, B)
    if type(A) ~= "table" or type(B) ~= "table" or #A ~= #B then return false end

    for Index = 1, #A do
        if not A[Index] or not B[Index] or A[Index].Root ~= B[Index].Root or A[Index].ViewModel ~= B[Index].ViewModel then return false end
    end

    return true
end

function IsWeaponShaderPartAllowed(Part, RootData)
    if not Part or not Part:IsA("BasePart") or not RootData or not RootData.Root then return false end

    if RootData.ViewModel then
        if IsViewModelWeaponPart(Part, RootData.Root) then return true end
        return WeaponShaderSettings.ApplyToArms == true and IsViewModelArmPart(Part)
    end

    return Part:IsDescendantOf(RootData.Root)
end

function BindWeaponShaderRoots(Roots)
    DisconnectWeaponShaderRoots()

    WeaponShaderSettings.Roots = Roots

    for _, RootData in ipairs(Roots) do
        local Root = RootData.Root

        if Root and Root.Parent then
            for _, Object in ipairs( Root:GetDescendants() ) do
                IndexWeaponShaderObject( Object, RootData)
            end

            WeaponShaderSettings.RootConnections[ #WeaponShaderSettings.RootConnections + 1 ] = Root.DescendantAdded:Connect(function(Object)
                        IndexWeaponShaderObject( Object, RootData)

                        if Object:IsA("BasePart") or Object:IsA("SpecialMesh") or Object:IsA("FileMesh") or Object:IsA("SurfaceAppearance") then
                            WeaponShaderSettings.Dirty = true

                            WeaponShaderSettings.NextRootCheck = 0
                        end
                    end)

            WeaponShaderSettings.RootConnections[ #WeaponShaderSettings.RootConnections + 1 ] = Root.DescendantRemoving:Connect(function(Object)
                        UnindexWeaponShaderObject( Object)

                        if Object:IsA("BasePart") or Object:IsA("SpecialMesh") or Object:IsA("FileMesh") or Object:IsA("SurfaceAppearance") then
                            WeaponShaderSettings.Dirty = true

                            WeaponShaderSettings.NextRootCheck = 0
                        end
                    end)
        end
    end

    WeaponShaderSettings.Dirty = true
end

function ApplyWeaponShaderSurface(Surface, Asset)
    if not Surface or not Surface.Parent or not Surface:IsA( "SurfaceAppearance" ) or not Asset then return false end

    if WeaponShaderSettings.SurfaceOriginal[ Surface ] == nil then
        local Original = {}

        Internal.Call(function()
            Original.ColorMap = Surface.ColorMap
        end)

        Internal.Call(function()
            Original.NormalMap = Surface.NormalMap
        end)

        Internal.Call(function()
            Original.MetalnessMap = Surface.MetalnessMap
        end)

        Internal.Call(function()
            Original.RoughnessMap = Surface.RoughnessMap
        end)

        WeaponShaderSettings.SurfaceOriginal[ Surface ] = Original
    end

    Internal.Call(function()
        if Surface.ColorMap ~= Asset then Surface.ColorMap = Asset end

        if Surface.NormalMap ~= "" then Surface.NormalMap = "" end

        if Surface.MetalnessMap ~= "" then Surface.MetalnessMap = "" end

        if Surface.RoughnessMap ~= "" then Surface.RoughnessMap = "" end
    end)

    WeaponShaderSettings.SurfaceActive[ Surface ] = true

    return true
end

function ApplyWeaponShaderMesh(Object, Asset)
    if not Object or not Object.Parent or not Asset then return false end
    if Object:IsA("MeshPart") then
        if WeaponShaderSettings.MeshOriginal[Object] == nil then WeaponShaderSettings.MeshOriginal[Object] = Object.TextureID end
        if Object.TextureID ~= Asset then Object.TextureID = Asset end
    elseif Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then
        if WeaponShaderSettings.MeshOriginal[Object] == nil then WeaponShaderSettings.MeshOriginal[Object] = Object.TextureId end
        if Object.TextureId ~= Asset then Object.TextureId = Asset end
    else
        return false
    end
    WeaponShaderSettings.MeshActive[Object] = true
    return true
end
function WeaponShaderPartNeedsFaceTextures(Part)
    if not Part or not Part:IsA("BasePart") then return false end
    if Part:IsA("MeshPart") or Part:IsA("UnionOperation") or Part:FindFirstChildWhichIsA("SpecialMesh") or Part:FindFirstChildWhichIsA("FileMesh") then return true end
    local Name = string.lower(Part.Name)
    if string.find(Name, "handle", 1, true) or string.find(Name, "receiver", 1, true) or string.find(Name, "slide", 1, true) or string.find(Name, "barrel", 1, true)
        or string.find(Name, "bolt", 1, true) or string.find(Name, "mag", 1, true) or string.find(Name, "stock", 1, true) or string.find(Name, "grip", 1, true)
        or string.find(Name, "trigger", 1, true) or string.find(Name, "sight", 1, true) then return true end
    return Part.Transparency < 0.98
end

function ApplyWeaponShaderFaceTextures(Part, Asset)
    if not Part or not Part:IsA("BasePart") or not Asset then return end

    local Faces = WeaponShaderSettings.Faces local Map = WeaponShaderSettings.FaceTextures[Part]

    if type(Map) ~= "table" then
        Map = {}

        for _, Child in ipairs(Part:GetChildren()) do
            if Child:IsA("Texture") and Child.Name == "AtramentaWeaponShader" then
                Map[Child.Face] = Child
                WeaponShaderSettings.Textures[Child] = true
            end
        end

        WeaponShaderSettings.FaceTextures[Part] = Map
    end

    local Tile = math.max(tonumber(WeaponShaderSettings.Tile) or 2.5, 0.1) local Offset = WeaponShaderSettings.Time % 2048
    local ShaderColor = typeof(WeaponShaderSettings.Color) == "Color3" and WeaponShaderSettings.Color or Color3.new(1, 1, 1)

    for _, Face in ipairs(Faces) do
        local Texture = Map[Face]

        if not Texture or not Texture.Parent then
            Texture = Instance.new("Texture")
            Texture.Name = "AtramentaWeaponShader"
            Texture.Face = Face
            Texture.Transparency = 0
            Texture.Parent = Part
            Map[Face] = Texture
        end

        Texture.Texture = Asset
        Texture.Color3 = ShaderColor Texture.StudsPerTileU = Tile
        Texture.StudsPerTileV = Tile
        Texture.OffsetStudsU = Offset
        Texture.OffsetStudsV = Offset * 0.63

        WeaponShaderSettings.Textures[Texture] = true
    end
end

function ClearWeaponShaders()
    if type(WeaponShaderSettings) ~= "table" then return end

    WeaponShaderSettings.RespawnSerial = (tonumber(WeaponShaderSettings.RespawnSerial) or 0) + 1

    local RenderName = WeaponShaderSettings.RenderName
    if type(RenderName) == "string" and RenderName ~= "" then RunService:UnbindFromRenderStep(RenderName) end
    WeaponShaderSettings.RenderName = nil

    if type(DisconnectWeaponShaderLifecycle) == "function" then DisconnectWeaponShaderLifecycle() end
    if type(DisconnectWeaponShaderRoots) == "function" then DisconnectWeaponShaderRoots() end
    if type(DisconnectWeaponShaderCharacterSignals) == "function" then DisconnectWeaponShaderCharacterSignals() end
    if type(DisconnectWeaponShaderCameraSignals) == "function" then DisconnectWeaponShaderCameraSignals() end

    local Textures = {}
    local Meshes = {}
    local Surfaces = {}

    if type(WeaponShaderSettings.Textures) == "table" then
        for Texture in pairs(WeaponShaderSettings.Textures) do Textures[#Textures + 1] = Texture end
    end

    if type(WeaponShaderSettings.MeshOriginal) == "table" then
        for Object in pairs(WeaponShaderSettings.MeshOriginal) do Meshes[#Meshes + 1] = Object end
    end

    if type(WeaponShaderSettings.SurfaceOriginal) == "table" then
        for Surface in pairs(WeaponShaderSettings.SurfaceOriginal) do Surfaces[#Surfaces + 1] = Surface end
    end

    for Index = 1, #Textures do
        local Texture = Textures[Index]
        if Texture and Texture.Parent then Texture:Destroy() end
    end

    for Index = 1, #Meshes do
        local Object = Meshes[Index]
        if type(RestoreWeaponShaderMesh) == "function" then RestoreWeaponShaderMesh(Object) end
    end

    for Index = 1, #Surfaces do
        local Surface = Surfaces[Index]
        if type(RestoreWeaponShaderSurface) == "function" then RestoreWeaponShaderSurface(Surface) end
    end

    WeaponShaderSettings.Textures = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.MeshOriginal = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.MeshActive = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.SurfaceOriginal = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.SurfaceActive = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.FaceTextures = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.IndexedParts = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.IndexedMeshes = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.IndexedSurfaces = setmetatable({}, {__mode = "k"})
    WeaponShaderSettings.Roots = {}
    WeaponShaderSettings.RootConnections = {}
    WeaponShaderSettings.CharacterConnections = {}
    WeaponShaderSettings.LastFirstPerson = nil
    WeaponShaderSettings.LastCamera = nil
    WeaponShaderSettings.BoundCamera = nil
    WeaponShaderSettings.Dirty = true
    WeaponShaderSettings.NextRootCheck = 0
    WeaponShaderSettings.LastAnimate = 0
    WeaponShaderSettings.Time = 0
    WeaponShaderSettings.ColorRefreshQueued = false
    WeaponShaderSettings.LastAppliedColor = nil
end

function RefreshWeaponShaderColorOnly()
    if not WeaponShaderSettings.Enabled then return end

    local ShaderColor = typeof(WeaponShaderSettings.Color) == "Color3" and WeaponShaderSettings.Color or Color3.new(1, 1, 1)

    if WeaponShaderSettings.LastAppliedColor == ShaderColor then return end

    WeaponShaderSettings.LastAppliedColor = ShaderColor

    local Dead = nil

    for Texture in pairs(WeaponShaderSettings.Textures) do
        if Texture and Texture.Parent then
            if Texture.Color3 ~= ShaderColor then
                Texture.Color3 = ShaderColor end
        else
            Dead = Dead or {}
            Dead[#Dead + 1] = Texture
        end
    end

    if Dead then
        for Index = 1, #Dead do
            WeaponShaderSettings.Textures[Dead[Index]] = nil
        end
    end
end

function QueueWeaponShaderColorRefresh()
    if not WeaponShaderSettings.Enabled or WeaponShaderSettings.ColorRefreshQueued then return end

    WeaponShaderSettings.ColorRefreshQueued = true

    task.defer(function()
        WeaponShaderSettings.ColorRefreshQueued = false

        if WeaponShaderSettings.Enabled then RefreshWeaponShaderColorOnly() end
    end)
end

function RefreshWeaponShaderAppearance()
    if not WeaponShaderSettings.Enabled then return end

    local Asset = WeaponShaderSettings.Assets[WeaponShaderSettings.Preset] or WeaponShaderSettings.Assets.Galaxy

    local Tile = math.max(tonumber(WeaponShaderSettings.Tile) or 2.5, 0.1)

    local ShaderColor = typeof(WeaponShaderSettings.Color) == "Color3" and WeaponShaderSettings.Color or Color3.new(1, 1, 1)

    local Dead = nil

    for Texture in pairs(WeaponShaderSettings.Textures) do
        if Texture and Texture.Parent then
            if Texture.Texture ~= Asset then Texture.Texture = Asset end

            if Texture.Color3 ~= ShaderColor then
                Texture.Color3 = ShaderColor end

            if Texture.StudsPerTileU ~= Tile then Texture.StudsPerTileU = Tile end

            if Texture.StudsPerTileV ~= Tile then Texture.StudsPerTileV = Tile end
        else
            Dead = Dead or {}
            Dead[#Dead + 1] = Texture
        end
    end

    if Dead then
        for Index = 1, #Dead do
            WeaponShaderSettings.Textures[Dead[Index]] = nil
        end
    end

    for Object in pairs(WeaponShaderSettings.MeshActive) do
        if Object and Object.Parent then ApplyWeaponShaderMesh(Object, Asset) end
    end

    for Surface in pairs(WeaponShaderSettings.SurfaceActive) do
        if Surface and Surface.Parent then ApplyWeaponShaderSurface(Surface, Asset) end
    end

    WeaponShaderSettings.LastAppliedColor = ShaderColor end

function RefreshWeaponShaders(Force)
    if not WeaponShaderSettings.Enabled then
        ClearWeaponShaders()
        return
    end

    local Roots = GetWeaponShaderRoots()

    if not WeaponShaderRootsEqual( Roots, WeaponShaderSettings.Roots ) then
        BindWeaponShaderRoots( Roots)

        Force = true
    end

    if not Force and not WeaponShaderSettings.Dirty then return end

    WeaponShaderSettings.Dirty = false

    local Asset = WeaponShaderSettings.Assets[ WeaponShaderSettings.Preset ] or WeaponShaderSettings.Assets.Galaxy

    local ActiveParts = {}
    local ActiveTextures = {}
    local ActiveMeshes = {}
    local ActiveSurfaces = {}

    for Part, RootData in pairs( WeaponShaderSettings.IndexedParts ) do
        if Part and Part.Parent and IsWeaponShaderPartAllowed( Part, RootData ) then
            ActiveParts[Part] = true

            if Part:IsA("MeshPart") and ApplyWeaponShaderMesh( Part, Asset ) then ActiveMeshes[Part] = true end

            if WeaponShaderPartNeedsFaceTextures( Part ) then ApplyWeaponShaderFaceTextures( Part, Asset) end
        end
    end

    for Object, RootData in pairs( WeaponShaderSettings.IndexedMeshes ) do
        if Object and Object.Parent then
            local Part = Object:FindFirstAncestorWhichIsA( "BasePart")

            if Part and IsWeaponShaderPartAllowed( Part, RootData ) and ApplyWeaponShaderMesh( Object, Asset ) then ActiveMeshes[Object] = true end
        end
    end

    for Surface, RootData in pairs( WeaponShaderSettings.IndexedSurfaces ) do
        if Surface and Surface.Parent then
            local Part = Surface:FindFirstAncestorWhichIsA( "BasePart")

            if Part and IsWeaponShaderPartAllowed( Part, RootData ) and ApplyWeaponShaderSurface( Surface, Asset ) then ActiveSurfaces[ Surface ] = true end
        end
    end

    for Texture in pairs( WeaponShaderSettings.Textures ) do
        if Texture and Texture.Parent and ActiveParts[ Texture.Parent ] then ActiveTextures[ Texture ] = true end
    end

    local StaleTextures = {}
    local StaleMeshes = {}
    local StaleSurfaces = {}

    for Texture in pairs( WeaponShaderSettings.Textures ) do
        if not ActiveTextures[ Texture ] then StaleTextures[ #StaleTextures + 1 ] = Texture end
    end

    for Object in pairs( WeaponShaderSettings.MeshOriginal ) do
        if not ActiveMeshes[ Object ] then StaleMeshes[ #StaleMeshes + 1 ] = Object end
    end

    for Surface in pairs( WeaponShaderSettings.SurfaceOriginal ) do
        if not ActiveSurfaces[ Surface ] then StaleSurfaces[ #StaleSurfaces + 1 ] = Surface end
    end

    for _, Texture in ipairs( StaleTextures ) do
        if Texture and Texture.Parent then Texture:Destroy() end

        WeaponShaderSettings.Textures[ Texture ] = nil
    end

    for _, Object in ipairs( StaleMeshes ) do
        RestoreWeaponShaderMesh( Object)
    end

    for _, Surface in ipairs( StaleSurfaces ) do
        RestoreWeaponShaderSurface( Surface)
    end
end

function EnsureWeaponShaderRender()
    if not WeaponShaderSettings.Enabled then
        ClearWeaponShaders()
        return
    end

    if WeaponShaderSettings.RenderName then return end

    local RenderName = "AtramentaWeaponShaders_" .. tostring( LocalPlayer.UserId)

    WeaponShaderSettings.RenderName = RenderName

    RunService:UnbindFromRenderStep( RenderName)

    RunService:BindToRenderStep( RenderName, Enum.RenderPriority.Last.Value + 210, function(DeltaTime)
        local Success = Internal.Call(function()
            if not WeaponShaderSettings.Enabled then return end

            local CurrentTime = os.clock()

            local CameraObject = Internal.GetCamera()

            local FirstPerson = IsViewModelFirstPerson()

            local CameraChanged = WeaponShaderSettings.LastCamera
                    ~= CameraObject

            local PerspectiveChanged = WeaponShaderSettings.LastFirstPerson
                    ~= FirstPerson

            if CameraChanged then
                WeaponShaderSettings.LastCamera = CameraObject

                BindWeaponShaderCameraSignals( CameraObject)
            end

            if PerspectiveChanged then WeaponShaderSettings.LastFirstPerson = FirstPerson end

            if CameraChanged or PerspectiveChanged then
                WeaponShaderSettings.Dirty = true
                WeaponShaderSettings.NextRootCheck = 0
            end

            WeaponShaderSettings.Time += DeltaTime * math.max( tonumber(WeaponShaderSettings.Speed) or 1, 0.01)

            local ViewModel = FirstPerson and GetArmsViewModel() or nil

            local RootInterval = FirstPerson and not ViewModel and 0.04 or ( WeaponShaderSettings.RootCheckInterval or 0.18)

            if CurrentTime
                >= ( WeaponShaderSettings.NextRootCheck or 0 ) then
                WeaponShaderSettings.NextRootCheck = CurrentTime + RootInterval

                local Roots = GetWeaponShaderRoots()

                if not WeaponShaderRootsEqual( Roots, WeaponShaderSettings.Roots ) then BindWeaponShaderRoots( Roots) end

                if WeaponShaderSettings.Dirty then RefreshWeaponShaders(true) end
            end

            if CurrentTime
                - ( WeaponShaderSettings.LastAnimate or 0)
                < ( WeaponShaderSettings.AnimateInterval or 1 / 30 ) then
                return
            end

            WeaponShaderSettings.LastAnimate = CurrentTime

            local Offset = WeaponShaderSettings.Time % 2048

            local Dead = nil

            for Texture in pairs( WeaponShaderSettings.Textures ) do
                if Texture and Texture.Parent then
                    Texture.OffsetStudsU = Offset

                    Texture.OffsetStudsV = Offset * 0.63
                else
                    Dead = Dead or {}

                    Dead[ #Dead + 1 ] = Texture
                end
            end

            if Dead then
                for _, Texture in ipairs( Dead ) do
                    WeaponShaderSettings.Textures[ Texture ] = nil
                end
            end
        end)

        if not Success then
            WeaponShaderSettings.Dirty = true
            WeaponShaderSettings.NextRootCheck = 0
        end
        end)
end

function SetWeaponShaderEnabled(Value)
    if type(WeaponShaderSettings) ~= "table" then return end
    WeaponShaderSettings.Enabled = Value == true

    if not WeaponShaderSettings.Enabled then
        ClearWeaponShaders()
        EnsureWeaponPerspectiveFix()
        return
    end

    EnsureWeaponPerspectiveFix()

    WeaponShaderSettings.LastFirstPerson = nil
    WeaponShaderSettings.LastCamera = nil
    WeaponShaderSettings.Dirty = true
    WeaponShaderSettings.NextRootCheck = 0

    if type(BindWeaponShaderLifecycle) == "function" then BindWeaponShaderLifecycle() end
    if type(EnsureWeaponShaderRender) == "function" then EnsureWeaponShaderRender() end

    local Character = LocalPlayer and LocalPlayer.Character
    if Character and Character.Parent then
        if type(RebindWeaponShadersAfterRespawn) == "function" then RebindWeaponShadersAfterRespawn(Character) end
    elseif type(RefreshWeaponShaders) == "function" then
        RefreshWeaponShaders(true)
    end
end

function ApplyWeaponChams()
    EnsureViewModelChamsRender()
    UpdateViewModelChams()
    if WeaponShaderSettings.Enabled then WeaponShaderSettings.Dirty = true; RefreshWeaponShaders(true) end
end

function RestoreWeaponChams()
    RestoreViewModelChams( "Weapon")
end

function WeaponChamsEnable()
    WeaponChamsEnabled = true
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
    EnsureWeaponPerspectiveFix()
    UpdateViewModelChams()
end

function WeaponChamsDisable()
    WeaponChamsEnabled = false
    RestoreWeaponChams()
    UpdateChamsBloom()
    EnsureViewModelChamsRender()
    EnsureWeaponPerspectiveFix()
end

function GetFinishAuraTarget(LocalRoot)
    if not LocalRoot then return nil end

    local CharStats = ReplicatedStorage:FindFirstChild( "CharStats")

    local ClosestCharacter = nil local ClosestDistance = math.clamp( tonumber(FinishAuraDistance) or 15, 1, 15)

    local BestTier = -1

    for _, PlayerObject in ipairs( Players:GetPlayers() ) do
        if not IsCombatTargetAllowed( PlayerObject ) then continue end

        local Character = PlayerObject.Character

        local Root = Character and Character:FindFirstChild( "HumanoidRootPart")

        local Head = Character and Character:FindFirstChild( "Head")

        local Humanoid = Character and Character:FindFirstChildOfClass( "Humanoid")

        local Stats = CharStats and CharStats:FindFirstChild( PlayerObject.Name)

        local Downed = Stats and Stats:FindFirstChild( "Downed")

        if Root and Head and Humanoid and Humanoid.Health > 0 and Downed and Downed.Value == true
            and not CombatChecks.HasForceField(PlayerObject, Character) then
            local Distance = ( LocalRoot.Position - Root.Position ).Magnitude

            local Tier = GetCombatTargetPriority( PlayerObject)

            if Distance <= FinishAuraDistance and ( Tier > BestTier or Tier == BestTier and Distance < ClosestDistance ) then
                BestTier = Tier
                ClosestDistance = Distance
                ClosestCharacter = Character
            end
        end
    end

    return ClosestCharacter
end

function ExecuteFinishAura(TargetCharacter)
    if FinishAuraBusy or not FinishAuraEnabled or not TargetCharacter then return end

    local TargetPlayer = Internal.GetPlayerFromTrackedCharacter( TargetCharacter)

    local FinishToken = { TargetWasDowned = TargetPlayer and Internal.IsAtramentaPlayerActuallyDowned( TargetPlayer ) or false, FinishSoundPlayed = false,
        Source = "FinishAura" }

    local Character = LocalPlayer.Character local Tool = Character and Character:FindFirstChildOfClass("Tool")
    local RightLeg = Character and ( Character:FindFirstChild("Right Leg") or Character:FindFirstChild("RightLowerLeg") or Character:FindFirstChild("RightFoot"))
    local TargetHead = TargetCharacter:FindFirstChild("Head")

    local Events = ReplicatedStorage:FindFirstChild("Events") local InvokeRemote = Events and Events:FindFirstChild("XMHH.2")
    local FireRemote = Events and Events:FindFirstChild("XMHH2.2")

    if not Character or not Tool or not RightLeg or not TargetHead or not InvokeRemote or not FireRemote then return end

    FinishAuraBusy = true

    task.spawn(function()
        local Success, InvokeResult = Internal.Call(function()
            return InvokeRemote:InvokeServer( "\240\159\141\158", tick(), Tool, "EXECQX")
        end)

        if Success and InvokeResult and FinishAuraEnabled and TargetCharacter.Parent and TargetHead.Parent then
            task.wait(0.25)

            if FinishAuraEnabled and Tool.Parent and TargetCharacter.Parent and TargetHead.Parent then
                Internal.Call(function()
                    FireRemote:FireServer( "\240\159\141\158", tick(), Tool, "2389ZFX34", InvokeResult, false, RightLeg, TargetHead, TargetCharacter,
                        TargetHead.Position, TargetHead.Position)
                end)

                if TargetPlayer and FinishToken.TargetWasDowned == true then WatchAtramentaFinishSound( TargetPlayer, TargetCharacter, FinishToken) end
            end
        end

        FinishAuraBusy = false
    end)
end

function FinishAuraEnable()
    if FinishAuraEnabled then return end

    FinishAuraEnabled = true
    FinishAuraBusy = false

    if FinishAuraConnection then
        FinishAuraConnection:Disconnect()
        FinishAuraConnection = nil
    end

    FinishAuraClock = 0
    FinishAuraConnection = RunService.RenderStepped:Connect(function(DeltaTime)
        if not FinishAuraEnabled or FinishAuraBusy then return end

        FinishAuraClock += math.clamp(tonumber(DeltaTime) or 0, 0, 0.05)
        if FinishAuraClock < 1 / 60 then return end
        FinishAuraClock = FinishAuraClock % (1 / 60)

        local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")
        local Tool = Character and Character:FindFirstChildOfClass("Tool")

        if not Root or not Tool then return end

        local TargetCharacter = GetFinishAuraTarget(Root)
        if TargetCharacter then ExecuteFinishAura(TargetCharacter) end
    end)
end

function FinishAuraDisable()
    FinishAuraEnabled = false
    FinishAuraBusy = false
    FinishAuraClock = 0

    if FinishAuraConnection then
        FinishAuraConnection:Disconnect()
        FinishAuraConnection = nil
    end
end

;(function()
