        NoFallDamageEnabled = true

            Environment.AtramentaNoFallDamage = true
        Environment.AtramentaBlockRagdoll = true

        if type(InstallSharedNamecallRouter) == "function" then InstallSharedNamecallRouter() end

        if State.CharacterConnection then State.CharacterConnection:Disconnect() end

        State.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function()
            task.defer(ApplyNoFallCharacterState)
        end)

        if State.HeartbeatConnection then State.HeartbeatConnection:Disconnect() end

        State.HeartbeatConnection = RunService.Heartbeat:Connect(function()
            if not NoFallDamageEnabled then return end
            Environment.AtramentaNoFallDamage = true
            ApplyNoFallCharacterState()
        end)

        ApplyNoFallCharacterState()
    end

    function NoFallDamageDisable()
        if not NoFallDamageEnabled then return end
        NoFallDamageEnabled = false

            Environment.AtramentaNoFallDamage = false
        Environment.AtramentaBlockRagdoll = false

        if State.CharacterConnection then
            State.CharacterConnection:Disconnect()
            State.CharacterConnection = nil
        end

        if State.HeartbeatConnection then
            State.HeartbeatConnection:Disconnect()
            State.HeartbeatConnection = nil
        end
    end
end)()

AntiEffectsController = {
    PlayerGuiConnection = nil,
    CameraConnection = nil,
    CameraChangedConnection = nil,
    WorkspaceConnection = nil,
    SoundConnection = nil,
    StorageConnection = nil,
    CharacterConnection = nil,
    PlayerGuiAddedConnection = nil,
    AnimationConnection = nil,
    BoundHumanoid = nil,
    BlindSounds = nil,
    BlindAnimation = nil,
    SoundConnections = setmetatable({}, { __mode = "k" })
}

function AntiEffectsController.IsSmokeObject(Object)
    if not Object then return false end
    if Object.Name == "Smoke" or Object.Name == "SmokeExplosion" then return true end
    return Object:IsA("ParticleEmitter") and string.find(string.lower(Object.Name), "smoke", 1, true) ~= nil
end

function AntiEffectsController.GetBlindSounds()
    local Storage = ReplicatedStorage:FindFirstChild("Storage") local FrameworkStuff = Storage and Storage:FindFirstChild("FrameworkStuff")
    local BlindSounds = FrameworkStuff and FrameworkStuff:FindFirstChild("BlindSounds")
    AntiEffectsController.BlindSounds = BlindSounds
    return BlindSounds
end

function AntiEffectsController.GetBlindAnimation()
    local Storage = ReplicatedStorage:FindFirstChild("Storage") local Animations = Storage and Storage:FindFirstChild("Animations")
    local BlindAnimation = Animations and Animations:FindFirstChild("BlindAnim")
    AntiEffectsController.BlindAnimation = BlindAnimation
    return BlindAnimation
end

function AntiEffectsController.RemovePlayerGuiEffect(Object)
    if not Object then return end

    if AntiFlashbangEnabled and Object.Name == "FlashedGUI" and Object:IsA("ScreenGui") then
        Object:Destroy()
    elseif AntiSmokeEnabled and Object.Name == "SmokeScreenGUI" and Object:IsA("ScreenGui") then
        Object:Destroy()
    end
end

function AntiEffectsController.RemoveCameraEffect(Object)
    if not AntiFlashbangEnabled or not Object then return end
    if Object.Name == "BlindEffect" and (Object:IsA("ColorCorrectionEffect") or Object:IsA("BlurEffect")) then Object:Destroy() end
end

function AntiEffectsController.RemoveEqualizer(Object)
    if not AntiFlashbangEnabled or not Object or not Object:IsA("EqualizerSoundEffect") then return end
    Object.HighGain = 0
    Object.MidGain = 0
    Object.LowGain = 0
    Object:Destroy()
end

function AntiEffectsController.DisconnectSound(Sound)
    local Connections = AntiEffectsController.SoundConnections[Sound] if not Connections then return end

    for _, Connection in pairs(Connections) do
        if Connection then Connection:Disconnect() end
    end

    AntiEffectsController.SoundConnections[Sound] = nil
end

function AntiEffectsController.BindBlindSound(Sound)
    if not AntiFlashbangEnabled or not Sound or not Sound:IsA("Sound") or AntiEffectsController.SoundConnections[Sound] then return end

    Sound:Stop()
    Sound.Volume = 0

    local Connections = {}
    Connections.Played = Sound.Played:Connect(function()
        if AntiFlashbangEnabled and Sound.Parent then Sound:Stop() end
    end)
    Connections.Volume = Sound:GetPropertyChangedSignal("Volume"):Connect(function()
        if AntiFlashbangEnabled and Sound.Parent and Sound.Volume ~= 0 then Sound.Volume = 0 end
    end)
    Connections.Ancestry = Sound.AncestryChanged:Connect(function(_, Parent)
        if not Parent then AntiEffectsController.DisconnectSound(Sound) end
    end)
    AntiEffectsController.SoundConnections[Sound] = Connections
end

function AntiEffectsController.CleanPlayerGui()
    local PlayerGui = LocalPlayer:FindFirstChild("PlayerGui") if not PlayerGui then return end
    for _, Object in ipairs(PlayerGui:GetDescendants()) do AntiEffectsController.RemovePlayerGuiEffect(Object) end
end

function AntiEffectsController.CleanCamera()
    if not AntiFlashbangEnabled then return end
    local Camera = workspace.CurrentCamera if not Camera then return end
    for _, Object in ipairs(Camera:GetDescendants()) do AntiEffectsController.RemoveCameraEffect(Object) end
end

function AntiEffectsController.CleanFlashSounds()
    if not AntiFlashbangEnabled then return end
    local BlindSounds = AntiEffectsController.GetBlindSounds() if not BlindSounds then return end

    for _, Object in ipairs(BlindSounds:GetDescendants()) do
        if Object:IsA("Sound") then AntiEffectsController.BindBlindSound(Object) end
    end
end

function AntiEffectsController.CleanEqualizers()
    if not AntiFlashbangEnabled then return end
    for _, Object in ipairs(SoundService:GetDescendants()) do AntiEffectsController.RemoveEqualizer(Object) end
end

function AntiEffectsController.IsBlindTrack(Track)
    if not Track then return false end
    local Animation = Track.Animation local BlindAnimation = AntiEffectsController.BlindAnimation or AntiEffectsController.GetBlindAnimation()
    if not Animation or not BlindAnimation then return false end
    if Animation == BlindAnimation then return true end

    local AnimationId = Animation.AnimationId local BlindAnimationId = BlindAnimation.AnimationId
    return AnimationId ~= "" and BlindAnimationId ~= "" and AnimationId == BlindAnimationId
end

function AntiEffectsController.BindCharacter(Character)
    if AntiEffectsController.AnimationConnection then
        AntiEffectsController.AnimationConnection:Disconnect()
        AntiEffectsController.AnimationConnection = nil
    end

    AntiEffectsController.BoundHumanoid = nil
    if not AntiFlashbangEnabled or not Character then return end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid") if not Humanoid then return end

    AntiEffectsController.BoundHumanoid = Humanoid
    AntiEffectsController.GetBlindAnimation()

    for _, Track in ipairs(Humanoid:GetPlayingAnimationTracks()) do
        if AntiEffectsController.IsBlindTrack(Track) then Track:Stop(0) end
    end

    AntiEffectsController.AnimationConnection = Humanoid.AnimationPlayed:Connect(function(Track)
        if AntiFlashbangEnabled and AntiEffectsController.IsBlindTrack(Track) then Track:Stop(0) end
    end)
end

function AntiEffectsController.CleanWorldSmoke()
    if not AntiSmokeEnabled then return end
    for _, Object in ipairs(workspace:GetDescendants()) do
        if AntiEffectsController.IsSmokeObject(Object) then Object:Destroy() end
    end
end

function AntiEffectsController.HandlePlayerGuiDescendant(Object)
    AntiEffectsController.RemovePlayerGuiEffect(Object)
end

function AntiEffectsController.HandleCameraDescendant(Object)
    AntiEffectsController.RemoveCameraEffect(Object)
end

function AntiEffectsController.HandleWorkspaceDescendant(Object)
    if AntiSmokeEnabled and AntiEffectsController.IsSmokeObject(Object) then
        task.defer(function()
            if AntiSmokeEnabled and Object and Object.Parent then Object:Destroy() end
        end)
    end
end

function AntiEffectsController.HandleSoundDescendant(Object)
    AntiEffectsController.RemoveEqualizer(Object)
end

function AntiEffectsController.HandleStorageDescendant(Object)
    if not AntiFlashbangEnabled or not Object then return end

    if Object.Name == "BlindSounds" then
        task.defer(AntiEffectsController.CleanFlashSounds)
        return
    end

    if not Object:IsA("Sound") then return end
    local BlindSounds = AntiEffectsController.BlindSounds
    if not BlindSounds or not BlindSounds.Parent then BlindSounds = AntiEffectsController.GetBlindSounds() end
    if BlindSounds and Object:IsDescendantOf(BlindSounds) then AntiEffectsController.BindBlindSound(Object) end
end

function AntiEffectsController.Disconnect()
    local ConnectionNames = {
        "PlayerGuiConnection", "CameraConnection", "CameraChangedConnection", "WorkspaceConnection",
        "SoundConnection", "StorageConnection", "CharacterConnection", "PlayerGuiAddedConnection", "AnimationConnection"
    }

    for _, Name in ipairs(ConnectionNames) do
        local Connection = AntiEffectsController[Name]
        if Connection then
            Connection:Disconnect()
            AntiEffectsController[Name] = nil
        end
    end

    AntiEffectsController.BoundHumanoid = nil
    for Sound in pairs(AntiEffectsController.SoundConnections) do AntiEffectsController.DisconnectSound(Sound) end
end

function AntiEffectsController.BindCamera()
    if AntiEffectsController.CameraConnection then
        AntiEffectsController.CameraConnection:Disconnect()
        AntiEffectsController.CameraConnection = nil
    end

    if not AntiFlashbangEnabled then return end
    local Camera = workspace.CurrentCamera if not Camera then return end
    AntiEffectsController.CameraConnection = Camera.DescendantAdded:Connect(AntiEffectsController.HandleCameraDescendant)
    AntiEffectsController.CleanCamera()
end

function AntiEffectsController.RefreshConnections()
    AntiEffectsController.Disconnect()
    if not AntiFlashbangEnabled and not AntiSmokeEnabled then return end

    local PlayerGui = LocalPlayer:FindFirstChild("PlayerGui")
    if PlayerGui then AntiEffectsController.PlayerGuiConnection = PlayerGui.DescendantAdded:Connect(AntiEffectsController.HandlePlayerGuiDescendant) end
    AntiEffectsController.PlayerGuiAddedConnection = LocalPlayer.ChildAdded:Connect(function(Object)
        if (AntiFlashbangEnabled or AntiSmokeEnabled) and Object:IsA("PlayerGui") then AntiEffectsController.RefreshConnections() end
    end)

    if AntiFlashbangEnabled then
        AntiEffectsController.BindCamera()
        AntiEffectsController.CameraChangedConnection = workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(AntiEffectsController.BindCamera)
        AntiEffectsController.SoundConnection = SoundService.DescendantAdded:Connect(AntiEffectsController.HandleSoundDescendant)

        local Storage = ReplicatedStorage:FindFirstChild("Storage")
        if Storage then AntiEffectsController.StorageConnection = Storage.DescendantAdded:Connect(AntiEffectsController.HandleStorageDescendant) end

        AntiEffectsController.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
            task.defer(AntiEffectsController.BindCharacter, Character)
        end)
        AntiEffectsController.BindCharacter(LocalPlayer.Character)
    end

    if AntiSmokeEnabled then AntiEffectsController.WorkspaceConnection = workspace.DescendantAdded:Connect(AntiEffectsController.HandleWorkspaceDescendant) end

    AntiEffectsController.CleanPlayerGui()
    if AntiFlashbangEnabled then
        AntiEffectsController.CleanFlashSounds()
        AntiEffectsController.CleanEqualizers()
    end
    if AntiSmokeEnabled then AntiEffectsController.CleanWorldSmoke() end
end

function AntiFlashbangEnable()
    if AntiFlashbangEnabled then return end
    AntiFlashbangEnabled = true
    AntiEffectsController.RefreshConnections()
end

function AntiFlashbangDisable()
    if not AntiFlashbangEnabled then return end
    AntiFlashbangEnabled = false
    AntiEffectsController.RefreshConnections()
end

function AntiSmokeEnable()
    if AntiSmokeEnabled then return end
    AntiSmokeEnabled = true
    AntiEffectsController.RefreshConnections()
end

function AntiSmokeDisable()
    if not AntiSmokeEnabled then return end
    AntiSmokeEnabled = false
    AntiEffectsController.RefreshConnections()
end

function AntiBarbwireEnable()
    AntiBarbwireEnabled = true
    Environment.AtramentaAntiBarrier = true
    if type(InstallSharedNamecallRouter) == "function" then InstallSharedNamecallRouter() end
end

function AntiBarbwireDisable()
    AntiBarbwireEnabled = false
    Environment.AtramentaAntiBarrier = false
end

function NoBarriersApply(Value)
    local Filter = workspace:FindFirstChild("Filter") local Parts = Filter and Filter:FindFirstChild("Parts") local FParts = Parts and Parts:FindFirstChild("F_Parts")

    if not FParts then return end

    for _, InstanceObject in ipairs(FParts:GetDescendants()) do
        if InstanceObject:IsA("Part") or InstanceObject:IsA("MeshPart") then InstanceObject.CanTouch = not Value end
    end
end

function NoBarriersEnable()
    NoBarriersEnabled = true
    NoBarriersApply(true)
end

function NoBarriersDisable()
    NoBarriersEnabled = false
    NoBarriersApply(false)
end

PepperAuraLastHit = PepperAuraLastHit or setmetatable({}, { __mode = "k" })
PepperAuraLastTick = tonumber(PepperAuraLastTick) or 0
PepperAuraSpraying = PepperAuraSpraying == true
PepperAuraTickRate = 0.12
PepperAuraHitRate = 0.30

function PepperAuraEnable()
    if PepperAuraEnabled then return end

    PepperAuraEnabled = true

    if PepperAuraConnection then
        PepperAuraConnection:Disconnect()
        PepperAuraConnection = nil
    end

    PepperAuraConnection = RunService.Heartbeat:Connect( function()
                if not PepperAuraEnabled then return end

                local Now = os.clock()

                if Now - PepperAuraLastTick
                    < PepperAuraTickRate then
                    return
                end

                PepperAuraLastTick = Now

                local Character = LocalPlayer.Character

                local Root = Character and Character:FindFirstChild( "HumanoidRootPart")

                local Pepper = Character and Character:FindFirstChild( "Pepper-spray")

                local Remote = Pepper and Pepper:FindFirstChild( "RemoteEvent")

                if not Root or not Pepper or not Remote or not Remote:IsA("RemoteEvent") then
                    PepperAuraSpraying = false

                    return
                end

                if PepperAuraInfinite then
                    local Ammo = Pepper:FindFirstChild( "Ammo")

                    if Ammo then Ammo.Value = 100 end
                end

                local MaximumDistance = math.clamp( tonumber(PepperAuraDistance) or 15, 1, 15)

                local Targets = {}

                for _, PlayerObject in ipairs( Players:GetPlayers() ) do
                    if IsCombatTargetAllowed(PlayerObject) then
                        local TargetCharacter = PlayerObject.Character

                        local TargetRoot = TargetCharacter and TargetCharacter:FindFirstChild( "HumanoidRootPart")

                        local Humanoid = TargetCharacter and TargetCharacter:FindFirstChildOfClass( "Humanoid")

                        if TargetRoot and Humanoid and Humanoid.Health > 0 and not TargetCharacter:GetAttribute( "Downed" ) and ( Root.Position
                                - TargetRoot.Position ).Magnitude
                                <= MaximumDistance then
                            Targets[ #Targets + 1 ] = TargetCharacter
                        end
                    end
                end

                local HasTarget = #Targets > 0

                if HasTarget and not PepperAuraSpraying then
                    Remote:FireServer( "Spray", true)

                    PepperAuraSpraying = true
                elseif not HasTarget and PepperAuraSpraying then
                    Remote:FireServer( "Spray", false)

                    PepperAuraSpraying = false
                end

                for _, TargetCharacter in ipairs( Targets ) do
                    local LastHit = tonumber( PepperAuraLastHit[ TargetCharacter ] ) or 0

                    if Now - LastHit
                        >= PepperAuraHitRate then
                        PepperAuraLastHit[ TargetCharacter ] = Now

                        Remote:FireServer( "Hit", TargetCharacter)
                    end
                end
            end)
end

function PepperAuraDisable()
    PepperAuraEnabled = false

    if PepperAuraConnection then
        PepperAuraConnection:Disconnect()
        PepperAuraConnection = nil
    end

    if PepperAuraSpraying then
        local Character = LocalPlayer.Character

        local Pepper = Character and Character:FindFirstChild( "Pepper-spray")

        local Remote = Pepper and Pepper:FindFirstChild( "RemoteEvent")

        if Remote and Remote:IsA("RemoteEvent") then Remote:FireServer( "Spray", false) end
    end

    PepperAuraSpraying = false
    PepperAuraLastHit = setmetatable({}, { __mode = "k" })
end

Ragebot.WeaponConfigCache = Ragebot.WeaponConfigCache or setmetatable({}, {__mode = "k"})

function Ragebot.GetWeaponConfig(Tool)
    if not Tool then return nil end
    local Cached = Ragebot.WeaponConfigCache[Tool]
    if type(Cached) == "table" then return Cached end
    local ConfigModule = Tool:FindFirstChild("Config")
    if not ConfigModule or not ConfigModule:IsA("ModuleScript") then return nil end
    local Success, Config = Internal.Call(require, ConfigModule)
    if Success and type(Config) == "table" then
        Ragebot.WeaponConfigCache[Tool] = Config
        return Config
    end
    return nil
end

function Ragebot.GetServerTimestamp(Tool, Config)
    Config = type(Config) == "table" and Config or Ragebot.GetWeaponConfig(Tool)
    local SharedValues = ReplicatedStorage:FindFirstChild("Values") local ServerTick = SharedValues and SharedValues:FindFirstChild("ServerTick")

    if ServerTick and typeof(ServerTick.Value) == "number" then
        local Salt = type(Config) == "table" and tonumber(Config.IntSalt or Config.Salt) or nil
        if Salt then return ServerTick.Value - Salt end
        return ServerTick.Value
    end

    local ToolValues = Tool and Tool:FindFirstChild("Values") local ToolServerTick = ToolValues and ToolValues:FindFirstChild("ServerTick")
    if ToolServerTick and typeof(ToolServerTick.Value) == "number" then return ToolServerTick.Value end
    return tick()
end

function Ragebot.GetProtocolTimestamp(Tool)
    return Ragebot.GetServerTimestamp(Tool, Ragebot.GetWeaponConfig(Tool))
end

function Ragebot.GetRemoteKey(Tool, Config)
    local Value = Ragebot.GetServerTimestamp(Tool, Config)
    return typeof(Value) == "number" and Value or tick()
end

function Ragebot.GetCharacter(Player)
    if not Player then return nil end
    if type(ResolveTrackedCharacter) == "function" then
        local Character = ResolveTrackedCharacter(Player, Player.Character)
        if Character then return Character end
    end
    return Player.Character
end

function Ragebot.GetRootPart(Character)
    if not Character then return nil end
    return Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")
end

function Ragebot.RandomString(Length)
    local Characters = table.create(Length)
    for Index = 1, Length do Characters[Index] = string.char(math.random(65, 122)) end
    return table.concat(Characters)
end

Ragebot.GoldenAngle = tonumber(Ragebot.GoldenAngle) or math.pi * (3 - math.sqrt(5))
Ragebot.RayParams = RaycastParams.new()
Ragebot.RayParams.FilterType = Enum.RaycastFilterType.Exclude
Ragebot.RayParams.IgnoreWater = true
Ragebot.RayParams.RespectCanCollide = false
Ragebot.OverlapParams = OverlapParams.new()
Ragebot.OverlapParams.FilterType = Enum.RaycastFilterType.Exclude
Ragebot.Filter = {}
Ragebot.FilterCharacter = nil
Ragebot.FilterDebris = nil
Ragebot.FilterWorld = nil
Ragebot.RouteCache = setmetatable({}, { __mode = "k" })
Ragebot.RouteStore = {
    Path = "AtramentaWallbangRoutes.txt",
    Header = "# V1|PlaceId|GameId|Unix|Distance|Vertical|Pitch|Stage|Part|OriginB1|OriginB2|OriginPole|HitB1|HitB2|HitPole|NormalB1|NormalB2|NormalPole|BlockerB1|BlockerB2|BlockerPole|OriginMagnitude|LateralMagnitude|PreMagnitude|PreLateral|PrePole|RefineGain|RefineChecks|RefineMoves",
    Loaded = false,
    Available = type(isfile) == "function" and type(readfile) == "function" and type(writefile) == "function",
    Routes = {},
    ByPlace = {},
    Keys = {}
}
Ragebot.LastTarget = nil
Ragebot.LastRoute = nil
Ragebot.LastStage = "idle"
Ragebot.LastScanCount = 0
Ragebot.LastScanTime = 0

Ragebot.FOVGlowLayers = { {2.25, 0.22}, {1.62, 0.44}, {1.08, 0.72} }

function Ragebot.ResetWallbangRuntime()
    local Wallbang = Ragebot.Runtime.Wallbang
    if type(Wallbang) == "table" then
        Wallbang.LastScan = 0
