function Ragebot.IsFirearm(Tool)
    if not Tool or not Tool:IsA("Tool") then return false end

    local Values = Tool:FindFirstChild("Values")

    if Values and ( Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo") ) then return true end

    if Tool:FindFirstChild("Hitmarker") then return true end

    local Config = Tool:FindFirstChild("Config")
    return Config ~= nil and Config:IsA("ModuleScript")
end

function Ragebot.GetFieldOfViewPosition()
    return UserInputService:GetMouseLocation()
end

function Ragebot.GetTargetScreenPosition(WorldPosition, CameraObject)
    CameraObject = CameraObject or workspace.CurrentCamera

    if not CameraObject
        or typeof(WorldPosition) ~= "Vector3"
    then
        return nil
    end

    local ScreenPosition, Visible =
        CameraObject:WorldToScreenPoint(
            WorldPosition
        )

    if not Visible
        or ScreenPosition.Z <= 0
    then
        return nil
    end

    return Vector2.new(
        ScreenPosition.X,
        ScreenPosition.Y
    )
end

function Ragebot.GetTargetScreenParts(Character)
    if not Character then return {} end

    local Parts = {}
    local Seen = {}

    local function Add(Part)
        if Part
            and Part:IsA("BasePart")
            and not Seen[Part]
        then
            Seen[Part] = true
            Parts[#Parts + 1] = Part
        end
    end

    Add(
        Character:FindFirstChild(
            tostring(
                Ragebot.Settings.TargetPart
                or "Head"
            )
        )
    )

    Add(Character:FindFirstChild("Head"))
    Add(Character:FindFirstChild("Torso"))
    Add(Character:FindFirstChild("HumanoidRootPart"))

    return Parts
end

function Ragebot.GetTargetScreenMetric(
    Character,
    MousePosition,
    CameraObject
)
    if not Character
        or typeof(MousePosition) ~= "Vector2"
        or not CameraObject
    then
        return nil
    end

    local Best = math.huge
    local Found = false
    local Parts = Ragebot.GetTargetScreenParts(Character)

    for Index = 1, #Parts do
        local Part = Parts[Index]
        local Screen = Ragebot.GetTargetScreenPosition(
            Part.Position,
            CameraObject
        )

        if Screen then
            local Distance =
                (Screen - MousePosition).Magnitude

            if Distance < Best then
                Best = Distance
                Found = true
            end
        end
    end

    return Found and Best or nil
end
function Ragebot.RemoveDrawing(Object)
    if not Object then return end

    Object.Visible = false

    if type(Object.Remove) == "function" then Object:Remove() end
end

function Ragebot.DestroyFieldOfView()
    if Ragebot.FOVConnection then
        Ragebot.FOVConnection:Disconnect()
        Ragebot.FOVConnection = nil
    end

    Ragebot.RemoveDrawing(Ragebot.FOVCircle)
    Ragebot.FOVCircle = nil

    for Index = 1, #Ragebot.FOVGlowCircles do
        Ragebot.RemoveDrawing(Ragebot.FOVGlowCircles[Index])
    end

    for Index = 1, #Ragebot.FOVGradientLines do
        Ragebot.RemoveDrawing(Ragebot.FOVGradientLines[Index])
    end

    Ragebot.FOVGlowCircles = {}
    Ragebot.FOVGradientLines = {}
end

function Ragebot.CreateFieldOfViewCircle(Color, Thickness, Transparency)
    if type(Drawing) ~= "table" or type(Drawing.new) ~= "function" then return nil end

    local Circle = Drawing.new("Circle")
    Circle.Filled = false
    Circle.NumSides = 96
    Circle.Color = Color Circle.Thickness = Thickness
    Circle.Transparency = Transparency
    Circle.Radius = math.clamp(tonumber(Ragebot.Settings.FOV) or 320, 10, 700)
    Circle.Visible = false
    return Circle
end

function Ragebot.CreateFieldOfViewGlow()
    Ragebot.FOVGlowCircles = {}

    if Ragebot.Settings.FOVGlow ~= true then return end

    local Thickness = math.clamp( tonumber(Ragebot.Settings.FOVGlowThickness) or 8, 3, 24)

    local Transparency = math.clamp( tonumber(Ragebot.Settings.FOVGlowTransparency) or 0.20, 0, 1)

    for Index = 1, #Ragebot.FOVGlowLayers do
        local Layer = Ragebot.FOVGlowLayers[Index] local Circle = Ragebot.CreateFieldOfViewCircle( Ragebot.Settings.FOVGlowColor or Ragebot.Settings.FOVGradientColor,
            math.max(Thickness * Layer[1], 1), math.clamp(Transparency * Layer[2], 0.02, 1))

        if Circle then Ragebot.FOVGlowCircles[#Ragebot.FOVGlowCircles + 1] = Circle end
    end
end

function Ragebot.CreateFieldOfViewGradient()
    Ragebot.FOVGradientLines = {}

    if Ragebot.Settings.FOVGradient ~= true or type(Drawing) ~= "table" or type(Drawing.new) ~= "function" then return end

    for Index = 1, 64 do
        local Line = Drawing.new("Line")
        Line.Thickness = 2
        Line.Transparency = math.clamp( tonumber(Ragebot.Settings.FOVTransparency) or 0.72, 0, 1)
        Line.Visible = false
        Ragebot.FOVGradientLines[Index] = Line
    end
end

function Ragebot.EnsureFieldOfView()
    if not Ragebot.FOVCircle then
        Ragebot.FOVCircle = Ragebot.CreateFieldOfViewCircle( Ragebot.Settings.FOVColor or Color3.fromRGB(255, 255, 255), 2, math.clamp(
                tonumber(Ragebot.Settings.FOVTransparency) or 0.72, 0, 1 ))
    end

    if Ragebot.Settings.FOVGlow == true then
        if #Ragebot.FOVGlowCircles == 0 then Ragebot.CreateFieldOfViewGlow() end
    elseif #Ragebot.FOVGlowCircles > 0 then
        for Index = 1, #Ragebot.FOVGlowCircles do
            Ragebot.RemoveDrawing(Ragebot.FOVGlowCircles[Index])
        end

        Ragebot.FOVGlowCircles = {}
    end

    if Ragebot.Settings.FOVGradient == true then
        if #Ragebot.FOVGradientLines == 0 then Ragebot.CreateFieldOfViewGradient() end
    elseif #Ragebot.FOVGradientLines > 0 then
        for Index = 1, #Ragebot.FOVGradientLines do
            Ragebot.RemoveDrawing(Ragebot.FOVGradientLines[Index])
        end

        Ragebot.FOVGradientLines = {}
    end
end

function Ragebot.UpdateFieldOfView()
    local Visible = Ragebot.Enabled and Ragebot.Settings.TargetSelection == "FOV" and Ragebot.Settings.ShowFOV == true

    if not Visible then
        if Ragebot.FOVCircle then Ragebot.FOVCircle.Visible = false end

        for Index = 1, #Ragebot.FOVGlowCircles do
            Ragebot.FOVGlowCircles[Index].Visible = false
        end

        for Index = 1, #Ragebot.FOVGradientLines do
            Ragebot.FOVGradientLines[Index].Visible = false
        end

        return
    end

    Ragebot.EnsureFieldOfView()

    local Position = Ragebot.GetFieldOfViewPosition() local Radius = math.clamp( tonumber(Ragebot.Settings.FOV) or 320, 10, 700)

    local Primary = Ragebot.Settings.FOVColor or Color3.fromRGB(255, 255, 255)

    local Secondary = Ragebot.Settings.FOVGradientColor or Color3.fromRGB(54, 218, 145)

    local Transparency = math.clamp( tonumber(Ragebot.Settings.FOVTransparency) or 0.72, 0, 1)

    if Ragebot.FOVCircle then
        Ragebot.FOVCircle.Position = Position
        Ragebot.FOVCircle.Radius = Radius
        Ragebot.FOVCircle.Color = Primary
        Ragebot.FOVCircle.Thickness = Ragebot.Settings.FOVGradient == true and 1 or 2

        Ragebot.FOVCircle.Transparency = Ragebot.Settings.FOVGradient == true and math.min(Transparency * 0.32, 0.28) or Transparency

        Ragebot.FOVCircle.Visible = true
    end

    local GlowThickness = math.clamp( tonumber(Ragebot.Settings.FOVGlowThickness) or 8, 3, 24)

    local GlowTransparency = math.clamp( tonumber(Ragebot.Settings.FOVGlowTransparency) or 0.20, 0, 1)

    for Index = 1, #Ragebot.FOVGlowCircles do
        local Circle = Ragebot.FOVGlowCircles[Index] local Layer = Ragebot.FOVGlowLayers[Index] or Ragebot.FOVGlowLayers[#Ragebot.FOVGlowLayers]

        Circle.Position = Position
        Circle.Radius = Radius
        Circle.Color = Ragebot.Settings.FOVGlowColor or Secondary

        Circle.Thickness = math.max( GlowThickness * Layer[1], 1)

        Circle.Transparency = math.clamp( GlowTransparency * Layer[2], 0.02, 1)

        Circle.Visible = Ragebot.Settings.FOVGlow == true
    end

    local SegmentCount = #Ragebot.FOVGradientLines

    if Ragebot.Settings.FOVGradient == true and SegmentCount > 0 then
        for Index = 1, SegmentCount do
            local Line = Ragebot.FOVGradientLines[Index]

            local T0 = (Index - 1) / SegmentCount

            local T1 = Index / SegmentCount

            local Angle0 = T0 * math.pi * 2

            local Angle1 = T1 * math.pi * 2

            Line.From = Position + Vector2.new( math.cos(Angle0) * Radius, math.sin(Angle0) * Radius)

            Line.To = Position + Vector2.new( math.cos(Angle1) * Radius, math.sin(Angle1) * Radius)

            local Wave = 0.5 - 0.5 * math.cos( T0 * math.pi * 2)

            Line.Color = Primary:Lerp( Secondary, Wave)

            Line.Thickness = 2
            Line.Transparency = Transparency
            Line.Visible = true
        end
    end
end

function Ragebot.RefreshFieldOfView()
    local ShouldRun = Ragebot.Enabled and Ragebot.Settings.TargetSelection == "FOV"

    if ShouldRun then
        if not Ragebot.FOVConnection then Ragebot.FOVConnection = RunService.RenderStepped:Connect( Ragebot.UpdateFieldOfView) end

        Ragebot.UpdateFieldOfView()
    else
        Ragebot.DestroyFieldOfView()
    end
end

function Ragebot.DestroyTargetLine()
    if Ragebot.TargetLineConnection then
        Ragebot.TargetLineConnection:Disconnect()
        Ragebot.TargetLineConnection = nil
    end

    Ragebot.RemoveDrawing( Ragebot.TargetLine)

    Ragebot.TargetLine = nil
end

function Ragebot.EnsureTargetLine()
    if Ragebot.TargetLine or type(Drawing) ~= "table" or type(Drawing.new) ~= "function" then return end

    Ragebot.TargetLine = Drawing.new("Line")

    Ragebot.TargetLine.Visible = false
    Ragebot.TargetLine.Thickness = 1
    Ragebot.TargetLine.Transparency = 0.95
    Ragebot.TargetLine.Color = Ragebot.Settings.TargetLineColor or Color3.fromRGB(255, 75, 75)
end

function Ragebot.UpdateTargetLine()
    if not Ragebot.Enabled or Ragebot.Settings.TargetLine ~= true then
        if Ragebot.TargetLine then Ragebot.TargetLine.Visible = false end

        return
    end

    Ragebot.EnsureTargetLine()

    if not Ragebot.TargetLine then return end

    local Target = Ragebot.CurrentTarget or Ragebot.Runtime.Target or Ragebot.LastTarget

    local Character = Target and Ragebot.GetCharacter(Target) or nil

    local Part = Character and ( Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Head") ) or nil

    local CameraObject = Internal.GetCamera()

    if not Part or not CameraObject then
        Ragebot.TargetLine.Visible = false
        return
    end

    local Screen, OnScreen = CameraObject:WorldToViewportPoint( Part.Position)

    if not OnScreen or Screen.Z <= 0 then
        Ragebot.TargetLine.Visible = false
        return
    end

    local MousePosition = Ragebot.GetFieldOfViewPosition()

    Ragebot.TargetLine.From = MousePosition

    Ragebot.TargetLine.To = Vector2.new( Screen.X, Screen.Y)

    Ragebot.TargetLine.Color = Ragebot.Settings.TargetLineColor or Color3.fromRGB(255, 75, 75)

    Ragebot.TargetLine.Visible = true
end

function Ragebot.RefreshTargetLine()
    local ShouldRun = Ragebot.Enabled and Ragebot.Settings.TargetLine == true

    if ShouldRun then
        Ragebot.EnsureTargetLine()

        if not Ragebot.TargetLineConnection then Ragebot.TargetLineConnection = RunService.RenderStepped:Connect( Ragebot.UpdateTargetLine) end

        Ragebot.UpdateTargetLine()
    else
        Ragebot.DestroyTargetLine()
    end
end

function Ragebot.ResetTargeting()
    local Wallbang = Ragebot.Runtime.Wallbang
    if type(Wallbang) == "table" then
        Wallbang.ValidPair = nil
        Wallbang.LastPair = nil
    end
    Ragebot.CurrentTarget = nil
    Ragebot.LockedTarget = nil
end

function Ragebot.RefreshRaycastParameters()
    local Filter = {}
    if LocalPlayer.Character then Filter[#Filter + 1] = LocalPlayer.Character end
    if workspace.CurrentCamera then Filter[#Filter + 1] = workspace.CurrentCamera end
    Ragebot.RayParams.FilterType = Enum.RaycastFilterType.Exclude
    Ragebot.RayParams.FilterDescendantsInstances = Filter
    Ragebot.RayParams.IgnoreWater = true
    return Ragebot.RayParams
end

function Ragebot.GetPosition()
    local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    return Root and Root.Position or Vector3.zero
end

function Ragebot.GetHitRadius()
    local Wallbang = Ragebot.Runtime.Wallbang local Radius = math.clamp(tonumber(Wallbang.HitRadius) or 23.50, 20, 25)
    if Wallbang.HitRadius ~= Radius then Wallbang.HitRadius = Radius end
    return Radius
end

function Ragebot.PredictPosition(Player, TargetPart)
    if not Player or not TargetPart or not TargetPart:IsA("BasePart") then return nil end

    local BasePosition = TargetPart.Position
    if Ragebot.Settings.Simulation ~= true then return BasePosition end

    local PredictionTime = math.clamp((tonumber(Ragebot.Settings.Prediction) or 0) / 1000, 0, 0.32)
    if PredictionTime <= 0 then return BasePosition end

    local PredictedPosition = ResolveCombatPosition(
        Player,
        Player.Character,
        TargetPart,
        PredictionTime,
        Ragebot.Runtime.SimulationSettings
    )

    if typeof(PredictedPosition) ~= "Vector3" then PredictedPosition = BasePosition + TargetPart.AssemblyLinearVelocity * PredictionTime end

    local DivisorX = math.max(tonumber(Ragebot.Settings.PredictionDivisorX) or 1, 0.1) local DivisorY = math.max(tonumber(Ragebot.Settings.PredictionDivisorY) or 1, 0.1)
    local Offset = PredictedPosition - BasePosition

    return BasePosition + Vector3.new(Offset.X / DivisorX, Offset.Y / DivisorY, Offset.Z / DivisorX)
end

function Ragebot.DisconnectReload()
    local Wallbang = Ragebot.Runtime.Wallbang
    for Index = #Wallbang.ReloadConnections, 1, -1 do
        local Connection = Wallbang.ReloadConnections[Index]
        if Connection then Connection:Disconnect() end
        Wallbang.ReloadConnections[Index] = nil
    end
    Wallbang.ReloadTool = nil
end

function Ragebot.RequestReload(Tool)
    if Ragebot.Settings.AutoReload ~= true or not Tool or not Tool.Parent then return false end
    local Values = Tool:FindFirstChild("Values")
    local Ammo = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    local Stored = Values and (Values:FindFirstChild("SERVER_StoredAmmo") or Values:FindFirstChild("StoredAmmo"))
    if not Ammo or typeof(Ammo.Value) ~= "number" or Ammo.Value > 0 then return false end
    if not Stored or typeof(Stored.Value) ~= "number" or Stored.Value <= 0 then return false end
    local Wallbang = Ragebot.Runtime.Wallbang
    local Now = os.clock()
    if Now - (tonumber(Wallbang.ReloadLastRequest) or 0) < 0.10 then return false end
    Wallbang.ReloadLastRequest = Now
    if type(InstantReload) == "function" and Configuration.NoRecoil.Enabled == true
        and Configuration.NoRecoil.Settings.GunMods.InstantReload == true then
        return InstantReload(Tool, true)
    end
    local Events = ReplicatedStorage:FindFirstChild("Events")
    local Remote = Events and Events:FindFirstChild("GNX_R")
    if not Remote or not Remote:IsA("RemoteEvent") then return false end
    local Key = Ragebot.GetRemoteKey(Tool, Ragebot.GetWeaponConfig(Tool))
    return Internal.Call(Remote.FireServer, Remote, Key, "KLWE89U0", Tool) == true
end

function Ragebot.BindReload(Tool)
    local Wallbang = Ragebot.Runtime.Wallbang

    if Ragebot.Settings.AutoReload ~= true then
        Ragebot.DisconnectReload()
        return
    end

    if Wallbang.ReloadTool == Tool then return end
    Ragebot.DisconnectReload()

    if not Tool or not Tool.Parent or not Tool:FindFirstChild("IsGun") then return end

    local Values = Tool:FindFirstChild("Values") if not Values then return end

    local Ammo = Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo")
    local Stored = Values:FindFirstChild("SERVER_StoredAmmo") or Values:FindFirstChild("StoredAmmo")
    Wallbang.ReloadTool = Tool

    local function Request()
        Ragebot.RequestReload(Tool)
    end

    if Ammo then Wallbang.ReloadConnections[#Wallbang.ReloadConnections + 1] = Ammo:GetPropertyChangedSignal("Value"):Connect(Request) end

    if Stored then Wallbang.ReloadConnections[#Wallbang.ReloadConnections + 1] = Stored:GetPropertyChangedSignal("Value"):Connect(Request) end

    Wallbang.ReloadConnections[#Wallbang.ReloadConnections + 1] = Tool.AncestryChanged:Connect(function()
        if not Tool.Parent then Ragebot.DisconnectReload() end
    end)

    Request()
end

function Ragebot.RefreshReload()
    if Ragebot.Settings.AutoReload ~= true then
        Ragebot.DisconnectReload()
        return
    end

    local Character = LocalPlayer.Character local Tool = Character and Character:FindFirstChildOfClass("Tool")
    Ragebot.BindReload(Tool)
end

function Ragebot.GetTargetCharacter(TargetObject)
    if not TargetObject then return nil end
    if TargetObject:IsA("Model") then return TargetObject end
    return TargetObject:FindFirstAncestorOfClass("Model")
end

function Ragebot.IsHitPart(Part)
    if not Part or not Part:IsA("BasePart") then return false end
    local Name = Part.Name
    return Name == "Head" or Name == "Torso" or Name == "UpperTorso" or Name == "LowerTorso"
        or Name == "Left Arm" or Name == "Right Arm" or Name == "Left Leg" or Name == "Right Leg"
        or Name == "LeftUpperArm" or Name == "RightUpperArm" or Name == "LeftLowerArm" or Name == "RightLowerArm"
        or Name == "LeftUpperLeg" or Name == "RightUpperLeg" or Name == "LeftLowerLeg" or Name == "RightLowerLeg"
end

function Ragebot.GetHitTolerance(Part)
    if not Part or not Part:IsA("BasePart") then return 0 end
    local Name = Part.Name
    if Name == "Head" then return 1.5 end
    if Name == "Torso" or Name == "UpperTorso" or Name == "LowerTorso" then return 3 end
    return 2.5
end

function Ragebot.GetCharacterModel(Object)
    if not Object then return nil end

    local Wallbang = Ragebot.Runtime.Wallbang
    local Cache = Wallbang.CharacterCache
    local CurrentTime = os.clock()
    local Entry = type(Cache) == "table" and Cache[Object] or nil

    if type(Entry) == "table"
        and Entry.Parent == Object.Parent
        and CurrentTime <= (tonumber(Entry.Expires) or 0)
    then
        if Entry.Model == false then return nil end

        if Entry.Model
            and Entry.Model.Parent
            and Object:IsDescendantOf(Entry.Model)
        then
            return Entry.Model
        end
    end

    local Current = Object

    while Current and Current ~= workspace do
        if Current:IsA("Model") and Current:FindFirstChildOfClass("Humanoid") then
            if type(Cache) == "table" then
                Cache[Object] = {
                    Parent = Object.Parent,
                    Model = Current,
                    Expires = CurrentTime + 0.75
                }
            end

            return Current
        end

        Current = Current.Parent
    end

    if type(Cache) == "table" then
        Cache[Object] = {
            Parent = Object.Parent,
            Model = false,
            Expires = CurrentTime + 0.22
        }
    end

    return nil
end
function Ragebot.IsBlocker(Part, LocalRoot)
    if not Part or not Part:IsA("BasePart") then return true end
    if Part:FindFirstChild("CanHitT") then return true end
    if Part.CanCollide ~= true then return false end
    if not LocalRoot or not LocalRoot:IsA("BasePart") then return true end
    return PhysicsService:CollisionGroupsAreCollidable(Part.CollisionGroup, LocalRoot.CollisionGroup)
end

function Ragebot.GetRayParams()
    local Wallbang = Ragebot.Runtime.Wallbang local Params = Wallbang.ValidationRayParams local Character = LocalPlayer.Character local CameraObject = workspace.CurrentCamera
    local DebrisFolder = workspace:FindFirstChild("Debris")

    if Wallbang.ValidationCharacter ~= Character
        or Wallbang.ValidationCamera ~= CameraObject
        or Wallbang.ValidationDebris ~= DebrisFolder
    then
        local Ignore = Wallbang.ValidationIgnore
        table.clear(Ignore)

        if CameraObject then Ignore[#Ignore + 1] = CameraObject end
        if Character then Ignore[#Ignore + 1] = Character end
        if DebrisFolder then Ignore[#Ignore + 1] = DebrisFolder end

        Params.FilterType = Enum.RaycastFilterType.Exclude
        Params.FilterDescendantsInstances = Ignore
        Params.IgnoreWater = true
        Params.RespectCanCollide = false

        Wallbang.ValidationCharacter = Character
        Wallbang.ValidationCamera = CameraObject
        Wallbang.ValidationDebris = DebrisFolder
    end

    return Params
end

function Ragebot.GetRayContext(TargetObject)
    local Character = LocalPlayer.Character local LocalRoot = Character and Character:FindFirstChild("HumanoidRootPart")
    if not LocalRoot then return nil end

    local TargetCharacter = Ragebot.GetTargetCharacter(TargetObject)
    if not TargetCharacter then return nil end

    return {
        LocalRoot = LocalRoot,
        TargetCharacter = TargetCharacter,
        TargetRoot = TargetCharacter:FindFirstChild("HumanoidRootPart"),
        Params = Ragebot.GetRayParams(),
        MaxOrigin = math.min(tonumber(Ragebot.Runtime.Wallbang.MaxOrigin) or 19, 19),
        HitRadius = Ragebot.GetHitRadius()
    }
end

function Ragebot.ValidatePath(Context, Origin, CandidateHit)
    if type(Context) ~= "table" or typeof(Origin) ~= "Vector3" or typeof(CandidateHit) ~= "Vector3" then return false, nil end

    local LocalRoot = Context.LocalRoot local TargetCharacter = Context.TargetCharacter
    if not LocalRoot or not LocalRoot.Parent or not TargetCharacter or not TargetCharacter.Parent then return false, nil end

    if (Origin - LocalRoot.Position).Magnitude > Context.MaxOrigin + 0.001 then return false, nil end

    local Delta = CandidateHit - Origin local Distance = Delta.Magnitude
    if Distance <= 0.001 then return false, nil end

    local Unit = Delta.Unit local Extra = math.max(6, Context.HitRadius) local TargetRoot = Context.TargetRoot
    if TargetRoot and TargetRoot.Parent then Extra = math.max(Extra, (CandidateHit - TargetRoot.Position).Magnitude + 8) end

    local Remaining = Distance + Extra local CurrentOrigin = Origin local Params = Context.Params local Skips = 0

    while Remaining > 0.001 and Skips < 64 do
        local Result = workspace:Raycast(CurrentOrigin, Unit * Remaining, Params)
        if not Result or not Result.Instance then return false, nil end

        local Part = Result.Instance local Owner = nil

        if Part:IsDescendantOf(TargetCharacter) then
            Owner = TargetCharacter
        else
            Owner = Ragebot.GetCharacterModel(Part)
        end

        if Owner == TargetCharacter then
            if Ragebot.IsHitPart(Part) then
                local Tolerance = Ragebot.GetHitTolerance(Part)
                if (Result.Position - Part.Position).Magnitude <= Tolerance + 0.05 then return true, Result end
                return false, Result
            end
        elseif Owner and Ragebot.IsHitPart(Part) then
            return false, Result
        elseif not Owner and Ragebot.IsBlocker(Part, LocalRoot) then
            return false, Result
        end

        local Travel = (Result.Position - CurrentOrigin).Magnitude local Step = 0.011
        Remaining -= Travel + Step
        CurrentOrigin = Result.Position + Unit * Step
        Skips += 1
    end

    return false, nil
end

function Ragebot.ValidateShot(Origin, CandidateHit, TargetObject)
    local Context = Ragebot.GetRayContext(TargetObject)
    if not Context then return false, nil end
    return Ragebot.ValidatePath(Context, Origin, CandidateHit)
end

function Ragebot.CheckPath(PointA, PointB, TargetObject)
    local Valid = Ragebot.ValidateShot(PointA, PointB, TargetObject)
    return Valid == true
end

function Ragebot.GetBasis(PoleDirection)
    if typeof(PoleDirection) ~= "Vector3" or PoleDirection.Magnitude <= 0.001 then return nil, nil, nil end

    local Pole = PoleDirection.Unit local Canonical = Pole

    if math.abs(Pole.X) > 0.0001 then
        if Pole.X < 0 then Canonical = -Pole end
    elseif math.abs(Pole.Y) > 0.0001 then
        if Pole.Y < 0 then Canonical = -Pole end
    elseif Pole.Z < 0 then
        Canonical = -Pole
    end

    local Reference = math.abs(Canonical.Y) < 0.92 and Vector3.new(0, 1, 0) or Vector3.new(1, 0, 0)

    local Tangent1 = Reference - Canonical * Reference:Dot(Canonical)
    if Tangent1.Magnitude <= 0.001 then
        Reference = Vector3.new(0, 0, 1)
        Tangent1 = Reference - Canonical * Reference:Dot(Canonical)
    end

    Tangent1 = Tangent1.Unit
    local Tangent2 = Canonical:Cross(Tangent1).Unit

    return Pole, Tangent1, Tangent2
end

function Ragebot.RouteValue(Value)
    return string.format("%.5f", tonumber(Value) or 0)
end

function Ragebot.RouteText(Value)
    return tostring(Value or ""):gsub("[|\r\n]", "/")
end

function Ragebot.NormalizeRouteStage(Stage)
    Stage = tostring(Stage or "Unknown")

    while Stage:sub(1, 7) == "Stored:" do
        Stage = Stage:sub(8)
    end

    while Stage:sub(-8) == ":Refined" or Stage:sub(-7) == ":Stable" do
        if Stage:sub(-8) == ":Refined" then
            Stage = Stage:sub(1, -9)
        else
            Stage = Stage:sub(1, -8)
        end
    end

    if Stage == "" then Stage = "Unknown" end
    return Stage
end

function Ragebot.GetRouteKey(Data)
    if type(Data) ~= "table" then return nil end

    local function Q(Value, Scale)
        return math.floor((tonumber(Value) or 0) * Scale + 0.5)
    end

    return table.concat({
        tostring(Data.PlaceId or 0),
        Q(Data.Distance, 0.10),
        Q(Data.Pitch, 20),
        Q(Data.OriginB1, 4),
        Q(Data.OriginB2, 4),
        Q(Data.OriginPole, 4),
        Q(Data.HitB1, 4),
        Q(Data.HitB2, 4),
        Q(Data.HitPole, 4)
    }, ":")
end

function Ragebot.AddStoredRoute(Data)
    if type(Data) ~= "table" then return false end

    Data.Stage = Ragebot.NormalizeRouteStage(Data.Stage)

    local Store = Ragebot.RouteStore local Key = Ragebot.GetRouteKey(Data)
    if not Key or Store.Keys[Key] then return false end

    Store.Keys[Key] = true
    Store.Routes[#Store.Routes + 1] = Data

    local PlaceKey = tostring(Data.PlaceId or 0)
    Store.ByPlace[PlaceKey] = Store.ByPlace[PlaceKey] or {}
    Store.ByPlace[PlaceKey][#Store.ByPlace[PlaceKey] + 1] = Data

    return true
end

function Ragebot.ParseRoute(Line)
    if type(Line) ~= "string" or Line:sub(1, 3) ~= "V1|" then return nil end

    local Fields = string.split(Line, "|")
    if #Fields < 23 then return nil end

    local Data = {
        PlaceId = tonumber(Fields[2]) or 0,
        GameId = tonumber(Fields[3]) or 0,
        Unix = tonumber(Fields[4]) or 0,
        Distance = tonumber(Fields[5]) or 0,
        Vertical = tonumber(Fields[6]) or 0,
        Pitch = tonumber(Fields[7]) or 0,
        Stage = Fields[8] or "",
        Part = Fields[9] or "",
        OriginB1 = tonumber(Fields[10]) or 0,
        OriginB2 = tonumber(Fields[11]) or 0,
        OriginPole = tonumber(Fields[12]) or 0,
        HitB1 = tonumber(Fields[13]) or 0,
        HitB2 = tonumber(Fields[14]) or 0,
        HitPole = tonumber(Fields[15]) or 0,
        NormalB1 = tonumber(Fields[16]) or 0,
        NormalB2 = tonumber(Fields[17]) or 0,
        NormalPole = tonumber(Fields[18]) or 0,
        BlockerB1 = tonumber(Fields[19]) or 0,
        BlockerB2 = tonumber(Fields[20]) or 0,
        BlockerPole = tonumber(Fields[21]) or 0,
        OriginMagnitude = tonumber(Fields[22]) or 0,
        LateralMagnitude = tonumber(Fields[23]) or 0,
        PreMagnitude = tonumber(Fields[24]) or 0,
        PreLateral = tonumber(Fields[25]) or 0,
        PrePole = tonumber(Fields[26]) or 0,
        RefineGain = tonumber(Fields[27]) or 0,
        RefineChecks = tonumber(Fields[28]) or 0,
        RefineMoves = tonumber(Fields[29]) or 0
    }

    if Data.Distance <= 0 then return nil end
    return Data
end

function Ragebot.LoadRoutes()
    local Store = Ragebot.RouteStore
    if Store.Loaded then return Store.Available end
    Store.Loaded = true

    if not Store.Available then return false end

    if not isfile(Store.Path) then
        writefile(Store.Path, Store.Header .. "\n")
        return true
    end

    local Content = readfile(Store.Path)
    if type(Content) ~= "string" then return false end

    for Line in (Content .. "\n"):gmatch("([^\r\n]+)") do
        local Data = Ragebot.ParseRoute(Line)
        if Data then Ragebot.AddStoredRoute(Data) end
    end

    return true
end

function Ragebot.EncodeRoute(Data)
    if type(Data) ~= "table" then return nil end

    return table.concat({
        "V1",
        tostring(Data.PlaceId or 0),
        tostring(Data.GameId or 0),
        tostring(Data.Unix or 0),
        Ragebot.RouteValue(Data.Distance),
        Ragebot.RouteValue(Data.Vertical),
        Ragebot.RouteValue(Data.Pitch),
        Ragebot.RouteText(Data.Stage),
        Ragebot.RouteText(Data.Part),
        Ragebot.RouteValue(Data.OriginB1),
        Ragebot.RouteValue(Data.OriginB2),
        Ragebot.RouteValue(Data.OriginPole),
        Ragebot.RouteValue(Data.HitB1),
        Ragebot.RouteValue(Data.HitB2),
        Ragebot.RouteValue(Data.HitPole),
        Ragebot.RouteValue(Data.NormalB1),
        Ragebot.RouteValue(Data.NormalB2),
        Ragebot.RouteValue(Data.NormalPole),
        Ragebot.RouteValue(Data.BlockerB1),
        Ragebot.RouteValue(Data.BlockerB2),
        Ragebot.RouteValue(Data.BlockerPole),
        Ragebot.RouteValue(Data.OriginMagnitude),
        Ragebot.RouteValue(Data.LateralMagnitude),
        Ragebot.RouteValue(Data.PreMagnitude),
        Ragebot.RouteValue(Data.PreLateral),
        Ragebot.RouteValue(Data.PrePole),
        Ragebot.RouteValue(Data.RefineGain),
        tostring(math.floor(tonumber(Data.RefineChecks) or 0)),
        tostring(math.floor(tonumber(Data.RefineMoves) or 0))
    }, "|")
end

function Ragebot.SaveRoute(BaseOrigin, TargetPosition, Pair, Stage)
    if typeof(BaseOrigin) ~= "Vector3" or typeof(TargetPosition) ~= "Vector3"
        or type(Pair) ~= "table" or typeof(Pair.Origin) ~= "Vector3"
    then
        return false
    end

    local Candidate = Pair.CandidateHit or Pair.Hit
    if typeof(Candidate) ~= "Vector3" then return false end

    if not Ragebot.LoadRoutes() then return false end

    local Shot = TargetPosition - BaseOrigin
    if Shot.Magnitude <= 0.001 then return false end

    local Pole, Basis1, Basis2 = Ragebot.GetBasis(Shot)
    if not Pole or not Basis1 or not Basis2 then return false end

    local OriginOffset = Pair.Origin - BaseOrigin local HitOffset = Candidate - TargetPosition
    local Normal = typeof(Pair.Normal) == "Vector3" and Pair.Normal or Vector3.zero local BlockerNormal = Vector3.zero

    local Axial = OriginOffset:Dot(Pole) local Lateral = OriginOffset - Pole * Axial

    local Data = {
        PlaceId = game.PlaceId,
        GameId = game.GameId,
        Unix = os.time(),
        Distance = Shot.Magnitude,
        Vertical = TargetPosition.Y - BaseOrigin.Y,
        Pitch = Pole.Y,
        Stage = tostring(Stage or Ragebot.LastStage or "Unknown"),
        Part = Pair.Part and Pair.Part.Name or "",
        OriginB1 = OriginOffset:Dot(Basis1),
        OriginB2 = OriginOffset:Dot(Basis2),
        OriginPole = Axial,
        HitB1 = HitOffset:Dot(Basis1),
        HitB2 = HitOffset:Dot(Basis2),
        HitPole = HitOffset:Dot(Pole),
        NormalB1 = Normal:Dot(Basis1),
        NormalB2 = Normal:Dot(Basis2),
        NormalPole = Normal:Dot(Pole),
        BlockerB1 = BlockerNormal:Dot(Basis1),
        BlockerB2 = BlockerNormal:Dot(Basis2),
        BlockerPole = BlockerNormal:Dot(Pole),
        OriginMagnitude = OriginOffset.Magnitude,
        LateralMagnitude = Lateral.Magnitude,
        PreMagnitude = tonumber(Pair.RefineStartMagnitude) or OriginOffset.Magnitude,
        PreLateral = tonumber(Pair.RefineStartLateral) or Lateral.Magnitude,
        PrePole = tonumber(Pair.RefineStartPole) or Axial,
        RefineGain = tonumber(Pair.RefineGain) or 0,
        RefineChecks = tonumber(Pair.RefineChecks) or 0,
        RefineMoves = tonumber(Pair.RefineMoves) or 0
    }

    local StoredData = table.clone(Data)
    StoredData.Stage = Ragebot.NormalizeRouteStage(Data.Stage)

    if not Ragebot.AddStoredRoute(StoredData) then return false end

    local Line = Ragebot.EncodeRoute(Data)
    if not Line then return false end

    local Store = Ragebot.RouteStore

    if type(appendfile) == "function" then
        appendfile(Store.Path, Line .. "\n")
    else
        local Existing = isfile(Store.Path) and readfile(Store.Path) or (Store.Header .. "\n")
        writefile(Store.Path, tostring(Existing or "") .. Line .. "\n")
    end

    return true
end

Ragebot.FibonacciData = {
    Origins = {},
    Hits = {},
    Trig = {},
    GoldenAngle = math.pi * (3 - math.sqrt(5)),
    GoldenRatio = 0.618033988749895
}

function Ragebot.GetFibonacciTrig(Index, Rotation)
    Index =
        math.max(
            math.floor(tonumber(Index) or 0),
            0
        )

    Rotation =
        tonumber(Rotation) or 0

    local Trig =
        Ragebot.FibonacciData.Trig

    local Entry =
        Trig[Index]

    if not Entry then
        local Angle =
            Ragebot.FibonacciData.GoldenAngle
            * Index

        Entry = {
            math.cos(Angle),
            math.sin(Angle)
        }

        Trig[Index] = Entry
    end

    if math.abs(Rotation) <= 0.0000001 then
        return Entry[1], Entry[2]
    end

    local RotationCos =
        math.cos(Rotation)

    local RotationSin =
        math.sin(Rotation)

    return
        Entry[1] * RotationCos
            - Entry[2] * RotationSin,
        Entry[2] * RotationCos
            + Entry[1] * RotationSin
end

function Ragebot.FibonacciCache(Target)
    local Wallbang = Ragebot.Runtime.Wallbang
    local Cache = Wallbang.Cache[Target]

    if type(Cache) ~= "table" then
        Cache = {}
        Wallbang.Cache[Target] = Cache
    end

    return Cache
end

function Ragebot.FibonacciParts(Character)
    if not Character or not Character.Parent then return {} end

    local Wallbang = Ragebot.Runtime.Wallbang
    local Preferred = tostring(
        Ragebot.Settings.TargetPart or "Head"
    )

    local Entry = Wallbang.PartCache[Character]

    if type(Entry) == "table"
        and Entry.Name == Preferred
        and type(Entry.Parts) == "table"
    then
        local Valid = #Entry.Parts > 0

        for Index = 1, #Entry.Parts do
            local Part = Entry.Parts[Index]

            if not Part
                or not Part.Parent
                or not Part:IsDescendantOf(Character)
                or not Ragebot.IsHitPart(Part)
            then
                Valid = false
                break
            end
        end

        if Valid then return Entry.Parts end
    end

    local Parts = {}
    local Seen = {}

    local function Add(Name)
        local Part = Character:FindFirstChild(Name)

        if Part
            and Part:IsA("BasePart")
            and Ragebot.IsHitPart(Part)
            and not Seen[Part]
        then
            Seen[Part] = true
            Parts[#Parts + 1] = Part
        end
    end

    Add(Preferred)
    Add("Head")
    Add("Torso")
    Add("UpperTorso")
    Add("LowerTorso")
    Add("Left Arm")
    Add("Right Arm")
    Add("Left Leg")
    Add("Right Leg")
    Add("LeftUpperArm")
    Add("RightUpperArm")
    Add("LeftUpperLeg")
    Add("RightUpperLeg")

    Wallbang.PartCache[Character] = {
        Name = Preferred,
        Parts = Parts
    }

    return Parts
end

function Ragebot.GetFibonacciTarget(TargetObject)
    if not TargetObject then return nil end
    if TargetObject:IsA("Model") then return TargetObject end
    return TargetObject:FindFirstAncestorOfClass("Model")
end

function Ragebot.FibonacciWorldBlocks(Part, LocalRoot)
    if not Part or not Part:IsA("BasePart") then return true end
    if Part:FindFirstChild("CanHitT") then return true end
    if Part.CanCollide ~= true then return false end
    if not LocalRoot or not LocalRoot:IsA("BasePart") then return true end

    return PhysicsService:CollisionGroupsAreCollidable(
        Part.CollisionGroup,
        LocalRoot.CollisionGroup
    )
end

function Ragebot.GetFibonacciRayParams(TargetCharacter)
    local Wallbang = Ragebot.Runtime.Wallbang
    local Params = Wallbang.FibonacciRayParams
    local Character = LocalPlayer.Character
    local CameraObject = workspace.CurrentCamera
    local LocalRoot = Character
        and Character:FindFirstChild("HumanoidRootPart")

    local DebrisFolder = workspace:FindFirstChild("Debris")
    local CharactersFolder = workspace:FindFirstChild("Characters")
    local FilterFolder = workspace:FindFirstChild("Filter")
    local MapFolder = workspace:FindFirstChild("Map")
    local CollisionGroup = LocalRoot
        and LocalRoot.CollisionGroup
        or "Default"

    local CurrentTime = os.clock()

    if CurrentTime >= (
            tonumber(Wallbang.FibonacciRayRefresh)
            or 0
        )
        or Wallbang.FibonacciRayCharacter ~= Character
        or Wallbang.FibonacciRayTarget ~= TargetCharacter
        or Wallbang.FibonacciRayCamera ~= CameraObject
        or Wallbang.FibonacciRayDebris ~= DebrisFolder
        or Wallbang.FibonacciRayCharacters ~= CharactersFolder
        or Wallbang.FibonacciRayFilter ~= FilterFolder
        or Wallbang.FibonacciRayMap ~= MapFolder
        or Wallbang.FibonacciRayCollisionGroup ~= CollisionGroup
    then
        local Ignore = Wallbang.FibonacciIgnore
        table.clear(Ignore)

        local function Add(Object)
            if Object then
                Ignore[#Ignore + 1] = Object
            end
        end

        Add(Character)
        Add(CameraObject)
        Add(DebrisFolder)
        Add(CharactersFolder)

        if TargetCharacter
            and (
                not CharactersFolder
                or not TargetCharacter:IsDescendantOf(
                    CharactersFolder
                )
            )
        then
            Add(TargetCharacter)
        end

        if FilterFolder then
            Add(FilterFolder:FindFirstChild("SpawnedPiles"))
            Add(FilterFolder:FindFirstChild("SpawnedTools"))
            Add(FilterFolder:FindFirstChild("SpawnedBread"))
            Add(FilterFolder:FindFirstChild("Spawns"))
            Add(FilterFolder:FindFirstChild("WaterCurrents"))
            Add(FilterFolder:FindFirstChild("ToolSpawns"))
        end

        if MapFolder then
            Add(MapFolder:FindFirstChild("Shopz"))
            Add(MapFolder:FindFirstChild("BredMakurz"))
            Add(MapFolder:FindFirstChild("ATMz"))
            Add(MapFolder:FindFirstChild("Security"))
            Add(MapFolder:FindFirstChild("StreetLights"))
        end

        Params.FilterType = Enum.RaycastFilterType.Exclude
        Params.FilterDescendantsInstances = Ignore
        Params.IgnoreWater = true
        Params.RespectCanCollide = false
        Params.CollisionGroup = CollisionGroup

        Wallbang.FibonacciRayCharacter = Character
        Wallbang.FibonacciRayTarget = TargetCharacter
        Wallbang.FibonacciRayCamera = CameraObject
        Wallbang.FibonacciRayDebris = DebrisFolder
        Wallbang.FibonacciRayCharacters = CharactersFolder
        Wallbang.FibonacciRayFilter = FilterFolder
        Wallbang.FibonacciRayMap = MapFolder
        Wallbang.FibonacciRayCollisionGroup = CollisionGroup
        Wallbang.FibonacciRayRefresh = CurrentTime + 0.35
    end

    return Params
end

function Ragebot.TraceFibonacci(
    Origin,
    Hit,
    TargetObject
)
    if typeof(Origin) ~= "Vector3"
        or typeof(Hit) ~= "Vector3"
        or not TargetObject
    then
        return false, nil, 0
    end

    local TargetCharacter =
        Ragebot.GetFibonacciTarget(
            TargetObject
        )

    if not TargetCharacter
        or not TargetCharacter.Parent
    then
        return false, nil, 0
    end

    local Character =
        LocalPlayer.Character

    local LocalRoot =
        Character
        and Character:FindFirstChild(
            "HumanoidRootPart"
        )

    if not LocalRoot then
        return false, nil, 0
    end

    local OriginMagnitude =
        (
            Origin
            - LocalRoot.Position
        ).Magnitude

    if OriginMagnitude > 19.001 then
        return false, nil, 0
    end

    local Delta =
        Hit - Origin

    local TotalDistance =
        Delta.Magnitude

    if TotalDistance <= 0.001 then
        return false, nil, 0
    end

    local Direction =
        Delta / TotalDistance

    local Params =
        Ragebot.GetFibonacciRayParams(
            TargetCharacter
        )

    local CurrentOrigin =
        Origin

    local Travelled = 0
    local Skips = 0
    local MaximumSkips = 384

    local BaseEpsilon =
        math.clamp(
            TotalDistance * 0.000035,
            0.008,
            0.028
        )

    local LastPart
    local RepeatCount = 0

    while Travelled
            < TotalDistance - 0.001
        and Skips < MaximumSkips
    do
        local Remaining =
            TotalDistance
            - Travelled

        if Remaining <= 0.001 then
            return true, nil, Skips
        end

        local Result =
            workspace:Raycast(
                CurrentOrigin,
                Direction * Remaining,
                Params
            )

        if not Result
            or not Result.Instance
        then
            return true, nil, Skips
        end

        local Part =
            Result.Instance

        local Owner =
            Ragebot.GetCharacterModel(
                Part
            )

        if not Owner
            and Ragebot.FibonacciWorldBlocks(
                Part,
                LocalRoot
            )
        then
            return false, Result, Skips
        end

        local SegmentMagnitude =
            (
                Result.Position
                - CurrentOrigin
            ).Magnitude

        if SegmentMagnitude
            > Remaining + 0.01
        then
            return true, nil, Skips
        end

        if Part == LastPart then
            RepeatCount += 1
        else
            LastPart = Part
            RepeatCount = 0
        end

        local Epsilon =
            math.min(
                BaseEpsilon
                * (
                    1
                    + RepeatCount * 0.50
                ),
                0.06
            )

        local Advance =
            math.max(
                SegmentMagnitude
                + Epsilon,
                Epsilon
            )

        Travelled =
            math.min(
                Travelled
                + Advance,
                TotalDistance
            )

        CurrentOrigin =
            Origin
            + Direction * Travelled

        Skips += 1
    end

    return
        Travelled
            >= TotalDistance - 0.001,
        nil,
        Skips
end

function Ragebot.ValidateFibonacci(
    Origin,
    Hit,
    TargetObject
)
    local Valid,
        Result,
        Skips =
        Ragebot.TraceFibonacci(
            Origin,
            Hit,
            TargetObject
        )

    return
        Valid == true,
        Result,
        Skips
end

function Ragebot.MakeFibonacciPair(
    Origin,
    CandidateHit,
    Part,
    Target,
    OriginOffset,
    AimOffset,
    PredictionOffset,
    Skips
)
    if typeof(Origin) ~= "Vector3"
        or typeof(CandidateHit) ~= "Vector3"
        or not Part
        or not Part:IsA("BasePart")
        or not Target
    then
        return nil
    end

    OriginOffset =
        typeof(OriginOffset) == "Vector3"
            and OriginOffset
            or Vector3.zero

    PredictionOffset =
        typeof(PredictionOffset) == "Vector3"
            and PredictionOffset
            or Vector3.zero

    AimOffset =
        typeof(AimOffset) == "Vector3"
            and AimOffset
            or CandidateHit
                - Part.Position
                - PredictionOffset

    return {
        Origin = Origin,
        Hit = CandidateHit,
        CandidateHit = CandidateHit,
        Part = Part,
        ValidatedPart = Part,
        Normal = Vector3.zero,
        Target = Target,
        Fibonacci = true,
        OriginOffset = OriginOffset,
        AimOffset = AimOffset,
        HitOffset = AimOffset,
        HitLocal =
            Part.CFrame:VectorToObjectSpace(
                AimOffset
            ),
        PredictionOffset = PredictionOffset,
        ScanSkips = tonumber(Skips) or 0
    }
end

function Ragebot.CacheFibonacci(
    BaseOrigin,
    TargetPosition,
    Target,
    Pair,
    Radius
)
    if typeof(BaseOrigin) ~= "Vector3"
        or typeof(TargetPosition) ~= "Vector3"
        or not Target
        or type(Pair) ~= "table"
        or typeof(Pair.Origin) ~= "Vector3"
        or typeof(Pair.CandidateHit) ~= "Vector3"
        or not Pair.Part
        or not Pair.Part:IsA("BasePart")
    then
        return
    end

    Radius =
        math.max(
            math.min(
                tonumber(Radius) or 19,
                25
            ),
            0.001
        )

    local OriginOffset =
        typeof(Pair.OriginOffset) == "Vector3"
            and Pair.OriginOffset
            or Pair.Origin - BaseOrigin

    if OriginOffset.Magnitude
        > Radius + 0.001
    then
        return
    end

    local PredictionOffset =
        typeof(Pair.PredictionOffset) == "Vector3"
            and Pair.PredictionOffset
            or Vector3.zero

    local AimOffset =
        typeof(Pair.AimOffset) == "Vector3"
            and Pair.AimOffset
            or Pair.CandidateHit
                - Pair.Part.Position
                - PredictionOffset

    local HitLocal =
        typeof(Pair.HitLocal) == "Vector3"
            and Pair.HitLocal
            or Pair.Part.CFrame:
                VectorToObjectSpace(
                    AimOffset
                )

    local Wallbang =
        Ragebot.Runtime.Wallbang

    local Threshold =
        math.clamp(
            tonumber(
                Wallbang.CacheThreshold
            ) or 0.5,
            0.1,
            5
        )

    local function Quantize(Value)
        Value =
            (tonumber(Value) or 0)
            / Threshold

        return Value >= 0
            and math.floor(Value + 0.5)
            or math.ceil(Value - 0.5)
    end

    local Key =
        table.concat({
            Pair.Part.Name,
            Quantize(OriginOffset.X),
            Quantize(OriginOffset.Y),
            Quantize(OriginOffset.Z),
            Quantize(HitLocal.X),
            Quantize(HitLocal.Y),
            Quantize(HitLocal.Z)
        }, ":")

    local Cache =
        Ragebot.FibonacciCache(
            Target
        )

    local Entry
    local EntryIndex

    for Index = 1, #Cache do
        if Cache[Index].Key == Key then
            Entry = Cache[Index]
            EntryIndex = Index
            break
        end
    end

    local CurrentTime =
        os.clock()

    if not Entry then
        Entry = {
            Key = Key,
            Hits = 0,
            Fails = 0
        }

        Cache[#Cache + 1] =
            Entry

        EntryIndex =
            #Cache
    end

    Entry.PartName =
        Pair.Part.Name

    Entry.OriginOffset =
        OriginOffset

    Entry.AimOffset =
        AimOffset

    Entry.HitLocal =
        HitLocal

    Entry.Hits =
        (tonumber(Entry.Hits) or 0)
        + 1

    Entry.Fails =
        math.max(
            (tonumber(Entry.Fails) or 0)
            - 1,
            0
        )

    Entry.LastUsed =
        CurrentTime

    Entry.TargetPosition =
        TargetPosition

    if EntryIndex
        and EntryIndex > 1
    then
        table.remove(
            Cache,
            EntryIndex
        )

        table.insert(
            Cache,
            1,
            Entry
        )
    end

    table.sort(
        Cache,
        function(A, B)
            local AFails =
                tonumber(A.Fails) or 0

            local BFails =
                tonumber(B.Fails) or 0

            if AFails ~= BFails then
                return AFails < BFails
            end

            local AHits =
                tonumber(A.Hits) or 0

            local BHits =
                tonumber(B.Hits) or 0

            if AHits ~= BHits then
                return AHits > BHits
            end

            return
                (tonumber(A.LastUsed) or 0)
                > (tonumber(B.LastUsed) or 0)
        end
    )

    local Limit =
        math.max(
            math.floor(
                tonumber(
                    Wallbang.CacheLimit
                ) or 30
            ),
            1
        )

    while #Cache > Limit do
        table.remove(Cache)
    end
end

function Ragebot.TryFibonacciCache(
    BaseOrigin,
    TargetPosition,
    Target,
    Radius,
    PredictionOffset
)
    if typeof(BaseOrigin) ~= "Vector3"
        or typeof(TargetPosition) ~= "Vector3"
        or not Target
        or not Target.Character
    then
        return nil, 0
    end

    local Wallbang =
        Ragebot.Runtime.Wallbang

    local Cache =
        Ragebot.FibonacciCache(
            Target
        )

    local Probe =
        math.min(
            #Cache,
            math.max(
                math.floor(
                    tonumber(
                        Wallbang.CacheProbe
                    ) or 10
                ),
                1
            )
        )

    local Checks = 0
    local Index = 1
    local Attempts = 0

    PredictionOffset =
        typeof(PredictionOffset) == "Vector3"
            and PredictionOffset
            or Vector3.zero

    while Attempts < Probe
        and Index <= #Cache
    do
        local Entry =
            Cache[Index]

        Attempts += 1

        local Part =
            Target.Character:FindFirstChild(
                tostring(
                    Entry.PartName or ""
                )
            )

        local HitLocal =
            typeof(Entry.HitLocal) == "Vector3"
            and Entry.HitLocal
            or nil

        local AimOffset =
            HitLocal
            and Part
            and Part:IsA("BasePart")
            and Part.CFrame:
                VectorToWorldSpace(
                    HitLocal
                )
            or Entry.AimOffset

        local ValidEntry =
            Part
            and Part:IsA("BasePart")
            and Ragebot.IsHitPart(Part)
            and typeof(Entry.OriginOffset)
                == "Vector3"
            and typeof(AimOffset)
                == "Vector3"
            and Entry.OriginOffset.Magnitude
                <= Radius + 0.001

        if not ValidEntry then
            table.remove(
                Cache,
                Index
            )

            continue
        end

        local Origin =
            BaseOrigin
            + Entry.OriginOffset

        local Hit =
            Part.Position
            + PredictionOffset
            + AimOffset

        Checks += 1

        local Valid, _, Skips =
            Ragebot.ValidateFibonacci(
                Origin,
                Hit,
                Target.Character
            )

        if Valid then
            local Pair =
                Ragebot.MakeFibonacciPair(
                    Origin,
                    Hit,
                    Part,
                    Target,
                    Entry.OriginOffset,
                    AimOffset,
                    PredictionOffset,
                    Skips
                )

            if Pair then
                Pair.Cached = true

                Entry.AimOffset =
                    AimOffset

                Entry.HitLocal =
                    Part.CFrame:
                        VectorToObjectSpace(
                            AimOffset
                        )

                Entry.Hits =
                    (tonumber(Entry.Hits) or 0)
                    + 1

                Entry.Fails = 0
                Entry.LastUsed = os.clock()

                if Index > 1 then
                    table.remove(
                        Cache,
                        Index
                    )

                    table.insert(
                        Cache,
                        1,
                        Entry
                    )
                end

                return Pair, Checks
            end
        end

        Entry.Fails =
            (tonumber(Entry.Fails) or 0)
            + 1

        Entry.Hits =
            math.max(
                (tonumber(Entry.Hits) or 0)
                - 0.25,
                0
            )

        if Entry.Fails >= 4 then
            table.remove(
                Cache,
                Index
            )
        else
            Index += 1
        end
    end

    table.sort(
        Cache,
        function(A, B)
            local AFails =
                tonumber(A.Fails) or 0

            local BFails =
                tonumber(B.Fails) or 0

            if AFails ~= BFails then
                return AFails < BFails
            end

            local AHits =
                tonumber(A.Hits) or 0

            local BHits =
                tonumber(B.Hits) or 0

            if AHits ~= BHits then
                return AHits > BHits
            end

            return
                (tonumber(A.LastUsed) or 0)
                > (tonumber(B.LastUsed) or 0)
        end
    )

    return nil, Checks
end

function Ragebot.Algo1Origins(Radius, Count, Phase)
    Radius = math.clamp(tonumber(Radius) or 19, 0.001, 19)
    Count = math.max(math.floor(tonumber(Count) or 30), 1)

    local Output = {}
    local Seen = {}

    local function Add(Point)
        if #Output >= Count or typeof(Point) ~= "Vector3" then return end
        if Point.Magnitude > Radius then Point = Point.Unit * Radius end

        local Key = table.concat({
            math.floor(Point.X * 32 + 0.5),
            math.floor(Point.Y * 32 + 0.5),
            math.floor(Point.Z * 32 + 0.5)
        }, ":")

        if Seen[Key] then return end
        Seen[Key] = true
        Output[#Output + 1] = Point
    end

    Add(Vector3.zero)

    local Directions = {
        Vector3.new(-1, 0, 0),
        Vector3.new(1, 0, 0),
        Vector3.new(0, -1, 0),
        Vector3.new(0, 1, 0),
        Vector3.new(0, 0, -1),
        Vector3.new(0, 0, 1)
    }

    local Scales = {1.00, 0.82, 0.64, 0.46, 0.28}

    for ScaleIndex = 1, #Scales do
        for DirectionIndex = 1, #Directions do
            Add(Directions[DirectionIndex] * Radius * Scales[ScaleIndex])
        end
    end

    return Output
end

function Ragebot.Algo2Origins(Radius, Count, Phase)
    Radius = math.clamp(tonumber(Radius) or 19, 0.001, 19)
    Count = math.max(math.floor(tonumber(Count) or 96), 1)
    Phase = math.max(math.floor(tonumber(Phase) or 0), 0)

    local Output = {}
    local Seen = {}
    local GoldenAngle = Ragebot.FibonacciData.GoldenAngle
    local GoldenRatio = Ragebot.FibonacciData.GoldenRatio
    local Rotation = Phase * GoldenAngle * GoldenRatio

    local function Add(Point)
        if #Output >= Count or typeof(Point) ~= "Vector3" then return end
        if Point.Magnitude > Radius then Point = Point.Unit * Radius end

        local Key = table.concat({
            math.floor(Point.X * 36 + 0.5),
            math.floor(Point.Y * 36 + 0.5),
            math.floor(Point.Z * 36 + 0.5)
        }, ":")

        if Seen[Key] then return end
        Seen[Key] = true
        Output[#Output + 1] = Point
    end

    Add(Vector3.zero)

    local DownCount = math.clamp(math.floor(Count * 0.10 + 0.5), 6, 14)

    for Index = 1, DownCount do
        local T = Index / DownCount
        Add(Vector3.new(0, -Radius * (0.20 + 0.80 * T ^ 0.76), 0))
    end

    local LowerCount = math.clamp(math.floor(Count * 0.56 + 0.5), 18, Count)

    for Index = 0, LowerCount - 1 do
        if #Output >= Count then break end

        local T = (Index + 0.5) / LowerCount
        local Y = -1 + 0.94 * T ^ 0.72
        local Ring = math.sqrt(math.max(1 - Y * Y, 0))
        local Angle = Rotation + GoldenAngle * Index
        local VolumeT = (Index * 0.7548776662466927 + 0.5) % 1
        local ShellScale = Index % 3 == 0 and 1 or 0.30 + 0.70 * VolumeT ^ (1 / 3)

        Add(Vector3.new(math.cos(Angle) * Ring, Y, math.sin(Angle) * Ring) * Radius * ShellScale)
    end

    local FillIndex = 0

    while #Output < Count and FillIndex < Count * 10 do
        local VerticalT = (FillIndex * GoldenRatio + 0.5) % 1
        local Y = 1 - 2 * VerticalT
        local Ring = math.sqrt(math.max(1 - Y * Y, 0))
        local Angle = Rotation + GoldenAngle * (FillIndex + LowerCount + DownCount)
        local RadiusT = (FillIndex * 0.5698402909980532 + 0.25) % 1
        local ShellScale = FillIndex % 4 == 0 and 1 or 0.34 + 0.66 * RadiusT ^ (1 / 3)

        Add(Vector3.new(math.cos(Angle) * Ring, Y, math.sin(Angle) * Ring) * Radius * ShellScale)
        FillIndex += 1
    end

    return Output
end

function Ragebot.Algo3Origins(Radius, Count, Phase)
    Radius = math.clamp(tonumber(Radius) or 19, 0.001, 19)
    Count = math.max(math.floor(tonumber(Count) or 96), 1)
    Phase = math.max(math.floor(tonumber(Phase) or 0), 0)

    local Output = {}
    local Seen = {}
    local GoldenAngle = Ragebot.FibonacciData.GoldenAngle
    local Rotation = Phase * GoldenAngle * 0.5

    local function Add(Point)
        if #Output >= Count or typeof(Point) ~= "Vector3" then return end
        if Point.Magnitude > Radius then Point = Point.Unit * Radius end

        local Key = table.concat({
            math.floor(Point.X * 36 + 0.5),
            math.floor(Point.Y * 36 + 0.5),
            math.floor(Point.Z * 36 + 0.5)
        }, ":")

        if Seen[Key] then return end
        Seen[Key] = true
        Output[#Output + 1] = Point
    end

    Add(Vector3.zero)

    local Turns = 6
    local Samples = math.max(Count * 2, 1)

    for Index = 0, Samples do
        if #Output >= Count then break end

        local T = Index / Samples
        local Angle = Rotation + T * math.pi * 2 * Turns
        local Y = -1 + 2 * T
        local Ring = math.sqrt(math.max(1 - Y * Y, 0))
        local RadiusT = (Index * 0.618033988749895) % 1
        local SpiralRadius = 0.28 + 0.72 * RadiusT ^ (1 / 3)

        Add(Vector3.new(math.cos(Angle) * Ring, Y, math.sin(Angle) * Ring) * Radius * SpiralRadius)
    end

    return Output
end

function Ragebot.Algo4Origins(
    Radius,
    Count,
    Phase
)
    Radius =
        math.clamp(
            tonumber(Radius) or 19,
            0.001,
            19
        )

    Count =
        math.max(
            math.floor(
                tonumber(Count) or 96
            ),
            1
        )

    Phase =
        math.max(
            math.floor(
                tonumber(Phase) or 0
            ),
            0
        )

    local Output = {}
    local Seen = {}

    local GoldenAngle =
        Ragebot.FibonacciData.GoldenAngle

    local Rotation =
        Phase
        * GoldenAngle
        * 0.618033988749895

    local function Add(Point)
        if #Output >= Count
            or typeof(Point) ~= "Vector3"
        then
            return
        end

        if Point.Magnitude > Radius then
            Point =
                Point.Unit * Radius
        end

        local Key =
            table.concat({
                math.floor(
                    Point.X * 40 + 0.5
                ),
                math.floor(
                    Point.Y * 40 + 0.5
                ),
                math.floor(
                    Point.Z * 40 + 0.5
                )
            }, ":")

        if Seen[Key] then
            return
        end

        Seen[Key] = true
        Output[#Output + 1] = Point
    end

    Add(Vector3.zero)

    local SurfaceCount =
        math.max(
            Count - 1,
            1
        )

    for Index = 0,
        SurfaceCount - 1
    do
        if #Output >= Count then
            break
        end

        local T =
            (
                Index + 0.5
            ) / SurfaceCount

        local Y =
            1 - 2 * T

        local Ring =
            math.sqrt(
                math.max(
                    1 - Y * Y,
                    0
                )
            )

        local Angle =
            Rotation
            + GoldenAngle * Index

        Add(
            Vector3.new(
                math.cos(Angle) * Ring,
                Y,
                math.sin(Angle) * Ring
            ) * Radius
        )
    end

    return Output
end

function Ragebot.Algo5Origins(
    Radius,
    Count,
    Phase
)
    Radius =
        math.clamp(
            tonumber(Radius) or 19,
            0.001,
            19
        )

    Count =
        math.max(
            math.floor(
                tonumber(Count) or 96
            ),
            1
        )

    Phase =
        math.max(
            math.floor(
                tonumber(Phase) or 0
            ),
            0
        )

    local Output = {}
    local Seen = {}

    local GoldenAngle =
        Ragebot.FibonacciData.GoldenAngle

    local GoldenRatio =
        Ragebot.FibonacciData.GoldenRatio

    local Rotation =
        Phase
        * GoldenAngle
        * 0.7548776662466927

    local function Add(Point)
        if #Output >= Count
            or typeof(Point) ~= "Vector3"
        then
            return
        end

        if Point.Magnitude > Radius then
            Point =
                Point.Unit * Radius
        end

        local Key =
            table.concat({
                math.floor(
                    Point.X * 42 + 0.5
                ),
                math.floor(
                    Point.Y * 42 + 0.5
                ),
                math.floor(
                    Point.Z * 42 + 0.5
                )
            }, ":")

        if Seen[Key] then
            return
        end

        Seen[Key] = true
        Output[#Output + 1] = Point
    end

    Add(Vector3.zero)

    local OrbitBudget =
        math.clamp(
            math.floor(
                Count * 0.46 + 0.5
            ),
            12,
            math.max(
                Count - 1,
                12
            )
        )

    local OrbitLayers = {
        {-0.86, 0.46},
        {-0.62, 0.68},
        {-0.36, 0.84},
        {-0.12, 1.00},
        {0.18, 0.92},
        {0.46, 0.74},
        {0.72, 0.52}
    }

    local PerLayer =
        math.max(
            math.floor(
                OrbitBudget
                / #OrbitLayers
            ),
            1
        )

    for LayerIndex = 1,
        #OrbitLayers
    do
        if #Output >= Count then
            break
        end

        local Layer =
            OrbitLayers[LayerIndex]

        local YRatio =
            Layer[1]

        local RadiusScale =
            Layer[2]

        local Ring =
            math.sqrt(
                math.max(
                    1
                    - YRatio
                        * YRatio,
                    0
                )
            )

        for Index = 0,
            PerLayer - 1
        do
            if #Output >= Count then
                break
            end

            local Angle =
                Rotation
                + (
                    Index
                    / PerLayer
                ) * math.pi * 2
                + LayerIndex
                    * GoldenAngle
                    * 0.31

            Add(
                Vector3.new(
                    math.cos(Angle)
                        * Ring
                        * RadiusScale,
                    YRatio,
                    math.sin(Angle)
                        * Ring
                        * RadiusScale
                ) * Radius
            )
        end
    end

    local InvisibleIndex = 0
    local InvisibleLimit =
        Count * 12

    while #Output < Count
        and InvisibleIndex
            < InvisibleLimit
    do
        local U =
            (
                (
                    InvisibleIndex + 0.5
                )
                * GoldenRatio
                + Phase * 0.1732050807568877
            ) % 1

        local V =
            (
                (
                    InvisibleIndex + 0.5
                )
                * 0.4142135623730951
                + Phase * 0.2718281828459045
            ) % 1

        local W =
            (
                (
                    InvisibleIndex + 0.5
                )
                * 0.7320508075688772
                + Phase * 0.1414213562373095
            ) % 1

        local Y =
            1 - 2 * U

        local Ring =
            math.sqrt(
                math.max(
                    1 - Y * Y,
                    0
                )
            )

        local Angle =
            Rotation
            + V * math.pi * 2

        local VolumeScale =
            0.14
            + 0.86
                * W ^ (1 / 3)

        local Point =
            Vector3.new(
                math.cos(Angle) * Ring,
                Y,
                math.sin(Angle) * Ring
            ) * Radius * VolumeScale

        if InvisibleIndex % 4 == 0 then
            local OrbitAngle =
                Rotation
                + GoldenAngle
                    * InvisibleIndex

            local Tilt =
                math.sin(
                    OrbitAngle * 0.5
                ) * 0.48

            Point =
                Vector3.new(
                    math.cos(OrbitAngle)
                        * Radius
                        * 0.86,
                    Tilt * Radius,
                    math.sin(OrbitAngle)
                        * Radius
                        * 0.86
                )
        end

        Add(Point)

        InvisibleIndex += 1
    end

    return Output
end

function Ragebot.FibonacciOrigins(
    Radius,
    Count,
    Phase,
    Algorithm
)
    Algorithm =
        math.clamp(
            math.floor(
                tonumber(Algorithm) or 2
            ),
            1,
            5
        )

    local Key =
        table.concat({
            Algorithm,
            math.floor(
                (
                    tonumber(Radius)
                    or 19
                ) * 100
                + 0.5
            ),
            math.floor(
                tonumber(Count) or 96
            ),
            math.floor(
                tonumber(Phase) or 0
            ) % 32
        }, ":")

    local Cached =
        Ragebot.FibonacciData.Origins[
            Key
        ]

    if type(Cached) == "table" then
        return Cached
    end

    local Output

    if Algorithm == 1 then
        Output =
            Ragebot.Algo1Origins(
                Radius,
                Count,
                Phase
            )
    elseif Algorithm == 2 then
        Output =
            Ragebot.Algo2Origins(
                Radius,
                Count,
                Phase
            )
    elseif Algorithm == 3 then
        Output =
            Ragebot.Algo3Origins(
                Radius,
                Count,
                Phase
            )
    elseif Algorithm == 4 then
        Output =
            Ragebot.Algo4Origins(
                Radius,
                Count,
                Phase
            )
    else
        Output =
            Ragebot.Algo5Origins(
                Radius,
                Count,
                Phase
            )
    end

    Ragebot.FibonacciData.Origins[
        Key
    ] = Output

    return Output
end

function Ragebot.GetFibonacciReachRadius(
    BaseRadius,
    Level
)
    BaseRadius =
        math.clamp(
            tonumber(BaseRadius) or 23.5,
            20,
            25
        )

    Level =
        math.clamp(
            math.floor(
                tonumber(Level) or 1
            ),
            1,
            6
        )

    local MaximumReach = 144

    if Level <= 1 then
        return BaseRadius
    end

    if Level >= 6 then
        return MaximumReach
    end

    local Phi =
        (
            1 + math.sqrt(5)
        ) * 0.5

    local T =
        (Level - 1) / 5

    local GoldenCurve =
        (
            math.exp(Phi * T)
            - 1
        )
        / (
            math.exp(Phi)
            - 1
        )

    local Hermite =
        T * T
        * (
            3 - 2 * T
        )

    local Ratio =
        MaximumReach
        / BaseRadius

    local GeometricCurve =
        (
            math.exp(
                math.log(Ratio)
                * Hermite
            )
            - 1
        )
        / (
            Ratio - 1
        )

    local Blend =
        math.clamp(
            GoldenCurve * 0.60
            + GeometricCurve * 0.40,
            0,
            1
        )

    local Reach =
        BaseRadius
        + (
            MaximumReach
            - BaseRadius
        ) * Blend

    return
        math.clamp(
            Reach,
            BaseRadius,
            MaximumReach
        )
end

function Ragebot.ExpandFibonacciState(State)
    if type(State) ~= "table" then return end

    State.MissSlices =
        (tonumber(State.MissSlices) or 0)
        + 1

    if State.MissSlices < 4 then
        return
    end

    State.MissSlices = 0

    local Level = math.clamp(
        math.floor(
            tonumber(State.ReachLevel) or 1
        ) + 1,
        1,
        6
    )

    if Level == State.ReachLevel then
        return
    end

    State.ReachLevel = Level
    State.HitRadius =
        Ragebot.GetFibonacciReachRadius(
            State.BaseHitRadius,
            Level
        )

    State.Hits =
        Ragebot.FibonacciHits(
            State.HitRadius,
            State.HitCount,
            State.Phase
        )

    State.Cursor = 0
end

function Ragebot.FibonacciHits(
    Radius,
    Count,
    Phase
)
    Radius =
        math.clamp(
            tonumber(Radius) or 23.5,
            20,
            144
        )

    Count =
        math.clamp(
            math.floor(
                tonumber(Count) or 96
            ),
            8,
            180
        )

    Phase =
        math.max(
            math.floor(
                tonumber(Phase) or 0
            ),
            0
        )

    local Key =
        table.concat({
            math.floor(
                Radius * 100 + 0.5
            ),
            Count,
            Phase % 32
        }, ":")

    local Cached =
        Ragebot.FibonacciData.Hits[
            Key
        ]

    if type(Cached) == "table" then
        return Cached
    end

    local Output = {}
    local Seen = {}

    local GoldenAngle =
        Ragebot.FibonacciData.GoldenAngle

    local GoldenRatio =
        Ragebot.FibonacciData.GoldenRatio

    local Rotation =
        Phase
        * GoldenAngle
        * 0.3819660112501051

    local function Quantize(Value)
        Value *= 24

        return Value >= 0
            and math.floor(Value + 0.5)
            or math.ceil(Value - 0.5)
    end

    local function Add(Offset)
        if #Output >= Count
            or typeof(Offset) ~= "Vector3"
        then
            return false
        end

        local Magnitude =
            Offset.Magnitude

        if Magnitude > Radius then
            Offset =
                Offset.Unit * Radius
        end

        local PointKey =
            table.concat({
                Quantize(Offset.X),
                Quantize(Offset.Y),
                Quantize(Offset.Z)
            }, ":")

        if Seen[PointKey] then
            return false
        end

        Seen[PointKey] = true

        Output[#Output + 1] =
            Offset

        return true
    end

    Add(Vector3.zero)

    local CoreRadius =
        math.clamp(
            Radius * 0.055,
            1.25,
            4.75
        )

    local CoreAxes = {
        Vector3.new(1, 0, 0),
        Vector3.new(-1, 0, 0),
        Vector3.new(0, 1, 0),
        Vector3.new(0, -1, 0),
        Vector3.new(0, 0, 1),
        Vector3.new(0, 0, -1)
    }

    for Index = 1, #CoreAxes do
        Add(
            CoreAxes[Index]
            * CoreRadius
        )
    end

    local CoreCornerRadius =
        CoreRadius * 0.82

    for X = -1, 1, 2 do
        for Y = -1, 1, 2 do
            for Z = -1, 1, 2 do
                Add(
                    Vector3.new(
                        X,
                        Y,
                        Z
                    ).Unit
                    * CoreCornerRadius
                )
            end
        end
    end

    local SkirtCount =
        math.clamp(
            math.floor(
                Count * 0.20 + 0.5
            ),
            6,
            24
        )

    local SkirtRadius =
        math.clamp(
            Radius * 0.14,
            CoreRadius * 1.45,
            math.min(
                Radius,
                18
            )
        )

    for Index = 0,
        SkirtCount - 1
    do
        if #Output >= Count then
            break
        end

        local T =
            (Index + 0.5)
            / SkirtCount

        local Y =
            -0.22
            - 0.70
                * T ^ 0.72

        local Ring =
            math.sqrt(
                math.max(
                    1 - Y * Y,
                    0
                )
            )

        local Angle =
            Rotation
            + GoldenAngle
                * Index

        local RadialJitter =
            0.72
            + 0.28
                * (
                    (
                        Index
                        * 0.7548776662466927
                    ) % 1
                )

        Add(
            Vector3.new(
                math.cos(Angle)
                    * Ring,
                Y,
                math.sin(Angle)
                    * Ring
            )
            * SkirtRadius
            * RadialJitter
        )
    end

    local MinimumRadius =
        math.max(
            CoreRadius * 1.18,
            1.5
        )

    local RadiusRatio =
        math.max(
            Radius / MinimumRadius,
            1
        )

    local FillIndex = 0
    local FillLimit =
        Count * 12

    while #Output < Count
        and FillIndex < FillLimit
    do
        local VerticalT =
            (
                (
                    FillIndex + 0.5
                ) * GoldenRatio
            ) % 1

        local LowerPass =
            FillIndex % 3 ~= 2

        local Y

        if LowerPass then
            Y =
                -(
                    0.05
                    + 0.95
                        * VerticalT ^ 0.68
                )
        else
            Y =
                1
                - 2
                    * VerticalT
        end

        local Ring =
            math.sqrt(
                math.max(
                    1 - Y * Y,
                    0
                )
            )

        local Angle =
            Rotation
            + GoldenAngle
                * (
                    FillIndex
                    + SkirtCount
                    + 7
                )

        local RadiusT =
            (
                (
                    FillIndex + 0.5
                )
                * 0.5698402909980532
            ) % 1

        local ShellRadius

        if FillIndex % 5 == 0 then
            ShellRadius =
                Radius
        elseif FillIndex % 7 == 0 then
            ShellRadius =
                MinimumRadius
                * (
                    RadiusRatio
                    ^ 0.32
                )
        else
            ShellRadius =
                MinimumRadius
                * (
                    RadiusRatio
                    ^ RadiusT
                )
        end

        Add(
            Vector3.new(
                math.cos(Angle)
                    * Ring,
                Y,
                math.sin(Angle)
                    * Ring
            )
            * ShellRadius
        )

        FillIndex += 1
    end

    Ragebot.FibonacciData.Hits[
        Key
    ] = Output

    return Output
end

function Ragebot.NewFibonacciState(
    Target,
    Character,
    Radius,
    HitRadius,
    OriginCount,
    HitCount,
    TargetPartName
)
    local ReachLevel = 1
    local ReachRadius = Ragebot.GetFibonacciReachRadius(HitRadius, ReachLevel)
    local Algorithm = 1

    return {
        Target = Target,
        Character = Character,
        Radius = Radius,
        BaseHitRadius = HitRadius,
        HitRadius = ReachRadius,
        OriginCount = OriginCount,
        HitCount = HitCount,
        TargetPartName = TargetPartName,
        ReachLevel = ReachLevel,
        MissSlices = 0,
        Phase = 0,
        Algorithm = Algorithm,
        Origins = Ragebot.FibonacciOrigins(Radius, OriginCount, 0, Algorithm),
        Hits = Ragebot.FibonacciHits(ReachRadius, HitCount, 0),
        Parts = Ragebot.FibonacciParts(Character),
        Cursor = 0
    }
end

function Ragebot.RefreshFibonacciState(State)
    if type(State) ~= "table"
        or not State.Character
    then
        return false
    end

    local Parts = State.Parts
    local Valid =
        type(Parts) == "table"
        and #Parts > 0

    if Valid then
        for Index = 1, #Parts do
            local Part = Parts[Index]

            if not Part
                or not Part.Parent
                or not Part:IsDescendantOf(
                    State.Character
                )
                or not Ragebot.IsHitPart(Part)
            then
                Valid = false
                break
            end
        end
    end

    if not Valid then
        State.Parts =
            Ragebot.FibonacciParts(
                State.Character
            )

        State.Cursor = 0
    end

    return #State.Parts > 0
end

function Ragebot.RotateFibonacciState(State)
    if type(State) ~= "table" then
        return
    end

    local Algorithm =
        math.clamp(
            math.floor(
                tonumber(
                    State.Algorithm
                ) or 1
            ),
            1,
            5
        )

    if Algorithm < 5 then
        Algorithm += 1
    else
        Algorithm = 1
        State.Phase += 1

        Ragebot.ExpandFibonacciState(
            State
        )
    end

    State.Algorithm =
        Algorithm

    State.Origins =
        Ragebot.FibonacciOrigins(
            State.Radius,
            State.OriginCount,
            State.Phase,
            Algorithm
        )

    State.Hits =
        Ragebot.FibonacciHits(
            State.HitRadius,
            State.HitCount,
            State.Phase
        )

    State.Cursor = 0
end

function Ragebot.FibonacciRoute(State)
    local OriginCount = #State.Origins
    local PartCount = #State.Parts
    local HitCount = #State.Hits

    if OriginCount <= 0
        or PartCount <= 0
        or HitCount <= 0
    then
        return nil, 0
    end

    local ManipulatedOrigins =
        math.max(
            OriginCount - 1,
            0
        )

    local CrossHits =
        math.max(
            HitCount - 1,
            0
        )

    local CenterSweep = PartCount
    local PrimaryAimSweep = CrossHits

    local OriginCenterSweep =
        ManipulatedOrigins
        * PartCount

    local BroadCrossSweep =
        ManipulatedOrigins
        * PartCount

    local FullCrossSweep =
        ManipulatedOrigins
        * PartCount
        * CrossHits

    local Total =
        CenterSweep
        + PrimaryAimSweep
        + OriginCenterSweep
        + BroadCrossSweep
        + FullCrossSweep

    if State.Cursor >= Total then
        return nil, Total
    end

    local Route = State.Cursor
    State.Cursor += 1

    if Route < CenterSweep then
        return
            1,
            Route + 1,
            1,
            Total
    end

    Route -= CenterSweep

    if Route < PrimaryAimSweep then
        return
            1,
            1,
            Route + 2,
            Total
    end

    Route -= PrimaryAimSweep

    if Route < OriginCenterSweep then
        if ManipulatedOrigins <= 0 then
            return nil, Total
        end

        local OriginIndex =
            Route % ManipulatedOrigins
            + 2

        local PartIndex =
            math.floor(
                Route / ManipulatedOrigins
            ) % PartCount
            + 1

        return
            OriginIndex,
            PartIndex,
            1,
            Total
    end

    Route -= OriginCenterSweep

    if Route < BroadCrossSweep then
        if ManipulatedOrigins <= 0
            or CrossHits <= 0
        then
            return nil, Total
        end

        local OriginBase =
            Route % ManipulatedOrigins

        local PartBase =
            math.floor(
                Route / ManipulatedOrigins
            ) % PartCount

        local HitBase =
            (
                OriginBase * 37
                + PartBase * 13
                + State.Phase * 17
            ) % CrossHits

        return
            OriginBase + 2,
            PartBase + 1,
            HitBase + 2,
            Total
    end

    Route -= BroadCrossSweep

    if ManipulatedOrigins <= 0
        or CrossHits <= 0
    then
        return nil, Total
    end

    local OriginIndex =
        Route % ManipulatedOrigins
        + 2

    local PairIndex =
        math.floor(
            Route / ManipulatedOrigins
        )

    local HitIndex =
        PairIndex % CrossHits
        + 2

    local PartIndex =
        math.floor(
            PairIndex / CrossHits
        ) % PartCount
        + 1

    return
        OriginIndex,
        PartIndex,
        HitIndex,
        Total
end
function Ragebot.ResetFibonacciSearch(Target)
    local State =
        Ragebot.Runtime.Wallbang.State

    if type(State) == "table"
        and (
            not Target
            or State.Target == Target
        )
    then
        State.Cursor = 0
    end
end

function Ragebot.DropFibonacci(Pair)
    local Wallbang =
        Ragebot.Runtime.Wallbang

    Wallbang.ValidPair = nil
    Wallbang.LockedPath = nil
    Wallbang.Cached = false

    if type(Wallbang.LastPair) == "table"
        and (
            not Pair
            or not Pair.Target
            or Wallbang.LastPair.Target
                == Pair.Target
        )
    then
        Wallbang.LastPair = nil
    end

    Ragebot.ResetFibonacciSearch(
        Pair and Pair.Target or nil
    )
end

function Ragebot.RememberFibonacci(Pair)
    if type(Pair) ~= "table"
        or not Pair.Target
        or not Pair.Part
        or not Pair.Part:IsA("BasePart")
        or typeof(Pair.OriginOffset)
            ~= "Vector3"
        or typeof(Pair.AimOffset)
            ~= "Vector3"
    then
        return
    end

    Ragebot.Runtime.Wallbang.LastPair = {
        Target = Pair.Target,
        PartName = Pair.Part.Name,
        OriginOffset = Pair.OriginOffset,
        AimOffset = Pair.AimOffset,
        HitLocal =
            typeof(Pair.HitLocal) == "Vector3"
            and Pair.HitLocal
            or Pair.Part.CFrame:
                VectorToObjectSpace(
                    Pair.AimOffset
                ),
        LastUsed = os.clock()
    }
end

function Ragebot.TryLastFibonacci(
    BaseOrigin,
    Target,
    Radius,
    PredictionOffset
)
    local Wallbang =
        Ragebot.Runtime.Wallbang

    local Last =
        Wallbang.LastPair

    if type(Last) ~= "table"
        or Last.Target ~= Target
        or not Target
        or not Target.Character
    then
        return nil, 0, false
    end

    local Part =
        Target.Character:FindFirstChild(
            tostring(
                Last.PartName or ""
            )
        )

    local AimOffset =
        Part
        and Part:IsA("BasePart")
        and typeof(Last.HitLocal) == "Vector3"
        and Part.CFrame:
            VectorToWorldSpace(
                Last.HitLocal
            )
        or Last.AimOffset

    if not Part
        or not Part:IsA("BasePart")
        or not Ragebot.IsHitPart(Part)
        or typeof(Last.OriginOffset)
            ~= "Vector3"
        or typeof(AimOffset)
            ~= "Vector3"
        or Last.OriginOffset.Magnitude
            > Radius + 0.001
    then
        Wallbang.LastPair = nil
        return nil, 0, true
    end

    PredictionOffset =
        typeof(PredictionOffset) == "Vector3"
            and PredictionOffset
            or Vector3.zero

    local Origin =
        BaseOrigin
        + Last.OriginOffset

    local Hit =
        Part.Position
        + PredictionOffset
        + AimOffset

    local Valid, _, Skips =
        Ragebot.ValidateFibonacci(
            Origin,
            Hit,
            Target.Character
        )

    if not Valid then
        Wallbang.LastPair = nil
        return nil, 1, true
    end

    local Pair =
        Ragebot.MakeFibonacciPair(
            Origin,
            Hit,
            Part,
            Target,
            Last.OriginOffset,
            AimOffset,
            PredictionOffset,
            Skips
        )

    if not Pair then
        Wallbang.LastPair = nil
        return nil, 1, true
    end

    Pair.LastPair = true
    Pair.Cached = true

    Last.AimOffset = AimOffset
    Last.HitLocal =
        Part.CFrame:
            VectorToObjectSpace(
                AimOffset
            )
    Last.LastUsed = os.clock()

    return Pair, 1, false
end

function Ragebot.GetFibonacciBoxContact(
    Origin,
    Direction,
    Part,
    PredictionOffset
)
    if typeof(Origin) ~= "Vector3"
        or typeof(Direction) ~= "Vector3"
        or Direction.Magnitude <= 0.001
        or not Part
        or not Part:IsA("BasePart")
    then
        return nil
    end

    PredictionOffset =
        typeof(PredictionOffset) == "Vector3"
        and PredictionOffset
        or Vector3.zero

    Direction =
        Direction.Unit

    local VirtualCFrame =
        Part.CFrame
        + PredictionOffset

    local LocalOrigin =
        VirtualCFrame:
            PointToObjectSpace(
                Origin
            )

    local LocalDirection =
        VirtualCFrame:
            VectorToObjectSpace(
                Direction
            )

    local Half =
        Part.Size * 0.5

    local Minimum = -math.huge
    local Maximum = math.huge

    local function Clip(
        OriginAxis,
        DirectionAxis,
        Extent
    )
        if math.abs(DirectionAxis)
            <= 0.000001
        then
            return
                math.abs(OriginAxis)
                    <= Extent,
                Minimum,
                Maximum
        end

        local First =
            (
                -Extent
                - OriginAxis
            ) / DirectionAxis

        local Second =
            (
                Extent
                - OriginAxis
            ) / DirectionAxis

        if First > Second then
            First,
                Second =
                Second,
                First
        end

        local NewMinimum =
            math.max(
                Minimum,
                First
            )

        local NewMaximum =
            math.min(
                Maximum,
                Second
            )

        return
            NewMinimum
                <= NewMaximum,
            NewMinimum,
            NewMaximum
    end

    local Valid

    Valid,
        Minimum,
        Maximum =
        Clip(
            LocalOrigin.X,
            LocalDirection.X,
            Half.X
        )

    if not Valid then
        return nil
    end

    Valid,
        Minimum,
        Maximum =
        Clip(
            LocalOrigin.Y,
            LocalDirection.Y,
            Half.Y
        )

    if not Valid then
        return nil
    end

    Valid,
        Minimum,
        Maximum =
        Clip(
            LocalOrigin.Z,
            LocalDirection.Z,
            Half.Z
        )

    if not Valid then
        return nil
    end

    local Distance =
        Minimum >= 0
        and Minimum
        or Maximum

    if Distance < 0
        or Distance == math.huge
        or Distance ~= Distance
    then
        return nil
    end

    local LocalHit =
        LocalOrigin
        + LocalDirection
            * Distance

    local Margin =
        Vector3.new(
            math.max(
                Half.X - 0.015,
                0
            ),
            math.max(
                Half.Y - 0.015,
                0
            ),
            math.max(
                Half.Z - 0.015,
                0
            )
        )

    LocalHit =
        Vector3.new(
            math.clamp(
                LocalHit.X,
                -Margin.X,
                Margin.X
            ),
            math.clamp(
                LocalHit.Y,
                -Margin.Y,
                Margin.Y
            ),
            math.clamp(
                LocalHit.Z,
                -Margin.Z,
                Margin.Z
            )
        )

    return
        VirtualCFrame:
            PointToWorldSpace(
                LocalHit
            )
end

function Ragebot.ResolveFibonacciRegistration(
    Origin,
    SearchHit,
    Part,
    TargetCharacter,
    PredictionOffset
)
    if typeof(Origin) ~= "Vector3"
        or typeof(SearchHit) ~= "Vector3"
        or not Part
        or not Part:IsA("BasePart")
        or not TargetCharacter
    then
        return nil, 0, nil
    end

    PredictionOffset =
        typeof(PredictionOffset) == "Vector3"
        and PredictionOffset
        or Vector3.zero

    local SearchDelta =
        SearchHit - Origin

    if SearchDelta.Magnitude
        <= 0.001
    then
        return nil, 0, nil
    end

    local SearchDirection =
        SearchDelta.Unit

    local DirectContact =
        Ragebot.GetFibonacciBoxContact(
            Origin,
            SearchDirection,
            Part,
            PredictionOffset
        )

    local Checks = 0

    if DirectContact then
        Checks += 1

        local Valid,
            _,
            Skips =
            Ragebot.ValidateFibonacci(
                Origin,
                DirectContact,
                TargetCharacter
            )

        if Valid then
            return
                DirectContact,
                Checks,
                tonumber(Skips) or 0
        end
    end

    local VirtualCFrame =
        Part.CFrame
        + PredictionOffset

    local Half =
        Part.Size * 0.5

    local Scale = 0.78

    local LocalCandidates = {
        Vector3.zero,
        Vector3.new(
            Half.X * Scale,
            0,
            0
        ),
        Vector3.new(
            -Half.X * Scale,
            0,
            0
        ),
        Vector3.new(
            0,
            Half.Y * Scale,
            0
        ),
        Vector3.new(
            0,
            -Half.Y * Scale,
            0
        ),
        Vector3.new(
            0,
            0,
            Half.Z * Scale
        ),
        Vector3.new(
            0,
            0,
            -Half.Z * Scale
        )
    }

    local Ranked = {}

    for Index = 1,
        #LocalCandidates
    do
        local Point =
            VirtualCFrame:
                PointToWorldSpace(
                    LocalCandidates[Index]
                )

        local Delta =
            Point - Origin

        if Delta.Magnitude > 0.001 then
            Ranked[#Ranked + 1] = {
                Point = Point,
                Score =
                    SearchDirection:Dot(
                        Delta.Unit
                    )
            }
        end
    end

    table.sort(
        Ranked,
        function(A, B)
            return A.Score > B.Score
        end
    )

    local ProbeLimit =
        math.min(
            #Ranked,
            5
        )

    for Index = 1,
        ProbeLimit
    do
        local Point =
            Ranked[Index].Point

        Checks += 1

        local Valid,
            _,
            Skips =
            Ragebot.ValidateFibonacci(
                Origin,
                Point,
                TargetCharacter
            )

        if Valid then
            return
                Point,
                Checks,
                tonumber(Skips) or 0
        end
    end

    return nil, Checks, nil
end

function Ragebot.GetRageBulletCount(Tool)
    local Config =
        Ragebot.GetWeaponConfig(
            Tool
        )

    if type(Config) ~= "table" then
        return 1
    end

    local Count =
        tonumber(
            Config.BulletsPerShot
        )
        or tonumber(
            Config.PelletsPerShot
        )
        or tonumber(
            Config.Pellets
        )
        or tonumber(
            Config.ProjectileCount
        )
        or 1

    return
        math.clamp(
            math.floor(
                Count
            ),
            1,
            32
        )
end

function Ragebot.SendRageDamage(
    DamageRemote,
    Tool,
    ShotCode,
    DamagePart,
    DamagePosition,
    Direction
)
    if not DamageRemote
        or not DamageRemote:IsA(
            "RemoteEvent"
        )
        or not Tool
        or not Tool:IsA("Tool")
        or not DamagePart
        or not DamagePart:IsA(
            "BasePart"
        )
        or typeof(DamagePosition)
            ~= "Vector3"
        or typeof(Direction)
            ~= "Vector3"
        or Direction.Magnitude
            <= 0.001
    then
        return false, 0
    end

    local FireServer =
        DamageRemote.FireServer

    if type(FireServer)
        ~= "function"
    then
        return false, 0
    end

    local UnitDirection =
        Direction.Unit

    local BulletCount =
        Ragebot.GetRageBulletCount(
            Tool
        )

    local Marker =
        game.GameId == 1494262959
        and "🧈"
        or "🍯"

    local Sent = 0

    for BulletIndex = 1,
        BulletCount
    do
        if game.GameId
            == 1494262959
        then
            FireServer(
                DamageRemote,
                Marker,
                Tool,
                ShotCode,
                BulletIndex,
                DamagePart,
                DamagePosition,
                UnitDirection,
                {
                    HIP = nil
                }
            )
        else
            FireServer(
                DamageRemote,
                Marker,
                math.huge,
                Tool,
                ShotCode,
                BulletIndex,
                DamagePart,
                DamagePosition,
                UnitDirection,
                Tool,
                nil,
                19052023.49
            )
        end

        Sent += 1
    end

    return Sent > 0,
        Sent
end

function Ragebot.FindFibonacci(
    BaseOrigin,
    Target,
    Radius,
    Budget,
    TargetPosition,
    PredictionOffset
)
    if typeof(BaseOrigin) ~= "Vector3"
        or not Target
        or not Target.Character
    then
        return nil, 0, false, "AtramentaScan"
    end

    local Character = Target.Character
    local TargetRoot =
        Character:FindFirstChild(
            "HumanoidRootPart"
        )

    TargetPosition =
        typeof(TargetPosition) == "Vector3"
            and TargetPosition
            or (
                TargetRoot
                and TargetRoot.Position
            )

    if typeof(TargetPosition) ~= "Vector3" then
        return nil, 0, false, "AtramentaScan"
    end

    PredictionOffset =
        typeof(PredictionOffset) == "Vector3"
            and PredictionOffset
            or Vector3.zero

    local Wallbang =
        Ragebot.Runtime.Wallbang

    Radius = math.min(
        math.max(
            tonumber(Radius) or 0,
            0
        ),
        19
    )

    local HitRadius =
        Ragebot.GetHitRadius()

    Budget = math.max(
        math.floor(
            tonumber(Budget)
            or Wallbang.ScanBudget
            or 1200
        ),
        1
    )

    if Radius <= 0 then
        return nil, 0, true, "AtramentaScan"
    end

    local Checks = 0

    local LastPair,
        LastChecks,
        LastFailed =
        Ragebot.TryLastFibonacci(
            BaseOrigin,
            Target,
            Radius,
            PredictionOffset
        )

    Checks += LastChecks

    if LastPair then
        return
            LastPair,
            Checks,
            false,
            "AtramentaScanLast"
    end

    if LastFailed then
        Ragebot.ResetFibonacciSearch(Target)
    end

    local Cached, CacheChecks =
        Ragebot.TryFibonacciCache(
            BaseOrigin,
            TargetPosition,
            Target,
            Radius,
            PredictionOffset
        )

    Checks += CacheChecks

    if Cached then
        return
            Cached,
            Checks,
            false,
            "AtramentaScanCache"
    end

    if Checks >= Budget then
        return nil, Checks, false, "AtramentaScan"
    end

    local OriginCount =
        math.clamp(
            math.floor(
                tonumber(
                    Wallbang.OriginScans
                ) or 96
            ),
            30,
            180
        )

    local HitCount =
        math.clamp(
            math.floor(
                tonumber(
                    Wallbang.HitScans
                ) or 96
            ),
            8,
            180
        )

    local TargetPartName =
        tostring(
            Ragebot.Settings.TargetPart
            or "Head"
        )

    local State = Wallbang.State

    if type(State) ~= "table"
        or State.Target ~= Target
        or State.Character ~= Character
        or math.abs(
            (
                tonumber(State.Radius)
                or 0
            ) - Radius
        ) > 0.001
        or math.abs(
            (
                tonumber(State.BaseHitRadius)
                or 0
            ) - HitRadius
        ) > 0.001
        or State.OriginCount ~= OriginCount
        or State.HitCount ~= HitCount
        or State.TargetPartName
            ~= TargetPartName
    then
        State =
            Ragebot.NewFibonacciState(
                Target,
                Character,
                Radius,
                HitRadius,
                OriginCount,
                HitCount,
                TargetPartName
            )

        Wallbang.State = State
    end

    if not Ragebot.RefreshFibonacciState(State) then
        return nil, Checks, true, "AtramentaScan"
    end

    local Completed = false

    while Checks < Budget do
        local OriginIndex,
            PartIndex,
            HitIndex,
            RouteTotal =
            Ragebot.FibonacciRoute(State)

        if not OriginIndex then
            Ragebot.RotateFibonacciState(State)
            Completed = true
            continue
        end

        local OriginOffset =
            State.Origins[OriginIndex]

        local Part =
            State.Parts[PartIndex]

        local AimOffset =
            State.Hits[HitIndex]

        if typeof(OriginOffset) ~= "Vector3"
            or not Part
            or not Part.Parent
            or typeof(AimOffset) ~= "Vector3"
        then
            continue
        end

        if OriginOffset.Magnitude
            > Radius + 0.001
        then
            OriginOffset =
                OriginOffset.Unit
                * Radius
        end

        local Origin =
            BaseOrigin
            + OriginOffset

        local Hit =
            Part.Position
            + PredictionOffset
            + AimOffset

        Checks += 1

        local Valid, _, Skips =
            Ragebot.ValidateFibonacci(
                Origin,
                Hit,
                Character
            )

        if Valid then
            local RegistrationHit,
                RegistrationChecks,
                RegistrationSkips =
                Ragebot.ResolveFibonacciRegistration(
                    Origin,
                    Hit,
                    Part,
                    Character,
                    PredictionOffset
                )

            Checks +=
                tonumber(
                    RegistrationChecks
                ) or 0

            if RegistrationHit then
                local RegistrationAimOffset =
                    RegistrationHit
                    - Part.Position
                    - PredictionOffset

                local Pair =
                    Ragebot.MakeFibonacciPair(
                        Origin,
                        RegistrationHit,
                        Part,
                        Target,
                        OriginOffset,
                        RegistrationAimOffset,
                        PredictionOffset,
                        RegistrationSkips
                            or Skips
                    )

                if Pair then
                    Pair.SearchHit = Hit
                    Pair.SearchAimOffset =
                        AimOffset
                    Pair.RegistrationHit =
                        RegistrationHit
                    Pair.RegistrationRepaired =
                        (
                            RegistrationHit
                            - Hit
                        ).Magnitude
                            > 0.025
                    Pair.OriginIndex =
                        OriginIndex
                    Pair.PartIndex =
                        PartIndex
                    Pair.HitIndex =
                        HitIndex
                    Pair.Route =
                        State.Cursor - 1
                    Pair.RouteTotal =
                        RouteTotal
                    Pair.Phase =
                        State.Phase
                    Pair.Algorithm =
                        State.Algorithm
                    Pair.Direct =
                        OriginIndex == 1
                        and HitIndex == 1

                    Ragebot.CacheFibonacci(
                        BaseOrigin,
                        TargetPosition,
                        Target,
                        Pair,
                        Radius
                    )

                    State.Cursor = 0
                    State.MissSlices = 0

                    return
                        Pair,
                        Checks,
                        false,
                        Pair.Direct
                            and "AtramentaAlgo"
                                .. tostring(
                                    State.Algorithm
                                    or 1
                                )
                                .. "Direct"
                            or "AtramentaAlgo"
                                .. tostring(
                                    State.Algorithm
                                    or 1
                                )
                end
            end
        end
    end

    Ragebot.ExpandFibonacciState(State)

    return
        nil,
        Checks,
        Completed,
        "AtramentaScan"
end
function Ragebot.GetTarget()
    local Character = LocalPlayer.Character
    local Root = Character
        and Character:FindFirstChild("HumanoidRootPart")

    if not Root then return nil end

    local CameraObject = workspace.CurrentCamera
    if not CameraObject then return nil end

    local Mode = tostring(
        Ragebot.Settings.TargetSelection
        or "Distance"
    )

    if Mode ~= "Distance"
        and Mode ~= "Mouse"
        and Mode ~= "FOV"
    then
        Mode = "Distance"
        Ragebot.Settings.TargetSelection = Mode
    end

    local MyPosition = Ragebot.GetPosition()
    local MousePosition = Ragebot.GetFieldOfViewPosition()
    local FOVRadius = math.clamp(
        tonumber(Ragebot.Settings.FOV) or 320,
        10,
        700
    )

    local function IsValid(Player)
        if not Player
            or Player == LocalPlayer
            or Player.Parent ~= Players
            or not Player.Character
        then
            return false
        end

        if not IsCombatTargetAllowed(Player) then
            return false
        end

        if not CombatChecks.Passes(
            Player,
            Player.Character,
            Ragebot.Settings
        ) then
            return false
        end

        return Player.Character:FindFirstChild(
            "HumanoidRootPart"
        ) ~= nil
    end

    local function GetMetric(Player)
        if not IsValid(Player) then return nil end

        local TargetRoot =
            Player.Character:FindFirstChild(
                "HumanoidRootPart"
            )

        if not TargetRoot then return nil end

        if Mode == "Distance" then
            return (
                TargetRoot.Position
                - MyPosition
            ).Magnitude
        end

        local Metric =
            Ragebot.GetTargetScreenMetric(
                Player.Character,
                MousePosition,
                CameraObject
            )

        if not Metric then return nil end

        if Mode == "FOV"
            and Metric > FOVRadius
        then
            return nil
        end

        return Metric
    end

    if Ragebot.Settings.LockTarget == true then
        local LockedMetric =
            GetMetric(Ragebot.CurrentTarget)

        if LockedMetric then
            return Ragebot.CurrentTarget
        end
    end

    local Best = nil
    local BestMetric = math.huge
    local CurrentMetric =
        GetMetric(Ragebot.CurrentTarget)

    for _, Player in ipairs(
        Players:GetPlayers()
    ) do
        local Metric = GetMetric(Player)

        if Metric
            and Metric < BestMetric
        then
            BestMetric = Metric
            Best = Player
        end
    end

    if Ragebot.CurrentTarget
        and CurrentMetric
        and Best
        and Ragebot.CurrentTarget ~= Best
    then
        local HoldMargin =
            Mode == "Distance"
            and 3
            or 10

        if CurrentMetric
            <= BestMetric + HoldMargin
        then
            Best = Ragebot.CurrentTarget
            BestMetric = CurrentMetric
        end
    end

    Ragebot.CurrentTarget = Best

    return Best
end

function Ragebot.AcquireTarget()
    local Target = Ragebot.GetTarget()
    if not Target or not Target.Character then return nil end
    local Part = Target.Character:FindFirstChild("HumanoidRootPart")
    return Target, Target.Character, Part
end

function Ragebot.UpdateRage()
    local Wallbang = Ragebot.Runtime.Wallbang

    if Ragebot.Enabled ~= true then
        Wallbang.ValidPair = nil
        Wallbang.LockedPath = nil
        Wallbang.State = nil
        return
    end

    Ragebot.RefreshReload()

    local Target = Ragebot.GetTarget()
    if not Target or not Target.Character then
        Wallbang.ValidPair = nil
        Wallbang.LockedPath = nil
        Wallbang.LastPair = nil
        Wallbang.Cached = false
        Wallbang.State = nil
        Ragebot.CurrentTarget = nil
        return
    end

    local Character = LocalPlayer.Character local MyRoot = Character and Character:FindFirstChild("HumanoidRootPart")
    local TargetRoot = Target.Character:FindFirstChild("HumanoidRootPart")

    if not MyRoot or not TargetRoot then
        Wallbang.ValidPair = nil
        Wallbang.LockedPath = nil
        Wallbang.Cached = false
        Wallbang.State = nil
        return
    end

    local PreferredPart = Target.Character:FindFirstChild(Ragebot.Settings.TargetPart or "Head")
        or Target.Character:FindFirstChild("Head") or Target.Character:FindFirstChild("Torso") or TargetRoot

    local MyPosition = Ragebot.GetPosition()
    local RawTargetPosition = PreferredPart.Position
    local MaxTargetDistance = math.max(
        tonumber(Wallbang.MaxTargetDistance) or 850,
        1
    )

    if (RawTargetPosition - MyPosition).Magnitude > MaxTargetDistance then
        Wallbang.ValidPair = nil
        Wallbang.LockedPath = nil
        Wallbang.Cached = false
        Ragebot.LastRoute = nil
        return
    end

    local TargetPosition = Ragebot.PredictPosition(Target, PreferredPart) or RawTargetPosition
    local PredictionOffset = TargetPosition - PreferredPart.Position
    Ragebot.CurrentTarget = Target

    if Wallbang.ValidPair
        and Wallbang.ValidPair.Target ~= Target
    then
        Wallbang.ValidPair = nil
        Wallbang.LockedPath = nil
        Wallbang.Cached = false
    end

    if Wallbang.LastPair
        and Wallbang.LastPair.Target ~= Target
    then
        Wallbang.LastPair = nil
    end

    if Wallbang.State
        and Wallbang.State.Target ~= Target
    then
        Wallbang.State = nil
    end

    if tick() - Wallbang.LastScan < 1 / Wallbang.ScanRate then return end
    Wallbang.LastScan = tick()

    local Radius = math.min(tonumber(Wallbang.OriginRadius) or 19, tonumber(Wallbang.MaxOrigin) or 19, 19)
    local Pair, Checks, Exhausted, Stage = Ragebot.FindFibonacci(
        MyPosition,
        Target,
        Radius,
        Wallbang.ScanBudget,
        TargetPosition,
        PredictionOffset
    )

    Ragebot.LastStage = Stage or "AtramentaFibonacci"
    Ragebot.LastScanCount = Checks

    if Pair then
        Wallbang.ValidPair = Pair
        Wallbang.LockedPath = nil
        Wallbang.Cached = Pair.Cached == true
        Ragebot.LastRoute = Pair

        Ragebot.SaveRoute(MyPosition, TargetPosition, Pair, Ragebot.LastStage)
        Ragebot.Fire()
        return
    end

    if Exhausted then Ragebot.LastRoute = nil end
end

function Ragebot.Fire()
    if Ragebot.Enabled ~= true then return end

    local Wallbang =
        Ragebot.Runtime.Wallbang

    local Pair = Wallbang.ValidPair

    if not Pair
        or not Pair.Target
        or not Pair.Target.Character
    then
        return
    end

    if not IsCombatTargetAllowed(Pair.Target) then
        Ragebot.DropFibonacci(Pair)
        return
    end

    local Character = LocalPlayer.Character
    local Tool = Character
        and Character:FindFirstChildOfClass("Tool")

    if not Tool
        or not Tool:FindFirstChild("IsGun")
    then
        return
    end

    local Delay = math.clamp(
        tonumber(Ragebot.Settings.Delay) or 0.03,
        0.01,
        0.50
    )

    if Ragebot.Runtime.RateTool ~= Tool
        or math.abs(
            (
                tonumber(
                    Ragebot.Runtime.AppliedFireDelay
                )
                or -1
            ) - Delay
        ) > 0.0001
    then
        Ragebot.ApplyFireRate(
            Tool,
            Delay
        )
    end

    if tick() - Wallbang.LastShot < Delay then
        return
    end

    local Values = Tool:FindFirstChild("Values")
    local Ammo = Values
        and (
            Values:FindFirstChild("SERVER_Ammo")
            or Values:FindFirstChild("Ammo")
        )

    if not Ammo
        or Ammo.Value <= 0
    then
        Ragebot.RequestReload(Tool, true)
        return
    end

    if Ammo.Value <= 1 then
        Ragebot.RequestReload(Tool, false)
    end

    local TargetCharacter =
        Pair.Target.Character

    local LocalRoot = Character
        and Character:FindFirstChild(
            "HumanoidRootPart"
        )

    if not LocalRoot then return end

    local DistancePart =
        Pair.Part
        and Pair.Part:IsA("BasePart")
        and Pair.Part
        or TargetCharacter:FindFirstChild("HumanoidRootPart")

    local MaxTargetDistance = math.max(
        tonumber(Wallbang.MaxTargetDistance) or 850,
        1
    )

    if DistancePart
        and (DistancePart.Position - LocalRoot.Position).Magnitude > MaxTargetDistance
    then
        Ragebot.DropFibonacci(Pair)
        return
    end

    if (
        Pair.Origin
        - LocalRoot.Position
    ).Magnitude
        > Wallbang.MaxOrigin + 0.001
    then
        Ragebot.DropFibonacci(Pair)
        return
    end

    local Part
    local HitPosition
    local DamageHitPosition
    local SurfaceNormal

    if Pair.Fibonacci then
        if not Pair.Part
            or not Pair.Part:IsA("BasePart")
            or not Pair.Part:IsDescendantOf(
                TargetCharacter
            )
        then
            Ragebot.DropFibonacci(Pair)
            return
        end

        local OriginOffset =
            typeof(Pair.OriginOffset) == "Vector3"
                and Pair.OriginOffset
                or Pair.Origin
                    - LocalRoot.Position

        if OriginOffset.Magnitude
            > Wallbang.MaxOrigin + 0.001
        then
            Ragebot.DropFibonacci(Pair)
            return
        end

        local PredictionOffset =
            typeof(Pair.PredictionOffset)
                == "Vector3"
                and Pair.PredictionOffset
                or Vector3.zero

        local AimOffset =
            typeof(Pair.HitLocal)
                == "Vector3"
                and Pair.Part.CFrame:
                    VectorToWorldSpace(
                        Pair.HitLocal
                    )
            or typeof(Pair.AimOffset)
                == "Vector3"
                and Pair.AimOffset
            or typeof(Pair.HitOffset)
                == "Vector3"
                and Pair.HitOffset
            or Vector3.zero

        local CurrentOrigin =
            LocalRoot.Position
            + OriginOffset

        local CurrentHit =
            Pair.Part.Position
            + PredictionOffset
            + AimOffset

        local Valid, _, Skips =
            Ragebot.ValidateFibonacci(
                CurrentOrigin,
                CurrentHit,
                TargetCharacter
            )

        if not Valid then
            Ragebot.DropFibonacci(Pair)
            return
        end

        Pair.Origin = CurrentOrigin
        Pair.Hit = CurrentHit
        Pair.CandidateHit = CurrentHit
        Pair.ValidatedPart = Pair.Part
        Pair.Normal = Vector3.zero
        Pair.AimOffset = AimOffset
        Pair.HitOffset = AimOffset
        Pair.HitLocal =
            Pair.Part.CFrame:VectorToObjectSpace(
                AimOffset
            )
        Pair.ScanSkips =
            tonumber(Skips) or 0

        Pair.RouteValidAtFire =
            true

        Pair.RouteValidatedAt =
            os.clock()

        Part = Pair.Part
        HitPosition = CurrentHit

        DamageHitPosition =
            CurrentHit

        SurfaceNormal =
            -(
                CurrentHit
                - CurrentOrigin
            ).Unit
    else
        local Valid, Result =
            Ragebot.ValidateShot(
                Pair.Origin,
                Pair.CandidateHit or Pair.Hit,
                TargetCharacter
            )

        if not Valid
            or not Result
            or not Result.Instance
            or not Result.Instance:IsA("BasePart")
        then
            Wallbang.ValidPair = nil
            Wallbang.LockedPath = nil
            return
        end

        Part = Result.Instance
        HitPosition = Result.Position
        DamageHitPosition = HitPosition
        SurfaceNormal =
            typeof(Result.Normal) == "Vector3"
                and Result.Normal
                or nil
    end

    DamageHitPosition =
        typeof(DamageHitPosition) == "Vector3"
            and DamageHitPosition
            or HitPosition

    local Delta =
        HitPosition
        - Pair.Origin

    if Delta.Magnitude <= 0.001 then
        return
    end

    local Key =
        "K"
        .. math.random(
            1000,
            9999
        )

    local UnitDirection =
        Delta.Unit

    local PacketDirection =
        UnitDirection

    local DamagePart =
        Part

    local DamageVector =
        SurfaceNormal
        or -UnitDirection

    if Pair.Fibonacci then
        PacketDirection =
            UnitDirection

        DamageVector =
            UnitDirection

        if not DamagePart
            or not Ragebot.IsHitPart(
                DamagePart
            )
        then
            local TargetHead =
                TargetCharacter:FindFirstChild(
                    "Head"
                )

            if TargetHead
                and TargetHead:IsA(
                    "BasePart"
                )
            then
                DamagePart =
                    TargetHead
            end
        end
    end

    local Events =
        ReplicatedStorage:FindFirstChild("Events")

    local ShootRemote =
        Events
        and Events:FindFirstChild("GNX_S")

    local DamageRemote =
        Events
        and (
            Events:FindFirstChild("ZFKLF__H")
            or Events:FindFirstChild("ZFKLF_H")
        )

    if not ShootRemote
        or not DamageRemote
    then
        return
    end

    local Attack =
        Internal.RegisterLocalAttack(
            TargetCharacter,
            DamagePart,
            Key,
            Tool,
            "RageBot",
            Pair.Origin,
            UnitDirection
        )

    if Attack then
        Attack.Ragebot = true
        Attack.Prediction =
            tonumber(
                Ragebot.Settings.Prediction
            ) or 0

        Attack.PredictionDivisorX =
            tonumber(
                Ragebot.Settings.PredictionDivisorX
            ) or 1

        Attack.PredictionDivisorY =
            tonumber(
                Ragebot.Settings.PredictionDivisorY
            ) or 1

        Attack.RageWallbangStage =
            Ragebot.LastStage

        Attack.PacketOrigin = Pair.Origin
        Attack.PacketDirection = PacketDirection
        Attack.HitPosition = HitPosition
        Attack.DamageHitPosition = DamageHitPosition
        Attack.SurfaceNormal = SurfaceNormal
        Attack.CandidateHit = Pair.CandidateHit
        Attack.WallbangOriginOffset =
            Pair.Origin
            - LocalRoot.Position

        Attack.PacketMagnitude =
            PacketDirection.Magnitude

        Attack.PacketUnitDirection =
            PacketDirection.Magnitude > 0.001
            and PacketDirection.Unit
            or nil

        Attack.TargetDistance =
            Delta.Magnitude

        Attack.ScanSkips =
            tonumber(Pair.ScanSkips) or 0

        Attack.RouteValidAtFire =
            Pair.RouteValidAtFire == true

        Attack.RouteValidatedAt =
            tonumber(
                Pair.RouteValidatedAt
            ) or os.clock()

        Attack.PredictionOffsetAtFire =
            typeof(
                Pair.PredictionOffset
            ) == "Vector3"
            and Pair.PredictionOffset
            or Vector3.zero

        Attack.HitLocalAtFire =
            typeof(Pair.HitLocal)
                == "Vector3"
            and Pair.HitLocal
            or nil

        Attack.TargetCFrameAtFire =
            Part
            and Part:IsA("BasePart")
            and Part.CFrame
            or nil

        Attack.TargetSizeAtFire =
            Part
            and Part:IsA("BasePart")
            and Part.Size
            or nil

        Attack.RegistrationHit =
            Pair.RegistrationHit

        Attack.SearchHit =
            Pair.SearchHit

        Attack.RegistrationRepaired =
            Pair.RegistrationRepaired
                == true
    end

    local BulletType =
        true

    local RealBulletTypes =
        Ragebot.Runtime.RealBulletTypes

    if type(RealBulletTypes)
            == "table"
        and RealBulletTypes[Tool]
            ~= nil
    then
        BulletType =
            RealBulletTypes[Tool]
    end

    local ProtocolTimestamp =
        Ragebot.GetRemoteKey(
            Tool,
            Ragebot.GetWeaponConfig(
                Tool
            )
        )

    ShootRemote:FireServer(
        ProtocolTimestamp,
        Key,
        Tool,
        "FDS9I83",
        Pair.Origin,
        {PacketDirection},
        BulletType
    )

    if Attack then
        Attack.RageRemoteSent =
            true

        Attack.RageRemoteSentAt =
            os.clock()

        Attack.BulletTypeAtFire =
            BulletType
    end

    local DamageSent,
        DamagePackets =
        Ragebot.SendRageDamage(
            DamageRemote,
            Tool,
            Key,
            DamagePart,
            DamageHitPosition,
            DamageVector
        )

    if Attack then
        Attack.DamagePacketSent =
            DamageSent == true

        Attack.DamagePacketSentAt =
            DamageSent
            and os.clock()
            or nil

        Attack.DamagePacketCount =
            tonumber(
                DamagePackets
            ) or 0
    end

    Wallbang.LastShot = tick()
    Ragebot.LastTarget = Pair.Target

    if Pair.Fibonacci then
        Ragebot.RememberFibonacci(Pair)
        Ragebot.ResetFibonacciSearch(
            Pair.Target
        )
    end
end

function Ragebot.ScanOrigins(TargetPart, BaseOrigin)
    if not TargetPart or not TargetPart:IsA("BasePart") or typeof(BaseOrigin) ~= "Vector3" then return nil end

    local Character = TargetPart.Parent
    local Player = Character and Players:GetPlayerFromCharacter(Character)
    local TargetRoot = Character and Character:FindFirstChild("HumanoidRootPart")
    if not Player or not TargetRoot then return nil end

    local Wallbang = Ragebot.Runtime.Wallbang
    local Radius = math.min(tonumber(Wallbang.OriginRadius) or 19, tonumber(Wallbang.MaxOrigin) or 19, 19)
    local Pair = Ragebot.FindFibonacci(
        BaseOrigin,
        Player,
        Radius,
        Wallbang.ScanBudget,
        TargetPart.Position,
        Vector3.zero
    )

    if not Pair then return nil end

    local Delta = Pair.Hit - Pair.Origin
    if Delta.Magnitude <= 0.001 then return nil end

    local PacketLength = math.clamp(math.max(2048, Delta.Magnitude + 512), 2048, 20000)

    return {
        Origin = Pair.Origin,
        Hit = Pair.Hit,
        CandidateHit = Pair.CandidateHit,
        DamagePart = Pair.ValidatedPart or Pair.Part,
        SurfaceNormal = Pair.Normal,
        PacketDirection = Delta.Unit * PacketLength,
        Stage = Pair.Cached and "AtramentaFibonacciCache"
            or (Pair.Direct and "AtramentaFibonacciDirect" or "AtramentaFibonacci"),
        MagicBullet = true,
        Wallbang = true,
        StrictValidated = true
    }
end

function Ragebot.ServerRayCheck(
    Origin,
    Direction,
    TargetPart,
    HitPosition
)
    local Target =
        typeof(HitPosition) == "Vector3"
            and HitPosition
        or typeof(Direction) == "Vector3"
            and Direction.Magnitude > 0.001
            and Origin + Direction
        or nil

    if typeof(Origin) ~= "Vector3"
        or typeof(Target) ~= "Vector3"
    then
        return false, nil
    end

    if TargetPart
        and TargetPart:IsA("BasePart")
    then
        local Character =
            TargetPart:FindFirstAncestorOfClass(
                "Model"
            )

        if Character
            and Character:FindFirstChildOfClass(
                "Humanoid"
            )
        then
            return Ragebot.ValidateFibonacci(
                Origin,
                Target,
                Character
            )
        end

        return Ragebot.ValidateShot(
            Origin,
            Target,
            TargetPart
        )
    end

    return false, nil
end
function Ragebot.ApplyFireRate(Tool, Delay)
    Delay = math.clamp(tonumber(Delay) or tonumber(Ragebot.Settings.Delay) or 0.03, 0.01, 0.50)

    Ragebot.Runtime.AppliedFireDelay = Delay
    Ragebot.Runtime.RateTool = Tool
    AtramentaRageFireRate.Enabled = Ragebot.Enabled == true

    if Tool then RefreshAtramentaRageFireRateTool(Tool) end
    if type(ApplyGunValues) == "function" then ApplyGunValues() end

    return true
end

function Ragebot.RestoreFireRate()
    Ragebot.Runtime.AppliedFireDelay = nil
    Ragebot.Runtime.RateTool = nil
    RestoreAtramentaRageFireRate()
    if type(RestoreRageFireRateUpvalues) == "function" then RestoreRageFireRateUpvalues() end
    if type(ApplyGunValues) == "function" then ApplyGunValues() end
    local Character = LocalPlayer.Character
    local Tool = Character and Character:FindFirstChildOfClass("Tool")
    if Tool then RefreshAtramentaRageFireRateTool(Tool) end
end

function Ragebot.RestoreModePosition()
    Ragebot.Runtime.ModeMoveState = nil
end

function Ragebot.Enable()
    if Ragebot.Enabled then return end
    Ragebot.Enabled = true
    Environment.RageBotting = true
    Environment.RageBotLoopRunning = true
    Ragebot.Reset()
    Ragebot.RefreshFieldOfView()
    Ragebot.RefreshTargetLine()
    local Wallbang = Ragebot.Runtime.Wallbang
    Wallbang.LastShot = 0
    if Wallbang.FireConnection then
        Wallbang.FireConnection:Disconnect()
        Wallbang.FireConnection = nil
    end
    Ragebot.RefreshReload()
    local Character = LocalPlayer.Character
    local Tool = Character and Character:FindFirstChildOfClass("Tool")
    Ragebot.ApplyFireRate(Tool, Ragebot.Settings.Delay)
    if not Wallbang.SearchConnection then
        Wallbang.SearchConnection = RunService.Heartbeat:Connect(Ragebot.UpdateRage)
        AtramentaRuntimeControl:AddConnection(Wallbang.SearchConnection)
    end
end

function Ragebot.Disable()
    if Ragebot.Enabled ~= true then return end
    Ragebot.Enabled = false
    Environment.RageBotting = false
    Environment.RageBotLoopRunning = false
    local Wallbang = Ragebot.Runtime.Wallbang
    Wallbang.ValidPair, Wallbang.LastPair, Wallbang.State = nil, nil, nil
    if Wallbang.SearchConnection then
        Wallbang.SearchConnection:Disconnect()
        Wallbang.SearchConnection = nil
    end
    if Wallbang.FireConnection then
        Wallbang.FireConnection:Disconnect()
        Wallbang.FireConnection = nil
    end
    Ragebot.DisconnectReload()
    Ragebot.RestoreFireRate()
    Ragebot.CurrentTarget = nil
    Ragebot.LockedTarget = nil
    Ragebot.Runtime.Target = nil
    Ragebot.Reset()
    Ragebot.RefreshFieldOfView()
    Ragebot.DestroyTargetLine()
    if type(RefreshLocalShotTracking) == "function" then RefreshLocalShotTracking() end
end

do
    Environment.AtramentaAntiBarrier = AntiBarbwireEnabled == true
end

Environment.WallBang = true
if Ragebot.Settings.TargetSelection == "Near" or Ragebot.Settings.TargetSelection == "Nearest" then
    Ragebot.Settings.TargetSelection = "Distance"
elseif Ragebot.Settings.TargetSelection == "Centre" or Ragebot.Settings.TargetSelection == "Lock" then
    Ragebot.Settings.TargetSelection = "FOV"
end

if Ragebot.Settings.TargetSelection ~= "Distance"
    and Ragebot.Settings.TargetSelection ~= "Mouse"
    and Ragebot.Settings.TargetSelection ~= "FOV"
then
    Ragebot.Settings.TargetSelection = "Distance"
end

