    local function readCashAmountText()
        local candidates = { { "CoreGUI", "StatsFrame", "Frame2", "Frame", "Container", "Cash", "Amt" }, { "CoreGUI", "StatsFrame", "Frame2", "Frame", "Container", "Cash" } }
        for _, path in ipairs(candidates) do
