    local function ClearFarmRuntime()
        Farm.Destroyed = true
        for Index = #Farm.RuntimeThreads, 1, -1 do
            local Thread = Farm.RuntimeThreads[Index]
            if Thread and type(task.cancel) == "function" then Internal.Call(task.cancel, Thread) end
            Farm.RuntimeThreads[Index] = nil
        end
        for Index = #Farm.RuntimeConnections, 1, -1 do
            local Connection = Farm.RuntimeConnections[Index]
            if Connection and typeof(Connection) == "RBXScriptConnection" then Internal.Call(function() Connection:Disconnect() end) end
            Farm.RuntimeConnections[Index] = nil
        end
        for Key, Connection in pairs(Farm.TargetConnections) do
            if Connection and typeof(Connection) == "RBXScriptConnection" then Internal.Call(function() Connection:Disconnect() end) end
            Farm.TargetConnections[Key] = nil
        end
        for Index = #Farm.AdminConnections, 1, -1 do
            local Connection = Farm.AdminConnections[Index]
            if Connection and typeof(Connection) == "RBXScriptConnection" then Internal.Call(function() Connection:Disconnect() end) end
            Farm.AdminConnections[Index] = nil
        end
        if Farm.CashAddedConnection then Internal.Call(function() Farm.CashAddedConnection:Disconnect() end); Farm.CashAddedConnection = nil end
        if Farm.CashAddedTextConnection then Internal.Call(function() Farm.CashAddedTextConnection:Disconnect() end); Farm.CashAddedTextConnection = nil end
        if Farm.DiedConnection then Internal.Call(function() Farm.DiedConnection:Disconnect() end); Farm.DiedConnection = nil end
