        local map = getMap() local targetFolder = map and map:FindFirstChild("BredMakurz")
        if not targetFolder then return end
        for _, object in ipairs(targetFolder:GetChildren()) do
            local highlight = object:FindFirstChild("ESP_Highlight") local billboard = object:FindFirstChild("ESP_Billboard")
            if highlight then highlight:Destroy() end
            if billboard then billboard:Destroy() end
        end
    end

    local function disconnectTargetConnections()
        for object, connection in pairs(Farm.TargetConnections) do
            if connection then connection:Disconnect() end
            Farm.TargetConnections[object] = nil
        end
    end

    local function bindTargetModel(model)
        if not model or not model:IsA("Model") or not isSafeTarget(model) or Farm.TargetConnections[model] then return end
        local values = model:FindFirstChild("Values") local broken = values and values:FindFirstChild("Broken")
        if broken and broken:IsA("BoolValue") then
            Farm.TargetConnections[model] = broken:GetPropertyChangedSignal("Value"):Connect(function()
                Farm.ProcessedList[model] = nil
                Farm.RetargetPending = true
    end)
        end
    end

    local function bindTargetTracking()
        disconnectTargetConnections()
        local map = getMap() local targetFolder = map and map:FindFirstChild("BredMakurz")
        if not targetFolder then return end
        for _, object in ipairs(targetFolder:GetChildren()) do
            bindTargetModel(object)
        end
        Farm.TargetConnections.TargetAdded = targetFolder.ChildAdded:Connect(function(object)
            task.defer(function()
                bindTargetModel(object)
    end)
        end)
        Farm.TargetConnections.TargetRemoving = targetFolder.ChildRemoved:Connect(function(object)
            local connection = Farm.TargetConnections[object]
            if connection then
                connection:Disconnect()
                Farm.TargetConnections[object] = nil
            end
            Farm.ProcessedList[object] = nil
            Farm.TempIgnoredTargets[object] = nil
        end)
    end

    local CollectionService = game:GetService("CollectionService")

    local function GetSafeApproachCFrame(Safe, RootPosition)
        if typeof(RootPosition)
            ~= "Vector3" then
            local Root = getRoot()

            RootPosition = Root and Root.Position or Vector3.zero
        end

        local MainPart = nil local Model = nil

        if typeof(Safe)
            == "Instance" then
            if Safe:IsA("BasePart") then
                MainPart = Safe

                Model = Safe.Parent and Safe.Parent:IsA( "Model" ) and Safe.Parent or nil
            elseif Safe:IsA("Model") then
                Model = Safe

                MainPart = Safe:FindFirstChild( "MainPart")
            end
        end

        if not MainPart or not MainPart:IsA( "BasePart" ) then return nil end

        local SafeCFrame = MainPart.CFrame

        local SafeSize = MainPart.Size

        local SafeCenter = SafeCFrame.Position

        local Character = getCharacter()

        local Parameters = RaycastParams.new()

        Parameters.FilterType = Enum.RaycastFilterType.Exclude

        Parameters.IgnoreWater = true

        local Filter = {}

        if Character then Filter[#Filter + 1] = Character end

        if Model then
            Filter[#Filter + 1] = Model
        else
            Filter[#Filter + 1] = MainPart
        end

        Parameters. FilterDescendantsInstances = Filter

        local Root = getRoot()

        local CharacterRadius = Root and math.max( Root.Size.X, Root.Size.Z ) * 0.5 or 1

        local Clearance = math.clamp( CharacterRadius + 1.15, 2.1, 3.4)

        local HalfX = math.max( SafeSize.X * 0.5, 0.75)

        local HalfZ = math.max( SafeSize.Z * 0.5, 0.75)

        local Faces = { { Offset = Vector3.new( 0, 0, HalfZ + Clearance ),

                Direction = SafeCFrame.LookVector }, { Offset = Vector3.new( 0, 0, -HalfZ - Clearance ),

                Direction = -SafeCFrame.LookVector }, { Offset = Vector3.new( HalfX + Clearance, 0, 0 ),

                Direction = SafeCFrame.RightVector }, { Offset = Vector3.new( -HalfX - Clearance, 0, 0 ),

                Direction = -SafeCFrame.RightVector } }

        local Best = nil local BestScore = math.huge

        local MaximumHorizontalDistance = math.clamp( math.max( HalfX, HalfZ ) + Clearance + 1.25, 3.25, 7)

        for Index, Face in ipairs( Faces ) do
            local HorizontalPosition = SafeCFrame:PointToWorldSpace( Face.Offset)

            local ProbeOrigin = Vector3.new( HorizontalPosition.X, SafeCenter.Y + math.max( SafeSize.Y * 0.5 + 5, 8 ), HorizontalPosition.Z)

            local Ground = workspace:Raycast( ProbeOrigin, Vector3.new( 0, -24, 0 ), Parameters)

            if Ground then
                local Position = Ground.Position + Vector3.new( 0, 3.05, 0)

                local HorizontalOffset = Vector3.new( Position.X - SafeCenter.X, 0, Position.Z - SafeCenter.Z)

                if HorizontalOffset.Magnitude
                    > MaximumHorizontalDistance then
                    HorizontalOffset = HorizontalOffset.Unit * MaximumHorizontalDistance

                    Position = Vector3.new( SafeCenter.X + HorizontalOffset.X, Position.Y, SafeCenter.Z + HorizontalOffset.Z)
                end

                local VerticalDifference = math.abs( Position.Y - SafeCenter.Y)

                if VerticalDifference <= 7.5 then
                    local ToSafe = Vector3.new( SafeCenter.X - Position.X, 0, SafeCenter.Z - Position.Z)

                    local Candidate = ToSafe.Magnitude > 0.05 and CFrame.lookAt( Position, Position + ToSafe.Unit ) or CFrame.new( Position)

                    local HeadBlocked = workspace:Raycast( Position + Vector3.new( 0, 1.5, 0 ), Vector3.new( 0, 3.5, 0 ), Parameters)
                        ~= nil

                    local SafeDirection = ToSafe.Magnitude > 0.05 and ToSafe.Unit or -Face.Direction

                    local FrontBlocked = workspace:Raycast( Position + Vector3.new( 0, 1.2, 0 ), SafeDirection * math.min( Clearance * 0.55, 1.5 ), Parameters)
                        ~= nil

                    local DistanceScore = ( Position - RootPosition ).Magnitude

                    local VerticalPenalty = VerticalDifference * 3

                    local BlockPenalty = ( HeadBlocked or FrontBlocked ) and 1000 or 0

                    local Score = DistanceScore + VerticalPenalty + BlockPenalty + Index * 0.001

                    if Score < BestScore then
                        BestScore = Score
                        Best = Candidate
                    end
                end
            end
        end

        if Best then return Best end

        local FlatDirection = Vector3.new( RootPosition.X - SafeCenter.X, 0, RootPosition.Z - SafeCenter.Z)

        if FlatDirection.Magnitude
            <= 0.05 then
            FlatDirection = -SafeCFrame.LookVector else
            FlatDirection = FlatDirection.Unit
        end

        local FallbackDistance = math.clamp( math.max( HalfX, HalfZ ) + Clearance, 3, 6)

        local FallbackPosition = SafeCenter + FlatDirection * FallbackDistance

        FallbackPosition = Vector3.new( FallbackPosition.X, SafeCenter.Y + 2.9, FallbackPosition.Z)

        return CFrame.lookAt( FallbackPosition, Vector3.new( SafeCenter.X, FallbackPosition.Y, SafeCenter.Z ))
    end

    local function resolveFarmDestination(destination)
        local root = getRoot() local rootPos = root and root.Position or Vector3.zero

        if typeof(destination) == "Instance" then
            local approach = GetSafeApproachCFrame(destination, rootPos)
            if approach then return approach end
            if destination:IsA("BasePart") then
                local Direction = Vector3.new( rootPos.X - destination.Position.X, 0, rootPos.Z - destination.Position.Z)

                if Direction.Magnitude
                    <= 0.05 then
                    Direction = -destination.CFrame.LookVector else
                    Direction = Direction.Unit
                end

                local Position = destination.Position + Direction * math.clamp( math.max( destination.Size.X, destination.Size.Z ) * 0.5 + 2.75, 3.25, 6)

                Position = Vector3.new( Position.X, destination.Position.Y + 2.9, Position.Z)

                return CFrame.lookAt( Position, Vector3.new( destination.Position.X, Position.Y, destination.Position.Z ))
            end
        elseif typeof(destination) == "CFrame" then
            return destination
        elseif typeof(destination) == "Vector3" then
            return CFrame.new(destination)
        end
        return nil
    end

    local function getFarmRagdollRemote()
        local Events = ReplicatedStorage:FindFirstChild("Events") local remote = Events and Events:FindFirstChild("__RZDONL")
        if remote and remote:IsA("RemoteEvent") then return remote end
        return nil
    end

    local function cancelMagicTeleport()
        Farm.State.TeleportGeneration += 1
        Farm.State.TeleportBusy = false
        Environment.AtramentaFarmMove = false

        local Root = Farm.State.TeleportRoot

        if Root and Root.Parent then
            Root.Anchored = Farm.State.TeleportWasAnchored
                == true

            Root.AssemblyLinearVelocity = Vector3.zero

            Root.AssemblyAngularVelocity = Vector3.zero
        end

        Farm.State.TeleportRoot = nil
        Farm.State.TeleportWasAnchored = false
        Farm.State.TeleportLastTarget = nil
    end

    local function magicTeleportTo(destination, statusText)
        local Root = getRoot() local Humanoid = getHumanoid() local Character = getCharacter()

        if not Root or not Humanoid or not Character or isDead() or not Farm.Enabled then return false end

        local TargetCFrame = resolveFarmDestination( destination)

        if typeof(TargetCFrame)
            ~= "CFrame" then
            return false
        end

        local TargetPosition = TargetCFrame.Position

        local StartPosition = Root.Position

        local Distance = ( StartPosition - TargetPosition ).Magnitude

        if Distance <= 3.5 then
            Root.AssemblyLinearVelocity = Vector3.zero

            Root.AssemblyAngularVelocity = Vector3.zero

            return true
        end

        cancelMagicTeleport()

        Farm.State.TeleportGeneration += 1

        local Generation = Farm.State.TeleportGeneration

        Farm.State.TeleportBusy = true
        Farm.State.TeleportRoot = Root
        Farm.State.TeleportWasAnchored = Root.Anchored

        Farm.State.TeleportLastTarget = TargetCFrame

        Environment.AtramentaFarmMove = true

        setStatus( statusText or "Magic Teleport")

        local RagdollRemote = getFarmRagdollRemote()

        local function Active()
            return Farm.Enabled and Farm.State. TeleportGeneration
                    == Generation and not isDead()
        end

        Root.Anchored = false

        Root.AssemblyLinearVelocity = Vector3.zero

        Root.AssemblyAngularVelocity = Vector3.zero

        if RagdollRemote then RagdollRemote:FireServer( "__---r", Vector3.zero, Root.CFrame, false) end

        RunService.Heartbeat:Wait()

        if not Active() then
            cancelMagicTeleport()
            return false
        end

        Root = getRoot()
        Character = getCharacter()

        if not Root or not Character then
            cancelMagicTeleport()
            return false
        end

        local Rotation = TargetCFrame - TargetPosition

        local HorizontalDistance = Vector3.new( TargetPosition.X - StartPosition.X, 0, TargetPosition.Z - StartPosition.Z ).Magnitude

        local HeightDifference = TargetPosition.Y - StartPosition.Y

        local TransitHeight = math.clamp( StartPosition.Y + math.clamp( HeightDifference, -2.5, 4)
                    + 2.25, math.min( StartPosition.Y, TargetPosition.Y ) + 1.5, math.max( StartPosition.Y, TargetPosition.Y ) + 4)

        local TransitDirection = Vector3.new( TargetPosition.X - StartPosition.X, 0, TargetPosition.Z - StartPosition.Z)

        local TransitPosition = TargetPosition

        if TransitDirection.Magnitude
            > 8 then
            TransitPosition = TargetPosition - TransitDirection.Unit * math.clamp( TransitDirection.Magnitude * 0.08, 1.25, 3.5)
        end

        TransitPosition = Vector3.new( TransitPosition.X, TransitHeight, TransitPosition.Z)

        local TransitCFrame = CFrame.new( TransitPosition ) * Rotation

        Character:PivotTo( TransitCFrame)

        Root.AssemblyLinearVelocity = Vector3.zero

        Root.AssemblyAngularVelocity = Vector3.zero

        if RagdollRemote then RagdollRemote:FireServer( "__---r", Vector3.zero, TransitCFrame, false) end

        RunService.Heartbeat:Wait()

        if not Active() then
            cancelMagicTeleport()
            return false
        end

        Root = getRoot()
        Character = getCharacter()

        if not Root or not Character then
            cancelMagicTeleport()
            return false
        end

        Character:PivotTo( TargetCFrame)

        Root.AssemblyLinearVelocity = Vector3.zero

        Root.AssemblyAngularVelocity = Vector3.zero

        if RagdollRemote then RagdollRemote:FireServer( "__---r", Vector3.zero, TargetCFrame, false) end

        local Accepted = false local StableFrames = 0 local LastPosition = nil local Deadline = os.clock() + math.clamp( 0.26 + Distance / 5000, 0.26, 0.48)

        while os.clock() < Deadline do
            if not Active() then
                cancelMagicTeleport()
                return false
            end

            RunService.Heartbeat:Wait()

            Root = getRoot()

            if not Root then
                cancelMagicTeleport()
                return false
            end

            Root.AssemblyLinearVelocity = Vector3.zero

            Root.AssemblyAngularVelocity = Vector3.zero

            local ErrorDistance = ( Root.Position - TargetPosition ).Magnitude

            local FrameMovement = LastPosition and ( Root.Position - LastPosition ).Magnitude or 0

            LastPosition = Root.Position

            if ErrorDistance <= 5.25 and FrameMovement <= 2.75 then
                StableFrames += 1
            else
                StableFrames = 0
            end

            if StableFrames >= 3 then
                Accepted = true
                break
            end

            if ( Root.Position
                - StartPosition ).Magnitude <= 7 and os.clock() + 0.08
                    >= Deadline then
                break
            end
        end

        Root = getRoot()

        if Root and Root.Parent then
            Root.Anchored = Farm.State.TeleportWasAnchored
                == true

            Root.AssemblyLinearVelocity = Vector3.zero

            Root.AssemblyAngularVelocity = Vector3.zero
        end

        Farm.State.TeleportBusy = false
        Farm.State.TeleportRoot = nil
        Farm.State.TeleportWasAnchored = false
        Farm.State.TeleportLastTarget = nil
        Environment.AtramentaFarmMove = false

        if Accepted then
            Farm.State.TeleportLastSuccessAt = os.clock()

            return true
        end

        Farm.State.CooldownUntil = math.max( tonumber(Farm.State.CooldownUntil) or 0, tick() + 1.8)

        return false
    end

    local function facePosition(position)
        local root = getRoot() local character = getCharacter()
        if root and character and typeof(position) == "Vector3" then
            local flat = Vector3.new(position.X, root.Position.Y, position.Z)
            if (flat - root.Position).Magnitude > 0.05 then
                character:PivotTo(CFrame.lookAt(root.Position, flat))
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end

    local function moveToPosition(position, statusText)
        return magicTeleportTo(position, statusText)
    end

    local function moveRoute(positions, statusText)
        for Index, Position in ipairs( positions ) do
            if not Farm.Enabled or Farm.State.TeleportBusy then return false end

            if not moveToPosition( Position, statusText ) then return false end

            if Index < #positions then
                local Until = os.clock() + 0.12

                while os.clock() < Until do
                    if not Farm.Enabled then return false end

                    RunService.Heartbeat:Wait()
                end
            end
        end

        return true
    end

    local function enterTower(model, part)
        Farm.State.TowerZoneEntered = true
        if not moveRoute({Farm.State.TowerFirstPosition, Farm.State.TowerSecondPosition}, "Moving To Target") then return false end
        return moveToPosition(model or part, "Moving To Target")
    end

    local function leaveTower()
        if not Farm.State.TowerZoneEntered then return true end
        setStatus("Leaving Tower")
        local moved = moveRoute({Farm.State.TowerSecondPosition, Farm.State.TowerFirstPosition}, "Leaving Tower")
        Farm.State.TowerZoneEntered = false
        setStatus("Idle")
        return moved
    end

    local function enterSW11(model, part)
        Farm.State.SW11ZoneEntered = true
        local root = getRoot()
        Farm.State.SW11SavedEntryPathPoint = root and root.Position or nil
        Farm.State.SW11SavedVisualPath = {Farm.State.SW11FirstPosition, Farm.State.SW11SecondPosition, Farm.State.SW11ThirdPosition}
        setStatus("Entering SW_11")
        if not moveRoute(Farm.State.SW11SavedVisualPath, "Entering SW_11") then return false end
        return moveToPosition(model or part, "Entering SW_11")
    end

    local function leaveSW11()
        if not Farm.State.SW11ZoneEntered then return true end
        setStatus("Leaving SW_11")
        local moved = moveRoute({Farm.State.SW11ThirdPosition, Farm.State.SW11SecondPosition, Farm.State.SW11FirstPosition}, "Leaving SW_11")
        if moved and Farm.State.SW11SavedEntryPathPoint then moved = moveToPosition(Farm.State.SW11SavedEntryPathPoint, "Leaving SW_11") end
        Farm.State.SW11ZoneEntered = false
        Farm.State.SW11SavedEntryPathPoint = nil
        Farm.State.SW11SavedVisualPath = nil
        setStatus("Idle")
        return moved
    end

    local function enterZoneRoute(model, part)
        local route = ZoneRoutes[model.Name]
        if not route then return false end
        Farm.State.CurrentZoneRoute = route
        if not moveRoute({route.lowPos, route.highPos}, "Moving To Target") then return false end
        return moveToPosition(model or part, "Moving To Target")
    end

    local function leaveZoneRoute()
        local route = Farm.State.CurrentZoneRoute
        if not route then return true end
        local moved = moveRoute({route.highPos, route.lowPos}, "Leaving " .. route.zone)
        Farm.State.CurrentZoneRoute = nil
        return moved
    end

    local function enterSURoute(model, part)
        Farm.State.SUZoneEntered = true
        if not moveToPosition(Farm.State.SUFirstPosition, "Moving To Target") then return false end
        return moveToPosition(model or part, "Moving To Target")
    end

    local function leaveSURoute()
        if not Farm.State.SUZoneEntered then return true end
        local moved = moveToPosition(Farm.State.SUFirstPosition, "Leaving SU")
        Farm.State.SUZoneEntered = false
        return moved
    end

    local function moveToTargetByRoute(model, part)
        if SW11TargetNames[model.Name] then return enterSW11(model, part) end
        if TowerTargetNames[model.Name] then return enterTower(model, part) end
        if ZoneRoutes[model.Name] then return enterZoneRoute(model, part) end
        if SUTargetNames[model.Name] then return enterSURoute(model, part) end

        return moveToPosition(model or part, "Moving To Target")
    end

    local function teleportRecovery(destination)
        if destination == nil then return false end
        setStatus("Teleport Recovery")
        return magicTeleportTo(destination, "Teleport Recovery")
    end

    local function runRecoveryLoopFix()
        return moveRoute({ Farm.State.RecoveryLoopFixFrom, Farm.State.RecoveryLoopFixTo }, "Recovery Move")
    end

    local function recoveryMove(destination)
        local Root = getRoot()

        if not Root or destination == nil or Farm.State.TeleportBusy then return false end

        local CurrentTime = tick()

        if CurrentTime
            < ( tonumber(Farm.State.CooldownUntil) or 0 ) then
            return false
        end

        setStatus("Recovery Move")

        return moveToPosition( destination, "Recovery Move")
    end

    local function handlePostMoveSuccess(model)
        Farm.State.RetryCount = 0
        Farm.State.LastActiveAt = tick()
        Farm.State.HasReachedTargetY = true
        Farm.State.TargetY = getTargetPart(model) and getTargetPart(model).Position.Y or nil
        return true
    end

    local function handlePostMoveFailure(model, part)
        Farm.State.RetryCount += 1
        Farm.State.HasReachedTargetY = false
        Farm.State.CooldownUntil = math.max( tonumber(Farm.State.CooldownUntil) or 0, tick() + 1.8)

        if model then Farm.TempIgnoredTargets[ model ] = tick() + math.max( 4, tonumber(Settings.IgnoreDuration) or 6) end

        Farm.RetargetPending = true

        return false
    end

    local function processTargetMoveOutcome(model, part, moved)
        if moved then return handlePostMoveSuccess(model) end
        return handlePostMoveFailure(model, part)
    end

function Internal.getTool(namePattern)
        local character = getCharacter() local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
        for _, container in ipairs({character, backpack}) do
            if container then
                for _, tool in ipairs(container:GetChildren()) do
                    if tool:IsA("Tool") and string.find(string.lower(tool.Name), string.lower(namePattern), 1, true) then return tool end
                end
            end
        end
        return nil
    end

    local function equipTool(tool)
        local humanoid = getHumanoid() local character = getCharacter()
        if not humanoid or not tool or not character then return false end
        if tool.Parent == character then return true end

        Internal.Call(function()
            humanoid:UnequipTools()
        end)
        task.wait(0.05)
        Internal.Call(function()
            tool.Parent = character
        end)
        Internal.Call(function()
            humanoid:EquipTool(tool)
        end)
        task.wait(0.15)
        if tool.Parent ~= character then
            Internal.Call(function()
                tool.Parent = character
            end)
            task.wait(0.1)
        end
        return tool.Parent == character
    end

    local function unequipTools()
        local humanoid = getHumanoid()
        if humanoid then safeCall(humanoid.UnequipTools, humanoid) end
    end

    local function hasFistsTool()
        return Internal.getTool("fists") ~= nil
    end

    local ShopItemContracts = { Crowbar = { ShopType = "IllegalStore", Category = "Melees", ShopModelName = "Dealer" }, Lockpick = {
            ShopType = "LegalStore", Category = "Misc", ShopModelName = "ArmoryDealer" } }

    local function getShopMainPart(contract)
        local map = getMap() local shops = map and map:FindFirstChild("Shopz")
        local shop = shops and shops:FindFirstChild(contract.ShopModelName) local mainPart = shop and shop:FindFirstChild("MainPart")
        return mainPart and mainPart:IsA("BasePart") and mainPart or nil
    end

    local function buyItem(itemName)
        local contract = ShopItemContracts[itemName]
        if not contract then return false end
        local shopMainPart = getShopMainPart(contract)
        if not shopMainPart then return false end
        if not moveToPosition(shopMainPart.Position, "Moving To Dealer for " .. itemName) then return false end
        task.wait(Settings.ShopPreOpenSec)
        setStatus(itemName == "Lockpick" and "Buying Lockpicks (idle 5s in shop)" or "Buying " .. itemName)
        if ShopProtectionRemote then safeCall( ShopProtectionRemote.FireServer, ShopProtectionRemote, true, "shop", shopMainPart, contract.ShopType) end
        local ok, success = safeCall( ShopRemote.InvokeServer, ShopRemote, contract.ShopType, contract.Category, itemName, shopMainPart, nil, true)
        if ShopProtectionRemote then safeCall(ShopProtectionRemote.FireServer, ShopProtectionRemote, false) end
        task.wait(Settings.ShopAfterOpenSec)
        if not ok or not success then return false end
        local startedAt = tick()
        while tick() - startedAt < Settings.ShopBuyMaxWaitSec do
            if Internal.getTool(itemName) then
                task.wait(Settings.ShopPostBuySec)
                return true
            end
            task.wait(Settings.ShopBuyPollSec)
        end
        return false
    end

    local function ensureBreakingTools()
        if Settings.BreakingMethod == "Fist + Lockpick" then
            if not hasFistsTool() then return false end
            local lockpick = Internal.getTool("lockpick")
            if not lockpick then
                setStatus("Moving To Dealer for Lockpick")
                if not buyItem("Lockpick") then return false end
            end
            return true
        end
        local crowbar = Internal.getTool("crowbar")
        if not crowbar then
            setStatus("Buying Crowbar")
            if not buyItem("Crowbar") then return false end
        end
        return true
    end

    local function countToolsByName(name)
        local total = 0 local character = getCharacter() local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
        for _, container in ipairs({character, backpack}) do
            if container then
                for _, item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") and item.Name == name then total += 1 end
                end
            end
        end
        return total
    end

    local function findNearestLockpickShopPart()
        local root = getRoot() local selected local selectedDistance = math.huge
        for _, contract in ipairs({ ShopItemContracts.Lockpick, ShopItemContracts.Crowbar }) do
            local part = getShopMainPart(contract)
            if part then
                local distance = root and (part.Position - root.Position).Magnitude or 0
                if distance < selectedDistance then
                    selected = part
                    selectedDistance = distance
                end
            end
        end
        return selected
    end

    local function purchaseLockpickAt(shopPart)
        if not shopPart then return false end
        local illegalOk, illegalAccepted, illegalMessage = safeCall( ShopRemote.InvokeServer, ShopRemote, "IllegalStore", "Misc", "Lockpick", shopPart, nil,
            true, nil)
        task.wait(0.25)
        local legalOk, legalAccepted, legalMessage = safeCall( ShopRemote.InvokeServer, ShopRemote, "LegalStore", "Misc", "Lockpick", shopPart, nil, true)
        return illegalOk and (illegalAccepted == true or illegalMessage == "PURCHASE COMPLETE") or legalOk
            and (legalAccepted == true or legalMessage == "PURCHASE COMPLETE")
    end

    local function buyLockpickBatch(quantity)
        quantity = math.max(1, math.floor(tonumber(quantity) or 7))
        local shopPart = findNearestLockpickShopPart()
        if not shopPart then return false end
        if not moveToPosition(shopPart.Position, "Moving To Dealer for Lockpick") then return false end
        local startingCount = countToolsByName("Lockpick") local successfulPurchases = 0
        for _ = 1, quantity do
            if not Farm.Enabled then break end
            if purchaseLockpickAt(shopPart) then successfulPurchases += 1 end
            task.wait(0.20)
        end
        task.wait(0.75)
        return countToolsByName("Lockpick") > startingCount or successfulPurchases > 0
    end

    local function dropLockpick(tool)
        local root = getRoot()
        if not tool or not DropToolRemote or not root then return false end
        local ok = safeCall( DropToolRemote.FireServer, DropToolRemote, tool, nil, root.Position)
        return ok
    end

    local function tryLockpickTarget(target)
        local tool = Internal.getTool("Lockpick")
        if not tool then return false, "lockpick_missing" end
        if not equipTool(tool) then return false, "lockpick_equip_failed" end
        local remote = tool:FindFirstChild("Remote")
        if not remote or not remote:IsA("RemoteFunction") then return false, "lockpick_remote_missing" end
        local startOk, token = safeCall( remote.InvokeServer, remote, "S", target, "s")
        if startOk and type(token) == "number" then
            task.wait(0.25)
            local finishOk = safeCall( remote.InvokeServer, remote, "D", target, "s", token)
            return finishOk, finishOk and "lockpick_success" or "lockpick_finish_failed"
        end
        dropLockpick(tool)
        return false, "lockpick_failed"
    end

    local function strikeTargetWithCrowbar(target)
        local tool = Internal.getTool("Crowbar") local character = getCharacter()
        local targetPart = getTargetPart(target) local rightArm = character and ( character:FindFirstChild("Right Arm") or character:FindFirstChild("RightHand"))
        if not MeleeRemote or not MeleeHitRemote or not tool or not character or not rightArm or not targetPart then return false end

        if tool.Parent ~= character then equipTool(tool) end
        local invokeOk, token = safeCall( MeleeRemote.InvokeServer, MeleeRemote, "🍞", tick(), tool, "DZDRRRKI", target, "Register")
        if invokeOk and type(token) == "number" then
            local fireOk = safeCall( MeleeHitRemote.FireServer, MeleeHitRemote, "🍞", tick(), tool, "2389ZFX34", token, false, rightArm, targetPart, target,
                targetPart.Position, targetPart.Position)
            return fireOk
        end
        return invokeOk
    end

    local function breakTarget(target, targetPart)
        if not target or not target.Parent then return false end
        if isTargetBroken(target) then return true end
        if Settings.BreakingMethod == "Crowbar" then
            local crowbar = Internal.getTool("Crowbar")
            if not crowbar then
                if not buyItem("Crowbar") then return false end
                crowbar = Internal.getTool("Crowbar")
            end
            if not crowbar then return false end

            if not equipTool(crowbar) then
                task.wait(0.2)
                crowbar = Internal.getTool("Crowbar")
                if not crowbar or not equipTool(crowbar) then return false end
            end
            local startedAt = tick()
            while Farm.Enabled and target.Parent and not isTargetBroken(target) and tick() - startedAt < 30 do
                targetPart = getTargetPart(target)
                local root = getRoot() local character = getCharacter()
                if not targetPart or not root then return false end
                crowbar = Internal.getTool("Crowbar")
                if not crowbar then return false end
                if character and crowbar.Parent ~= character then equipTool(crowbar) end
                if (targetPart.Position - root.Position).Magnitude > 14 then
                    if not moveToTargetByRoute(target, targetPart) then return false end
                end
                strikeTargetWithCrowbar(target)
                task.wait()
            end
        else
            local startedAt = tick() local nextBatchSize = 7
            while Farm.Enabled and target.Parent and not isTargetBroken(target) and tick() - startedAt < 120 do
                targetPart = getTargetPart(target)
                local root = getRoot()
                if not targetPart or not root then return false end
                if (targetPart.Position - root.Position).Magnitude > 14 then
                    if not moveToTargetByRoute(target, targetPart) then return false end
                end
                if not Internal.getTool("Lockpick") then
                    if not buyLockpickBatch(nextBatchSize) then return false end
                    nextBatchSize = 15
                    if target.Parent and not isTargetBroken(target) then
                        targetPart = getTargetPart(target)
                        if targetPart then moveToTargetByRoute(target, targetPart) end
                    end
                end
                local opened = tryLockpickTarget(target)
                if opened then
                    local completedAt = tick()
                    while target.Parent and not isTargetBroken(target) and tick() - completedAt < 12 do
                        task.wait(0.10)
                    end
                    break
                end
                task.wait(1.25)
            end
        end

        if Settings.BreakingMethod ~= "Crowbar" then unequipTools() end
        return isTargetBroken(target)
    end

    local function getSpawnedBread()
        local filter = workspace:FindFirstChild("Filter")
        return filter and filter:FindFirstChild("SpawnedBread") or nil
    end

    local function normalizeCashObject(object)
        local spawnedBread = getSpawnedBread()
        if not spawnedBread or not object then return nil end
        if object.Parent ~= spawnedBread then object = object.Parent end
        if object and object:IsA("BasePart") and object.Parent == spawnedBread then return object end
        return nil
    end

    local function collectCashObject(object)
        local cashObject = normalizeCashObject(object) local root = getRoot()
        if not cashObject or not root or (cashObject.Position - root.Position).Magnitude >= 22 then return false end
        local ok = safeCall(CashPickupRemote.FireServer, CashPickupRemote, cashObject, nil)
        return ok
    end

    local function clearNearbyCashNoMove()
        if not Settings.AutoMoney then return 0 end
        local root = getRoot() local spawnedBread = getSpawnedBread()
        if not root or not spawnedBread then return 0 end
        local collected = 0
        for _, cashObject in ipairs(spawnedBread:GetChildren()) do
            if cashObject:IsA("BasePart") and cashObject.Transparency < 1 and (cashObject.Position - root.Position).Magnitude <= Settings.PickupDistance then
                if collectCashObject(cashObject) then collected += 1 end
            end
        end
        return collected
    end

    local function collectNearbyCash(duration)
        setStatus("Collecting")
        local startedAt = tick()
        while Farm.Enabled and tick() - startedAt < (duration or 3) do
            clearNearbyCashNoMove()
            task.wait(0.15)
        end
    end

    local function findNearestATMMainPart()
        local root = getRoot() local map = getMap() local atmFolder = map and map:FindFirstChild("ATMz")
        if not root or not atmFolder then return nil end
        local best local bestDistance = math.huge
        for _, atmModel in ipairs(atmFolder:GetChildren()) do
            if atmModel:IsA("Model") and atmModel.Name == "ATM" then
                local mainPart = atmModel:FindFirstChild("MainPart")
                if mainPart and mainPart:IsA("BasePart") then
                    local distance = (mainPart.Position - root.Position).Magnitude
                    if distance < bestDistance then
                        best = mainPart
                        bestDistance = distance
                    end
                end
            end
        end
        return best
    end

    local function claimAllowance()
        if not Settings.AutoAllowance then return false end
        local allowance = readAllowanceText()
        if not string.find(string.upper(allowance), "READY", 1, true) then return false end
        local atmMainPart = findNearestATMMainPart()
        if not atmMainPart then return false end
        setStatus("Claiming Allowance")
        local ok, success = safeCall( ClaimAllowanceRemote.InvokeServer, ClaimAllowanceRemote, atmMainPart, nil)
        task.wait(0.5)
        return ok and success == true
    end

    local function tryDeposit(force)
        if not Settings.AutoDeposit and not force then return false end
        local cash = math.floor(tonumber(readCashAmountValue()) or 0) local threshold = math.max(1, tonumber(Settings.AutoDepositThresholdK) or 5) * 1000
        if not force and cash < threshold then return false end
        if cash < 1 then return false end
        local atmMainPart = findNearestATMMainPart()
        if not atmMainPart then return false end
        Farm.State.InProgress = true
        setStatus("Depositing Cash")

        local root = getRoot() local standPos = atmMainPart.Position + Vector3.new(0, 2.5, 0)
        if root then
            local dir = Vector3.new(root.Position.X - atmMainPart.Position.X, 0, root.Position.Z - atmMainPart.Position.Z)
            if dir.Magnitude < 0.1 then dir = Vector3.new(0, 0, 1) else dir = dir.Unit end
            standPos = atmMainPart.Position + dir * 4 + Vector3.new(0, 2.2, 0)
        end

        local moved = moveToPosition(standPos, "Depositing Cash")
        root = getRoot()
        if root and (root.Position - atmMainPart.Position).Magnitude > 6.5 then

            Internal.Call(function()
                local char = getCharacter and getCharacter() or LocalPlayer.Character
                if char and char.PivotTo then
                    char:PivotTo(CFrame.lookAt(standPos, atmMainPart.Position))
                elseif root then
                    root.CFrame = CFrame.lookAt(standPos, atmMainPart.Position)
                end
            end)
            task.wait(0.15)
        end

        root = getRoot()
        local success = false
        if root and (root.Position - atmMainPart.Position).Magnitude <= 6.5 then
            if ShopProtectionRemote then
                safeCall(ShopProtectionRemote.FireServer, ShopProtectionRemote, true, "ATM", atmMainPart)
                task.wait(0.2)
            end
            local amount = math.floor(tonumber(readCashAmountValue()) or cash) local ok, result = safeCall( ATMRemote.InvokeServer, ATMRemote, "DP", amount, atmMainPart)

            success = ok and result ~= false and result ~= nil
            task.wait(0.5)
            if ShopProtectionRemote then safeCall(ShopProtectionRemote.FireServer, ShopProtectionRemote, false) end
        end
        Farm.State.InProgress = false
        return success
    end

    local function TryDepositAllNow()
        return tryDeposit(true)
    end

    local function handleHackSuccess(model)
        Farm.ProcessedList[model] = true
        Farm.RetargetPending = false
        Farm.State.LastActiveAt = tick()

        local part = getTargetPart(model) local anchor = part and part.Position or (getRoot() and getRoot().Position)
        setStatus("Looting")

        local lootDeadline = tick() + 15 local idleSince = tick()
        while Farm.Enabled and tick() < lootDeadline do
            local got = 0
            if Settings.AutoMoney and anchor then
                local spawnedBread = getSpawnedBread()
                if spawnedBread then
                    for _, cashObject in ipairs(spawnedBread:GetChildren()) do
                        if cashObject:IsA("BasePart") and cashObject.Transparency < 1 and (cashObject.Position - anchor).Magnitude <= 20 then
                            if collectCashObject(cashObject) then got += 1 end
                        end
                    end
                end
            end
            clearNearbyCashNoMove()
            if got > 0 then
                idleSince = tick()
            elseif tick() - idleSince > 2.5 then
                break
            end
            task.wait(0.1)
        end
        clearNearbyCashNoMove()

        setStatus("Looting (wait)")
        local holdUntil = tick() + 5
        while Farm.Enabled and tick() < holdUntil do
            if Settings.AutoMoney and anchor then
                local spawnedBread = getSpawnedBread()
                if spawnedBread then
                    for _, cashObject in ipairs(spawnedBread:GetChildren()) do
                        if cashObject:IsA("BasePart") and cashObject.Transparency < 1 and (cashObject.Position - anchor).Magnitude <= 20 then
                            collectCashObject(cashObject)
                        end
                    end
                end
            end
            clearNearbyCashNoMove()
            task.wait(0.15)
        end

        return true
    end

    local function processTarget(model, part)
        if not model or not part then return false end

        setStatus("Moving To Target")
        local moved = moveToTargetByRoute(model, part)
        if not processTargetMoveOutcome(model, part, moved) then
            Farm.TempIgnoredTargets[model] = tick() + Settings.IgnoreDuration
            return false
        end

        setStatus("Breaking")
        if not breakTarget(model, part) then
            Farm.TempIgnoredTargets[model] = tick() + Settings.IgnoreDuration
            return false
        end

        setStatus("Looting")
        return handleHackSuccess(model)
    end

    local function findCashAddedLabel()
        local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") local core = playerGui and playerGui:FindFirstChild("CoreGUI")
        local stats = core and core:FindFirstChild("StatsFrame") local frame2 = stats and stats:FindFirstChild("Frame2")
        local frame = frame2 and frame2:FindFirstChild("Frame") local container = frame and frame:FindFirstChild("Container")
        local cash = container and container:FindFirstChild("Cash")
        if not cash then return nil end
        local added = cash:FindFirstChild("Added")
        if added and added:IsA("TextLabel") then return added end
        for _, object in ipairs(cash:GetDescendants()) do
            if object:IsA("TextLabel") and string.lower(object.Name) == "added" then return object end
        end
        return nil
    end

    local function processCashAddedText(text)
        text = trim(text)
        if text == "" or text == Farm.LastCashAddedText then return end
        Farm.LastCashAddedText = text
        if text:sub(1, 1) ~= "+" then return end
        local amount = parseCashTextToNumber(text)
        if amount > 0 then
            Farm.EarnMoneyTotal += amount
            Settings.EarnMoneyTotal = Farm.EarnMoneyTotal
        end
    end

    local function bindCashTracking()
        if Farm.CashAddedConnection then
            Farm.CashAddedConnection:Disconnect()
            Farm.CashAddedConnection = nil
        end
        if Farm.CashAddedTextConnection then
            Farm.CashAddedTextConnection:Disconnect()
            Farm.CashAddedTextConnection = nil
        end
        local label = findCashAddedLabel()
        if label then
            Farm.CashAddedTextConnection = label:GetPropertyChangedSignal("Text"):Connect(function()
                processCashAddedText(label.Text)
            end)
            processCashAddedText(label.Text)
            return
        end
        local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if playerGui then
            Farm.CashAddedConnection = playerGui.DescendantAdded:Connect(function(object)
                if object:IsA("TextLabel") and string.lower(object.Name) == "added" then task.defer(bindCashTracking) end
            end)
        end
    end

    local function refreshInfoLabels()
        local elapsed = Farm.StartedAt > 0 and math.floor(tick() - Farm.StartedAt) or 0 local hours = math.floor(elapsed / 3600)
        local minutes = math.floor(elapsed % 3600 / 60) local seconds = elapsed % 60
        local currentCash = readCashAmountValue() local fallbackTotal = Settings.EarnMoneyTotal + math.max(0, currentCash - Farm.StartCash)
        if fallbackTotal > Farm.EarnMoneyTotal then Farm.EarnMoneyTotal = fallbackTotal end
        if Farm.UI.Died then setUiText(Farm.UI.Died, "Died: " .. tostring(Farm.DiedCount)) end
        if Farm.UI.Bank then setUiText(Farm.UI.Bank, "Bank: " .. readBankAmountText()) end
        if Farm.UI.Allowance then setUiText(Farm.UI.Allowance, "Allowance: " .. readAllowanceText()) end
        if Farm.UI.Time then setUiText(Farm.UI.Time, string.format("Time: %02d:%02d:%02d", hours, minutes, seconds)) end
        if Farm.UI.EarnMoney then setUiText(Farm.UI.EarnMoney, "Earn Money: " .. tostring(math.floor(Farm.EarnMoneyTotal))) end
    end

    local function resetInfo()
        Settings.EarnMoneyTotal = 0
        Farm.EarnMoneyTotal = 0
        Farm.StartCash = readCashAmountValue()
        Farm.DiedCount = 0
        Farm.StartedAt = tick()
        Settings.save()
        refreshInfoLabels()
        notify("Notification", "INFO reset complete", 4)
    end

    local function recommendServer()
        local targets = rebuildTargets() local count = #targets local text
        if count <= 2 then
            text = "Few targets (" .. tostring(count) .. "), too many competitors. Switch server."
        else
            text = "Enough targets (" .. tostring(count) .. "), farming is viable."
        end
        notify("Recommendation", text, 7)
    end

    local function detectAdmin(player)
        if player == LocalPlayer then return false end
        if player:GetAttribute("IsAdmin") == true then return true end
        for _, containerName in ipairs({"leaderstats", "Data", "Values", "Admins", "Adminz"}) do
            local container = player:FindFirstChild(containerName)
            if container then
                local value = container:FindFirstChild("Admin") or container:FindFirstChild("IsAdmin")
                if value and value:IsA("BoolValue") and value.Value then return true end
            end
        end
        return false
    end

    local function rejoin(reason)
        if not Settings.AntiRejoin or tick() - Farm.LastRejoinAt < 10 then return end
        Farm.LastRejoinAt = tick()
        notify("JX", tostring(reason or "Rejoining"), 4)
        safeCall(TeleportService.Teleport, TeleportService, game.PlaceId, LocalPlayer)
    end

    local function adminCheck()
        if not Settings.AdminCheck then return false end
        for _, player in ipairs(Players:GetPlayers()) do
            if detectAdmin(player) then
                rejoin("Admin detected")
                return true
            end
        end
        return false
    end

    local function bindAdminDetection()
        table.insert(Farm.AdminConnections, Players.PlayerAdded:Connect(function(player)
            task.wait(1)
            if Settings.AdminCheck and detectAdmin(player) then rejoin("Admin detected: " .. player.Name) end
        end))
        safeCall(function()
            local promptGui = CoreGui:FindFirstChild("RobloxPromptGui") local overlay = promptGui and promptGui:FindFirstChild("promptOverlay")
            if overlay then
                table.insert(Farm.AdminConnections, overlay.DescendantAdded:Connect(function(object)
                    if object:IsA("TextLabel") then
                        local text = string.lower(tostring(object.Text))
                        if text:find("kick", 1, true) or text:find("kicked", 1, true) or text:find("disconnect", 1, true) or text:find("error", 1, true) then
                            rejoin("Prompt: " .. object.Text)
                        end
                    end
                end))
            end
        end)
        safeCall(function()
            table.insert(Farm.AdminConnections, GuiService.ErrorMessageChanged:Connect(function(message)
                local text = string.lower(tostring(message))
                if text:find("kick", 1, true) or text:find("disconnect", 1, true) or text:find("error", 1, true) then rejoin("GuiService: " .. tostring(message)) end
            end))
        end)
    end

