function SafeFarmIsFiniteNumber(Value)
    return type(Value) == "number" and Value == Value and Value > -math.huge and Value < math.huge
end

function SafeFarmIsFiniteVector(Value)
    return typeof(Value) == "Vector3" and SafeFarmIsFiniteNumber(Value.X) and SafeFarmIsFiniteNumber(Value.Y) and SafeFarmIsFiniteNumber(Value.Z)
end

function SafeFarmGetCharacter()
    local Character = LocalPlayer.Character
    if not Character or not Character.Parent then return nil, nil, nil end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    local Root = Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")

    if not Humanoid or Humanoid.Health <= 0 or not Root or not Root:IsA("BasePart") then return Character, Humanoid, nil end
    return Character, Humanoid, Root
end

function SafeFarmSetInvisibility(Enabled)
    Environment.AtramentaFarmInvis = Enabled == true
    Environment.UserWantsInvis = Enabled == true
    Environment.IsInvisEnabled = Enabled == true

    if type(AtramentaFarmModule) == "table" and type(AtramentaFarmModule.SetSetting) == "function" then
        AtramentaFarmModule.SetSetting("HideBody", Enabled == true)
    end

    if Enabled then
        if type(InvisibilityEnable) == "function" then InvisibilityEnable() end
    elseif type(InvisibilityDisable) == "function" then
        InvisibilityDisable()
    end
end

function SafeFarmApplyCharacterState()
    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return false end

    if Humanoid.PlatformStand then Humanoid.PlatformStand = false end
    if Root.Anchored then Root.Anchored = false end

    SafeFarmSetInvisibility(true)
    return true
end

function SafeFarmGetCrowbar()
    local Character = LocalPlayer.Character
    if Character then
        local Equipped = Character:FindFirstChild("Crowbar")
        if Equipped and Equipped:IsA("Tool") then return Equipped end
    end

    local Backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack") local Stored = Backpack and Backpack:FindFirstChild("Crowbar")
    return Stored and Stored:IsA("Tool") and Stored or nil
end

function SafeFarmEquipCrowbar()
    local Character, Humanoid = SafeFarmGetCharacter()
    if not Character or not Humanoid then return nil end

    local Equipped = Character:FindFirstChild("Crowbar")
    if Equipped and Equipped:IsA("Tool") then return Equipped end

    local Crowbar = SafeFarmGetCrowbar()
    if not Crowbar then return nil end

    Humanoid:EquipTool(Crowbar)
    task.wait(0.08)

    Equipped = Character:FindFirstChild("Crowbar")
    return Equipped and Equipped:IsA("Tool") and Equipped or nil
end

function SafeFarmGetSafeFolder()
    local Map = workspace:FindFirstChild("Map")
    if not Map then return nil end

    local Folder = Map:FindFirstChild("BredMakurz")
    if Folder then return Folder end

    for _, Object in ipairs(Map:GetDescendants()) do
        if Object:IsA("Folder") or Object:IsA("Model") then
            local Name = string.lower(Object.Name)
            if string.find(Name, "bred", 1, true) or string.find(Name, "safe", 1, true) or string.find(Name, "register", 1, true) then
                for _, Child in ipairs(Object:GetChildren()) do
                    local Values = Child:FindFirstChild("Values") local MainPart = Child:FindFirstChild("MainPart")
                    if Values and MainPart and MainPart:IsA("BasePart") then return Object end
                end
            end
        end
    end

    return Map
end

function SafeFarmIsBroken(Safe)
    if not Safe or not Safe.Parent then return true end
    local Values = Safe:FindFirstChild("Values") local Broken = Values and Values:FindFirstChild("Broken")
    return Broken and Broken:IsA("BoolValue") and Broken.Value == true
end

function SafeFarmGetSafePart(Safe)
    if not Safe then return nil end

    local Part = Safe:FindFirstChild("MainPart") or Safe:FindFirstChild("SafePart") or Safe.PrimaryPart

    if Part and Part:IsA("BasePart") then return Part end

    for _, Object in ipairs(Safe:GetDescendants()) do
        if Object:IsA("BasePart") then return Object end
    end

    return nil
end

function SafeFarmGetAllSafes(ExcludeSafe)
    local Folder = SafeFarmGetSafeFolder()
    if not Folder then return {} end

    local Safes = {}
    local Seen = {}

    local function AddSafe(Object)
        if not Object or Seen[Object] or Object == ExcludeSafe then return end
        if not Object:IsA("Model") and not Object:IsA("Folder") then return end

        local Part = SafeFarmGetSafePart(Object) if not Part then return end

        local Values = Object:FindFirstChild("Values") local Broken = Values and Values:FindFirstChild("Broken") local Name = string.lower(Object.Name)

        local LooksLikeSafe = Broken ~= nil or string.find(Name, "safe", 1, true) ~= nil or string.find(Name, "register", 1, true) ~= nil

        if not LooksLikeSafe and Folder.Name == "BredMakurz" then LooksLikeSafe = true end

        if LooksLikeSafe then
            Seen[Object] = true
            Safes[#Safes + 1] = Object
        end
    end

    for _, Object in ipairs(Folder:GetChildren()) do AddSafe(Object) end

    if #Safes == 0 then
        for _, Object in ipairs(Folder:GetDescendants()) do AddSafe(Object) end
    end

    return Safes
end

function SafeFarmFindTarget(ExcludeSafe)
    local Folder = SafeFarmGetSafeFolder() local _, _, Root = SafeFarmGetCharacter()
    if not Folder or not Root then return nil end

    local CurrentTime = os.clock() local CachedOrigin = SafeFarmRuntime.TargetCacheOrigin

    if not ExcludeSafe and CurrentTime - SafeFarmRuntime.TargetCacheTime <= SafeFarmRuntime.TargetCacheLifetime and SafeFarmIsFiniteVector(CachedOrigin)
        and (CachedOrigin - Root.Position).Magnitude <= 10 then
        for Index = 1, #SafeFarmRuntime.TargetCache do
            local Safe = SafeFarmRuntime.TargetCache[Index]
            if Safe and Safe ~= ExcludeSafe and Safe.Parent and not SafeFarmIsBroken(Safe) then
                local Part = SafeFarmGetSafePart(Safe) local Cooldown = tonumber(SafeFarmRuntime.TargetCooldowns[Safe]) or 0
                if Part and CurrentTime >= Cooldown then return Safe end
            end
        end
    end

    local Safes = SafeFarmGetAllSafes(ExcludeSafe)
    if #Safes == 0 then return nil end

    local Candidates = {}

    for _, Safe in ipairs(Safes) do
        if Safe ~= ExcludeSafe and not SafeFarmIsBroken(Safe) then
            local Part = SafeFarmGetSafePart(Safe) local Cooldown = tonumber(SafeFarmRuntime.TargetCooldowns[Safe]) or 0

            if Part and CurrentTime >= Cooldown then
                local Delta = Part.Position - Root.Position local VerticalPenalty = math.abs(Delta.Y) * math.max(tonumber(SafeFarmRuntime.UndergroundVerticalPenalty) or 0.04, 0)
                local FailurePenalty = (tonumber(SafeFarmRuntime.TargetFailures[Safe]) or 0) * 18

                Candidates[#Candidates + 1] = { Safe = Safe, Score = Delta.Magnitude + VerticalPenalty + FailurePenalty }
            end
        end
    end

    table.sort(Candidates, function(A, B)
        return A.Score < B.Score
    end)

    if not ExcludeSafe then
        table.clear(SafeFarmRuntime.TargetCache)
        for Index = 1, math.min(#Candidates, 8) do
            SafeFarmRuntime.TargetCache[Index] = Candidates[Index].Safe
        end
        SafeFarmRuntime.TargetCacheTime = CurrentTime
        SafeFarmRuntime.TargetCacheOrigin = Root.Position
    end

    return Candidates[1] and Candidates[1].Safe or nil
end

function SafeFarmGetDealer()
    local Map = workspace:FindFirstChild("Map") local Dealers = Map and Map:FindFirstChild("Shopz") local _, _, Root = SafeFarmGetCharacter()
    if not Dealers or not Root then return nil end

    local BestDealer, BestDistance local FallbackDealer, FallbackDistance

    for _, Dealer in ipairs(Dealers:GetChildren()) do
        local MainPart = Dealer:FindFirstChild("MainPart")
        if MainPart and MainPart:IsA("BasePart") then
            local Distance = (MainPart.Position - Root.Position).Magnitude local Stocks = Dealer:FindFirstChild("CurrentStocks")
            local Stock = Stocks and Stocks:FindFirstChild("Crowbar") local HasKnownStock = Stock and tonumber(Stock.Value) and Stock.Value > 0

            if HasKnownStock and (not BestDistance or Distance < BestDistance) then BestDealer, BestDistance = Dealer, Distance end

            if not FallbackDistance or Distance < FallbackDistance then FallbackDealer, FallbackDistance = Dealer, Distance end
        end
    end

    return BestDealer or FallbackDealer
end

function SafeFarmGetBodyProfile(Character, Humanoid, Root)
    local RootHalf = Root and Root:IsA("BasePart") and Root.Size.Y * 0.5 or 1 local HipHeight = Humanoid and tonumber(Humanoid.HipHeight) or 0
    local FootClearance = math.max(2.6, RootHalf + HipHeight + 0.30) local HeadClearance = math.max(2.35, RootHalf + 1.35)
    local Radius = Root and Root:IsA("BasePart") and math.max(math.min(Root.Size.X, Root.Size.Z) * 0.42, 0.62) or 0.72

    return FootClearance, HeadClearance, Radius
end

function SafeFarmGetProbeAxes(Root)
    local Right = Root and Root.CFrame.RightVector or Vector3.xAxis local Forward = Root and Root.CFrame.LookVector or Vector3.zAxis

    Right = Vector3.new(Right.X, 0, Right.Z)
    Forward = Vector3.new(Forward.X, 0, Forward.Z)

    Right = Right.Magnitude > 0.05 and Right.Unit or Vector3.xAxis
    Forward = Forward.Magnitude > 0.05 and Forward.Unit or Vector3.zAxis
    return Right, Forward
end

function SafeFarmProbeSurface(Position, Character, Humanoid, Root, ProbeDistance)
    if not SafeFarmIsFiniteVector(Position) then return nil end

    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.FilterDescendantsInstances = Character and {Character} or {}
    Parameters.IgnoreWater = false

    local _, _, BodyRadius = SafeFarmGetBodyProfile(Character, Humanoid, Root)
    local ProbeRadius = math.max( math.min(tonumber(SafeFarmRuntime.FloorProbeRadius) or 0.72, BodyRadius), 0.45) local Right, Forward = SafeFarmGetProbeAxes(Root)
    local UpDistance = math.max(tonumber(SafeFarmRuntime.FloorProbeUp) or 3.8, 2.5)
    local DownDistance = math.max( tonumber(ProbeDistance) or tonumber(SafeFarmRuntime.FloorProbeDown) or 9.5, 4)

    local Offsets = { Vector3.zero, Right * ProbeRadius, -Right * ProbeRadius, Forward * ProbeRadius, -Forward * ProbeRadius }

    local Hits = table.create(#Offsets) local CenterHit = nil

    for Index = 1, #Offsets do
        local Offset = Offsets[Index]
        local Result = workspace:Raycast( Position + Offset + Vector3.yAxis * UpDistance, Vector3.yAxis * -(UpDistance + DownDistance), Parameters)

        if Result and Result.Instance and Result.Instance:IsA("BasePart") and Result.Instance.CanCollide and Result.Normal.Y >= 0.42 then
            Hits[Index] = Result
            if Index == 1 then CenterHit = Result end
        end
    end

    if not CenterHit then return nil end

    local FloorY = CenterHit.Position.Y local MaximumStep = math.max(tonumber(SafeFarmRuntime.FloorMaximumStep) or 1.35, 0.5)

    for Index = 2, #Hits do
        local Result = Hits[Index]
        if Result and Result.Position.Y > FloorY and Result.Position.Y - CenterHit.Position.Y <= MaximumStep then FloorY = Result.Position.Y end
    end

    return { Position = Vector3.new(Position.X, FloorY, Position.Z), Center = CenterHit, Hits = Hits }
end

function SafeFarmProbeCeiling(Position, Character, Humanoid, Root)
    if not SafeFarmIsFiniteVector(Position) then return false end

    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.FilterDescendantsInstances = Character and {Character} or {}
    Parameters.IgnoreWater = true

    local _, HeadClearance, BodyRadius = SafeFarmGetBodyProfile(Character, Humanoid, Root)
    local ProbeRadius = math.max( math.min(tonumber(SafeFarmRuntime.FloorProbeRadius) or 0.72, BodyRadius), 0.45) local Right, Forward = SafeFarmGetProbeAxes(Root)
    local Margin = math.max(tonumber(SafeFarmRuntime.ClearanceMargin) or 0.18, 0.05) local Distance = HeadClearance + Margin

    local Offsets = { Vector3.zero, Right * ProbeRadius, -Right * ProbeRadius, Forward * ProbeRadius, -Forward * ProbeRadius }

    for Index = 1, #Offsets do
        local Result = workspace:Raycast( Position + Offsets[Index], Vector3.yAxis * Distance, Parameters)

        if Result and Result.Instance and Result.Instance:IsA("BasePart") and Result.Instance.CanCollide
            and (Result.Position - (Position + Offsets[Index])).Magnitude < Distance - 0.03 then
            return true, Result
        end
    end

    return false
end

function SafeFarmResolveClearPosition(Position, Character, Humanoid, Root, ProbeDistance, MaximumSnap)
    if not SafeFarmIsFiniteVector(Position) then return nil, "InvalidPosition" end

    local Surface = SafeFarmProbeSurface( Position, Character, Humanoid, Root, ProbeDistance)
    if not Surface then return nil, "NoFloor" end

    local FootClearance = SafeFarmGetBodyProfile(Character, Humanoid, Root) local Resolved = Vector3.new( Position.X, Surface.Position.Y + FootClearance, Position.Z)

    if MaximumSnap and math.abs(Resolved.Y - Position.Y) > math.max(tonumber(MaximumSnap) or 0, 0.5) then return nil, "WrongFloor" end

    local CeilingBlocked = SafeFarmProbeCeiling( Resolved, Character, Humanoid, Root)
    if CeilingBlocked then return nil, "LowCeiling" end

    return Resolved, nil, Surface
end

function SafeFarmGroundPosition(Position, Character, Humanoid, Root)
    if not SafeFarmIsFiniteVector(Position) then return Position end

    local Resolved = SafeFarmResolveClearPosition( Position, Character, Humanoid, Root, 9.5,
        math.max(tonumber(SafeFarmRuntime.GroundSnapMaximumDrop) or 7, 3))

    return Resolved or Position
end

function SafeFarmResolveRoutePosition(Position, Character, Humanoid, Root)
    if not SafeFarmIsFiniteVector(Position) then return Position end

    local Range = math.max(tonumber(SafeFarmRuntime.VerticalWaypointRange) or 9, 5)
    local Resolved = SafeFarmResolveClearPosition( Position, Character, Humanoid, Root, Range, Range * 0.72)

    return Resolved or Position
end

function SafeFarmGetGroundBelow(Position, Character, Distance)
    if not SafeFarmIsFiniteVector(Position) then return nil end

    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.FilterDescendantsInstances = Character and {Character} or {}
    Parameters.IgnoreWater = false

    return workspace:Raycast( Position + Vector3.new(0, 1.5, 0), Vector3.new(0, -(math.max(tonumber(Distance) or 9, 3) + 1.5), 0), Parameters)
end

function SafeFarmRecordGroundedPosition(Character, Humanoid, Root)
    if not Character or not Humanoid or not Root then return end

    local Ground = SafeFarmGetGroundBelow( Root.Position, Character, math.max(tonumber(SafeFarmRuntime.GroundProbeDistance) or 9, 4))

    if Ground and Humanoid.FloorMaterial ~= Enum.Material.Air then
        SafeFarmRuntime.LastGroundedCFrame = Root.CFrame
        SafeFarmRuntime.LastGroundedAt = os.clock()
    end
end

function SafeFarmValidateDestination(StartPosition, Destination, Character, RouteWaypoint, ClimbPortal)
    if not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(Destination) then return false, "InvalidDestination" end

    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") local Root = Character and Character:FindFirstChild("HumanoidRootPart")

    if not Root then return false, "CharacterInvalid" end
    if ClimbPortal and ClimbPortal.Parent then return true end

    local MaximumDrop = math.max(tonumber(SafeFarmRuntime.MaximumUnsafeDrop) or 4.5, 2) local Drop = StartPosition.Y - Destination.Y

    local Surface = SafeFarmProbeSurface( Destination, Character, Humanoid, Root, math.max(tonumber(SafeFarmRuntime.GroundProbeDistance) or 9, 4))

    if not Surface then return false, "NoFloor" end

    local FootClearance = SafeFarmGetBodyProfile(Character, Humanoid, Root) local ExpectedRootY = Surface.Position.Y + FootClearance
    local SupportError = math.abs(Destination.Y - ExpectedRootY)

    if Drop > MaximumDrop and SupportError > math.max(tonumber(SafeFarmRuntime.GroundSnapMaximumDrop) or 7, 3) then return false, "UnsafeDrop" end

    local CeilingBlocked = SafeFarmProbeCeiling( Vector3.new(Destination.X, ExpectedRootY, Destination.Z), Character, Humanoid, Root)

    if CeilingBlocked then return false, "LowCeiling" end
    return true
end

function SafeFarmGetBodyRayOffsets(Character, Root, Delta)
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    local FootClearance, HeadClearance, BodyRadius = SafeFarmGetBodyProfile(Character, Humanoid, Root)

    local Flat = Vector3.new(Delta.X, 0, Delta.Z) local Right = Flat.Magnitude > 0.05 and Flat.Unit:Cross(Vector3.yAxis) or (Root and Root.CFrame.RightVector or Vector3.xAxis)

    Right = Vector3.new(Right.X, 0, Right.Z)
    Right = Right.Magnitude > 0.05 and Right.Unit or Vector3.xAxis

    local Side = math.max(math.min(BodyRadius * 0.92, 0.95), 0.55) local FeetY = -FootClearance + 0.48 local TorsoY = 0 local HeadY = HeadClearance - 0.32

    return { Vector3.new(0, FeetY, 0), Vector3.new(0, TorsoY, 0), Vector3.new(0, HeadY, 0), Vector3.new(0, FeetY, 0) + Right * Side,
        Vector3.new(0, FeetY, 0) - Right * Side, Right * Side, -Right * Side, Vector3.new(0, HeadY, 0) + Right * Side,
        Vector3.new(0, HeadY, 0) - Right * Side }
end

function SafeFarmTrustedRouteBlocked(StartPosition, EndPosition, Character, Root, TargetSafe)
    if not Root or not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(EndPosition) then return true end

    local Delta = EndPosition - StartPosition
    if Delta.Magnitude <= 0.35 then return false end

    local Parameters = SafeFarmMakeRouteRayParams(Character, TargetSafe) local Offsets = SafeFarmGetBodyRayOffsets(Character, Root, Delta)

    for Index = 1, #Offsets do
        local Offset = Offsets[Index] local Result = workspace:Raycast(StartPosition + Offset, Delta, Parameters)

        if Result and Result.Instance and Result.Instance:IsA("BasePart") and Result.Instance.CanCollide then
            local Remaining = (Result.Position - (EndPosition + Offset)).Magnitude local FloorLike = Result.Normal.Y >= 0.55

            if Remaining > 0.82 and not FloorLike then return true, Result end
        end
    end

    return false
end

function SafeFarmMakeRouteRayParams(Character, TargetSafe)
    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.IgnoreWater = true

    local Filter = {}
    if Character then Filter[#Filter + 1] = Character end
    if TargetSafe then Filter[#Filter + 1] = TargetSafe end
    Parameters.FilterDescendantsInstances = Filter
    return Parameters
end

function SafeFarmPointClear(Position, Character, Root, TargetSafe)
    if not SafeFarmIsFiniteVector(Position) or not Root then return false end

    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    local Resolved = SafeFarmResolveClearPosition( Position, Character, Humanoid, Root, math.max(tonumber(SafeFarmRuntime.GroundProbeDistance) or 9, 4),
        math.max(tonumber(SafeFarmRuntime.GroundSnapMaximumDrop) or 7, 3))

    if not Resolved then return false end

    local FootClearance, HeadClearance, BodyRadius = SafeFarmGetBodyProfile(Character, Humanoid, Root)

    local Parameters = OverlapParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude

    local Filter = {}
    if Character then Filter[#Filter + 1] = Character end
    if TargetSafe then Filter[#Filter + 1] = TargetSafe end
    Parameters.FilterDescendantsInstances = Filter
    Parameters.MaxParts = 20

    local Margin = math.max(tonumber(SafeFarmRuntime.ClearanceMargin) or 0.18, 0.05) local Height = FootClearance + HeadClearance - Margin * 2
    local CenterY = Resolved.Y + (HeadClearance - FootClearance) * 0.5 local Size = Vector3.new( BodyRadius * 1.72, math.max(Height, 4.35), BodyRadius * 1.72)

    local Parts = workspace:GetPartBoundsInBox( CFrame.new(Resolved.X, CenterY, Resolved.Z), Size, Parameters)

    for Index = 1, #Parts do
        local Part = Parts[Index]
        if Part:IsA("BasePart") and Part.CanCollide and Part.Transparency < 0.98 then return false end
    end

    return true
end

function SafeFarmSegmentBlocked(StartPosition, EndPosition, Character, Root, TargetSafe)
    if not Root or not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(EndPosition) then return true end

    local Delta = EndPosition - StartPosition
    if Delta.Magnitude <= 0.35 then return false end

    local Parameters = SafeFarmMakeRouteRayParams(Character, TargetSafe) local Offsets = SafeFarmGetBodyRayOffsets(Character, Root, Delta)

    for Index = 1, #Offsets do
        local Offset = Offsets[Index] local Result = workspace:Raycast(StartPosition + Offset, Delta, Parameters)

        if Result and Result.Instance and Result.Instance:IsA("BasePart") and Result.Instance.CanCollide then
            local Remaining = (Result.Position - (EndPosition + Offset)).Magnitude local FloorLike = Result.Normal.Y >= 0.58

            if Remaining > 0.82 and not FloorLike then return true, Result end
        end
    end

    local Midpoint = StartPosition:Lerp(EndPosition, 0.5) local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
    local MidResolved = SafeFarmResolveClearPosition( Midpoint, Character, Humanoid, Root, math.max(tonumber(SafeFarmRuntime.GroundProbeDistance) or 9, 4),
        math.max(tonumber(SafeFarmRuntime.GroundSnapMaximumDrop) or 7, 3))

    if not MidResolved then return true end

    return false
end

function SafeFarmCompressRoute(Waypoints, Character, Root, TargetSafe)
    if type(Waypoints) ~= "table" or #Waypoints < 2 then return Waypoints end

    local Result = {Waypoints[1]}
    local Index = 1 local VerticalThreshold = tonumber(SafeFarmRuntime.VerticalRouteThreshold) or 0.65
    local VerticalLimit = math.max(math.floor(tonumber(SafeFarmRuntime.VerticalCompressionLimit) or 2), 1)

    while Index < #Waypoints do
        local Best = Index + 1

        for Candidate = math.min(#Waypoints, Index + 7), Index + 1, -1 do
            local StartPosition = Result[#Result].Position local EndPosition = Waypoints[Candidate].Position
            local HasJump = false local HasVerticalRun = math.abs(EndPosition.Y - StartPosition.Y) > VerticalThreshold local PreviousY = Waypoints[Index].Position.Y

            for Scan = Index + 1, Candidate do
                local CurrentWaypoint = Waypoints[Scan]
                if CurrentWaypoint.Action == Enum.PathWaypointAction.Jump then HasJump = true end
                if math.abs(CurrentWaypoint.Position.Y - PreviousY) > VerticalThreshold then HasVerticalRun = true end
                PreviousY = CurrentWaypoint.Position.Y
            end

            if HasJump and Candidate > Index + 2 then continue end
            if HasVerticalRun and Candidate > Index + VerticalLimit then continue end

            local Blocked
            if HasVerticalRun then
                Blocked = SafeFarmTrustedRouteBlocked(StartPosition, EndPosition, Character, Root, TargetSafe)
            else
                Blocked = SafeFarmSegmentBlocked(StartPosition, EndPosition, Character, Root, TargetSafe)
            end

            if not Blocked then
                Best = Candidate
                break
            end
        end

        Result[#Result + 1] = Waypoints[Best]
        Index = Best
    end

    return Result
end

function SafeFarmRouteLength(Waypoints)
    if type(Waypoints) ~= "table" or #Waypoints < 2 then return math.huge end

    local Length = 0
    for Index = 2, #Waypoints do Length += (Waypoints[Index].Position - Waypoints[Index - 1].Position).Magnitude end
    return Length
end

function SafeFarmAtlasCopyWaypoints(Waypoints)
    local Result = table.create(type(Waypoints) == "table" and #Waypoints or 0)
    if type(Waypoints) ~= "table" then return Result end

    for Index = 1, #Waypoints do
        local Waypoint = Waypoints[Index]

        if Waypoint then
            local IsCustomWaypoint = type(Waypoint) == "table" local Position = Waypoint.Position local Action = Waypoint.Action

            if SafeFarmIsFiniteVector(Position) then
                Result[#Result + 1] = { Position = Position, Action = Action or Enum.PathWaypointAction.Walk,
                    Climb = IsCustomWaypoint and Waypoint.Climb == true or false, Portal = IsCustomWaypoint and Waypoint.Portal or nil }
            end
        end
    end

    return Result
end

function SafeFarmComputeRawPath(StartPosition, GoalPosition, TargetSafe)
    if not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(GoalPosition) then return nil end

    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return nil end

    if not SafeFarmSegmentBlocked(StartPosition, GoalPosition, Character, Root, TargetSafe) then
        return { {Position = StartPosition, Action = Enum.PathWaypointAction.Walk}, {Position = GoalPosition, Action = Enum.PathWaypointAction.Walk} }
    end

    local Path = SafeFarmPathfindingService:CreatePath({ AgentRadius = 1.45, AgentHeight = 4.65, AgentCanJump = true, AgentCanClimb = true,
        WaypointSpacing = 2.5, Costs = {Water = 4.5} })

    Path:ComputeAsync(StartPosition, GoalPosition)
    if Path.Status ~= Enum.PathStatus.Success then return nil end

    local Waypoints = SafeFarmAtlasCopyWaypoints(Path:GetWaypoints())
    if #Waypoints < 2 then return nil end

    Waypoints = SafeFarmCompressRoute(Waypoints, Character, Root, TargetSafe)
    return SafeFarmAtlasCopyWaypoints(Waypoints)
end

function SafeFarmAtlasFindApproach(Safe)
    local Character, Humanoid, Root = SafeFarmGetCharacter() local Part = SafeFarmGetSafePart(Safe)

    if not Character or not Humanoid or not Root or not Part then return nil end

    local Center = Part.Position local Forward = Vector3.new(Part.CFrame.LookVector.X, 0, Part.CFrame.LookVector.Z)
    local Right = Vector3.new(Part.CFrame.RightVector.X, 0, Part.CFrame.RightVector.Z)

    Forward = Forward.Magnitude > 0.05 and Forward.Unit or Vector3.zAxis
    Right = Right.Magnitude > 0.05 and Right.Unit or Vector3.xAxis

    local Directions = { -Forward, Forward, Right, -Right, (Forward + Right).Unit, (Forward - Right).Unit, (-Forward + Right).Unit, (-Forward - Right).Unit
    }

    local Distances = {2.15, 2.45, 2.80, 3.05}

    for DistanceIndex = 1, #Distances do
        local Distance = Distances[DistanceIndex]

        for DirectionIndex = 1, #Directions do
            local Candidate = SafeFarmGroundPosition( Center + Directions[DirectionIndex] * Distance, Character, Humanoid, Root)

            if SafeFarmIsFiniteVector(Candidate) and SafeFarmPointClear(Candidate, Character, Root, Safe) then
                local Horizontal = Vector3.new(Candidate.X - Center.X, 0, Candidate.Z - Center.Z).Magnitude

                if Horizontal >= SafeFarmRuntime.SafeDistanceMin and Horizontal <= SafeFarmRuntime.SafeDistanceMax then
                    local InteractionStart = Candidate + Vector3.new(0, 1.4, 0) local InteractionEnd = Center + Vector3.new( 0, math.clamp(Part.Size.Y * 0.15, -0.4, 0.7), 0)

                    if not SafeFarmSegmentBlocked(InteractionStart, InteractionEnd, Character, Root, Safe) then return Candidate end
                end
            end
        end
    end

    return nil
end

function SafeFarmAtlasAddEdge(FromIndex, ToIndex, Waypoints)
    local Atlas = SafeFarmRuntime.RouteAtlas
    if not Atlas or type(Waypoints) ~= "table" or #Waypoints < 2 then return false end

    Atlas.Edges[FromIndex] = Atlas.Edges[FromIndex] or {}

    local Length = SafeFarmRouteLength(Waypoints)
    if Length == math.huge then return false end

    Atlas.Edges[FromIndex][ToIndex] = { Length = Length, Waypoints = SafeFarmAtlasCopyWaypoints(Waypoints) }

    return true
end

function SafeFarmAtlasBuildShortestPaths()
    local Atlas = SafeFarmRuntime.RouteAtlas local Count = #Atlas.Nodes

    Atlas.Distances = table.create(Count)
    Atlas.Next = table.create(Count)

    for From = 1, Count do
        local Dist = table.create(Count) local NextRow = table.create(Count)

        for To = 1, Count do
            Dist[To] = From == To and 0 or math.huge
            NextRow[To] = nil
        end

        local Edges = Atlas.Edges[From]
        if Edges then
            for To, Edge in pairs(Edges) do
                Dist[To] = Edge.Length
                NextRow[To] = To
            end
        end

        Atlas.Distances[From] = Dist
        Atlas.Next[From] = NextRow
    end

    for Middle = 1, Count do
        for From = 1, Count do
            local FromMiddle = Atlas.Distances[From][Middle]
            if FromMiddle ~= math.huge then
                for To = 1, Count do
                    local MiddleTo = Atlas.Distances[Middle][To]
                    if MiddleTo ~= math.huge then
                        local Candidate = FromMiddle + MiddleTo

                        if Candidate < Atlas.Distances[From][To] then
                            Atlas.Distances[From][To] = Candidate
                            Atlas.Next[From][To] = Atlas.Next[From][Middle]
                        end
                    end
                end
            end
        end
    end
end

function SafeFarmAtlasGetComponents()
    local Atlas = SafeFarmRuntime.RouteAtlas local Count = #Atlas.Nodes
    local Visited = {}
    local Components = {}

    for StartIndex = 1, Count do
        if not Visited[StartIndex] then
            local Component = {}
            local Queue = {StartIndex}
            Visited[StartIndex] = true
            local QueueIndex = 1

            while QueueIndex <= #Queue do
                local Current = Queue[QueueIndex]
                QueueIndex += 1
                Component[#Component + 1] = Current

                for Other = 1, Count do
                    if not Visited[Other] then
                        local Forward = Atlas.Edges[Current] and Atlas.Edges[Current][Other] local Reverse = Atlas.Edges[Other] and Atlas.Edges[Other][Current]

                        if Forward or Reverse then
                            Visited[Other] = true
                            Queue[#Queue + 1] = Other
                        end
                    end
                end
            end

            Components[#Components + 1] = Component
        end
    end

    return Components
end

function SafeFarmAtlasBridgeComponents(Generation)
    local Atlas = SafeFarmRuntime.RouteAtlas

    for _ = 1, 12 do
        if Generation ~= Atlas.Generation or not Atlas.Building then return end

        local Components = SafeFarmAtlasGetComponents()
        if #Components <= 1 then return end

        local Base = Components[1] local BestA, BestB, BestDistance = nil, nil, math.huge

        for ComponentIndex = 2, #Components do
            local Other = Components[ComponentIndex]

            for AIndex = 1, #Base do
                local A = Base[AIndex] local APosition = Atlas.Nodes[A].Position

                for BIndex = 1, #Other do
                    local B = Other[BIndex] local BPosition = Atlas.Nodes[B].Position local Distance = (APosition - BPosition).Magnitude

                    if Distance < BestDistance then BestA, BestB, BestDistance = A, B, Distance end
                end
            end
        end

        if not BestA or not BestB then return end

        local NodeA = Atlas.Nodes[BestA] local NodeB = Atlas.Nodes[BestB]
        local Forward = SafeFarmComputeRawPath(NodeA.Position, NodeB.Position, NodeB.Safe) local Reverse = SafeFarmComputeRawPath(NodeB.Position, NodeA.Position, NodeA.Safe)

        if Forward then SafeFarmAtlasAddEdge(BestA, BestB, Forward) end
        if Reverse then SafeFarmAtlasAddEdge(BestB, BestA, Reverse) end

        Atlas.BuildOperations += 2
        if not Forward and not Reverse then
            Atlas.BuildFailures += 1
            return
        end

        task.wait()
    end
end

function SafeFarmBuildRouteAtlas()
    local Atlas = SafeFarmRuntime.RouteAtlas
    if not Atlas or Atlas.Building then return false end

    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return false end

    Atlas.Building = true
    Atlas.Ready = false
    Atlas.Generation += 1
    Atlas.Status = "Discovering"
    Atlas.BuildOperations = 0
    Atlas.BuildFailures = 0

    local Generation = Atlas.Generation local Safes = SafeFarmGetAllSafes()

    Atlas.Nodes = {}
    Atlas.NodeBySafe = setmetatable({}, {__mode = "k"})
    Atlas.Edges = {}
    Atlas.Distances = {}
    Atlas.Next = {}
    Atlas.SafeCount = #Safes

    for Index = 1, #Safes do
        if Generation ~= Atlas.Generation or not Atlas.Building then return false end

        local Safe = Safes[Index] local Part = SafeFarmGetSafePart(Safe) local Approach = Part and SafeFarmAtlasFindApproach(Safe) or nil

        if Part and Approach then
            local NodeIndex = #Atlas.Nodes + 1
            local Node = { Index = NodeIndex, Safe = Safe, Part = Part, Position = Approach, Name = tostring(Safe.Name) }

            Atlas.Nodes[NodeIndex] = Node
            Atlas.NodeBySafe[Safe] = Node
            Atlas.Edges[NodeIndex] = {}
        end

        if Index % 8 == 0 then task.wait() end
    end

    local NodeCount = #Atlas.Nodes
    if NodeCount < 2 then
        Atlas.Status = "Insufficient Nodes"
        Atlas.Building = false
        return false
    end

    Atlas.Status = "Connecting"

    for FromIndex = 1, NodeCount do
        if Generation ~= Atlas.Generation or not Atlas.Building then return false end

        local FromNode = Atlas.Nodes[FromIndex]
        local Neighbors = {}

        for ToIndex = 1, NodeCount do
            if ToIndex ~= FromIndex then
                local Distance = (FromNode.Position - Atlas.Nodes[ToIndex].Position).Magnitude

                if Distance <= Atlas.MaximumNeighborDistance then Neighbors[#Neighbors + 1] = { Index = ToIndex, Distance = Distance } end
            end
        end

        table.sort(Neighbors, function(A, B) return A.Distance < B.Distance end)

        local Limit = math.min(#Neighbors, Atlas.NeighborCount)

        for NeighborIndex = 1, Limit do
            local ToIndex = Neighbors[NeighborIndex].Index

            if not Atlas.Edges[FromIndex][ToIndex] then
                local ToNode = Atlas.Nodes[ToIndex] local Route = SafeFarmComputeRawPath( FromNode.Position, ToNode.Position, ToNode.Safe)

                Atlas.BuildOperations += 1

                if Route then
                    SafeFarmAtlasAddEdge(FromIndex, ToIndex, Route)
                else
                    Atlas.BuildFailures += 1
                end

                if Atlas.BuildOperations % Atlas.BuildYieldEvery == 0 then task.wait() end
            end
        end
    end

    Atlas.Status = "Bridging"
    SafeFarmAtlasBridgeComponents(Generation)

    if Generation ~= Atlas.Generation or not Atlas.Building then return false end

    Atlas.Status = "Indexing"
    SafeFarmAtlasBuildShortestPaths()

    local Components = SafeFarmAtlasGetComponents()
    Atlas.Ready = #Components == 1
    Atlas.Building = false
    Atlas.LastBuild = os.clock()
    Atlas.Status = Atlas.Ready and "Ready" or "Partial"

    return Atlas.Ready
end

function SafeFarmEnsureRouteAtlas()
    local Atlas = SafeFarmRuntime.RouteAtlas
    if not Atlas or Atlas.Building then return end

    local Safes = SafeFarmGetAllSafes()
    if Atlas.Ready and Atlas.SafeCount == #Safes and #Atlas.Nodes > 1 then return end

    task.spawn(function()
        SafeFarmBuildRouteAtlas()
    end)
end

function SafeFarmAtlasGetStartNode(Position)
    local Atlas = SafeFarmRuntime.RouteAtlas
    if not Atlas or not Atlas.Ready or not SafeFarmIsFiniteVector(Position) then return nil end

    local LastSafe = SafeFarmRuntime.LastSafe local LastNode = LastSafe and Atlas.NodeBySafe[LastSafe]

    if LastNode and (LastNode.Position - Position).Magnitude <= 8.5 then return LastNode end

    local Character, _, Root = SafeFarmGetCharacter()
    if not Character or not Root then return nil end

    local Candidates = {}

    for Index = 1, #Atlas.Nodes do
        local Node = Atlas.Nodes[Index]
        Candidates[#Candidates + 1] = { Node = Node, Distance = (Node.Position - Position).Magnitude }
    end

    table.sort(Candidates, function(A, B) return A.Distance < B.Distance end)

    for Index = 1, math.min(#Candidates, 8) do
        local Entry = Candidates[Index]

        if not SafeFarmSegmentBlocked( Position, Entry.Node.Position, Character, Root, Entry.Node.Safe ) then return Entry.Node end
    end

    return nil
end

function SafeFarmAtlasBuildRoute(StartPosition, GoalPosition, TargetSafe)
    local Atlas = SafeFarmRuntime.RouteAtlas
    if not Atlas or not Atlas.Ready or not TargetSafe then return nil end

    local TargetNode = Atlas.NodeBySafe[TargetSafe] local StartNode = SafeFarmAtlasGetStartNode(StartPosition)

    if not TargetNode or not StartNode then return nil end

    local Character, _, Root = SafeFarmGetCharacter()
    if not Character or not Root then return nil end

    if StartNode.Index == TargetNode.Index then
        if not SafeFarmSegmentBlocked(StartPosition, GoalPosition, Character, Root, TargetSafe) then
            return { {Position = StartPosition, Action = Enum.PathWaypointAction.Walk}, {Position = GoalPosition, Action = Enum.PathWaypointAction.Walk} }
        end
        return nil
    end

    local FirstHop = Atlas.Next[StartNode.Index] and Atlas.Next[StartNode.Index][TargetNode.Index]

    if not FirstHop then return nil end

    local Route = { {Position = StartPosition, Action = Enum.PathWaypointAction.Walk} }

    if (StartPosition - StartNode.Position).Magnitude > 1.0 then
        if SafeFarmSegmentBlocked(StartPosition, StartNode.Position, Character, Root, StartNode.Safe) then return nil end

        Route[#Route + 1] = { Position = StartNode.Position, Action = Enum.PathWaypointAction.Walk }
    end

    local CurrentIndex = StartNode.Index local Guard = 0

    while CurrentIndex ~= TargetNode.Index and Guard < #Atlas.Nodes + 2 do
        Guard += 1

        local NextIndex = Atlas.Next[CurrentIndex] and Atlas.Next[CurrentIndex][TargetNode.Index]

        if not NextIndex then return nil end

        local Edge = Atlas.Edges[CurrentIndex] and Atlas.Edges[CurrentIndex][NextIndex]

        if not Edge or type(Edge.Waypoints) ~= "table" then return nil end

        for WaypointIndex = 2, #Edge.Waypoints do
            Route[#Route + 1] = { Position = Edge.Waypoints[WaypointIndex].Position,
                Action = Edge.Waypoints[WaypointIndex].Action or Enum.PathWaypointAction.Walk }
        end

        CurrentIndex = NextIndex
    end

    if CurrentIndex ~= TargetNode.Index then return nil end

    local LastPosition = Route[#Route].Position

    if (LastPosition - GoalPosition).Magnitude > 0.8 then
        if SafeFarmSegmentBlocked(LastPosition, GoalPosition, Character, Root, TargetSafe) then return nil end

        Route[#Route + 1] = { Position = GoalPosition, Action = Enum.PathWaypointAction.Walk }
    end

    Route = SafeFarmCompressRoute(Route, Character, Root, TargetSafe)
    return Route
end

function SafeFarmIsVerticalPortalPart(Object)
    if not Object or not Object:IsA("BasePart") then return false end
    if Object:IsA("TrussPart") then return true end

    local Name = string.lower(tostring(Object.Name or ""))
    if string.find(Name, "ladder", 1, true) or string.find(Name, "truss", 1, true) or string.find(Name, "climb", 1, true)
        or string.find(Name, "stairwell", 1, true) or string.find(Name, "manhole", 1, true) or string.find(Name, "hatch", 1, true)
        or string.find(Name, "sewer", 1, true) then
        return true
    end

    local Parent = Object.Parent
    if Parent then
        local ParentName = string.lower(tostring(Parent.Name or ""))
        if string.find(ParentName, "ladder", 1, true) or string.find(ParentName, "truss", 1, true) or string.find(ParentName, "stairwell", 1, true)
            or string.find(ParentName, "manhole", 1, true) or string.find(ParentName, "hatch", 1, true) or string.find(ParentName, "sewer", 1, true) then
            return true
        end
    end

    return false
end

function SafeFarmRefreshVerticalPortals(Force)
    local CurrentTime = os.clock()

    if Force ~= true and CurrentTime - (tonumber(SafeFarmRuntime.VerticalPortalScanAt) or 0)
            < math.max(tonumber(SafeFarmRuntime.VerticalPortalScanCooldown) or 5, 1) then
        return SafeFarmRuntime.VerticalPortals
    end

    SafeFarmRuntime.VerticalPortalScanAt = CurrentTime
    local Portals = {}
    local Map = workspace:FindFirstChild("Map")

    if Map then
        for _, Object in ipairs(Map:GetDescendants()) do
            if SafeFarmIsVerticalPortalPart(Object) then Portals[#Portals + 1] = Object end
        end
    end

    SafeFarmRuntime.VerticalPortals = Portals
    return Portals
end

function SafeFarmFindVerticalPortal(StartPosition, EndPosition)
    if not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(EndPosition) then return nil end

    local Portals = SafeFarmRefreshVerticalPortals(false) local MinimumY = math.min(StartPosition.Y, EndPosition.Y)
    local MaximumY = math.max(StartPosition.Y, EndPosition.Y) local Midpoint = (StartPosition + EndPosition) * 0.5 local Best, BestScore = nil, math.huge

    for Index = 1, #Portals do
        local Portal = Portals[Index]

        if Portal and Portal.Parent and Portal:IsA("BasePart") then
            local HalfY = math.max(Portal.Size.Y * 0.5, 1) local PortalMinimumY = Portal.Position.Y - HalfY - 3.5
            local PortalMaximumY = Portal.Position.Y + HalfY + 3.5 local CoversVerticalRange = PortalMaximumY >= MinimumY and PortalMinimumY <= MaximumY

            if CoversVerticalRange then
                local ToStart = Vector3.new( Portal.Position.X - StartPosition.X, 0, Portal.Position.Z - StartPosition.Z ).Magnitude

                local ToEnd = Vector3.new( Portal.Position.X - EndPosition.X, 0, Portal.Position.Z - EndPosition.Z ).Magnitude

                local ToMid = Vector3.new( Portal.Position.X - Midpoint.X, 0, Portal.Position.Z - Midpoint.Z ).Magnitude

                local Score = ToStart + ToEnd * 0.72 + ToMid * 0.35

                if Score < BestScore and math.min(ToStart, ToEnd, ToMid) <= 38 then
                    Best = Portal
                    BestScore = Score
                end
            end
        end
    end

    return Best
end

function SafeFarmGetPortalSide(Portal, ReferencePosition)
    local Flat = Vector3.new( ReferencePosition.X - Portal.Position.X, 0, ReferencePosition.Z - Portal.Position.Z)

    if Flat.Magnitude > 0.15 then return Flat.Unit end

    local Look = Vector3.new(Portal.CFrame.LookVector.X, 0, Portal.CFrame.LookVector.Z)
    if Look.Magnitude > 0.05 then return -Look.Unit end
    return Vector3.zAxis
end

function SafeFarmGetPortalEndpoints(Portal, StartPosition, EndPosition)
    if not Portal or not Portal:IsA("BasePart") then return nil, nil end

    local Side = SafeFarmGetPortalSide(Portal, StartPosition) local Offset = math.max(tonumber(SafeFarmRuntime.ClimbAlignDistance) or 1.35, 0.85)
    local HalfY = math.max(Portal.Size.Y * 0.5, 2.4) local RootClearance = 2.7

    local Bottom = Vector3.new( Portal.Position.X + Side.X * Offset, Portal.Position.Y - HalfY + RootClearance, Portal.Position.Z + Side.Z * Offset)

    local Top = Vector3.new( Portal.Position.X + Side.X * Offset, Portal.Position.Y + HalfY - 0.65, Portal.Position.Z + Side.Z * Offset)

    if StartPosition.Y <= EndPosition.Y then return Bottom, Top end

    return Top, Bottom
end

function SafeFarmShouldClimbSegment(StartPosition, EndPosition, Waypoint)
    if not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(EndPosition) then return false end
    if type(Waypoint) == "table" and Waypoint.Climb == true then return true end

    local Delta = EndPosition - StartPosition local Vertical = math.abs(Delta.Y)

    if Vertical < math.max(tonumber(SafeFarmRuntime.ClimbVerticalThreshold) or 2.25, 1.25) then return false end

    return SafeFarmFindVerticalPortal(StartPosition, EndPosition) ~= nil
end

function SafeFarmClimbSegment(Destination, FacePosition, TargetSafe, PortalHint)
    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root or not SafeFarmIsFiniteVector(Destination) then return false, "CharacterInvalid" end

    if TargetSafe and not SafeFarmTargetStillValid(TargetSafe) then return false, "TargetInvalid" end

    local StartPosition = Root.Position
    local Portal = PortalHint and PortalHint.Parent and PortalHint:IsA("BasePart") and PortalHint or SafeFarmFindVerticalPortal(StartPosition, Destination)

    if not Portal then return false, "NoClimbPortal" end

    local ClimbStart, ClimbEnd = SafeFarmGetPortalEndpoints(Portal, StartPosition, Destination)
    if not ClimbStart or not ClimbEnd then return false, "InvalidPortal" end

    local DestinationSafe, DestinationReason = SafeFarmValidateDestination( StartPosition, ClimbEnd, Character, true, Portal)
    if not DestinationSafe then return false, DestinationReason end

    if (Root.Position - ClimbStart).Magnitude > 1.45 then
        local Aligned, AlignReason = SafeFarmTweenSegment( ClimbStart, Portal.Position, false, TargetSafe, true)

        if not Aligned then return false, AlignReason or "ClimbAlignFailed" end
    end

    Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return false, "CharacterInvalid" end

    SafeFarmRecordGroundedPosition(Character, Humanoid, Root)

    local Distance = (ClimbEnd - Root.Position).Magnitude local Timeout = math.max( Distance / math.max(tonumber(SafeFarmRuntime.ClimbSpeed) or 20, 8) + 1.2, 1.2)

    local Started = os.clock() local BestDistance = Distance local LastProgress = Started

    Humanoid:ChangeState(Enum.HumanoidStateType.Climbing)
    Humanoid:MoveTo(ClimbEnd)

    while SafeFarmEnabled and SafeFarmRuntime.Running and os.clock() - Started <= Timeout do
        Character, Humanoid, Root = SafeFarmGetCharacter()
        if not Character or not Humanoid or not Root then return false, "CharacterInvalid" end
        if TargetSafe and not SafeFarmTargetStillValid(TargetSafe) then return false, "TargetInvalid" end

        local Remaining = (Root.Position - ClimbEnd).Magnitude
        if Remaining <= 1.9 then break end

        if Remaining < BestDistance - 0.12 then
            BestDistance = Remaining
            LastProgress = os.clock()
        elseif os.clock() - LastProgress > 0.65 then
            return false, "ClimbStuck"
        end

        Humanoid:ChangeState(Enum.HumanoidStateType.Climbing)
        Humanoid:MoveTo(ClimbEnd)
        SafeFarmRunService.Heartbeat:Wait()
    end

    Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Root then return false, "CharacterInvalid" end
    if (Root.Position - ClimbEnd).Magnitude > 2.1 then return false, "ClimbMiss" end

    SafeFarmRecordGroundedPosition(Character, Humanoid, Root)

    if (ClimbEnd - Destination).Magnitude > 1.25 then return SafeFarmTweenSegment( Destination, FacePosition, false, TargetSafe, true) end

    return true, "Climbed"
end

function SafeFarmBuildVerticalPortalRoute(StartPosition, GoalPosition, TargetSafe)
    if SafeFarmRuntime.UndergroundEnabled ~= true then return nil end

    local Delta = GoalPosition - StartPosition
    if math.abs(Delta.Y) < 7 then return nil end

    local Portal = SafeFarmFindVerticalPortal(StartPosition, GoalPosition)
    if not Portal then return nil end

    local Entry, Exit = SafeFarmGetPortalEndpoints(Portal, StartPosition, GoalPosition)
    if not Entry or not Exit then return nil end

    local ToEntry = SafeFarmComputeRawPath(StartPosition, Entry, TargetSafe) local FromExit = SafeFarmComputeRawPath(Exit, GoalPosition, TargetSafe)

    if not ToEntry or not FromExit then return nil end

    local Route = SafeFarmAtlasCopyWaypoints(ToEntry)

    Route[#Route + 1] = { Position = Exit, Action = Enum.PathWaypointAction.Walk, Climb = true, Portal = Portal }

    for Index = 2, #FromExit do
        local Waypoint = FromExit[Index] local IsCustomWaypoint = type(Waypoint) == "table"

        Route[#Route + 1] = { Position = Waypoint.Position, Action = Waypoint.Action or Enum.PathWaypointAction.Walk,
            Climb = IsCustomWaypoint and Waypoint.Climb == true or false, Portal = IsCustomWaypoint and Waypoint.Portal or nil }
    end

    return Route
end

function SafeFarmBuildPath(StartPosition, GoalPosition, TargetSafe)
    if not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(GoalPosition) then return nil end

    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return nil end

    if not SafeFarmSegmentBlocked(StartPosition, GoalPosition, Character, Root, TargetSafe) then
        local Delta = GoalPosition - StartPosition local Distance = Delta.Magnitude
        local Step = math.max(tonumber(SafeFarmRuntime.RouteSurfaceSample) or 2.25, 1.25) local Count = math.clamp(math.ceil(Distance / Step), 1, 24)
        local Route = { {Position = StartPosition, Action = Enum.PathWaypointAction.Walk} }

        for Index = 1, Count do
            local Alpha = Index / Count local Raw = StartPosition:Lerp(GoalPosition, Alpha)
            local Resolved = SafeFarmResolveClearPosition( Raw, Character, Humanoid, Root, math.max(tonumber(SafeFarmRuntime.GroundProbeDistance) or 9, 4),
                math.max(tonumber(SafeFarmRuntime.GroundSnapMaximumDrop) or 7, 3))

            if not Resolved then
                Route = nil
                break
            end

            Route[#Route + 1] = { Position = Resolved, Action = Enum.PathWaypointAction.Walk }
        end

        if Route and #Route >= 2 then return Route end
    end

    if TargetSafe and SafeFarmRuntime.RouteAtlas and SafeFarmRuntime.RouteAtlas.Ready then
        local AtlasRoute = SafeFarmAtlasBuildRoute(StartPosition, GoalPosition, TargetSafe)
        if AtlasRoute and #AtlasRoute >= 2 then return AtlasRoute end
    end

    local Grid = 3
    local Key = table.concat({ math.floor(StartPosition.X / Grid + 0.5), math.floor(StartPosition.Y / Grid + 0.5), math.floor(StartPosition.Z / Grid + 0.5),
        math.floor(GoalPosition.X / Grid + 0.5), math.floor(GoalPosition.Y / Grid + 0.5), math.floor(GoalPosition.Z / Grid + 0.5) }, ":")

    local CurrentTime = os.clock()
    SafeFarmPrunePathCache(CurrentTime, false)
    local Cached = SafeFarmRuntime.PathCache[Key]
    if type(Cached) == "table" and CurrentTime - (tonumber(Cached.Time) or 0) <= SafeFarmRuntime.PathCacheLifetime and type(Cached.Waypoints) == "table"
    then
        local CachedRoute = SafeFarmAtlasCopyWaypoints(Cached.Waypoints)
        if #CachedRoute >= 2 then return CachedRoute end
        SafeFarmRuntime.PathCache[Key] = nil
    end

    local Path = SafeFarmPathfindingService:CreatePath({ AgentRadius = 1.45, AgentHeight = 4.65, AgentCanJump = true, AgentCanClimb = true,
        WaypointSpacing = 2.5, Costs = {Water = 4.5} })

    Path:ComputeAsync(StartPosition, GoalPosition)

    if Path.Status ~= Enum.PathStatus.Success then
        local VerticalRoute = SafeFarmBuildVerticalPortalRoute( StartPosition, GoalPosition, TargetSafe)

        if VerticalRoute and #VerticalRoute >= 2 then
            VerticalRoute = SafeFarmAtlasCopyWaypoints(VerticalRoute)
            SafeFarmRuntime.PathCache[Key] = { Time = CurrentTime, Waypoints = VerticalRoute }
            return VerticalRoute
        end

        return nil
    end

    local Waypoints = SafeFarmAtlasCopyWaypoints(Path:GetWaypoints())
    if #Waypoints < 2 then return nil end

    Waypoints = SafeFarmCompressRoute(Waypoints, Character, Root, TargetSafe)
    Waypoints = SafeFarmAtlasCopyWaypoints(Waypoints)

    SafeFarmRuntime.PathCache[Key] = { Time = CurrentTime, Waypoints = Waypoints }

    return Waypoints
end

function SafeFarmPrunePathCache(CurrentTime, Force)
    CurrentTime = tonumber(CurrentTime) or os.clock()
    if Force ~= true and CurrentTime < (tonumber(SafeFarmRuntime.PathCachePruneAt) or 0) then return end

    SafeFarmRuntime.PathCachePruneAt = CurrentTime + 1
    local Lifetime = math.max(tonumber(SafeFarmRuntime.PathCacheLifetime) or 0.45, 0.05) local Maximum = math.max(math.floor(tonumber(SafeFarmRuntime.PathCacheMaximum) or 96), 16)
    local Entries = {}

    for Key, Entry in pairs(SafeFarmRuntime.PathCache) do
        local Time = type(Entry) == "table" and tonumber(Entry.Time) or nil
        if not Time or CurrentTime - Time > Lifetime * 4 then
            SafeFarmRuntime.PathCache[Key] = nil
        else
            Entries[#Entries + 1] = {Key = Key, Time = Time}
        end
    end

    if #Entries <= Maximum then return end
    table.sort(Entries, function(A, B) return A.Time < B.Time end)
    for Index = 1, #Entries - Maximum do SafeFarmRuntime.PathCache[Entries[Index].Key] = nil end
end

SafeFarmTargetStillValid = nil

SafeFarmTargetStillValid = function(Safe)
    if not Safe or SafeFarmIsBroken(Safe) then return false end
    local Part = SafeFarmGetSafePart(Safe)
    return Part ~= nil and Part.Parent ~= nil
end

SafeFarmFindApproach = nil

SafeFarmFindApproach = function(TargetPart, TargetSafe)
    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root or not TargetPart or not TargetPart:IsA("BasePart") then return nil end

    local CurrentTime = os.clock() local Cached = SafeFarmRuntime.ApproachCache[TargetPart]
    if type(Cached) == "table" and CurrentTime - (tonumber(Cached.Time) or 0) <= 2.25
        and SafeFarmIsFiniteVector(Cached.Position) and SafeFarmIsFiniteVector(Cached.TargetPosition)
        and (Cached.TargetPosition - TargetPart.Position).Magnitude <= 0.8 then
        return Cached.Position
    end

    local Center = TargetPart.Position local Forward = Vector3.new(TargetPart.CFrame.LookVector.X, 0, TargetPart.CFrame.LookVector.Z)
    Forward = Forward.Magnitude > 0.05 and Forward.Unit or Vector3.zAxis

    local Right = Vector3.new(TargetPart.CFrame.RightVector.X, 0, TargetPart.CFrame.RightVector.Z)
    Right = Right.Magnitude > 0.05 and Right.Unit or Vector3.xAxis

    local FromPlayer = Vector3.new(Root.Position.X - Center.X, 0, Root.Position.Z - Center.Z)
    FromPlayer = FromPlayer.Magnitude > 0.05 and FromPlayer.Unit or -Forward

    local Directions = { FromPlayer, -Forward, Forward, Right, -Right, (Forward + Right).Unit, (Forward - Right).Unit,
        (-Forward + Right).Unit, (-Forward - Right).Unit }
    local Distances = {2.05, 2.35, 2.7, 3.0}
    local Candidates = {}

    local function AddCandidate(Direction, Distance)
        local Candidate = SafeFarmGroundPosition(Center + Direction * Distance, Character, Humanoid, Root)
        if not SafeFarmIsFiniteVector(Candidate) or not SafeFarmPointClear(Candidate, Character, Root, TargetSafe) then return nil end

        local Horizontal = Vector3.new(Candidate.X - Center.X, 0, Candidate.Z - Center.Z).Magnitude
        if Horizontal < SafeFarmRuntime.SafeDistanceMin or Horizontal > SafeFarmRuntime.SafeDistanceMax then return nil end

        local InteractionStart = Candidate + Vector3.new(0, 1.4, 0) local InteractionEnd = Center + Vector3.new(0, math.clamp(TargetPart.Size.Y * 0.15, -0.4, 0.7), 0)
        if SafeFarmSegmentBlocked(InteractionStart, InteractionEnd, Character, Root, TargetSafe) then return nil end

        local DirectBlocked = SafeFarmSegmentBlocked(Root.Position, Candidate, Character, Root, TargetSafe)
        local Score = (Candidate - Root.Position).Magnitude + math.abs(Candidate.Y - Root.Position.Y) * 0.16 + math.abs(Horizontal - 2.2) * 1.4
            - math.max(Direction:Dot(FromPlayer), 0) * 0.9

        local Entry = {Position = Candidate, Score = Score, Direct = not DirectBlocked}
        Candidates[#Candidates + 1] = Entry
        return Entry
    end

    for _, Distance in ipairs(Distances) do
        for _, Direction in ipairs(Directions) do
            local Entry = AddCandidate(Direction, Distance)
            if Entry and Entry.Direct then
                local Route = { {Position = Root.Position, Action = Enum.PathWaypointAction.Walk},
                    {Position = Entry.Position, Action = Enum.PathWaypointAction.Walk} }
                SafeFarmRuntime.ApproachCache[TargetPart] = { Time = CurrentTime, Position = Entry.Position, TargetPosition = TargetPart.Position,
                    Route = Route, RouteOrigin = Root.Position }
                return Entry.Position
            end
        end
    end

    table.sort(Candidates, function(A, B) return A.Score < B.Score end)

    local MaximumChecks = math.min(#Candidates, 4)
    for Index = 1, MaximumChecks do
        local Entry = Candidates[Index] local Route = SafeFarmBuildPath(Root.Position, Entry.Position, TargetSafe)
        if Route then
            SafeFarmRuntime.ApproachCache[TargetPart] = { Time = CurrentTime, Position = Entry.Position, TargetPosition = TargetPart.Position,
                Route = Route, RouteOrigin = Root.Position }
            return Entry.Position
        end
    end

    local Fallback = SafeFarmGroundPosition(Center + FromPlayer * 2.35, Character, Humanoid, Root)
    if SafeFarmPointClear(Fallback, Character, Root, TargetSafe) then
        local Route = SafeFarmBuildPath(Root.Position, Fallback, TargetSafe)
        if Route then
            SafeFarmRuntime.ApproachCache[TargetPart] = { Time = CurrentTime, Position = Fallback, TargetPosition = TargetPart.Position,
                Route = Route, RouteOrigin = Root.Position }
            return Fallback
        end
    end

    return nil
end

function SafeFarmPrepareNextTarget(CurrentSafe)
    local NextSafe = SafeFarmFindTarget(CurrentSafe)
    SafeFarmRuntime.NextTarget, SafeFarmRuntime.NextApproach, SafeFarmRuntime.NextPath = NextSafe, nil, nil
    SafeFarmRuntime.NextPreparedAt = os.clock()
    if not NextSafe then return nil end

    local Part = SafeFarmGetSafePart(NextSafe)
    if not Part then
        SafeFarmRuntime.NextTarget = nil
        return nil
    end

    local Approach = SafeFarmFindApproach(Part, NextSafe)
    SafeFarmRuntime.NextApproach = Approach

    local Cached = SafeFarmRuntime.ApproachCache[Part]
    SafeFarmRuntime.NextPath = type(Cached) == "table" and Cached.Route or nil
    return NextSafe
end

function SafeFarmBuildObstacleDetour(StartPosition, Destination, Character, Humanoid, Root, TargetSafe)
    if not Root or not SafeFarmIsFiniteVector(StartPosition) or not SafeFarmIsFiniteVector(Destination) then return nil end

    local Blocked, Result = SafeFarmSegmentBlocked(StartPosition, Destination, Character, Root, TargetSafe)
    if not Blocked or not Result or not Result.Instance or not Result.Instance:IsA("BasePart") then return nil end

    local Travel = Destination - StartPosition local Flat = Vector3.new(Travel.X, 0, Travel.Z)
    if Flat.Magnitude <= 0.05 then return nil end

    local Forward = Flat.Unit local Side = Forward:Cross(Vector3.yAxis)
    Side = Side.Magnitude > 0.05 and Side.Unit or Root.CFrame.RightVector

    local HitPosition = Result.Position local BestRoute, BestScore = nil, math.huge local Distances = SafeFarmRuntime.ObstacleDetourDistances

    for DirectionSign = -1, 1, 2 do
        for DistanceIndex = 1, #Distances do
            local SideDistance = Distances[DistanceIndex] local Lateral = Side * SideDistance * DirectionSign

            local EntryRaw = HitPosition - Forward * 1.25 + Lateral local ExitRaw = HitPosition + Forward * math.min(4.5 + SideDistance * 0.18, 6.5) + Lateral

            local Entry = SafeFarmResolveRoutePosition(EntryRaw, Character, Humanoid, Root) local Exit = SafeFarmResolveRoutePosition(ExitRaw, Character, Humanoid, Root)

            if SafeFarmPointClear(Entry, Character, Root, TargetSafe) and SafeFarmPointClear(Exit, Character, Root, TargetSafe) then
                local BlockEntry = SafeFarmSegmentBlocked(StartPosition, Entry, Character, Root, TargetSafe)
                local BlockMiddle = SafeFarmSegmentBlocked(Entry, Exit, Character, Root, TargetSafe)
                local BlockExit = SafeFarmSegmentBlocked(Exit, Destination, Character, Root, TargetSafe)

                if not BlockEntry and not BlockMiddle and not BlockExit then
                    local Score = (Entry - StartPosition).Magnitude + (Exit - Entry).Magnitude + (Destination - Exit).Magnitude + SideDistance * 0.12

                    if Score < BestScore then
                        BestScore = Score
                        BestRoute = { {Position = Entry, Action = Enum.PathWaypointAction.Walk}, {Position = Exit, Action = Enum.PathWaypointAction.Walk} }
                    end
                end
            end
        end
    end

    return BestRoute
end

function SafeFarmTweenSegment(Destination, FacePosition, AllowJump, TargetSafe, RouteWaypoint)
    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root or not SafeFarmIsFiniteVector(Destination) then return false, "CharacterInvalid" end
    if TargetSafe and not SafeFarmTargetStillValid(TargetSafe) then return false, "TargetInvalid" end

    local ResolvedDestination, ResolveReason

    if RouteWaypoint then
        local Range = math.max(tonumber(SafeFarmRuntime.VerticalWaypointRange) or 9, 5)
        ResolvedDestination, ResolveReason = SafeFarmResolveClearPosition( Destination, Character, Humanoid, Root, Range, Range * 0.72)
    else
        ResolvedDestination, ResolveReason = SafeFarmResolveClearPosition( Destination, Character, Humanoid, Root, 9.5,
            math.max(tonumber(SafeFarmRuntime.GroundSnapMaximumDrop) or 7, 3))
    end

    if not ResolvedDestination then return false, ResolveReason or "NoClearance" end
    Destination = ResolvedDestination

    local DestinationSafe, DestinationReason = SafeFarmValidateDestination( Root.Position, Destination, Character, RouteWaypoint == true, nil)
    if not DestinationSafe then return false, DestinationReason end

    SafeFarmRecordGroundedPosition(Character, Humanoid, Root)

    local Delta = Destination - Root.Position local Distance = Delta.Magnitude
    local VerticalDelta = Destination.Y - Root.Position.Y local Ascending = VerticalDelta > (tonumber(SafeFarmRuntime.VerticalRouteThreshold) or 0.65)

    if Distance <= SafeFarmRuntime.ArrivalDistance then return true end

    local Blocked
    if RouteWaypoint and Distance <= math.max(tonumber(SafeFarmRuntime.TrustedRouteMaximumSegment) or 10, 4) then
        Blocked = SafeFarmTrustedRouteBlocked(Root.Position, Destination, Character, Root, TargetSafe)
    else
        Blocked = SafeFarmSegmentBlocked(Root.Position, Destination, Character, Root, TargetSafe)
    end

    if Blocked then return false, "Blocked" end

    if (AllowJump or Ascending) and Humanoid.FloorMaterial ~= Enum.Material.Air then
        Humanoid.Jump = true
        if Ascending and VerticalDelta > 1.15 then Humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end
    end

    local Facing = SafeFarmIsFiniteVector(FacePosition) and FacePosition or Destination local FlatFacing = Vector3.new(Facing.X, Destination.Y, Facing.Z)
    local GoalCFrame = (FlatFacing - Destination).Magnitude > 0.05 and CFrame.lookAt(Destination, FlatFacing)
        or CFrame.new(Destination) * (Root.CFrame - Root.CFrame.Position)

    Root.AssemblyLinearVelocity, Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero

    local Speed = math.max(tonumber(SafeFarmRuntime.Speed) or 32, 8) local Duration = math.max(Distance / Speed, 0.035)
    local Tween = TweenService:Create( Root, TweenInfo.new(Duration, Enum.EasingStyle.Linear, Enum.EasingDirection.Out), {CFrame = GoalCFrame})

    local Finished = false
    local Connection = Tween.Completed:Connect(function() Finished = true end)
    Tween:Play()

    local StartedAt = os.clock() local LastObstacleCheck = 0 local BestRemaining = Distance local LastProgressAt = StartedAt
    local JumpRetried = false

    while SafeFarmEnabled and SafeFarmRuntime.Running and not Finished do
        Character, Humanoid, Root = SafeFarmGetCharacter()
        if not Character or not Humanoid or not Root then
            Tween:Cancel()
            Connection:Disconnect()
            return false, "CharacterInvalid"
        end

        if TargetSafe and not SafeFarmTargetStillValid(TargetSafe) then
            Tween:Cancel()
            Connection:Disconnect()
            return false, "TargetInvalid"
        end

        Root.AssemblyLinearVelocity, Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
        SafeFarmRecordGroundedPosition(Character, Humanoid, Root)

        local Now = os.clock() local Remaining = (Root.Position - Destination).Magnitude

        if Now - LastObstacleCheck >= 0.06 then
            local CurrentResolved = SafeFarmResolveClearPosition( Root.Position, Character, Humanoid, Root,
                math.max(tonumber(SafeFarmRuntime.GroundProbeDistance) or 9, 4), 3.2)

            if not CurrentResolved or Root.Position.Y < CurrentResolved.Y - 0.58 then
                Tween:Cancel()
                Connection:Disconnect()
                return false, "FloorClearance"
            end
        end

        if Remaining < BestRemaining - (tonumber(SafeFarmRuntime.StuckProgress) or 0.16) then
            BestRemaining = Remaining
            LastProgressAt = Now
        end

        if Ascending and not JumpRetried and Now - LastProgressAt >= 0.20 and Humanoid.FloorMaterial ~= Enum.Material.Air then
            JumpRetried = true
            Humanoid.Jump = true
            Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        end

        if Now - LastProgressAt >= math.max(tonumber(SafeFarmRuntime.StuckTimeout) or 0.48, 0.30) then
            Tween:Cancel()
            Connection:Disconnect()
            return false, Ascending and "VerticalStuck" or "Stuck"
        end

        if Now - LastObstacleCheck >= 0.10 then
            LastObstacleCheck = Now

            local IsBlocked
            if RouteWaypoint and Remaining <= math.max(tonumber(SafeFarmRuntime.TrustedRouteMaximumSegment) or 10, 4) then
                IsBlocked = SafeFarmTrustedRouteBlocked(Root.Position, Destination, Character, Root, TargetSafe)
            else
                IsBlocked = SafeFarmSegmentBlocked(Root.Position, Destination, Character, Root, TargetSafe)
            end

            if IsBlocked then
                Tween:Cancel()
                Connection:Disconnect()
                return false, "Blocked"
            end
        end

        if Now - StartedAt > Duration + 0.45 then
            Tween:Cancel()
            break
        end

        SafeFarmRunService.Heartbeat:Wait()
    end

    Connection:Disconnect()
    Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Root then return false, "CharacterInvalid" end

    Root.AssemblyLinearVelocity, Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
    SafeFarmRecordGroundedPosition(Character, Humanoid, Root)
    return (Root.Position - Destination).Magnitude <= math.max(SafeFarmRuntime.ArrivalDistance, 1.5)
end

function SafeFarmMoveTo(GoalPosition, FacePosition, TargetSafe, PreparedRoute)
    if not SafeFarmIsFiniteVector(GoalPosition) then return false end

    SafeFarmRuntime.MovementTarget = GoalPosition
    local MaximumAttempts = math.max(math.floor(tonumber(SafeFarmRuntime.RepathAttempts) or 5), 1)

    for Attempt = 1, MaximumAttempts do
        local Character, Humanoid, Root = SafeFarmGetCharacter()
        if not Character or not Humanoid or not Root then return false, "CharacterInvalid" end
        if TargetSafe and not SafeFarmTargetStillValid(TargetSafe) then return false, "TargetInvalid" end

        if (Root.Position - GoalPosition).Magnitude <= math.max(SafeFarmRuntime.ArrivalDistance, 1.8) then return true end

        local Route
        if Attempt == 1 and type(PreparedRoute) == "table" and #PreparedRoute >= 2 then
            Route, PreparedRoute = PreparedRoute, nil
        else
            Route = SafeFarmBuildPath(Root.Position, GoalPosition, TargetSafe)
        end

        if not Route or #Route < 2 then
            SafeFarmRuntime.PathCache = {}
            task.wait(0.012)
            continue
        end

        Route = SafeFarmAtlasCopyWaypoints(Route)
        if #Route < 2 then
            SafeFarmRuntime.PathCache = {}
            task.wait(0.012)
            continue
        end

        Character, Humanoid, Root = SafeFarmGetCharacter()
        if not Root then return false, "CharacterInvalid" end

        local StartIndex = 2

        while StartIndex < #Route and (Route[StartIndex].Position - Root.Position).Magnitude <= 1.65 do
            StartIndex += 1
        end

        local Repath = false
        for Index = StartIndex, #Route do
            if not SafeFarmEnabled or not SafeFarmRuntime.Running then return false, "Stopped" end
            if TargetSafe and not SafeFarmTargetStillValid(TargetSafe) then return false, "TargetInvalid" end

            Character, Humanoid, Root = SafeFarmGetCharacter()
            if not Root then return false, "CharacterInvalid" end

            local Waypoint = Route[Index] local WaypointPortal = type(Waypoint) == "table" and Waypoint.Portal or nil
            local RemainingToGoal = (Root.Position - GoalPosition).Magnitude
            if RemainingToGoal <= math.max(SafeFarmRuntime.ArrivalDistance, 1.8) then return true end
            if (Root.Position - Waypoint.Position).Magnitude <= 1.35 then continue end

            local SegmentFace = Index == #Route and FacePosition or Waypoint.Position local PreviousPosition = Index > 1 and Route[Index - 1].Position or Root.Position
            local RouteVerticalDelta = Waypoint.Position.Y - PreviousPosition.Y
            local NeedsVerticalAssist = Waypoint.Action == Enum.PathWaypointAction.Jump or RouteVerticalDelta > (tonumber(SafeFarmRuntime.VerticalRouteThreshold) or 0.65)

            local ClimbSegment = SafeFarmShouldClimbSegment( Root.Position, Waypoint.Position, Waypoint)

            local Moved, Reason

            if ClimbSegment then
                Moved, Reason = SafeFarmClimbSegment( Waypoint.Position, SegmentFace, TargetSafe, WaypointPortal)
            else
                Moved, Reason = SafeFarmTweenSegment( Waypoint.Position, SegmentFace, NeedsVerticalAssist, TargetSafe, true)
            end

            if not Moved then
                Character, Humanoid, Root = SafeFarmGetCharacter()
                if Root and (Root.Position - GoalPosition).Magnitude <= 2.15 then return true end
                if Reason == "TargetInvalid" or Reason == "CharacterInvalid" then return false, Reason end

                if Root and (Reason == "Blocked" or Reason == "Stuck" or Reason == "VerticalStuck") then
                    local Detour = SafeFarmBuildObstacleDetour( Root.Position, Waypoint.Position, Character, Humanoid, Root, TargetSafe)

                    if type(Detour) == "table" and #Detour >= 1 then
                        local DetourWorked = true

                        for DetourIndex = 1, #Detour do
                            local DetourPoint = Detour[DetourIndex]
                            local DetourMoved = SafeFarmTweenSegment( DetourPoint.Position, DetourPoint.Position, false, TargetSafe, true)

                            if not DetourMoved then
                                DetourWorked = false
                                break
                            end
                        end

                        if DetourWorked then
                            if ClimbSegment then
                                Moved, Reason = SafeFarmClimbSegment( Waypoint.Position, SegmentFace, TargetSafe, WaypointPortal)
                            else
                                Moved, Reason = SafeFarmTweenSegment( Waypoint.Position, SegmentFace, NeedsVerticalAssist, TargetSafe, true)
                            end
                        end
                    end
                end

                if not Moved then
                    if Reason == "VerticalStuck" and Root then
                        Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
                        if Humanoid and Humanoid.FloorMaterial ~= Enum.Material.Air then
                            Humanoid.Jump = true
                            Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                        end
                        task.wait(0.05)
                    end

                    Repath = true
                    SafeFarmRuntime.PathCache = {}
                    break
                end
            end
        end

        Character, Humanoid, Root = SafeFarmGetCharacter()
        if Root and (Root.Position - GoalPosition).Magnitude <= 2.15 then
            if SafeFarmIsFiniteVector(FacePosition) then
                local FlatTarget = Vector3.new(FacePosition.X, Root.Position.Y, FacePosition.Z)
                if (FlatTarget - Root.Position).Magnitude > 0.05 then Root.CFrame = CFrame.lookAt(Root.Position, FlatTarget) end
            end

            Root.AssemblyLinearVelocity, Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
            return true
        end

        if not Repath then return false, "ArrivalMiss" end
        task.wait(0.01)
    end

    return false, "PathFailed"
end

function SafeFarmMoveNearPart(Part, TargetSafe)
    if not Part or not Part:IsA("BasePart") then return false end

    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return false, "CharacterInvalid" end

    local function Measure()
        local Horizontal = Vector3.new(Root.Position.X - Part.Position.X, 0, Root.Position.Z - Part.Position.Z).Magnitude
        local Vertical = math.abs(Root.Position.Y - Part.Position.Y)
        return Horizontal, Vertical
    end

    if SafeFarmRuntime.ArrivalLatchPart == Part and os.clock() < (tonumber(SafeFarmRuntime.ArrivalLatchUntil) or 0) then
        local Horizontal, Vertical = Measure()
        if Horizontal >= 0.85 and Horizontal <= 4.6 and Vertical <= 7.5 then
            local FlatTarget = Vector3.new(Part.Position.X, Root.Position.Y, Part.Position.Z)
            if (FlatTarget - Root.Position).Magnitude > 0.05 then Root.CFrame = CFrame.lookAt(Root.Position, FlatTarget) end
            return true
        end
    end

    local Approach = SafeFarmFindApproach(Part, TargetSafe)
    if not Approach then return false, "NoApproach" end

    local PreparedRoute local Cached = SafeFarmRuntime.ApproachCache[Part]
    if type(Cached) == "table" and type(Cached.Route) == "table" and SafeFarmIsFiniteVector(Cached.RouteOrigin)
        and (Cached.RouteOrigin - Root.Position).Magnitude <= 3.5
        and SafeFarmIsFiniteVector(Cached.Position) and (Cached.Position - Approach).Magnitude <= 0.25 then
        PreparedRoute = Cached.Route
    end

    local Moved, Reason = SafeFarmMoveTo(Approach, Part.Position, TargetSafe, PreparedRoute)
    if not Moved then return false, Reason end

    Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return false, "CharacterInvalid" end

    local Horizontal, Vertical = Measure()
    if Vertical > 7.5 then return false, "VerticalMiss" end

    if Horizontal < 0.85 or Horizontal > 4.6 then
        local Away = Vector3.new(Root.Position.X - Part.Position.X, 0, Root.Position.Z - Part.Position.Z)
        if Away.Magnitude <= 0.05 then Away = Vector3.new(-Part.CFrame.LookVector.X, 0, -Part.CFrame.LookVector.Z) end
        Away = Away.Magnitude > 0.05 and Away.Unit or Vector3.zAxis

        local Correction = SafeFarmGroundPosition(Part.Position + Away * 2.15, Character, Humanoid, Root)
        if SafeFarmPointClear(Correction, Character, Root, TargetSafe)
            and not SafeFarmSegmentBlocked(Root.Position, Correction, Character, Root, TargetSafe) then
            SafeFarmTweenSegment(Correction, Part.Position, false, TargetSafe, false)
            Character, Humanoid, Root = SafeFarmGetCharacter()
            if not Root then return false, "CharacterInvalid" end
            Horizontal, Vertical = Measure()
        end
    end

    if Horizontal >= 0.75 and Horizontal <= 4.8 and Vertical <= 7.5 then
        SafeFarmRuntime.ArrivalLatchPart = Part
        SafeFarmRuntime.ArrivalLatchUntil = os.clock() + 1.35

        local FlatTarget = Vector3.new(Part.Position.X, Root.Position.Y, Part.Position.Z)
        if (FlatTarget - Root.Position).Magnitude > 0.05 then Root.CFrame = CFrame.lookAt(Root.Position, FlatTarget) end
        Root.AssemblyLinearVelocity, Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
        return true
    end

    return false, "ArrivalMiss"
end

function SafeFarmBuyCrowbar()
    if SafeFarmGetCrowbar() then return true end

    local Dealer = SafeFarmGetDealer() local DealerPart = Dealer and Dealer:FindFirstChild("MainPart")
    if not DealerPart or not DealerPart:IsA("BasePart") then return false end
    if not SafeFarmMoveNearPart(DealerPart) then return false end

    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if not Character or not Humanoid or not Root then return false end

    local FlatTarget = Vector3.new(DealerPart.Position.X, Root.Position.Y, DealerPart.Position.Z)
    if (FlatTarget - Root.Position).Magnitude > 0.05 then Root.CFrame = CFrame.lookAt(Root.Position, FlatTarget) end

    if SafeFarmProtectionRemote and SafeFarmProtectionRemote:IsA("RemoteEvent") then
        SafeFarmProtectionRemote:FireServer(true, "shop", DealerPart, "IllegalStore")
        task.wait(0.2)
    end

    if SafeFarmShopRemote and SafeFarmShopRemote:IsA("RemoteFunction") then
        Internal.Call( SafeFarmShopRemote.InvokeServer, SafeFarmShopRemote, "IllegalStore", "Melees", "Crowbar", DealerPart, nil, true)
    end

    if SafeFarmProtectionRemote and SafeFarmProtectionRemote:IsA("RemoteEvent") then
        task.wait(0.15)
        SafeFarmProtectionRemote:FireServer(false)
    end

    for _ = 1, 16 do
        if SafeFarmGetCrowbar() then return true end
        task.wait(0.15)
    end

    return SafeFarmGetCrowbar() ~= nil
end

function SafeFarmOpenSafe(Safe)
    local MainPart = SafeFarmGetSafePart(Safe)
    if not MainPart then return false end

    local StartedAt = os.clock()
    while SafeFarmEnabled and SafeFarmRuntime.Running and Safe.Parent and not SafeFarmIsBroken(Safe) do
        if os.clock() - StartedAt > 14 then return false end

        local Crowbar = SafeFarmEquipCrowbar() local Character, Humanoid, Root = SafeFarmGetCharacter()
        if not Crowbar or not Character or not Humanoid or not Root then
            task.wait(0.08)
            continue
        end

        local Distance = (Root.Position - MainPart.Position).Magnitude
        if Distance > 11 then return false end

        local FlatTarget = Vector3.new(MainPart.Position.X, Root.Position.Y, MainPart.Position.Z)
        if (FlatTarget - Root.Position).Magnitude > 0.05 then Root.CFrame = CFrame.lookAt(Root.Position, FlatTarget) end

        local RightArm = Character:FindFirstChild("Right Arm") or Character:FindFirstChild("RightHand")
        if not SafeFarmSwingRemote or not SafeFarmSwingRemote:IsA("RemoteFunction") then return false end

        local SwingSuccess, SwingToken = Internal.Call( SafeFarmSwingRemote.InvokeServer, SafeFarmSwingRemote, "\240\159\141\158", tick(), Crowbar, "DZDRRRKI",
            Safe, "Register")

        if SwingSuccess and SwingToken and SwingToken ~= false and SafeFarmHitRemote and SafeFarmHitRemote:IsA("RemoteEvent") then
            SafeFarmHitRemote:FireServer( "\240\159\141\158", tick(), Crowbar, "2389ZFX34", SwingToken, false,
                RightArm, MainPart, Safe, MainPart.Position, MainPart.Position)
        end

        task.wait(0.11)
    end

    return SafeFarmIsBroken(Safe)
end

function SafeFarmCollectCash()
    if not AutoPickupCashController.Runtime.Enabled then return end
    AutoPickupCashController.CollectFor(3)
end

function SafeFarmRegisterFailure(Safe)
    if not Safe then return end
    local Failures = (tonumber(SafeFarmRuntime.TargetFailures[Safe]) or 0) + 1
    SafeFarmRuntime.TargetFailures[Safe] = Failures
    SafeFarmRuntime.TargetCooldowns[Safe] = os.clock() + math.min(1.5 + Failures * 0.5, 6)
end

function SafeFarmReleaseTargetLock()
    SafeFarmRuntime.LockedTarget = nil
    SafeFarmRuntime.LockedTargetSince = 0
    SafeFarmRuntime.LockedTargetFailures = 0
end

function SafeFarmAcquireLockedTarget()
    local Locked = SafeFarmRuntime.LockedTarget
    if Locked and SafeFarmTargetStillValid(Locked) then
        local Age = os.clock() - (tonumber(SafeFarmRuntime.LockedTargetSince) or 0)
        if Age <= math.max(tonumber(SafeFarmRuntime.TargetLockTimeout) or 18, 4) then return Locked end
    end

    SafeFarmReleaseTargetLock()

    local Candidate = SafeFarmRuntime.NextTarget
    if not SafeFarmTargetStillValid(Candidate) then Candidate = SafeFarmFindTarget() end

    if Candidate then
        SafeFarmRuntime.LockedTarget = Candidate
        SafeFarmRuntime.LockedTargetSince = os.clock()
        SafeFarmRuntime.LockedTargetFailures = 0
    end

    return Candidate
end

function SafeFarmRuntime:Run()
    if self.Running then return end
    self.Running = true

    while self.Running and SafeFarmEnabled do
        if not SafeFarmApplyCharacterState() then
            self.Status = "Waiting For Character"
            task.wait(0.2)
            continue
        end

        if not SafeFarmGetCrowbar() then
            self.Status = "Buying Crowbar"

            if not SafeFarmBuyCrowbar() then
                self.TargetCacheTime = 0
                self.PathCache = {}
                task.wait(0.25)
            end

            continue
        end

        local Safe = SafeFarmAcquireLockedTarget()

        self.NextTarget = nil
        self.NextApproach = nil
        self.NextPath = nil
        self.CurrentTarget = Safe
        self.MovementTarget = Safe

        if not Safe then
            self.Status = "No Safes"
            task.wait(0.18)
            continue
        end

        local MainPart = SafeFarmGetSafePart(Safe)
        if not MainPart then
            SafeFarmRegisterFailure(Safe)
            task.wait(0.06)
            continue
        end

        self.Status = "Moving To " .. tostring(Safe.Name)
        SafeFarmPrepareNextTarget(Safe)

        local Moved, MoveReason = SafeFarmMoveNearPart(MainPart, Safe)
        if not Moved then
            if MoveReason == "TargetInvalid" or not SafeFarmTargetStillValid(Safe) then
                SafeFarmReleaseTargetLock()
            else
                SafeFarmRegisterFailure(Safe)
                self.LockedTargetFailures = (tonumber(self.LockedTargetFailures) or 0) + 1
                if self.LockedTargetFailures >= 3 then SafeFarmReleaseTargetLock() end
            end

            self.CurrentTarget = nil
            self.MovementTarget = nil
            task.wait(0.03)
            continue
        end

        self.LockedTargetFailures = 0

        self.Status = "Opening " .. tostring(Safe.Name)
        if not self.NextTarget or not SafeFarmTargetStillValid(self.NextTarget) then SafeFarmPrepareNextTarget(Safe) end

        if not SafeFarmOpenSafe(Safe) then
            SafeFarmRegisterFailure(Safe)
            self.LockedTargetFailures = (tonumber(self.LockedTargetFailures) or 0) + 1
            if not SafeFarmTargetStillValid(Safe) or self.LockedTargetFailures >= 3 then SafeFarmReleaseTargetLock() end
            task.wait(0.06)
            continue
        end

        SafeFarmReleaseTargetLock()
        self.LastSafe = Safe

        self.TargetFailures[Safe] = 0
        self.TargetCacheTime = 0
        self.TargetCooldowns[Safe] = 0
        self.Status = "Collecting"

        if not self.NextTarget or not SafeFarmTargetStillValid(self.NextTarget) then SafeFarmPrepareNextTarget(Safe) end

        SafeFarmCollectCash()

        if self.NextTarget and SafeFarmTargetStillValid(self.NextTarget) then
            local NextPart = SafeFarmGetSafePart(self.NextTarget)
            if NextPart and not self.NextApproach then self.NextApproach = SafeFarmFindApproach(NextPart, self.NextTarget) end
        end

        if type(AtramentaDoDeposit) == "function" then AtramentaDoDeposit() end
        self.CurrentTarget = nil
        self.MovementTarget = nil
        task.wait(0.015)
    end

    self.CurrentTarget = nil
    self.Status = "Idle"
    self.Running = false
    self.Thread = nil
end

function SafeFarmRuntime:Start()
    if self.Running then return end
    self.Thread = task.spawn(function() self:Run() end)
end

function SafeFarmRuntime:Stop()
    self.Running = false
    self.CurrentTarget = nil
    self.MovementTarget = nil
    self.NextTarget = nil
    self.NextApproach = nil
    self.NextPath = nil
    self.ArrivalLatchPart = nil
    self.ArrivalLatchUntil = 0
    self.LockedTarget = nil
    self.LockedTargetSince = 0
    self.LockedTargetFailures = 0
    self.TargetCacheTime = 0
    self.TargetCacheOrigin = nil
    table.clear(self.TargetCache)
    table.clear(self.PathCache)
    self.PathCachePruneAt = 0
end

function SafeFarmEnable()
    if SafeFarmEnabled then return end

    AltFarmEnabled = false
    SafeFarmEnabled = true

    if type(AutoPickupMoneyEnable) == "function" then AutoPickupMoneyEnable() end
    if type(FastPickupEnable) == "function" then FastPickupEnable() end
    if type(AutoRespawnEnable) == "function" then AutoRespawnEnable() end

    if type(AtramentaFarmModule) == "table" then
        if type(AtramentaFarmModule.SetSetting) == "function" then
            AtramentaFarmModule.SetSetting("AutoMoney", true)
            AtramentaFarmModule.SetSetting("AutoRespawn", true)
            AtramentaFarmModule.SetSetting("HideBody", true)
        end
        if type(AtramentaFarmModule.Stop) == "function" then AtramentaFarmModule.Stop() end
    end

    SafeFarmSetInvisibility(true)

    local Character, Humanoid, Root = SafeFarmGetCharacter()
    if Character and Humanoid and Root then SafeFarmRecordGroundedPosition(Character, Humanoid, Root) end

    SafeFarmRuntime:Start()

    task.delay(1.25, function()
        if SafeFarmEnabled and type(SafeFarmEnsureRouteAtlas) == "function" then SafeFarmEnsureRouteAtlas() end
    end)
end

function SafeFarmDisable()
    if not SafeFarmEnabled then return end

    SafeFarmEnabled = false
    SafeFarmRuntime:Stop()

    if type(AutoPickupMoneyDisable) == "function" then AutoPickupMoneyDisable() end
    if type(FastPickupDisable) == "function" then FastPickupDisable() end
    if type(AutoRespawnDisable) == "function" then AutoRespawnDisable() end

    if type(AtramentaFarmModule) == "table" and type(AtramentaFarmModule.SetSetting) == "function" then
        AtramentaFarmModule.SetSetting("AutoMoney", false)
        AtramentaFarmModule.SetSetting("AutoRespawn", false)
        AtramentaFarmModule.SetSetting("HideBody", false)
    end

    SafeFarmSetInvisibility(false)

end

return SafeFarmRuntime
end)()

AutoDepositBusy = false
function AtramentaGetCashAmount()
    local function from(data)
        if not data then return 0 end
        local cash = data:FindFirstChild("Cash")
        if cash and tonumber(cash.Value) then return math.floor(tonumber(cash.Value)) end
        return 0
    end
    local v = from(LocalPlayer:FindFirstChild("PlayerbaseData2"))
    if v > 0 then return v end
    local folder = ReplicatedStorage:FindFirstChild("PlayerbaseData2")
    if folder then
        v = from(folder:FindFirstChild(LocalPlayer.Name))
        if v > 0 then return v end
    end
    return 0
end

function AtramentaFindNearestATM()
    local map = workspace:FindFirstChild("Map") local folder = map and map:FindFirstChild("ATMz")
    local char = LocalPlayer.Character local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not folder or not hrp then return nil end
    local best, bestD = nil, math.huge
    for _, m in ipairs(folder:GetChildren()) do
        local part = m:FindFirstChild("MainPart") or m:FindFirstChild("atm")
        if part and part:IsA("BasePart") then
            local d = (part.Position - hrp.Position).Magnitude
            if d < bestD then best, bestD = part, d end
        end
    end
    return best
end

function AtramentaTeleportNearATM(atmPart)
    local char = LocalPlayer.Character local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not char or not hrp or not atmPart then return false end
    local dir = Vector3.new(hrp.Position.X - atmPart.Position.X, 0, hrp.Position.Z - atmPart.Position.Z)
    if dir.Magnitude < 0.1 then dir = Vector3.new(0, 0, 1) else dir = dir.Unit end
    local stand = atmPart.Position + dir * 4 + Vector3.new(0, 2.2, 0)

    if type(OurFarm_MainLoop) == "function" then

    end
    Internal.Call(function()
        if char.PivotTo then
            char:PivotTo(CFrame.lookAt(stand, atmPart.Position))
        else
            hrp.CFrame = CFrame.lookAt(stand, atmPart.Position)
        end
        hrp.AssemblyLinearVelocity = Vector3.zero
    end)

    Internal.Call(function()
        local ev = ReplicatedStorage:FindFirstChild("Events") local mov = ev and ev:FindFirstChild("MOVZREP")
        if mov then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                local joints = {}
                for _, v in ipairs(char:GetDescendants()) do
                    if v:IsA("Motor6D") then joints[#joints + 1] = v end
                end
                table.sort(joints, function(a, b) return a.Name < b.Name end)
                local c0s = {}
                for i = 1, math.min(7, #joints) do c0s[i] = joints[i].C0 end
                for i = #c0s + 1, 7 do c0s[i] = CFrame.new() end
                mov:FireServer({c0s, false, false, hum.WalkSpeed}, true)
            end
        end
    end)
    task.wait(0.35)
    return (hrp.Position - atmPart.Position).Magnitude <= 6.5
end

function AtramentaDoDeposit()
    if AutoDepositBusy then return false end
    local settings = AtramentaFarmModule and AtramentaFarmModule.Settings
    if not settings or not settings.AutoDeposit then return false end
    local cash = AtramentaGetCashAmount() local threshold = math.max(1, tonumber(settings.AutoDepositThresholdK) or 5) * 1000
    if cash < threshold then return false end
    local atm = AtramentaFindNearestATM()
    if not atm then return false end
    AutoDepositBusy = true
    local ok = false
    Internal.Call(function()
        if not AtramentaTeleportNearATM(atm) then

            AtramentaTeleportNearATM(atm)
        end
        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not hrp or (hrp.Position - atm.Position).Magnitude > 6.5 then return end
        local ev = ReplicatedStorage:FindFirstChild("Events") local atmRemote = ev and ev:FindFirstChild("ATM") local prot = ev and ev:FindFirstChild("BYZERSPROTEC")
        if prot then
            Internal.Call(function() prot:FireServer(true, "ATM", atm) end)
            task.wait(0.25)
        end
        local amount = AtramentaGetCashAmount()
        if atmRemote and amount > 0 then
            local success, result = Internal.Call(function()
                return atmRemote:InvokeServer("DP", amount, atm)
            end)
            ok = success and result ~= false
        end
        if prot then Internal.Call(function() prot:FireServer(false) end) end
        task.wait(0.4)
    end)
    AutoDepositBusy = false
    return ok
end

AtramentaRuntimeControl:AddThread(task.spawn(function()
    while not AtramentaRuntimeControl.Destroyed do
        task.wait(2.5)
        if AtramentaRuntimeControl.Destroyed then break end
        Internal.Call(function()
            local Settings = AtramentaFarmModule and AtramentaFarmModule.Settings
            if Settings and Settings.AutoDeposit then AtramentaDoDeposit() end
        end)
    end
end))

