    AtramentaFarmModule.SetSetting("AutoPlay", false)
    if not SafeFarmEnabled then
        if type(AtramentaFarmModule.Destroy) == "function" then AtramentaFarmModule.Destroy() else AtramentaFarmModule.Stop() end
    end
