function DestroyChinaHat()
    if Configuration.ChinaHat.Motor and Configuration.ChinaHat.Motor.Parent then Configuration.ChinaHat.Motor:Destroy() end
    if Configuration.ChinaHat.Model then Configuration.ChinaHat.Model:Destroy() end
    Configuration.ChinaHat.Model = nil
    Configuration.ChinaHat.Motor = nil
    Internal.AtramentaReleaseBuffer(Configuration.ChinaHat.SurfaceBeams)
    Internal.AtramentaReleaseBuffer(Configuration.ChinaHat.OutlineBeams)
    Internal.AtramentaReleaseBuffer(Configuration.ChinaHat.Attachments)
    Configuration.ChinaHat.AppearanceAccumulator = 0
    Configuration.ChinaHat.AppearanceBatchIndex = 1
    Configuration.ChinaHat.RuntimeAccumulator = 0
end

function BuildChinaHatRainbowPalette()
    local Palette = Configuration.ChinaHat.RainbowPalette local Count = math.max(math.floor(tonumber(Configuration.ChinaHat.RainbowPaletteSize) or 96), 24)

    if #Palette == Count then return Palette end

    table.clear(Palette)

    for Index = 1, Count do
        Palette[Index] = Color3.fromHSV((Index - 1) / Count, 0.82, 1)
    end

    return Palette
end

function GetChinaHatColor(Index, Offset)
    if not Configuration.ChinaHat.Rainbow then return Configuration.ChinaHat.Color end

    local Palette = BuildChinaHatRainbowPalette() local Count = #Palette
    local Segments = math.max(Configuration.ChinaHat.Segments, 1) local Phase = (Configuration.ChinaHat.Time * Configuration.ChinaHat.RainbowSpeed) % 1
    local Position = Phase + (Index - 1) / Segments + (Offset or 0) local PaletteIndex = math.floor((Position % 1) * Count) + 1

    return Palette[PaletteIndex]
end

function CreateChinaHatAttachment(Parent, Name, Position)
    local Attachment = Instance.new("Attachment")
    Attachment.Name = Name
    Attachment.Position = Position
    Attachment.Parent = Parent
    Configuration.ChinaHat.Attachments[#Configuration.ChinaHat.Attachments + 1] = Attachment
    return Attachment
end

function CreateChinaHatBeam(Parent, Name, Attachment0, Attachment1, Width0, Width1, Transparency, ZOffset)
    local Beam = Instance.new("Beam")
    Beam.Name = Name
    Beam.Attachment0 = Attachment0
    Beam.Attachment1 = Attachment1
    Beam.FaceCamera = true
    Beam.Segments = 1
    Beam.Width0 = Width0
    Beam.Width1 = Width1
    Beam.Transparency = Transparency
    Beam.LightEmission = 0.82
    Beam.LightInfluence = 0
    Beam.Brightness = 1
    Beam.ZOffset = ZOffset
    Beam.Parent = Parent
    return Beam
end

function UpdateChinaHatAppearance(UseBatch)
    local Transparency = AngelWingClamp(Configuration.ChinaHat.Transparency, 0, 0.94) local SurfaceBeams = Configuration.ChinaHat.SurfaceBeams
    local OutlineBeams = Configuration.ChinaHat.OutlineBeams local SurfaceCount = #SurfaceBeams
    local OutlineCount = #OutlineBeams local TotalCount = SurfaceCount + OutlineCount local StartIndex = UseBatch and Configuration.ChinaHat.AppearanceBatchIndex or 1
    local EndIndex = UseBatch and math.min(StartIndex + Configuration.ChinaHat.AppearanceBatchSize - 1, TotalCount) or TotalCount local UpdateTransparency = UseBatch ~= true

    for GlobalIndex = StartIndex, math.min(EndIndex, SurfaceCount) do
        local Index = GlobalIndex local Data = SurfaceBeams[Index] local Beam = Data and Data.Beam
        if Beam and Beam.Parent then
            Beam.Color = ColorSequence.new(GetChinaHatColor(Index, 0), GetChinaHatColor(Index + 1, 0))
            if UpdateTransparency then
                Beam.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.26, 0, 0.97)),
                    NumberSequenceKeypoint.new(0.72, AngelWingClamp(Transparency + 0.20, 0, 0.96)),
                    NumberSequenceKeypoint.new(1, AngelWingClamp(Transparency + 0.12, 0, 0.95)) })
            end
        end
    end

    local OutlineStart = math.max(StartIndex, SurfaceCount + 1)
    for GlobalIndex = OutlineStart, EndIndex do
        local Index = GlobalIndex - SurfaceCount local Data = OutlineBeams[Index]
        if not Data then break end
        local Beam = Data.Beam
        if Beam and Beam.Parent then
            Beam.Color = ColorSequence.new(GetChinaHatColor(Data.ColorIndex or Index, Data.HueOffset or 0),
                GetChinaHatColor((Data.ColorIndex or Index) + 1, Data.HueOffset or 0))
            if UpdateTransparency then Beam.Transparency = NumberSequence.new(AngelWingClamp(Transparency + (Data.Faint and 0.22 or 0), 0, 0.96)) end
        end
    end

    if UseBatch and TotalCount > 0 then
        Configuration.ChinaHat.AppearanceBatchIndex = EndIndex >= TotalCount and 1 or EndIndex + 1
    else
        Configuration.ChinaHat.AppearanceBatchIndex = 1
    end
end

function CreateChinaHat(Character)
    Character = Character or LocalPlayer.Character
    local CurrentTime = os.clock()
    if CurrentTime < (tonumber(Configuration.ChinaHat.NextBuildAt) or 0) then return false end
    Configuration.ChinaHat.NextBuildAt = CurrentTime + 0.20

    if not Character then return false end
    local Head = Character:FindFirstChild("Head") local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Head or not Humanoid or Humanoid.RigType ~= Enum.HumanoidRigType.R6 then return false end

    DestroyChinaHat()
    local Model = Instance.new("Model")
    Model.Name = "MinecraftChinaHat"
    Model.Parent = Character
    local Pivot = Instance.new("Part")
    Pivot.Name = "ChinaHatPivot"
    Pivot.Size = Vector3.new(0.1, 0.1, 0.1)
    Pivot.Transparency = 1
    Pivot.Anchored = false
    Pivot.CanCollide = false
    Pivot.CanTouch = false
    Pivot.CanQuery = false
    Pivot.Massless = true
    Pivot.CastShadow = false
    Pivot.CFrame = Head.CFrame * CFrame.new(0, Configuration.ChinaHat.Height, 0)
    Pivot.Parent = Model
    local Motor = Instance.new("Motor6D")
    Motor.Name = "ChinaHatMotor"
    Motor.Part0 = Head
    Motor.Part1 = Pivot
    Motor.C0 = CFrame.new(0, Configuration.ChinaHat.Height, 0)
    Motor.C1 = CFrame.new()
    Motor.Parent = Head
    local Segments = Configuration.ChinaHat.Segments local Scale = Configuration.ChinaHat.Scale local Radius = 1.18 * Scale local RimHeight = -0.28 * Scale
    local ApexHeight = 0.48 * Scale local InnerRadius = Radius * 0.54
    local InnerHeight = RimHeight + (ApexHeight - RimHeight) * 0.46 local ArcWidth = (Radius * math.pi * 2) / Segments
    local Apex = CreateChinaHatAttachment(Pivot, "HatApex", Vector3.new(0, ApexHeight, 0))
    local Rim = {}
    local Inner = {}
    for Index = 1, Segments do
        local Angle = (Index - 1) / Segments * math.pi * 2 local X = math.cos(Angle) local Z = math.sin(Angle)
        Rim[Index] = CreateChinaHatAttachment(Pivot, "HatRim_" .. Index, Vector3.new(X * Radius, RimHeight, Z * Radius))
        Inner[Index] = CreateChinaHatAttachment(Pivot, "HatInner_" .. Index, Vector3.new(X * InnerRadius, InnerHeight, Z * InnerRadius))
    end
    for Index = 1, Segments do
        local NextIndex = Index % Segments + 1
        local Surface = CreateChinaHatBeam(Pivot, "HatSurface_" .. Index, Apex, Rim[Index], 0.018 * Scale, ArcWidth * 1.08, NumberSequence.new(0.42), -0.02)
        Configuration.ChinaHat.SurfaceBeams[#Configuration.ChinaHat.SurfaceBeams + 1] = { Beam = Surface }
        local RimBeam = CreateChinaHatBeam(Pivot, "HatRimLine_" .. Index, Rim[Index], Rim[NextIndex], 0.038 * Scale, 0.038 * Scale, NumberSequence.new(0.10), 0.03)
        Configuration.ChinaHat.OutlineBeams[#Configuration.ChinaHat.OutlineBeams + 1] = { Beam = RimBeam, ColorIndex = Index, HueOffset = 0, Faint = false }
        local InnerBeam = CreateChinaHatBeam(Pivot, "HatInnerLine_" .. Index, Inner[Index], Inner[NextIndex], 0.024 * Scale, 0.024 * Scale, NumberSequence.new(0.32), 0.02)
        Configuration.ChinaHat.OutlineBeams[#Configuration.ChinaHat.OutlineBeams + 1] = { Beam = InnerBeam, ColorIndex = Index, HueOffset = 0.04, Faint = true }
        if Index % 4 == 1 then
            local Spoke = CreateChinaHatBeam(Pivot, "HatSpoke_" .. Index, Apex, Rim[Index], 0.018 * Scale, 0.018 * Scale, NumberSequence.new(0.38), 0.04)
            Configuration.ChinaHat.OutlineBeams[#Configuration.ChinaHat.OutlineBeams + 1] = { Beam = Spoke, ColorIndex = Index, HueOffset = 0.02, Faint = true }
        end
    end
    Configuration.ChinaHat.Model = Model
    Configuration.ChinaHat.Motor = Motor Configuration.ChinaHat.Time = 0
    Configuration.ChinaHat.AppearanceAccumulator = 0
    UpdateChinaHatAppearance()
    Configuration.ChinaHat.RuntimeAccumulator = 0
    Configuration.ChinaHat.NextBuildAt = 0
    return true
end
function UpdateChinaHat(DeltaTime)
    if not Configuration.ChinaHat.Enabled then return end
    DeltaTime = AngelWingClamp(tonumber(DeltaTime) or 0.016, 0.001, 0.05)
    Configuration.ChinaHat.RuntimeAccumulator = (tonumber(Configuration.ChinaHat.RuntimeAccumulator) or 0) + DeltaTime
    local RuntimeInterval = tonumber(Configuration.ChinaHat.RuntimeInterval) or 1 / 30
    if Configuration.ChinaHat.RuntimeAccumulator < RuntimeInterval then return end

    DeltaTime = Configuration.ChinaHat.RuntimeAccumulator Configuration.ChinaHat.RuntimeAccumulator = 0
    local Character = LocalPlayer.Character
    if not Character then DestroyChinaHat(); return end
    if not Configuration.ChinaHat.Model or Configuration.ChinaHat.Model.Parent ~= Character then CreateChinaHat(Character); return end

    local Motor = Configuration.ChinaHat.Motor if not Motor or not Motor.Parent then CreateChinaHat(Character); return end
    Configuration.ChinaHat.Time += DeltaTime
    local Rotation = math.rad(Configuration.ChinaHat.Time * Configuration.ChinaHat.SpinSpeed) local Bob = math.sin(Configuration.ChinaHat.Time * 2) * 0.012
    local Target = CFrame.new(0, Bob, 0) * CFrame.Angles(0, Rotation, 0)
    Motor.Transform = Motor.Transform:Lerp(Target, AngelWingExpAlpha(10, DeltaTime))

    if Configuration.ChinaHat.Rainbow then
        Configuration.ChinaHat.AppearanceAccumulator += DeltaTime
        if Configuration.ChinaHat.AppearanceAccumulator >= Configuration.ChinaHat.AppearanceInterval then
            Configuration.ChinaHat.AppearanceAccumulator %= Configuration.ChinaHat.AppearanceInterval
            UpdateChinaHatAppearance(true)
        end
    else
        Configuration.ChinaHat.AppearanceAccumulator = 0
    end
end

function SetupChinaHat()
    if Configuration.ChinaHat.Connection then Configuration.ChinaHat.Connection:Disconnect() end
    Configuration.ChinaHat.Connection = RunService.Heartbeat:Connect(function(DeltaTime)
        Internal.Call(UpdateChinaHat, DeltaTime)
    end)
    if Configuration.ChinaHat.CharacterConnection then Configuration.ChinaHat.CharacterConnection:Disconnect() end
    Configuration.ChinaHat.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
        Configuration.ChinaHat.BuildGeneration = (tonumber(Configuration.ChinaHat.BuildGeneration) or 0) + 1
        local Generation = Configuration.ChinaHat.BuildGeneration
        task.spawn(function()
            task.wait(0.55)
            if Configuration.ChinaHat.Enabled and Generation == Configuration.ChinaHat.BuildGeneration and Character == LocalPlayer.Character then
                Configuration.ChinaHat.NextBuildAt = 0
                CreateChinaHat(Character)
            end
        end)
    end)
    Configuration.ChinaHat.NextBuildAt = 0
    CreateChinaHat(LocalPlayer.Character)
end

function RebuildChinaHat()
    if not Configuration.ChinaHat.Enabled then return end
    Configuration.ChinaHat.NextBuildAt = 0
    CreateChinaHat(LocalPlayer.Character)
end

function ToggleChinaHat(State)
    Configuration.ChinaHat.Enabled = State == true
    Configuration.ChinaHat.BuildGeneration = (tonumber(Configuration.ChinaHat.BuildGeneration) or 0) + 1
    if Configuration.ChinaHat.Enabled then
        SetupChinaHat()
    else
        if Configuration.ChinaHat.Connection then Configuration.ChinaHat.Connection:Disconnect(); Configuration.ChinaHat.Connection = nil end
        if Configuration.ChinaHat.CharacterConnection then Configuration.ChinaHat.CharacterConnection:Disconnect(); Configuration.ChinaHat.CharacterConnection = nil end
        DestroyChinaHat()
    end
end

function AngelWingClamp(Value, Minimum, Maximum) return math.max(Minimum, math.min(Maximum, Value)) end

function AngelWingLerp(A, B, Alpha) return A + (B - A) * Alpha end

function AngelWingSmoothStep(Value)
    Value = AngelWingClamp(Value, 0, 1)
    return Value * Value * (3 - 2 * Value)
end

function AngelWingExpAlpha(Speed, DeltaTime) return 1 - math.exp(-Speed * DeltaTime) end

function AngelWingStableStroke(Value)
    Value = AngelWingClamp(tonumber(Value) or 0, -1, 1)
    return Value * (0.88 + 0.12 * (1 - math.abs(Value)))
end

function HoldAngelWingsForRagdoll(Duration)
    if not Configuration or not Configuration.AngelWings then return end
    local Until = os.clock() + math.max(tonumber(Duration) or 0.18, 0.05)
    Configuration.AngelWings.RagdollHoldUntil = math.max(tonumber(Configuration.AngelWings.RagdollHoldUntil) or 0, Until)
end

function IsAngelWingGameRagdolled(Character, Humanoid)
    if not Character or not Humanoid then return false end
    if os.clock() < (tonumber(Configuration.AngelWings.RagdollHoldUntil) or 0) then return true end
    local State = Humanoid:GetState()
    if State == Enum.HumanoidStateType.Ragdoll or State == Enum.HumanoidStateType.FallingDown or State == Enum.HumanoidStateType.Physics then return true end
    local CurrentTime = os.clock()
    local Switch = Configuration.AngelWings.RagdollSwitch
    if Configuration.AngelWings.RagdollSwitchCharacter ~= Character or CurrentTime >= (tonumber(Configuration.AngelWings.NextRagdollScan) or 0) or Switch and not Switch.Parent then
        Configuration.AngelWings.RagdollSwitchCharacter = Character
        Configuration.AngelWings.NextRagdollScan = CurrentTime + (tonumber(Configuration.AngelWings.RagdollScanInterval) or 0.35)
        Switch = nil
        local CharacterStats = Character:FindFirstChild("CharStats")
        if CharacterStats then
            local PlayerStats = CharacterStats:FindFirstChild(LocalPlayer.Name) or CharacterStats:FindFirstChild(tostring(LocalPlayer.UserId)) or CharacterStats
            Switch = PlayerStats:FindFirstChild("RagdollSwitch") or CharacterStats:FindFirstChild("RagdollSwitch", true)
        end
        Configuration.AngelWings.RagdollSwitch = Switch
    end
    return Switch ~= nil and Switch:IsA("BoolValue") and Switch.Value == true
end

function SetAngelWingEmittersEnabled(Enabled)
    for _, Emitter in ipairs(Configuration.AngelWings.Emitters) do
        if Emitter and Emitter.Parent then Emitter.Enabled = Enabled == true end
    end
    for _, Trail in ipairs(Configuration.AngelWings.Trails) do
        if Trail and Trail.Parent then Trail.Enabled = Enabled == true end
    end
end

function FreezeAngelWingsForRagdoll()
    local LeftMotor = Configuration.AngelWings.LeftMotor
    local RightMotor = Configuration.AngelWings.RightMotor
    if LeftMotor and LeftMotor.Parent then LeftMotor.Transform = CFrame.Angles(math.rad(-7), math.rad(-18), math.rad(-10)) end
    if RightMotor and RightMotor.Parent then RightMotor.Transform = CFrame.Angles(math.rad(-7), math.rad(18), math.rad(10)) end
    Configuration.AngelWings.StrokeVelocity = 0
    Configuration.AngelWings.PreviousStroke = -0.35
    Configuration.AngelWings.CurrentActivity = 0.46
    Configuration.AngelWings.FeatherAccumulator = 0
    Configuration.AngelWings.EmitterAccumulator = 0
    SetAngelWingEmittersEnabled(false)
end

function RecoverAngelWingsFromRagdoll(Character)
    if not Character or Character ~= LocalPlayer.Character then return false end
    local LeftMotor = Configuration.AngelWings.LeftMotor
    local RightMotor = Configuration.AngelWings.RightMotor
    if not LeftMotor or not RightMotor or not LeftMotor.Parent or not RightMotor.Parent then
        CreateAngelWings(Character)
        return false
    end
    LeftMotor.Transform = CFrame.new()
    RightMotor.Transform = CFrame.new()
    Configuration.AngelWings.Phase = 0
    Configuration.AngelWings.PreviousStroke = -0.35
    Configuration.AngelWings.StrokeVelocity = 0
    Configuration.AngelWings.CurrentActivity = 0.50
    Configuration.AngelWings.FeatherAccumulator = 0
    Configuration.AngelWings.FeatherBatchIndex = 1
    Configuration.AngelWings.EmitterAccumulator = 0
    Configuration.AngelWings.ValidationAccumulator = 0
    UpdateAngelWingFeathers(0, 0.50)
    SetAngelWingEmittersEnabled(true)
    return true
end

function AngelWingFrame(Position, Tangent, Normal)
    local Axis = Tangent.Magnitude > 0.001 and Tangent.Unit or Vector3.new(1, 0, 0)
    local Up = Normal.Magnitude > 0.001 and Normal.Unit or Vector3.new(0, 1, 0)
    if math.abs(Axis:Dot(Up)) > 0.94 then Up = Vector3.new(0, 0, 1) end
    local Back = Axis:Cross(Up)
    if Back.Magnitude < 0.001 then Back = Vector3.new(0, 0, 1) else Back = Back.Unit end
    Up = Back:Cross(Axis)
    if Up.Magnitude < 0.001 then Up = Vector3.new(0, 1, 0) else Up = Up.Unit end
    return CFrame.fromMatrix(Position, Axis, Up, Back)
end

function DestroyAngelWingModel()
    if Configuration.AngelWings.LeftMotor and Configuration.AngelWings.LeftMotor.Parent then Configuration.AngelWings.LeftMotor:Destroy() end
    if Configuration.AngelWings.RightMotor and Configuration.AngelWings.RightMotor.Parent then Configuration.AngelWings.RightMotor:Destroy() end
    if Configuration.AngelWings.Model and Configuration.AngelWings.Model.Parent then Configuration.AngelWings.Model:Destroy() end
    local Character = LocalPlayer.Character
    if Character then
        for _, Object in ipairs(Character:GetChildren()) do
            if Object:IsA("Model") and Object.Name == "AtramentaCosmeticWings" then Object:Destroy() end
        end
        local Torso = Character:FindFirstChild("Torso")
        if Torso then
            for _, Object in ipairs(Torso:GetChildren()) do
                if Object:IsA("Motor6D") and (Object.Name == "LeftWingMotor" or Object.Name == "RightWingMotor") then Object:Destroy() end
            end
        end
    end
    Configuration.AngelWings.Model = nil
    Configuration.AngelWings.LeftMotor = nil
    Configuration.AngelWings.RightMotor = nil
    Internal.AtramentaReleaseBuffer(Configuration.AngelWings.Feathers)
    Internal.AtramentaReleaseBuffer(Configuration.AngelWings.Beams)
    Internal.AtramentaReleaseBuffer(Configuration.AngelWings.Emitters)
    Internal.AtramentaReleaseBuffer(Configuration.AngelWings.Trails)
    Configuration.AngelWings.FeatherAccumulator = 0
    Configuration.AngelWings.FeatherBatchIndex = 1
    Configuration.AngelWings.EmitterAccumulator = 0
    Configuration.AngelWings.ValidationAccumulator = 0
    Configuration.AngelWings.RuntimeAccumulator = 0
    Configuration.AngelWings.CachedCharacter = nil
    Configuration.AngelWings.CachedHumanoid = nil
    Configuration.AngelWings.CachedRootPart = nil
    Configuration.AngelWings.Ragdolled = false
    Configuration.AngelWings.RecoverUntil = 0
    Configuration.AngelWings.LastRagdollCharacter = nil
    Configuration.AngelWings.RagdollSwitch = nil
    Configuration.AngelWings.RagdollSwitchCharacter = nil
    Configuration.AngelWings.NextRagdollScan = 0
end

function GetAngelWingStroke(Phase)
    local Cycle = (Phase / (math.pi * 2)) % 1
    if Cycle < 0.34 then
        local T = AngelWingSmoothStep(Cycle / 0.34)
        return AngelWingLerp(-1, 1, T), true, Cycle
    end
    local T = AngelWingSmoothStep((Cycle - 0.34) / 0.66)
    return AngelWingLerp(1, -1, T), false, Cycle
end

function CreateAngelWingPivot(Torso, Model, Side)
    local Pivot = Instance.new("Part")
    Pivot.Name = Side < 0 and "LeftWingPivot" or "RightWingPivot"
    Pivot.Size = Vector3.new(0.1, 0.1, 0.1)
    Pivot.Transparency = 1
    Pivot.Anchored = false
    Pivot.CanCollide = false
    Pivot.CanTouch = false
    Pivot.CanQuery = false
    Pivot.Massless = true
    Pivot.CastShadow = false
    local Offset = Vector3.new(Side * Configuration.AngelWings.SideOffset, Configuration.AngelWings.HeightOffset, Configuration.AngelWings.BackOffset)
    Pivot.CFrame = Torso.CFrame * CFrame.new(Offset)
    Pivot.Parent = Model
    local Motor = Instance.new("Motor6D")
    Motor.Name = Side < 0 and "LeftWingMotor" or "RightWingMotor"
    Motor.Part0 = Torso
    Motor.Part1 = Pivot
    Motor.C0 = CFrame.new(Offset)
    Motor.C1 = CFrame.new()
    Motor.Parent = Torso
    return Pivot, Motor
end

function CreateAngelWingAttachment(Parent, Name, Position, Tangent, Normal)
    local Attachment = Instance.new("Attachment")
    Attachment.Name = Name
    Attachment.CFrame = AngelWingFrame(Position, Tangent, Normal)
    Attachment.Parent = Parent
    return Attachment
end

function CreateAngelWingBeam(Parent, Name, Attachment0, Attachment1, Width0, Width1, Curve0, Curve1, Color, Transparency, Brightness, ZOffset)
    local Beam = Instance.new("Beam")
    Beam.Name = Name
    Beam.Attachment0 = Attachment0
    Beam.Attachment1 = Attachment1
    Beam.FaceCamera = true
    Beam.Segments = Name:find("Vein_", 1, true) and 4 or Name:find("Spine_", 1, true) and 8 or 10
    Beam.Width0 = Width0
    Beam.Width1 = Width1
    Beam.CurveSize0 = Curve0
    Beam.CurveSize1 = Curve1
    Beam.Color = Color
    Beam.Transparency = Transparency
    Beam.LightEmission = 0.88
    Beam.LightInfluence = 0
    Beam.Brightness = Brightness
    Beam.ZOffset = ZOffset or 0
    Beam.Parent = Parent
    Configuration.AngelWings.Beams[#Configuration.AngelWings.Beams + 1] = Beam
    return Beam
end

function CreateAngelWingFeather(Pivot, Side, Layer, Index, Count, RootPosition, TipPosition, Width, Curve, Flutter, Weight)
    local Progress = Count > 1 and (Index - 1) / (Count - 1) or 0
    local Direction = TipPosition - RootPosition
    local Normal = Vector3.new(0, 1, Side * 0.16)
    local Root = CreateAngelWingAttachment(Pivot, "Root_" .. Layer .. "_" .. Index, RootPosition, Direction + Vector3.new(0, Curve * 0.42, 0), Normal)
    local Tip = CreateAngelWingAttachment(Pivot, "Tip_" .. Layer .. "_" .. Index, TipPosition, Direction + Vector3.new(0, -Curve * 0.22, Side * 0.08), Normal)
    local Core = Configuration.AngelWings.CoreColor
    local Glow = Configuration.AngelWings.GlowColor
    local MainBeam = CreateAngelWingBeam(Pivot, "Feather_" .. Layer .. "_" .. Index, Root, Tip, Width, Width * 0.055, Curve, Curve * 0.46,
        ColorSequence.new({ColorSequenceKeypoint.new(0, Core), ColorSequenceKeypoint.new(0.68, Core), ColorSequenceKeypoint.new(1, Glow)}),
        NumberSequence.new({NumberSequenceKeypoint.new(0, 0.08), NumberSequenceKeypoint.new(0.72, 0.20), NumberSequenceKeypoint.new(1, 0.72)}), 1.05, 0)
    local EdgeBeam = CreateAngelWingBeam(Pivot, "Edge_" .. Layer .. "_" .. Index, Root, Tip, Width * 1.08, Width * 0.075, Curve, Curve * 0.46,
        ColorSequence.new({ColorSequenceKeypoint.new(0, Glow), ColorSequenceKeypoint.new(0.52, Core), ColorSequenceKeypoint.new(1, Glow)}),
        NumberSequence.new({NumberSequenceKeypoint.new(0, 0.72), NumberSequenceKeypoint.new(0.72, 0.82), NumberSequenceKeypoint.new(1, 0.96)}), 0.72, -0.018)
    local VeinBeam = CreateAngelWingBeam(Pivot, "Vein_" .. Layer .. "_" .. Index, Root, Tip, math.max(Width * 0.09, 0.028), 0.008, Curve * 0.94, Curve * 0.42,
        ColorSequence.new(Glow, Core), NumberSequence.new({NumberSequenceKeypoint.new(0, 0.34), NumberSequenceKeypoint.new(0.80, 0.56), NumberSequenceKeypoint.new(1, 0.92)}), 1.12, 0.012)
    local TrailTip
    local TrailOffset = 0
    if Layer == "Primary" and Index == Count then
        TrailOffset = math.max(Width * 0.16, 0.045)
        local TipFrame = AngelWingFrame(TipPosition, Direction + Vector3.new(0, -Curve * 0.22, Side * 0.08), Normal)
        TrailTip = Instance.new("Attachment")
        TrailTip.Name = "TrailTip_" .. tostring(Side)
        TrailTip.CFrame = TipFrame * CFrame.new(0, TrailOffset, 0)
        TrailTip.Parent = Pivot
    end
    Configuration.AngelWings.Feathers[#Configuration.AngelWings.Feathers + 1] = {
        Side = Side, Layer = Layer, Index = Index, Count = Count, Progress = Progress, RootPosition = RootPosition, TipPosition = TipPosition,
        Curve = Curve, Flutter = Flutter, Weight = Weight, Offset = Index * 0.41 + (Layer == "Primary" and 0 or Layer == "Upper" and 1.35 or Layer == "Inner" and 2.45 or 3.2),
        Root = Root, Tip = Tip, TrailTip = TrailTip, TrailOffset = TrailOffset, MainBeam = MainBeam, EdgeBeam = EdgeBeam, VeinBeam = VeinBeam, LastTip = TipPosition, LastCurve0 = Curve, LastCurve1 = Curve * 0.46
    }
end

function CreateAngelWingSpine(Pivot, Side, Scale, Name, Middle, Tip)
    local RootPosition = Vector3.new(Side * 0.02, 0.20 * Scale, 0)
    local MiddlePosition = Vector3.new(Side * Middle.X * Scale, Middle.Y * Scale, Middle.Z * Scale)
    local TipPosition = Vector3.new(Side * Tip.X * Scale, Tip.Y * Scale, Tip.Z * Scale)
    local RootDirection = MiddlePosition - RootPosition
    local TipDirection = TipPosition - MiddlePosition
    local Root = CreateAngelWingAttachment(Pivot, "SpineRoot_" .. Name, RootPosition, RootDirection, Vector3.new(0, 1, 0))
    local MiddleA = CreateAngelWingAttachment(Pivot, "SpineMidA_" .. Name, MiddlePosition, RootDirection, Vector3.new(0, 1, 0))
    local MiddleB = CreateAngelWingAttachment(Pivot, "SpineMidB_" .. Name, MiddlePosition, TipDirection, Vector3.new(0, 1, 0))
    local TipA = CreateAngelWingAttachment(Pivot, "SpineTip_" .. Name, TipPosition, TipDirection, Vector3.new(0, 1, 0))
    local Color = ColorSequence.new(Configuration.AngelWings.GlowColor, Configuration.AngelWings.CoreColor)
    local Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.28), NumberSequenceKeypoint.new(0.72, 0.46), NumberSequenceKeypoint.new(1, 0.82)})
    CreateAngelWingBeam(Pivot, "Spine_" .. Name .. "A", Root, MiddleA, 0.15 * Scale, 0.09 * Scale, 0.35 * Scale, -0.12 * Scale, Color, Transparency, 1.1, -0.01)
    CreateAngelWingBeam(Pivot, "Spine_" .. Name .. "B", MiddleB, TipA, 0.09 * Scale, 0.025 * Scale, 0.28 * Scale, -0.18 * Scale, Color, Transparency, 1.0, -0.01)
end

function CreateAngelWingSide(Pivot, Side, Scale)
    CreateAngelWingSpine(Pivot, Side, Scale, "Upper", Vector3.new(1.85, 0.92, 0.16), Vector3.new(4.65, 1.28, 0.46))
    CreateAngelWingSpine(Pivot, Side, Scale, "Lower", Vector3.new(2.05, -0.12, 0.28), Vector3.new(5.10, -1.42, 0.82))
    local PrimaryCount = 11
    for Index = 1, PrimaryCount do
        local T = (Index - 1) / (PrimaryCount - 1)
        local Root = Vector3.new(Side * (0.10 + T * 1.18) * Scale, (0.18 - T * 0.22) * Scale, (0.02 + T * 0.12) * Scale)
        local Tip = Vector3.new(Side * (3.30 + T * 2.55) * Scale, (0.62 - T * 3.42) * Scale, (0.24 + T * 0.78) * Scale)
        CreateAngelWingFeather(Pivot, Side, "Primary", Index, PrimaryCount, Root, Tip, (0.72 - T * 0.22) * Scale, (1.18 + T * 0.34) * Scale, (0.10 + T * 0.08) * Scale, 1)
    end
    local UpperCount = 8
    for Index = 1, UpperCount do
        local T = (Index - 1) / (UpperCount - 1)
        local Root = Vector3.new(Side * (0.06 + T * 0.90) * Scale, (0.40 + T * 0.06) * Scale, (0.01 + T * 0.08) * Scale)
        local Tip = Vector3.new(Side * (2.20 + T * 2.88) * Scale, (2.42 - T * 1.28) * Scale, (0.16 + T * 0.50) * Scale)
        CreateAngelWingFeather(Pivot, Side, "Upper", Index, UpperCount, Root, Tip, (0.68 - T * 0.16) * Scale, (0.92 + T * 0.30) * Scale, (0.07 + T * 0.05) * Scale, 0.78)
    end
    local InnerCount = 7
    for Index = 1, InnerCount do
        local T = (Index - 1) / (InnerCount - 1)
        local Root = Vector3.new(Side * (0.03 + T * 0.64) * Scale, (0.16 + T * 0.20) * Scale, (0.01 + T * 0.06) * Scale)
        local Tip = Vector3.new(Side * (1.42 + T * 2.18) * Scale, (1.34 - T * 1.12) * Scale, (0.08 + T * 0.40) * Scale)
        CreateAngelWingFeather(Pivot, Side, "Inner", Index, InnerCount, Root, Tip, (0.64 - T * 0.15) * Scale, (0.74 + T * 0.22) * Scale, (0.05 + T * 0.04) * Scale, 0.54)
    end
    local LowerCount = 5
    for Index = 1, LowerCount do
        local T = (Index - 1) / (LowerCount - 1)
        local Root = Vector3.new(Side * (0.08 + T * 0.74) * Scale, (-0.02 - T * 0.12) * Scale, (0.04 + T * 0.08) * Scale)
        local Tip = Vector3.new(Side * (2.34 + T * 2.22) * Scale, (-1.28 - T * 1.70) * Scale, (0.22 + T * 0.62) * Scale)
        CreateAngelWingFeather(Pivot, Side, "Lower", Index, LowerCount, Root, Tip, (0.58 - T * 0.12) * Scale, (1.02 + T * 0.30) * Scale, (0.08 + T * 0.06) * Scale, 0.86)
    end
end

function CreateAngelWingEffects(Pivot, Side, Scale)
    local Aura = Instance.new("Attachment")
    Aura.Name = "WingAura"
    Aura.Position = Vector3.new(Side * 0.42 * Scale, 0.32 * Scale, 0.10 * Scale)
    Aura.Parent = Pivot
    local Emitter = Instance.new("ParticleEmitter")
    Emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
    Emitter.Color = ColorSequence.new(Configuration.AngelWings.CoreColor, Configuration.AngelWings.GlowColor)
    Emitter.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.58), NumberSequenceKeypoint.new(0.62, 0.78), NumberSequenceKeypoint.new(1, 1)})
    Emitter.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.045), NumberSequenceKeypoint.new(0.42, 0.11), NumberSequenceKeypoint.new(1, 0)})
    Emitter.Lifetime = NumberRange.new(0.55, 0.95)
    Emitter.Rate = 2
    Emitter.Speed = NumberRange.new(0.08, 0.30)
    Emitter.SpreadAngle = Vector2.new(70, 70)
    Emitter.Rotation = NumberRange.new(0, 360)
    Emitter.RotSpeed = NumberRange.new(-35, 35)
    Emitter.Drag = 2.5
    Emitter.Acceleration = Vector3.new(0, 0.28, 0)
    Emitter.VelocityInheritance = 0.12
    Emitter.LightEmission = 0.92
    Emitter.LightInfluence = 0
    Emitter.Brightness = 0.85
    Emitter.Parent = Aura
    Configuration.AngelWings.Emitters[#Configuration.AngelWings.Emitters + 1] = Emitter
    local TrailFeather
    for Index = #Configuration.AngelWings.Feathers, 1, -1 do
        local Feather = Configuration.AngelWings.Feathers[Index]
        if Feather and Feather.Side == Side and Feather.Layer == "Primary" and Feather.Index == Feather.Count and Feather.Tip and Feather.TrailTip then
            TrailFeather = Feather
            break
        end
    end
    if TrailFeather then
        local Trail = Instance.new("Trail")
        Trail.Name = "WingTipTrail"
        Trail.Attachment0 = TrailFeather.Tip
        Trail.Attachment1 = TrailFeather.TrailTip
        Trail.FaceCamera = true
        Trail.Lifetime = 0.065
        Trail.MinLength = 0.025
        Trail.LightEmission = 0.86
        Trail.LightInfluence = 0
        Trail.Color = ColorSequence.new(Configuration.AngelWings.GlowColor, Configuration.AngelWings.CoreColor)
        Trail.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.76), NumberSequenceKeypoint.new(0.45, 0.88), NumberSequenceKeypoint.new(1, 1)})
        Trail.WidthScale = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.24), NumberSequenceKeypoint.new(1, 0)})
        Trail.Parent = Pivot
        Configuration.AngelWings.Trails[#Configuration.AngelWings.Trails + 1] = Trail
    end
end

function UpdateAngelWingAppearance()
    local Transparency = AngelWingClamp(Configuration.AngelWings.Transparency, 0, 0.92)
    local Core = Configuration.AngelWings.CoreColor
    local Glow = Configuration.AngelWings.GlowColor
    for _, Beam in ipairs(Configuration.AngelWings.Beams) do
        if Beam and Beam.Parent then
            if Beam.Name:find("Edge_", 1, true) then
                Beam.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, Glow), ColorSequenceKeypoint.new(0.52, Core), ColorSequenceKeypoint.new(1, Glow)})
                Beam.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.55, 0, 0.95)), NumberSequenceKeypoint.new(0.72, AngelWingClamp(Transparency + 0.68, 0, 0.98)), NumberSequenceKeypoint.new(1, 1)})
            elseif Beam.Name:find("Vein_", 1, true) then
                Beam.Color = ColorSequence.new(Glow, Core)
                Beam.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.18, 0, 0.90)), NumberSequenceKeypoint.new(0.80, AngelWingClamp(Transparency + 0.42, 0, 0.96)), NumberSequenceKeypoint.new(1, 1)})
            elseif Beam.Name:find("Spine_", 1, true) then
                Beam.Color = ColorSequence.new(Glow, Core)
                Beam.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.16, 0, 0.90)), NumberSequenceKeypoint.new(0.72, AngelWingClamp(Transparency + 0.36, 0, 0.95)), NumberSequenceKeypoint.new(1, 0.88)})
            else
                Beam.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, Core), ColorSequenceKeypoint.new(0.68, Core), ColorSequenceKeypoint.new(1, Glow)})
                Beam.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, Transparency), NumberSequenceKeypoint.new(0.72, AngelWingClamp(Transparency + 0.12, 0, 0.94)), NumberSequenceKeypoint.new(1, AngelWingClamp(Transparency + 0.62, 0, 0.98))})
            end
        end
    end
    for _, Emitter in ipairs(Configuration.AngelWings.Emitters) do
        if Emitter and Emitter.Parent then
            Emitter.Color = ColorSequence.new(Core, Glow)
            Emitter.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.42, 0, 0.94)), NumberSequenceKeypoint.new(0.62, AngelWingClamp(Transparency + 0.62, 0, 0.98)), NumberSequenceKeypoint.new(1, 1)})
        end
    end
    for _, Trail in ipairs(Configuration.AngelWings.Trails) do
        if Trail and Trail.Parent then
            Trail.Color = ColorSequence.new(Glow, Core)
            Trail.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, AngelWingClamp(Transparency + 0.50, 0, 0.96)), NumberSequenceKeypoint.new(0.55, AngelWingClamp(Transparency + 0.68, 0, 0.98)), NumberSequenceKeypoint.new(1, 1)})
        end
    end
end

function CreateAngelWings(Character)
    Character = Character or LocalPlayer.Character
    local CurrentTime = os.clock()
    if CurrentTime < (tonumber(Configuration.AngelWings.NextBuildAt) or 0) then return false end
    Configuration.AngelWings.NextBuildAt = CurrentTime + 0.22
    if not Character then return false end
    local Torso = Character:FindFirstChild("Torso")
    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Torso or not Humanoid or Humanoid.RigType ~= Enum.HumanoidRigType.R6 then return false end
    DestroyAngelWingModel()
    local Model = Instance.new("Model")
    Model.Name = "AtramentaCosmeticWings"
    Model.Parent = Character
    local LeftPivot, LeftMotor = CreateAngelWingPivot(Torso, Model, -1)
    local RightPivot, RightMotor = CreateAngelWingPivot(Torso, Model, 1)
    local Scale = AngelWingClamp(tonumber(Configuration.AngelWings.Scale) or 1.18, 0.65, 1.90)
    CreateAngelWingSide(LeftPivot, -1, Scale)
    CreateAngelWingSide(RightPivot, 1, Scale)
    CreateAngelWingEffects(LeftPivot, -1, Scale)
    CreateAngelWingEffects(RightPivot, 1, Scale)
    Configuration.AngelWings.Model = Model
    Configuration.AngelWings.LeftMotor = LeftMotor
    Configuration.AngelWings.RightMotor = RightMotor
    Configuration.AngelWings.Phase = 0
    Configuration.AngelWings.PreviousStroke = -1
    Configuration.AngelWings.StrokeVelocity = 0
    Configuration.AngelWings.CurrentActivity = 0.54
    Configuration.AngelWings.FeatherAccumulator = 0
    Configuration.AngelWings.FeatherBatchIndex = 1
    Configuration.AngelWings.EmitterAccumulator = 0
    Configuration.AngelWings.RuntimeAccumulator = 0
    Configuration.AngelWings.CachedCharacter = Character
    Configuration.AngelWings.CachedHumanoid = Humanoid
    Configuration.AngelWings.CachedRootPart = Character:FindFirstChild("HumanoidRootPart")
    Configuration.AngelWings.Ragdolled = false
    Configuration.AngelWings.RecoverUntil = 0
    Configuration.AngelWings.LastRagdollCharacter = nil
    Configuration.AngelWings.RagdollHoldUntil = math.min(tonumber(Configuration.AngelWings.RagdollHoldUntil) or 0, os.clock())
    UpdateAngelWingAppearance()
    Configuration.AngelWings.NextBuildAt = 0
    Configuration.AngelWings.NextRagdollScan = 0
    return true
end

function UpdateAngelWingFeathers(Phase, Activity)
    local Feathers = Configuration.AngelWings.Feathers
    local Count = #Feathers
    if Count == 0 then return end
    local StartIndex = Configuration.AngelWings.FeatherBatchIndex
    local EndIndex = math.min(StartIndex + Configuration.AngelWings.FeatherBatchSize - 1, Count)
    for Index = StartIndex, EndIndex do
        local Feather = Feathers[Index]
        if Feather and Feather.Tip and Feather.Tip.Parent then
            local Delay = Feather.Progress * 0.28 + Feather.Weight * 0.055
            local Stroke = AngelWingStableStroke(select(1, GetAngelWingStroke(Phase - Delay)))
            local Wave = math.sin(Phase * 1.35 + Feather.Offset)
            local Fine = math.sin(Phase * 2.15 + Feather.Offset * 1.46)
            local Base = Feather.TipPosition
            local Span = 1 - (1 - Stroke) * 0.014 * Feather.Weight
            local Lift = Stroke * (0.08 + Feather.Progress * 0.24) * Feather.Weight
            local Sweep = -Stroke * (0.10 + Feather.Progress * 0.26) * Feather.Weight
            local Tip = Vector3.new(Base.X * Span, Base.Y + Lift, Base.Z + Sweep)
            Tip += Vector3.new(0, Wave * Feather.Flutter * (0.32 + Activity * 0.22), Fine * Feather.Flutter * 0.24)
            local Direction = Tip - Feather.RootPosition
            local Normal = Vector3.new(0, 1, Feather.Side * (0.16 + Fine * 0.035))
            local Tangent = Direction + Vector3.new(0, -Feather.Curve * 0.20, Feather.Side * Wave * Feather.Flutter * 0.12)
            if not Feather.LastTip or (Tip - Feather.LastTip).Magnitude > 0.0018 then
                local TipFrame = AngelWingFrame(Tip, Tangent, Normal)
                Feather.Tip.CFrame = TipFrame
                if Feather.TrailTip and Feather.TrailTip.Parent then
                    Feather.TrailTip.CFrame = TipFrame * CFrame.new(0, math.max(tonumber(Feather.TrailOffset) or 0.045, 0.025), 0)
                end
                Feather.LastTip = Tip
            end
            local Curve0 = Feather.Curve * AngelWingClamp(1 + Stroke * 0.045 * Feather.Weight + Fine * 0.012, 0.90, 1.10)
            local Curve1 = Feather.Curve * 0.46 * AngelWingClamp(1 - Stroke * 0.035 * Feather.Weight, 0.92, 1.08)
            if math.abs(Curve0 - (Feather.LastCurve0 or Curve0)) > 0.0015 or math.abs(Curve1 - (Feather.LastCurve1 or Curve1)) > 0.0015 then
                Feather.MainBeam.CurveSize0 = Curve0
                Feather.MainBeam.CurveSize1 = Curve1
                Feather.EdgeBeam.CurveSize0 = Curve0
                Feather.EdgeBeam.CurveSize1 = Curve1
                Feather.VeinBeam.CurveSize0 = Curve0 * 0.94
                Feather.VeinBeam.CurveSize1 = Curve1 * 0.92
                Feather.LastCurve0 = Curve0
                Feather.LastCurve1 = Curve1
            end
        end
    end
    Configuration.AngelWings.FeatherBatchIndex = EndIndex >= Count and 1 or EndIndex + 1
end

function UpdateAngelWings(DeltaTime)
    if not Configuration.AngelWings.Enabled then return end
    DeltaTime = AngelWingClamp(tonumber(DeltaTime) or 0.016, 0.001, 0.05)
    Configuration.AngelWings.RuntimeAccumulator = (tonumber(Configuration.AngelWings.RuntimeAccumulator) or 0) + DeltaTime
    local RuntimeInterval = tonumber(Configuration.AngelWings.RuntimeInterval) or 1 / 45
    if Configuration.AngelWings.RuntimeAccumulator < RuntimeInterval then return end
    DeltaTime = math.min(Configuration.AngelWings.RuntimeAccumulator, 0.05)
    Configuration.AngelWings.RuntimeAccumulator = 0
    local Character = LocalPlayer.Character
    if not Character then DestroyAngelWingModel(); return end
    if not Configuration.AngelWings.Model or Configuration.AngelWings.Model.Parent ~= Character then CreateAngelWings(Character); return end
    local Humanoid = Configuration.AngelWings.CachedHumanoid
    local RootPart = Configuration.AngelWings.CachedRootPart
    if Configuration.AngelWings.CachedCharacter ~= Character or not Humanoid or Humanoid.Parent ~= Character or not RootPart or RootPart.Parent ~= Character then
        Humanoid = Character:FindFirstChildOfClass("Humanoid")
        RootPart = Character:FindFirstChild("HumanoidRootPart")
        Configuration.AngelWings.CachedCharacter = Character
        Configuration.AngelWings.CachedHumanoid = Humanoid
        Configuration.AngelWings.CachedRootPart = RootPart
    end
    local LeftMotor = Configuration.AngelWings.LeftMotor
    local RightMotor = Configuration.AngelWings.RightMotor
    if not Humanoid or not RootPart or not LeftMotor or not RightMotor or not LeftMotor.Parent or not RightMotor.Parent then CreateAngelWings(Character); return end
    local Ragdolled = IsAngelWingGameRagdolled(Character, Humanoid)
    if Ragdolled then
        Configuration.AngelWings.Ragdolled = true
        Configuration.AngelWings.LastRagdollCharacter = Character
        Configuration.AngelWings.RecoverUntil = os.clock() + Configuration.AngelWings.RecoverDelay
        FreezeAngelWingsForRagdoll()
        return
    end
    if Configuration.AngelWings.Ragdolled == true then
        if os.clock() < (tonumber(Configuration.AngelWings.RecoverUntil) or 0) then FreezeAngelWingsForRagdoll(); return end
        Configuration.AngelWings.Ragdolled = false
        Configuration.AngelWings.LastRagdollCharacter = nil
        if not RecoverAngelWingsFromRagdoll(Character) then return end
        LeftMotor = Configuration.AngelWings.LeftMotor
        RightMotor = Configuration.AngelWings.RightMotor
        if not LeftMotor or not RightMotor then return end
    end
    Configuration.AngelWings.ValidationAccumulator = (tonumber(Configuration.AngelWings.ValidationAccumulator) or 0) + DeltaTime
    if Configuration.AngelWings.ValidationAccumulator >= Configuration.AngelWings.ValidationInterval then
        Configuration.AngelWings.ValidationAccumulator = 0
        local Models = 0
        for _, Object in ipairs(Character:GetChildren()) do
            if Object:IsA("Model") and Object.Name == "AtramentaCosmeticWings" then Models += 1 end
        end
        if Models ~= 1 or not LeftMotor.Part0 or not LeftMotor.Part1 or not RightMotor.Part0 or not RightMotor.Part1 then CreateAngelWings(Character); return end
    end
    local Movement = Humanoid.MoveDirection.Magnitude
    local State = Humanoid:GetState()
    local Airborne = State == Enum.HumanoidStateType.Jumping or State == Enum.HumanoidStateType.Freefall
    local TargetActivity = Configuration.AngelWings.Reactive and (0.48 + Movement * 0.18 + (Airborne and 0.22 or 0)) or 0.54
    TargetActivity = AngelWingClamp(TargetActivity, 0.44, 0.92)
    Configuration.AngelWings.CurrentActivity = AngelWingLerp(Configuration.AngelWings.CurrentActivity, TargetActivity, AngelWingExpAlpha(4.2, DeltaTime))
    local Activity = Configuration.AngelWings.CurrentActivity
    Configuration.AngelWings.Phase += DeltaTime * Configuration.AngelWings.FlapSpeed * (0.68 + Activity * 0.38) * math.pi * 2
    local Phase = Configuration.AngelWings.Phase
    local Stroke, Downstroke, Cycle = GetAngelWingStroke(Phase)
    local StableStroke = AngelWingStableStroke(Stroke)
    local Velocity = (StableStroke - Configuration.AngelWings.PreviousStroke) / DeltaTime
    Configuration.AngelWings.PreviousStroke = StableStroke
    Configuration.AngelWings.StrokeVelocity = AngelWingLerp(Configuration.AngelWings.StrokeVelocity, AngelWingClamp(Velocity, -8, 8), AngelWingExpAlpha(8, DeltaTime))
    local Vertical = AngelWingClamp(RootPart.AssemblyLinearVelocity.Y * 0.035, -3.5, 3.5)
    local Breath = math.sin(Cycle * math.pi * 2) * 1.4
    local Roll = 15 + StableStroke * (17 + Activity * 5)
    local Pitch = -7 - (Downstroke and 2.5 or -1.5) * Activity - Vertical * 0.18 + Breath
    local Sweep = 11 + (1 - Activity) * 4 - StableStroke * 3.5
    local LeftTarget = CFrame.Angles(math.rad(Pitch), math.rad(-Sweep), math.rad(-Roll))
    local RightTarget = CFrame.Angles(math.rad(Pitch), math.rad(Sweep), math.rad(Roll))
    local Alpha = AngelWingExpAlpha(8.5, DeltaTime)
    LeftMotor.Transform = LeftMotor.Transform:Lerp(LeftTarget, Alpha)
    RightMotor.Transform = RightMotor.Transform:Lerp(RightTarget, Alpha)
    Configuration.AngelWings.FeatherAccumulator += DeltaTime
    if Configuration.AngelWings.FeatherAccumulator >= Configuration.AngelWings.FeatherInterval then
        Configuration.AngelWings.FeatherAccumulator %= Configuration.AngelWings.FeatherInterval
        UpdateAngelWingFeathers(Phase, Activity)
    end
    local Energy = AngelWingClamp(math.abs(Configuration.AngelWings.StrokeVelocity) / 8, 0, 1)
    Configuration.AngelWings.EmitterAccumulator += DeltaTime
    if Configuration.AngelWings.EmitterAccumulator >= Configuration.AngelWings.EmitterInterval then
        Configuration.AngelWings.EmitterAccumulator %= Configuration.AngelWings.EmitterInterval
        for _, Emitter in ipairs(Configuration.AngelWings.Emitters) do
            if Emitter and Emitter.Parent then
                Emitter.Rate = 1.5 + Energy * 3.5
                Emitter.Speed = NumberRange.new(0.06 + Energy * 0.08, 0.24 + Energy * 0.28)
            end
        end
        for _, Trail in ipairs(Configuration.AngelWings.Trails) do
            if Trail and Trail.Parent then Trail.Lifetime = 0.045 + Energy * 0.045 end
        end
    end
end

function RebuildAngelWings()
    if not Configuration.AngelWings.Enabled then return end
    Configuration.AngelWings.NextBuildAt = 0
    CreateAngelWings(LocalPlayer.Character)
end

function ToggleAngelWings(Enabled)
    Configuration.AngelWings.Enabled = Enabled == true
    Configuration.AngelWings.BuildGeneration = (tonumber(Configuration.AngelWings.BuildGeneration) or 0) + 1
    if Configuration.AngelWings.Enabled then
        if not Configuration.AngelWings.RenderConnection then
            Configuration.AngelWings.RenderConnection = RunService.Heartbeat:Connect(function(DeltaTime)
                Internal.Call(UpdateAngelWings, DeltaTime)
            end)
        end
        if not Configuration.AngelWings.CharacterConnection then
            Configuration.AngelWings.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
                Configuration.AngelWings.RagdollHoldUntil = 0
                Configuration.AngelWings.Ragdolled = false
                Configuration.AngelWings.RecoverUntil = 0
                Configuration.AngelWings.LastRagdollCharacter = nil
                Configuration.AngelWings.RagdollSwitch = nil
                Configuration.AngelWings.RagdollSwitchCharacter = nil
                Configuration.AngelWings.BuildGeneration = (tonumber(Configuration.AngelWings.BuildGeneration) or 0) + 1
                local Generation = Configuration.AngelWings.BuildGeneration
                task.spawn(function()
                    task.wait(0.65)
                    if Configuration.AngelWings.Enabled and Generation == Configuration.AngelWings.BuildGeneration and Character == LocalPlayer.Character then
                        Configuration.AngelWings.NextBuildAt = 0
                        CreateAngelWings(Character)
                    end
                end)
            end)
        end
        Configuration.AngelWings.NextBuildAt = 0
        CreateAngelWings(LocalPlayer.Character)
    else
        if Configuration.AngelWings.RenderConnection then Configuration.AngelWings.RenderConnection:Disconnect(); Configuration.AngelWings.RenderConnection = nil end
        if Configuration.AngelWings.CharacterConnection then Configuration.AngelWings.CharacterConnection:Disconnect(); Configuration.AngelWings.CharacterConnection = nil end
        DestroyAngelWingModel()
    end
end

function DestroyDemonCosmetics()
    local Demon = Configuration.Demon

    if Demon.Folder and Demon.Folder.Parent then
        Demon.Folder:Destroy()
    end

    for Index = #Demon.Attachments, 1, -1 do
        local Attachment = Demon.Attachments[Index]
        if Attachment and Attachment.Parent then
            Attachment:Destroy()
        end
        Demon.Attachments[Index] = nil
    end

    table.clear(Demon.CoreBeams)
    table.clear(Demon.GlowBeams)
    table.clear(Demon.HornAttachments)
    table.clear(Demon.TailAttachments)
    table.clear(Demon.SpikeAttachments)
    table.clear(Demon.SpadeAttachments)
    table.clear(Demon.TailBeams)
    table.clear(Demon.SpikeBeams)
    table.clear(Demon.SpadeBeams)

    Demon.Folder = nil
    Demon.Character = nil
    Demon.Head = nil
    Demon.RootPart = nil
end

function CreateDemonAttachment(Parent, Name, Position)
    local Attachment = Instance.new("Attachment")
    Attachment.Name = Name
    Attachment.Position = Position or Vector3.zero
    Attachment.Parent = Parent
    Configuration.Demon.Attachments[#Configuration.Demon.Attachments + 1] = Attachment
    return Attachment
end

function IsDemonBeamRoleEnabled(Role)
    local Demon = Configuration.Demon

    if Role == "Horn" then
        return Demon.Horns == true
    elseif Role == "Tail" or Role == "Spade" then
        return Demon.Tail == true
    elseif Role == "Spike" then
        return Demon.Tail == true and Demon.Spikes == true
    end

    return true
end

function CreateDemonBeam(Parent, Attachment0, Attachment1, Width0, Width1, Role)
    local Demon = Configuration.Demon
    local Beam = Instance.new("Beam")
    Beam.Name = "AtramentaDemon" .. tostring(Role or "Core")
    Beam.Attachment0 = Attachment0
    Beam.Attachment1 = Attachment1
    Beam.FaceCamera = true
    Beam.Segments = 1
    Beam.Width0 = Width0
    Beam.Width1 = Width1
    Beam.LightEmission = 0.72
    Beam.LightInfluence = 0
    Beam.Color = ColorSequence.new(Demon.Color)
    Beam.Transparency = NumberSequence.new(Demon.Transparency)
    Beam.ZOffset = 0.02
    Beam.Enabled = IsDemonBeamRoleEnabled(Role)
    Beam:SetAttribute("AtramentaDemonRole", tostring(Role or "Core"))
    Beam.Parent = Parent
    Demon.CoreBeams[#Demon.CoreBeams + 1] = Beam

    local GlowBeam = Instance.new("Beam")
    GlowBeam.Name = "AtramentaDemonGlow"
    GlowBeam.Attachment0 = Attachment0
    GlowBeam.Attachment1 = Attachment1
    GlowBeam.FaceCamera = true
    GlowBeam.Segments = 1
    GlowBeam.Width0 = Width0 * 2.15
    GlowBeam.Width1 = Width1 * 2.15
    GlowBeam.LightEmission = 1
    GlowBeam.LightInfluence = 0
    GlowBeam.Color = ColorSequence.new(Demon.GlowColor)
    GlowBeam.Transparency = NumberSequence.new(math.clamp(0.68 + Demon.Transparency * 0.22, 0, 0.96))
    GlowBeam.ZOffset = -0.02
    GlowBeam.Enabled = Demon.Glow == true and IsDemonBeamRoleEnabled(Role)
    GlowBeam:SetAttribute("AtramentaDemonRole", tostring(Role or "Core"))
    GlowBeam.Parent = Parent
    Demon.GlowBeams[#Demon.GlowBeams + 1] = GlowBeam

    return Beam, GlowBeam
end

function UpdateDemonAppearance()
    local Demon = Configuration.Demon
    local CoreTransparency = math.clamp(tonumber(Demon.Transparency) or 0.08, 0, 0.92)
    local GlowTransparency = math.clamp(0.68 + CoreTransparency * 0.22, 0, 0.96)

    for _, Beam in ipairs(Demon.CoreBeams) do
        if Beam and Beam.Parent then
            local Role = Beam:GetAttribute("AtramentaDemonRole")
            Beam.Color = ColorSequence.new(Demon.Color)
            Beam.Transparency = NumberSequence.new(CoreTransparency)
            Beam.Enabled = IsDemonBeamRoleEnabled(Role)
        end
    end

    for _, Beam in ipairs(Demon.GlowBeams) do
        if Beam and Beam.Parent then
            local Role = Beam:GetAttribute("AtramentaDemonRole")
            Beam.Color = ColorSequence.new(Demon.GlowColor)
            Beam.Transparency = NumberSequence.new(GlowTransparency)
            Beam.Enabled = Demon.Glow == true and IsDemonBeamRoleEnabled(Role)
        end
    end
end

function BuildDemonHorns(Head, Folder)
    local Demon = Configuration.Demon
    local SegmentCount = 8
    local Scale = Demon.Scale * Demon.HornScale

    for SideIndex, Side in ipairs({-1, 1}) do
        local Horn = {}

        for Segment = 0, SegmentCount do
            local Alpha = Segment / SegmentCount
            local SideDistance = (0.36 + math.sin(Alpha * 1.8) * 1.02) * Side * Scale
            local Height = (0.46 + Alpha * 1.62 - Alpha ^ 2.2 * 0.42) * Scale
            local Back = (-0.08 + Alpha ^ 1.8 * 1.06) * Scale

            Horn[Segment + 1] = CreateDemonAttachment(
                Head,
                "AtramentaDemonHorn" .. tostring(SideIndex) .. "_" .. tostring(Segment),
                Vector3.new(SideDistance, Height, Back)
            )
        end

        Demon.HornAttachments[SideIndex] = Horn

        for Segment = 1, SegmentCount do
            local Alpha0 = (Segment - 1) / SegmentCount
            local Alpha1 = Segment / SegmentCount
            local Width0 = math.max(0.035, (0.22 * (1 - Alpha0 * 0.84)) * Scale * Demon.Thickness)
            local Width1 = math.max(0.025, (0.22 * (1 - Alpha1 * 0.84)) * Scale * Demon.Thickness)

            local Beam, GlowBeam = CreateDemonBeam(
                Folder,
                Horn[Segment],
                Horn[Segment + 1],
                Width0,
                Width1,
                "Horn"
            )

            Beam.Enabled = Demon.Horns == true
            GlowBeam.Enabled = Demon.Horns == true and Demon.Glow == true
        end
    end
end

function BuildDemonTail(RootPart, Folder)
    local Demon = Configuration.Demon
    local SegmentCount = math.clamp(math.floor(tonumber(Demon.TailSegments) or 18), 10, 28)

    for Segment = 0, SegmentCount do
        Demon.TailAttachments[Segment + 1] = CreateDemonAttachment(
            RootPart,
            "AtramentaDemonTail" .. tostring(Segment),
            Vector3.zero
        )
    end

    for Segment = 1, SegmentCount do
        local Alpha0 = (Segment - 1) / SegmentCount
        local Alpha1 = Segment / SegmentCount
        local Width0 = math.max(0.035, (0.29 * (1 - Alpha0 * 0.88)) * Demon.Scale * Demon.Thickness)
        local Width1 = math.max(0.025, (0.29 * (1 - Alpha1 * 0.88)) * Demon.Scale * Demon.Thickness)

        local Beam, GlowBeam = CreateDemonBeam(
            Folder,
            Demon.TailAttachments[Segment],
            Demon.TailAttachments[Segment + 1],
            Width0,
            Width1,
            "Tail"
        )

        Beam.Enabled = Demon.Tail == true
        GlowBeam.Enabled = Demon.Tail == true and Demon.Glow == true
        Demon.TailBeams[#Demon.TailBeams + 1] = Beam
    end

    local SpikeCount = 8

    for Index = 1, SpikeCount do
        local TailIndex = math.clamp(
            math.floor(2 + (Index / (SpikeCount + 1)) * (SegmentCount - 3)),
            2,
            SegmentCount
        )

        local SpikeAttachment = CreateDemonAttachment(
            RootPart,
            "AtramentaDemonSpike" .. tostring(Index),
            Vector3.zero
        )

        Demon.SpikeAttachments[Index] = {
            Attachment = SpikeAttachment,
            TailIndex = TailIndex
        }

        local Beam, GlowBeam = CreateDemonBeam(
            Folder,
            Demon.TailAttachments[TailIndex],
            SpikeAttachment,
            0.075 * Demon.Scale * Demon.Thickness,
            0.018,
            "Spike"
        )

        Beam.Enabled = Demon.Tail == true and Demon.Spikes == true
        GlowBeam.Enabled = Demon.Tail == true and Demon.Spikes == true and Demon.Glow == true
        Demon.SpikeBeams[#Demon.SpikeBeams + 1] = Beam
    end

    local SpadeNames = {"Base", "Left", "Right", "Top", "Bottom", "Apex"}

    for Index, Name in ipairs(SpadeNames) do
        Demon.SpadeAttachments[Index] = CreateDemonAttachment(
            RootPart,
            "AtramentaDemonSpade" .. Name,
            Vector3.zero
        )
    end

    local SpadePairs = {
        {1, 2},
        {2, 6},
        {6, 3},
        {3, 1},
        {4, 6},
        {5, 6}
    }

    for _, Pair in ipairs(SpadePairs) do
        local Beam, GlowBeam = CreateDemonBeam(
            Folder,
            Demon.SpadeAttachments[Pair[1]],
            Demon.SpadeAttachments[Pair[2]],
            0.055 * Demon.Scale * Demon.Thickness,
            0.032 * Demon.Scale * Demon.Thickness,
            "Spade"
        )

        Beam.Enabled = Demon.Tail == true
        GlowBeam.Enabled = Demon.Tail == true and Demon.Glow == true
        Demon.SpadeBeams[#Demon.SpadeBeams + 1] = Beam
    end
end

function UpdateDemonTail(Time)
    local Demon = Configuration.Demon
    local Attachments = Demon.TailAttachments
    local SegmentCount = #Attachments - 1

    if SegmentCount < 2 then return end

    local Scale = Demon.Scale
    local SegmentLength = (Demon.TailLength * Scale) / SegmentCount
    local Speed = Time * Demon.SwaySpeed
    local Sway = Demon.SwayStrength * Scale
    local Position = Vector3.new(0, -0.48 * Scale, 0.58 * Scale)
    local Direction = Vector3.new(0, -0.34, 0.94).Unit
    local Positions = table.create(SegmentCount + 1)

    Positions[1] = Position
    Attachments[1].Position = Position

    for Segment = 1, SegmentCount do
        local Alpha = Segment / SegmentCount
        local Side = math.sin(Speed - Alpha * 3.45) * (0.14 + Alpha * 0.54) * Sway
        local Vertical = math.cos(Speed * 0.82 - Alpha * 2.65) * (0.07 + Alpha * 0.22) * Sway
        local Arch = math.sin(Alpha * math.pi) * 0.30 * Scale

        local SegmentDirection = (
            Direction
            + Vector3.new(
                Side,
                Vertical + Arch * 0.16,
                0
            )
        ).Unit

        Position += SegmentDirection * SegmentLength
        Positions[Segment + 1] = Position
        Attachments[Segment + 1].Position = Position
    end

    for Index, SpikeData in ipairs(Demon.SpikeAttachments) do
        local TailIndex = math.clamp(SpikeData.TailIndex, 2, SegmentCount)
        local PositionIndex = math.clamp(TailIndex, 1, #Positions)
        local BasePosition = Positions[PositionIndex]
        local Alpha = PositionIndex / #Positions
        local SideWave = math.sin(Speed - Alpha * 3.45)
        local SpikeHeight = Demon.SpikeHeight * Scale * (1 - Alpha * 0.52)

        SpikeData.Attachment.Position = BasePosition + Vector3.new(
            SideWave * 0.05 * Scale,
            SpikeHeight,
            -0.03 * Scale
        )
    end

    local PreviousPosition = Positions[SegmentCount]
    local TipPosition = Positions[SegmentCount + 1]
    local Tangent = TipPosition - PreviousPosition

    if Tangent.Magnitude < 0.001 then
        Tangent = Vector3.new(0, 0, 1)
    else
        Tangent = Tangent.Unit
    end

    local Right = Vector3.new(1, 0, 0)
    local Up = Vector3.new(0, 1, 0)
    local Width = 0.34 * Scale
    local Height = 0.30 * Scale
    local Length = 0.58 * Scale
    local Base = TipPosition - Tangent * 0.05 * Scale
    local Apex = TipPosition + Tangent * Length

    Demon.SpadeAttachments[1].Position = Base
    Demon.SpadeAttachments[2].Position = TipPosition - Right * Width + Up * 0.06 * Scale
    Demon.SpadeAttachments[3].Position = TipPosition + Right * Width + Up * 0.06 * Scale
    Demon.SpadeAttachments[4].Position = TipPosition + Up * Height
    Demon.SpadeAttachments[5].Position = TipPosition - Up * Height * 0.78
    Demon.SpadeAttachments[6].Position = Apex
end

function UpdateDemonCosmetics(DeltaTime)
    local Demon = Configuration.Demon

    if not Demon.Enabled then return end

    Demon.RuntimeAccumulator += math.clamp(DeltaTime, 0, 0.05)

    if Demon.RuntimeAccumulator < Demon.RuntimeInterval then
        return
    end

    Demon.RuntimeAccumulator = 0

    local Character = LocalPlayer.Character

    if not Character then
        DestroyDemonCosmetics()
        return
    end

    if Demon.Character ~= Character
        or not Demon.Folder
        or not Demon.Folder.Parent
        or not Demon.Head
        or not Demon.Head.Parent
        or not Demon.RootPart
        or not Demon.RootPart.Parent
    then
        CreateDemonCosmetics(Character)
        return
    end

    if Demon.Tail then
        UpdateDemonTail(os.clock())
    end
end

function CreateDemonCosmetics(Character)
    local Demon = Configuration.Demon

    if not Demon.Enabled or not Character then
        DestroyDemonCosmetics()
        return
    end

    local Head = Character:FindFirstChild("Head")
    local RootPart = Character:FindFirstChild("HumanoidRootPart")

    if not Head or not RootPart then
        return
    end

    DestroyDemonCosmetics()

    local Folder = Instance.new("Folder")
    Folder.Name = "AtramentaDemonCosmetics"
    Folder.Parent = Character

    Demon.Folder = Folder
    Demon.Character = Character
    Demon.Head = Head
    Demon.RootPart = RootPart

    BuildDemonHorns(Head, Folder)
    BuildDemonTail(RootPart, Folder)
    UpdateDemonTail(os.clock())
    UpdateDemonAppearance()
end

function RebuildDemonCosmetics()
    if not Configuration.Demon.Enabled then return end
    CreateDemonCosmetics(LocalPlayer.Character)
end

function ToggleDemonCosmetics(Enabled)
    local Demon = Configuration.Demon
    Demon.Enabled = Enabled == true

    if Demon.Enabled then
        if not Demon.Connection then
            Demon.Connection = RunService.Heartbeat:Connect(function(DeltaTime)
                Internal.Call(UpdateDemonCosmetics, DeltaTime)
            end)
        end

        CreateDemonCosmetics(LocalPlayer.Character)
    else
        if Demon.Connection then
            Demon.Connection:Disconnect()
            Demon.Connection = nil
        end

        DestroyDemonCosmetics()
    end
end

function GetAimFOVAnchorPosition()
    local CameraObject = Internal.GetCamera()

    if Configuration.AimBot.SilentEnabled then
        local MousePosition = UserInputService:GetMouseLocation()

        Configuration.AimBot.FOVPosition = MousePosition

        return MousePosition, true
    end

    if CameraObject then
        local CenterPosition = CameraObject.ViewportSize * 0.5

        Configuration.AimBot.FOVPosition = CenterPosition

        return CenterPosition, false
    end

    local Fallback = Configuration.AimBot.FOVPosition or Vector2.new(500, 500)

    return Fallback, false
end

function RemoveAimFOVCircle()
    local Circle = Configuration.AimBot.FOVCircle

    if Circle then
        Internal.Call(function()
            Circle.Visible = false
            Circle:Remove()
        end)
    end

    if type(Configuration.AimBot.FOVGlowCircles) == "table" then
        for _, GlowCircle in ipairs( Configuration.AimBot.FOVGlowCircles ) do
            if GlowCircle then
                Internal.Call( function()
                        GlowCircle.Visible = false
                        GlowCircle:Remove()
                    end)
            end
        end
    end

    if Configuration.AimBot.FOVGlowCircle then
        Internal.Call(function()
            Configuration.AimBot.FOVGlowCircle.Visible = false
            Configuration.AimBot.FOVGlowCircle:Remove()
        end)
    end

    Configuration.AimBot.FOVCircle = nil
    Configuration.AimBot.FOVGlowCircle = nil
    Configuration.AimBot.FOVGlowCircles = {}
end

function CreateAimFOVDrawingCircle(Color, Thickness, Transparency)
    local Success, Circle = Internal.Call( Drawing.new, "Circle")

    if not Success or not Circle then return nil end

    Circle.Color = Color Circle.Filled = false
    Circle.Thickness = Thickness
    Circle.Transparency = Transparency
    Circle.Radius = Configuration.AimBot.FOV
    Circle.NumSides = 72

    return Circle
end

function CreateAimFOVGlow(Position, Visible)
    Configuration.AimBot.FOVGlowCircles = {}

    if not Configuration.AimBot.FOVGlow then return end

    local BaseThickness = math.clamp( tonumber(Configuration.AimBot.FOVGlowThickness) or 8, 3, 24)

    local BaseTransparency = math.clamp( tonumber(Configuration.AimBot.FOVGlowTransparency) or 0.18, 0, 1)

    local Layers = { { 2.15, 0.28 }, { 1.55, 0.52 }, { 1.05, 0.82 } }

    for Index, Layer in ipairs(Layers) do
        local GlowCircle = CreateAimFOVDrawingCircle( Configuration.AimBot.FOVGlowColor, math.max( BaseThickness * Layer[1], 1 ), math.clamp( BaseTransparency * Layer[2], 0, 1 ))

        if GlowCircle then
            GlowCircle.Position = Position
            GlowCircle.Visible = Visible
            Configuration.AimBot.FOVGlowCircles[ Index ] = GlowCircle
        end
    end

    Configuration.AimBot.FOVGlowCircle = Configuration.AimBot.FOVGlowCircles[3]
end

function CreateFOVCircle()
    RemoveAimFOVCircle()

    if not Configuration.AimBot.ShowFOV or not Drawing or type(Drawing.new) ~= "function" then return end

    local Position = GetAimFOVAnchorPosition()

    local Visible = Configuration.AimBot.Enabled and Configuration.AimBot.ShowFOV

    CreateAimFOVGlow( Position, Visible)

    local Circle = CreateAimFOVDrawingCircle( Configuration.AimBot.FOVColor, 2, Configuration.AimBot.FOVTransparency)

    if not Circle then
        RemoveAimFOVCircle()
        return
    end

    Circle.Position = Position
    Circle.Visible = Visible
    Configuration.AimBot.FOVCircle = Circle
end

function UpdateFOVCircle()
    local Circle = Configuration.AimBot.FOVCircle

    if not Circle then return end

    local CameraObject = Internal.GetCamera()

    if not CameraObject then
        Circle.Visible = false

        for _, GlowCircle in ipairs( Configuration.AimBot.FOVGlowCircles or {} ) do
            GlowCircle.Visible = false
        end

        return
    end

    local Position = GetAimFOVAnchorPosition()

    local Visible = Configuration.AimBot.Enabled and Configuration.AimBot.ShowFOV

    Circle.Position = Position
    Circle.Radius = Configuration.AimBot.FOV
    Circle.Color = Configuration.AimBot.FOVColor Circle.Transparency = Configuration.AimBot.FOVTransparency
    Circle.Visible = Visible

    if Configuration.AimBot.FOVGlow and #( Configuration.AimBot.FOVGlowCircles or {} ) == 0 then
        CreateFOVCircle()
        return
    end

    local BaseThickness = math.clamp( tonumber(Configuration.AimBot.FOVGlowThickness) or 8, 3, 24)

    local BaseTransparency = math.clamp( tonumber(Configuration.AimBot.FOVGlowTransparency) or 0.18, 0, 1)

    local Layers = { { 2.15, 0.28 }, { 1.55, 0.52 }, { 1.05, 0.82 } }

    for Index, GlowCircle in ipairs( Configuration.AimBot.FOVGlowCircles or {} ) do
        local Layer = Layers[Index] or Layers[#Layers]

        GlowCircle.Position = Position
        GlowCircle.Radius = Configuration.AimBot.FOV
        GlowCircle.Color = Configuration.AimBot.FOVGlowColor GlowCircle.Thickness = math.max( BaseThickness * Layer[1], 1)
        GlowCircle.Transparency = math.clamp( BaseTransparency * Layer[2], 0, 1)
        GlowCircle.Visible = Visible and Configuration.AimBot.FOVGlow
    end
end

function ResetAimbotTargetLock()
    Configuration.AimBot.AimbotLockedTarget = nil
    Configuration.AimBot.CurrentTarget = nil
    Configuration.AimBot.CachedScanTarget = nil
    Configuration.AimBot.LastTargetScan = 0
    Configuration.AimBot.PositionCacheCharacter = nil
    Configuration.AimBot.PositionCacheValue = nil
end

function ResetSilentAimTargetLock()
    Configuration.AimBot.SilentAimLockedTarget = nil

    if SilentAimController then
        SilentAimController.CachedPart = nil
        SilentAimController.CachedPlayer = nil
        SilentAimController.CachedCharacter = nil
        SilentAimController.CachedAimPosition = nil
    end
end

function ResetAimTargetLock()
    ResetAimbotTargetLock()
    ResetSilentAimTargetLock()
end

if type(HeadHitbox) == "table" then
    if type(HeadHitbox.Stop) == "function" then
        HeadHitbox.Stop()
    elseif type(HeadHitbox.Disable) == "function" then
        HeadHitbox.Disable()
    end
end

HeadHitbox = {
    Enabled = false,
    SafetyMargin = 0.08,
    Runtime = {
        Started = false,
        PlayerAdded = nil,
        PlayerRemoving = nil,
        RenderConnection = nil,
        MaintenanceConnection = nil,
        MaintenanceClock = 0,
        MaintenanceInterval = 0.15,
        Records = setmetatable({}, {__mode = "k"}),
        PlayerConnections = setmetatable({}, {__mode = "k"}),
        PhysicalOriginals = setmetatable({}, {__mode = "k"}),
        PhysicalCharacters = setmetatable({}, {__mode = "k"}),
        PhysicalVisuals = setmetatable({}, {__mode = "k"}),
        PhysicalEnabled = false,
        PhysicalPartName = "Head",
        Edges = { {1, 2}, {1, 3}, {1, 5}, {2, 4}, {2, 6}, {3, 4}, {3, 7}, {4, 8}, {5, 6}, {5, 7}, {6, 8}, {7, 8} }
    }
}

function HeadHitbox.GetEnabled()
    return type(Configuration.HitboxExpander) == "table" and Configuration.HitboxExpander.Enabled == true
end

function HeadHitbox.GetSizeValue()
    local Settings = type(Configuration.HitboxExpander) == "table" and Configuration.HitboxExpander or nil
    return math.clamp(Settings and tonumber(Settings.Size) or 3, 1, 15)
end

function HeadHitbox.GetPhysicalEnabled()
    return HeadHitbox.GetEnabled()
end

function HeadHitbox.GetPhysicalScaleValue()
    return HeadHitbox.GetEnabled() and HeadHitbox.GetSizeValue() or 1
end

function HeadHitbox.GetEffectivePhysicalSize(Head)
    if not Head or not Head:IsA("BasePart") then return nil end

    local Original = HeadHitbox.Runtime.PhysicalOriginals[Head]
    local BaseSize = type(Original) == "table" and typeof(Original.Size) == "Vector3" and Original.Size or Head.Size

    if not HeadHitbox.GetEnabled() then return BaseSize end
    return BaseSize * HeadHitbox.GetSizeValue()
end

function HeadHitbox.GetVisualEnabled()
    local Settings = type(Configuration.HitboxExpander) == "table" and Configuration.HitboxExpander or nil
    return HeadHitbox.GetEnabled() and (not Settings or Settings.Visualize ~= false)
end

function HeadHitbox.GetVirtualSize(Head, Scale)
    if not Head or not Head:IsA("BasePart") then return nil end

    Scale = math.clamp(tonumber(Scale) or HeadHitbox.GetPhysicalScaleValue(), 1, 15)

    local Original = HeadHitbox.Runtime.PhysicalOriginals[Head]
    local BaseSize = type(Original) == "table" and typeof(Original.Size) == "Vector3" and Original.Size or Head.Size

    return BaseSize * Scale
end

function HeadHitbox.GetPhysicalPart(Character)
    if not Character then return nil end

    local Name = HeadHitbox.Runtime.PhysicalPartName or "Head" local Part = Character:FindFirstChild(Name)

    return Part and Part:IsA("BasePart") and Part or nil
end

function HeadHitbox.StorePhysicalOriginal(Part)
    if not Part or not Part:IsA("BasePart") then return nil end

    local Originals = HeadHitbox.Runtime.PhysicalOriginals local Original = Originals[Part]

    if type(Original) ~= "table" then
        Original = {
            Size = Part.Size,
            Massless = Part.Massless,
            Transparency = Part.Transparency,
            LocalTransparencyModifier = Part.LocalTransparencyModifier,
            CanCollide = Part.CanCollide,
            CanTouch = Part.CanTouch,
            CanQuery = Part.CanQuery,
            VisualChildren = setmetatable({}, {__mode = "k"})
        }
        Originals[Part] = Original
    end

    return Original
end

function HeadHitbox.IsPhysicalVisualChild(Object)
    return Object and (Object:IsA("Decal") or Object:IsA("Texture"))
end

function HeadHitbox.RestorePhysicalVisualChildren(Part, Original)
    if type(Original) ~= "table" or type(Original.VisualChildren) ~= "table" then return end

    for Object, Transparency in pairs(Original.VisualChildren) do
        if Object and Object.Parent and Object:IsDescendantOf(Part) and type(Transparency) == "number" then
            Object.Transparency = Transparency
        end
    end
end

function HeadHitbox.SuppressPhysicalVisualChildren(Part, Original)
    if not Part or not Part.Parent or type(Original) ~= "table" then return end

    if type(Original.VisualChildren) ~= "table" then Original.VisualChildren = setmetatable({}, {__mode = "k"}) end

    for _, Object in ipairs(Part:GetDescendants()) do
        if HeadHitbox.IsPhysicalVisualChild(Object) then
            if Original.VisualChildren[Object] == nil then Original.VisualChildren[Object] = Object.Transparency end
            Object.Transparency = 1
        end
    end
end

function HeadHitbox.GetPhysicalVisualSignature(Part)
    if not Part or not Part:IsA("BasePart") then return "" end

    local Values = {Part.ClassName}

    if Part:IsA("MeshPart") then
        Values[#Values + 1] = tostring(Part.MeshId)
        Values[#Values + 1] = tostring(Part.TextureID)
    end

    for _, Object in ipairs(Part:GetDescendants()) do
        if Object:IsA("SpecialMesh") then
            Values[#Values + 1] = Object.ClassName
            Values[#Values + 1] = tostring(Object.MeshId)
            Values[#Values + 1] = tostring(Object.TextureId)
            Values[#Values + 1] = tostring(Object.MeshType)
            Values[#Values + 1] = tostring(Object.Scale)
        elseif Object:IsA("Decal") or Object:IsA("Texture") then
            Values[#Values + 1] = Object.ClassName
            Values[#Values + 1] = Object.Name
            Values[#Values + 1] = tostring(Object.Texture)
            Values[#Values + 1] = tostring(Object.Face)
        elseif Object:IsA("SurfaceAppearance") then
            Values[#Values + 1] = Object.ClassName
            Values[#Values + 1] = tostring(Object.ColorMap)
            Values[#Values + 1] = tostring(Object.NormalMap)
            Values[#Values + 1] = tostring(Object.RoughnessMap)
            Values[#Values + 1] = tostring(Object.MetalnessMap)
        end
    end

    return table.concat(Values, "|")
end

function HeadHitbox.DestroyPhysicalVisual(Part, RestoreSource)
    local Runtime = HeadHitbox.Runtime
    local Entry = Runtime.PhysicalVisuals[Part]

    if type(Entry) == "table" then
        local Clone = Entry.Clone
        if Clone and Clone.Parent then Clone:Destroy() end
    elseif typeof(Entry) == "Instance" and Entry.Parent then
        Entry:Destroy()
    end

    Runtime.PhysicalVisuals[Part] = nil

    if RestoreSource then
        local Original = Runtime.PhysicalOriginals[Part]

        if type(Original) == "table" then
            HeadHitbox.RestorePhysicalVisualChildren(Part, Original)

            if Part and Part.Parent then
                Part.Transparency = Original.Transparency
                Part.LocalTransparencyModifier = Original.LocalTransparencyModifier
            end
        end
    end
end

function HeadHitbox.CreatePhysicalVisual(Part, Original, Signature)
    if not Part or not Part:IsA("BasePart") or not Part.Parent or type(Original) ~= "table" then return nil end

    HeadHitbox.RestorePhysicalVisualChildren(Part, Original)

    local Archivable = Part.Archivable
    if not Archivable then Part.Archivable = true end

    local Success, Clone = Internal.Call(function()
        return Part:Clone()
    end)

    if not Archivable and Part then Part.Archivable = false end
    if not Success or not Clone or not Clone:IsA("BasePart") then
        HeadHitbox.SuppressPhysicalVisualChildren(Part, Original)
        return nil
    end

    for _, Object in ipairs(Clone:GetDescendants()) do
        if Object:IsA("JointInstance")
            or Object:IsA("Constraint")
            or Object:IsA("LuaSourceContainer")
            or Object:IsA("Sound")
            or Object:IsA("ParticleEmitter")
            or Object:IsA("Trail")
            or Object:IsA("Beam")
            or Object:IsA("ProximityPrompt")
            or Object:IsA("ClickDetector")
        then
            Object:Destroy()
        end
    end

    Clone.Name = "AtramentaHeadVisual"
    Clone.Size = Original.Size
    Clone.CFrame = Part.CFrame
    Clone.Anchored = true
    Clone.Massless = true
    Clone.CanCollide = false
    Clone.CanTouch = false
    Clone.CanQuery = false
    Clone.Transparency = Original.Transparency
    Clone.LocalTransparencyModifier = Original.LocalTransparencyModifier
    Clone.Parent = workspace.CurrentCamera or workspace

    HeadHitbox.Runtime.PhysicalVisuals[Part] = {
        Clone = Clone,
        Signature = Signature or HeadHitbox.GetPhysicalVisualSignature(Part)
    }

    HeadHitbox.SuppressPhysicalVisualChildren(Part, Original)
    Part.Transparency = 1
    Part.LocalTransparencyModifier = 0

    return Clone
end

function HeadHitbox.EnsurePhysicalVisual(Part, Original)
    if not Part or not Part.Parent or type(Original) ~= "table" then return nil end

    local Runtime = HeadHitbox.Runtime
    local Signature = HeadHitbox.GetPhysicalVisualSignature(Part)
    local Entry = Runtime.PhysicalVisuals[Part]
    local Clone = type(Entry) == "table" and Entry.Clone or nil

    if not Clone or not Clone.Parent or Entry.Signature ~= Signature then
        HeadHitbox.DestroyPhysicalVisual(Part, false)
        Clone = HeadHitbox.CreatePhysicalVisual(Part, Original, Signature)
    end

    if Clone and Clone.Parent then
        Clone.Size = Original.Size
        Clone.CFrame = Part.CFrame
        Clone.Color = Part.Color
        Clone.Material = Part.Material
        Clone.MaterialVariant = Part.MaterialVariant
        Clone.Reflectance = Part.Reflectance
        Clone.CastShadow = Part.CastShadow
        Clone.Transparency = Original.Transparency
        Clone.LocalTransparencyModifier = Original.LocalTransparencyModifier

        local Parent = workspace.CurrentCamera or workspace
        if Clone.Parent ~= Parent then Clone.Parent = Parent end
    end

    HeadHitbox.SuppressPhysicalVisualChildren(Part, Original)
    Part.Transparency = 1
    Part.LocalTransparencyModifier = 0

    return Clone
end

function HeadHitbox.UpdatePhysicalVisuals()
    local Runtime = HeadHitbox.Runtime

    for Part, Entry in pairs(Runtime.PhysicalVisuals) do
        local Clone = type(Entry) == "table" and Entry.Clone or nil
        local Original = Runtime.PhysicalOriginals[Part]

        if not Part or not Part.Parent or not Clone or not Clone.Parent or type(Original) ~= "table" then
            HeadHitbox.DestroyPhysicalVisual(Part, false)
        else
            Clone.CFrame = Part.CFrame
            Clone.Size = Original.Size
            Clone.Transparency = Original.Transparency
            Clone.LocalTransparencyModifier = Original.LocalTransparencyModifier
        end
    end
end

function HeadHitbox.ApplyPhysicalPart(Part)
    if not Part or not Part:IsA("BasePart") or not Part.Parent then return false end

    local Original = HeadHitbox.StorePhysicalOriginal(Part)
    if not Original then return false end

    local DesiredSize = HeadHitbox.GetEffectivePhysicalSize(Part)
    if typeof(DesiredSize) ~= "Vector3" then return false end

    local Expanded = (DesiredSize - Original.Size).Magnitude > 0.001

    if Expanded then
        HeadHitbox.EnsurePhysicalVisual(Part, Original)
    else
        HeadHitbox.DestroyPhysicalVisual(Part, true)
    end

    Part.Size = DesiredSize
    Part.Massless = true
    Part.CanCollide = false
    Part.CanTouch = false
    Part.CanQuery = true

    if Expanded then
        Part.Transparency = 1
        Part.LocalTransparencyModifier = 0
        HeadHitbox.SuppressPhysicalVisualChildren(Part, Original)
    else
        Part.Transparency = Original.Transparency
        Part.LocalTransparencyModifier = Original.LocalTransparencyModifier
        HeadHitbox.RestorePhysicalVisualChildren(Part, Original)
    end

    return true
end

function HeadHitbox.RestorePhysicalPart(Part)
    if not Part or not Part:IsA("BasePart") then return end

    local Originals = HeadHitbox.Runtime.PhysicalOriginals local Original = Originals[Part]

    if type(Original) ~= "table" then
        HeadHitbox.DestroyPhysicalVisual(Part, false)
        return
    end

    HeadHitbox.DestroyPhysicalVisual(Part, true)

    if Part.Parent then
        Part.Size = Original.Size
        Part.Massless = Original.Massless
        Part.Transparency = Original.Transparency
        Part.LocalTransparencyModifier = Original.LocalTransparencyModifier
        Part.CanCollide = Original.CanCollide
        Part.CanTouch = Original.CanTouch
        Part.CanQuery = Original.CanQuery
    end

    Originals[Part] = nil
end

function HeadHitbox.ApplyPhysicalCharacter(PlayerObject, Character)
    if not HeadHitbox.Runtime.PhysicalEnabled
        or not Character
        or PlayerObject == LocalPlayer
    then
        return
    end

    local Part = HeadHitbox.GetPhysicalPart(Character) if not Part then return end

    HeadHitbox.ApplyPhysicalPart(Part)
    HeadHitbox.Runtime.PhysicalCharacters[Character] = Part
end

function HeadHitbox.RestorePhysicalCharacter(Character)
    if not Character then return end

    local Part = HeadHitbox.Runtime.PhysicalCharacters[Character]

    if not Part then Part = HeadHitbox.GetPhysicalPart(Character) end

    if Part then HeadHitbox.RestorePhysicalPart(Part) end

    HeadHitbox.Runtime.PhysicalCharacters[Character] = nil
end

function HeadHitbox.RefreshPhysical()
    local Runtime = HeadHitbox.Runtime
    Runtime.PhysicalEnabled = HeadHitbox.GetPhysicalEnabled()

    if not Runtime.PhysicalEnabled then
        for Part in pairs(Runtime.PhysicalOriginals) do
            HeadHitbox.RestorePhysicalPart(Part)
        end

        Runtime.PhysicalCharacters = setmetatable({}, {__mode = "k"})
        return
    end

    for _, PlayerObject in ipairs(Players:GetPlayers()) do
        if PlayerObject ~= LocalPlayer then
            HeadHitbox.ReconcilePlayer(PlayerObject, PlayerObject.Character)
        end
    end
end

function HeadHitbox.UpdatePhysicalSize()
    if not HeadHitbox.Runtime.PhysicalEnabled then return end

    for Part, Original in pairs(HeadHitbox.Runtime.PhysicalOriginals) do
        if Part and Part.Parent and type(Original) == "table" then
            HeadHitbox.ApplyPhysicalPart(Part)
        end
    end

    HeadHitbox.Maintain()
end

function HeadHitbox.GetColor()
    local Settings = type(Configuration.HitboxExpander) == "table" and Configuration.HitboxExpander or nil local Color = Settings and Settings.Color
    if typeof(Color) == "Color3" then return Color end
    local Theme = Library and Library.Theme local Accent = type(Theme) == "table" and Theme["Accent"]
    return typeof(Accent) == "Color3" and Accent or Color3.fromRGB(243, 167, 124)
end

function HeadHitbox.Disconnect(Connection)
    if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
end

function HeadHitbox.RemoveDrawing(Object)
    if not Object then return end

    Object.Visible = false

    if type(Object.Remove) == "function" then Object:Remove() end
end

function HeadHitbox.ClampLocalPoint(Point, Half)
    return Vector3.new(math.clamp(Point.X, -Half.X, Half.X), math.clamp(Point.Y, -Half.Y, Half.Y), math.clamp(Point.Z, -Half.Z, Half.Z))
end

function HeadHitbox.ClampToRealHead(Head, DesiredPosition, Margin)
    if not Head or not Head:IsA("BasePart") then return nil end
    if typeof(DesiredPosition) ~= "Vector3" then return Head.Position end

    Margin = math.clamp(
        tonumber(Margin) or HeadHitbox.SafetyMargin,
        0.03,
        0.15
    )

    local Half = Head.Size * 0.5 - Vector3.new(Margin, Margin, Margin)

    Half = Vector3.new(
        math.max(Half.X, 0.01),
        math.max(Half.Y, 0.01),
        math.max(Half.Z, 0.01)
    )

    local LocalPoint = Head.CFrame:PointToObjectSpace(DesiredPosition) local SafeLocal = HeadHitbox.ClampLocalPoint(LocalPoint, Half)

    return Head.CFrame:PointToWorldSpace(SafeLocal)
end

function HeadHitbox.UpdateRayBoxAxis(OriginValue, DirectionValue, HalfValue, MinimumTime, MaximumTime)
    if math.abs(DirectionValue) <= 0.000001 then return math.abs(OriginValue) <= HalfValue, MinimumTime, MaximumTime end

    local First = (-HalfValue - OriginValue) / DirectionValue local Second = (HalfValue - OriginValue) / DirectionValue

    if First > Second then First, Second = Second, First end

    MinimumTime = math.max(MinimumTime, First)
    MaximumTime = math.min(MaximumTime, Second)

    return MinimumTime <= MaximumTime, MinimumTime, MaximumTime
end

function HeadHitbox.GetRayBoxIntersection(LocalOrigin, LocalDirection, Half)
    local MinimumTime = 0 local MaximumTime = math.huge local Valid

    Valid, MinimumTime, MaximumTime = HeadHitbox.UpdateRayBoxAxis(
        LocalOrigin.X, LocalDirection.X, Half.X, MinimumTime, MaximumTime
    )
    if not Valid then return false, nil end

    Valid, MinimumTime, MaximumTime = HeadHitbox.UpdateRayBoxAxis(
        LocalOrigin.Y, LocalDirection.Y, Half.Y, MinimumTime, MaximumTime
    )
    if not Valid then return false, nil end

    Valid, MinimumTime, MaximumTime = HeadHitbox.UpdateRayBoxAxis(
        LocalOrigin.Z, LocalDirection.Z, Half.Z, MinimumTime, MaximumTime
    )
    if not Valid or MaximumTime < 0 then return false, nil end

    return true, math.max(MinimumTime, 0)
end

function HeadHitbox.GetRayBoxDistanceSquared(LocalOrigin, LocalDirection, Half, Time)
    local Point = LocalOrigin + LocalDirection * Time local BoxPoint = HeadHitbox.ClampLocalPoint(Point, Half) local Delta = Point - BoxPoint

    return Delta:Dot(Delta), BoxPoint
end

function HeadHitbox.GetClosestVirtualPoint(RayOrigin, RayDirection, Head, Scale)
    if typeof(RayOrigin) ~= "Vector3" or typeof(RayDirection) ~= "Vector3"
        or RayDirection.Magnitude <= 0.001
        or not Head or not Head:IsA("BasePart")
    then
        return nil, false
    end

    local VirtualSize = HeadHitbox.GetVirtualSize(Head, Scale)
    if not VirtualSize then return nil, false end

    local Half = VirtualSize * 0.5 local LocalOrigin = Head.CFrame:PointToObjectSpace(RayOrigin) local LocalDirection = Head.CFrame:VectorToObjectSpace(RayDirection.Unit)

    local Intersects, EntryTime = HeadHitbox.GetRayBoxIntersection(
        LocalOrigin,
        LocalDirection,
        Half
    )

    if Intersects and EntryTime then
        local EntryPoint = LocalOrigin + LocalDirection * EntryTime local VirtualLocal = HeadHitbox.ClampLocalPoint(EntryPoint, Half)

        return Head.CFrame:PointToWorldSpace(VirtualLocal), true
    end

    local CenterTime = math.max(-LocalOrigin:Dot(LocalDirection), 0) local Radius = Half.Magnitude + 2
    local MinimumTime = math.max(CenterTime - Radius, 0) local MaximumTime = CenterTime + Radius

    for _ = 1, 14 do
        local FirstTime = (MinimumTime * 2 + MaximumTime) / 3 local SecondTime = (MinimumTime + MaximumTime * 2) / 3 local FirstDistance = HeadHitbox.GetRayBoxDistanceSquared(
            LocalOrigin, LocalDirection, Half, FirstTime
        )
        local SecondDistance = HeadHitbox.GetRayBoxDistanceSquared(
            LocalOrigin, LocalDirection, Half, SecondTime
        )

        if FirstDistance <= SecondDistance then
            MaximumTime = SecondTime
        else
            MinimumTime = FirstTime
        end
    end

    local BestTime = (MinimumTime + MaximumTime) * 0.5 local _, VirtualLocal = HeadHitbox.GetRayBoxDistanceSquared(
        LocalOrigin,
        LocalDirection,
        Half,
        BestTime
    )

    return Head.CFrame:PointToWorldSpace(VirtualLocal), false
end

function HeadHitbox.GetRayIntersectionDistance(RayOrigin, RayDirection, Head, Scale, MaximumDistance)
    if typeof(RayOrigin) ~= "Vector3" or typeof(RayDirection) ~= "Vector3"
        or RayDirection.Magnitude <= 0.001
        or not Head or not Head:IsA("BasePart")
    then
        return nil, nil
    end

    local VirtualSize = HeadHitbox.GetVirtualSize(Head, Scale)
    if not VirtualSize then return nil, nil end

    local LocalOrigin = Head.CFrame:PointToObjectSpace(RayOrigin) local LocalDirection = Head.CFrame:VectorToObjectSpace(RayDirection.Unit)
    local Half = VirtualSize * 0.5 local Intersects, EntryTime = HeadHitbox.GetRayBoxIntersection(
        LocalOrigin,
        LocalDirection,
        Half
    )

    if not Intersects or not EntryTime or EntryTime < 0 then return nil, nil end

    MaximumDistance = math.max(tonumber(MaximumDistance) or 5000, 1)

    if EntryTime > MaximumDistance then return nil, nil end

    local EntryLocal = LocalOrigin + LocalDirection * EntryTime local VirtualLocal = HeadHitbox.ClampLocalPoint(EntryLocal, Half)
    local VirtualPoint = Head.CFrame:PointToWorldSpace(VirtualLocal)

    return EntryTime, VirtualPoint
end

function HeadHitbox.FindPacketHbeTarget(RayOrigin, Directions, Scale, MaximumDistance)
    if typeof(RayOrigin) ~= "Vector3" or type(Directions) ~= "table" then return nil end

    local Best local BestDistance = math.huge

    for PlayerObject, Record in pairs(HeadHitbox.Runtime.Records) do
        if PlayerObject ~= LocalPlayer
            and IsCombatTargetAllowed(PlayerObject)
            and type(Record) == "table"
        then
            local Character = Record.Character local Humanoid = Record.Humanoid local Head = Record.Head

            if Character and Character.Parent
                and Humanoid and Humanoid.Health > 0
                and Head and Head:IsA("BasePart") and Head.Parent
                and CombatChecks.Passes(PlayerObject, Character, Configuration.AimBot)
            then
                for DirectionIndex = 1, #Directions do
                    local Direction = Directions[DirectionIndex]

                    if typeof(Direction) == "Vector3" and Direction.Magnitude > 0.001 then
                        local EntryDistance, VirtualPoint = HeadHitbox.GetRayIntersectionDistance(
                            RayOrigin,
                            Direction,
                            Head,
                            Scale,
                            MaximumDistance
                        )

                        if EntryDistance and EntryDistance < BestDistance then
                            local ShotPoint = HeadHitbox.ClampToRealHead(
                                Head,
                                VirtualPoint,
                                HeadHitbox.SafetyMargin
                            )

                            if ShotPoint then
                                BestDistance = EntryDistance
                                Best = {
                                    Player = PlayerObject,
                                    Character = Character,
                                    Humanoid = Humanoid,
                                    Head = Head,
                                    VirtualPoint = VirtualPoint,
                                    ShotPoint = ShotPoint,
                                    EntryDistance = EntryDistance,
                                    DirectionIndex = DirectionIndex
                                }
                            end
                        end
                    end
                end
            end
        end
    end

    return Best
end

function HeadHitbox.ApplyPacketHbeTarget(Data, HbeTarget)
    if type(Data) ~= "table" or type(HbeTarget) ~= "table" then return false end

    local PlayerObject = HbeTarget.Player local Character = HbeTarget.Character local Head = HbeTarget.Head local ShotPoint = HbeTarget.ShotPoint

    if not PlayerObject or not Character or not Character.Parent
        or not Head or not Head:IsA("BasePart") or not Head:IsDescendantOf(Character)
        or typeof(ShotPoint) ~= "Vector3"
    then
        return false
    end

    Data.TargetPlayer = PlayerObject
    Data.TargetCharacter = Character
    Data.TargetPart = Head
    Data.PartName = "Head"
    Data.HbeTarget = true
    Data.HbeVirtualPoint = HbeTarget.VirtualPoint
    Data.HbeShotPoint = ShotPoint
    Data.HbeEntryDistance = HbeTarget.EntryDistance
    Data.HbeDirectionIndex = HbeTarget.DirectionIndex

    SilentAimController.LastTarget = PlayerObject
    SilentAimController.LastPart = Head
    Configuration.AimBot.CurrentTarget = PlayerObject

    return true
end

function HeadHitbox.GetMeleeReach(Tool)
    local Reach = 6.5

    if not Tool or not Tool:IsA("Tool") then return Reach end

    local Config = Tool:FindFirstChild("Config")

    if Config and Config:IsA("ModuleScript") then
        local Success, Settings = Internal.Call(require, Config)

        if Success and type(Settings) == "table" then
            local Candidates = { Settings.MeleeRange, Settings.HitRange, Settings.Range, Settings.Reach, Settings.Distance }

            if type(Settings.Mains) == "table" then
                local Main = Settings.Mains.E or Settings.Mains.M1 or Settings.Mains.Primary

                if type(Main) == "table" then
                    Candidates[#Candidates + 1] = Main.MeleeRange
                    Candidates[#Candidates + 1] = Main.HitRange
                    Candidates[#Candidates + 1] = Main.Range
                    Candidates[#Candidates + 1] = Main.Reach
                    Candidates[#Candidates + 1] = Main.Distance
                end
            end

            for Index = 1, #Candidates do
                local Value = tonumber(Candidates[Index])

                if Value and Value > 0 then
                    Reach = Value
                    break
                end
            end
        end
    end

    local Name = string.lower(Tool.Name)

    if string.find(Name, "fist", 1, true)
        or string.find(Name, "punch", 1, true)
        or string.find(Name, "hand", 1, true)
    then
        Reach = math.min(Reach, 6.5)
    end

    return math.clamp(Reach, 3.5, 12)
end

function HeadHitbox.GetMeleeOrigin(Character, Tool)
    if not Character then return nil, nil end

    local Handle = Tool and (
        Tool:FindFirstChild("WeaponHandle")
        or Tool:FindFirstChild("Handle")
    )

    Handle = Handle and Handle:IsA("BasePart") and Handle or nil

    if not Handle then Handle = Character:FindFirstChild("Right Arm") or Character:FindFirstChild("RightHand") end

    if not Handle or not Handle:IsA("BasePart") then return nil, nil end

    return Handle.Position, Handle
end

function HeadHitbox.GetMeleeDirection(Origin)
    if typeof(Origin) ~= "Vector3" then return nil end

    local CameraObject = workspace.CurrentCamera local Hit = Mouse and Mouse.Hit

    if Hit and typeof(Hit.Position) == "Vector3" then
        local Delta = Hit.Position - Origin

        if Delta.Magnitude > 0.001 then return Delta.Unit end
    end

    if CameraObject then return CameraObject.CFrame.LookVector end

    local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")

    return Root and Root.CFrame.LookVector or nil
end

function HeadHitbox.FindMeleeHbeTarget(Character, Tool)
    if not HeadHitbox.GetEnabled() or not Character or not Tool then return nil end

    local Origin, Handle = HeadHitbox.GetMeleeOrigin(Character, Tool) local Direction = HeadHitbox.GetMeleeDirection(Origin)

    if typeof(Origin) ~= "Vector3"
        or typeof(Direction) ~= "Vector3"
        or Direction.Magnitude <= 0.001
    then
        return nil
    end

    local BaseReach = HeadHitbox.GetMeleeReach(Tool) local Scale = HeadHitbox.GetNormalShotScale() local Best local BestDistance = math.huge

    for PlayerObject, Record in pairs(HeadHitbox.Runtime.Records) do
        if PlayerObject ~= LocalPlayer
            and IsCombatTargetAllowed(PlayerObject)
            and type(Record) == "table"
        then
            local TargetCharacter = Record.Character local Humanoid = Record.Humanoid local Head = Record.Head

            if TargetCharacter and TargetCharacter.Parent
                and Humanoid and Humanoid.Health > 0
                and Head and Head:IsA("BasePart") and Head.Parent
                and CombatChecks.Passes(PlayerObject, TargetCharacter, Configuration.AimBot)
            then
                local VirtualSize = HeadHitbox.GetVirtualSize(Head, Scale) local ExtraReach = VirtualSize and math.max(VirtualSize.X, VirtualSize.Y, VirtualSize.Z) * 0.5 or 0
                local MaximumDistance = math.min(
                    BaseReach + ExtraReach,
                    BaseReach + 5
                )
                local EntryDistance, VirtualPoint = HeadHitbox.GetRayIntersectionDistance(
                    Origin,
                    Direction,
                    Head,
                    Scale,
                    MaximumDistance
                )

                if EntryDistance and EntryDistance < BestDistance then
                    local RealEntryDistance = HeadHitbox.GetRayIntersectionDistance(
                        Origin,
                        Direction,
                        Head,
                        1,
                        MaximumDistance
                    )

                    if not RealEntryDistance
                        and CombatChecks.IsVisible(Origin, VirtualPoint, PlayerObject, TargetCharacter)
                    then
                        BestDistance = EntryDistance
                        Best = {
                            Player = PlayerObject,
                            Character = TargetCharacter,
                            Humanoid = Humanoid,
                            Head = Head,
                            Handle = Handle,
                            Origin = Origin,
                            Direction = Direction.Unit,
                            VirtualPoint = VirtualPoint,
                            EntryDistance = EntryDistance,
                            Reach = MaximumDistance
                        }
                    end
                end
            end
        end
    end

    return Best
end

function HeadHitbox.RecordPhysicalMeleeHit(Arguments)
    if type(Arguments) ~= "table"
        or Arguments[4] ~= "2389ZFX34"
    then
        return
    end

    local Token = Arguments[5] local Tool = Arguments[3]

    if Token == nil then return end

    local Runtime = HeadHitbox.Runtime
    Runtime.MeleePhysicalHits = type(Runtime.MeleePhysicalHits) == "table" and Runtime.MeleePhysicalHits or {}
    Runtime.MeleeHitTemplates = type(Runtime.MeleeHitTemplates) == "table" and Runtime.MeleeHitTemplates or setmetatable({}, {__mode = "k"})

    Runtime.MeleePhysicalHits[Token] = os.clock()

    if typeof(Tool) == "Instance" and Tool:IsA("Tool") then
        local Copy = CloneNamecallArguments(Arguments)

        if Copy then Runtime.MeleeHitTemplates[Tool] = { Time = os.clock(), Arguments = Copy } end
    end
end

function HeadHitbox.HasRecentPhysicalMeleeHit(Token)
    if Token == nil then return false end

    local Hits = HeadHitbox.Runtime.MeleePhysicalHits

    if type(Hits) ~= "table" then return false end

    local Time = tonumber(Hits[Token])

    if not Time then return false end

    if os.clock() - Time <= 0.16 then return true end

    Hits[Token] = nil
    return false
end

function HeadHitbox.SendMeleeHbeHit(SwingArguments, Token)
    if not HeadHitbox.GetEnabled()
        or type(SwingArguments) ~= "table"
        or Token == nil
    then
        return false
    end

    task.wait(0.035)

    if HeadHitbox.HasRecentPhysicalMeleeHit(Token) then return false end

    local Character = LocalPlayer.Character local Tool = SwingArguments[3]

    if not Character
        or typeof(Tool) ~= "Instance"
        or not Tool:IsA("Tool")
        or Tool.Parent ~= Character
    then
        return false
    end

    local Target = HeadHitbox.FindMeleeHbeTarget(Character, Tool)

    if not Target then return false end

    local Head = Target.Head local TargetCharacter = Target.Character local Handle = Target.Handle local Root = Character:FindFirstChild("HumanoidRootPart")

    if not Head or not Head.Parent
        or not TargetCharacter or not TargetCharacter.Parent
        or not Handle or not Handle.Parent
        or not Root
    then
        return false
    end

    local HitPosition = Target.VirtualPoint local CenterDelta = HitPosition - Head.Position

    if CenterDelta.Magnitude > 1.45 then HitPosition = Head.Position + CenterDelta.Unit * 1.45 end

    local Events = ReplicatedStorage:FindFirstChild("Events") local HitRemote = Events and Events:FindFirstChild("XMHH2.2")

    if not HitRemote or not HitRemote:IsA("RemoteEvent") then return false end

    local FireServer = HitRemote.FireServer

    if type(FireServer) ~= "function" then return false end

    local Runtime = HeadHitbox.Runtime local Templates = type(Runtime.MeleeHitTemplates) == "table" and Runtime.MeleeHitTemplates or nil
    local Template = Templates and Templates[Tool] local TemplateArguments = type(Template) == "table"
        and type(Template.Arguments) == "table"
        and os.clock() - (tonumber(Template.Time) or 0) <= 20
        and Template.Arguments or nil

    if TemplateArguments then
        local Arguments = CloneNamecallArguments(TemplateArguments)

        if not Arguments then return false end

        Arguments[5] = Token
        Arguments[6] = false
        Arguments[7] = Handle
        Arguments[8] = Head
        Arguments[9] = TargetCharacter
        Arguments[10] = Root.Position
        Arguments[11] = HitPosition

        FireServer(HitRemote, table.unpack(Arguments, 1, math.max(math.floor(tonumber(Arguments.n) or #Arguments), 11)))
    else
        FireServer(
            HitRemote,
            "🍞",
            tick(),
            Tool,
            "2389ZFX34",
            Token,
            false,
            Handle,
            Head,
            TargetCharacter,
            Root.Position,
            HitPosition
        )
    end

    return true
end

function HeadHitbox.QueueMeleeHbeSwing(Arguments, Token)
    if not HeadHitbox.GetEnabled()
        or type(Arguments) ~= "table"
        or Token == nil
        or Arguments[4] ~= "43TRFWX"
        or Arguments[5] ~= "Normal"
    then
        return
    end

    local Tool = Arguments[3]

    if typeof(Tool) ~= "Instance"
        or not Tool:IsA("Tool")
        or Tool.Parent ~= LocalPlayer.Character
    then
        return
    end

    task.spawn(HeadHitbox.SendMeleeHbeHit, Arguments, Token)
end

function HeadHitbox.GetCursorRay(CameraObject, CursorPosition, UseScreenCoordinates, TopLeftInset)
    if not CameraObject or typeof(CursorPosition) ~= "Vector2" then return nil end

    if UseScreenCoordinates == true then return CameraObject:ScreenPointToRay(CursorPosition.X, CursorPosition.Y) end

    local ViewportPosition = CursorPosition

    if typeof(TopLeftInset) == "Vector2" then ViewportPosition -= TopLeftInset end

    return CameraObject:ViewportPointToRay(ViewportPosition.X, ViewportPosition.Y)
end

function HeadHitbox.GetScreenSelection(Head, CursorPosition, CameraObject, UseScreenCoordinates, TopLeftInset, Scale)
    if not Head or not Head:IsA("BasePart")
        or typeof(CursorPosition) ~= "Vector2"
        or not CameraObject
    then
        return nil, false, nil, nil
    end

    local CursorRay = HeadHitbox.GetCursorRay(
        CameraObject,
        CursorPosition,
        UseScreenCoordinates,
        TopLeftInset
    )

    if not CursorRay then return nil, false, nil, nil end

    local VirtualPoint, Intersects = HeadHitbox.GetClosestVirtualPoint(
        CursorRay.Origin,
        CursorRay.Direction,
        Head,
        Scale
    )

    if typeof(VirtualPoint) ~= "Vector3" then return nil, false, nil, nil end

    local Projected local Visible

    if UseScreenCoordinates == true then
        Projected, Visible = CameraObject:WorldToScreenPoint(VirtualPoint)
    else
        Projected, Visible = CameraObject:WorldToViewportPoint(VirtualPoint)
    end

    if Projected.Z <= 0 then return nil, false, VirtualPoint, nil end

    local ProjectedPoint = Vector2.new(Projected.X, Projected.Y)

    if UseScreenCoordinates ~= true and typeof(TopLeftInset) == "Vector2" then ProjectedPoint += TopLeftInset end

    local Distance = (CursorPosition - ProjectedPoint).Magnitude local ShotPoint = HeadHitbox.ClampToRealHead(
        Head,
        VirtualPoint,
        HeadHitbox.SafetyMargin
    )

    if Intersects then Distance = math.min(Distance, 0.001) end

    return Distance, Visible == true, VirtualPoint, ShotPoint
end

function HeadHitbox.GetAimShotPoint(Head, CursorPosition, CameraObject, UseScreenCoordinates, TopLeftInset, Scale)
    local _, _, VirtualPoint, ShotPoint = HeadHitbox.GetScreenSelection(
        Head,
        CursorPosition,
        CameraObject,
        UseScreenCoordinates,
        TopLeftInset,
        Scale
    )

    return ShotPoint or HeadHitbox.ClampToRealHead(Head, VirtualPoint or Head.Position, HeadHitbox.SafetyMargin) or Head.Position
end

function HeadHitbox.HideVisual(Data)
    if type(Data) ~= "table" or type(Data.Lines) ~= "table" then return end

    for Index = 1, #Data.Lines do
        if Data.Lines[Index] then Data.Lines[Index].Visible = false end
    end
end

function HeadHitbox.DestroyVisual(PlayerObject)
    local Record = HeadHitbox.Runtime.Records[PlayerObject]

    if not Record or type(Record.Lines) ~= "table" then return end

    for Index = 1, #Record.Lines do
        HeadHitbox.RemoveDrawing(Record.Lines[Index])
        Record.Lines[Index] = nil
    end
end

function HeadHitbox.CreateVisual(PlayerObject)
    local Record = HeadHitbox.Runtime.Records[PlayerObject] if not Record then return end

    HeadHitbox.DestroyVisual(PlayerObject)
    if not HeadHitbox.GetVisualEnabled() then return end
    Record.Lines = {}

    if type(Drawing) ~= "table" or type(Drawing.new) ~= "function" then return end

    for Index = 1, 12 do
        local Line = Drawing.new("Line")
        Line.Color = HeadHitbox.GetColor()
        Line.Thickness = 1.35
        Line.Transparency = 0.88
        Line.Visible = false
        Record.Lines[Index] = Line
    end
end

function HeadHitbox.RefreshCharacter(PlayerObject, Character)
    if not PlayerObject or PlayerObject == LocalPlayer then return end

    local Runtime = HeadHitbox.Runtime
    local Record = Runtime.Records[PlayerObject]

    if not Record then
        Record = {
            Player = PlayerObject,
            Character = nil,
            Humanoid = nil,
            Head = nil,
            Lines = {},
            ChildAdded = nil,
            ChildRemoved = nil,
            AncestryChanged = nil,
            Generation = 0
        }

        Runtime.Records[PlayerObject] = Record
    end

    local PreviousCharacter = Record.Character

    if PreviousCharacter and PreviousCharacter ~= Character then
        HeadHitbox.RestorePhysicalCharacter(PreviousCharacter)
    end

    HeadHitbox.Disconnect(Record.ChildAdded)
    HeadHitbox.Disconnect(Record.ChildRemoved)
    HeadHitbox.Disconnect(Record.AncestryChanged)

    Record.ChildAdded = nil
    Record.ChildRemoved = nil
    Record.AncestryChanged = nil
    Record.Generation = (tonumber(Record.Generation) or 0) + 1

    local Generation = Record.Generation

    Record.Character = Character
    Record.Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") or nil
    Record.Head = Character and Character:FindFirstChild("Head") or nil

    if Record.Head and not Record.Head:IsA("BasePart") then Record.Head = nil end

    if Character then
        Record.ChildAdded = Character.ChildAdded:Connect(function(Child)
            if Record.Generation ~= Generation or Record.Character ~= Character then return end

            if Child:IsA("Humanoid") then Record.Humanoid = Child end

            if Child.Name == "Head" and Child:IsA("BasePart") then
                Record.Head = Child

                if Runtime.PhysicalEnabled then
                    HeadHitbox.ApplyPhysicalCharacter(PlayerObject, Character)
                end

                if HeadHitbox.GetVisualEnabled() then
                    HeadHitbox.CreateVisual(PlayerObject)
                end
            elseif Child:IsA("Humanoid") then
                Record.Humanoid = Character:FindFirstChildOfClass("Humanoid")
            end
        end)

        Record.ChildRemoved = Character.ChildRemoved:Connect(function(Child)
            if Record.Generation ~= Generation or Record.Character ~= Character then return end

            if Child == Record.Head then
                HeadHitbox.RestorePhysicalPart(Child)
                Runtime.PhysicalCharacters[Character] = nil
                Record.Head = nil
                HeadHitbox.HideVisual(Record)
            end

            if Child == Record.Humanoid then Record.Humanoid = nil end
        end)

        Record.AncestryChanged = Character.AncestryChanged:Connect(function(_, Parent)
            if Record.Generation ~= Generation or Record.Character ~= Character then return end

            if Parent == nil then
                HeadHitbox.RestorePhysicalCharacter(Character)
                HeadHitbox.HideVisual(Record)
                task.defer(HeadHitbox.ReconcilePlayer, PlayerObject)
            end
        end)
    end

    if HeadHitbox.GetVisualEnabled() then
        HeadHitbox.CreateVisual(PlayerObject)
    else
        HeadHitbox.DestroyVisual(PlayerObject)
    end

    if Runtime.PhysicalEnabled then
        HeadHitbox.ApplyPhysicalCharacter(PlayerObject, Character)
    end
end

function HeadHitbox.ReconcilePlayer(PlayerObject, PreferredCharacter)
    if not PlayerObject or PlayerObject == LocalPlayer or PlayerObject.Parent ~= Players then return false end

    local Runtime = HeadHitbox.Runtime
    local Record = Runtime.Records[PlayerObject]

    if not Record then
        Record = {
            Player = PlayerObject,
            Character = nil,
            Humanoid = nil,
            Head = nil,
            Lines = {},
            ChildAdded = nil,
            ChildRemoved = nil,
            AncestryChanged = nil,
            Generation = 0
        }

        Runtime.Records[PlayerObject] = Record
    end

    PreferredCharacter = PreferredCharacter or PlayerObject.Character

    local Character = ResolveTrackedCharacter(
        PlayerObject,
        PreferredCharacter
    ) or PreferredCharacter

    if Character and not Character.Parent then Character = nil end

    if Record.Character ~= Character then
        HeadHitbox.RefreshCharacter(PlayerObject, Character)
        Record = Runtime.Records[PlayerObject]
    end

    if not Record then return false end

    Character = Record.Character

    if not Character or not Character.Parent then
        Record.Humanoid = nil
        Record.Head = nil
        HeadHitbox.HideVisual(Record)
        return false
    end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    local Head = Character:FindFirstChild("Head")
    if Head and not Head:IsA("BasePart") then Head = nil end

    local Changed = Record.Humanoid ~= Humanoid or Record.Head ~= Head

    Record.Humanoid = Humanoid
    Record.Head = Head

    if Runtime.PhysicalEnabled and Head then
        local BoundPart = Runtime.PhysicalCharacters[Character]

        if BoundPart and BoundPart ~= Head then
            HeadHitbox.RestorePhysicalPart(BoundPart)
            Runtime.PhysicalCharacters[Character] = nil
        end

        if HeadHitbox.ApplyPhysicalPart(Head) then
            Runtime.PhysicalCharacters[Character] = Head
        end
    elseif not Runtime.PhysicalEnabled and Runtime.PhysicalCharacters[Character] then
        HeadHitbox.RestorePhysicalCharacter(Character)
    end

    if HeadHitbox.GetVisualEnabled() then
        if Changed or type(Record.Lines) ~= "table" or #Record.Lines ~= 12 then
            HeadHitbox.CreateVisual(PlayerObject)
        end
    else
        HeadHitbox.DestroyVisual(PlayerObject)
    end

    return Head ~= nil and Humanoid ~= nil
end

function HeadHitbox.Maintain()
    local Runtime = HeadHitbox.Runtime
    if not Runtime.Started or not HeadHitbox.GetPhysicalEnabled() then return end

    local Present = {}

    for _, PlayerObject in ipairs(Players:GetPlayers()) do
        if PlayerObject ~= LocalPlayer then
            Present[PlayerObject] = true

            if type(Runtime.PlayerConnections[PlayerObject]) ~= "table" then
                HeadHitbox.BindPlayer(PlayerObject)
            else
                HeadHitbox.ReconcilePlayer(PlayerObject, PlayerObject.Character)
            end
        end
    end

    for PlayerObject in pairs(Runtime.Records) do
        if not Present[PlayerObject] or PlayerObject.Parent ~= Players then
            HeadHitbox.UnbindPlayer(PlayerObject)
        end
    end
end

function HeadHitbox.BindPlayer(PlayerObject)
    if not PlayerObject or PlayerObject == LocalPlayer then return end

    local Runtime = HeadHitbox.Runtime local Connections = Runtime.PlayerConnections[PlayerObject]

    if type(Connections) == "table" then
        HeadHitbox.Disconnect(Connections.CharacterAdded)
        HeadHitbox.Disconnect(Connections.CharacterRemoving)
    else
        Connections = {}
        Runtime.PlayerConnections[PlayerObject] = Connections
    end

    Connections.CharacterAdded = PlayerObject.CharacterAdded:Connect(function(Character)
        HeadHitbox.RefreshCharacter(PlayerObject, Character)
        task.defer(HeadHitbox.ReconcilePlayer, PlayerObject, Character)

        task.delay(0.12, function()
            if HeadHitbox.Runtime.Started and PlayerObject.Parent == Players then
                HeadHitbox.ReconcilePlayer(PlayerObject, Character)
            end
        end)

        task.delay(0.45, function()
            if HeadHitbox.Runtime.Started and PlayerObject.Parent == Players then
                HeadHitbox.ReconcilePlayer(PlayerObject, PlayerObject.Character)
            end
        end)
    end)

    Connections.CharacterRemoving = PlayerObject.CharacterRemoving:Connect(function(Character)
        local Record = Runtime.Records[PlayerObject]

        if Record and Record.Character == Character then
            HeadHitbox.RestorePhysicalCharacter(Character)
            HeadHitbox.HideVisual(Record)
            HeadHitbox.Disconnect(Record.ChildAdded)
            HeadHitbox.Disconnect(Record.ChildRemoved)
            Record.ChildAdded = nil
            Record.ChildRemoved = nil
            Record.Character = nil
            Record.Humanoid = nil
            Record.Head = nil
        end
    end)

    HeadHitbox.RefreshCharacter(PlayerObject, ResolveTrackedCharacter(PlayerObject, PlayerObject.Character) or PlayerObject.Character)
    task.defer(HeadHitbox.ReconcilePlayer, PlayerObject, PlayerObject.Character)
end

function HeadHitbox.UnbindPlayer(PlayerObject)
    local Runtime = HeadHitbox.Runtime local Connections = Runtime.PlayerConnections[PlayerObject] local Record = Runtime.Records[PlayerObject]

    if type(Connections) == "table" then
        HeadHitbox.Disconnect(Connections.CharacterAdded)
        HeadHitbox.Disconnect(Connections.CharacterRemoving)
    end

    if Record then
        if Record.Character then HeadHitbox.RestorePhysicalCharacter(Record.Character) end

        HeadHitbox.Disconnect(Record.ChildAdded)
        HeadHitbox.Disconnect(Record.ChildRemoved)
        HeadHitbox.Disconnect(Record.AncestryChanged)
        HeadHitbox.DestroyVisual(PlayerObject)
    end

    Runtime.PlayerConnections[PlayerObject] = nil
    Runtime.Records[PlayerObject] = nil
end

function HeadHitbox.UpdateVisual(PlayerObject, Record, CameraObject)
    if not HeadHitbox.GetVisualEnabled() or not Record or not CameraObject then
        HeadHitbox.HideVisual(Record)
        return
    end

    local Head = Record.Head local Humanoid = Record.Humanoid

    if not Head or not Head:IsA("BasePart") or not Head.Parent
        or not Humanoid or Humanoid.Health <= 0
    then
        HeadHitbox.HideVisual(Record)
        return
    end

    if type(Record.Lines) ~= "table" or #Record.Lines ~= 12 then HeadHitbox.CreateVisual(PlayerObject) end

    if type(Record.Lines) ~= "table" or #Record.Lines ~= 12 then return end

    local VirtualSize = HeadHitbox.GetVirtualSize(
        Head,
        HeadHitbox.GetSizeValue()
    )

    if not VirtualSize then
        HeadHitbox.HideVisual(Record)
        return
    end

    local Half = VirtualSize * 0.5 local Corners = Record.Corners

    if type(Corners) ~= "table" then
        Corners = table.create(8)
        Record.Corners = Corners
    end

    Corners[1] = Vector3.new(-Half.X, -Half.Y, -Half.Z)
    Corners[2] = Vector3.new(Half.X, -Half.Y, -Half.Z)
    Corners[3] = Vector3.new(-Half.X, Half.Y, -Half.Z)
    Corners[4] = Vector3.new(Half.X, Half.Y, -Half.Z)
    Corners[5] = Vector3.new(-Half.X, -Half.Y, Half.Z)
    Corners[6] = Vector3.new(Half.X, -Half.Y, Half.Z)
    Corners[7] = Vector3.new(-Half.X, Half.Y, Half.Z)
    Corners[8] = Vector3.new(Half.X, Half.Y, Half.Z)

    local ScreenCorners = Record.ScreenCorners

    if type(ScreenCorners) ~= "table" then
        ScreenCorners = table.create(8)
        Record.ScreenCorners = ScreenCorners
    end

    for Index = 1, 8 do
        local WorldPoint = Head.CFrame:PointToWorldSpace(Corners[Index]) local Projected = CameraObject:WorldToViewportPoint(WorldPoint)

        if Projected.Z <= 0 then
            HeadHitbox.HideVisual(Record)
            return
        end

        ScreenCorners[Index] = Vector2.new(Projected.X, Projected.Y)
    end

    local Color = HeadHitbox.GetColor() local Edges = HeadHitbox.Runtime.Edges

    for Index = 1, #Edges do
        local Line = Record.Lines[Index] local Edge = Edges[Index]

        if Line then
            Line.From = ScreenCorners[Edge[1]]
            Line.To = ScreenCorners[Edge[2]]
            Line.Color = Color
            Line.Thickness = 1.35
            Line.Transparency = 0.88
            Line.Visible = true
        end
    end
end

function HeadHitbox.UpdateVisuals()
    if not HeadHitbox.GetVisualEnabled() then return end

    local CameraObject = Internal.GetCamera() if not CameraObject then return end

    for PlayerObject, Record in pairs(HeadHitbox.Runtime.Records) do
        HeadHitbox.UpdateVisual(PlayerObject, Record, CameraObject)
    end
end

function HeadHitbox.Start()
    local Runtime = HeadHitbox.Runtime
    if Runtime.Started then return end

    Runtime.Started = true

    Runtime.PlayerAdded = Players.PlayerAdded:Connect(function(PlayerObject)
        HeadHitbox.BindPlayer(PlayerObject)
    end)

    Runtime.PlayerRemoving = Players.PlayerRemoving:Connect(function(PlayerObject)
        HeadHitbox.UnbindPlayer(PlayerObject)
    end)

    Runtime.RenderConnection = RunService.RenderStepped:Connect(function()
        Internal.Call(HeadHitbox.UpdatePhysicalVisuals)
        Internal.Call(HeadHitbox.UpdateVisuals)
    end)

    Runtime.MaintenanceClock = 0
    Runtime.MaintenanceConnection = RunService.Heartbeat:Connect(function(DeltaTime)
        Runtime.MaintenanceClock += tonumber(DeltaTime) or 0

        if Runtime.MaintenanceClock < Runtime.MaintenanceInterval then return end

        Runtime.MaintenanceClock = 0
        Internal.Call(HeadHitbox.Maintain)
    end)

    for _, PlayerObject in ipairs(Players:GetPlayers()) do
        HeadHitbox.BindPlayer(PlayerObject)
    end

    HeadHitbox.Maintain()
end

function HeadHitbox.Stop()
    local Runtime = HeadHitbox.Runtime

    HeadHitbox.Disconnect(Runtime.PlayerAdded)
    HeadHitbox.Disconnect(Runtime.PlayerRemoving)
    HeadHitbox.Disconnect(Runtime.RenderConnection)
    HeadHitbox.Disconnect(Runtime.MaintenanceConnection)

    Runtime.PlayerAdded = nil
    Runtime.PlayerRemoving = nil
    Runtime.RenderConnection = nil
    Runtime.MaintenanceConnection = nil
    Runtime.MaintenanceClock = 0

    for PlayerObject in pairs(Runtime.Records) do
        HeadHitbox.UnbindPlayer(PlayerObject)
    end

    for Part in pairs(Runtime.PhysicalOriginals) do
        HeadHitbox.RestorePhysicalPart(Part)
    end

    for Part in pairs(Runtime.PhysicalVisuals) do
        HeadHitbox.DestroyPhysicalVisual(Part, false)
    end

    Runtime.PhysicalOriginals = setmetatable({}, {__mode = "k"})
    Runtime.PhysicalCharacters = setmetatable({}, {__mode = "k"})
    Runtime.PhysicalVisuals = setmetatable({}, {__mode = "k"})
    Runtime.PhysicalEnabled = false
    Runtime.Records = setmetatable({}, {__mode = "k"})
    Runtime.PlayerConnections = setmetatable({}, {__mode = "k"})
    Runtime.Started = false
end

function HeadHitbox.Refresh()
    HeadHitbox.Enabled = HeadHitbox.GetEnabled()

    if not HeadHitbox.GetPhysicalEnabled() then
        HeadHitbox.RefreshPhysical()
        HeadHitbox.Stop()
        return
    end

    HeadHitbox.Start()
    HeadHitbox.RefreshPhysical()
    HeadHitbox.Maintain()
    HeadHitbox.UpdatePhysicalSize()

    for PlayerObject, Record in pairs(HeadHitbox.Runtime.Records) do
        if HeadHitbox.GetVisualEnabled() and Record and Record.Head and Record.Head.Parent then
            HeadHitbox.CreateVisual(PlayerObject)
        else
            HeadHitbox.DestroyVisual(PlayerObject)
        end
    end
end

function HeadHitbox.Disable()
    HeadHitbox.Enabled = false
    HeadHitbox.Runtime.PhysicalEnabled = false
    HeadHitbox.Stop()
end

function GetHeadHitboxPart(Character)
    if not Character then return nil end

    local Head = Character:FindFirstChild("Head")
    return Head and Head:IsA("BasePart") and Head or nil
end

function GetHeadServerPoint(Head, DesiredPosition)
    return HeadHitbox.ClampToRealHead(Head, DesiredPosition, HeadHitbox.SafetyMargin)
end

function GetHeadHitboxScreenDistance(Part, WorldPosition, CursorPosition, CameraObject, UseScreenCoordinates, TopLeftInset, Size)
    if not Part or not Part:IsA("BasePart") then return nil, false end

    return HeadHitbox.GetScreenSelection(Part, CursorPosition, CameraObject, UseScreenCoordinates, TopLeftInset, Size)
end

HeadHitbox.Refresh()

function GetAimTargetData(PlayerObject, TargetPartName)
    if not Configuration.AimBot.Enabled or not IsCombatTargetAllowed(PlayerObject) then return nil, nil end

    local Character = ResolveTrackedCharacter(PlayerObject, PlayerObject.Character) or PlayerObject.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid") local HumanoidRootPart = ResolverGetRoot(Character)

    if not Character or not Humanoid or not HumanoidRootPart then return nil, nil end
    if not CombatChecks.Passes(PlayerObject, Character, Configuration.AimBot) then return nil, nil end

    TargetPartName = tostring(TargetPartName or Configuration.AimBot.TargetPart or "Head")
    local TargetPart

    if TargetPartName == "Head" and HeadHitbox.GetEnabled() then TargetPart = GetHeadHitboxPart(Character) end

    TargetPart = TargetPart or Character:FindFirstChild(TargetPartName) or Character:FindFirstChild("Head") or HumanoidRootPart
    if not TargetPart or not TargetPart:IsA("BasePart") then return nil, nil end

    return Character, TargetPart
end

function IsAimTargetVisible(Character, TargetPosition)
    if Configuration.AimBot.WallCheck ~= true then return true end
    if not Character or typeof(TargetPosition) ~= "Vector3" then return false end

    local CameraObject = Internal.GetCamera()
    if not CameraObject then return false end

    local PlayerObject = Internal.GetPlayerFromTrackedCharacter(Character)
    return CombatChecks.IsVisible(CameraObject.CFrame.Position, TargetPosition, PlayerObject, Character)
end

function GetAimTargetScore(PlayerObject)
    local Character, TargetPart = GetAimTargetData(PlayerObject)
    if not Character or not TargetPart then return nil end

    local CameraObject = Internal.GetCamera()
    if not CameraObject then return nil end

    local TargetPosition = TargetPart.Position
    if not IsAimTargetVisible(Character, TargetPosition) then return nil end

    local FieldOfViewPosition, UseScreenCoordinates = GetAimFOVAnchorPosition() local Distance

    if HeadHitbox.GetEnabled() and TargetPart.Name == "Head" then
        Distance = GetHeadHitboxScreenDistance(
            TargetPart,
            TargetPosition,
            FieldOfViewPosition,
            CameraObject,
            UseScreenCoordinates,
            nil,
            HeadHitbox.GetSizeValue()
        )
    else
        local ScreenPosition, IsOnScreen

        if UseScreenCoordinates then
            ScreenPosition, IsOnScreen = CameraObject:WorldToScreenPoint(TargetPosition)
        else
            ScreenPosition, IsOnScreen = CameraObject:WorldToViewportPoint(TargetPosition)
        end

        if not IsOnScreen or ScreenPosition.Z <= 0 then return nil end
        Distance = (FieldOfViewPosition - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude
    end

    if not Distance or Distance > math.max(tonumber(Configuration.AimBot.FOV) or 100, 1) then return nil end

    return Distance, Character, TargetPart
end

function GetClosestPlayer()
    if not Configuration.AimBot.Enabled then return nil end

    local CurrentTime = os.clock() local ScanInterval = math.max(tonumber(Configuration.AimBot.TargetScanInterval) or 0.05, 0.04)

    if CurrentTime - (Configuration.AimBot.LastTargetScan or 0) < ScanInterval then
        local CachedTarget = Configuration.AimBot.CachedScanTarget
        if CachedTarget and GetAimTargetScore(CachedTarget) then return CachedTarget end
    end

    Configuration.AimBot.LastTargetScan = CurrentTime

    local ClosestPlayer local ShortestDistance = math.max(tonumber(Configuration.AimBot.FOV) or 100, 1) local BestTier = -1

    for _, PlayerObject in ipairs(Players:GetPlayers()) do
        if PlayerObject ~= LocalPlayer then
            local Distance = GetAimTargetScore(PlayerObject)

            if Distance then
                local Tier = GetCombatTargetPriority(PlayerObject)
                if Tier > BestTier or (Tier == BestTier and Distance < ShortestDistance) then
                    BestTier = Tier
                    ShortestDistance = Distance
                    ClosestPlayer = PlayerObject
                end
            end
        end
    end

    Configuration.AimBot.CachedScanTarget = ClosestPlayer
    return ClosestPlayer
end

function GetTargetPosition(CharacterObject, PlayerObject, AimMode)
    if not CharacterObject then return nil end

    local CurrentTime = os.clock() local UpdateInterval = math.max( tonumber(Configuration.AimBot.PositionUpdateInterval) or (1 / 45), 1 / 60)

    if Configuration.AimBot.PositionCacheCharacter == CharacterObject and Configuration.AimBot.PositionCacheValue and Configuration.AimBot.PositionCacheMode == AimMode
        and CurrentTime - (Configuration.AimBot.LastPositionUpdate or 0) < UpdateInterval then
        return Configuration.AimBot.PositionCacheValue
    end

    local TargetPart = CharacterObject:FindFirstChild(Configuration.AimBot.TargetPart) or CharacterObject:FindFirstChild("HumanoidRootPart")
        or CharacterObject:FindFirstChild("Head")

    if not TargetPart or not TargetPart:IsA("BasePart") then return nil end

    local PredictionTime = math.clamp( (tonumber(Configuration.AimBot.Prediction) or 0) / 1000, 0, 0.30)

    local PositionValue = ResolveCombatPosition( PlayerObject, CharacterObject, TargetPart, PredictionTime, Configuration.AimBot ) or TargetPart.Position

    local DivisorX local DivisorY
    if AimMode == "Silent Aim" then
        DivisorX = math.max(tonumber(Configuration.AimBot.SilentPredictionDivisorX) or 1, 0.05)
        DivisorY = math.max(tonumber(Configuration.AimBot.SilentPredictionDivisorY) or 1, 0.05)
    else
        DivisorX = math.max(tonumber(Configuration.AimBot.AimbotPredictionDivisorX) or 1, 0.05)
        DivisorY = math.max(tonumber(Configuration.AimBot.AimbotPredictionDivisorY) or 1, 0.05)
    end
    local PredictionOffset = PositionValue - TargetPart.Position
    PositionValue = TargetPart.Position + Vector3.new( PredictionOffset.X / DivisorX, PredictionOffset.Y / DivisorY, PredictionOffset.Z / DivisorX)

    if HeadHitbox.GetEnabled() and TargetPart.Name == "Head" then
        local CameraObject = Internal.GetCamera() local AnchorPosition, UseScreenCoordinates = GetAimFOVAnchorPosition()
        local SelectionShotPoint = CameraObject and HeadHitbox.GetAimShotPoint(
            TargetPart,
            AnchorPosition,
            CameraObject,
            UseScreenCoordinates,
            nil,
            HeadHitbox.GetSizeValue()
        ) or TargetPart.Position
        local PredictionOffset = PositionValue - TargetPart.Position

        PositionValue = HeadHitbox.ClampToRealHead(
            TargetPart,
            SelectionShotPoint + PredictionOffset,
            HeadHitbox.SafetyMargin
        ) or TargetPart.Position
    end

    Configuration.AimBot.PositionCacheCharacter = CharacterObject
    Configuration.AimBot.PositionCacheValue = PositionValue
    Configuration.AimBot.PositionCacheMode = AimMode
    Configuration.AimBot.LastPositionUpdate = CurrentTime

    return PositionValue
end

function GetAimSmoothAlpha(Axis)
    local Value
    if Axis == "Y" then
        Value = Configuration.AimBot.SmoothnessY
    else
        Value = Configuration.AimBot.SmoothnessX
    end
    return math.clamp(tonumber(Value) or tonumber(Configuration.AimBot.Smoothness) or 0.1, 0.01, 1)
end

function SmoothAim(TargetPosition)
    if not TargetPosition then return end

    local CameraObject = Internal.GetCamera() if not CameraObject then return end

    local CurrentCFrame = CameraObject.CFrame local TargetDelta = TargetPosition - CurrentCFrame.Position
    if TargetDelta.Magnitude <= 0.001 then return end

    local CurrentDirection = CurrentCFrame.LookVector.Unit local TargetDirection = TargetDelta.Unit
    local CurrentYaw = math.atan2(-CurrentDirection.X, -CurrentDirection.Z) local TargetYaw = math.atan2(-TargetDirection.X, -TargetDirection.Z)
    local CurrentPitch = math.asin(math.clamp(CurrentDirection.Y, -1, 1)) local TargetPitch = math.asin(math.clamp(TargetDirection.Y, -1, 1))
    local YawDelta = math.atan2(math.sin(TargetYaw - CurrentYaw), math.cos(TargetYaw - CurrentYaw)) local NewYaw = CurrentYaw + YawDelta * GetAimSmoothAlpha("X")
    local NewPitch = CurrentPitch + (TargetPitch - CurrentPitch) * GetAimSmoothAlpha("Y") local CosPitch = math.cos(NewPitch)
    local Direction = Vector3.new( -math.sin(NewYaw) * CosPitch, math.sin(NewPitch), -math.cos(NewYaw) * CosPitch)
    CameraObject.CFrame = CFrame.lookAt(CurrentCFrame.Position, CurrentCFrame.Position + Direction)
end

function AimLoop()
    if not Configuration.AimBot.Enabled then return end

    if not Configuration.AimBot.AimbotEnabled then
        Configuration.AimBot.AimActive = false
        Configuration.AimBot.CurrentTarget = nil
        ResetAimbotTargetLock()
        return
    end

    local CurrentTarget local Character local TargetPart

    if Configuration.AimBot.LockTarget == true and Configuration.AimBot.AimbotLockedTarget then
        local Distance
        Distance, Character, TargetPart = GetAimTargetScore(Configuration.AimBot.AimbotLockedTarget)

        if Distance and Character and TargetPart then
            CurrentTarget = Configuration.AimBot.AimbotLockedTarget
        else
            ResetAimbotTargetLock()
        end
    end

    if not CurrentTarget then
        CurrentTarget = GetClosestPlayer()

        if CurrentTarget then Character, TargetPart = GetAimTargetData(CurrentTarget) end

        if CurrentTarget and Configuration.AimBot.LockTarget == true then Configuration.AimBot.AimbotLockedTarget = CurrentTarget end
    end

    Configuration.AimBot.CurrentTarget = CurrentTarget
    if not Configuration.AimBot.AimActive or not CurrentTarget or not Character or not TargetPart then return end

    local TargetPosition = GetTargetPosition(Character, CurrentTarget, "Aimbot")
    if TargetPosition and IsAimTargetVisible(Character, TargetPosition) then SmoothAim(TargetPosition) end
end

SilentAimController = SilentAimController or { Connection = nil, Visualize = nil, LastShotCode = nil, LastShotTime = 0, LastTarget = nil,
    LastPart = nil, PendingShots = {}, PendingLifetime = 1.25, LastPacketDirection = nil, LastPacketOrigin = nil, LastPacketTargetPosition = nil,
    ProjectileSpeedCache = {}, ProjectileConnection = nil, LastProjectileProbe = nil, LastProjectileProfile = nil, ChanceSequence = 0 }

SilentAimController.PendingShots = type(SilentAimController.PendingShots) == "table" and SilentAimController.PendingShots or {}
SilentAimController.ChanceSequence = math.max(math.floor(tonumber(SilentAimController.ChanceSequence) or 0), 0)

function GetCriminologyProjectileNameHint(Tool)
    if not Tool then return false, "" end

    local Name = string.lower( tostring( Tool.Name or "" ))

    local Hints = { "rpg", "rocket", "missile", "launcher", "snow", "snowball", "grenade", "projectile", "bow", "crossbow", "flare", "harpoon" }

    for Index = 1, #Hints do
        if string.find( Name, Hints[Index], 1, true ) then return true, Name end
    end

    return false, Name
end

function FindCriminologyProjectileNumber(Container, Wanted, Depth, Seen)
    if type(Container) ~= "table" or Depth > 3 then return nil, nil end

    Seen = Seen or {}

    if Seen[Container] then return nil, nil end

    Seen[Container] = true

    local BestValue local BestScore = -math.huge local BestName

    for Key, Value in pairs( Container ) do
        local Name = string.lower( tostring(Key))

        if type(Value) == "number" and Value == Value then
            local Score = -math.huge

            if Wanted == "Speed" then
                if string.find(Name, "projectilespeed", 1, true) then
                    Score = 100
                elseif string.find(Name, "muzzlevelocity", 1, true) then
                    Score = 96
                elseif string.find(Name, "bulletvelocity", 1, true) then
                    Score = 94
                elseif string.find(Name, "launchvelocity", 1, true) then
                    Score = 92
                elseif string.find(Name, "rocketspeed", 1, true) then
                    Score = 90
                elseif string.find(Name, "travelspeed", 1, true) then
                    Score = 88
                elseif string.find(Name, "velocity", 1, true) then
                    Score = 72
                elseif string.find(Name, "speed", 1, true) and not string.find(Name, "reload", 1, true) and not string.find(Name, "equip", 1, true)
                    and not string.find(Name, "walk", 1, true) and not string.find(Name, "anim", 1, true) and not string.find(Name, "fire", 1, true)
                then
                    Score = 52
                end

                if Value < 8 or Value > 3000 then Score = -math.huge end
            else
                if string.find(Name, "projectilegravity", 1, true) then
                    Score = 100
                elseif string.find(Name, "gravity", 1, true) then
                    Score = 85
                elseif string.find(Name, "drop", 1, true) then
                    Score = 65
                end

                if Value < 0 or Value > 1000 then Score = -math.huge end
            end

            if Score > BestScore then
                BestScore = Score

                BestValue = Value

                BestName = Name
            end
        elseif type(Value) == "table" then
            local Nested, NestedName = FindCriminologyProjectileNumber( Value, Wanted, Depth + 1, Seen)

            if Nested ~= nil then
                local NestedScore = 45

                if NestedScore > BestScore then
                    BestScore = NestedScore

                    BestValue = Nested

                    BestName = NestedName
                end
            end
        end
    end

    return BestValue, BestName
end

function GetCriminologyProjectileInstanceNumber(Tool, Wanted)
    if not Tool then return nil, nil end

    local BestValue local BestScore = -math.huge local BestName

    local function Test(Name, Value)
        Value = tonumber(Value)

        if not Value then return end

        local LowerName = string.lower(tostring(Name))

        local Score = -math.huge

        if Wanted == "Speed" then
            if string.find(LowerName, "projectilespeed", 1, true) or string.find(LowerName, "muzzlevelocity", 1, true)
                or string.find(LowerName, "bulletvelocity", 1, true)
            then
                Score = 100
            elseif string.find(LowerName, "velocity", 1, true) then
                Score = 80
            elseif string.find(LowerName, "speed", 1, true) and not string.find(LowerName, "fire", 1, true) then
                Score = 60
            end

            if Value < 8 or Value > 3000 then Score = -math.huge end
        else
            if string.find(LowerName, "gravity", 1, true) then
                Score = 100
            elseif string.find(LowerName, "drop", 1, true) then
                Score = 70
            end

            if Value < 0 or Value > 1000 then Score = -math.huge end
        end

        if Score > BestScore then
            BestScore = Score

            BestValue = Value

            BestName = LowerName
        end
    end

    local Attributes = Tool:GetAttributes()

    for Name, Value in pairs( Attributes ) do
        Test( Name, Value)
    end

    local Values = Tool:FindFirstChild( "Values")

    if Values then
        for _, Object in ipairs( Values:GetDescendants() ) do
            if Object:IsA("NumberValue") or Object:IsA("IntValue") then Test( Object.Name, Object.Value) end
        end
    end

    return BestValue, BestName
end

function GetCriminologyProjectileProfile(Tool, SpeedHint)
    if not Tool or not Tool:IsA("Tool") then return { IsProjectile = false } end

    local NameHint, LowerName = GetCriminologyProjectileNameHint( Tool)

    local Config = type(Ragebot.GetWeaponConfig) == "function" and Ragebot.GetWeaponConfig( Tool ) or nil

    local ConfigSpeed, ConfigSpeedName = FindCriminologyProjectileNumber( Config, "Speed", 0, {})

    local ConfigGravity, ConfigGravityName = FindCriminologyProjectileNumber( Config, "Gravity", 0, {})

    local InstanceSpeed, InstanceSpeedName = GetCriminologyProjectileInstanceNumber( Tool, "Speed")

    local InstanceGravity, InstanceGravityName = GetCriminologyProjectileInstanceNumber( Tool, "Gravity")

    local Cached = SilentAimController.ProjectileSpeedCache[ tostring( Tool.Name ) ]

    local Speed = tonumber(Cached) or tonumber(ConfigSpeed) or tonumber(InstanceSpeed)

    local Hint = tonumber(SpeedHint)

    if NameHint and Hint and Hint >= 8 and Hint <= 3000 then Speed = Hint end

    local ExplicitProjectile = NameHint == true

    if type(Config) == "table" then
        local Hitscan = rawget(Config, "Hitscan")
        local Projectile = rawget(Config, "Projectile")
        local ProjectileType = rawget(Config, "ProjectileType")
        local ProjectileClass = rawget(Config, "ProjectileClass")

        if Hitscan == false or Projectile == true or type(Projectile) == "table" or ProjectileType ~= nil or ProjectileClass ~= nil then
            ExplicitProjectile = true
        elseif Hitscan == true then
            ExplicitProjectile = false
        end
    end

    local ProjectileAttribute = Tool:GetAttribute("Projectile")
    local HitscanAttribute = Tool:GetAttribute("Hitscan")
    if ProjectileAttribute == true then ExplicitProjectile = true end
    if HitscanAttribute == true then ExplicitProjectile = false end

    if not ExplicitProjectile then return { IsProjectile = false } end

    if not Speed then
        if string.find(LowerName, "rpg", 1, true) or string.find(LowerName, "rocket", 1, true) or string.find(LowerName, "missile", 1, true) then
            Speed = 120
        elseif string.find(LowerName, "snow", 1, true) then
            Speed = 82
        elseif string.find(LowerName, "bow", 1, true) then
            Speed = 145
        elseif string.find(LowerName, "grenade", 1, true) then
            Speed = 88
        else
            Speed = 110
        end
    end

    local Gravity = tonumber(ConfigGravity) or tonumber(InstanceGravity)

    if Gravity == nil then
        if string.find(LowerName, "rpg", 1, true) or string.find(LowerName, "rocket", 1, true) or string.find(LowerName, "missile", 1, true) then
            Gravity = 0
        elseif string.find(LowerName, "snow", 1, true) or string.find(LowerName, "grenade", 1, true) or string.find(LowerName, "bow", 1, true) then
            Gravity = workspace.Gravity
        else
            Gravity = 0
        end
    elseif Gravity > 0 and Gravity <= 5 and ( ConfigGravityName and string.find( ConfigGravityName, "gravity", 1, true ) ) then
        Gravity = workspace.Gravity * Gravity
    end

    local Profile = { IsProjectile = true, Speed = math.clamp( tonumber(Speed) or 110, 8, 3000 ), Gravity = math.clamp( tonumber(Gravity) or 0, 0,
                1000 ), SpeedSource = Cached and "observed" or ConfigSpeed and ( "config:" .. tostring( ConfigSpeedName ) ) or InstanceSpeed and (
                    "value:" .. tostring( InstanceSpeedName ) ) or Hint and "direction" or "fallback", GravitySource = ConfigGravity and ( "config:"
                .. tostring( ConfigGravityName ) ) or InstanceGravity and ( "value:" .. tostring( InstanceGravityName ) ) or "fallback" }

    SilentAimController.LastProjectileProfile = Profile

    return Profile
end

function GetCriminologyProjectileTargetVelocity(Data)
    if type(Data) ~= "table" then return Vector3.zero end

    local Character = Data.TargetCharacter

    local PlayerObject = Data.TargetPlayer

    local Part = Data.TargetPart

    local Velocity

    if type(ResolverGetMovementVelocity) == "function" and PlayerObject and Character then
        local Resolved = ResolverGetMovementVelocity( PlayerObject, Character, Configuration.AimBot)

        if typeof(Resolved) == "Vector3" then Velocity = Resolved end
    end

    if typeof(Velocity) ~= "Vector3" and Part and Part:IsA("BasePart") then Velocity = Part.AssemblyLinearVelocity end

    if typeof(Velocity) ~= "Vector3" then return Vector3.zero end

    if Velocity.Magnitude > 220 then Velocity = Velocity.Unit * 220 end

    return Velocity
end

function SolveCriminologyProjectileIntercept(Origin, TargetPosition, TargetVelocity, Speed, Gravity)
    if typeof(Origin) ~= "Vector3" or typeof(TargetPosition) ~= "Vector3" or typeof(TargetVelocity) ~= "Vector3" then return nil end

    Speed = math.max( tonumber(Speed) or 0, 0.001)

    Gravity = math.max( tonumber(Gravity) or 0, 0)

    local Relative = TargetPosition - Origin

    local A = TargetVelocity:Dot( TargetVelocity) - Speed * Speed

    local B = 2 * Relative:Dot( TargetVelocity)

    local C = Relative:Dot( Relative)

    local Time

    if math.abs(A) <= 0.000001 then
        if math.abs(B) > 0.000001 then
            local Candidate = -C / B

            if Candidate > 0 then Time = Candidate end
        end
    else
        local Discriminant = B * B - 4 * A * C

        if Discriminant >= 0 then
            local Root = math.sqrt( Discriminant)

            local First = ( -B - Root ) / ( 2 * A)

            local Second = ( -B + Root ) / ( 2 * A)

            if First > 0 and Second > 0 then
                Time = math.min( First, Second)
            elseif First > 0 then
                Time = First
            elseif Second > 0 then
                Time = Second
            end
        end
    end

    if not Time then Time = Relative.Magnitude / Speed end

    Time = math.clamp( Time, 0, 4)

    local AimPosition

    for _ = 1, 3 do
        AimPosition = TargetPosition + TargetVelocity * Time + Vector3.new( 0, Gravity * 0.5 * Time * Time, 0)

        local Delta = AimPosition - Origin

        if Delta.Magnitude <= 0.001 then return nil end

        Time = math.clamp( Delta.Magnitude / Speed, 0, 4)
    end

    local Direction = AimPosition - Origin

    if Direction.Magnitude <= 0.001 then return nil end

    return { Direction = Direction.Unit, AimPosition = AimPosition, TravelTime = Time }
end

function InstallCriminologyProjectileObserver()
    if SilentAimController.ProjectileConnection then return end

    SilentAimController.ProjectileConnection = workspace.DescendantAdded:Connect( function(Object)
                local Probe = SilentAimController.LastProjectileProbe

                if type(Probe) ~= "table" or os.clock()
                        - ( tonumber(Probe.Time) or 0 ) > 0.35
                then
                    return
                end

                task.defer( function()
                        if not Object or not Object.Parent then return end

                        local Part

                        if Object:IsA("BasePart") then
                            Part = Object
                        elseif Object:IsA("Model") then
                            Part = Object.PrimaryPart or Object:FindFirstChildWhichIsA( "BasePart", true)
                        end

                        if not Part or not Part:IsA("BasePart") then return end

                        local ObjectName = string.lower(tostring(Object.Name) .. " " .. tostring(Object.Parent and Object.Parent.Name or ""))

                        local LooksProjectile = string.find(ObjectName, "projectile", 1, true) or string.find(ObjectName, "rocket", 1, true)
                            or string.find(ObjectName, "missile", 1, true) or string.find(ObjectName, "snow", 1, true) or string.find(ObjectName, "grenade", 1, true)
                            or string.find(ObjectName, "bullet", 1, true)

                        if not LooksProjectile then return end

                        local Distance = ( Part.Position - Probe.Origin ).Magnitude

                        if Distance > 28 then return end

                        local Velocity = Part.AssemblyLinearVelocity

                        local Speed = Velocity.Magnitude

                        if Speed < 8 or Speed > 3000 then return end

                        if typeof(Probe.Direction) == "Vector3" and Velocity.Magnitude > 0.001 and Velocity.Unit:Dot( Probe.Direction ) < 0.25 then return end

                        local Key = tostring( Probe.ToolName or "")

                        if Key == "" then return end

                        local Previous = tonumber( SilentAimController.ProjectileSpeedCache[ Key ])

                        SilentAimController.ProjectileSpeedCache[ Key ] = Previous and Previous * 0.65 + Speed * 0.35 or Speed
                    end)
            end)
end

function SilentAimGetMousePosition()
    return UserInputService:GetMouseLocation()
end

function SilentAimGetScreenPosition(WorldPosition)
    local CameraObject = Internal.GetCamera()
    if not CameraObject or typeof(WorldPosition) ~= "Vector3" then return nil, false end

    local Screen, OnScreen = CameraObject:WorldToViewportPoint(WorldPosition)
    return Vector2.new(Screen.X, Screen.Y), OnScreen and Screen.Z > 0
end

function GetCriminologySilentAimRayParams()
    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.IgnoreWater = true

    local Ignore = {}
    if LocalPlayer.Character then Ignore[#Ignore + 1] = LocalPlayer.Character end

    local Characters = workspace:FindFirstChild("Characters")
    if Characters then Ignore[#Ignore + 1] = Characters end

    local Debris = workspace:FindFirstChild("Debris")
    if Debris then Ignore[#Ignore + 1] = Debris end

    Parameters.FilterDescendantsInstances = Ignore
    return Parameters
end

function IsCriminologySilentAimDirectPathClear(Origin, TargetPosition)
    if typeof(Origin) ~= "Vector3" or typeof(TargetPosition) ~= "Vector3" then return false, nil end

    local Delta = TargetPosition - Origin
    if Delta.Magnitude <= 0.001 then return false, nil end

    local Result = workspace:Raycast(Origin, Delta, GetCriminologySilentAimRayParams())
    return Result == nil, Result
end

SilentAimHitboxDefinitions = {
    {Name = "Head", Parts = {"Head"}},
    {Name = "Chest", Parts = {"UpperTorso", "Torso"}},
    {Name = "Stomach", Parts = {"LowerTorso", "Torso", "HumanoidRootPart"}},
    {Name = "Root", Parts = {"HumanoidRootPart"}},
    {Name = "Left Arm", Parts = {"LeftUpperArm", "LeftLowerArm", "LeftHand", "Left Arm"}},
    {Name = "Right Arm", Parts = {"RightUpperArm", "RightLowerArm", "RightHand", "Right Arm"}},
    {Name = "Left Leg", Parts = {"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "Left Leg"}},
    {Name = "Right Leg", Parts = {"RightUpperLeg", "RightLowerLeg", "RightFoot", "Right Leg"}}
}

SilentAimHitboxLookup = {}
for Index = 1, #SilentAimHitboxDefinitions do
    local Definition = SilentAimHitboxDefinitions[Index]
    SilentAimHitboxLookup[Definition.Name] = Definition
end

function NormalizeCriminologySilentAimHitboxes(Value)
    local Output = {}
    local Seen = {}

    local function Add(Name)
        Name = tostring(Name or "")
        if Name ~= "" and SilentAimHitboxLookup[Name] and not Seen[Name] then
            Seen[Name] = true
            Output[#Output + 1] = Name
        end
    end

    if type(Value) == "string" then
        Add(Value)
    elseif type(Value) == "table" then
        for Index = 1, #Value do
            Add(Value[Index])
        end

        for Name, Enabled in pairs(Value) do
            if type(Name) == "string" and Enabled == true then
                Add(Name)
            end
        end
    end

    if #Output == 0 then Output[1] = "Head" end
    return Output
end

function GetCriminologySilentAimCandidates(Character)
    if not Character then return {} end

    local Selected = NormalizeCriminologySilentAimHitboxes(Configuration.AimBot.SilentHitboxes)
    Configuration.AimBot.SilentHitboxes = Selected

    local Candidates = {}
    local SeenParts = {}

    for GroupIndex = 1, #Selected do
        local GroupName = Selected[GroupIndex]
        local Definition = SilentAimHitboxLookup[GroupName]

        if Definition then
            for PartIndex = 1, #Definition.Parts do
                local Part = Character:FindFirstChild(Definition.Parts[PartIndex])

                if Part and Part:IsA("BasePart") and not SeenParts[Part] then
                    SeenParts[Part] = true
                    Candidates[#Candidates + 1] = {
                        Part = Part,
                        Group = GroupName,
                        Priority = GroupIndex
                    }
                end
            end
        end
    end

    if #Candidates == 0 then
        local Head = Character:FindFirstChild("Head")
        if Head and Head:IsA("BasePart") then
            Candidates[1] = {
                Part = Head,
                Group = "Head",
                Priority = 1
            }
        end
    end

    return Candidates
end

function GetCriminologySilentAimParts(Character)
    local Candidates = GetCriminologySilentAimCandidates(Character)
    local Parts = table.create(#Candidates)

    for Index = 1, #Candidates do
        Parts[Index] = Candidates[Index].Part
    end

    return Parts
end

function GetCriminologySilentAimSafePoint(Part, DesiredPosition, Margin)
    if not Part or not Part:IsA("BasePart") then return nil end

    DesiredPosition = typeof(DesiredPosition) == "Vector3" and DesiredPosition or Part.Position
    Margin = math.max(tonumber(Margin) or 0.035, 0)

    if Part.Name == "Head" and HeadHitbox.GetEnabled() then
        return HeadHitbox.ClampToRealHead(Part, DesiredPosition, math.max(HeadHitbox.SafetyMargin, Margin)) or Part.Position
    end

    local Half = Part.Size * 0.5
    local SafeHalf = Vector3.new(
        math.max(Half.X - Margin, 0),
        math.max(Half.Y - Margin, 0),
        math.max(Half.Z - Margin, 0)
    )
    local LocalPoint = Part.CFrame:PointToObjectSpace(DesiredPosition)

    return Part.CFrame:PointToWorldSpace(Vector3.new(
        math.clamp(LocalPoint.X, -SafeHalf.X, SafeHalf.X),
        math.clamp(LocalPoint.Y, -SafeHalf.Y, SafeHalf.Y),
        math.clamp(LocalPoint.Z, -SafeHalf.Z, SafeHalf.Z)
    ))
end

function GetCriminologySilentAimStablePoint(Part, DesiredPosition)
    if not Part or not Part:IsA("BasePart") then return nil end
    DesiredPosition = typeof(DesiredPosition) == "Vector3" and DesiredPosition or Part.Position
    local Half = Part.Size * 0.5
    local Margin = Part.Name == "Head" and 0.10 or 0.08
    local Scale = Part.Name == "Head" and 0.46 or 0.62
    local Safe = Vector3.new(
        math.max((Half.X - Margin) * Scale, 0),
        math.max((Half.Y - Margin) * Scale, 0),
        math.max((Half.Z - Margin) * Scale, 0)
    )
    local Point = Part.CFrame:PointToObjectSpace(DesiredPosition)
    return Part.CFrame:PointToWorldSpace(Vector3.new(
        math.clamp(Point.X, -Safe.X, Safe.X),
        math.clamp(Point.Y, -Safe.Y, Safe.Y),
        math.clamp(Point.Z, -Safe.Z, Safe.Z)
    ))
end

function GetCriminologySilentAimRayPartContact(Origin, Direction, Part)
    if typeof(Origin) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude <= 0.000001
        or not Part or not Part:IsA("BasePart")
    then
        return nil
    end

    local LocalOrigin = Part.CFrame:PointToObjectSpace(Origin)
    local LocalDirection = Part.CFrame:VectorToObjectSpace(Direction.Unit)
    local Half = Part.Size * 0.5
    local MinimumTime = -math.huge
    local MaximumTime = math.huge

    local function Axis(OriginValue, DirectionValue, HalfValue)
        if math.abs(DirectionValue) <= 0.000001 then
            return OriginValue >= -HalfValue and OriginValue <= HalfValue
        end

        local First = (-HalfValue - OriginValue) / DirectionValue
        local Second = (HalfValue - OriginValue) / DirectionValue
        if First > Second then First, Second = Second, First end
        MinimumTime = math.max(MinimumTime, First)
        MaximumTime = math.min(MaximumTime, Second)
        return MinimumTime <= MaximumTime
    end

    if not Axis(LocalOrigin.X, LocalDirection.X, Half.X)
        or not Axis(LocalOrigin.Y, LocalDirection.Y, Half.Y)
        or not Axis(LocalOrigin.Z, LocalDirection.Z, Half.Z)
    then
        return nil
    end

    local Time = MinimumTime >= 0 and MinimumTime or MaximumTime
    if Time < 0 or Time == math.huge or Time ~= Time then return nil end

    local Contact = Origin + Direction.Unit * Time
    return GetCriminologySilentAimSafePoint(Part, Contact, 0.025)
end

function GetCriminologySilentAimSelectionPosition(PlayerObject, Character, Part)
    if not PlayerObject or not Character or not Part or not Part:IsA("BasePart") then return nil end

    local PredictionTime = math.clamp((tonumber(Configuration.AimBot.Prediction) or 0) / 1000, 0, 0.30)
    local PositionValue = ResolveCombatPosition(PlayerObject, Character, Part, PredictionTime, Configuration.AimBot) or Part.Position
    local DivisorX = math.max(tonumber(Configuration.AimBot.SilentPredictionDivisorX) or 1, 0.05)
    local DivisorY = math.max(tonumber(Configuration.AimBot.SilentPredictionDivisorY) or 1, 0.05)
    local PredictionOffset = PositionValue - Part.Position

    local DesiredPosition = Part.Position + Vector3.new(
        PredictionOffset.X / DivisorX,
        PredictionOffset.Y / DivisorY,
        PredictionOffset.Z / DivisorX
    )

    return GetCriminologySilentAimStablePoint(Part, DesiredPosition)
        or GetCriminologySilentAimSafePoint(Part, DesiredPosition, 0.08)
        or Part.Position
end

function GetCriminologySilentAimPartPosition(PlayerObject, Character, Part)
    if not PlayerObject or not Character or not Part or not Part:IsA("BasePart") then return nil end

    local PredictionTime = math.clamp((tonumber(Configuration.AimBot.Prediction) or 0) / 1000, 0, 0.30)
    local PositionValue = ResolveCombatPosition(
        PlayerObject,
        Character,
        Part,
        PredictionTime,
        Configuration.AimBot
    ) or Part.Position

    local DivisorX = math.max(tonumber(Configuration.AimBot.SilentPredictionDivisorX) or 1, 0.05)
    local DivisorY = math.max(tonumber(Configuration.AimBot.SilentPredictionDivisorY) or 1, 0.05)
    local PredictionOffset = PositionValue - Part.Position

    return Part.Position + Vector3.new(
        PredictionOffset.X / DivisorX,
        PredictionOffset.Y / DivisorY,
        PredictionOffset.Z / DivisorX
    )
end

function GetCriminologySilentAimTarget()
    local CameraObject = Internal.GetCamera()
    if not CameraObject then return nil, nil, nil end

    local MousePosition = SilentAimGetMousePosition()
    local Radius = math.max(tonumber(Configuration.AimBot.FOV) or 120, 1)
    local RayParameters = Configuration.AimBot.SilentWallbang ~= true and GetCriminologySilentAimRayParams() or nil
    local SelectionMode = tostring(Configuration.AimBot.SilentHitboxMode or "Closest")

    if SelectionMode ~= "Closest" and SelectionMode ~= "Priority" then
        SelectionMode = "Closest"
    end

    local PriorityWindow = 12

    local function EvaluateCandidate(PlayerObject, Character, Candidate)
        if type(Candidate) ~= "table" then return nil end

        local TargetPart = Candidate.Part
        if not TargetPart or not TargetPart:IsA("BasePart") or not TargetPart.Parent then return nil end

        local SelectionPosition = GetCriminologySilentAimSelectionPosition(PlayerObject, Character, TargetPart)
        if typeof(SelectionPosition) ~= "Vector3" then return nil end

        local ScreenPosition, OnScreen = CameraObject:WorldToViewportPoint(SelectionPosition)
        if not OnScreen or ScreenPosition.Z <= 0 then return nil end

        local Distance = (MousePosition - Vector2.new(ScreenPosition.X, ScreenPosition.Y)).Magnitude
        if Distance >= Radius then return nil end

        local AimPosition = GetCriminologySilentAimPartPosition(PlayerObject, Character, TargetPart)
        if typeof(AimPosition) ~= "Vector3" then return nil end

        if RayParameters then
            local Origin = CameraObject.CFrame.Position
            local Result = workspace:Raycast(Origin, AimPosition - Origin, RayParameters)

            if Result and not Result.Instance:IsDescendantOf(Character) then
                return nil
            end
        end

        return {
            Distance = Distance,
            Character = Character,
            Part = TargetPart,
            Position = AimPosition,
            Group = Candidate.Group,
            Priority = tonumber(Candidate.Priority) or math.huge
        }
    end

    local function EvaluateTarget(PlayerObject)
        if PlayerObject == LocalPlayer or not IsCombatTargetAllowed(PlayerObject) then return nil end

        local Character = ResolveTrackedCharacter(PlayerObject, PlayerObject.Character) or PlayerObject.Character
        local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

        if not Character or not Humanoid or Humanoid.Health <= 0 then return nil end
        if not CombatChecks.Passes(PlayerObject, Character, Configuration.AimBot) then return nil end

        local Candidates = GetCriminologySilentAimCandidates(Character)
        local Valid = {}
        local ClosestDistance = Radius

        for Index = 1, #Candidates do
            local Result = EvaluateCandidate(PlayerObject, Character, Candidates[Index])

            if Result then
                Valid[#Valid + 1] = Result
                if Result.Distance < ClosestDistance then
                    ClosestDistance = Result.Distance
                end
            end
        end

        if #Valid == 0 then return nil end

        local Best

        if SelectionMode == "Closest" then
            for Index = 1, #Valid do
                local Result = Valid[Index]

                if not Best or Result.Distance < Best.Distance then
                    Best = Result
                end
            end
        else
            local MaximumPriorityDistance = ClosestDistance + PriorityWindow

            for Index = 1, #Valid do
                local Result = Valid[Index]

                if Result.Distance <= MaximumPriorityDistance then
                    if not Best
                        or Result.Priority < Best.Priority
                        or (Result.Priority == Best.Priority and Result.Distance < Best.Distance)
                    then
                        Best = Result
                    end
                end
            end

            if not Best then
                for Index = 1, #Valid do
                    local Result = Valid[Index]

                    if not Best or Result.Distance < Best.Distance then
                        Best = Result
                    end
                end
            end
        end

        if not Best then return nil end

        return Best.Distance, Best.Character, Best.Part, Best.Position
    end

    if Configuration.AimBot.LockTarget == true and Configuration.AimBot.SilentAimLockedTarget then
        local Distance, Character, TargetPart, AimPosition = EvaluateTarget(Configuration.AimBot.SilentAimLockedTarget)

        if Distance and Character and TargetPart then
            return Configuration.AimBot.SilentAimLockedTarget, Character, TargetPart, AimPosition
        end

        ResetSilentAimTargetLock()
    end

    local ClosestPlayer
    local ClosestCharacter
    local ClosestPart
    local ClosestAimPosition
    local ClosestDistance = Radius

    for _, PlayerObject in ipairs(Players:GetPlayers()) do
        local Distance, Character, TargetPart, AimPosition = EvaluateTarget(PlayerObject)

        if Distance and Distance < ClosestDistance then
            ClosestDistance = Distance
            ClosestPlayer = PlayerObject
            ClosestCharacter = Character
            ClosestPart = TargetPart
            ClosestAimPosition = AimPosition
        end
    end

    if ClosestPlayer and Configuration.AimBot.LockTarget == true then
        Configuration.AimBot.SilentAimLockedTarget = ClosestPlayer
    end

    return ClosestPlayer, ClosestCharacter, ClosestPart, ClosestAimPosition
end

function GetCriminologySilentAimChanceRoll(Tool, ShotCode, Salt)
    local Key = ShotCode ~= nil and tostring(ShotCode) or ""

    if Key == "" then
        SilentAimController.ChanceSequence = (tonumber(SilentAimController.ChanceSequence) or 0) + 1
        Key = tostring(SilentAimController.ChanceSequence)
    end

    if Tool then Key ..= ":" .. tostring(Tool.Name or "") end
    Key ..= ":" .. tostring(Salt or "roll")

    local Hash = 17
    for Index = 1, #Key do
        Hash = (Hash * 131 + string.byte(Key, Index)) % 1000003
    end

    return (Hash % 10000) / 100
end

function GetCriminologySilentAimShotChance(Tool, ShotCode)
    local FixedChance = math.clamp(tonumber(Configuration.AimBot.SilentHitChance) or 100, 0, 100)

    if Configuration.AimBot.SilentRandomHitChance ~= true then
        return FixedChance
    end

    local Minimum = math.clamp(tonumber(Configuration.AimBot.SilentRandomHitChanceMin) or 70, 0, 100)
    local Maximum = math.clamp(tonumber(Configuration.AimBot.SilentRandomHitChanceMax) or 100, 0, 100)

    if Minimum > Maximum then
        Minimum, Maximum = Maximum, Minimum
    end

    if Maximum <= Minimum then
        return Minimum
    end

    local RandomUnit = GetCriminologySilentAimChanceRoll(Tool, ShotCode, "chance") / 100
    return Minimum + (Maximum - Minimum) * RandomUnit
end

function ShouldSilentAimRedirect(Tool, ShotCode)
    local Chance = GetCriminologySilentAimShotChance(Tool, ShotCode)

    if Chance >= 100 then return true end
    if Chance <= 0 then return false end

    return GetCriminologySilentAimChanceRoll(Tool, ShotCode, "roll") < Chance
end

function GetCriminologySilentAimBulletCount(Tool, BulletsPerShot)
    local Count

    if type(BulletsPerShot) == "table" then
        Count = #BulletsPerShot
    elseif type(BulletsPerShot) == "number" then
        Count = BulletsPerShot
    end

    if not Count and type(GetRageBulletsPerShot) == "function" then Count = GetRageBulletsPerShot(Tool) end

    if not Count and type(Ragebot.GetWeaponConfig) == "function" then
        local Config = Ragebot.GetWeaponConfig(Tool)
        if type(Config) == "table" then
            Count = tonumber(Config.BulletsPerShot) or tonumber(Config.PelletsPerShot) or tonumber(Config.Pellets) or tonumber(Config.ProjectileCount)
        end
    end

    return math.clamp(math.floor(tonumber(Count) or 1), 1, 32)
end

function ResolveCriminologySilentAimShotCode(ShotCode, ...)
    if type(ShotCode) == "string" and #ShotCode > 0 then return ShotCode end

    local Arguments = table.pack(...)
    for Index = 1, Arguments.n do
        local Value = Arguments[Index]
        if type(Value) == "string" and Value ~= "FDS9I83" and #Value >= 12 then return Value end
    end

    return nil
end

function CleanupCriminologySilentAimPending()
    local Pending = SilentAimController.PendingShots

    if type(Pending) ~= "table" then
        SilentAimController.PendingShots = {}
        return
    end

    local Now = os.clock() local Lifetime = math.max( tonumber(SilentAimController.PendingLifetime) or 0.85, 0.20)

    for Key, Data in pairs(Pending) do
        local Part = type(Data) == "table" and Data.TargetPart or nil

        if type(Data) ~= "table" or Now
                - ( tonumber(Data.Time) or 0 ) > Lifetime or not Part or not Part.Parent
        then
            Pending[Key] = nil
        end
    end
end

function GetCriminologySilentAimPending(ShotCode)
    if ShotCode == nil then return nil end

    CleanupCriminologySilentAimPending()

    local Data = SilentAimController.PendingShots[ tostring(ShotCode) ]

    if type(Data) ~= "table" then return nil end

    local PlayerObject = Data.TargetPlayer

    local Character = Data.TargetCharacter

    local Part = Data.TargetPart

    local Humanoid = Character and Character:FindFirstChildOfClass( "Humanoid")

    if not PlayerObject or not Character or Character
            ~= PlayerObject.Character or not Humanoid or Humanoid.Health <= 0 or not Part or not Part:IsA("BasePart") or not Part:IsDescendantOf(
            Character ) or not IsCombatTargetAllowed( PlayerObject)
    then
        SilentAimController.PendingShots[ tostring(ShotCode) ] = nil

        return nil
    end

    return Data
end

function CreateCriminologySilentAimPending(ShotCode, Tool)
    local Existing = GetCriminologySilentAimPending( ShotCode)

    if Existing then return Existing end

    if not Tool or not Tool:IsA("Tool") or Tool.Parent
            ~= LocalPlayer.Character
    then
        return nil
    end

    if not ShouldSilentAimRedirect(Tool, ShotCode) then return nil end

    local TargetPlayer, TargetCharacter, TargetPart, TargetAimPosition = GetCriminologySilentAimTarget()

    if not TargetPlayer or not TargetCharacter or not TargetPart or not TargetPart.Parent then return nil end

    local Humanoid = TargetCharacter:FindFirstChildOfClass( "Humanoid")

    if not Humanoid or Humanoid.Health <= 0 then return nil end

    local Data = { ShotCode = ShotCode ~= nil and tostring(ShotCode) or nil, Tool = Tool, TargetPlayer = TargetPlayer, TargetCharacter =
            TargetCharacter, TargetPart = TargetPart, PartName = TargetPart.Name, TargetAimPosition = TargetAimPosition, HbeTarget = false, Time = os.clock(), PacketSeen = false, VisualizeSeen = false,
        BulletCount = GetCriminologySilentAimBulletCount(Tool, nil) }

    if Data.ShotCode then SilentAimController.PendingShots[ Data.ShotCode ] = Data end

    SilentAimController.LastTarget = TargetPlayer

    SilentAimController.LastPart = TargetPart

    Configuration.AimBot.CurrentTarget = TargetPlayer

    return Data
end

function ResolveCriminologySilentAimPending(ShotCode, Tool)
    return GetCriminologySilentAimPending( ShotCode ) or CreateCriminologySilentAimPending( ShotCode, Tool)
end

function GetCriminologySilentAimPacketSolution(Data, Origin)
    if type(Data) ~= "table" or typeof(Origin) ~= "Vector3" then return nil end
    local Part = Data.TargetPart
    local Character = Data.TargetCharacter
    local PlayerObject = Data.TargetPlayer
    if not Part or not Part:IsA("BasePart") or not Part.Parent or not Character or not Character.Parent then return nil end

    if Configuration.AimBot.SilentProjectilePrediction ~= false then
        local Profile = GetCriminologyProjectileProfile(Data.Tool, Data.OriginalDirectionMagnitude)
        if type(Profile) == "table" and Profile.IsProjectile == true then
            local Time = math.clamp((tonumber(Configuration.AimBot.Prediction) or 0) / 1000, 0, 0.30)
            local Base = ResolveCombatPosition(PlayerObject, Character, Part, Time, Configuration.AimBot) or Part.Position
            local Velocity = GetCriminologyProjectileTargetVelocity(Data)
            local Ballistic = SolveCriminologyProjectileIntercept(Origin, Base, Velocity, Profile.Speed, Profile.Gravity)
            if Ballistic then
                return {
                    Origin = Origin,
                    Direction = Ballistic.Direction.Unit,
                    TargetPosition = Ballistic.AimPosition,
                    ImpactTargetPosition = Base + Velocity * Ballistic.TravelTime,
                    Route = nil,
                    Wallbang = false,
                    Projectile = true,
                    ProjectileSpeed = Profile.Speed,
                    ProjectileGravity = Profile.Gravity,
                    ProjectileTravelTime = Ballistic.TravelTime,
                    ProjectileProfile = Profile
                }
            end
        end
    end

    local TargetPosition = GetCriminologySilentAimSelectionPosition(PlayerObject, Character, Part)
        or GetCriminologySilentAimStablePoint(Part, Part.Position)
        or Part.Position
    local Delta = TargetPosition - Origin
    if Delta.Magnitude <= 0.001 then return nil end

    if IsCriminologySilentAimDirectPathClear(Origin, TargetPosition) then
        local Direction = Delta.Unit
        local Registration = GetCriminologySilentAimRayPartContact(Origin, Direction, Part)
            or GetCriminologySilentAimStablePoint(Part, TargetPosition)
            or Part.Position
        return {
            Origin = Origin,
            Direction = Direction,
            TargetPosition = TargetPosition,
            RegistrationPosition = Registration,
            Route = nil,
            Wallbang = false,
            Projectile = false
        }
    end

    local Center = GetCriminologySilentAimStablePoint(Part, Part.Position) or Part.Position
    local CenterDelta = Center - Origin
    if CenterDelta.Magnitude > 0.001 and IsCriminologySilentAimDirectPathClear(Origin, Center) then
        local Direction = CenterDelta.Unit
        local Registration = GetCriminologySilentAimRayPartContact(Origin, Direction, Part) or Center
        return {
            Origin = Origin,
            Direction = Direction,
            TargetPosition = Center,
            RegistrationPosition = Registration,
            Route = nil,
            Wallbang = false,
            Projectile = false
        }
    end

    if Configuration.AimBot.SilentWallbang ~= true or not Ragebot or type(Ragebot.ScanOrigins) ~= "function" then return nil end
    local Route = Ragebot.ScanOrigins(Part, Origin)
    if type(Route) ~= "table" or typeof(Route.Origin) ~= "Vector3" or typeof(Route.Hit) ~= "Vector3" then return nil end
    if (Route.Origin - Origin).Magnitude > 19.001 then return nil end

    local Direction = typeof(Route.PacketDirection) == "Vector3" and Route.PacketDirection or Route.Hit - Route.Origin
    if Direction.Magnitude <= 0.001 then return nil end
    Direction = Direction.Unit

    if Route.BlindOrbit ~= true then
        local TargetCharacter = Part:FindFirstAncestorOfClass("Model") or Part.Parent
        if not select(1, Ragebot.ValidateFibonacci(Route.Origin, Route.Hit, TargetCharacter)) then return nil end
    end

    local Registration = GetCriminologySilentAimRayPartContact(Route.Origin, Direction, Part)
        or GetCriminologySilentAimStablePoint(Part, Part.Position)
        or Part.Position

    return {
        Origin = Route.Origin,
        Direction = Direction,
        TargetPosition = Registration,
        RegistrationPosition = Registration,
        RouteHitPosition = Route.Hit,
        Route = Route,
        Wallbang = true,
        Projectile = false
    }
end

function GetCriminologySilentAimPacketDirection(Data, Origin)
    local Solution = GetCriminologySilentAimPacketSolution( Data, Origin)

    if not Solution then return nil, nil end

    return Solution.Direction, Solution.TargetPosition
end

function IsAtramentaRageShotCode(ShotCode)
    if ShotCode == nil then return false end

    local Key = tostring(ShotCode)

    local Reported = Ragebot and type( Ragebot.ReportedShots ) == "table" and Ragebot.ReportedShots[ Key ] or nil

    if type(Reported) == "table" and tostring( Reported.Source or "" ) == "RageBot" then return true end

    local Pending = Ragebot.Runtime and Ragebot.Runtime.PendingShot or nil

    if type(Pending) == "table" and tostring( Pending.ShotId or "" ) == Key and tostring( Pending.Source or "RageBot" ) == "RageBot" then return true end

    return false
end

function TrySendCriminologySilentAimDamage(Data)
    if type(Data) ~= "table" or Data.DamageSent == true or Data.DamageSending == true or Data.PacketSeen ~= true then return false end

    if Data.Projectile == true then
        Data.DamageDeferredToProjectile = true

        return false
    end

    Data.DamageSending = true

    local Tool = Data.Tool

    local TargetPart = Data.TargetPart

    local TargetCharacter = Data.TargetCharacter

    if not Tool or not Tool:IsA("Tool") or Tool.Parent ~= LocalPlayer.Character or not TargetPart or not TargetPart:IsA("BasePart")
        or not TargetPart.Parent or not TargetCharacter or not TargetCharacter.Parent
    then
        Data.DamageSending = false

        return false
    end

    local Humanoid = TargetCharacter:FindFirstChildOfClass( "Humanoid")

    if Humanoid and Humanoid.Health <= 0 then
        Data.DamageSending = false

        return false
    end

    local Direction = Data.PacketDirection
    local TargetPosition = Data.ShotRegistrationPosition or Data.RegistrationPosition or Data.PacketTargetPosition or Data.TargetPosition

    if typeof(Direction) ~= "Vector3" or Direction.Magnitude <= 0.001 or typeof(TargetPosition) ~= "Vector3" then
        Data.DamageSending = false

        return false
    end

    local Events = ReplicatedStorage:FindFirstChild( "Events")

    local DamageRemote = Events and ( Events:FindFirstChild( "ZFKLF__H" ) or Events:FindFirstChild( "ZFKLF_H" ))

    if not DamageRemote or not DamageRemote:IsA( "RemoteEvent" ) then
        Data.DamageSending = false

        return false
    end

    local DirectFireServer = DamageRemote.FireServer

    if type(DirectFireServer)
        ~= "function"
    then
        Data.DamageSending = false

        return false
    end

    local BulletCount = math.clamp( math.floor( tonumber(Data.BulletCount) or 1 ), 1, 32)

    local Marker = game.GameId == 1494262959 and "🧈" or "🍯"

    local DamageContext = { HIP = typeof( Data.HipContext ) == "Instance" and Data.HipContext or nil }

    local PacketDirections = type(Data.PacketDirections) == "table" and Data.PacketDirections or nil

    for BulletIndex = 1, BulletCount do
        local BulletDirection = PacketDirections and PacketDirections[BulletIndex] or Direction
        if typeof(BulletDirection) ~= "Vector3" or BulletDirection.Magnitude <= 0.001 then BulletDirection = Direction end
        BulletDirection = BulletDirection.Unit

        if game.GameId == 1494262959 then
            DirectFireServer(DamageRemote, Marker, Tool, Data.ShotCode, BulletIndex, TargetPart, TargetPosition, BulletDirection, DamageContext)
        else
            DirectFireServer(DamageRemote, Marker, math.huge, Tool, Data.ShotCode, BulletIndex, TargetPart, TargetPosition, BulletDirection, Tool, nil,
                19052023.49)
        end
    end

    Data.DamageSent = true

    Data.DamageSending = false

    Data.DamageSentAt = os.clock()
    if type(Data.Attack) == "table" then
        Data.Attack.DamagePacketSent = true
        Data.Attack.DamagePacketSentAt = Data.DamageSentAt
    end

    Data.DamageDirection = Direction

    Data.DamageTargetPosition = TargetPosition

    return true
end

function RedirectCriminologySilentAimPacket(Arguments)
    if type(checkcaller) == "function" and checkcaller() then return nil end
    if Configuration.AimBot.SilentEnabled ~= true or type(Arguments) ~= "table" then return nil end

    local Count = math.max( math.floor( tonumber(Arguments.n) or #Arguments ), 0)

    if Count < 6 or Arguments[4] ~= "FDS9I83" or typeof(Arguments[5]) ~= "Vector3" or type(Arguments[6]) ~= "table" then return nil end

    local Tool = Arguments[3]

    if typeof(Tool) ~= "Instance" or not Tool:IsA("Tool") or Tool.Parent ~= LocalPlayer.Character then return nil end

    local ShotCode = Arguments[2]

    if ShotCode == nil or IsAtramentaRageShotCode( ShotCode ) then return nil end

    local Data = ResolveCriminologySilentAimPending(ShotCode, Tool)

    if not Data then return nil end

    local OriginalOrigin = Arguments[5] local OriginalDirections = Arguments[6] local DirectionCount = #OriginalDirections

    if DirectionCount < 1 then return nil end

    local MaximumDirectionMagnitude = 0

    for Index = 1, DirectionCount do
        local OriginalDirection = OriginalDirections[Index]

        if typeof(OriginalDirection) == "Vector3" then MaximumDirectionMagnitude = math.max( MaximumDirectionMagnitude, OriginalDirection.Magnitude) end
    end

    Data.OriginalDirectionMagnitude = MaximumDirectionMagnitude

    local Solution = GetCriminologySilentAimPacketSolution( Data, OriginalOrigin)

    if not Solution then return nil end

    local NewDirections = table.clone(OriginalDirections)
    local Replaced = 0
    local PrimaryPacketDirection

    for Index = 1, #NewDirections do
        if typeof(NewDirections[Index]) == "Vector3" then
            local PacketDirection = Solution.Direction.Unit
            NewDirections[Index] = PacketDirection
            PrimaryPacketDirection = PrimaryPacketDirection or PacketDirection
            Replaced += 1
        end
    end

    if Replaced <= 0 or #NewDirections ~= DirectionCount then return nil end

    for Index = 1, DirectionCount do
        if typeof( OriginalDirections[Index] ) ~= typeof( NewDirections[Index] ) then return nil end
    end

    local NewArguments = CloneNamecallArguments( Arguments)

    if not NewArguments then return nil end

    NewArguments[5] = Solution.Origin

    NewArguments[6] = NewDirections

    Data.Time = os.clock()
    Data.PacketSeen = true
    Data.PacketOriginalOrigin = OriginalOrigin
    Data.PacketOrigin = Solution.Origin
    Data.PacketDirection = (PrimaryPacketDirection or Solution.Direction).Unit
    Data.PacketDirections = NewDirections
    Data.PacketUnitDirection = Solution.Direction
    Data.PacketHbe = Data.HbeTarget == true
    Data.RegistrationPosition = Solution.RegistrationPosition
        or GetCriminologySilentAimRayPartContact(Solution.Origin, Solution.Direction, Data.TargetPart)
        or GetCriminologySilentAimStablePoint(Data.TargetPart, Solution.TargetPosition)
        or Data.TargetPart.Position
    Data.ShotRegistrationPosition = Data.RegistrationPosition
    Data.ShotTargetPart = Data.TargetPart
    Data.PacketTargetPosition = Data.RegistrationPosition
    Data.TargetPosition = Data.RegistrationPosition
    Data.RouteHitPosition = Solution.RouteHitPosition
    Data.DirectionCount = Replaced
    Data.Wallbang = Solution.Wallbang == true
    Data.Route = Solution.Route

    Data.Projectile = Solution.Projectile == true

    Data.ProjectileSpeed = Solution.ProjectileSpeed

    Data.ProjectileGravity = Solution.ProjectileGravity

    Data.ProjectileTravelTime = Solution.ProjectileTravelTime

    Data.ProjectileProfile = Solution.ProjectileProfile

    if Data.Projectile then
        InstallCriminologyProjectileObserver()

        SilentAimController.LastProjectileProbe = { Time = os.clock(), ToolName = Tool.Name, Origin = Solution.Origin, Direction = Solution.Direction,
            Speed = Solution.ProjectileSpeed }
    end

    if type(Internal.RegisterLocalAttack) == "function" then
        local Attack = Internal.RegisterLocalAttack(Data.TargetCharacter, Data.TargetPart, ShotCode, Tool, "SilentAim", Solution.Origin, Data.PacketDirection)

        if type(Attack) == "table" then
            Attack.RemoteSeen = true
            Attack.RemoteConfirmed = false
            Attack.RemoteConfirmedAt = nil

            Attack.TargetPositionAtFire = Data.RegistrationPosition
            Attack.HitPosition = Data.RegistrationPosition
            Attack.DamageHitPosition = Data.RegistrationPosition
            Attack.Direction = Data.PacketDirection
            Attack.PacketOrigin = Solution.Origin
            Attack.PacketDirection = Data.PacketDirection
            Attack.PacketRewritten = true
            Attack.SpreadBypassed = true
            Attack.Projectile = Data.Projectile == true
            Attack.ProjectileTravelTime = tonumber(Data.ProjectileTravelTime) or 0
            Attack.Wallbang = Data.Wallbang == true
            Attack.RouteHitPosition = Data.RouteHitPosition
            Attack.HeadExpander = Data.HbeTarget == true
            Attack.HbeEntryDistance = Data.HbeEntryDistance
            Attack.HbeVirtualPoint = Data.HbeVirtualPoint
            Attack.HbeShotPoint = Data.HbeShotPoint

            Data.Attack = Attack
        end
    end

    SilentAimController.LastShotCode = tostring( ShotCode)

    SilentAimController.LastShotTime = os.clock()

    SilentAimController.LastPacketDirection = Data.PacketDirection

    SilentAimController.LastPacketOrigin = Solution.Origin

    SilentAimController.LastPacketTargetPosition = Data.RegistrationPosition

    task.defer( TrySendCriminologySilentAimDamage, Data)

    return NewArguments, Data
end

function HeadHitbox.GetNormalShotScale()
    if not HeadHitbox.GetEnabled() then return 1 end
    return math.clamp(HeadHitbox.GetSizeValue(), 1, 15)
end

function HeadHitbox.FindNormalShotHbeTarget(RayOrigin, Directions, Scale, MaximumDistance)
    if typeof(RayOrigin) ~= "Vector3" or type(Directions) ~= "table" then return nil end

    Scale = math.clamp(tonumber(Scale) or HeadHitbox.GetNormalShotScale(), 1, 15)
    if Scale <= 1.001 then return nil end

    local BestTarget local BestDistance = math.huge

    for PlayerObject, Record in pairs(HeadHitbox.Runtime.Records) do
        if PlayerObject ~= LocalPlayer and IsCombatTargetAllowed(PlayerObject) and type(Record) == "table" then
            local Character = Record.Character local Humanoid = Record.Humanoid local Head = Record.Head

            if Character and Character.Parent and Humanoid and Humanoid.Health > 0
                and Head and Head:IsA("BasePart") and Head.Parent
                and CombatChecks.Passes(PlayerObject, Character, Configuration.AimBot)
            then
                for DirectionIndex = 1, #Directions do
                    local Direction = Directions[DirectionIndex]

                    if typeof(Direction) == "Vector3" and Direction.Magnitude > 0.001 then
                        local EntryDistance, VirtualPoint = HeadHitbox.GetRayIntersectionDistance(
                            RayOrigin, Direction, Head, Scale, MaximumDistance
                        )

                        if EntryDistance and EntryDistance < BestDistance then
                            local RealEntryDistance = HeadHitbox.GetRayIntersectionDistance(
                                RayOrigin, Direction, Head, 1, MaximumDistance
                            )

                            if not RealEntryDistance then
                                local ShotPoint = HeadHitbox.ClampToRealHead(
                                    Head, VirtualPoint, HeadHitbox.SafetyMargin
                                )

                                if ShotPoint and CombatChecks.IsVisible(
                                    RayOrigin, ShotPoint, PlayerObject, Character
                                ) then
                                    BestDistance = EntryDistance
                                    BestTarget = {
                                        Player = PlayerObject, Character = Character, Humanoid = Humanoid,
                                        Head = Head, VirtualPoint = VirtualPoint, ShotPoint = ShotPoint,
                                        EntryDistance = EntryDistance, DirectionIndex = DirectionIndex,
                                        OriginalDirection = Direction
                                    }
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    return BestTarget
end

function HeadHitbox.GetRealHeadContact(RayOrigin, Direction, Head)
    if typeof(RayOrigin) ~= "Vector3" or typeof(Direction) ~= "Vector3" or Direction.Magnitude <= 0.001
        or not Head or not Head:IsA("BasePart")
    then
        return nil, nil
    end

    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Include
    Parameters.FilterDescendantsInstances = {Head}
    Parameters.IgnoreWater = true
    Parameters.RespectCanCollide = false

    local Distance = (Head.Position - RayOrigin).Magnitude + math.max(Head.Size.Magnitude * 2, 4) local Result = workspace:Raycast(RayOrigin, Direction.Unit * Distance, Parameters)

    if Result and Result.Instance == Head then return Result.Position, Result.Normal end

    return nil, nil
end

function HeadHitbox.SendNormalShotHbeDamage(Data)
    if type(Data) ~= "table" or Data.Sent == true then return false end

    local Tool = Data.Tool local Head = Data.Head local Character = Data.Character local Direction = Data.Direction

    if not Tool or not Tool:IsA("Tool") or Tool.Parent ~= LocalPlayer.Character
        or not Head or not Head:IsA("BasePart") or not Head.Parent
        or not Character or not Character.Parent
        or typeof(Direction) ~= "Vector3" or Direction.Magnitude <= 0.001
    then
        return false
    end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Humanoid or Humanoid.Health <= 0 then return false end

    local HitPosition = Data.VirtualPoint

    if typeof(HitPosition) ~= "Vector3" then return false end

    local OriginalDirection = Data.OriginalDirection

    if Data.PacketRedirected ~= true
        and typeof(OriginalDirection) == "Vector3"
        and OriginalDirection.Magnitude > 0.001
    then
        local RayDirection = OriginalDirection.Unit local RayDistance = math.max(
            (HitPosition - Data.Origin):Dot(RayDirection),
            0
        )

        Data.VirtualPoint = Data.Origin + RayDirection * RayDistance
        HitPosition = Data.VirtualPoint
    end

    local CenterDelta = HitPosition - Head.Position local MaximumReportRadius = 1.45

    if CenterDelta.Magnitude > MaximumReportRadius then HitPosition = Head.Position + CenterDelta.Unit * MaximumReportRadius end

    local SurfaceNormal = -Direction.Unit local Events = ReplicatedStorage:FindFirstChild("Events") local DamageRemote = Events and (
        Events:FindFirstChild("ZFKLF__H")
        or Events:FindFirstChild("ZFKLF_H")
    )

    if not DamageRemote or not DamageRemote:IsA("RemoteEvent") then return false end

    local FireServer = DamageRemote.FireServer
    if type(FireServer) ~= "function" then return false end

    Data.Sent = true
    Data.HitPosition = HitPosition
    Data.SurfaceNormal = SurfaceNormal

    if game.GameId == 1494262959 then
        FireServer(DamageRemote, "🧈", Tool, Data.ShotCode, Data.BulletIndex, Head, HitPosition, SurfaceNormal, {HIP = nil}, nil)
    else
        FireServer(
            DamageRemote,
            "🍯",
            math.huge,
            Tool,
            Data.ShotCode,
            Data.BulletIndex,
            Head,
            HitPosition,
            Direction,
            Tool,
            nil,
            19052023.49
        )
    end

    local Attack = type(Internal.RegisterLocalAttack) == "function" and Internal.RegisterLocalAttack(
        Character,
        Head,
        Data.ShotCode,
        Tool,
        "HBE",
        Data.Origin,
        Direction
    ) or nil

    if type(Attack) == "table" then
        Attack.HeadExpander = true
        Attack.HbeNormalShot = true
        Attack.HbeRayPreserved = true
        Attack.HbeEntryDistance = Data.EntryDistance
        Attack.HbeVirtualPoint = Data.VirtualPoint
        Attack.HbeShotPoint = HitPosition
        Attack.HbeServerHitPosition = HitPosition
        Attack.HitPosition = Data.VirtualPoint
        Attack.VisualHitPosition = Data.VirtualPoint
        Attack.SurfaceNormal = SurfaceNormal
        Attack.PacketDirectionChanged = false
        Attack.DamagePacketSent = true
    end

    return true
end

function HeadHitbox.RedirectNormalShotPacket(Arguments)
    if not HeadHitbox.GetEnabled() or type(Arguments) ~= "table" then return nil end

    local Count = math.max(
        math.floor(tonumber(Arguments.n) or #Arguments),
        0
    )

    if Count < 6
        or Arguments[4] ~= "FDS9I83"
        or typeof(Arguments[5]) ~= "Vector3"
        or type(Arguments[6]) ~= "table"
    then
        return nil
    end

    local Tool = Arguments[3] local ShotCode = Arguments[2]

    if typeof(Tool) ~= "Instance"
        or not Tool:IsA("Tool")
        or Tool.Parent ~= LocalPlayer.Character
        or ShotCode == nil
        or IsAtramentaRageShotCode(ShotCode)
    then
        return nil
    end

    local Origin = Arguments[5] local Directions = Arguments[6]

    if #Directions < 1 then return nil end

    local Target = HeadHitbox.FindNormalShotHbeTarget(
        Origin,
        Directions,
        HeadHitbox.GetNormalShotScale(),
        5000
    )

    if not Target then return nil end

    local DirectionIndex = Target.DirectionIndex local OriginalDirection = Directions[DirectionIndex]

    if typeof(OriginalDirection) ~= "Vector3"
        or OriginalDirection.Magnitude <= 0.001
    then
        return nil
    end

    local ShotPoint = Target.ShotPoint
    if typeof(ShotPoint) ~= "Vector3" then return nil end

    local RedirectDelta = ShotPoint - Origin
    if RedirectDelta.Magnitude <= 0.001 then return nil end

    local RedirectedDirection = RedirectDelta.Unit local NewDirections = table.clone(Directions)
    NewDirections[DirectionIndex] = RedirectedDirection * OriginalDirection.Magnitude

    local NewArguments = CloneNamecallArguments(Arguments)
    if not NewArguments then return nil end

    NewArguments[6] = NewDirections

    local Data = {
        Tool = Tool,
        ShotCode = ShotCode,
        Origin = Origin,
        Direction = RedirectedDirection,
        OriginalDirection = OriginalDirection,
        BulletIndex = DirectionIndex,
        Player = Target.Player,
        Character = Target.Character,
        Head = Target.Head,
        VirtualPoint = Target.VirtualPoint,
        ShotPoint = ShotPoint,
        EntryDistance = Target.EntryDistance,
        Sent = false,
        RayPreserved = false,
        PacketRedirected = true
    }

    task.defer(function()
        HeadHitbox.SendNormalShotHbeDamage(Data)
    end)

    return NewArguments, Data
end

function HandleCriminologySilentAimVisualize(HipContext, ShotCode, ThirdArgument, Gun, FifthArgument, StartPosition, BulletsPerShot, ...)
    if Configuration.AimBot.SilentEnabled ~= true
        or HeadHitbox.GetEnabled()
    then
        return
    end

    local Character = LocalPlayer.Character

    if not Character then return end

    local Tool = typeof(Gun) == "Instance" and Gun:IsA("Tool") and Gun or Character:FindFirstChildWhichIsA( "Tool")

    if not Tool or Tool.Parent ~= Character then return end

    local ResolvedShotCode = ResolveCriminologySilentAimShotCode( ShotCode, ThirdArgument, Gun, FifthArgument, StartPosition, BulletsPerShot, ...)

    if type(ResolvedShotCode) ~= "string" then return end

    local Data = ResolveCriminologySilentAimPending( ResolvedShotCode, Tool)

    if not Data then return end

    local TargetPlayer = Data.TargetPlayer

    local TargetCharacter = Data.TargetCharacter

    local TargetPart = Data.TargetPart

    if not TargetPlayer or not TargetCharacter or not TargetPart or not TargetPart.Parent then return end

    local Humanoid = TargetCharacter:FindFirstChildOfClass( "Humanoid")

    if Humanoid and Humanoid.Health <= 0 then return end

    Data.Time = os.clock()
    Data.VisualizeSeen = true
    Data.HipContext = HipContext
    Data.BulletCount = GetCriminologySilentAimBulletCount( Tool, BulletsPerShot)

    SilentAimController.LastShotCode = ResolvedShotCode

    SilentAimController.LastShotTime = os.clock()

    SilentAimController.LastTarget = TargetPlayer

    SilentAimController.LastPart = TargetPart

    Configuration.AimBot.CurrentTarget = TargetPlayer

    task.defer( TrySendCriminologySilentAimDamage, Data)
end

function IsNoFallDamageActive()
    if NoFallDamageEnabled == true or Environment.AtramentaNoFallDamage == true then return true end
    local FarmSettings = type(AtramentaFarmModule) == "table" and AtramentaFarmModule.Settings or nil
    return type(FarmSettings) == "table" and FarmSettings.AntiFallDamage == true
end

function DisableSilentAimHooks()
    local FireState = rawget(Environment, "AtramentaSilentAimFireHook") local RaycastState = rawget(Environment, "AtramentaSilentAimRaycastHook")

    if type(FireState) == "table" then
        FireState.Handler = nil
        FireState.NamecallInstalled = false
    end

    if type(RaycastState) == "table" then
        RaycastState.Handler = nil
        RaycastState.Installed = false
        RaycastState.OldNamecall = nil
    end
end

function HandleAtramentaStompRemote(Self, Arguments)
    if type(Arguments) ~= "table" or Arguments[1] ~= "2389ZFX34" or typeof(Self) ~= "Instance" or not Self:IsA("RemoteEvent") then return false end

    local TargetCharacter = Arguments[9]

    if typeof(TargetCharacter) ~= "Instance" or not TargetCharacter:IsA("Model") then return false end

    local TargetPlayer = Players:GetPlayerFromCharacter( TargetCharacter)

    if not TargetPlayer or TargetPlayer == LocalPlayer then return false end

    local CurrentTime = os.clock()

    local Existing = HitFeedbackRuntimeState.FinishTokens[ TargetCharacter ]

    if type(Existing) == "table" and CurrentTime
            - ( tonumber(Existing.StompRemoteTime) or 0 ) <= 0.90
    then
        return true
    end

    local Downed = Internal.GetAtramentaDownedObject( TargetPlayer)

    local Token = { Player = TargetPlayer, Character = TargetCharacter, TargetWasDowned = Downed ~= nil and Downed.Value == true,
        FinishSoundPlayed = true, Source = "StompRemote", Remote = Self, StompRemoteTime = CurrentTime, FinishConfirmedAt = CurrentTime }

    HitFeedbackRuntimeState.FinishTokens[ TargetCharacter ] = Token

    task.defer( Internal.PlayConfirmedFinishSound)

    return true
end

function InstallSharedNamecallRouter()
    if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then return false end
    local State = rawget(Environment, "AtramentaSharedNamecallRouter")

    if type(State) ~= "table" then
        State = { Installed = false, OldNamecall = nil, Handler = nil }
        rawset(Environment, "AtramentaSharedNamecallRouter", State)
    end

    local Events = ReplicatedStorage:FindFirstChild("Events")

    State.Events = Events

    State.FallRemote = Events and Events:FindFirstChild("__RZDONL") or nil

    State.MoveRemote = Events and Events:FindFirstChild( "MOVZREP" ) or ReplicatedStorage:FindFirstChild( "MOVZREP", true)

    local StompGroup = Events and Events:FindFirstChild( "XMHH2")

    State.StompRemote = Events and ( Events:FindFirstChild( "XMHH2.2", true ) or ( StompGroup and ( StompGroup:FindFirstChild( "2", true)
                    or StompGroup:IsA( "RemoteEvent" ) and StompGroup or nil ) ) ) or nil

    State.Handler = function(Self, Method, Arguments)
        local WeaponSource = rawget(Environment, "AtramentaWeaponConfigSource")
        local WeaponSettings = type(WeaponSource) == "table" and type(WeaponSource.Settings) == "table" and WeaponSource.Settings or nil
        if Method == "FireServer" and Arguments[1] == "Do" and type(ProjectileController) == "table"
            and ProjectileController.C4Enabled == true and type(ProjectileController.ShouldBlockC4Attach) == "function"
            and typeof(Self) == "Instance" and Self.ClassName == "RemoteEvent" and ProjectileController:ShouldBlockC4Attach(Self)
        then
            return "Block"
        end

        if WeaponSource and WeaponSource.Enabled == true and WeaponSettings and WeaponSettings.NoRecoil == true
            and typeof(Self) == "Instance" and Self.Name == "RCL" and (Method == "Fire" or Method == "FireServer")
        then
            local Scale = math.clamp(tonumber(WeaponSettings.RecoilScale) or 0, 0, 1)
            if Scale <= 0.001 then return "Block" end
            local NewArguments = CloneNamecallArguments(Arguments)
            if NewArguments then
                local Count = math.max(math.floor(tonumber(NewArguments.n) or #NewArguments), 0)
                local ScaleFunction = type(ScaleRecoil) == "function" and ScaleRecoil or type(ScaleRecoilArgumentNR) == "function" and ScaleRecoilArgumentNR or nil
                if ScaleFunction then
                    for Index = 1, Count do NewArguments[Index] = ScaleFunction(NewArguments[Index], Scale, 0) end
                    return "Forward", NewArguments
                end
            end
        end

        if Method == "FireServer" and WeaponSource and WeaponSource.Enabled == true and WeaponSettings
            and WeaponSettings.NoScopeGlint == true and Arguments[1] == "ScopeGlint"
        then
            return "Block"
        end

        if Method == "FireServer" and WeaponSource and WeaponSource.Enabled == true and WeaponSettings and WeaponSettings.InstantReload == true
            and typeof(Self) == "Instance" and Self.Name == "GNX_R" and Arguments[2] == "KLWE89U0"
        then
            local ReloadTool = Arguments[3]
            local Runtime = rawget(Environment, "GunMods")
            local IsGame = type(checkcaller) ~= "function" or not checkcaller()
            if typeof(ReloadTool) == "Instance" and ReloadTool:IsA("Tool") then
                if type(FastReload) == "function" then task.defer(FastReload, ReloadTool) end
                if IsGame then
                    local Now = os.clock()
                    local Suppressed = type(Runtime) == "table" and Runtime.ReloadSuppressTool == ReloadTool
                        and Now < (tonumber(Runtime.ReloadSuppressUntil) or 0)
                    if type(Runtime) == "table" then
                        Runtime.ReloadTool = ReloadTool
                        Runtime.ReloadSuppressTool = ReloadTool
                        Runtime.ReloadSuppressUntil = Now + 0.15
                    end
                    if not Suppressed and type(InstantReload) == "function" then task.defer(InstantReload, ReloadTool, true) end
                    return "Block"
                end
            end
        end

        if Method == "FireServer" and typeof(Self) == "Instance"
            and Self.Name == "GNX_S" and Arguments[4] == "FDS9I83"
            and typeof(Arguments[3]) == "Instance" and Arguments[3]:IsA("Tool")
            and (type(Arguments[7]) == "string" or type(Arguments[7]) == "boolean")
            and (type(checkcaller) ~= "function" or not checkcaller())
        then
            Ragebot.Runtime.RealBulletTypes = type(Ragebot.Runtime.RealBulletTypes) == "table" and Ragebot.Runtime.RealBulletTypes or setmetatable({}, {__mode = "k"})
            Ragebot.Runtime.RealBulletTypes[Arguments[3]] = Arguments[7]
        end

        if Method == "FireServer"
            and typeof(Self) == "Instance"
            and Self.Name == "XMHH2.2"
            and Arguments[4] == "2389ZFX34"
            and (type(checkcaller) ~= "function" or not checkcaller())
        then
            HeadHitbox.RecordPhysicalMeleeHit(Arguments)
        end

        if Method == "FireServer" and typeof(Self) == "Instance" and Self.ClassName == "RemoteEvent" and Arguments[1] == "2389ZFX34"
            and typeof(Arguments[9]) == "Instance"
        then
            HandleAtramentaStompRemote(Self, Arguments)
        end

        if Method == "FireServer"
            and typeof(Self) == "Instance"
            and Self.Name == "FGRGJBHBEE"
            and (type(checkcaller) ~= "function" or not checkcaller())
        then
            Ragebot.Runtime = type(Ragebot.Runtime) == "table" and Ragebot.Runtime or {}
            Ragebot.Runtime.HitboxReports = type(Ragebot.Runtime.HitboxReports) == "table" and Ragebot.Runtime.HitboxReports or {}

            local Reports = Ragebot.Runtime.HitboxReports
            local Entry = { Time = os.clock(), Remote = Self, Size = Arguments[1], Character = Arguments[2] }

            Reports[#Reports + 1] = Entry

            if #Reports > 32 then table.remove(Reports, 1) end

            Ragebot.Runtime.LastHitboxReport = Entry

            if HeadHitbox.GetPhysicalEnabled() then return "Block" end
        end

        if Method == "FireServer"
            and HeadHitbox.GetEnabled()
            and typeof(Self) == "Instance"
            and Self.Name == "GNX_S"
            and Arguments[4] == "FDS9I83"
            and (type(checkcaller) ~= "function" or not checkcaller())
        then
            if Configuration.AimBot.SilentEnabled == true then
                local SilentArguments, SilentData = RedirectCriminologySilentAimPacket(Arguments)

                if SilentArguments and SilentData and NamecallArgumentTypesMatch(Arguments, SilentArguments) then
                    local TracerState = rawget(Environment, "AtramentaBulletTracerShotHook")
                    if type(TracerState) == "table" and TracerState.Enabled and (tonumber(TracerState.FireServerVersion) or 0) < 1 then
                        task.defer(DispatchBulletTracerRemoteShot, Self, table.unpack(SilentArguments, 1, SilentArguments.n))
                    end
                    return "Forward", SilentArguments
                end
            end

            local NewArguments, HbeData = HeadHitbox.RedirectNormalShotPacket(Arguments)

            if NewArguments and HbeData and NamecallArgumentTypesMatch(Arguments, NewArguments) then
                local TracerState = rawget(Environment, "AtramentaBulletTracerShotHook")

                if type(TracerState) == "table" and TracerState.Enabled
                    and (tonumber(TracerState.FireServerVersion) or 0) < 1
                then
                    task.defer(DispatchBulletTracerRemoteShot, Self, table.unpack(NewArguments, 1, NewArguments.n))
                end

                return "Forward", NewArguments
            end
        end

        if Method == "FireServer"
            and Configuration.AimBot.SilentEnabled == true
            and not HeadHitbox.GetEnabled()
            and typeof(Self) == "Instance"
            and Self.Name == "GNX_S"
            and (Self.Parent == ReplicatedStorage or Self.Parent == State.Events or Self.Parent ~= nil)
            and (type(checkcaller) ~= "function" or not checkcaller())
        then
            local NewArguments, SilentData = RedirectCriminologySilentAimPacket( Arguments)

            if NewArguments and NamecallArgumentTypesMatch( Arguments, NewArguments ) then
                local TracerState = rawget( Environment, "AtramentaBulletTracerShotHook")

                if type(TracerState) == "table" and TracerState.Enabled and ( tonumber(TracerState.FireServerVersion) or 0 ) < 1 then
                    task.defer( DispatchBulletTracerRemoteShot, Self, table.unpack( NewArguments, 1, NewArguments.n ))
                end

                return "Forward", NewArguments
            end
        end

        if Method == "FireServer" then
            local TracerState = rawget(Environment, "AtramentaBulletTracerShotHook")
            if type(TracerState) == "table" and TracerState.Enabled and (tonumber(TracerState.FireServerVersion) or 0) < 1 then
                task.defer( DispatchBulletTracerRemoteShot, Self, table.unpack(Arguments, 1, Arguments.n))
            end

        end

        if Method == "FireServer" and Self == State.MoveRemote and ( type(checkcaller) ~= "function" or not checkcaller() ) then
            local Packet, PacketIndex = FindMovementReplicationPacket( Arguments)

            if Packet and PacketIndex then
                local NewPacket local Changed = false

                if MovementDriverEnabled then
                    local DriverPacket, DriverChanged = ApplyMovementDriverPacket( Packet)

                    if DriverChanged and DriverPacket then
                        NewPacket = DriverPacket

                        Changed = true
                    end
                end

                if Changed and NewPacket and IsMovementReplicationPacket( NewPacket ) then
                    local NewArguments = CloneNamecallArguments( Arguments)

                    if NewArguments then
                        NewArguments[ PacketIndex ] = NewPacket

                        if NamecallArgumentTypesMatch( Arguments, NewArguments ) then return "Forward", NewArguments end
                    end
                end
            end
        end

        if AntiBarbwireEnabled and Method == "FireServer" then
            local Arg1 = Arguments[1] local IsBarrierRemote = Self == State.FallRemote or typeof(Self) == "Instance" and Self.Name == "__RZDONL"
            if IsBarrierRemote and AntiBarbwireRemoteKeys[Arg1] then return "Block" end
        end

        if IsNoFallDamageActive() and ( Method == "FireServer" or Method == "InvokeServer" ) then
            local FlyRagdollActive = FlyEnabled == true and FlyMethod == "Ragdoll"

            local Arg1 = Arguments[1]

            local SelfName = typeof(Self) == "Instance" and Self.Name or ""

            local IsRagdollRemote = Self == State.FallRemote or SelfName == "__RZDONL"

            if IsRagdollRemote then
                if FlyRagdollActive and Arg1 == "__---r" then return nil end

                return "Block"
            end

            if Arg1 == "FlllD" or Arg1 == "FllH" or Arg1 == "BHHh" then return "Block" end

            if SelfName == "FallDamage" or SelfName == "FD_Event" or SelfName == "BreakLimb" then return "Block" end
        end

        return nil
    end

    if State.Installed and type(State.OldNamecall) == "function" then
        SilentAimController.RaycastHooked = true
        return true
    end

    local function IsInternalRedoRay()
        if type(debug) == "table" and type(debug.info) == "function" then
            for Level = 2, 8 do
                local FunctionName = debug.info(Level, "n") local SourceName = debug.info(Level, "s")

                if type(FunctionName) == "string" then
                    if FunctionName == "RedoRay" or ( FunctionName == "Update" and type(SourceName) == "string" and ( SourceName:find("LaserM", 1, true)
                                or SourceName:find("LaserHandler", 1, true) ) ) or ( (FunctionName == "Raycast" or FunctionName == "RayCast")
                            and type(SourceName) == "string" and ( SourceName:find("NewModules.Client.Services.Blood", 1, true)
                                or SourceName:find("Services.Blood", 1, true) ) ) then
                        return true
                    end
                end

                if type(SourceName) == "string" and ( SourceName:find("LaserM", 1, true) or SourceName:find("LaserHandler", 1, true)
                        or SourceName:find("NewModules.Client.Services.Blood", 1, true) or SourceName:find("Services.Blood", 1, true) ) then
                    return true
                end
            end
        end

        if type(getcallingscript) == "function" then
            local CallingScript = getcallingscript()

            if typeof(CallingScript) == "Instance" then
                local CallingName = CallingScript.Name

                if type(CallingName) == "string" and ( CallingName == "LaserM" or CallingName == "LaserHandler" or CallingName == "Blood" ) then return true end
            end
        end

        return false
    end

    local RemoteEventProbe = Instance.new( "RemoteEvent")

    local FireServerMethod = RemoteEventProbe.FireServer

    RemoteEventProbe:Destroy()

    local RemoteFunctionProbe = Instance.new( "RemoteFunction")

    local InvokeServerMethod = RemoteFunctionProbe.InvokeServer

    RemoteFunctionProbe:Destroy()

    local OldNamecall
    local Callback = function(Self, ...)
        local Method = getnamecallmethod()

        if Method ~= "FireServer" and Method ~= "InvokeServer" and Method ~= "Raycast" and Method ~= "Fire" then return OldNamecall(Self, ...) end
        if type(checkcaller) == "function" and checkcaller() then return OldNamecall(Self, ...) end

        if Method == "Raycast" then
            if Self == workspace and IsInternalRedoRay() then return workspace.Raycast( workspace, ...) end

            return OldNamecall( Self, ...)
        end

        local Arguments = table.pack( ...)

        if AntiBarbwireEnabled and Method == "FireServer" and typeof(Self) == "Instance" and Self.Name == "__RZDONL" and AntiBarbwireRemoteKeys[
                Arguments[1] ]
        then
            return nil
        end

        if Method == "InvokeServer"
            and HeadHitbox.GetEnabled()
            and typeof(Self) == "Instance"
            and Self.Name == "XMHH.2"
            and Arguments[4] == "43TRFWX"
            and Arguments[5] == "Normal"
            and (type(checkcaller) ~= "function" or not checkcaller())
            and type(InvokeServerMethod) == "function"
        then
            local Count = math.max(
                math.floor(tonumber(Arguments.n) or #Arguments),
                0
            )
            local Results = table.pack(
                InvokeServerMethod(Self, table.unpack(Arguments, 1, Count))
            )
            local Token = Results[1]

            return table.unpack(Results, 1, Results.n)
        end

        local Handler = State.Handler

        local Action local NewArguments

        if type(Handler) == "function" then Action, NewArguments = Handler( Self, Method, Arguments) end

        if Action == "Block" then return nil end

        local DispatchArguments = Arguments

        if Action == "Forward" and type(NewArguments) == "table" and NamecallArgumentTypesMatch( Arguments, NewArguments ) then DispatchArguments = NewArguments end

        local Count = math.max( math.floor( tonumber(DispatchArguments.n) or #DispatchArguments ), 0)

        if Method == "FireServer" and type(FireServerMethod) == "function" then return FireServerMethod( Self, table.unpack( DispatchArguments, 1, Count )) end

        if Method == "InvokeServer" and type(InvokeServerMethod) == "function" then return InvokeServerMethod( Self, table.unpack( DispatchArguments, 1, Count )) end

        if Method == "Fire" then return OldNamecall(Self, table.unpack(DispatchArguments, 1, Count)) end

        return OldNamecall( Self, ...)
    end
    if type(newcclosure) == "function" then Callback = newcclosure(Callback) end
    OldNamecall = hookmetamethod(game, "__namecall", Callback)
    if type(OldNamecall) ~= "function" then
        State.Installed = false
        State.OldNamecall = nil
        SilentAimController.RaycastHooked = false
        return false
    end
    State.OldNamecall = OldNamecall
    State.Installed = true
    SilentAimController.RaycastHooked = true
    return true
end

if MovementDriverEnabled
    or Configuration and Configuration.AimBot and (Configuration.AimBot.SilentEnabled == true or HeadHitbox.GetEnabled())
    or HeadHitbox.GetEnabled()
then
    InstallSharedNamecallRouter()
end

function InstallSilentAimRaycastHook()
    DisableSilentAimHooks()
    return true
end

function DisableSilentAimController()
    if SilentAimController.Connection then
        SilentAimController.Connection:Disconnect()
        SilentAimController.Connection = nil
    end

    SilentAimController.Visualize = nil
    SilentAimController.LastTarget = nil
    SilentAimController.LastPart = nil
    SilentAimController.LastPacketDirection = nil
    SilentAimController.LastPacketOrigin = nil
    SilentAimController.LastPacketTargetPosition = nil
    SilentAimController.PendingShots = {}

    if Environment.SilentAimCon then Environment.SilentAimCon = nil end
    Environment.SilentAim = false
end

function EnableSilentAimController()
    DisableSilentAimHooks()
    if type(HookSpread) == "function" then HookSpread() end
    if not InstallSharedNamecallRouter() then return false end

    if SilentAimController.Connection then
        local Connected = SilentAimController.Connection.Connected
        if Connected then return true end
        SilentAimController.Connection = nil
    end

    local Events2 = ReplicatedStorage:FindFirstChild("Events2") local Visualize = Events2 and Events2:FindFirstChild("Visualize")
    if not Visualize or not Visualize:IsA("BindableEvent") then return false end

    SilentAimController.Visualize = Visualize
    SilentAimController.Connection = Visualize.Event:Connect(HandleCriminologySilentAimVisualize)

    Environment.SilentAimCon = SilentAimController.Connection
    Environment.SilentAim = true
    Environment.CrimAimState = Configuration.AimBot
    Environment.AimPart = Configuration.AimBot.TargetPart

    return true
end

function UpdateSilentAimController()
    if Configuration.AimBot.SilentEnabled then
        EnableSilentAimController()
    else
        DisableSilentAimController()
    end
end

DisableSilentAimHooks()

function RefreshAimEngine()
    local EngineEnabled = Configuration.AimBot.AimbotEnabled or Configuration.AimBot.SilentEnabled
    Configuration.AimBot.Enabled = EngineEnabled
    Configuration.AimBot.Resolver = true
    Configuration.AimBot.ResolverMode = "Adaptive"
    Configuration.AimBot.ResolverStrength = 0.85
    if not Configuration.AimBot.AimbotEnabled then ResetAimbotTargetLock() end
    if not Configuration.AimBot.SilentEnabled then ResetSilentAimTargetLock() end
    Configuration.AimBot.PositionCacheMode = nil
    Configuration.AimBot.LastPositionUpdate = 0
    if EngineEnabled then
        if Configuration.AimBot.ShowFOV then CreateFOVCircle() else RemoveAimFOVCircle() end
        if not Configuration.AimBot.FOVUpdateConnection then Configuration.AimBot.FOVUpdateConnection = RunService.RenderStepped:Connect(UpdateFOVCircle) end
        if not Configuration.AimBot.Connection then Configuration.AimBot.Connection = RunService.RenderStepped:Connect(AimLoop) end
        UpdateSilentAimController()
        return
    end
    Configuration.AimBot.AimActive = false
    RemoveAimFOVCircle()
    DisableSilentAimController()
    if Configuration.AimBot.FOVUpdateConnection then Configuration.AimBot.FOVUpdateConnection:Disconnect(); Configuration.AimBot.FOVUpdateConnection = nil end
    if Configuration.AimBot.Connection then Configuration.AimBot.Connection:Disconnect(); Configuration.AimBot.Connection = nil end
end

function ToggleAimBot(StateValue)
    Configuration.AimBot.AimbotEnabled = StateValue == true

    if not Configuration.AimBot.AimbotEnabled then
        Configuration.AimBot.AimActive = false
        ResetAimbotTargetLock()
    end

    RefreshAimEngine()
end

function ToggleSilentAim(StateValue)
    Configuration.AimBot.SilentEnabled = StateValue == true

    Environment.SilentAim = Configuration.AimBot.SilentEnabled
    Environment.CrimAimState = Configuration.AimBot
    Environment.AimPart = Configuration.AimBot.TargetPart

    if not Configuration.AimBot.SilentEnabled then ResetSilentAimTargetLock() end
    RefreshAimEngine()
end

function SetupBlur()
    if not Configuration.Blur.BlurEffect then
        Configuration.Blur.BlurEffect = Instance.new("BlurEffect", game:GetService("Lighting"))
        Configuration.Blur.BlurEffect.Size = 0
    end
    if Configuration.Blur.Connection then
        Configuration.Blur.Connection:Disconnect()
        Configuration.Blur.Connection = nil
    end
    Configuration.Blur.Connection = RunService.RenderStepped:Connect(function()
        if not Configuration.Blur.Enabled or not Configuration.Blur.BlurEffect then return end
        local CameraObject = Internal.GetCamera() if not CameraObject then return end
        Configuration.Blur.CurrentLookVector = CameraObject.CFrame.LookVector
        Configuration.Blur.RotationSpeed = (Configuration.Blur.CurrentLookVector - (Configuration.Blur.LastLookVector or Configuration.Blur.CurrentLookVector)).Magnitude * 130
        Configuration.Blur.BlurEffect.Size = math.clamp(Configuration.Blur.RotationSpeed, 0, 20)
        Configuration.Blur.LastLookVector = Configuration.Blur.CurrentLookVector end)
end

function DisableBlur()
    if Configuration.Blur.Connection then
        Configuration.Blur.Connection:Disconnect()
        Configuration.Blur.Connection = nil
    end
    if Configuration.Blur.BlurEffect then
        Configuration.Blur.BlurEffect.Size = 0
        Configuration.Blur.BlurEffect:Destroy()
        Configuration.Blur.BlurEffect = nil
    end
end

function ToggleBlur(StateValue)
    Configuration.Blur.Enabled = StateValue
    if StateValue then SetupBlur() else DisableBlur() end
end

function GetCameraFOVDesired()
    return math.clamp( tonumber(Configuration.CameraFOV.Value) or 90, 40, 120)
end

function DisconnectCameraFOVWatcher()
    if Configuration.CameraFOV.ChangeConnection then
        Configuration.CameraFOV.ChangeConnection:Disconnect()
        Configuration.CameraFOV.ChangeConnection = nil
    end
    Configuration.CameraFOV.Camera = nil
end

function BindCameraFOVWatcher(CameraObject)
    if not CameraObject then return end

    if Configuration.CameraFOV.Camera == CameraObject and Configuration.CameraFOV.ChangeConnection then return end

    DisconnectCameraFOVWatcher()

    Configuration.CameraFOV.Camera = CameraObject

    if Configuration.CameraFOV.SavedValues[CameraObject] == nil then Configuration.CameraFOV.SavedValues[CameraObject] = CameraObject.FieldOfView end

    Configuration.CameraFOV.ChangeConnection = CameraObject:GetPropertyChangedSignal( "FieldOfView" ):Connect(function()
                if not Configuration.CameraFOV.Enabled or Configuration.CameraFOV.Applying then return end

                local Desired = GetCameraFOVDesired()

                if math.abs( CameraObject.FieldOfView
                    - Desired ) <= 0.001 then
                    return
                end

                Configuration.CameraFOV.Applying = true
                CameraObject.FieldOfView = Desired
                Configuration.CameraFOV.Applying = false
            end)
end

function UpdateCameraFOV()
    if not Configuration.CameraFOV.Enabled then return end

    local CameraObject = Internal.GetCamera()

    if not CameraObject then return end

    BindCameraFOVWatcher( CameraObject)

    local Desired = GetCameraFOVDesired()

    if math.abs( CameraObject.FieldOfView
        - Desired ) > 0.001 then
        Configuration.CameraFOV.Applying = true
        CameraObject.FieldOfView = Desired
        Configuration.CameraFOV.Applying = false
    end
end

function EnableCameraFOV()
    local CameraObject = Internal.GetCamera()

    if CameraObject then
        if Configuration.CameraFOV.SavedValues[CameraObject] == nil then Configuration.CameraFOV.SavedValues[CameraObject] = CameraObject.FieldOfView end

        Configuration.CameraFOV.SavedValue = Configuration.CameraFOV.SavedValues[ CameraObject ]

        BindCameraFOVWatcher( CameraObject)
    end

    Internal.Call(function()
        RunService:UnbindFromRenderStep( Configuration.CameraFOV.BindName)
    end)

    Configuration.CameraFOV.Enabled = true

    RunService:BindToRenderStep( Configuration.CameraFOV.BindName, Enum.RenderPriority.Last.Value, UpdateCameraFOV)

    UpdateCameraFOV()
end

function DisableCameraFOV()
    Configuration.CameraFOV.Enabled = false

    Internal.Call(function()
        RunService:UnbindFromRenderStep( Configuration.CameraFOV.BindName)
    end)

    DisconnectCameraFOVWatcher()

    local CameraObject = Internal.GetCamera()

    if CameraObject then
        local Saved = Configuration.CameraFOV.SavedValues[ CameraObject ]

        if Saved == nil then Saved = Configuration.CameraFOV.SavedValue end

        if Saved ~= nil then
            Internal.Call(function()
                CameraObject.FieldOfView = Saved
            end)
        end
    end

    Configuration.CameraFOV.SavedValue = nil
    Configuration.CameraFOV.Applying = false
end

function ToggleCameraFOV(State)
    if State == true then
        EnableCameraFOV()
    else
        DisableCameraFOV()
    end
end

function DisconnectFreecamInputs()
    for _, Connection in ipairs(Configuration.Freecam.InputConnections) do
        Internal.Call(function()
            Connection:Disconnect()
        end)
    end

    Configuration.Freecam.InputConnections = {}
end

function AddFreecamInputConnection(Connection)
    Configuration.Freecam.InputConnections[#Configuration.Freecam.InputConnections + 1] = Connection
    return Connection
end

function ApplyFreecamMouseState()
    if Configuration.Freecam.OnMobile then return end

    if not Configuration.Freecam.Enabled then return end

    if Configuration.Freecam.Rotating then
        UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
        UserInputService.MouseIconEnabled = false
    else
        UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
    end
end

function ResolveFreecamMouseRestore(SavedCameraMode)
    if SavedCameraMode == Enum.CameraMode.LockFirstPerson then return Enum.MouseBehavior.LockCenter, false end
    return Enum.MouseBehavior.Default, true
end

function ReleaseFreecamCharacter(Saved)
    local Character = LocalPlayer.Character
    local CurrentRoot = Character and (Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso"))

    if Saved and Saved.RootPart and Saved.RootPart.Parent then
        Saved.RootPart.Anchored = false
        Saved.RootPart.AssemblyLinearVelocity = Vector3.zero
        Saved.RootPart.AssemblyAngularVelocity = Vector3.zero
    end

    if CurrentRoot and CurrentRoot.Parent then
        CurrentRoot.Anchored = false
        CurrentRoot.AssemblyLinearVelocity = Vector3.zero
        CurrentRoot.AssemblyAngularVelocity = Vector3.zero
    end
end

function ForceRestorePlayerCamera(Saved, RestoreTransform)
    local CameraObject = Internal.GetCamera() local Character = LocalPlayer.Character local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    ReleaseFreecamCharacter(Saved)

    if Saved.MinZoom ~= nil then LocalPlayer.CameraMinZoomDistance = Saved.MinZoom end
    if Saved.MaxZoom ~= nil then LocalPlayer.CameraMaxZoomDistance = Saved.MaxZoom end

    local Mode = Saved.CameraMode or Enum.CameraMode.Classic
    LocalPlayer.CameraMode = Enum.CameraMode.Classic

    if CameraObject then
        local Subject = Saved.Subject
        if not Subject or not Subject.Parent then Subject = Humanoid end

        CameraObject.CameraType = Enum.CameraType.Custom
        if Subject then CameraObject.CameraSubject = Subject end
        if Saved.FOV then CameraObject.FieldOfView = Saved.FOV end

        if RestoreTransform ~= false then
            if typeof(Saved.CameraCFrame) == "CFrame" then CameraObject.CFrame = Saved.CameraCFrame end
            if typeof(Saved.CameraFocus) == "CFrame" then CameraObject.Focus = Saved.CameraFocus end
        end
    end

    LocalPlayer.CameraMode = Mode

    local Behavior, Icon = ResolveFreecamMouseRestore(Mode)
    UserInputService.MouseBehavior = Behavior UserInputService.MouseIconEnabled = Icon

    return Mode
end

function RestoreFreecamCameraState(Saved, Token)
    if Configuration.Freecam.Enabled or Configuration.Freecam.MouseRestoreToken ~= Token then return end

    local Mode = ForceRestorePlayerCamera(Saved, true)

    task.spawn(function()
        RunService.RenderStepped:Wait()
        if Configuration.Freecam.Enabled or Configuration.Freecam.MouseRestoreToken ~= Token then return end

        local CameraObject = Internal.GetCamera() local Character = LocalPlayer.Character local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

        ReleaseFreecamCharacter(Saved)

        if CameraObject then
            local Subject = Saved.Subject
            if not Subject or not Subject.Parent then Subject = Humanoid end
            CameraObject.CameraType = Enum.CameraType.Custom
            if Subject then CameraObject.CameraSubject = Subject end
            if Saved.FOV then CameraObject.FieldOfView = Saved.FOV end
        end

        LocalPlayer.CameraMode = Mode

        if Mode == Enum.CameraMode.LockFirstPerson then
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled = false
        else
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            UserInputService.MouseIconEnabled = true
        end

        RunService.RenderStepped:Wait()
        if Configuration.Freecam.Enabled or Configuration.Freecam.MouseRestoreToken ~= Token then return end

        ReleaseFreecamCharacter(Saved)

        if Mode ~= Enum.CameraMode.LockFirstPerson then
            local CurrentCamera = Internal.GetCamera() local Distance = CurrentCamera and (CurrentCamera.CFrame.Position - CurrentCamera.Focus.Position).Magnitude or math.huge
            if Distance > 1.05 then
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                UserInputService.MouseIconEnabled = true
            end
        end

        Configuration.Freecam.StartedFirstPerson = false
        Configuration.Freecam.SavedCameraMode = nil
        Configuration.Freecam.SavedMinZoom = nil
        Configuration.Freecam.SavedMaxZoom = nil
        Configuration.Freecam.SavedMouseBehavior = nil
        Configuration.Freecam.SavedMouseIconEnabled = nil
        Configuration.Freecam.SavedCameraType = nil
        Configuration.Freecam.SavedCameraSubject = nil
        Configuration.Freecam.SavedCameraCFrame = nil
        Configuration.Freecam.SavedCameraFocus = nil
        Configuration.Freecam.SavedFieldOfView = nil
        Configuration.Freecam.SavedRootAnchored = nil
        Configuration.Freecam.SavedRootPart = nil
    end)
end

function SetFreecamRotationState(State)
    Configuration.Freecam.Rotating = State == true
    Configuration.Freecam.MouseDelta = Vector2.zero
    ApplyFreecamMouseState()
end

function GetFreecamMovementVector(CameraFrame)
    local Move = Vector3.zero local Keys = Configuration.Freecam.KeysDown

    if UserInputService:IsKeyDown(Enum.KeyCode.W) or Keys[Enum.KeyCode.W] then
        Move += CameraFrame.LookVector end

    if UserInputService:IsKeyDown(Enum.KeyCode.S) or Keys[Enum.KeyCode.S] then
        Move -= CameraFrame.LookVector end

    if UserInputService:IsKeyDown(Enum.KeyCode.A) or Keys[Enum.KeyCode.A] then
        Move -= CameraFrame.RightVector end

    if UserInputService:IsKeyDown(Enum.KeyCode.D) or Keys[Enum.KeyCode.D] then
        Move += CameraFrame.RightVector end

    if UserInputService:IsKeyDown(Enum.KeyCode.E) or UserInputService:IsKeyDown(Enum.KeyCode.Space) or Keys[Enum.KeyCode.E] or Keys[Enum.KeyCode.Space] then
        Move += Vector3.yAxis
    end

    if UserInputService:IsKeyDown(Enum.KeyCode.Q) or UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or Keys[Enum.KeyCode.Q]
        or Keys[Enum.KeyCode.LeftControl] then
        Move -= Vector3.yAxis
    end

    if Move.Magnitude > 0 then return Move.Unit end

    return Vector3.zero
end

function UpdateFreecam(DeltaTime)
    if not Configuration.Freecam.Enabled then return end

    local CameraObject = Internal.GetCamera()
    if not CameraObject then
        ToggleFreecam(false)
        return
    end

    DeltaTime = math.clamp(tonumber(DeltaTime) or 0, 0, 1 / 30)

    if LocalPlayer.CameraMode == Enum.CameraMode.LockFirstPerson then LocalPlayer.CameraMode = Enum.CameraMode.Classic end

    CameraObject.CameraType = Enum.CameraType.Scriptable
    if Configuration.Freecam.Rotating ~= Configuration.Freecam.RightMouseDown then SetFreecamRotationState(Configuration.Freecam.RightMouseDown) end

    if Configuration.Freecam.Rotating then
        local Delta = UserInputService:GetMouseDelta()

        if Configuration.Freecam.MouseDelta.Magnitude > Delta.Magnitude then Delta = Configuration.Freecam.MouseDelta end

        Configuration.Freecam.MouseDelta = Vector2.zero

        local Sensitivity = math.clamp(tonumber(Configuration.Freecam.Sensitivity) or 0.18, 0.02, 0.60) local RotationScale = math.rad(Sensitivity)

        Configuration.Freecam.Yaw -= Delta.X * RotationScale
        Configuration.Freecam.Pitch = math.clamp( Configuration.Freecam.Pitch - Delta.Y * RotationScale, math.rad(-89), math.rad(89))
    else
        Configuration.Freecam.MouseDelta = Vector2.zero
    end

    local RotationFrame = CFrame.Angles(0, Configuration.Freecam.Yaw, 0) * CFrame.Angles(Configuration.Freecam.Pitch, 0, 0)

    local Movement = GetFreecamMovementVector(RotationFrame) local Speed = math.clamp(tonumber(Configuration.Freecam.Speed) or 18, 1, 120)

    if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then Speed *= math.clamp(tonumber(Configuration.Freecam.BoostMultiplier) or 2, 1, 3) end

    local TargetVelocity = Movement * Speed local Acceleration = math.clamp(tonumber(Configuration.Freecam.Acceleration) or 14, 1, 30)
    local Alpha = 1 - math.exp(-Acceleration * DeltaTime)

    if Movement.Magnitude > 0 then
        Configuration.Freecam.Velocity = Configuration.Freecam.Velocity:Lerp(TargetVelocity, Alpha)

        if Configuration.Freecam.Velocity.Magnitude > Speed and Configuration.Freecam.Velocity.Magnitude > 0 then
            Configuration.Freecam.Velocity = Configuration.Freecam.Velocity.Unit * Speed
        end
    else
        Configuration.Freecam.Velocity = Configuration.Freecam.Velocity:Lerp( Vector3.zero, math.clamp(Alpha * 1.35, 0, 1))
    end

    Configuration.Freecam.Position += Configuration.Freecam.Velocity * DeltaTime

    local CameraFrame = CFrame.new(Configuration.Freecam.Position) * RotationFrame

    CameraObject.CFrame = CameraFrame
    CameraObject.Focus = CFrame.new( Configuration.Freecam.Position + CameraFrame.LookVector * 512)

    ApplyFreecamMouseState()
end

function SetupFreecam()
    local CameraObject = Internal.GetCamera()
    if not CameraObject then
        Configuration.Freecam.Enabled = false
        return
    end

    DisconnectFreecamInputs()

    Internal.Call(function()
        RunService:UnbindFromRenderStep("AtramentaFreecam")
    end)

    Configuration.Freecam.SavedCameraType = CameraObject.CameraType
    Configuration.Freecam.SavedCameraSubject = CameraObject.CameraSubject
    Configuration.Freecam.SavedCameraCFrame = CameraObject.CFrame
    Configuration.Freecam.SavedCameraFocus = CameraObject.Focus
    Configuration.Freecam.SavedFieldOfView = CameraObject.FieldOfView
    Configuration.Freecam.SavedMouseBehavior = UserInputService.MouseBehavior
    Configuration.Freecam.SavedMouseIconEnabled = UserInputService.MouseIconEnabled
    Configuration.Freecam.SavedCameraMode = LocalPlayer.CameraMode
    Configuration.Freecam.SavedMinZoom = LocalPlayer.CameraMinZoomDistance
    Configuration.Freecam.SavedMaxZoom = LocalPlayer.CameraMaxZoomDistance

    local CameraDistance = ( CameraObject.CFrame.Position - CameraObject.Focus.Position ).Magnitude

    Configuration.Freecam.StartedFirstPerson = LocalPlayer.CameraMode
            == Enum.CameraMode.LockFirstPerson or CameraDistance <= 1.05 or ( tonumber(Configuration.Freecam.SavedMinZoom) ~= nil
            and tonumber(Configuration.Freecam.SavedMaxZoom) ~= nil and Configuration.Freecam.SavedMinZoom <= 0.6 and Configuration.Freecam.SavedMaxZoom <= 0.6)

    Configuration.Freecam.MouseRestoreToken += 1
    Configuration.Freecam.Position = CameraObject.CFrame.Position

    local Pitch, Yaw = CameraObject.CFrame:ToOrientation()
    Configuration.Freecam.Pitch = math.clamp(Pitch, math.rad(-89), math.rad(89))
    Configuration.Freecam.Yaw = Yaw
    Configuration.Freecam.Velocity = Vector3.zero
    Configuration.Freecam.MouseDelta = Vector2.zero
    Configuration.Freecam.KeysDown = {}
    Configuration.Freecam.Rotating = false
    Configuration.Freecam.RightMouseDown = false

    local Character = LocalPlayer.Character local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")

    Configuration.Freecam.SavedRootPart = RootPart

    if RootPart then
        Configuration.Freecam.SavedRootAnchored = RootPart.Anchored
        RootPart.Anchored = true
    else
        Configuration.Freecam.SavedRootAnchored = nil
    end

    LocalPlayer.CameraMode = Enum.CameraMode.Classic
    CameraObject.CameraType = Enum.CameraType.Scriptable
    UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    UserInputService.MouseIconEnabled = true

    AddFreecamInputConnection( UserInputService.InputBegan:Connect(function(Input)
            if not Configuration.Freecam.Enabled then return end

            if Input.UserInputType == Enum.UserInputType.MouseButton2 then
                Configuration.Freecam.RightMouseDown = true
                SetFreecamRotationState(true)
            elseif Input.KeyCode == Enum.KeyCode.W or Input.KeyCode == Enum.KeyCode.A or Input.KeyCode == Enum.KeyCode.S or Input.KeyCode == Enum.KeyCode.D
                or Input.KeyCode == Enum.KeyCode.Q or Input.KeyCode == Enum.KeyCode.E or Input.KeyCode == Enum.KeyCode.Space
                or Input.KeyCode == Enum.KeyCode.LeftControl then
                Configuration.Freecam.KeysDown[Input.KeyCode] = true
            end
        end))

    AddFreecamInputConnection( UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton2 then
                Configuration.Freecam.RightMouseDown = false
                SetFreecamRotationState(false)
            elseif Input.KeyCode ~= Enum.KeyCode.Unknown then
                Configuration.Freecam.KeysDown[Input.KeyCode] = nil
            end
        end))

    AddFreecamInputConnection( UserInputService.InputChanged:Connect(function(Input)
            if not Configuration.Freecam.Enabled then return end

            if Input.UserInputType == Enum.UserInputType.MouseMovement and Configuration.Freecam.Rotating then
                Configuration.Freecam.MouseDelta += Vector2.new(Input.Delta.X, Input.Delta.Y)
            end
        end))

    Internal.Call(function()
        AddFreecamInputConnection( UserInputService.WindowFocusReleased:Connect(function()
                Configuration.Freecam.RightMouseDown = false
                SetFreecamRotationState(false)
            end))
    end)

    RunService:BindToRenderStep( "AtramentaFreecam", Enum.RenderPriority.Camera.Value + 100, UpdateFreecam)

    ApplyFreecamMouseState()
end

function DisableFreecam()
    Internal.Call(function()
        RunService:UnbindFromRenderStep("AtramentaFreecam")
    end)

    DisconnectFreecamInputs()

    Configuration.Freecam.RightMouseDown = false
    Configuration.Freecam.Rotating = false
    Configuration.Freecam.MouseDelta = Vector2.zero
    Configuration.Freecam.KeysDown = {}
    Configuration.Freecam.Velocity = Vector3.zero

    Configuration.Freecam.MouseRestoreToken += 1
    local Token = Configuration.Freecam.MouseRestoreToken

    local Saved = { CameraType = Configuration.Freecam.SavedCameraType, Subject = Configuration.Freecam.SavedCameraSubject, FOV = Configuration.Freecam.SavedFieldOfView,
        CameraCFrame = Configuration.Freecam.SavedCameraCFrame, CameraFocus = Configuration.Freecam.SavedCameraFocus, CameraMode = Configuration.Freecam.SavedCameraMode,
        MinZoom = Configuration.Freecam.SavedMinZoom, MaxZoom = Configuration.Freecam.SavedMaxZoom, RootAnchored = Configuration.Freecam.SavedRootAnchored, RootPart = Configuration.Freecam.SavedRootPart,
        WasFirstPerson = Configuration.Freecam.StartedFirstPerson == true }

    UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    UserInputService.MouseIconEnabled = true
    ReleaseFreecamCharacter(Saved)
    ForceRestorePlayerCamera(Saved, true)
    RestoreFreecamCameraState(Saved, Token)

    Configuration.Freecam.Position = nil

    if Configuration.CameraFOV and Configuration.CameraFOV.Enabled then UpdateCameraFOV() end
end

function ToggleFreecam(State)
    State = State == true

    if State == Configuration.Freecam.Enabled then return end

    if State and ProjectileController and ProjectileController.CurrentObject then ProjectileController:Release() end

    if State then
        Configuration.Freecam.Enabled = true
        SetupFreecam()
    else
        Configuration.Freecam.Enabled = false
        DisableFreecam()
    end
end

Internal.Call(function()
    RunService:UnbindFromRenderStep("AtramentaFreecam")
    if Configuration.Freecam.Enabled then return end
    local Character = LocalPlayer.Character local RootPart = Character and Character:FindFirstChild("HumanoidRootPart")
    if RootPart and RootPart.Anchored and not SafeFarmTeleportLock then RootPart.Anchored = false end
end)

local GunMods = rawget(Environment, "GunMods")
local OldGunMods = rawget(Environment, "GunMods")

function ReadUpvalue(Function, Index)
    if type(Function) ~= "function" then return false, nil, nil end
    if type(debug) == "table" and type(debug.getupvalue) == "function" then
        local Success, Name, Value = Internal.Call(debug.getupvalue, Function, Index)
        if Success and Name ~= nil then return true, Name, Value end
    end
    return false, nil, nil
end

function WriteUpvalue(Function, Index, Value)
    if type(Function) ~= "function" then return false end
    if type(setupvalue) == "function" then
        local Success = Internal.Call(setupvalue, Function, Index, Value)
        if Success then return true end
    end
    if type(debug) == "table" and type(debug.setupvalue) == "function" then
        local Success = Internal.Call(debug.setupvalue, Function, Index, Value)
        if Success then return true end
    end
    return false
end

function RestoreGunTable(Runtime)
    if type(Runtime) ~= "table" or type(Runtime.Upvalues) ~= "table" then return end
    local FallbackRate
    local Character = LocalPlayer.Character
    local Tool = Character and Character:FindFirstChildOfClass("Tool")
    local Module = Tool and Tool:FindFirstChild("Config")
    if Module and Module:IsA("ModuleScript") then
        local Success, Config = Internal.Call(require, Module)
        if Success and type(Config) == "table" then
            local Original = AtramentaWeaponConfigSource.Originals[Config]
            FallbackRate = type(Original) == "table" and tonumber(Original.FireRate) or tonumber(AtramentaRageFireRate.Originals[Config])
            if not FallbackRate then
                local Current = tonumber(rawget(Config, "FireRate"))
                if Current and math.abs(Current - 999) >= 0.001 and Current < 100000 then FallbackRate = Current end
            end
        end
    end
    for Function, Records in pairs(Runtime.Upvalues) do
        if type(Function) == "function" and type(Records) == "table" then
            for Index = 1, #Records do
                local Record = Records[Index]
                if type(Record) == "table" and type(Record.Index) == "number" and type(Record.Original) == "number" then
                    local Value = Record.Original
                    local DirtyRate = Record.Key == "FireRate" and (math.abs(Value - 999) < 0.001 or Value >= 100000)
                    if DirtyRate then Value = FallbackRate end
                    if type(Value) == "number" then WriteUpvalue(Function, Record.Index, Value) end
                end
            end
        end
    end
end

RestoreGunTable(OldGunMods)
if GunMods ~= OldGunMods then RestoreGunTable(GunMods) end

local function DropConnection(Connection)
    if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
end

if type(OldGunMods) == "table" then
    DropConnection(OldGunMods.ManualReloadConnection)
    DropConnection(OldGunMods.BackpackConnection)
end
if type(GunMods) == "table" then
    DropConnection(GunMods.ReloadConnection)
    DropConnection(GunMods.BackpackConnection)
end

GunMods = {
    Upvalues = setmetatable({}, {__mode = "k"}),
    Functions = setmetatable({}, {__mode = "k"}),
    Tables = setmetatable({}, {__mode = "k"}),
    Animations = setmetatable({}, {__mode = "k"}),
    SpreadCallers = setmetatable({}, {__mode = "k"}),
    RefreshQueued = false,
    Scanning = false,
    Scanned = false,
    ScanAgain = false,
    RefreshForce = false,
    ScanToken = 0,
    LastScan = 0,
    BackpackConnection = nil,
    ReloadConnection = nil,
    ReloadBusy = false,
    ReloadLast = 0,
    ReloadToken = 0,
    ReloadSuppressUntil = 0,
    ReloadSuppressTool = nil,
    ReloadTool = nil,
    CharacterToken = 0
}
rawset(Environment, "GunMods", GunMods)
rawset(Environment, "AtramentaWeaponModsRuntime", nil)

function GetRecoilScale()
    local Settings = Configuration.NoRecoil.Settings.GunMods
    if Settings.NoRecoil ~= true then return 1 end
    if tostring(Settings.RecoilMode or "No Recoil") == "No Recoil" then return 0 end
    return 1 - math.clamp(tonumber(Settings.RecoilReduction) or 100, 0, 100) / 100
end

function SyncGunMods()
    local Settings = Configuration.NoRecoil.Settings.GunMods
    local Source = AtramentaWeaponConfigSource.Settings
    local Active = Configuration.NoRecoil.Enabled == true
    AtramentaWeaponConfigSource.Enabled = Active
    Source.NoRecoil = Settings.NoRecoil == true
    Source.RecoilScale = GetRecoilScale()
    Source.NoSpread = Settings.NoSpread == true
    Source.CustomSpread = Settings.Spread == true and Settings.NoSpread ~= true
    Source.SpreadAmount = math.max(tonumber(Settings.SpreadAmount) or 0, 0)
    Source.InstantCharge = Settings.InstantCharge == true
    Source.InstantReload = Settings.InstantReload == true
    Source.InstantEquip = Settings.InstantEquip == true
    Source.InstantFireRate = Settings.InstantBullet == true
    Source.InfiniteRange = Settings.InfiniteRange == true
    Source.NoSlowdown = Settings.NoSlowdown == true
    Source.NoScopeGlint = Settings.NoScopeGlint == true
    AtramentaInfiniteRange.Enabled = Active and Source.InfiniteRange
    if type(AtramentaExtraState) == "table" and type(AtramentaExtraState.ScopeGlint) == "table" then
        AtramentaExtraState.ScopeGlint.Enabled = Active and Source.NoScopeGlint
    end
    return Source
end

function GetGunConfigModule(Tool)
    if not Tool or not Tool:IsA("Tool") then return nil end
    local Cached = Configuration.NoRecoil.ToolConfigLookup[Tool]
    if Cached and Cached.Parent and Cached:IsA("ModuleScript") then return Cached end
    local Config = Tool:FindFirstChild("Config")
    if not Config then
        for _, Child in ipairs(Tool:GetChildren()) do
            if Child:IsA("Folder") or Child:IsA("Configuration") then
                local Found = Child:FindFirstChild("Config")
                if Found and Found:IsA("ModuleScript") then Config = Found; break end
            end
        end
    end
    if Config and Config:IsA("ModuleScript") then
        Configuration.NoRecoil.ToolConfigLookup[Tool] = Config
        return Config
    end
    return nil
end

function RegisterGun(Tool)
    local Module = GetGunConfigModule(Tool)
    if not Module then return false end
    local Success, Config = Internal.Call(require, Module)
    if not Success or type(Config) ~= "table" then return false end
    AtramentaRageFireRate.Modules[Module] = Config
    RegisterAtramentaWeaponConfigSource(Config)
    ApplyAtramentaWeaponConfigSource(Config)
    return true
end

function RefreshGunConfigs()
    local Character = LocalPlayer.Character
    local Backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    if Character then
        for _, Tool in ipairs(Character:GetChildren()) do
            if Tool:IsA("Tool") then RegisterGun(Tool) end
        end
    end
    if Backpack then
        for _, Tool in ipairs(Backpack:GetChildren()) do
            if Tool:IsA("Tool") then RegisterGun(Tool) end
        end
    end
    Configuration.NoRecoil.CacheReady = true
end

local SpreadHook = rawget(Environment, "AtramentaWeaponSpreadHook")
if type(SpreadHook) ~= "table" then
    SpreadHook = {Installed = false, OldRandom = nil, Callers = setmetatable({}, {__mode = "k"})}
    rawset(Environment, "AtramentaWeaponSpreadHook", SpreadHook)
elseif type(SpreadHook.Callers) ~= "table" then
    SpreadHook.Callers = setmetatable({}, {__mode = "k"})
end

function IsSpreadCaller()
    if type(debug) ~= "table" or type(debug.info) ~= "function" then return false end
    for Level = 2, 5 do
        local SuccessName, Name = Internal.Call(debug.info, Level, "n")
        if SuccessName and Name == "getSPRD" then return true end
        local SuccessFunction, Caller = Internal.Call(debug.info, Level, "f")
        if SuccessFunction and type(Caller) == "function" and (GunMods.SpreadCallers[Caller] or SpreadHook.Callers[Caller]) then return true end
    end
    return false
end

function ZeroSpreadRandom(...)
    local Count = select("#", ...)
    if Count == 0 then return 0 end
    local Minimum = tonumber(select(1, ...))
    if Count == 1 then return Minimum and Minimum >= 1 and 1 or 0 end
    local Maximum = tonumber(select(2, ...))
    if Minimum and Maximum then
        if Minimum <= 0 and Maximum >= 0 then return 0 end
        return Minimum
    end
    return 0
end

function HookSpread()
    if SpreadHook.Installed then return true end
    if type(hookfunction) ~= "function" or type(math.random) ~= "function" then return false end
    local OldRandom
    local Callback = function(...)
        local Source = rawget(Environment, "AtramentaWeaponConfigSource")
        local GunSpread = type(Source) == "table" and Source.Enabled == true and type(Source.Settings) == "table" and Source.Settings.NoSpread == true
        local SilentSpread = Configuration and Configuration.AimBot and Configuration.AimBot.SilentEnabled == true
        if (GunSpread or SilentSpread) and IsSpreadCaller() then return ZeroSpreadRandom(...) end
        return OldRandom(...)
    end
    if type(newcclosure) == "function" then Callback = newcclosure(Callback) end
    OldRandom = hookfunction(math.random, Callback)
    if type(OldRandom) ~= "function" then return false end
    SpreadHook.OldRandom = OldRandom
    SpreadHook.Installed = true
    return true
end

local AffectHook = rawget(Environment, "AtramentaWeaponAffectCharHook")
if type(AffectHook) ~= "table" then
    AffectHook = {Hooked = setmetatable({}, {__mode = "k"})}
    rawset(Environment, "AtramentaWeaponAffectCharHook", AffectHook)
elseif type(AffectHook.Hooked) ~= "table" then
    AffectHook.Hooked = setmetatable({}, {__mode = "k"})
end

function HookSlowdown()
    if type(hookfunction) ~= "function" then return false end
    local AffectChar = rawget(_G, "AffectChar")
    if type(AffectChar) ~= "function" then return false end
    if AffectHook.Hooked[AffectChar] then return true end
    local OldAffectChar
    local Callback = function(...)
        local Source = rawget(Environment, "AtramentaWeaponConfigSource")
        if type(Source) == "table" and Source.Enabled == true and type(Source.Settings) == "table" and Source.Settings.NoSlowdown == true then
            local First, Second = select(1, ...), select(2, ...)
            if First == "SD" then return OldAffectChar("SD", 0, "x", 0) end
            if Second == "SD" then return OldAffectChar(First, "SD", 0, "x", 0) end
        end
        return OldAffectChar(...)
    end
    if type(newcclosure) == "function" then Callback = newcclosure(Callback) end
    OldAffectChar = hookfunction(AffectChar, Callback)
    if type(OldAffectChar) ~= "function" then return false end
    AffectHook.Hooked[AffectChar] = true
    return true
end

function ScaleRecoil(Value, Scale, Depth)
    Scale = math.clamp(tonumber(Scale) or 1, 0, 1)
    Depth = math.floor(tonumber(Depth) or 0)
    if type(Value) == "number" then return Value * Scale end
    if typeof(Value) == "Vector2" or typeof(Value) == "Vector3" then return Value * Scale end
    if type(Value) == "table" and Depth < 2 then
        local Copy = table.clone(Value)
        for Key, Nested in pairs(Copy) do
            if type(Nested) == "number" or typeof(Nested) == "Vector2" or typeof(Nested) == "Vector3" or type(Nested) == "table" then
                Copy[Key] = ScaleRecoil(Nested, Scale, Depth + 1)
            end
        end
        return Copy
    end
    return Value
end

function IsPatchedFireRate(Value)
    Value = tonumber(Value)
    if not Value then return false end
    return math.abs(Value - 999) < 0.001 or Value >= math.max((tonumber(AtramentaRageFireRate.MaxRate) or 999999) * 0.5, 100000)
end

function GetToolOriginalFireRate(Tool)
    if not Tool or not Tool:IsA("Tool") then return nil end
    local Module = GetGunConfigModule(Tool)
    if not Module then return nil end
    local Success, Config = Internal.Call(require, Module)
    if not Success or type(Config) ~= "table" then return nil end
    RegisterAtramentaWeaponConfigSource(Config)
    local Original = AtramentaWeaponConfigSource.Originals[Config]
    local Rate = type(Original) == "table" and tonumber(Original.FireRate) or nil
    if Rate and not IsPatchedFireRate(Rate) then return Rate end
    local RageOriginal = tonumber(AtramentaRageFireRate.Originals[Config])
    if RageOriginal and not IsPatchedFireRate(RageOriginal) then return RageOriginal end
    local Current = tonumber(rawget(Config, "FireRate"))
    if Current and not IsPatchedFireRate(Current) then return Current end
    return nil
end

function GetFunctionTool(Function)
    if type(Function) ~= "function" then return nil end
    local Env
    if type(getfenv) == "function" then
        local Success, Value = Internal.Call(getfenv, Function)
        if Success and type(Value) == "table" then Env = Value end
    end
    local ScriptObject = Env and rawget(Env, "script") or nil
    if typeof(ScriptObject) ~= "Instance" then return nil end
    local Current = ScriptObject
    while Current do
        if Current:IsA("Tool") then return Current end
        Current = Current.Parent
    end
    return nil
end

function GetEquippedOriginalFireRate()
    local Character = LocalPlayer.Character
    if not Character then return nil end
    local Tool = Character:FindFirstChildOfClass("Tool")
    return Tool and GetToolOriginalFireRate(Tool) or nil
end

function ResolveFireRateOriginal(Record)
    if type(Record) ~= "table" then return nil end
    local Original = tonumber(Record.Original)
    if Original and not IsPatchedFireRate(Original) then return Original end
    local ToolRate = GetToolOriginalFireRate(Record.Tool)
    if ToolRate then Record.Original = ToolRate; return ToolRate end
    local EquippedRate = GetEquippedOriginalFireRate()
    if EquippedRate then Record.Original = EquippedRate; return EquippedRate end
    return nil
end

function RestoreRageFireRateUpvalues()
    if type(GunMods) ~= "table" or type(GunMods.Upvalues) ~= "table" then return end
    local Settings = Configuration.NoRecoil.Settings.GunMods
    local WeaponModsActive = Configuration.NoRecoil.Enabled == true
    for Function, Records in pairs(GunMods.Upvalues) do
        if type(Function) == "function" and type(Records) == "table" then
            for Index = 1, #Records do
                local Record = Records[Index]
                if type(Record) == "table" and Record.Key == "FireRate" and type(Record.Index) == "number" then
                    local Original = ResolveFireRateOriginal(Record)
                    if Original then
                        local Value = WeaponModsActive and Settings.InstantBullet == true and 999 or Original
                        WriteUpvalue(Function, Record.Index, Value)
                    end
                end
            end
        end
    end
end

function GetGunKey(Name, Value)
    if type(Name) ~= "string" or type(Value) ~= "number" then return nil end
    local Key = string.lower(Name):gsub("[^%w]", "")
    if Key == "firerate" or Key == "gunfirerate" or Key == "weaponfirerate" then return "FireRate" end
    if Key == "spread" or Key == "gunspread" or Key == "weaponspread" then return "Spread" end
    if Key == "recoil" or Key == "gunrecoil" or Key == "weaponrecoil" then return "Recoil" end
    if string.find(Key, "equip", 1, true) then
        if string.find(Key, "anim", 1, true) and string.find(Key, "speed", 1, true) then return "EquipAnimSpeed" end
        if string.find(Key, "time", 1, true) then return "EquipTime" end
    end
    if string.find(Key, "reload", 1, true) then
        if string.find(Key, "slow", 1, true) then return "ReloadSlowDown" end
        if string.find(Key, "anim", 1, true) and string.find(Key, "speed", 1, true) then return "ReloadAnimSpeed" end
        if string.find(Key, "time", 1, true) then return "ReloadTime" end
    end
    if string.find(Key, "charge", 1, true) then
        if string.find(Key, "db", 1, true) or string.find(Key, "debounce", 1, true) then return "ChargeDB" end
        if string.find(Key, "time", 1, true) then return "ChargeTime" end
    end
    return nil
end

function IsGunConfig(Value)
    if type(Value) ~= "table" then return false end
    local FireRate = rawget(Value, "FireRate")
    local Spread = rawget(Value, "Spread")
    local Recoil = rawget(Value, "Recoil")
    if type(FireRate) ~= "number" or (type(Spread) ~= "number" and type(Recoil) ~= "number") then return false end
    if rawget(Value, "Name") ~= nil then return true end
    return type(rawget(Value, "EquipTime")) == "number" or type(rawget(Value, "ReloadTime")) == "number" or type(rawget(Value, "ChargeTime")) == "number"
end

function IndexGunTable(Value)
    if type(Value) ~= "table" or GunMods.Tables[Value] then return false end
    GunMods.Tables[Value] = true
    if not IsGunConfig(Value) then return false end
    RegisterAtramentaWeaponConfigSource(Value)
    return true
end

function IndexGunFunction(Function)
    if type(Function) ~= "function" or GunMods.Functions[Function] then return false end
    GunMods.Functions[Function] = true
    local FunctionName
    if type(debug) == "table" and type(debug.info) == "function" then
        local Success, Name = Internal.Call(debug.info, Function, "n")
        if Success then FunctionName = Name end
    end
    if FunctionName == "getSPRD" then
        GunMods.SpreadCallers[Function] = true
        SpreadHook.Callers[Function] = true
    end
    if type(debug) ~= "table" or type(debug.getupvalues) ~= "function" then return false end
    local Success, Values = Internal.Call(debug.getupvalues, Function)
    if not Success or type(Values) ~= "table" then return false end
    local Candidate = FunctionName == "getSPRD"
    for Name, Value in pairs(Values) do
        if GetGunKey(Name, Value) or type(Value) == "table" and IsGunConfig(Value) then Candidate = true; break end
    end
    if not Candidate then return false end
    local Tool = GetFunctionTool(Function)
    local Records
    for Index = 1, 48 do
        local Ok, Name, Value = ReadUpvalue(Function, Index)
        if not Ok then break end
        if type(Value) == "table" and IsGunConfig(Value) then RegisterAtramentaWeaponConfigSource(Value) end
        local Key = GetGunKey(Name, Value)
        if Key then
            local Original = Value
            if Key == "FireRate" and IsPatchedFireRate(Original) then Original = GetToolOriginalFireRate(Tool) or GetEquippedOriginalFireRate() end
            Records = Records or {}
            Records[#Records + 1] = {Index = Index, Key = Key, Original = Original, Tool = Tool}
        end
    end
    if Records then GunMods.Upvalues[Function] = Records; return true end
    return false
end

function GetGunValue(Key, Original)
    if type(Original) ~= "number" then return Original end
    local Settings = Configuration.NoRecoil.Settings.GunMods
    local Active = Configuration.NoRecoil.Enabled == true
    if Key == "FireRate" then
        if AtramentaRageFireRate.Enabled == true then return AtramentaRageFireRate.MaxRate end
        return Active and Settings.InstantBullet == true and 999 or Original
    end
    if not Active then return Original end
    if Key == "Spread" then
        if Settings.NoSpread == true then return 0.001 end
        if Settings.Spread == true then return math.max(tonumber(Settings.SpreadAmount) or 0, 0.001) end
        return Original
    end
    if Key == "Recoil" then
        if Settings.NoRecoil ~= true then return Original end
        local Scale = GetRecoilScale()
        if Scale <= 0.001 then return Original == 0 and 0 or 0.001 end
        return Original * Scale
    end
    if Key == "EquipTime" then return Settings.InstantEquip == true and 0.01 or Original end
    if Key == "EquipAnimSpeed" then return Settings.InstantEquip == true and 999 or Original end
    if Key == "ReloadTime" then return Settings.InstantReload == true and 0.01 or Original end
    if Key == "ReloadAnimSpeed" then return Settings.InstantReload == true and 999 or Original end
    if Key == "ReloadSlowDown" then return (Settings.InstantReload == true or Settings.NoSlowdown == true) and 0 or Original end
    if Key == "ChargeTime" or Key == "ChargeDB" then return Settings.InstantCharge == true and 0.01 or Original end
    return Original
end

function ApplyGunValues()
    for Function, Records in pairs(GunMods.Upvalues) do
        if type(Function) == "function" and type(Records) == "table" then
            for Index = 1, #Records do
                local Record = Records[Index]
                if type(Record) == "table" and type(Record.Index) == "number" then
                    local Original = Record.Key == "FireRate" and ResolveFireRateOriginal(Record) or tonumber(Record.Original)
                    if Original then WriteUpvalue(Function, Record.Index, GetGunValue(Record.Key, Original)) end
                end
            end
        end
    end
end

function RestoreGunValues()
    RestoreGunTable(GunMods)
end

function ScanGuns(Force)
    if type(getgc) ~= "function" then return false end
    if GunMods.Scanning then
        if Force == true then GunMods.ScanAgain = true end
        return true
    end
    if GunMods.Scanned and Force ~= true then return true end
    local Now = os.clock()
    if Force == true and Now - GunMods.LastScan < 1.25 then return true end
    GunMods.LastScan = Now
    GunMods.Scanning = true
    GunMods.ScanAgain = false
    GunMods.ScanToken += 1
    local Token = GunMods.ScanToken
    task.spawn(function()
        local Success, Objects = Internal.Call(getgc, true)
        if not Success or type(Objects) ~= "table" then GunMods.Scanning = false; return end
        local Batch = 48
        for Index = 1, #Objects do
            if Token ~= GunMods.ScanToken then break end
            local Object = Objects[Index]
            if type(Object) == "table" then IndexGunTable(Object)
            elseif type(Object) == "function" then IndexGunFunction(Object) end
            if Index % Batch == 0 then task.wait() end
        end
        if Token == GunMods.ScanToken then
            GunMods.Scanning = false
            GunMods.Scanned = true
            for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
            ApplyGunValues()
            if GunMods.ScanAgain then task.defer(ScanGuns, true) end
        end
    end)
    return true
end

function GetGunAnimations(Tool)
    local Cached = GunMods.Animations[Tool]
    if type(Cached) == "table" then return Cached end
    Cached = {Equip = {}, Reload = {}}
    GunMods.Animations[Tool] = Cached
    if not Tool or not Tool.Parent then return Cached end
    for _, Object in ipairs(Tool:GetDescendants()) do
        if Object:IsA("Animation") then
            local Name = string.lower(Object.Name)
            local Id = tostring(Object.AnimationId)
            if string.find(Name, "equip", 1, true) or string.find(Name, "draw", 1, true) or string.find(Name, "pull", 1, true) then Cached.Equip[Id] = true end
            if string.find(Name, "reload", 1, true) then Cached.Reload[Id] = true end
        end
    end
    return Cached
end

function SpeedGunAnimation(Tool, Mode)
    local Character = LocalPlayer.Character
    if not Character or not Tool or Tool.Parent ~= Character then return end
    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    local Animator = Humanoid and Humanoid:FindFirstChildOfClass("Animator")
    if not Animator or type(Animator.GetPlayingAnimationTracks) ~= "function" then return end
    local Ids = GetGunAnimations(Tool)[Mode]
    local Success, Tracks = Internal.Call(Animator.GetPlayingAnimationTracks, Animator)
    if not Success or type(Tracks) ~= "table" then return end
    for _, Track in ipairs(Tracks) do
        local Name = string.lower(tostring(Track.Name or ""))
        local Animation = Track.Animation
        local Id = Animation and tostring(Animation.AnimationId) or ""
        local Match = Ids and Ids[Id] == true
        if Mode == "Equip" then Match = Match or string.find(Name, "equip", 1, true) or string.find(Name, "draw", 1, true) or string.find(Name, "pull", 1, true)
        else Match = Match or string.find(Name, "reload", 1, true) end
        if Match then Internal.Call(Track.AdjustSpeed, Track, 999) end
    end
end

function FastEquip(Tool)
    if Configuration.NoRecoil.Enabled and Configuration.NoRecoil.Settings.GunMods.InstantEquip then SpeedGunAnimation(Tool, "Equip") end
end

function FastReload(Tool)
    if not Configuration.NoRecoil.Enabled or not Configuration.NoRecoil.Settings.GunMods.InstantReload or not Tool then return end
    GunMods.ReloadAnimToken = (tonumber(GunMods.ReloadAnimToken) or 0) + 1
    local Token = GunMods.ReloadAnimToken
    task.spawn(function()
        for Index = 1, 8 do
            if GunMods.ReloadAnimToken ~= Token or not Configuration.NoRecoil.Enabled
                or not Configuration.NoRecoil.Settings.GunMods.InstantReload or not Tool.Parent then return end
            SpeedGunAnimation(Tool, "Reload")
            RunService.RenderStepped:Wait()
        end
    end)
end

function GetReloadTool()
    local Character = LocalPlayer.Character
    if not Character then return nil end
    for _, Tool in ipairs(Character:GetChildren()) do
        if Tool:IsA("Tool") then
            local Values = Tool:FindFirstChild("Values")
            if Tool:FindFirstChild("IsGun") or GetGunConfigModule(Tool) or Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo")) then return Tool end
        end
    end
    return nil
end

function GetReloadState(Tool)
    if not Tool or not Tool:IsA("Tool") or Tool.Parent ~= LocalPlayer.Character then return nil end
    local Values = Tool:FindFirstChild("Values")
    local Ammo = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    local Stored = Values and (Values:FindFirstChild("SERVER_StoredAmmo") or Values:FindFirstChild("StoredAmmo"))
    local AmmoValue = Ammo and tonumber(Ammo.Value) or nil
    local StoredValue = Stored and tonumber(Stored.Value) or nil
    if StoredValue ~= nil and StoredValue <= 0 then return nil end
    local Module = GetGunConfigModule(Tool)
    local Config
    if Module then
        local Success, Result = Internal.Call(require, Module)
        if Success and type(Result) == "table" then Config = Result end
    end
    local MagSize = type(Config) == "table" and tonumber(rawget(Config, "MagSize")) or nil
    if AmmoValue ~= nil and MagSize and AmmoValue >= MagSize then return nil end
    return {Ammo = Ammo, Stored = Stored, AmmoValue = AmmoValue, StoredValue = StoredValue, Config = Config}
end

function GetReloadKey(Tool, Config)
    if type(Ragebot) == "table" then
        if type(Ragebot.GetProtocolTimestamp) == "function" then
            local Success, Value = Internal.Call(Ragebot.GetProtocolTimestamp, Tool)
            if Success and typeof(Value) == "number" then return Value end
        end
        if type(Ragebot.GetServerTimestamp) == "function" then
            local Success, Value = Internal.Call(Ragebot.GetServerTimestamp, Tool, Config)
            if Success and typeof(Value) == "number" then return Value end
        end
    end
    return tick()
end

function FireReload(Tool, State)
    if not Tool or Tool.Parent ~= LocalPlayer.Character then return false end
    local Events = ReplicatedStorage:FindFirstChild("Events")
    local Remote = Events and Events:FindFirstChild("GNX_R")
    if not Remote or not Remote:IsA("RemoteEvent") then return false end
    local Key = GetReloadKey(Tool, State and State.Config or nil)
    GunMods.ReloadSuppressTool = Tool
    GunMods.ReloadSuppressUntil = os.clock() + 0.15
    return Internal.Call(Remote.FireServer, Remote, Key, "KLWE89U0", Tool) == true
end

function InstantReload(Tool, Force)
    local Settings = Configuration.NoRecoil.Settings.GunMods
    if not Configuration.NoRecoil.Enabled or not Settings.InstantReload then return false end
    Tool = Tool or GetReloadTool()
    local State = GetReloadState(Tool)
    if not State then return false end
    local Now = os.clock()
    if GunMods.ReloadBusy then return false end
    local Gap = Force == true and 0.035 or 0.08
    if Now - (tonumber(GunMods.ReloadLast) or 0) < Gap then return false end
    GunMods.ReloadLast = Now
    GunMods.ReloadBusy = true
    GunMods.ReloadToken = (tonumber(GunMods.ReloadToken) or 0) + 1
    local Token = GunMods.ReloadToken
    GunMods.ReloadTool = Tool
    if type(ApplyGunValues) == "function" then ApplyGunValues() end
    FastReload(Tool)
    local Fired = FireReload(Tool, State)
    GunMods.ReloadBusy = false
    if not Fired then return false end
    task.spawn(function()
        for Index = 1, 8 do
            if GunMods.ReloadToken ~= Token or not Configuration.NoRecoil.Enabled or not Settings.InstantReload
                or not Tool or Tool.Parent ~= LocalPlayer.Character then return end
            FastReload(Tool)
            RunService.RenderStepped:Wait()
        end
    end)
    task.delay(0.045, function()
        if GunMods.ReloadToken ~= Token or not Configuration.NoRecoil.Enabled or not Settings.InstantReload
            or not Tool or Tool.Parent ~= LocalPlayer.Character then return end
        local Current = GetReloadState(Tool)
        if not Current then return end
        if State.AmmoValue ~= nil and Current.AmmoValue ~= nil and Current.AmmoValue > State.AmmoValue then return end
        FireReload(Tool, Current)
        FastReload(Tool)
    end)
    return true
end

function BindReloadKey()
    if GunMods.ReloadConnection then return true end
    GunMods.ReloadConnection = UserInputService.InputBegan:Connect(function(Input)
        if Input.KeyCode ~= Enum.KeyCode.R or not Configuration.NoRecoil.Enabled
            or not Configuration.NoRecoil.Settings.GunMods.InstantReload then return end
        if UserInputService:GetFocusedTextBox() then return end
        local Tool = GetReloadTool()
        if Tool then task.defer(InstantReload, Tool, true) end
    end)
    return true
end

function UnbindReloadKey()
    DropConnection(GunMods.ReloadConnection)
    GunMods.ReloadConnection = nil
    GunMods.ReloadBusy = false
    GunMods.ReloadToken = (tonumber(GunMods.ReloadToken) or 0) + 1
    GunMods.ReloadTool = nil
    GunMods.ReloadSuppressUntil = 0
    GunMods.ReloadSuppressTool = nil
end

function BindBackpack()
    if not Configuration.NoRecoil.Enabled then return false end
    if GunMods.BackpackConnection then return true end
    local Backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    if not Backpack then return false end
    GunMods.BackpackConnection = Backpack.ChildAdded:Connect(function(Tool)
        if Configuration.NoRecoil.Enabled and Tool:IsA("Tool") then task.defer(HandleGun, Tool) end
    end)
    for _, Tool in ipairs(Backpack:GetChildren()) do if Tool:IsA("Tool") then task.defer(HandleGun, Tool) end end
    return true
end

function UnbindBackpack()
    DropConnection(GunMods.BackpackConnection)
    GunMods.BackpackConnection = nil
end

function ApplyGunMods()
    SyncGunMods()
    for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
    ApplyGunValues()
end

function ResetGunMods()
    local Enabled = AtramentaWeaponConfigSource.Enabled
    AtramentaWeaponConfigSource.Enabled = false
    AtramentaInfiniteRange.Enabled = false
    if type(AtramentaExtraState) == "table" and type(AtramentaExtraState.ScopeGlint) == "table" then AtramentaExtraState.ScopeGlint.Enabled = false end
    for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
    AtramentaWeaponConfigSource.Enabled = Enabled
end

function HookGunMods()
    local Settings = Configuration.NoRecoil.Settings.GunMods
    BindBackpack()
    if Settings.NoSpread then HookSpread() end
    if Settings.NoSlowdown then HookSlowdown() end
    if Settings.InstantReload then BindReloadKey() else UnbindReloadKey() end
    if (Settings.NoRecoil or Settings.NoScopeGlint or Settings.InstantReload) and type(InstallSharedNamecallRouter) == "function" then InstallSharedNamecallRouter() end
end

function RefreshGunMods(Rescan)
    SyncGunMods()
    if Rescan or not Configuration.NoRecoil.CacheReady then RefreshGunConfigs() end
    for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
    ApplyGunValues()
    if not Configuration.NoRecoil.Enabled then return end
    HookGunMods()
    if not GunMods.Scanned then ScanGuns(false) elseif Rescan then ScanGuns(true) end
end

function QueueGunMods(Rescan)
    if Rescan then Configuration.NoRecoil.CacheReady = false end
    if GunMods.RefreshQueued then
        GunMods.RefreshForce = GunMods.RefreshForce or Rescan == true
        return
    end
    GunMods.RefreshQueued = true
    GunMods.RefreshForce = Rescan == true
    task.defer(function()
        local Force = GunMods.RefreshForce
        GunMods.RefreshQueued = false
        GunMods.RefreshForce = false
        RefreshGunMods(Force)
    end)
end

function HandleGun(Tool)
    if not Configuration.NoRecoil.Enabled or not Tool or not Tool:IsA("Tool") then return end
    if Configuration.NoRecoil.ToolJobs[Tool] then return end
    Configuration.NoRecoil.ToolJobs[Tool] = true
    local Registered = RegisterGun(Tool)
    local Settings = Configuration.NoRecoil.Settings.GunMods
    if Tool.Parent ~= LocalPlayer.Character and (Settings.InstantEquip or Settings.InstantReload) and GunMods.Animations[Tool] == nil then task.defer(GetGunAnimations, Tool) end
    if Tool.Parent == LocalPlayer.Character and Settings.InstantEquip then
        task.defer(FastEquip, Tool)
        task.delay(0.02, FastEquip, Tool)
    end
    if not Registered and Tool.Parent then
        task.delay(0.15, function()
            if Configuration.NoRecoil.Enabled and Tool and Tool.Parent then RegisterGun(Tool) end
        end)
    end
    Configuration.NoRecoil.ToolJobs[Tool] = nil
end

function BindGunCharacter(Character)
    DropConnection(Configuration.NoRecoil.CharacterChildConnection)
    Configuration.NoRecoil.CharacterChildConnection = nil
    GunMods.CharacterToken += 1
    local Token = GunMods.CharacterToken
    Configuration.NoRecoil.CacheReady = false
    Configuration.NoRecoil.ToolConfigLookup = setmetatable({}, {__mode = "k"})
    if not Character then return end
    Configuration.NoRecoil.CharacterChildConnection = Character.ChildAdded:Connect(function(Tool)
        if Token ~= GunMods.CharacterToken or not Tool:IsA("Tool") then return end
        if Configuration.NoRecoil.Enabled and Configuration.NoRecoil.Settings.GunMods.InstantEquip then task.defer(FastEquip, Tool) end
        HandleGun(Tool)
    end)
    for _, Tool in ipairs(Character:GetChildren()) do if Tool:IsA("Tool") then task.defer(HandleGun, Tool) end end
    task.defer(function()
        if Configuration.NoRecoil.Enabled and Character == LocalPlayer.Character and Token == GunMods.CharacterToken then RefreshGunMods(false) end
    end)
end

function EnableGunMods()
    if Configuration.NoRecoil.Enabled then QueueGunMods(false); return end
    Configuration.NoRecoil.Enabled = true
    SyncGunMods()
    HookGunMods()
    RefreshGunConfigs()
    ApplyGunMods()
    if LocalPlayer.Character then BindGunCharacter(LocalPlayer.Character) end
    ScanGuns(false)
end

function DisableGunMods()
    if not Configuration.NoRecoil.Enabled then return end
    Configuration.NoRecoil.Enabled = false
    GunMods.ScanToken += 1
    GunMods.Scanning = false
    GunMods.Scanned = false
    SyncGunMods()
    AtramentaInfiniteRange.Enabled = false
    if type(AtramentaExtraState) == "table" and type(AtramentaExtraState.ScopeGlint) == "table" then AtramentaExtraState.ScopeGlint.Enabled = false end
    for Config in pairs(AtramentaWeaponConfigSource.Configs) do ApplyAtramentaWeaponConfigSource(Config) end
    ApplyGunValues()
    DropConnection(Configuration.NoRecoil.CharacterChildConnection)
    Configuration.NoRecoil.CharacterChildConnection = nil
    for _, Connection in ipairs(Configuration.NoRecoil.Connections) do DropConnection(Connection) end
    Configuration.NoRecoil.Connections = {}
    Configuration.NoRecoil.ToolConfigLookup = setmetatable({}, {__mode = "k"})
    Configuration.NoRecoil.ToolJobs = setmetatable({}, {__mode = "k"})
    Configuration.NoRecoil.CacheReady = false
    UnbindReloadKey()
    UnbindBackpack()
end

function ToggleGunMods(Value)
    if Value then EnableGunMods() else DisableGunMods() end
end

IsGetSPRDRandomCallerNR = IsSpreadCaller
ZeroSpreadRandomNR = ZeroSpreadRandom

function FindRespawnButton()
    local Cached = AtramentaPerformanceRuntime and AtramentaPerformanceRuntime.RespawnButton or nil
    if Cached and Cached.Parent and Cached:IsA("GuiButton") then return Cached end

    local Gui = PlayerGui
    if not Gui or not Gui.Parent then Gui = LocalPlayer and LocalPlayer:FindFirstChildOfClass("PlayerGui") or nil end
    if not Gui then return nil end

    for _, Descendant in ipairs(Gui:GetDescendants()) do
        if Descendant and Descendant:IsA("GuiButton") then
            local Name = string.lower(tostring(Descendant.Name or "")) local Text = Descendant:IsA("TextButton") and string.lower(tostring(Descendant.Text or "")) or ""
            if string.find(Name, "respawn", 1, true) or string.find(Text, "respawn", 1, true) then
                if AtramentaPerformanceRuntime then AtramentaPerformanceRuntime.RespawnButton = Descendant end
                return Descendant
            end
        end
    end

    return nil
end

function TriggerRespawnButton()
    local RespawnButton = FindRespawnButton()
    if not RespawnButton or not RespawnButton.Parent then return false end
    if type(ActivateGuiButton) ~= "function" then return false end
    return ActivateGuiButton(RespawnButton) == true
end

function GetDeathRespawnEvent()
    if DeathRespawnEvent and DeathRespawnEvent.Parent then return DeathRespawnEvent end
    local Events = ReplicatedStorage and ReplicatedStorage:FindFirstChild("Events")
    DeathRespawnEvent = Events and Events:FindFirstChild("DeathRespawn") or nil
    return DeathRespawnEvent
end

function TriggerRespawnRemote()
    local Remote = GetDeathRespawnEvent()
    if not Remote then return false end

    if Remote:IsA("RemoteEvent") then
        local Success = Internal.Call(function() Remote:FireServer("KMG4R904") end)
        if Success then return true end
        return Internal.Call(function() Remote:FireServer() end) == true
    end

    if Remote:IsA("RemoteFunction") then
        local Success = Internal.Call(function() Remote:InvokeServer("KMG4R904") end)
        if Success then return true end
        return Internal.Call(function() Remote:InvokeServer() end) == true
    end

    if Remote:IsA("BindableEvent") then return Internal.Call(function() Remote:Fire() end) == true end

    return false
end

function RequestCharacterRespawn()
    if not LocalPlayer then return false end

    local Character = LocalPlayer.Character
    if not Character or not Character.Parent then return false end

    local Humanoid = Character:FindFirstChildOfClass("Humanoid")
    if not Humanoid or not Humanoid.Parent or Humanoid.Health > 0 then return false end

    local CurrentTime = os.clock()
    if RespawnSafetyState.RespawnRequestedFor == Character and CurrentTime - (tonumber(RespawnSafetyState.LastRespawnRequest) or 0) < 2.2 then return false end

    RespawnSafetyState.RespawnRequestedFor = Character
    RespawnSafetyState.LastRespawnRequest = CurrentTime

    if TriggerRespawnRemote() then return true end
    return TriggerRespawnButton()
end

function AutoRespawnEnable()
    if AutoRespawnEnabled then return end
    AutoRespawnEnabled = true

    if AutoRespawnCoroutine then
        Internal.Call(function() task.cancel(AutoRespawnCoroutine) end)
        AutoRespawnCoroutine = nil
    end

    AutoRespawnCoroutine = task.spawn(function()
        while AutoRespawnEnabled do
            task.wait(0.55)
            if not AutoRespawnEnabled then break end

            local Character = LocalPlayer and LocalPlayer.Character local Humanoid = Character and Character.Parent and Character:FindFirstChildOfClass("Humanoid") or nil

            if Character and Humanoid and Humanoid.Parent and Humanoid.Health <= 0 then
                RequestCharacterRespawn()
                task.wait(0.85)
            elseif not Character then
                RespawnSafetyState.RespawnRequestedFor = nil
            end
        end

        AutoRespawnCoroutine = nil
    end)
end

function AutoRespawnDisable()
    AutoRespawnEnabled = false
    RespawnSafetyState.RespawnRequestedFor = nil

    if AutoRespawnCoroutine then
        Internal.Call(function() task.cancel(AutoRespawnCoroutine) end)
        AutoRespawnCoroutine = nil
    end
end

