function AtramentaExtraGetCameraBobbingState()
    if type(AtramentaExtraState) ~= "table" then AtramentaExtraState = {} end

    local Current = AtramentaExtraState.CameraBobbing

    if type(Current) ~= "table" then
        Current = { Enabled = Current == true, Config = nil, Original = {}, Connection = nil, Accumulator = 0 }

        AtramentaExtraState.CameraBobbing = Current
    end

    if type(Current.Original) ~= "table" then Current.Original = {} end

    if type(Current.Enabled) ~= "boolean" then Current.Enabled = Current.Enabled == true end

    if type(Current.Accumulator) ~= "number" then Current.Accumulator = 0 end

    return Current
end
