AtramentaExtraGetCameraBobbingState()

function AtramentaExtraFindCameraBobbingConfig()
    local State = AtramentaExtraGetCameraBobbingState()

    if type(State.Config) == "table" then return State.Config end

    if type(getgc) ~= "function" then return nil end

    local Success, Objects = Internal.Call( getgc, true)

    if not Success or type(Objects) ~= "table" then return nil end

    for _, Object in pairs(Objects) do
        if type(Object) == "table" and ( rawget( Object, "CameraBobbing" ) ~= nil or rawget( Object, "Bobbing" ) ~= nil ) then
            State.Config = Object

            return Object
        end
    end

    return nil
end

function AtramentaExtraApplyCameraBobbing()
    local State = AtramentaExtraGetCameraBobbingState()

    if State.Enabled ~= true then return end

    local Config = AtramentaExtraFindCameraBobbingConfig()

    if type(Config) ~= "table" then return end

    if rawget( Config, "CameraBobbing" ) ~= nil then
        if State.Original.CameraBobbing == nil then State.Original.CameraBobbing = Config.CameraBobbing end

        Config.CameraBobbing = false
    end

    if rawget( Config, "Bobbing" ) ~= nil then
        if State.Original.Bobbing == nil then State.Original.Bobbing = Config.Bobbing end

        Config.Bobbing = false
    end
end

function AtramentaExtraSetCameraBobbing(Value)
    local State = AtramentaExtraGetCameraBobbingState()

    State.Enabled = Value == true

    State.Accumulator = 0

    if State.Enabled then
        AtramentaExtraApplyCameraBobbing()

        if not State.Connection then
            State.Connection = RunService.Heartbeat:Connect( function(DeltaTime)
                        local CurrentState = AtramentaExtraGetCameraBobbingState()

                        if CurrentState.Enabled ~= true then return end

                        CurrentState.Accumulator += math.min( tonumber(DeltaTime) or 0.016, 0.05)

                        if CurrentState.Accumulator < 0.15 then return end

                        CurrentState.Accumulator = 0

                        AtramentaExtraApplyCameraBobbing()
                    end)
        end
    else
        if State.Connection then
            State.Connection:Disconnect()
            State.Connection = nil
        end

        local Config = State.Config

        if type(Config) == "table" then
            if State.Original.CameraBobbing ~= nil and rawget( Config, "CameraBobbing" ) ~= nil then Config.CameraBobbing = State.Original.CameraBobbing end

            if State.Original.Bobbing ~= nil and rawget( Config, "Bobbing" ) ~= nil then Config.Bobbing = State.Original.Bobbing end
        end

        State.Config = nil

        State.Original = {}
    end
end

function AtramentaExtraApplyMaxZoom()
    local State = AtramentaExtraState and AtramentaExtraState.MaxZoom
    if type(State) ~= "table" or not State.Enabled or State.Applying then return end

    State.Applying = true
    LocalPlayer.CameraMaxZoomDistance = math.clamp(tonumber(State.Value) or 128, 10, 10000)
    State.Applying = false
end

function AtramentaExtraSetMaxZoom(Value)
    local State = AtramentaExtraState and AtramentaExtraState.MaxZoom
    if type(State) ~= "table" then return end

    State.Enabled = Value == true

    if State.Enabled then
        if State.Original == nil then State.Original = LocalPlayer.CameraMaxZoomDistance end
        AtramentaExtraApplyMaxZoom()

        if not State.Connection then
            State.Connection = LocalPlayer:GetPropertyChangedSignal("CameraMaxZoomDistance"):Connect(function()
                if State.Enabled and not State.Applying then AtramentaExtraApplyMaxZoom() end
            end)
        end
    else
        if State.Connection then State.Connection:Disconnect(); State.Connection = nil end

        if State.Original ~= nil then
            State.Applying = true
            LocalPlayer.CameraMaxZoomDistance = State.Original
            State.Applying = false
        end

        State.Original = nil
    end
end

function AtramentaExtraSetScopeGlint(Value)
    local Enabled = Value == true
    Configuration.NoRecoil.Settings.GunMods.NoScopeGlint = Enabled
    AtramentaWeaponConfigSource.Settings.NoScopeGlint = Enabled
    local State = AtramentaExtraState.ScopeGlint
    State.Enabled = Configuration.NoRecoil.Enabled == true and Enabled

    if State.CharacterConnection then State.CharacterConnection:Disconnect(); State.CharacterConnection = nil end
    if State.DescendantConnection then State.DescendantConnection:Disconnect(); State.DescendantConnection = nil end
    for Light, Original in pairs(State.Hidden) do if Light and Light.Parent then Light.Enabled = Original == true end end
    State.Hidden = setmetatable({}, {__mode = "k"})

    if Configuration.NoRecoil.Enabled and Enabled and type(InstallSharedNamecallRouter) == "function" then InstallSharedNamecallRouter() end
end

AtramentaExtraState.ShopLookup = type(AtramentaExtraState.ShopLookup) == "table" and AtramentaExtraState.ShopLookup or {
    Folder = nil, Entries = {}, Count = 0
}

function AtramentaExtraRefreshShopLookup()
    local Lookup = AtramentaExtraState.ShopLookup
    local Map = workspace:FindFirstChild("Map") local Shops = Map and Map:FindFirstChild("Shopz")
    if not Shops then
        Lookup.Folder = nil
        table.clear(Lookup.Entries)
        Lookup.Count = 0
        return false
    end

    if Lookup.Folder == Shops and Lookup.Count == #Shops:GetChildren() and #Lookup.Entries > 0 then return true end

    Lookup.Folder = Shops
    table.clear(Lookup.Entries)
    local Children = Shops:GetChildren()
    Lookup.Count = #Children

    for _, Shop in ipairs(Children) do
        if typeof(Shop) == "Instance" then
            local Success, MainPart = Internal.Call(function() return Shop:FindFirstChild("MainPart") end)
            if Success and MainPart and MainPart:IsA("BasePart") then
                local ShopName = string.lower(tostring(Shop.Name or ""))
                local Legal = string.find(ShopName, "armor", 1, true) ~= nil or string.find(ShopName, "legal", 1, true) ~= nil
                Lookup.Entries[#Lookup.Entries + 1] = {Shop = Shop, MainPart = MainPart, StoreType = Legal and "LegalStore" or "IllegalStore"}
            end
        end
    end

    return #Lookup.Entries > 0
end

function AtramentaExtraGetNearestShop(Root, MaximumDistance)
    if not Root or not Root.Parent or not Root:IsA("BasePart") then return nil end
    if not AtramentaExtraRefreshShopLookup() then return nil end

    local BestEntry, BestDistance
    MaximumDistance = math.max(tonumber(MaximumDistance) or 15, 0)

    for _, Entry in ipairs(AtramentaExtraState.ShopLookup.Entries) do
        local Shop, MainPart = Entry.Shop, Entry.MainPart
        if Shop and Shop.Parent and MainPart and MainPart.Parent then
            local Distance = (Root.Position - MainPart.Position).Magnitude
            if Distance <= MaximumDistance and (BestDistance == nil or Distance < BestDistance) then
                BestEntry = Entry
                BestDistance = Distance
            end
        end
    end

    if not BestEntry then return nil end
    return BestEntry.Shop, BestEntry.MainPart, BestEntry.StoreType
end

function AtramentaExtraAutoRefillTick()
    local State = AtramentaExtraState.AutoRefill
    if not State.Enabled or os.clock() - State.LastRefill < 0.5 then return end

    local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    local Tool = Character and Character:FindFirstChildOfClass("Tool")
    if not Root or not Tool then return end

    local Values = Tool:FindFirstChild("Values") local Current = Values and (Values:FindFirstChild("SERVER_Ammo") or Values:FindFirstChild("Ammo"))
    local Stored = Values and (Values:FindFirstChild("SERVER_StoredAmmo") or Values:FindFirstChild("StoredAmmo"))
    if not Current and not Stored then return end

    local Name = Tool.Name local CurrentValue = Current and tonumber(Current.Value) or nil
    local StoredValue = Stored and tonumber(Stored.Value) or nil local Config = Ragebot.GetWeaponConfig(Tool)
    local MagSize = type(Config) == "table" and tonumber(rawget(Config, "MagSize")) or nil

    if CurrentValue then State.MaxCurrent[Name] = math.max(tonumber(State.MaxCurrent[Name]) or CurrentValue, CurrentValue, MagSize or 0) end
    if StoredValue then State.MaxStored[Name] = math.max(tonumber(State.MaxStored[Name]) or StoredValue, StoredValue) end

    local NeedsRefill = CurrentValue and State.MaxCurrent[Name] and CurrentValue < State.MaxCurrent[Name]
        or StoredValue and State.MaxStored[Name] and StoredValue < State.MaxStored[Name]
    if not NeedsRefill then return end

    local Events = ReplicatedStorage:FindFirstChild("Events") local Protect = Events and Events:FindFirstChild("BYZERSPROTEC")
    local ShopRemote = Events and Events:FindFirstChild("SSHPRMTE1")
    if not Protect or not ShopRemote then return end

    local Shop, MainPart, StoreType = AtramentaExtraGetNearestShop(Root, 15)
    if not Shop or not MainPart or type(StoreType) ~= "string" then return end

    Internal.Call(function() Protect:FireServer() end)
    local Success = Internal.Call(function()
        return ShopRemote:InvokeServer(StoreType, "Guns", Name, MainPart, "ResupplyAmmo", true)
    end)

    if Success then State.LastRefill = os.clock() end
end

function AtramentaExtraSetAutoRefill(Value)
    local State = AtramentaExtraState.AutoRefill
    State.Enabled = Value == true
    State.Token += 1
    local Token = State.Token

    if not State.Enabled then return end

    task.spawn(function()
        while State.Enabled and State.Token == Token do
            AtramentaExtraAutoRefillTick()
            task.wait(0.18)
        end
    end)
end

function AtramentaExtraHasItem(Name)
    local Character = LocalPlayer.Character local Backpack = LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
    return Character and Character:FindFirstChild(Name) ~= nil or Backpack and Backpack:FindFirstChild(Name) ~= nil
end

function AtramentaExtraAutoBuyTick()
    local State = AtramentaExtraState.AutoBuy
    if not State.Enabled or os.clock() - State.LastBuy < 1 then return end
    if AtramentaExtraHasItem(State.Item) then return end

    local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    if not Root then return end

    local Events = ReplicatedStorage:FindFirstChild("Events") local ShopRemote = Events and Events:FindFirstChild("SSHPRMTE1")
    if not ShopRemote then return end

    local Shop, MainPart = AtramentaExtraGetNearestShop(Root, 15)
    if not Shop or not MainPart then return end

    local Categories = {"Guns", "Melees", "Throwables", "Misc"}
    local StoreTypes = {"IllegalStore", "LegalStore"}

    for StoreIndex = 1, #StoreTypes do
        for CategoryIndex = 1, #Categories do
            local Success, Result = Internal.Call(function()
                return ShopRemote:InvokeServer(StoreTypes[StoreIndex], Categories[CategoryIndex], State.Item, MainPart)
            end)

            if Success and Result ~= false then
                State.LastBuy = os.clock()
                return
            end
        end
    end

    State.LastBuy = os.clock()
end

function AtramentaExtraSetAutoBuy(Value)
    local State = AtramentaExtraState.AutoBuy
    State.Enabled = Value == true
    State.Token += 1
    local Token = State.Token

    if not State.Enabled then return end

    task.spawn(function()
        while State.Enabled and State.Token == Token do
            AtramentaExtraAutoBuyTick()
            task.wait(0.25)
        end
    end)
end

function AtramentaExtraGetSpoofText(Text)
    local State = AtramentaExtraState.NameSpoof
    Text = tostring(Text or "")

    if Text == "" then return Text end

    if LocalPlayer.DisplayName ~= "" and string.find(Text, LocalPlayer.DisplayName, 1, true) then Text = string.gsub(Text, LocalPlayer.DisplayName, State.FakeDisplay) end

    if LocalPlayer.Name ~= "" and string.find(Text, LocalPlayer.Name, 1, true) then Text = string.gsub(Text, LocalPlayer.Name, State.FakeName) end

    return Text
end

function AtramentaExtraProcessSpoofText(Object)
    local State = AtramentaExtraState.NameSpoof
    if not State.Enabled or State.Applying or not Object then return end
    if not (Object:IsA("TextLabel") or Object:IsA("TextButton") or Object:IsA("TextBox")) then return end

    local Current = Object.Text local Changed = AtramentaExtraGetSpoofText(Current)

    if Changed ~= Current then
        if State.Texts[Object] == nil then State.Texts[Object] = Current end
        State.Applying = true
        Object.Text = Changed
        State.Applying = false
    end
end

function AtramentaExtraApplyNameSpoof()
    local State = AtramentaExtraState.NameSpoof
    if not State.Enabled then return end

    local PlayerGuiObject = LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if PlayerGuiObject then
        for _, Object in ipairs(PlayerGuiObject:GetDescendants()) do
            AtramentaExtraProcessSpoofText(Object)
        end
    end

    local Character = LocalPlayer.Character local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    if Humanoid then
        if State.OriginalHumanoidDisplay == nil then State.OriginalHumanoidDisplay = Humanoid.DisplayName end
        Humanoid.DisplayName = State.FakeDisplay
    end
end

function AtramentaExtraSetNameSpoof(Value)
    local State = AtramentaExtraState.NameSpoof
    State.Enabled = Value == true

    for _, Connection in ipairs(State.Connections) do
        if Connection then Connection:Disconnect() end
    end
    State.Connections = {}

    if State.CharacterConnection then
        State.CharacterConnection:Disconnect()
        State.CharacterConnection = nil
    end

    if State.Enabled then
        AtramentaExtraApplyNameSpoof()

        local PlayerGuiObject = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if PlayerGuiObject then
            State.Connections[#State.Connections + 1] = PlayerGuiObject.DescendantAdded:Connect(function(Object)
                if State.Enabled then task.defer(AtramentaExtraProcessSpoofText, Object) end
            end)
        end

        State.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function()
            task.delay(0.4, function()
                if State.Enabled then AtramentaExtraApplyNameSpoof() end
            end)
        end)
    else
        State.Applying = true

        for Object, Original in pairs(State.Texts) do
            if Object and Object.Parent then Object.Text = Original end
        end

        local Character = LocalPlayer.Character local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

        if Humanoid and State.OriginalHumanoidDisplay ~= nil then Humanoid.DisplayName = State.OriginalHumanoidDisplay end

        State.Applying = false
        State.Texts = setmetatable({}, {__mode = "k"})
        State.OriginalHumanoidDisplay = nil
    end
end

function AtramentaExtraFindXPLabel()
    local Gui = LocalPlayer:FindFirstChildOfClass("PlayerGui") local Core = Gui and Gui:FindFirstChild("CoreGUI")
    local Frame = Core and Core:FindFirstChild("LevelFrame") local Bar = Frame and Frame:FindFirstChild("Bar") local Stat = Bar and Bar:FindFirstChild("Stat")
    return Stat and (Stat:IsA("TextLabel") or Stat:IsA("TextButton")) and Stat or nil
end

function AtramentaExtraFindLevelLabel()
    local Gui = LocalPlayer:FindFirstChildOfClass("PlayerGui") local Core = Gui and Gui:FindFirstChild("CoreGUI")
    local Frame = Core and Core:FindFirstChild("LevelFrame") local Box = Frame and Frame:FindFirstChild("LevelBox") local Number = Box and Box:FindFirstChild("LevelNumber")
    return Number and (Number:IsA("TextLabel") or Number:IsA("TextButton")) and Number or nil
end

function AtramentaExtraFindLeaderboardLevel()
    local Leaderstats = LocalPlayer:FindFirstChild("leaderstats") local Level = Leaderstats and (Leaderstats:FindFirstChild("Level") or Leaderstats:FindFirstChild("Lvl"))

    if Level and (Level:IsA("IntValue") or Level:IsA("NumberValue")) then return Level end

    local DataRoot = ReplicatedStorage:FindFirstChild("PlayerbaseData2") local PlayerData = DataRoot and DataRoot:FindFirstChild(LocalPlayer.Name)
    Level = PlayerData and (PlayerData:FindFirstChild("Level") or PlayerData:FindFirstChild("Lvl"))

    if Level and (Level:IsA("IntValue") or Level:IsA("NumberValue")) then return Level end

    return nil
end

function AtramentaExtraUpdateHudSpoof()
    local State = AtramentaExtraState.HudSpoof

    if State.XPEnabled then
        local Label = AtramentaExtraFindXPLabel()

        if Label then
            if State.XPOriginal == nil then State.XPOriginal = Label.Text end
            if Label.Text ~= State.XPText then Label.Text = State.XPText end
        end
    end

    if State.LevelEnabled then
        local Label = AtramentaExtraFindLevelLabel()

        if Label then
            if State.LevelOriginal == nil then State.LevelOriginal = Label.Text end
            if Label.Text ~= State.LevelText then Label.Text = State.LevelText end
        end
    end

    if State.LeaderboardEnabled then
        local Level = AtramentaExtraFindLeaderboardLevel()

        if Level then
            if State.LeaderboardOriginal == nil then State.LeaderboardOriginal = Level.Value end
            local Value = math.floor(tonumber(State.LeaderboardValue) or 999)
            if Level.Value ~= Value then Level.Value = Value end
        end
    end
end

function AtramentaExtraRefreshHudSpoof()
    local State = AtramentaExtraState.HudSpoof local Enabled = State.XPEnabled or State.LevelEnabled or State.LeaderboardEnabled

    if Enabled then
        AtramentaExtraUpdateHudSpoof()

        if not State.Connection then
            State.Connection = RunService.Heartbeat:Connect(function(DeltaTime)
                State.Accumulator += math.min(tonumber(DeltaTime) or 0.016, 0.05)
                if State.Accumulator < 0.20 then return end
                State.Accumulator = 0
                AtramentaExtraUpdateHudSpoof()
            end)
        end
    else
        if State.Connection then State.Connection:Disconnect(); State.Connection = nil end
        State.Accumulator = 0
    end
end

function AtramentaExtraRestoreHudSpoof()
    local State = AtramentaExtraState.HudSpoof

    local XP = AtramentaExtraFindXPLabel()
    if XP and State.XPOriginal ~= nil then XP.Text = State.XPOriginal end

    local LevelLabel = AtramentaExtraFindLevelLabel()
    if LevelLabel and State.LevelOriginal ~= nil then LevelLabel.Text = State.LevelOriginal end

    local LeaderLevel = AtramentaExtraFindLeaderboardLevel()
    if LeaderLevel and State.LeaderboardOriginal ~= nil then LeaderLevel.Value = State.LeaderboardOriginal end

    State.XPOriginal = nil
    State.LevelOriginal = nil
    State.LeaderboardOriginal = nil
end

function AtramentaExtraDestroy()
    AtramentaExtraSetCameraBobbing(false)
    AtramentaExtraSetMaxZoom(false)
    AtramentaExtraSetScopeGlint(false)
    AtramentaExtraSetAutoRefill(false)
    AtramentaExtraSetAutoBuy(false)
    AtramentaExtraSetNameSpoof(false)

    local Hud = AtramentaExtraState.HudSpoof
    Hud.XPEnabled = false
    Hud.LevelEnabled = false
    Hud.LeaderboardEnabled = false
    AtramentaExtraRefreshHudSpoof()
    AtramentaExtraRestoreHudSpoof()
end

