if type(GrenadeTrajectoryState) == "table" then
    if GrenadeTrajectoryState.Connection then GrenadeTrajectoryState.Connection:Disconnect() end
    if GrenadeTrajectoryState.DebrisConnection then GrenadeTrajectoryState.DebrisConnection:Disconnect() end

    if type(GrenadeTrajectoryState.ContainerConnections) == "table" then
        for Container, Connection in pairs(GrenadeTrajectoryState.ContainerConnections) do
            if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
            GrenadeTrajectoryState.ContainerConnections[Container] = nil
        end
    end

    if type(GrenadeTrajectoryState.Segments) == "table" then
        for Index = 1, #GrenadeTrajectoryState.Segments do
            local Object = GrenadeTrajectoryState.Segments[Index]
            if typeof(Object) == "Instance" and Object.Parent then
                Object:Destroy()
            elseif Object and type(Object.Remove) == "function" then
                Object:Remove()
            end
        end
    end

    if type(GrenadeTrajectoryState.BounceMarkers) == "table" then
        for Index = 1, #GrenadeTrajectoryState.BounceMarkers do
            local Object = GrenadeTrajectoryState.BounceMarkers[Index]
            if Object and type(Object.Remove) == "function" then Object:Remove() end
        end
    end

    if GrenadeTrajectoryState.ImpactMarker and type(GrenadeTrajectoryState.ImpactMarker.Remove) == "function" then GrenadeTrajectoryState.ImpactMarker:Remove() end
end

