function AutoBlockGetRemote()
    local Events = ReplicatedStorage:FindFirstChild("Events")
    return Events and Events:FindFirstChild("XMHH.2")
end

function AutoBlockGetServerTick()
    local Values = ReplicatedStorage:FindFirstChild("Values")
    return Values and Values:FindFirstChild("ServerTick")
end

function AutoBlockToolCanBlock(Tool)
    if not Tool or not Tool:IsA("Tool") then return false end
    if Tool:GetAttribute("CanBlock") == false then return false end
    local Cached = AutoBlockState.BlockCache[Tool]
    if Cached ~= nil then return Cached end
    local Anims = Tool:FindFirstChild("AnimsFolder") local CanBlock = Tool:GetAttribute("CanBlock") == true or Anims and Anims:FindFirstChild("BlockStart") ~= nil
    AutoBlockState.BlockCache[Tool] = CanBlock == true
    return CanBlock == true
end

function AutoBlockPlayerAttacking(Player)
    if not Player or not Player.Character then return false end
    local Tool = Player.Character:FindFirstChildOfClass("Tool")
    if not Tool or Tool:GetAttribute("Unblockable") == true or Tool:GetAttribute("IgnoreBlock") == true then return false end
    local Values = Tool:FindFirstChild("Values")
    if Values then
        local Attacking = Values:FindFirstChild("Attacking") local Slashing = Values:FindFirstChild("Slashing1")
        if Attacking and Attacking.Value == true or Slashing and Slashing.Value == true then return true end
        for _, Value in ipairs(Values:GetChildren()) do
            if Value:IsA("BoolValue") and Value.Value == true and string.find(string.lower(Value.Name), "slashing", 1, true) then return true end
        end
    end
    local Humanoid = Player.Character:FindFirstChildOfClass("Humanoid")
    if Humanoid then
        for _, Track in ipairs(Humanoid:GetPlayingAnimationTracks()) do
            local Name = string.lower(Track.Name)
            if string.find(Name, "slash", 1, true) or string.find(Name, "swing", 1, true) or string.find(Name, "attack", 1, true) or string.find(Name, "lunge", 1, true) or string.find(Name, "heavy", 1, true) then
                return true
            end
        end
    end
    return false
end

function AutoBlockSend(State, Tool)
    local Remote = AutoBlockGetRemote() local ServerTick = AutoBlockGetServerTick()
    if not Remote or not ServerTick or not Tool then return false end
    local Code = State and "BLSTAX1" or "BZLZSTI2"
    local Success = Internal.Call(function()
        Remote:InvokeServer("🍞", math.floor(ServerTick.Value - 81919), Tool, Code)
    end)
    return Success == true
end

function AutoBlockStep()
    if not AutoBlockState.Enabled then return end
    local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    local Tool = Character and Character:FindFirstChildOfClass("Tool")
    if not Root or not Tool or not AutoBlockToolCanBlock(Tool) then
        if AutoBlockState.Blocking then AutoBlockSend(false, Tool) end
        AutoBlockState.Blocking = false
        return
    end
    local Threat = false local Range = math.clamp(tonumber(AutoBlockState.Distance) or 15, 1, 15) local CachedPlayers = AutoBlockState.Players

    for Index = 1, #CachedPlayers do
        local Player = CachedPlayers[Index]
        if Player and Player.Parent == Players and Player ~= LocalPlayer and IsCombatTargetAllowed(Player) then
            local EnemyCharacter = Player.Character local EnemyRoot = EnemyCharacter and EnemyCharacter:FindFirstChild("HumanoidRootPart")
            if EnemyRoot and (EnemyRoot.Position - Root.Position).Magnitude <= Range and AutoBlockPlayerAttacking(Player) then
                Threat = true
                break
            end
        end
    end
    local Now = os.clock()
    if Threat then
        AutoBlockState.LastThreat = Now
        if not AutoBlockState.Blocking or Now - AutoBlockState.LastSend >= 0.09 then
            AutoBlockState.Blocking = AutoBlockSend(true, Tool) or AutoBlockState.Blocking
            AutoBlockState.LastSend = Now
        end
    elseif AutoBlockState.Blocking and Now - AutoBlockState.LastThreat > 0.20 then
        AutoBlockSend(false, Tool)
        AutoBlockState.Blocking = false
    end
end

function AutoBlockEnable()
    if AutoBlockState.Enabled then return end

    AutoBlockState.Enabled = true
    table.clear(AutoBlockState.Players)
    AutoBlockState.PlayerSet = setmetatable({}, {__mode = "k"})

    local function AddPlayer(Player)
        if not Player or Player == LocalPlayer or AutoBlockState.PlayerSet[Player] then return end
        AutoBlockState.PlayerSet[Player] = true
        AutoBlockState.Players[#AutoBlockState.Players + 1] = Player
    end

    local function RemovePlayer(Player)
        if not Player or not AutoBlockState.PlayerSet[Player] then return end
        AutoBlockState.PlayerSet[Player] = nil

        for Index = #AutoBlockState.Players, 1, -1 do
            if AutoBlockState.Players[Index] == Player then
                local Last = #AutoBlockState.Players
                AutoBlockState.Players[Index] = AutoBlockState.Players[Last]
                AutoBlockState.Players[Last] = nil
                break
            end
        end
    end

    for _, Player in ipairs(Players:GetPlayers()) do AddPlayer(Player) end

    if AutoBlockState.PlayerAddedConnection then AutoBlockState.PlayerAddedConnection:Disconnect() end
    if AutoBlockState.PlayerRemovingConnection then AutoBlockState.PlayerRemovingConnection:Disconnect() end

    AutoBlockState.PlayerAddedConnection = Players.PlayerAdded:Connect(AddPlayer)
    AutoBlockState.PlayerRemovingConnection = Players.PlayerRemoving:Connect(RemovePlayer)

    if AutoBlockState.Connection then AutoBlockState.Connection:Disconnect() end
    AutoBlockState.ScanClock = 0
    AutoBlockState.Connection = RunService.Heartbeat:Connect(function(DeltaTime)
        AutoBlockState.ScanClock += math.clamp(tonumber(DeltaTime) or 0, 0, 0.05)
        if AutoBlockState.ScanClock < 1 / 60 then return end
        AutoBlockState.ScanClock = AutoBlockState.ScanClock % (1 / 60)
        AutoBlockStep()
    end)
end

function AutoBlockDisable()
    AutoBlockState.Enabled = false
    if AutoBlockState.Connection then AutoBlockState.Connection:Disconnect(); AutoBlockState.Connection = nil end
    local Character = LocalPlayer.Character local Tool = Character and Character:FindFirstChildOfClass("Tool")
    if AutoBlockState.Blocking and Tool then AutoBlockSend(false, Tool) end
    AutoBlockState.Blocking = false
    AutoBlockState.ScanClock = 0
    table.clear(AutoBlockState.BlockCache)
    table.clear(AutoBlockState.Players)
    AutoBlockState.PlayerSet = setmetatable({}, {__mode = "k"})

    if AutoBlockState.PlayerAddedConnection then
        AutoBlockState.PlayerAddedConnection:Disconnect()
        AutoBlockState.PlayerAddedConnection = nil
    end

    if AutoBlockState.PlayerRemovingConnection then
        AutoBlockState.PlayerRemovingConnection:Disconnect()
        AutoBlockState.PlayerRemovingConnection = nil
    end
end

if type(GunMaterialChamsDisable) == "function" and GunMaterialChamsState.Enabled then Internal.Call(GunMaterialChamsDisable) end
GunMaterialChamsState.Enabled = false
GunMaterialChamsState.RootConnections = setmetatable({}, { __mode = "k" })
GunMaterialChamsState.ActiveRoots = setmetatable({}, { __mode = "k" })
GunMaterialChamsState.StyledObjects = setmetatable({}, { __mode = "k" })
GunMaterialChamsState.StyledRoots = setmetatable({}, { __mode = "k" })
GunMaterialChamsState.RootData = setmetatable({}, { __mode = "k" })
GunMaterialChamsState.Originals = setmetatable({}, { __mode = "k" })
GunMaterialChamsState.Connections = {}
GunMaterialChamsState.LastMaintenance = 0
GunMaterialChamsState.MaintenanceInterval = 0.18

function GunMaterialChamsGetRoots()
    local Roots = {}
    local ShaderRoots = GetWeaponShaderRoots()
    for Index = 1, #ShaderRoots do
        local RootData = ShaderRoots[Index]
        if RootData and RootData.Root and RootData.Root.Parent then Roots[#Roots + 1] = { Root = RootData.Root, ViewModel = RootData.ViewModel == true } end
    end
    return Roots
end

function GunMaterialChamsRootsEqual(A, B)
    if type(A) ~= "table" or type(B) ~= "table" or #A ~= #B then return false end
    for Index = 1, #A do
        if not A[Index] or not B[Index] or A[Index].Root ~= B[Index].Root or A[Index].ViewModel ~= B[Index].ViewModel then return false end
    end
    return true
end

function GunMaterialChamsGetPart(Object)
    if not Object then return nil end
    if Object:IsA("BasePart") then return Object end
    return Object:FindFirstAncestorWhichIsA("BasePart")
end

function GunMaterialChamsPartAllowed(Part, RootData)
    if not Part or not Part:IsA("BasePart") or not RootData or not RootData.Root then return false end
    if RootData.ViewModel then return IsViewModelWeaponPart(Part, RootData.Root) == true end
    return Part:IsDescendantOf(RootData.Root)
end

function GunMaterialChamsObjectAllowed(Object, RootData)
    if not Object or not Object.Parent then return false end
    if not (Object:IsA("BasePart") or Object:IsA("SpecialMesh") or Object:IsA("FileMesh") or Object:IsA("SurfaceAppearance")
        or Object:IsA("Texture") or Object:IsA("Decal")) then return false end
    local Part = GunMaterialChamsGetPart(Object)
    return GunMaterialChamsPartAllowed(Part, RootData)
end

function GunMaterialChamsSave(Object)
    if GunMaterialChamsState.Originals[Object] then return GunMaterialChamsState.Originals[Object] end

    local Data = {}
    if Object:IsA("BasePart") then
        Data.Color = Object.Color
        Data.Material = Object.Material
        Data.MaterialVariant = Object.MaterialVariant
        Data.Transparency = Object.Transparency
        Data.LocalTransparencyModifier = Object.LocalTransparencyModifier
        if Object:IsA("UnionOperation") then Data.UsePartColor = Object.UsePartColor end
        if Object:IsA("MeshPart") then Data.Texture = Object.TextureID end
    elseif Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then
        Data.Texture = Object.TextureId
    elseif Object:IsA("SurfaceAppearance") then
        Data.ColorMap = Object.ColorMap
        Data.NormalMap = Object.NormalMap
        Data.MetalnessMap = Object.MetalnessMap
        Data.RoughnessMap = Object.RoughnessMap
    elseif Object:IsA("Texture") or Object:IsA("Decal") then
        Data.Transparency = Object.Transparency
        Data.Color3 = Object.Color3
    end

    GunMaterialChamsState.Originals[Object] = Data
    return Data
end

function GunMaterialChamsRestoreObject(Object, Forget)
    local Data = GunMaterialChamsState.Originals[Object]
    if Data and Object and Object.Parent then
        if Object:IsA("BasePart") then
            Object.Color = Data.Color
            Object.Material = Data.Material
            Object.MaterialVariant = Data.MaterialVariant or ""
            Object.Transparency = Data.Transparency
            Object.LocalTransparencyModifier = Data.LocalTransparencyModifier
            if Object:IsA("UnionOperation") and Data.UsePartColor ~= nil then Object.UsePartColor = Data.UsePartColor end
            if Object:IsA("MeshPart") and Data.Texture ~= nil then Object.TextureID = Data.Texture end
        elseif Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then
            if Data.Texture ~= nil then Object.TextureId = Data.Texture end
        elseif Object:IsA("SurfaceAppearance") then
            Object.ColorMap = Data.ColorMap or ""
            Object.NormalMap = Data.NormalMap or ""
            Object.MetalnessMap = Data.MetalnessMap or ""
            Object.RoughnessMap = Data.RoughnessMap or ""
        elseif Object:IsA("Texture") or Object:IsA("Decal") then
            if Data.Transparency ~= nil then Object.Transparency = Data.Transparency end
            if Data.Color3 then Object.Color3 = Data.Color3 end
        end
    end
    if Forget then GunMaterialChamsState.Originals[Object] = nil end
end

function GunMaterialChamsApplyObject(Object, RootData)
    if not GunMaterialChamsState.Enabled or not GunMaterialChamsObjectAllowed(Object, RootData) then return end

    local Original = GunMaterialChamsSave(Object)
    GunMaterialChamsState.StyledObjects[Object] = true
    GunMaterialChamsState.StyledRoots[Object] = RootData.Root
    GunMaterialChamsState.RootData[Object] = RootData

    if Object:IsA("BasePart") then
        Object.Color = GunMaterialChamsState.Color
        Object.Material = Enum.Material[GunMaterialChamsState.Material] or Enum.Material.Neon
        Object.MaterialVariant = ""
        if Original.Transparency == nil or Original.Transparency < 0.99 then Object.Transparency = GunMaterialChamsState.Transparency end
        if RootData.ViewModel then Object.LocalTransparencyModifier = 0 end
        if Object:IsA("UnionOperation") then Object.UsePartColor = true end
        if Object:IsA("MeshPart") then
            if GunMaterialChamsState.NoTexture then Object.TextureID = ""
            elseif Original.Texture ~= nil then Object.TextureID = Original.Texture end
        end
    elseif Object:IsA("SpecialMesh") or Object:IsA("FileMesh") then
        if GunMaterialChamsState.NoTexture then Object.TextureId = ""
        elseif Original.Texture ~= nil then Object.TextureId = Original.Texture end
    elseif Object:IsA("SurfaceAppearance") then
        if GunMaterialChamsState.NoTexture then
            Object.ColorMap = ""
            Object.NormalMap = ""
            Object.MetalnessMap = ""
            Object.RoughnessMap = ""
        else
            Object.ColorMap = Original.ColorMap or ""
            Object.NormalMap = Original.NormalMap or ""
            Object.MetalnessMap = Original.MetalnessMap or ""
            Object.RoughnessMap = Original.RoughnessMap or ""
        end
    elseif Object:IsA("Texture") or Object:IsA("Decal") then
        if GunMaterialChamsState.NoTexture then Object.Transparency = 1
        elseif Original.Transparency ~= nil then Object.Transparency = Original.Transparency end
    end
end

function GunMaterialChamsDisconnectRoot(Root)
    local Connections = GunMaterialChamsState.RootConnections[Root]
    if type(Connections) == "table" then
        for Index = 1, #Connections do
            local Connection = Connections[Index]
            if Connection then Connection:Disconnect() end
        end
    end
    GunMaterialChamsState.RootConnections[Root] = nil
    GunMaterialChamsState.ActiveRoots[Root] = nil
end

function GunMaterialChamsBindRoot(RootData)
    local Root = RootData and RootData.Root
    if not Root or not Root.Parent then return end

    local Existing = GunMaterialChamsState.ActiveRoots[Root]
    if Existing and Existing.ViewModel == RootData.ViewModel and GunMaterialChamsState.RootConnections[Root] then return end
    if GunMaterialChamsState.RootConnections[Root] then GunMaterialChamsDisconnectRoot(Root) end

    GunMaterialChamsState.ActiveRoots[Root] = RootData
    for _, Object in ipairs(Root:GetDescendants()) do GunMaterialChamsApplyObject(Object, RootData) end

    GunMaterialChamsState.RootConnections[Root] = {
        Root.DescendantAdded:Connect(function(Object)
            if GunMaterialChamsState.Enabled then GunMaterialChamsApplyObject(Object, RootData) end
        end),
        Root.DescendantRemoving:Connect(function(Object)
            if GunMaterialChamsState.StyledObjects[Object] then
                GunMaterialChamsRestoreObject(Object, true)
                GunMaterialChamsState.StyledObjects[Object] = nil
                GunMaterialChamsState.StyledRoots[Object] = nil
                GunMaterialChamsState.RootData[Object] = nil
            end
        end)
    }
end

function GunMaterialChamsRefreshRoots()
    if not GunMaterialChamsState.Enabled then return end

    local Roots = GunMaterialChamsGetRoots()
    local Current = setmetatable({}, { __mode = "k" })
    for Index = 1, #Roots do
        local RootData = Roots[Index]
        Current[RootData.Root] = RootData
        GunMaterialChamsBindRoot(RootData)
    end

    local Stale = {}
    for Root in pairs(GunMaterialChamsState.RootConnections) do
        if not Root.Parent or not Current[Root] then Stale[#Stale + 1] = Root end
    end
    for Index = 1, #Stale do GunMaterialChamsDisconnectRoot(Stale[Index]) end

    GunMaterialChamsState.CurrentRoots = Roots
end

function GunMaterialChamsPruneStyled()
    local Stale = {}
    for Object in pairs(GunMaterialChamsState.StyledObjects) do
        local Root = GunMaterialChamsState.StyledRoots[Object] local RootData = GunMaterialChamsState.RootData[Object]
        if not Object or not Object.Parent or not Root or not Root.Parent or not GunMaterialChamsState.ActiveRoots[Root]
            or not GunMaterialChamsObjectAllowed(Object, RootData) then
            Stale[#Stale + 1] = Object
        end
    end

    for Index = 1, #Stale do
        local Object = Stale[Index]
        GunMaterialChamsRestoreObject(Object, true)
        GunMaterialChamsState.StyledObjects[Object] = nil
        GunMaterialChamsState.StyledRoots[Object] = nil
        GunMaterialChamsState.RootData[Object] = nil
    end
end

function GunMaterialChamsEnforce()
    if not GunMaterialChamsState.Enabled then return end
    for Object in pairs(GunMaterialChamsState.StyledObjects) do
        local Root = GunMaterialChamsState.StyledRoots[Object] local RootData = GunMaterialChamsState.RootData[Object]
        if Root and GunMaterialChamsState.ActiveRoots[Root] and GunMaterialChamsObjectAllowed(Object, RootData) then
            GunMaterialChamsApplyObject(Object, RootData)
        end
    end
end

function GunMaterialChamsApply()
    if not GunMaterialChamsState.Enabled then return end
    GunMaterialChamsRefreshRoots()
    GunMaterialChamsPruneStyled()
    GunMaterialChamsEnforce()
end

function GunMaterialChamsRestore()
    local Objects = {}
    for Object in pairs(GunMaterialChamsState.Originals) do Objects[#Objects + 1] = Object end
    for Index = 1, #Objects do GunMaterialChamsRestoreObject(Objects[Index], true) end
    table.clear(GunMaterialChamsState.StyledObjects)
    table.clear(GunMaterialChamsState.StyledRoots)
    table.clear(GunMaterialChamsState.RootData)
end

function GunMaterialChamsDisconnectObservers()
    for _, Connection in pairs(GunMaterialChamsState.Connections) do
        if Connection then Connection:Disconnect() end
    end
    table.clear(GunMaterialChamsState.Connections)

    local Roots = {}
    for Root in pairs(GunMaterialChamsState.RootConnections) do Roots[#Roots + 1] = Root end
    for Index = 1, #Roots do GunMaterialChamsDisconnectRoot(Roots[Index]) end
end

function GunMaterialChamsBindObservers()
    GunMaterialChamsDisconnectObservers()

    local function Refresh()
        if GunMaterialChamsState.Enabled then task.defer(GunMaterialChamsRefreshRoots) end
    end

    local function Rebind()
        if not GunMaterialChamsState.Enabled then return end
        task.defer(function()
            if not GunMaterialChamsState.Enabled then return end
            GunMaterialChamsBindObservers()
            GunMaterialChamsApply()
        end)
    end

    GunMaterialChamsState.Connections.CharacterAdded = LocalPlayer.CharacterAdded:Connect(Rebind)
    GunMaterialChamsState.Connections.CharacterRemoving = LocalPlayer.CharacterRemoving:Connect(Refresh)
    GunMaterialChamsState.Connections.CameraChanged = workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(Rebind)

    local Character = LocalPlayer.Character
    if Character then
        GunMaterialChamsState.Connections.CharacterAddedObject = Character.ChildAdded:Connect(Refresh)
        GunMaterialChamsState.Connections.CharacterRemovedObject = Character.ChildRemoved:Connect(Refresh)
    end

    local CameraObject = Internal.GetCamera()
    if CameraObject then
        GunMaterialChamsState.Connections.CameraAddedObject = CameraObject.ChildAdded:Connect(Refresh)
        GunMaterialChamsState.Connections.CameraRemovedObject = CameraObject.ChildRemoved:Connect(Refresh)
    end

    GunMaterialChamsState.LastMaintenance = 0
    GunMaterialChamsState.Connections.Maintenance = RunService.Heartbeat:Connect(function()
        if not GunMaterialChamsState.Enabled then return end
        local CurrentTime = os.clock()
        if CurrentTime - GunMaterialChamsState.LastMaintenance < GunMaterialChamsState.MaintenanceInterval then return end

        GunMaterialChamsState.LastMaintenance = CurrentTime
        GunMaterialChamsRefreshRoots()
        GunMaterialChamsPruneStyled()
        GunMaterialChamsEnforce()
    end)
end

function GunMaterialChamsEnable()
    if GunMaterialChamsState.Enabled then return end
    GunMaterialChamsState.Enabled = true
    GunMaterialChamsBindObservers()
    EnsureWeaponPerspectiveFix()
    GunMaterialChamsApply()
end

function GunMaterialChamsDisable()
    GunMaterialChamsState.Enabled = false
    GunMaterialChamsDisconnectObservers()
    GunMaterialChamsRestore()
    EnsureWeaponPerspectiveFix()
end

function GrenadeTrajectoryRemoveDrawing(Object)
    Internal.RemoveDrawing(Object)
end

function GrenadeTrajectoryHide()
    for Index = 1, #GrenadeTrajectoryState.Segments do
        local Line = GrenadeTrajectoryState.Segments[Index]
        if Line then Line.Visible = false end
    end

    for Index = 1, #GrenadeTrajectoryState.BounceMarkers do
        local Marker = GrenadeTrajectoryState.BounceMarkers[Index]
        if Marker then Marker.Visible = false end
    end

    if GrenadeTrajectoryState.ImpactMarker then GrenadeTrajectoryState.ImpactMarker.Visible = false end
end

function GrenadeTrajectoryClear()
    for Index = 1, #GrenadeTrajectoryState.Segments do
        GrenadeTrajectoryRemoveDrawing(GrenadeTrajectoryState.Segments[Index])
        GrenadeTrajectoryState.Segments[Index] = nil
    end

    for Index = 1, #GrenadeTrajectoryState.BounceMarkers do
        GrenadeTrajectoryRemoveDrawing(GrenadeTrajectoryState.BounceMarkers[Index])
        GrenadeTrajectoryState.BounceMarkers[Index] = nil
    end

    GrenadeTrajectoryRemoveDrawing(GrenadeTrajectoryState.ImpactMarker)
    GrenadeTrajectoryState.ImpactMarker = nil
    table.clear(GrenadeTrajectoryState.Points)
    table.clear(GrenadeTrajectoryState.BounceIndices)
end

function GrenadeTrajectoryIsThrowable(Tool)
    if not Tool or not Tool:IsA("Tool") then return false end
    if Tool:FindFirstChild("PinPulled") then return true end

    local Name = string.lower(Tool.Name)
    local Keys = {"grenade", "molotov", "flash", "smoke", "stun", "incendiary", "firework", "pumpkin", "gas"}

    for Index = 1, #Keys do
        if string.find(Name, Keys[Index], 1, true) then return true end
    end

    return false
end

function GrenadeTrajectoryGetTool()
    local Character = LocalPlayer.Character
    if not Character then return nil end

    for _, Object in ipairs(Character:GetChildren()) do
        if GrenadeTrajectoryIsThrowable(Object) then return Object end
    end

    return nil
end

function GrenadeTrajectoryGetHandle(Tool)
    if not Tool then return nil end

    local Handle = Tool:FindFirstChild("Handle") or Tool:FindFirstChild("RightGrip") or Tool:FindFirstChildWhichIsA("BasePart")
    return Handle and Handle:IsA("BasePart") and Handle or nil
end

function GrenadeTrajectoryGetCollisionPart(Tool, Handle)
    Handle = Handle or GrenadeTrajectoryGetHandle(Tool)
    if not Handle then return nil end

    local Hitbox = Handle:FindFirstChild("HB")
        or Tool and Tool:FindFirstChild("HB", true)
        or Handle:FindFirstChild("Hitbox")
        or Tool and Tool:FindFirstChild("Hitbox", true)

    return Hitbox and Hitbox:IsA("BasePart") and Hitbox or Handle
end

function GrenadeTrajectoryGetAimPoint(
    CameraObject,
    Character,
    Tool
)
    CameraObject =
        CameraObject
        or workspace.CurrentCamera

    if not CameraObject then
        return nil
    end

    local Ray

    if UserInputService.MouseBehavior
        == Enum.MouseBehavior.LockCenter
    then
        local Viewport =
            CameraObject.ViewportSize

        Ray =
            CameraObject:
                ViewportPointToRay(
                    Viewport.X * 0.5,
                    Viewport.Y * 0.5
                )
    else
        local MousePosition =
            UserInputService:
                GetMouseLocation()

        Ray =
            CameraObject:
                ScreenPointToRay(
                    MousePosition.X,
                    MousePosition.Y
                )
    end

    if not Ray then
        return nil
    end

    local Parameters =
        RaycastParams.new()

    Parameters.FilterType =
        Enum.RaycastFilterType.Exclude

    Parameters.IgnoreWater = false
    Parameters.RespectCanCollide = false

    local Ignore = {}

    if Character then
        Ignore[#Ignore + 1] =
            Character
    end

    if Tool then
        Ignore[#Ignore + 1] =
            Tool
    end

    Ignore[#Ignore + 1] =
        CameraObject

    Parameters.FilterDescendantsInstances =
        Ignore

    local CastDistance = 1600

    local Result =
        workspace:Raycast(
            Ray.Origin,
            Ray.Direction
                * CastDistance,
            Parameters
        )

    if Result
        and Result.Position
    then
        return Result.Position
    end

    return
        Ray.Origin
        + Ray.Direction
            * CastDistance
end

function GrenadeTrajectoryGetLaunchPoint(
    Tool,
    Handle
)
    if not Tool
        or not Handle
    then
        return nil
    end

    local Cached =
        GrenadeTrajectoryState.LaunchPointCache[
            Tool
        ]

    if Cached
        and Cached.Parent
    then
        if Cached:IsA("Attachment") then
            return
                Cached.WorldPosition
        end

        if Cached:IsA("BasePart") then
            return
                Cached.Position
        end
    end

    local Wanted = {
        throwpoint = true,
        throworigin = true,
        projectilespawn = true,
        spawnpoint = true,
        firepoint = true,
        muzzle = true
    }

    for _, Object in ipairs(
        Tool:GetDescendants()
    ) do
        local Name =
            string.lower(
                Object.Name
            )

        if Wanted[Name]
            and (
                Object:IsA("Attachment")
                or Object:IsA("BasePart")
            )
        then
            GrenadeTrajectoryState.LaunchPointCache[
                Tool
            ] = Object

            if Object:IsA("Attachment") then
                return
                    Object.WorldPosition
            end

            return Object.Position
        end
    end

    local Observed =
        GrenadeTrajectoryState.ObservedProfiles[
            string.lower(
                Tool.Name
            )
        ]

    if type(Observed) == "table"
        and typeof(
            Observed.OriginLocal
        ) == "Vector3"
        and Observed.OriginLocal.Magnitude
            <= 6
    then
        return
            Handle.CFrame:
                PointToWorldSpace(
                    Observed.OriginLocal
                )
    end

    return Handle.Position
end

function GrenadeTrajectoryGetPhysics(Part)
    if not Part or not Part:IsA("BasePart") then return nil end

    local Success, Properties = pcall(function() return Part.CurrentPhysicalProperties end)
    if Success and Properties then return Properties end

    return Part.CustomPhysicalProperties
end

function GrenadeTrajectoryGetProfile(Tool)
    local Profile = {
        ThrowSpeed = GrenadeTrajectoryState.ThrowSpeed,
        PredictionTime = GrenadeTrajectoryState.PredictionTime,
        GravityScale = GrenadeTrajectoryState.GravityScale,
        Friction = nil,
        FrictionWeight = nil,
        Elasticity = nil,
        ElasticityWeight = nil
    }

    if not Tool then return Profile end

    local Config = Tool:FindFirstChild("Config")

    if Config and Config:IsA("ModuleScript") then
        local Success, Settings = Internal.Call(require, Config)

        if Success and type(Settings) == "table" then
            local Velocity = tonumber(
                Settings.VELOCITY or Settings.Velocity or Settings.ThrowVelocity
                or Settings.ThrowSpeed or Settings.ProjectileSpeed
            )

            local ExplodeTime = tonumber(
                Settings.ExplodeTime or Settings.FuseTime or Settings.Fuse or Settings.Timer
            )

            local GravityScale = tonumber(
                Settings.GravityScale or Settings.ProjectileGravityScale
            )

            local Gravity = tonumber(Settings.Gravity or Settings.ProjectileGravity)
            local Friction = tonumber(Settings.Friction or Settings.ProjectileFriction)
            local Elasticity = tonumber(Settings.Elasticity or Settings.Restitution or Settings.Bounce)

            if Velocity and Velocity > 0 then Profile.ThrowSpeed = math.clamp(Velocity, 20, 450) end
            if ExplodeTime and ExplodeTime > 0 then Profile.PredictionTime = math.clamp(ExplodeTime, 0.05, 8) end

            if GravityScale and GravityScale > 0 then
                Profile.GravityScale = math.clamp(GravityScale, 0.05, 2)
            elseif Gravity and Gravity > 0 then
                Profile.GravityScale = math.clamp(Gravity <= 5 and Gravity or Gravity / math.max(workspace.Gravity, 0.001), 0.05, 2)
            end

            if Friction then Profile.Friction = math.clamp(Friction, 0, 2) end
            if Elasticity then Profile.Elasticity = math.clamp(Elasticity, 0, 1) end
        end
    end

    local Values = Tool:FindFirstChild("Values")

    if Values then
        for _, Name in next, {"Velocity", "ThrowSpeed", "Speed", "ProjectileSpeed"} do
            local Object = Values:FindFirstChild(Name)

            if Object and (Object:IsA("NumberValue") or Object:IsA("IntValue")) and Object.Value > 0 then
                Profile.ThrowSpeed = math.clamp(Object.Value, 20, 450)
                break
            end
        end

        for _, Name in next, {"Fuse", "FuseTime", "ExplodeTime", "Timer"} do
            local Object = Values:FindFirstChild(Name)

            if Object and (Object:IsA("NumberValue") or Object:IsA("IntValue")) and Object.Value > 0 then
                Profile.PredictionTime = math.clamp(Object.Value, 0.05, 8)
                break
            end
        end
    end

    local Pin = Tool:FindFirstChild("PinPulled")
    local Timer = Pin and Pin:FindFirstChild("Timer")

    if Timer and (Timer:IsA("NumberValue") or Timer:IsA("IntValue")) and Timer.Value > 0 then
        Profile.PredictionTime = math.clamp(Timer.Value, 0.05, 8)
    end

    local CollisionPart = GrenadeTrajectoryGetCollisionPart(Tool)
    local Properties = GrenadeTrajectoryGetPhysics(CollisionPart)

    if Properties then
        Profile.Friction = Profile.Friction or Properties.Friction
        Profile.FrictionWeight = Properties.FrictionWeight
        Profile.Elasticity = Profile.Elasticity or Properties.Elasticity
        Profile.ElasticityWeight = Properties.ElasticityWeight
    end

    local Observed = GrenadeTrajectoryState.ObservedProfiles[string.lower(Tool.Name)]

    if type(Observed) == "table"
        and os.clock() - (tonumber(Observed.Time) or 0) <= 180
        and tonumber(Observed.Speed)
    then
        Profile.ThrowSpeed = math.clamp(tonumber(Observed.Speed), 20, 450)
    end

    return Profile
end
function GrenadeTrajectoryGetLine(Index)
    local Line = GrenadeTrajectoryState.Segments[Index]

    if not Line and type(Drawing) == "table" and type(Drawing.new) == "function" then
        Line = Drawing.new("Line")
        Line.Visible = false
        Line.ZIndex = 2
        GrenadeTrajectoryState.Segments[Index] = Line
    end

    return Line
end

function GrenadeTrajectoryGetBounceMarker(Index)
    local Marker = GrenadeTrajectoryState.BounceMarkers[Index]

    if not Marker and type(Drawing) == "table" and type(Drawing.new) == "function" then
        Marker = Drawing.new("Circle")
        Marker.Filled = false
        Marker.NumSides = 18
        Marker.Radius = 3.5
        Marker.ZIndex = 3
        Marker.Visible = false
        GrenadeTrajectoryState.BounceMarkers[Index] = Marker
    end

    return Marker
end

function GrenadeTrajectoryGetImpactMarker()
    local Marker = GrenadeTrajectoryState.ImpactMarker

    if not Marker and type(Drawing) == "table" and type(Drawing.new) == "function" then
        Marker = Drawing.new("Circle")
        Marker.Filled = false
        Marker.NumSides = 24
        Marker.Radius = 7
        Marker.ZIndex = 3
        Marker.Visible = false
        GrenadeTrajectoryState.ImpactMarker = Marker
    end

    return Marker
end

function GrenadeTrajectoryPointVisible(CameraObject, Point, Ignore)
    if GrenadeTrajectoryState.Occlusion ~= true then return true end
    if not CameraObject or typeof(Point) ~= "Vector3" then return false end

    local Origin = CameraObject.CFrame.Position local Direction = Point - Origin local Distance = Direction.Magnitude
    if Distance <= 0.01 then return true end

    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.IgnoreWater = true
    Parameters.RespectCanCollide = true
    Parameters.FilterDescendantsInstances = type(Ignore) == "table" and Ignore or {}

    local Result = workspace:Raycast(Origin, Direction, Parameters)
    if not Result then return true end
    return (Result.Position - Origin).Magnitude + 0.15 >= Distance
end

function GrenadeTrajectoryProjectSegment(CameraObject, FirstPoint, SecondPoint)
    if not CameraObject or typeof(FirstPoint) ~= "Vector3" or typeof(SecondPoint) ~= "Vector3" then return nil end

    local First = CameraObject:WorldToViewportPoint(FirstPoint)
    local Second = CameraObject:WorldToViewportPoint(SecondPoint)
    local Near = 0.05

    if First.Z <= Near and Second.Z <= Near then return nil end

    if First.Z <= Near then
        local Denominator = Second.Z - First.Z
        if math.abs(Denominator) <= 0.0001 then return nil end

        local Alpha = math.clamp((Near - First.Z) / Denominator, 0, 1)
        FirstPoint = FirstPoint:Lerp(SecondPoint, Alpha)
        First = CameraObject:WorldToViewportPoint(FirstPoint)
    elseif Second.Z <= Near then
        local Denominator = First.Z - Second.Z
        if math.abs(Denominator) <= 0.0001 then return nil end

        local Alpha = math.clamp((Near - Second.Z) / Denominator, 0, 1)
        SecondPoint = SecondPoint:Lerp(FirstPoint, Alpha)
        Second = CameraObject:WorldToViewportPoint(SecondPoint)
    end

    return First, Second, FirstPoint, SecondPoint
end

function GrenadeTrajectoryDraw(Points, BounceIndices, Active)
    local CameraObject = workspace.CurrentCamera

    if not CameraObject or type(Drawing) ~= "table" or type(Drawing.new) ~= "function" then
        GrenadeTrajectoryHide()
        return
    end

    local Needed = math.max(#Points - 1, 0)
    local Color = Active == true and GrenadeTrajectoryState.ActiveColor or GrenadeTrajectoryState.Color
    local Thickness = math.clamp(tonumber(GrenadeTrajectoryState.Thickness) or 2, 1, 5)
    local Transparency = math.clamp(tonumber(GrenadeTrajectoryState.Transparency) or 0.92, 0.1, 1)
    local Ignore = {}
    local Character = LocalPlayer.Character

    if Character then Ignore[#Ignore + 1] = Character end
    if GrenadeTrajectoryState.ActiveProjectile then Ignore[#Ignore + 1] = GrenadeTrajectoryState.ActiveProjectile end

    for Index = 1, Needed do
        local Line = GrenadeTrajectoryGetLine(Index)
        local ProjectedFirst, ProjectedSecond, WorldFirst, WorldSecond = GrenadeTrajectoryProjectSegment(
            CameraObject,
            Points[Index],
            Points[Index + 1]
        )

        local WorldVisible = false

        if ProjectedFirst and ProjectedSecond then
            local Midpoint = WorldFirst:Lerp(WorldSecond, 0.5)
            WorldVisible = GrenadeTrajectoryPointVisible(CameraObject, Midpoint, Ignore)
        end

        if Line and ProjectedFirst and ProjectedSecond and WorldVisible then
            Line.From = Vector2.new(ProjectedFirst.X, ProjectedFirst.Y)
            Line.To = Vector2.new(ProjectedSecond.X, ProjectedSecond.Y)
            Line.Color = Color
            Line.Thickness = Thickness
            Line.Transparency = Transparency
            Line.Visible = true
        elseif Line then
            Line.Visible = false
        end
    end

    for Index = Needed + 1, #GrenadeTrajectoryState.Segments do
        local Line = GrenadeTrajectoryState.Segments[Index]
        if Line then Line.Visible = false end
    end

    local BounceCount = 0

    if GrenadeTrajectoryState.ShowBounces and type(BounceIndices) == "table" then
        for Index = 1, #BounceIndices do
            local Point = Points[BounceIndices[Index]]

            if Point then
                BounceCount += 1

                local Marker = GrenadeTrajectoryGetBounceMarker(BounceCount)
                local Screen = CameraObject:WorldToViewportPoint(Point)
                local WorldVisible = GrenadeTrajectoryPointVisible(CameraObject, Point, Ignore)

                if Marker and Screen.Z > 0.05 and WorldVisible then
                    Marker.Position = Vector2.new(Screen.X, Screen.Y)
                    Marker.Color = Color
                    Marker.Thickness = math.max(Thickness - 0.5, 1)
                    Marker.Transparency = Transparency
                    Marker.Visible = true
                elseif Marker then
                    Marker.Visible = false
                end
            end
        end
    end

    for Index = BounceCount + 1, #GrenadeTrajectoryState.BounceMarkers do
        local Marker = GrenadeTrajectoryState.BounceMarkers[Index]
        if Marker then Marker.Visible = false end
    end

    local Impact = GrenadeTrajectoryGetImpactMarker()
    local FinalPoint = Points[#Points]

    if GrenadeTrajectoryState.ShowImpact and Impact and FinalPoint then
        local Screen = CameraObject:WorldToViewportPoint(FinalPoint)
        local WorldVisible = GrenadeTrajectoryPointVisible(CameraObject, FinalPoint, Ignore)

        if Screen.Z > 0.05 and WorldVisible then
            Impact.Position = Vector2.new(Screen.X, Screen.Y)
            Impact.Color = Color
            Impact.Thickness = Thickness
            Impact.Transparency = Transparency
            Impact.Radius = Active == true and 8 or 7
            Impact.Visible = true
        else
            Impact.Visible = false
        end
    elseif Impact then
        Impact.Visible = false
    end
end
function GrenadeTrajectoryGetProjectilePart(Object)
    if not Object then return nil end
    if Object:IsA("BasePart") then return Object end

    local Part = Object:FindFirstChild("Handle", true) or Object:FindFirstChild("Hitbox", true) or Object:FindFirstChildWhichIsA("BasePart", true)

    return Part and Part:IsA("BasePart") and Part or nil
end

function GrenadeTrajectoryClearActive()
    GrenadeTrajectoryState.ActiveProjectile =
        nil
    GrenadeTrajectoryState.ActivePart =
        nil
    GrenadeTrajectoryState.ActiveProfile =
        nil
    GrenadeTrajectoryState.ActiveStarted =
        0
    GrenadeTrajectoryState.ActiveLastVelocity =
        nil
    GrenadeTrajectoryState.ActiveLastSample =
        0
end

function GrenadeTrajectoryTryTrackProjectile(Object)
    if not GrenadeTrajectoryState.Enabled
        or GrenadeTrajectoryState.ShowLive ~= true
        or not Object
        or not Object.Parent
    then
        return false
    end

    local CurrentTime =
        os.clock()

    if CurrentTime
        - (
            tonumber(
                GrenadeTrajectoryState.LastHeldAt
            ) or 0
        )
        > 1.15
    then
        return false
    end

    local Part =
        GrenadeTrajectoryGetProjectilePart(
            Object
        )

    if not Part
        or not Part.Parent
    then
        return false
    end

    local Character =
        LocalPlayer.Character

    if Character
        and Object:IsDescendantOf(
            Character
        )
    then
        return false
    end

    for _, Name in next, {
        "Creator",
        "Owner",
        "Player"
    } do
        local Owner =
            Object:FindFirstChild(
                Name,
                true
            )

        if Owner
            and Owner:IsA(
                "ObjectValue"
            )
            and Owner.Value
            and Owner.Value
                ~= LocalPlayer
        then
            return false
        end
    end

    local Root =
        Character
        and Character:FindFirstChild(
            "HumanoidRootPart"
        )

    local Reference =
        GrenadeTrajectoryState.LastHeldHandlePosition
        or Root
            and Root.Position

    if typeof(Reference) ~= "Vector3"
        or (
            Part.Position
            - Reference
        ).Magnitude > 55
    then
        return false
    end

    local LaunchVelocity =
        Part.AssemblyLinearVelocity

    local Speed =
        LaunchVelocity.Magnitude

    if Speed < 4 then
        return false
    end

    local AimDirection =
        GrenadeTrajectoryState.LastHeldAimDirection

    local RootVelocity =
        GrenadeTrajectoryState.LastHeldRootVelocity

    local LearnedSpeed

    if typeof(AimDirection)
            == "Vector3"
        and AimDirection.Magnitude
            > 0.001
        and typeof(RootVelocity)
            == "Vector3"
    then
        local Relative =
            LaunchVelocity
            - RootVelocity

        local Along =
            Relative:Dot(
                AimDirection.Unit
            )

        if Along > 20
            and Along <= 450
            and Relative.Magnitude > 0.001
            and Relative.Unit:Dot(
                AimDirection.Unit
            ) >= 0.55
        then
            LearnedSpeed =
                Along
        end
    end

    LearnedSpeed =
        LearnedSpeed
        or math.clamp(
            Speed,
            20,
            450
        )

    local Key =
        string.lower(
            tostring(
                GrenadeTrajectoryState.LastHeldToolName
                or Object.Name
            )
        )

    local Previous =
        GrenadeTrajectoryState.ObservedProfiles[
            Key
        ]

    local PreviousSpeed =
        type(Previous) == "table"
        and tonumber(
            Previous.Speed
        )
        or nil

    local Profile =
        GrenadeTrajectoryState.LastHeldProfile

    local GravityScale =
        type(Profile) == "table"
        and math.clamp(
            tonumber(
                Profile.GravityScale
            ) or GrenadeTrajectoryState.GravityScale,
            0.05,
            2
        )
        or GrenadeTrajectoryState.GravityScale

    local OriginLocal =
        type(Previous) == "table"
        and typeof(
            Previous.OriginLocal
        ) == "Vector3"
        and Previous.OriginLocal
        or nil

    local HandleCFrame =
        GrenadeTrajectoryState.LastHeldHandleCFrame

    if typeof(HandleCFrame) == "CFrame" then
        local Age =
            math.clamp(
                CurrentTime
                - (
                    tonumber(
                        GrenadeTrajectoryState.LastHeldAt
                    ) or CurrentTime
                ),
                0,
                0.16
            )

        local Gravity =
            Vector3.new(
                0,
                -workspace.Gravity
                    * GravityScale,
                0
            )

        local EstimatedOrigin =
            Part.Position
            - LaunchVelocity * Age
            + Gravity
                * (
                    0.5
                    * Age
                    * Age
                )

        local LocalOffset =
            HandleCFrame:
                PointToObjectSpace(
                    EstimatedOrigin
                )

        if LocalOffset.Magnitude <= 6 then
            OriginLocal =
                OriginLocal
                and OriginLocal:Lerp(
                    LocalOffset,
                    0.32
                )
                or LocalOffset
        end
    end

    GrenadeTrajectoryState.ObservedProfiles[
        Key
    ] = {
        Speed =
            PreviousSpeed
            and PreviousSpeed
                + (
                    LearnedSpeed
                    - PreviousSpeed
                ) * 0.35
            or LearnedSpeed,
        GravityScale =
            type(Previous) == "table"
            and tonumber(
                Previous.GravityScale
            )
            or GravityScale,
        OriginLocal =
            OriginLocal,
        Time =
            CurrentTime
    }

    GrenadeTrajectoryState.ActiveProjectile =
        Object

    GrenadeTrajectoryState.ActivePart =
        Part

    GrenadeTrajectoryState.ActiveProfile =
        type(Profile) == "table"
        and {
            ThrowSpeed =
                tonumber(
                    Profile.ThrowSpeed
                )
                or GrenadeTrajectoryState.ThrowSpeed,
            PredictionTime =
                tonumber(
                    Profile.PredictionTime
                )
                or GrenadeTrajectoryState.PredictionTime,
            GravityScale =
                GravityScale,
            Friction =
                Profile.Friction,
            FrictionWeight =
                Profile.FrictionWeight,
            Elasticity =
                Profile.Elasticity,
            ElasticityWeight =
                Profile.ElasticityWeight
        }
        or {
            ThrowSpeed =
                GrenadeTrajectoryState.ThrowSpeed,
            PredictionTime =
                GrenadeTrajectoryState.PredictionTime,
            GravityScale =
                GravityScale
        }

    GrenadeTrajectoryState.ActiveStarted =
        CurrentTime

    GrenadeTrajectoryState.ActiveLastVelocity =
        LaunchVelocity

    GrenadeTrajectoryState.ActiveLastSample =
        CurrentTime

    return true
end

function GrenadeTrajectoryGetContainers()
    local Result = {}
    local Seen = setmetatable({}, {__mode = "k"})

    local function Add(Object)
        if not Object or Seen[Object] then return end
        Seen[Object] = true
        Result[#Result + 1] = Object
    end

    local Debris = workspace:FindFirstChild("Debbris") or workspace:FindFirstChild("Debris")
    Add(Debris)
    if Debris then
        Add(Debris:FindFirstChild("VParts"))
        Add(Debris:FindFirstChild("Projectiles"))
        Add(Debris:FindFirstChild("Effects"))
    end

    Add(workspace:FindFirstChild("VParts"))
    Add(workspace:FindFirstChild("Projectiles"))
    return Result
end

function GrenadeTrajectoryBindDebrisFolder()
    local Containers = GrenadeTrajectoryGetContainers()
    local ActiveSet = setmetatable({}, {__mode = "k"})
    GrenadeTrajectoryState.Containers = Containers
    GrenadeTrajectoryState.DebrisFolder = Containers[1]

    for Index = 1, #Containers do
        local Container = Containers[Index]
        ActiveSet[Container] = true

        if not GrenadeTrajectoryState.ContainerConnections[Container] then
            GrenadeTrajectoryState.ContainerConnections[Container] = Container.ChildAdded:Connect(function(Object)
                if GrenadeTrajectoryState.Enabled ~= true or GrenadeTrajectoryState.ShowLive ~= true then return end

                task.defer(function()
                    if GrenadeTrajectoryTryTrackProjectile(Object) then return end
                    task.wait(0.025)
                    if GrenadeTrajectoryTryTrackProjectile(Object) then return end
                    task.wait(0.05)
                    GrenadeTrajectoryTryTrackProjectile(Object)
                end)
            end)
        end
    end

    for Container, Connection in pairs(GrenadeTrajectoryState.ContainerConnections) do
        if not ActiveSet[Container] or not Container.Parent then
            if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
            GrenadeTrajectoryState.ContainerConnections[Container] = nil
        end
    end
end

function GrenadeTrajectoryGetActiveProjectile()
    local Object =
        GrenadeTrajectoryState.ActiveProjectile

    local Part =
        GrenadeTrajectoryState.ActivePart

    if GrenadeTrajectoryState.ShowLive
            ~= true
        or not Object
        or not Object.Parent
        or not Part
        or not Part.Parent
    then
        GrenadeTrajectoryClearActive()
        return nil, nil, nil
    end

    local CurrentTime =
        os.clock()

    local Age =
        CurrentTime
        - (
            tonumber(
                GrenadeTrajectoryState.ActiveStarted
            ) or 0
        )

    if Age > 9 then
        GrenadeTrajectoryClearActive()
        return nil, nil, nil
    end

    local Stored =
        GrenadeTrajectoryState.ActiveProfile

    local Profile

    if type(Stored) == "table" then
        Profile = {
            ThrowSpeed =
                Stored.ThrowSpeed,
            GravityScale =
                Stored.GravityScale,
            PredictionTime =
                math.max(
                    (
                        tonumber(
                            Stored.PredictionTime
                        )
                        or GrenadeTrajectoryState.PredictionTime
                    )
                    - Age,
                    0.08
                ),
            Friction =
                Stored.Friction,
            FrictionWeight =
                Stored.FrictionWeight,
            Elasticity =
                Stored.Elasticity,
            ElasticityWeight =
                Stored.ElasticityWeight
        }
    end

    local CurrentVelocity =
        Part.AssemblyLinearVelocity

    local LastVelocity =
        GrenadeTrajectoryState.ActiveLastVelocity

    local LastSample =
        tonumber(
            GrenadeTrajectoryState.ActiveLastSample
        ) or 0

    local DeltaTime =
        CurrentTime - LastSample

    if typeof(LastVelocity)
            == "Vector3"
        and DeltaTime >= 0.012
        and DeltaTime <= 0.12
        and CurrentVelocity.Magnitude > 2
    then
        local DeltaVelocity =
            CurrentVelocity
            - LastVelocity

        local HorizontalChange =
            Vector3.new(
                DeltaVelocity.X,
                0,
                DeltaVelocity.Z
            ).Magnitude
            / DeltaTime

        local GravityEstimate =
            -DeltaVelocity.Y
            / DeltaTime
            / math.max(
                workspace.Gravity,
                0.001
            )

        if HorizontalChange < 45
            and GravityEstimate >= 0.08
            and GravityEstimate <= 2
        then
            local Key =
                string.lower(
                    tostring(
                        GrenadeTrajectoryState.LastHeldToolName
                        or Object.Name
                    )
                )

            local Observed =
                GrenadeTrajectoryState.ObservedProfiles[
                    Key
                ]

            if type(Observed) == "table" then
                local OldGravity =
                    tonumber(
                        Observed.GravityScale
                    )
                    or GravityEstimate

                Observed.GravityScale =
                    OldGravity
                    + (
                        GravityEstimate
                        - OldGravity
                    ) * 0.16

                Observed.Time =
                    CurrentTime

                if Profile then
                    Profile.GravityScale =
                        Observed.GravityScale
                end
            end
        end
    end

    GrenadeTrajectoryState.ActiveLastVelocity =
        CurrentVelocity

    GrenadeTrajectoryState.ActiveLastSample =
        CurrentTime

    return Object,
        Part,
        Profile
end

function GrenadeTrajectoryBuildCastParams(Ignore)
    local Parameters = RaycastParams.new()
    Parameters.FilterType = Enum.RaycastFilterType.Exclude
    Parameters.IgnoreWater = false
    Parameters.RespectCanCollide = true

    local Filter = {}

    if type(Ignore) == "table" then
        for Index = 1, #Ignore do
            local Object = Ignore[Index]
            if Object then Filter[#Filter + 1] = Object end
        end
    end

    local Characters = workspace:FindFirstChild("Characters")
    if Characters then Filter[#Filter + 1] = Characters end

    Parameters.FilterDescendantsInstances = Filter

    local CollisionGroup = rawget(_G, "CG_NCC")
    if type(CollisionGroup) == "string" and CollisionGroup ~= "" then
        pcall(function() Parameters.CollisionGroup = CollisionGroup end)
    end

    return Parameters
end

function GrenadeTrajectoryCast(Position, Radius, Travel, Parameters)
    if typeof(Position) ~= "Vector3" or typeof(Travel) ~= "Vector3" or Travel.Magnitude <= 0.0001 then return nil end

    if type(workspace.Spherecast) == "function" then
        return workspace:Spherecast(Position, Radius, Travel, Parameters)
    end

    return workspace:Raycast(Position, Travel, Parameters)
end

function GrenadeTrajectoryPushPoint(Points, Position, Force)
    if typeof(Position) ~= "Vector3" then return #Points end

    local Last = Points[#Points]

    if not Last then
        Points[1] = Position
        return 1
    end

    local Distance = (Last - Position).Magnitude

    if Distance <= 0.01 then
        Points[#Points] = Position
        return #Points
    end

    if Force or Distance >= 0.04 then
        Points[#Points + 1] = Position
    else
        Points[#Points] = Position
    end

    return #Points
end

function GrenadeTrajectoryCombinedPhysics(Profile, HitInstance)
    local Surface = HitInstance and HitInstance:IsA("BasePart") and GrenadeTrajectoryGetPhysics(HitInstance) or nil

    local FrictionA = math.clamp(tonumber(Profile.Friction) or 0.6, 0, 2)
    local FrictionB = Surface and math.clamp(tonumber(Surface.Friction) or 0.6, 0, 2) or FrictionA
    local FrictionWeightA = math.max(tonumber(Profile.FrictionWeight) or 1, 0.001)
    local FrictionWeightB = Surface and math.max(tonumber(Surface.FrictionWeight) or 1, 0.001) or FrictionWeightA

    local ElasticityA = math.clamp(tonumber(Profile.Elasticity) or 0, 0, 1)
    local ElasticityB = Surface and math.clamp(tonumber(Surface.Elasticity) or 0, 0, 1) or ElasticityA
    local ElasticityWeightA = math.max(tonumber(Profile.ElasticityWeight) or 1, 0.001)
    local ElasticityWeightB = Surface and math.max(tonumber(Surface.ElasticityWeight) or 1, 0.001) or ElasticityWeightA

    local Friction = (FrictionA * FrictionWeightA + FrictionB * FrictionWeightB) / (FrictionWeightA + FrictionWeightB)
    local Elasticity = (ElasticityA * ElasticityWeightA + ElasticityB * ElasticityWeightB) / (ElasticityWeightA + ElasticityWeightB)

    return Friction, Elasticity
end

function GrenadeTrajectoryBounceVelocity(Velocity, Normal, Profile, HitInstance)
    if typeof(Velocity) ~= "Vector3" or typeof(Normal) ~= "Vector3" or Normal.Magnitude <= 0.001 then return Velocity end

    Normal = Normal.Unit

    local NormalSpeed = Velocity:Dot(Normal)
    if NormalSpeed >= 0 then return Velocity end

    local NormalVelocity = Normal * NormalSpeed
    local TangentVelocity = Velocity - NormalVelocity
    local Friction, Elasticity = GrenadeTrajectoryCombinedPhysics(Profile, HitInstance)
    local UpDot = math.abs(Normal:Dot(Vector3.yAxis))

    local TangentRetention = math.clamp(1 - Friction * 0.12, 0.48, 0.96)
    local Restitution = math.clamp(0.035 + Elasticity * 0.82, 0.025, 0.38)

    if UpDot > 0.75 then
        TangentRetention *= 0.92
        Restitution *= 0.72
    elseif UpDot < 0.30 then
        TangentRetention *= 0.82
        Restitution *= 0.62
    else
        TangentRetention *= 0.88
        Restitution *= 0.82
    end

    if Velocity.Magnitude <= 22 then Restitution *= 0.38 end

    return TangentVelocity * TangentRetention - NormalVelocity * Restitution
end

function GrenadeTrajectorySimulate(Start, Velocity, Profile, Radius, Ignore)
    local Points = GrenadeTrajectoryState.Points
    local BounceIndices = GrenadeTrajectoryState.BounceIndices

    table.clear(Points)
    table.clear(BounceIndices)

    if typeof(Start) ~= "Vector3" or typeof(Velocity) ~= "Vector3" then return Points, BounceIndices, false end

    Profile = type(Profile) == "table" and Profile or {}
    Radius = math.clamp(tonumber(Radius) or 0.35, 0.12, 1.8)

    local GravityScale = math.clamp(tonumber(Profile.GravityScale) or GrenadeTrajectoryState.GravityScale, 0.05, 2)
    local Gravity = Vector3.new(0, -workspace.Gravity * GravityScale, 0)
    local Parameters = GrenadeTrajectoryBuildCastParams(Ignore)

    local PredictionTime = math.min(
        math.clamp(tonumber(GrenadeTrajectoryState.PredictionTime) or 6, 0.05, 8),
        math.clamp(tonumber(Profile.PredictionTime) or GrenadeTrajectoryState.PredictionTime, 0.05, 8)
    )

    local Position = Start
    local CurrentTime = 0
    local LastRenderTime = 0
    local Bounces = 0
    local Steps = 0
    local Stop = false

    GrenadeTrajectoryPushPoint(Points, Position, true)

    while CurrentTime < PredictionTime
        and Steps < GrenadeTrajectoryState.MaxSimulationSteps
        and not Stop
    do
        Steps += 1

        local Speed = math.max(Velocity.Magnitude, 0.001)
        local DeltaTime = math.min(
            GrenadeTrajectoryState.Step,
            GrenadeTrajectoryState.MaxCastDistance / Speed,
            PredictionTime - CurrentTime
        )

        DeltaTime = math.clamp(DeltaTime, 1 / 360, GrenadeTrajectoryState.Step)

        local Remaining = DeltaTime
        local CollisionPasses = 0

        while Remaining > 0.0001 and not Stop do
            local Travel = Velocity * Remaining + Gravity * (0.5 * Remaining * Remaining)
            local TravelDistance = Travel.Magnitude

            if TravelDistance <= 0.0001 then
                Velocity += Gravity * Remaining
                CurrentTime += Remaining
                Remaining = 0
                break
            end

            local Result = GrenadeTrajectoryCast(Position, Radius, Travel, Parameters)

            if Result and Result.Instance and (Result.Instance == workspace.Terrain or Result.Instance.CanCollide) then
                CollisionPasses += 1

                local ResultDistance = tonumber(Result.Distance)
                    or (Result.Position - Position).Magnitude

                local Alpha = math.clamp(ResultDistance / TravelDistance, 0, 1)
                local HitTime = math.clamp(Remaining * Alpha, math.min(Remaining, 1 / 1200), Remaining)
                local Incoming = Velocity + Gravity * HitTime
                local Normal = Result.Normal.Magnitude > 0.001 and Result.Normal.Unit or Vector3.yAxis
                local HitPosition = Result.Position + Normal * Radius

                CurrentTime += HitTime
                Remaining = math.max(Remaining - HitTime, 0)
                Position = HitPosition + Normal * math.max(0.012, Radius * 0.018)
                Velocity = GrenadeTrajectoryBounceVelocity(Incoming, Normal, Profile, Result.Instance)

                GrenadeTrajectoryPushPoint(Points, HitPosition, true)
                BounceIndices[#BounceIndices + 1] = #Points
                LastRenderTime = CurrentTime

                Bounces += 1

                if Bounces >= GrenadeTrajectoryState.MaxBounces
                    or Velocity.Magnitude <= 1.25
                    or CollisionPasses >= GrenadeTrajectoryState.MaxCollisionPasses
                then
                    Stop = true
                end
            else
                Position += Travel
                Velocity += Gravity * Remaining
                CurrentTime += Remaining
                Remaining = 0

                if CurrentTime - LastRenderTime >= GrenadeTrajectoryState.RenderStep then
                    GrenadeTrajectoryPushPoint(Points, Position, true)
                    LastRenderTime = CurrentTime
                end
            end
        end
    end

    GrenadeTrajectoryPushPoint(Points, Position, true)
    return Points, BounceIndices, #Points >= 2
end
function GrenadeTrajectoryBuild()
    local Character =
        LocalPlayer.Character

    local CameraObject =
        workspace.CurrentCamera

    if not CameraObject then
        table.clear(
            GrenadeTrajectoryState.Points
        )
        table.clear(
            GrenadeTrajectoryState.BounceIndices
        )

        return
            GrenadeTrajectoryState.Points,
            GrenadeTrajectoryState.BounceIndices,
            false,
            false
    end

    local ActiveObject,
        ActivePart,
        ActiveProfile =
        GrenadeTrajectoryGetActiveProjectile()

    if ActiveObject
        and ActivePart
        and ActivePart.Parent
    then
        local Velocity =
            ActivePart.AssemblyLinearVelocity

        local Radius =
            math.clamp(
                math.max(
                    ActivePart.Size.X,
                    ActivePart.Size.Y,
                    ActivePart.Size.Z
                ) * 0.5,
                0.12,
                1.8
            )

        local Ignore = {
            Character,
            ActiveObject,
            CameraObject
        }

        local Points,
            BounceIndices,
            Valid =
            GrenadeTrajectorySimulate(
                ActivePart.Position,
                Velocity,
                ActiveProfile,
                Radius,
                Ignore
            )

        return
            Points,
            BounceIndices,
            Valid,
            true
    end

    if GrenadeTrajectoryState.ShowPreview
        ~= true
    then
        table.clear(
            GrenadeTrajectoryState.Points
        )
        table.clear(
            GrenadeTrajectoryState.BounceIndices
        )

        return
            GrenadeTrajectoryState.Points,
            GrenadeTrajectoryState.BounceIndices,
            false,
            false
    end

    local Tool =
        GrenadeTrajectoryGetTool()

    local Handle =
        GrenadeTrajectoryGetHandle(
            Tool
        )

    if not Tool
        or not Handle
    then
        table.clear(
            GrenadeTrajectoryState.Points
        )
        table.clear(
            GrenadeTrajectoryState.BounceIndices
        )

        return
            GrenadeTrajectoryState.Points,
            GrenadeTrajectoryState.BounceIndices,
            false,
            false
    end

    local Profile =
        GrenadeTrajectoryGetProfile(
            Tool
        )

    local CollisionPart =
        GrenadeTrajectoryGetCollisionPart(
            Tool,
            Handle
        )

    local RootPart =
        Character
        and Character:FindFirstChild(
            "HumanoidRootPart"
        )

    local StartPosition =
        GrenadeTrajectoryGetLaunchPoint(
            Tool,
            Handle
        )
        or Handle.Position

    local AimPoint =
        GrenadeTrajectoryGetAimPoint(
            CameraObject,
            Character,
            Tool
        )

    GrenadeTrajectoryState.LastHeldTool =
        Tool

    GrenadeTrajectoryState.LastHeldToolName =
        Tool.Name

    GrenadeTrajectoryState.LastHeldHandlePosition =
        Handle.Position

    GrenadeTrajectoryState.LastHeldHandleCFrame =
        Handle.CFrame

    GrenadeTrajectoryState.LastHeldCameraCFrame =
        CameraObject.CFrame

    GrenadeTrajectoryState.LastHeldProfile =
        Profile

    GrenadeTrajectoryState.LastHeldAt =
        os.clock()

    if typeof(AimPoint) ~= "Vector3" then
        table.clear(
            GrenadeTrajectoryState.Points
        )
        table.clear(
            GrenadeTrajectoryState.BounceIndices
        )

        return
            GrenadeTrajectoryState.Points,
            GrenadeTrajectoryState.BounceIndices,
            false,
            false
    end

    local AimDelta =
        AimPoint
        - StartPosition

    if AimDelta.Magnitude <= 0.001 then
        table.clear(
            GrenadeTrajectoryState.Points
        )
        table.clear(
            GrenadeTrajectoryState.BounceIndices
        )

        return
            GrenadeTrajectoryState.Points,
            GrenadeTrajectoryState.BounceIndices,
            false,
            false
    end

    local Direction =
        AimDelta.Unit

    local RootVelocity =
        RootPart
        and RootPart.AssemblyLinearVelocity
        or Vector3.zero

    local Velocity =
        Direction
        * Profile.ThrowSpeed
        + RootVelocity

    local Radius =
        CollisionPart
        and math.clamp(
            math.max(
                CollisionPart.Size.X,
                CollisionPart.Size.Y,
                CollisionPart.Size.Z
            ) * 0.5,
            0.12,
            1.8
        )
        or 0.35

    GrenadeTrajectoryState.LastHeldAimDirection =
        Direction

    GrenadeTrajectoryState.LastHeldRootVelocity =
        RootVelocity

    local Ignore = {
        Character,
        Tool,
        CameraObject
    }

    local Points,
        BounceIndices,
        Valid =
        GrenadeTrajectorySimulate(
            StartPosition,
            Velocity,
            Profile,
            Radius,
            Ignore
        )

    return
        Points,
        BounceIndices,
        Valid,
        false
end

function GrenadeTrajectoryStep()
    if not GrenadeTrajectoryState.Enabled then return end

    local CurrentTime = os.clock()

    if CurrentTime
        - (
            tonumber(
                GrenadeTrajectoryState.LastContainerRefresh
            ) or 0
        ) >= 1
    then
        GrenadeTrajectoryState.LastContainerRefresh =
            CurrentTime
        GrenadeTrajectoryBindDebrisFolder()
    end

    if CurrentTime - GrenadeTrajectoryState.LastUpdate >= GrenadeTrajectoryState.UpdateRate then
        GrenadeTrajectoryState.LastUpdate = CurrentTime

        local _, _, Valid, Active = GrenadeTrajectoryBuild()
        GrenadeTrajectoryState.LastValid = Valid == true
        GrenadeTrajectoryState.LastActive = Active == true
    end

    if GrenadeTrajectoryState.LastValid then
        GrenadeTrajectoryDraw(
            GrenadeTrajectoryState.Points,
            GrenadeTrajectoryState.BounceIndices,
            GrenadeTrajectoryState.LastActive
        )
    else
        GrenadeTrajectoryHide()
    end
end
function GrenadeTrajectoryEnable()
    if GrenadeTrajectoryState.Enabled then return end

    GrenadeTrajectoryState.Enabled = true
    GrenadeTrajectoryState.ShowLive = true
    GrenadeTrajectoryState.LastUpdate = 0
    GrenadeTrajectoryState.LastValid = false
    GrenadeTrajectoryState.LastActive = false
    GrenadeTrajectoryState.LastContainerRefresh = 0
    GrenadeTrajectoryClearActive()
    GrenadeTrajectoryBindDebrisFolder()

    if GrenadeTrajectoryState.Connection then GrenadeTrajectoryState.Connection:Disconnect() end
    GrenadeTrajectoryState.Connection = RunService.RenderStepped:Connect(function()
        Internal.Call(GrenadeTrajectoryStep)
    end)
end

function GrenadeTrajectoryDisable()
    GrenadeTrajectoryState.Enabled = false
    GrenadeTrajectoryState.LastValid = false
    GrenadeTrajectoryState.LastActive = false

    if GrenadeTrajectoryState.Connection then
        GrenadeTrajectoryState.Connection:Disconnect()
        GrenadeTrajectoryState.Connection = nil
    end

    if GrenadeTrajectoryState.DebrisConnection then
        GrenadeTrajectoryState.DebrisConnection:Disconnect()
        GrenadeTrajectoryState.DebrisConnection = nil
    end

    for Container, Connection in pairs(GrenadeTrajectoryState.ContainerConnections) do
        if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
        GrenadeTrajectoryState.ContainerConnections[Container] = nil
    end

    table.clear(GrenadeTrajectoryState.Containers)
    GrenadeTrajectoryState.DebrisFolder = nil
    GrenadeTrajectoryState.LastHeldTool = nil
    GrenadeTrajectoryState.LastHeldToolName = nil
    GrenadeTrajectoryState.LastHeldHandlePosition = nil
    GrenadeTrajectoryState.LastHeldHandleCFrame = nil
    GrenadeTrajectoryState.LastHeldCameraCFrame = nil
    GrenadeTrajectoryState.LastHeldAimDirection = nil
    GrenadeTrajectoryState.LastHeldRootVelocity = nil
    GrenadeTrajectoryState.LastHeldProfile = nil
    GrenadeTrajectoryState.LastHeldAt = 0
    GrenadeTrajectoryState.ActiveLastVelocity = nil
    GrenadeTrajectoryState.ActiveLastSample = 0
    GrenadeTrajectoryState.LastContainerRefresh = 0
    GrenadeTrajectoryClearActive()
    GrenadeTrajectoryClear()
end

local PreviousCriminologyGrenadePrediction = rawget(Environment, "AtramentaCriminologyGrenadePrediction")
if type(PreviousCriminologyGrenadePrediction) == "table" and type(PreviousCriminologyGrenadePrediction.Shutdown) == "function" then
    Internal.Call(function() PreviousCriminologyGrenadePrediction:Shutdown() end)
end

CriminologyGrenadePrediction = {}

function CriminologyGrenadePrediction:SetEnabled(Value)
    Value = Value == true
    if Value then GrenadeTrajectoryEnable() else GrenadeTrajectoryDisable() end
end

function CriminologyGrenadePrediction:SetOcclusion(Value)
    GrenadeTrajectoryState.Occlusion = Value == true
end

function CriminologyGrenadePrediction:Shutdown()
    GrenadeTrajectoryDisable()
end

rawset(Environment, "AtramentaCriminologyGrenadePrediction", CriminologyGrenadePrediction)
AtramentaRuntimeControl:AddCleanup(function()
    if CriminologyGrenadePrediction then CriminologyGrenadePrediction:Shutdown() end
    if rawget(Environment, "AtramentaCriminologyGrenadePrediction") == CriminologyGrenadePrediction then
        rawset(Environment, "AtramentaCriminologyGrenadePrediction", nil)
    end
end)

