function ProjectileController:IsNeeded()
    return self.RocketEnabled == true or self.C4Enabled == true
end

function ProjectileController:Disconnect(Connection)
    if Connection and typeof(Connection) == "RBXScriptConnection" then Connection:Disconnect() end
end

function ProjectileController:ClearToolConnections()
    for Index = 1, #self.ToolConnections do
        self:Disconnect(self.ToolConnections[Index])
    end

    table.clear(self.ToolConnections)
end

function ProjectileController:MarkProjectile(Name)
    self.RecentShots[Name] = os.clock()
end

function ProjectileController:MarkToolShot(Tool)
    if not Tool or not Tool:IsA("Tool") then return end

    local Projectiles = self.RocketTools[Tool.Name]
    if type(Projectiles) ~= "table" then return end

    local CurrentTime = os.clock()
    self.RecentShots.__Any = CurrentTime

    for Index = 1, #Projectiles do
        self.RecentShots[Projectiles[Index]] = CurrentTime
    end
end

function ProjectileController:IsRecentProjectile(Name)
    local CurrentTime = os.clock() local ShotTime = self.RecentShots[Name]

    if ShotTime and CurrentTime - ShotTime <= (Name == "TransIgnore" and 1.6 or 1.35) then return true end

    local AnyTime = self.RecentShots.__Any
    return self.RocketProjectiles[Name] == true and AnyTime and CurrentTime - AnyTime <= 1.20 or false
end

function ProjectileController:GetC4Remote()
    local Remote = self.LastC4Remote
    if Remote and Remote.Parent and Remote:IsA("RemoteEvent") then return Remote end
    local Character = LocalPlayer.Character
    local Tool = Character and Character:FindFirstChild("C4")
    if not Tool then
        local Backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
        Tool = Backpack and Backpack:FindFirstChild("C4")
    end
    Remote = Tool and Tool:FindFirstChild("Event")
    if Remote and Remote:IsA("RemoteEvent") then
        self.LastC4Remote = Remote
        return Remote
    end
    return nil
end

function ProjectileController:IsC4Remote(Remote)
    if not Remote or Remote.ClassName ~= "RemoteEvent" then return false end
    if Remote == self.CurrentC4Remote or Remote == self.LastC4Remote then return true end
    local Tool = Remote.Parent
    return Tool and Tool.ClassName == "Tool" and Tool.Name == "C4" and Remote.Name == "Event"
end

function ProjectileController:ShouldBlockC4Attach(Remote)
    if self.C4Enabled ~= true
        or not self:IsC4Remote(Remote)
    then
        return false
    end

    local CurrentTime =
        os.clock()

    if self.C4InitialDoPending == true then
        if CurrentTime
            <= (
                tonumber(
                    self.C4InitialDoExpires
                ) or 0
            )
        then
            self.C4InitialDoPending =
                false

            self.C4InitialDoExpires =
                0

            return false
        end

        self.C4InitialDoPending =
            false

        self.C4InitialDoExpires =
            0
    end

    local Object =
        self.CurrentObject

    return
        Object ~= nil
        and Object.Parent ~= nil
        and Object.Name == "TransIgnore"
end

function ProjectileController:GetMapPart()
    local Map = workspace:FindFirstChild("Map")
    if not Map then return nil end

    if Map:IsA("Model") and Map.PrimaryPart and Map.PrimaryPart:IsA("BasePart") then return Map.PrimaryPart end

    return Map:FindFirstChildWhichIsA("BasePart", true)
end

function ProjectileController:DetonateC4()
    local Object = self.CurrentObject
    if not Object or Object.Name ~= "TransIgnore" then return end
    local Remote = self.CurrentC4Remote or self:GetC4Remote()
    if not Remote then return end
    local FireServer = Remote.FireServer
    if type(FireServer) ~= "function" then return end
    self.C4Detonating = true
    local MapPart = self:GetMapPart()
    if MapPart then FireServer(Remote, "Do", MapPart, Object.CFrame) end
    FireServer(Remote, "Detonate")
    task.delay(0.12, function()
        if ProjectileController.CurrentObject == Object then ProjectileController:Release() end
    end)
end

function ProjectileController:BindTool(Tool)
    if not Tool or not Tool:IsA("Tool") then return end

    if Tool.Name == "C4" then
        local Remote = Tool:FindFirstChild("Event")
        if Remote and Remote:IsA("RemoteEvent") then self.LastC4Remote = Remote end
        self.ToolConnections[#self.ToolConnections + 1] = Tool.Activated:Connect(function()
            if not ProjectileController.C4Enabled then return end
            local C4Remote = Tool:FindFirstChild("Event")
            if C4Remote and C4Remote:IsA("RemoteEvent") then ProjectileController.LastC4Remote = C4Remote end
            if ProjectileController.CurrentObject
                and ProjectileController.CurrentObject.Name
                    == "TransIgnore"
            then
                ProjectileController:DetonateC4()
            else
                local CurrentTime =
                    os.clock()

                ProjectileController.C4ThrowUntil =
                    CurrentTime + 2

                ProjectileController.C4InitialDoPending =
                    true

                ProjectileController.C4InitialDoExpires =
                    CurrentTime + 0.45

                ProjectileController:MarkProjectile(
                    "TransIgnore"
                )
            end
        end)
        return
    end

    if self.RocketTools[Tool.Name] then
        self.ToolConnections[#self.ToolConnections + 1] = Tool.Activated:Connect(function()
            if ProjectileController.RocketEnabled then ProjectileController:MarkToolShot(Tool) end
        end)
    end
end

function ProjectileController:BindCharacter(Character)
    self:ClearToolConnections()
    self:Disconnect(self.CharacterChildConnection)
    self.CharacterChildConnection = nil

    if not Character then return end

    for _, Child in ipairs(Character:GetChildren()) do
        self:BindTool(Child)
    end

    self.CharacterChildConnection = Character.ChildAdded:Connect(function(Child)
        ProjectileController:BindTool(Child)
    end)
end

function ProjectileController:SaveCamera()
    local CameraObject = workspace.CurrentCamera
    if not CameraObject then return false end
    if Configuration and Configuration.Freecam and Configuration.Freecam.Enabled == true then return false end

    self.CameraRestoreToken += 1
    self.Camera = CameraObject
    self.SavedCameraType = CameraObject.CameraType
    self.SavedCameraSubject = CameraObject.CameraSubject
    self.SavedCameraCFrame = CameraObject.CFrame
    self.SavedCameraFocus = CameraObject.Focus
    self.SavedFieldOfView = CameraObject.FieldOfView
    self.SavedCameraMode = LocalPlayer.CameraMode
    self.SavedMinZoom = LocalPlayer.CameraMinZoomDistance
    self.SavedMaxZoom = LocalPlayer.CameraMaxZoomDistance
    self.SavedMouseBehavior = UserInputService.MouseBehavior
    self.SavedMouseIconEnabled = UserInputService.MouseIconEnabled

    LocalPlayer.CameraMode = Enum.CameraMode.Classic
    CameraObject.CameraType = Enum.CameraType.Scriptable
    UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
    UserInputService.MouseIconEnabled = false

    return true
end

function ProjectileController:RestoreCamera()
    self.CameraRestoreToken += 1
    local Token = self.CameraRestoreToken
    local Saved = {
        CameraType = self.SavedCameraType,
        Subject = self.SavedCameraSubject,
        CameraCFrame = self.SavedCameraCFrame,
        CameraFocus = self.SavedCameraFocus,
        FieldOfView = self.SavedFieldOfView,
        CameraMode = self.SavedCameraMode,
        MinZoom = self.SavedMinZoom,
        MaxZoom = self.SavedMaxZoom,
        MouseBehavior = self.SavedMouseBehavior,
        MouseIconEnabled = self.SavedMouseIconEnabled
    }

    local function Apply()
        if ProjectileController.CurrentObject or ProjectileController.CameraRestoreToken ~= Token then return end
        if Configuration and Configuration.Freecam and Configuration.Freecam.Enabled == true then
            ApplyFreecamMouseState()
            return
        end

        local CameraObject = workspace.CurrentCamera or ProjectileController.Camera local Character = LocalPlayer.Character
        local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

        if Saved.MinZoom ~= nil then LocalPlayer.CameraMinZoomDistance = Saved.MinZoom end
        if Saved.MaxZoom ~= nil then LocalPlayer.CameraMaxZoomDistance = Saved.MaxZoom end

        LocalPlayer.CameraMode = Enum.CameraMode.Classic

        if CameraObject then
            local Subject = Saved.Subject
            if not Subject or not Subject.Parent then Subject = Humanoid end

            CameraObject.CameraType = Saved.CameraType == Enum.CameraType.Scriptable and Enum.CameraType.Custom or Saved.CameraType or Enum.CameraType.Custom

            if Subject then CameraObject.CameraSubject = Subject end
            if Saved.FieldOfView then CameraObject.FieldOfView = Saved.FieldOfView end
            if typeof(Saved.CameraCFrame) == "CFrame" then CameraObject.CFrame = Saved.CameraCFrame end
            if typeof(Saved.CameraFocus) == "CFrame" then CameraObject.Focus = Saved.CameraFocus end
        end

        local CameraMode = Saved.CameraMode or Enum.CameraMode.Classic
        LocalPlayer.CameraMode = CameraMode

        if CameraMode == Enum.CameraMode.LockFirstPerson then
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled = false
        else
            UserInputService.MouseBehavior = Saved.MouseBehavior or Enum.MouseBehavior.Default
            UserInputService.MouseIconEnabled = Saved.MouseIconEnabled ~= false

            if Saved.MouseBehavior ~= Enum.MouseBehavior.LockCenter then
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
                UserInputService.MouseIconEnabled = true
            end
        end
    end

    Apply()

    task.spawn(function()
        RunService.RenderStepped:Wait()
        Apply()
        RunService.RenderStepped:Wait()
        Apply()
    end)

    self.Camera = nil
    self.SavedCameraType = nil
    self.SavedCameraSubject = nil
    self.SavedCameraCFrame = nil
    self.SavedCameraFocus = nil
    self.SavedFieldOfView = nil
    self.SavedCameraMode = nil
    self.SavedMinZoom = nil
    self.SavedMaxZoom = nil
    self.SavedMouseBehavior = nil
    self.SavedMouseIconEnabled = nil
end

function ProjectileController:HoldCharacter()
    if not self.CurrentObject then return end

    local Humanoid = self.SavedHumanoid local Root = self.SavedRoot

    if Humanoid and Humanoid.Parent then
        Humanoid.AutoRotate = false
        Humanoid.Jump = false
        Humanoid:Move(Vector3.zero, false)
    end

    if Root and Root.Parent then
        Root.Anchored = true
        Root.AssemblyLinearVelocity = Vector3.zero
        Root.AssemblyAngularVelocity = Vector3.zero
    end
end

function ProjectileController:LockCharacter()
    if self.CharacterLockBound then
        RunService:UnbindFromRenderStep(self.CharacterLockName)
        self.CharacterLockBound = false
    end

    local Character = LocalPlayer.Character local Root = Character and Character:FindFirstChild("HumanoidRootPart")
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    self.SavedRoot = Root
    self.SavedRootAnchored = Root and Root.Anchored or nil
    self.SavedHumanoid = Humanoid
    self.SavedAutoRotate = Humanoid and Humanoid.AutoRotate or nil

    if Root then Root.Anchored = true end

    if Humanoid then
        Humanoid.AutoRotate = false
        Humanoid.Jump = false
        Humanoid:Move(Vector3.zero, false)
    end

    RunService:BindToRenderStep(self.CharacterLockName, Enum.RenderPriority.Input.Value + 10, function()
        if ProjectileController.CurrentObject then ProjectileController:HoldCharacter() end
    end)

    self.CharacterLockBound = true
end

function ProjectileController:UnlockCharacter()
    if self.CharacterLockBound then
        RunService:UnbindFromRenderStep(self.CharacterLockName)
        self.CharacterLockBound = false
    end

    local Humanoid = self.SavedHumanoid local Root = self.SavedRoot

    if Humanoid and Humanoid.Parent then
        Humanoid:Move(Vector3.zero, false)
        if self.SavedAutoRotate ~= nil then Humanoid.AutoRotate = self.SavedAutoRotate == true end
    end

    if Root and Root.Parent then
        Root.AssemblyLinearVelocity = Vector3.zero
        Root.AssemblyAngularVelocity = Vector3.zero

        if self.SavedRootAnchored ~= nil then Root.Anchored = self.SavedRootAnchored == true end
    end

    self.SavedHumanoid = nil
    self.SavedAutoRotate = nil
    self.SavedRoot = nil
    self.SavedRootAnchored = nil
end

function ProjectileController:Release()
    self:Disconnect(self.CurrentRemovalConnection)
    self.CurrentRemovalConnection = nil
    local Object = self.CurrentObject
    local C4State = self.C4State
    if Object and Object.Parent and Object.Name == "TransIgnore" and type(C4State) == "table" and self.C4Detonating ~= true then
        Object.CanTouch = C4State.CanTouch == true
        Object.CanCollide = C4State.CanCollide == true
        Object.Anchored = C4State.Anchored == true
    end
    if self.CurrentBodyVelocity then self.CurrentBodyVelocity:Destroy() end
    if self.CurrentBodyGyro then self.CurrentBodyGyro:Destroy() end
    self.CurrentBodyVelocity = nil
    self.CurrentBodyGyro = nil
    self.CurrentObject = nil
    self.CurrentC4Remote = nil
    self.C4State = nil
    self.C4Position = nil
    self.C4LastStep = 0
    self.C4ThrowUntil = 0
    self.C4InitialDoPending = false
    self.C4InitialDoExpires = 0
    self.C4AcquireToken += 1
    self.C4Detonating = false
    self.Forward = 0
    self.Sideways = 0
    self.Vertical = 0
    self.CameraLookDirection = nil
    self.CameraFollowPosition = nil
    self.CameraYaw = 0
    self.CameraPitch = 0
    self:UnlockCharacter()
    self:RestoreCamera()
end

function ProjectileController:Acquire(Projectile)
    if not Projectile or not Projectile:IsA("BasePart") or self.CurrentObject then return end
    if Configuration and Configuration.Freecam and Configuration.Freecam.Enabled == true then return end
    if not self:SaveCamera() then return end
    self:LockCharacter()
    local StartCFrame = Projectile.CFrame
    local LookDirection = self.Camera and self.Camera.CFrame.LookVector or StartCFrame.LookVector
    if LookDirection.Magnitude <= 0.001 then LookDirection = Vector3.new(0, 0, -1) end
    self.CameraLookDirection = LookDirection.Unit
    self.CameraPitch = math.asin(math.clamp(self.CameraLookDirection.Y, -1, 1))
    self.CameraYaw = math.atan2(-self.CameraLookDirection.X, -self.CameraLookDirection.Z)
    self.CameraFollowPosition = StartCFrame.Position - self.CameraLookDirection * 7 + Vector3.new(0, 2.4, 0)
    self.CurrentObject = Projectile
    if Projectile.Name == "TransIgnore" then
        self.CurrentC4Remote = self:GetC4Remote()
        self.C4State = {Anchored = Projectile.Anchored, CanTouch = Projectile.CanTouch, CanCollide = Projectile.CanCollide}
        self.C4Position = StartCFrame.Position
        self.C4LastStep = os.clock()
        self.C4ThrowUntil = os.clock() + 2
        Projectile.Anchored = false
        Projectile.CanTouch = false
        Projectile.CanCollide = false
        Projectile.AssemblyLinearVelocity = Vector3.zero
        Projectile.AssemblyAngularVelocity = Vector3.zero
    else
        for _, Name in ipairs({"BodyForce", "BodyAngularVelocity"}) do
            local Object = Projectile:FindFirstChild(Name)
            if Object then Object:Destroy() end
        end
        local RotationPart = Projectile:FindFirstChild("RotPart")
        local RotationVelocity = RotationPart and RotationPart:FindFirstChildOfClass("BodyAngularVelocity")
        if RotationVelocity then RotationVelocity:Destroy() end
        local BodyVelocity = Instance.new("BodyVelocity")
        BodyVelocity.Name = "AtramentaProjectileVelocity"
        BodyVelocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
        BodyVelocity.Velocity = Vector3.zero
        BodyVelocity.P = 50000
        BodyVelocity.Parent = Projectile
        local BodyGyro = Instance.new("BodyGyro")
        BodyGyro.Name = "AtramentaProjectileGyro"
        BodyGyro.P = 90000
        BodyGyro.D = 1200
        BodyGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
        BodyGyro.CFrame = CFrame.lookAt(StartCFrame.Position, StartCFrame.Position + self.CameraLookDirection)
        BodyGyro.Parent = Projectile
        self.CurrentBodyVelocity = BodyVelocity
        self.CurrentBodyGyro = BodyGyro
    end
    self.CurrentRemovalConnection = Projectile.AncestryChanged:Connect(function(_, Parent)
        if not Parent and ProjectileController.CurrentObject == Projectile then ProjectileController:Release() end
    end)
end

function ProjectileController:RegisterProjectile(Projectile)
    if not self:IsNeeded()
        or self.CurrentObject
        or not Projectile
        or not Projectile:IsA("BasePart")
    then
        return
    end

    local Name =
        Projectile.Name

    local IsC4 =
        Name == "TransIgnore"

    local IsRocket =
        self.RocketProjectiles[Name]
        == true

    if IsC4
        and not self.C4Enabled
    then
        return
    end

    if IsRocket
        and not self.RocketEnabled
    then
        return
    end

    if not IsC4
        and not IsRocket
    then
        return
    end

    if not self:IsRecentProjectile(
        Name
    )
    then
        return
    end

    local Character =
        LocalPlayer.Character

    local Root =
        Character
        and (
            Character:FindFirstChild(
                "HumanoidRootPart"
            )
            or Character:FindFirstChild(
                "Head"
            )
        )

    if Root
        and (
            Projectile.Position
            - Root.Position
        ).Magnitude > 35
    then
        return
    end

    self.RecentShots[Name] =
        nil

    if not IsC4 then
        self:Acquire(
            Projectile
        )
        return
    end

    self.C4AcquireToken += 1

    local Token =
        self.C4AcquireToken

    local function AcquireC4()
        if Token
                ~= ProjectileController.C4AcquireToken
            or ProjectileController.C4Enabled
                ~= true
            or ProjectileController.CurrentObject
            or not Projectile
            or not Projectile.Parent
        then
            return
        end

        local CurrentTime =
            os.clock()

        if ProjectileController.C4InitialDoPending
                == true
            and CurrentTime
                <= (
                    tonumber(
                        ProjectileController.C4InitialDoExpires
                    ) or 0
                )
        then
            task.delay(
                0.05,
                AcquireC4
            )

            return
        end

        ProjectileController.C4InitialDoPending =
            false

        ProjectileController.C4InitialDoExpires =
            0

        ProjectileController:Acquire(
            Projectile
        )
    end

    task.delay(
        0.08,
        AcquireC4
    )
end

function ProjectileController:ApplyCamera()
    local Object = self.CurrentObject local CameraObject = workspace.CurrentCamera or self.Camera

    if not Object or not Object.Parent or not CameraObject or not self.CameraLookDirection then return end

    self.Camera = CameraObject
    CameraObject.CameraType = Enum.CameraType.Scriptable

    local DesiredPosition = Object.Position - self.CameraLookDirection * 7 + Vector3.new(0, 2.4, 0)

    if self.CameraFollowPosition then
        self.CameraFollowPosition = self.CameraFollowPosition:Lerp(DesiredPosition, 0.25)
    else
        self.CameraFollowPosition = DesiredPosition
    end

    CameraObject.CFrame = CFrame.lookAt(
        self.CameraFollowPosition,
        Object.Position + self.CameraLookDirection * 18 + Vector3.new(0, 0.8, 0)
    )
end

function ProjectileController:Step()
    self:HoldCharacter()
    local Object = self.CurrentObject
    if not Object or not Object.Parent then
        if Object then self:Release() end
        return
    end
    local MouseDelta = UserInputService:GetMouseDelta()
    local Sensitivity = 0.0024
    self.CameraYaw -= MouseDelta.X * Sensitivity
    self.CameraPitch = math.clamp(self.CameraPitch - MouseDelta.Y * Sensitivity, -1.22, 1.10)
    local DesiredDirection = Vector3.new(
        -math.sin(self.CameraYaw) * math.cos(self.CameraPitch),
        math.sin(self.CameraPitch),
        -math.cos(self.CameraYaw) * math.cos(self.CameraPitch)
    )
    DesiredDirection = DesiredDirection.Magnitude > 0.001 and DesiredDirection.Unit or Vector3.new(0, 0, -1)
    self.CameraLookDirection = self.CameraLookDirection and self.CameraLookDirection:Lerp(DesiredDirection, 0.35) or DesiredDirection
    self.CameraLookDirection = self.CameraLookDirection.Magnitude > 0.001 and self.CameraLookDirection.Unit or DesiredDirection
    local RightDirection = self.CameraLookDirection:Cross(Vector3.new(0, 1, 0))
    RightDirection = RightDirection.Magnitude > 0.001 and RightDirection.Unit or Vector3.new(1, 0, 0)
    local MoveDirection = self.CameraLookDirection * self.Forward + RightDirection * self.Sideways
    if Object.Name == "TransIgnore" then MoveDirection += Vector3.new(0, tonumber(self.Vertical) or 0, 0) end
    if MoveDirection.Magnitude > 1 then MoveDirection = MoveDirection.Unit end
    local Speed = math.clamp(tonumber(self.Speed) or 200, 50, 500)
    if Object.Name == "TransIgnore" then
        local CurrentTime = os.clock()
        local Previous = tonumber(self.C4LastStep) or CurrentTime
        local DeltaTime = math.clamp(CurrentTime - Previous, 1 / 360, 0.05)
        self.C4LastStep = CurrentTime
        self.C4Position = typeof(self.C4Position) == "Vector3" and self.C4Position or Object.Position
        self.C4Position += MoveDirection * Speed * DeltaTime
        Object.Anchored = false
        Object.CanTouch = false
        Object.CanCollide = false
        local TargetCFrame = CFrame.lookAt(self.C4Position, self.C4Position + self.CameraLookDirection)
        if type(WriteFlyCFrame) == "function" then WriteFlyCFrame(Object, TargetCFrame) else Object.CFrame = TargetCFrame end
        Object.AssemblyLinearVelocity = Vector3.zero
        Object.AssemblyAngularVelocity = Vector3.zero
        self:ApplyCamera()
        return
    end
    local BodyVelocity = self.CurrentBodyVelocity
    local BodyGyro = self.CurrentBodyGyro
    if not BodyVelocity or not BodyVelocity.Parent or not BodyGyro or not BodyGyro.Parent then
        self:Release()
        return
    end
    BodyVelocity.Velocity = MoveDirection * Speed
    BodyGyro.CFrame = CFrame.lookAt(Object.Position, Object.Position + self.CameraLookDirection)
    self:ApplyCamera()
end

function ProjectileController:BindProjectileContainer()
    self:Disconnect(self.ProjectileConnection)
    self.ProjectileConnection = nil

    local DebrisFolder = workspace:FindFirstChild("Debris") local VParts = DebrisFolder and DebrisFolder:FindFirstChild("VParts")
    if not VParts then return end

    self.ProjectileConnection = VParts.ChildAdded:Connect(function(Projectile)
        if Projectile and Projectile.Name == "TransIgnore" then
            ProjectileController:RegisterProjectile(Projectile)
        else
            task.defer(function() ProjectileController:RegisterProjectile(Projectile) end)
        end
    end)
end

function ProjectileController:Start()
    if self.Active or not self:IsNeeded() then return end
    self.Active = true
    if type(InstallSharedNamecallRouter) == "function" then InstallSharedNamecallRouter() end
    self:BindCharacter(LocalPlayer.Character)
    self:BindProjectileContainer()

    self.CharacterConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
        ProjectileController:Release()
        ProjectileController:BindCharacter(Character)
    end)

    self.CameraConnection = workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        if ProjectileController.CurrentObject then ProjectileController:ApplyCamera() end
    end)

    self.InputBeganConnection = UserInputService.InputBegan:Connect(function(Input, Processed)
        if Input.KeyCode == Enum.KeyCode.Escape and ProjectileController.CurrentObject then
            ProjectileController:Release()
            return
        end

        if Processed then return end

        if Input.KeyCode == Enum.KeyCode.W then ProjectileController.Forward = 1
        elseif Input.KeyCode == Enum.KeyCode.S then ProjectileController.Forward = -1
        elseif Input.KeyCode == Enum.KeyCode.D then ProjectileController.Sideways = 1
        elseif Input.KeyCode == Enum.KeyCode.A then ProjectileController.Sideways = -1
        elseif Input.KeyCode == Enum.KeyCode.Space then ProjectileController.Vertical = 1
        elseif Input.KeyCode == Enum.KeyCode.LeftControl then ProjectileController.Vertical = -1 end
    end)

    self.InputEndedConnection = UserInputService.InputEnded:Connect(function(Input)
        if Input.KeyCode == Enum.KeyCode.W or Input.KeyCode == Enum.KeyCode.S then ProjectileController.Forward = 0
        elseif Input.KeyCode == Enum.KeyCode.D or Input.KeyCode == Enum.KeyCode.A then ProjectileController.Sideways = 0
        elseif Input.KeyCode == Enum.KeyCode.Space or Input.KeyCode == Enum.KeyCode.LeftControl then ProjectileController.Vertical = 0 end
    end)

    self.RenderConnection = RunService.RenderStepped:Connect(function()
        if ProjectileController.CurrentObject then ProjectileController:Step() end
    end)
end

function ProjectileController:Stop()
    if not self.Active then
        self:Release()
        return
    end

    self.Active = false
    self:Release()
    self:ClearToolConnections()

    self:Disconnect(self.CharacterConnection)
    self:Disconnect(self.CharacterChildConnection)
    self:Disconnect(self.ProjectileConnection)
    self:Disconnect(self.CameraConnection)
    self:Disconnect(self.InputBeganConnection)
    self:Disconnect(self.InputEndedConnection)
    self:Disconnect(self.RenderConnection)

    self.CharacterConnection = nil
    self.CharacterChildConnection = nil
    self.ProjectileConnection = nil
    self.CameraConnection = nil
    self.InputBeganConnection = nil
    self.InputEndedConnection = nil
    self.RenderConnection = nil

    self.C4InitialDoPending =
        false

    self.C4InitialDoExpires =
        0

    self.C4AcquireToken += 1

    table.clear(
        self.RecentShots
    )
end

function ProjectileController:Refresh()
    if self:IsNeeded() then
        self:Start()
        self:BindCharacter(LocalPlayer.Character)
        self:BindProjectileContainer()
    else
        self:Stop()
    end
end

function ProjectileController:Destroy()
    self.RocketEnabled = false
    self.C4Enabled = false
    self:Stop()
end

rawset(Environment, "AtramentaProjectileController", ProjectileController)
AtramentaRuntimeControl:AddCleanup(function()
    ProjectileController:Destroy()

    if rawget(Environment, "AtramentaProjectileController") == ProjectileController then
        rawset(Environment, "AtramentaProjectileController", nil)
    end
end)

