    AntiAFKEnabled = false
    AtramentaFarmModule.Settings.AntiAFK = false
    AtramentaPerformanceRuntime.Enabled = false
end

Internal.DisableDefaults()
RestoreAtramentaRageFireRate()
if type(RestoreRageFireRateUpvalues) == "function" then RestoreRageFireRateUpvalues() end
if type(RefreshAimEngine) == "function" then RefreshAimEngine() end
if type(HeadHitbox) == "table" and type(HeadHitbox.Disable) == "function" then HeadHitbox.Disable() end
if type(DisableSilentAimController) == "function" then DisableSilentAimController() end
Environment.SilentAim = false
VisualState.World.StopTimeLock()
RefreshLocalShotTracking()
CombatLogRuntime.RefreshEnemyShotTracking()

function BuildAtramentaMenu()
    local Window = Library:Window({ Name = "Atramenta.rip", Size = UDim2.fromOffset(680, 500), FadeSpeed = 0.12, Style = "Atramenta Emerald",
        StyleCallback = function(Value)
            Internal.ApplyThemePreset(Value)
        end })
    Window.IsOpen = true
    local Watermark = Library:Watermark("Atramenta.rip") local KeybindList = Library:KeybindList() local PlayerList = nil

    if type(Library.PlayerList) == "function" then
        PlayerList = Library:PlayerList({ Brand = "Atramenta", Visible = false, Scale = 100, StatusChanged = function(Player, Status)
                AtramentaSetPlayerStatusRuntime( Player, Status)
            end, Spectate = function(Player)
                local CameraObject = Internal.GetCamera() local Character = Player and Player.Character local Humanoid = Character and Character:FindFirstChildOfClass( "Humanoid")

                if CameraObject and Humanoid then CameraObject.CameraSubject = Humanoid end
            end, Unspectate = function()
                local CameraObject = Internal.GetCamera() local Character = LocalPlayer.Character

                local Humanoid = Character and Character:FindFirstChildOfClass( "Humanoid")

                if CameraObject and Humanoid then CameraObject.CameraSubject = Humanoid end
            end })

    end

    Library.MenuKeybind = Enum.KeyCode.Delete
    Watermark:SetVisibility(true)
    if type(Watermark.SetScale) == "function" then Watermark:SetScale(VisualState.Widgets.WatermarkScale * 100) end
    KeybindList:SetVisibility(false)
