    local PlayerESPElementFlags = {
        Box = "Player ESP Boxes",
        Fill = "Player ESP Fill",
        Name = "Player ESP Names",
        Avatar = "Player ESP Profile Picture",
        ["Health Bar"] = "Player ESP Health Bar",
        ["Health Text"] = "Player ESP Health Value",
        Weapon = "Player ESP Weapon",
        Ammo = "Player ESP Ammo",
        Distance = "Player ESP Distance",
        Level = "Player ESP Level",
        Forcefield = "Player ESP Forcefield",
        Flags = "Player ESP Flags",
        Skeleton = "Player ESP Skeleton",
        ["View Direction"] = "Player ESP Look Line",
        Tracer = "Player ESP Tracers",
        Offscreen = "Player ESP Offscreen",
        Prediction = "Player ESP Prediction",
        ["Box Glow"] = "Player ESP Box Glow",
        ["Visibility Colors"] = "Player ESP Adaptive Color",
        ["Health Trail"] = "Player ESP Delayed Health"
    }

    local PlayerESPElementNames = {
        "Box", "Fill", "Name", "Avatar", "Health Bar", "Health Text",
        "Weapon", "Ammo", "Distance", "Level", "Forcefield", "Flags",
        "Skeleton", "View Direction", "Tracer", "Offscreen", "Prediction",
        "Box Glow", "Visibility Colors", "Health Trail"
    }

    function ApplyPlayerESPElement(Name, Value)
        Name = tostring(Name)
        Value = Value == true

        if Name == "Box" then
            VisualState.Player.Boxes = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Box then Data.Drawings.Box.Visible = false end
                    if Data.Drawings.BoxOutline then Data.Drawings.BoxOutline.Visible = false end
                    if Data.CornersReady then
                        for Index = 1, 8 do
                            if Data.Corners[Index] then Data.Corners[Index].Visible = false end
                            if Data.CornerOutlines[Index] then Data.CornerOutlines[Index].Visible = false end
                        end
                    end
                    if Data.UiEsp then
                        if Data.UiEsp.Box then Data.UiEsp.Box.Visible = false end
                        if Data.UiEsp.BoxOutline then Data.UiEsp.BoxOutline.Visible = false end
                        if type(Data.UiEsp.Corners) == "table" then
                            for _, Corner in ipairs(Data.UiEsp.Corners) do Corner.Visible = false end
                        end
                    end
                end
            end
        elseif Name == "Fill" then
            VisualState.Player.Fill = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Fill then Data.Drawings.Fill.Visible = false end
                    if Data.UiEsp and Data.UiEsp.Fill then Data.UiEsp.Fill.Visible = false end
                end
            end
        elseif Name == "Name" then
            VisualState.Player.Names = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Name then Data.Drawings.Name.Visible = false end
                    if Data.UiEsp and Data.UiEsp.Name then Data.UiEsp.Name.Visible = false end
                end
            end
        elseif Name == "Avatar" then
            VisualState.Player.ProfilePicture = Value
            if Value and VisualState.Player.Renderer == "Drawing API" then
                for _, Data in ipairs(VisualState.Player.List) do
                    Internal.EnsureProfilePictureDrawings(Data)
                    QueueAtramentaProfilePicture(Data)
                end
            elseif not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.ProfilePicture then Data.Drawings.ProfilePicture.Visible = false end
                    if Data.Drawings.ProfilePictureBack then Data.Drawings.ProfilePictureBack.Visible = false end
                    if Data.UiEsp and Data.UiEsp.AvatarBack then Data.UiEsp.AvatarBack.Visible = false end
                end
            end
        elseif Name == "Health Bar" then
            VisualState.Player.HealthBar = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    for _, Key in ipairs({"HealthBack", "HealthDelayed", "Health"}) do
                        if Data.Drawings[Key] then Data.Drawings[Key].Visible = false end
                    end
                    if Data.UiEsp then
                        for _, Key in ipairs({"HealthBack", "HealthDelayed", "Health"}) do
                            if Data.UiEsp[Key] then Data.UiEsp[Key].Visible = false end
                        end
                    end
                end
            end
        elseif Name == "Health Text" then
            VisualState.Player.HealthText = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.HealthText then Data.Drawings.HealthText.Visible = false end
                    if Data.UiEsp and Data.UiEsp.HealthText then Data.UiEsp.HealthText.Visible = false end
                end
            end
        elseif Name == "Weapon" then
            VisualState.Player.Weapon = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Weapon then Data.Drawings.Weapon.Visible = false end
                    if Data.UiEsp and Data.UiEsp.Weapon then Data.UiEsp.Weapon.Visible = false end
                end
            end
        elseif Name == "Ammo" then
            VisualState.Player.Ammo.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    for _, Key in ipairs({"AmmoBack", "AmmoBar", "AmmoText"}) do
                        if Data.Drawings[Key] then Data.Drawings[Key].Visible = false end
                    end
                    if Data.UiEsp then
                        for _, Key in ipairs({"AmmoBack", "Ammo", "AmmoText"}) do
                            if Data.UiEsp[Key] then Data.UiEsp[Key].Visible = false end
                        end
                    end
                end
            end
        elseif Name == "Distance" then
            VisualState.Player.Distance = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Distance then Data.Drawings.Distance.Visible = false end
                    if Data.UiEsp and Data.UiEsp.Distance then Data.UiEsp.Distance.Visible = false end
                end
            end
        elseif Name == "Level" then
            VisualState.Player.Level = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Level then Data.Drawings.Level.Visible = false end
                    if Data.UiEsp and Data.UiEsp.Level then Data.UiEsp.Level.Visible = false end
                end
            end
        elseif Name == "Forcefield" then
            VisualState.Player.Forcefield.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Forcefield then Data.Drawings.Forcefield.Visible = false end
                    if Data.UiEsp and Data.UiEsp.Forcefield then Data.UiEsp.Forcefield.Visible = false end
                end
            end
        elseif Name == "Flags" then
            VisualState.Player.Flags.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.Flags then Data.Drawings.Flags.Visible = false end
                    if Data.UiEsp and Data.UiEsp.Flags then Data.UiEsp.Flags.Visible = false end
                end
            end
        elseif Name == "Skeleton" then
            VisualState.Player.Skeleton.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do HideSkeletonDrawings(Data) end
            end
        elseif Name == "View Direction" then
            VisualState.Player.Look.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.LookLine then Data.Drawings.LookLine.Visible = false end
                end
            end
        elseif Name == "Tracer" then
            VisualState.Player.Tracers = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do Internal.HideTracerDrawings(Data) end
            end
        elseif Name == "Offscreen" then
            VisualState.Player.Offscreen.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do HideOffscreenArrowDrawings(Data) end
            end
        elseif Name == "Prediction" then
            VisualState.Player.Prediction.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    if Data.Drawings.PredictionMarker then Data.Drawings.PredictionMarker.Visible = false end
                    if Data.Drawings.PredictionOutline then Data.Drawings.PredictionOutline.Visible = false end
                end
            end
        elseif Name == "Box Glow" then
            VisualState.Player.BoxGlow.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    for Index = 1, 3 do
                        local Glow = Data.Drawings["GlowBox" .. Index]
                        if Glow then Glow.Visible = false end
                    end
                end
            end
        elseif Name == "Visibility Colors" then
            VisualState.Player.Visibility.Enabled = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    Data.LastEspAdaptiveColor = VisualState.Player.BoxColor
                    Data.LastEspAdaptiveOutline = VisualState.Player.OutlineColor
                    Data.NextVisibilityUpdate = 0
                end
            end
            UpdatePlayerChams()
        elseif Name == "Health Trail" then
            VisualState.Player.Health.Delayed = Value
            if not Value then
                for _, Data in ipairs(VisualState.Player.List) do
                    Data.DelayedHealthPercent = Data.DisplayedHealthPercent
                    Data.HealthDamageHoldUntil = 0
                    if Data.Drawings.HealthDelayed then Data.Drawings.HealthDelayed.Visible = false end
                    if Data.UiEsp and Data.UiEsp.HealthDelayed then Data.UiEsp.HealthDelayed.Visible = false end
                end
            end
        end

        local Flag = PlayerESPElementFlags[Name]
        if Flag and type(Library) == "table" and type(Library.Flags) == "table" then
            Library.Flags[Flag] = Value
        end

        for _, Data in ipairs(VisualState.Player.List) do
            Data.NextEspUpdate = 0
            Data.NextFastDetailUpdate = 0
            Data.LastProjectionHealthAt = 0
        end

        SyncAtramentaESPPreview()
        EnsureVisualEngine()
    end

    function GetPlayerESPElementSelection()
        local Result = {}
        for _, Name in ipairs(PlayerESPElementNames) do
            local Flag = PlayerESPElementFlags[Name]
            if Flag and type(Library) == "table" and type(Library.Flags) == "table" then
                local State
                if Name == "Box" then State = VisualState.Player.Boxes
                elseif Name == "Fill" then State = VisualState.Player.Fill
                elseif Name == "Name" then State = VisualState.Player.Names
                elseif Name == "Avatar" then State = VisualState.Player.ProfilePicture
                elseif Name == "Health Bar" then State = VisualState.Player.HealthBar
                elseif Name == "Health Text" then State = VisualState.Player.HealthText
                elseif Name == "Weapon" then State = VisualState.Player.Weapon
                elseif Name == "Ammo" then State = VisualState.Player.Ammo.Enabled
                elseif Name == "Distance" then State = VisualState.Player.Distance
                elseif Name == "Level" then State = VisualState.Player.Level
                elseif Name == "Forcefield" then State = VisualState.Player.Forcefield.Enabled
                elseif Name == "Flags" then State = VisualState.Player.Flags.Enabled
                elseif Name == "Skeleton" then State = VisualState.Player.Skeleton.Enabled
                elseif Name == "View Direction" then State = VisualState.Player.Look.Enabled
                elseif Name == "Tracer" then State = VisualState.Player.Tracers
                elseif Name == "Offscreen" then State = VisualState.Player.Offscreen.Enabled
                elseif Name == "Prediction" then State = VisualState.Player.Prediction.Enabled
                elseif Name == "Box Glow" then State = VisualState.Player.BoxGlow.Enabled
                elseif Name == "Visibility Colors" then State = VisualState.Player.Visibility.Enabled
                elseif Name == "Health Trail" then State = VisualState.Player.Health.Delayed end
                if State == true then Result[#Result + 1] = Name end
            end
        end
        return Result
    end

    function ApplyPlayerESPElementSelection(Selection)
        local Selected = {}
        if type(Selection) == "table" then
            for _, Name in ipairs(Selection) do Selected[tostring(Name)] = true end
        end
        for _, Name in ipairs(PlayerESPElementNames) do
            ApplyPlayerESPElement(Name, Selected[Name] == true)
        end
    end

    function CreatePlayerESPElementSetter(ElementName, FlagName)
        return function(Value)
            Value = Value == true
            if type(Library) == "table" and type(Library.Flags) == "table" and type(FlagName) == "string" then
                Library.Flags[FlagName] = Value
            end
            ApplyPlayerESPElement(ElementName, Value)
        end
    end

    if type(Library.Setters) == "table" then
        for ElementName, FlagName in pairs(PlayerESPElementFlags) do
            Library.Setters[FlagName] = CreatePlayerESPElementSetter(ElementName, FlagName)
        end
    end

