        if Value ~= "Drawing API" and Value ~= "Roblox UI" then Value = "Drawing API" end
        VisualState.Player.Renderer = Value
        for _, Data in ipairs(VisualState.Player.List) do
            Internal.HidePlayerVisual(Data)
            if Value == "Drawing API" then DestroyPlayerUiEsp(Data) else HidePlayerDrawingCore(Data) end
            Data.NextEspUpdate = 0
            Data.NextFastDetailUpdate = 0
            Data.LastProjectionHealthAt = 0
        end
        RefreshPlayerUiProjection()
        EnsureVisualEngine()
    end })

