    local PlayerAdvancedSection = VisualESP:Section({ Name = "ESP Extras", Side = 1 })

    function ApplyPlayerESPIndicator(Name, Value)
        if Name == "Prediction Marker" then Name = "Prediction" end
        ApplyPlayerESPElement(Name, Value)
    end

    function GetPlayerESPIndicatorSelection()
        local Result = {}
        for _, Name in ipairs({"Offscreen", "Skeleton", "View Direction", "Box Glow", "Visibility Colors", "Health Trail", "Prediction"}) do
            local Flag = PlayerESPElementFlags[Name]
            if Flag and type(Library) == "table" and type(Library.Flags) == "table" and Library.Flags[Flag] == true then
                Result[#Result + 1] = Name
            end
        end
        return Result
    end

