    local AntiAimManual = MovementAntiAim:Section({ Name = "Manual", Side = 2 })
    local AntiAimNetwork = MovementAntiAim:Section({ Name = "Network", Side = 1 })
    local AntiAimPosition = MovementAntiAim:Section({ Name = "Fake Position", Side = 2 })

    AntiAimGeneral:Toggle({ Name = "Enabled", Flag = "Hide Head", Default = false, Callback = function(Value)
        SetHideHeadEnabled(Value)
    end })

    AntiAimGeneral:Dropdown({ Name = "Mode", Flag = "Anti Aim Mode", Default = GetAntiAimMode(), Items = { "Manual", "Down", "Spin" },
        Callback = function(Value)
            HideHeadController.Mode = tostring(Value)

            if HideHeadController.Mode == "Manual" then
                HideHeadController.Pitch = 0
            elseif HideHeadController.Mode == "Down" and math.abs( tonumber(HideHeadController.Pitch) or 0 ) < 1 then
                HideHeadController.Pitch = -82
            elseif HideHeadController.Mode ~= "Down" and math.abs( tonumber(HideHeadController.Pitch) or 0 ) >= 78 then
                HideHeadController.Pitch = 0
            end

            ResetAntiAimNetworkState()
            UpdateManualAntiAimIndicator()
        end })

    AntiAimGeneral:Slider({ Name = "Pitch", Flag = "Anti Aim Pitch", Min = -89, Max = 89, Default = tonumber(HideHeadController.Pitch) or 0, Step = 1,
        Suffix = "°", Callback = function(Value)
            HideHeadController.Pitch = math.clamp( tonumber(Value) or 0, -89, 89)
        end })

