AtramentaRuntimeControl:AddCleanup(function()
    if type(Ragebot.DestroyFieldOfView) == "function" then Ragebot.DestroyFieldOfView() end
    if type(DestroyHitFeedbackRuntime) == "function" then DestroyHitFeedbackRuntime() end
    if type(RestoreWorldVisuals) == "function" then RestoreWorldVisuals(true) end
    if VisualState and VisualState.World and type(VisualState.World.StopTimeLock) == "function" then VisualState.World.StopTimeLock() end
    if type(Internal.DestroyWorldEffects) == "function" then Internal.DestroyWorldEffects() end
    if type(ClearWeaponShaders) == "function" then ClearWeaponShaders() end
    if PlushieState and type(PlushieState.Destroy) == "function" then PlushieState.Destroy() end
    if type(ArmsChamsDisable) == "function" then ArmsChamsDisable() end
    if type(WeaponChamsDisable) == "function" then WeaponChamsDisable() end
    if type(GunMaterialChamsDisable) == "function" then GunMaterialChamsDisable() end
    if type(GrenadeTrajectoryDisable) == "function" then GrenadeTrajectoryDisable() end
    if type(AutoBlockDisable) == "function" then AutoBlockDisable() end
    if type(AutoPickupMoneyDisable) == "function" then AutoPickupMoneyDisable() end
    if type(FastPickupDisable) == "function" then FastPickupDisable() end
    if type(NoFailLockpickDisable) == "function" then NoFailLockpickDisable() end
    if type(OpenNearbyDoorsDisable) == "function" then OpenNearbyDoorsDisable() end
    if type(UnlockNearbyDoorsDisable) == "function" then UnlockNearbyDoorsDisable() end
    if type(AtramentaExtraDestroy) == "function" then AtramentaExtraDestroy() end
    if WalkSpeed and type(WalkSpeed.Shutdown) == "function" then WalkSpeed.Shutdown() end
    if Jump and type(Jump.Shutdown) == "function" then Jump.Shutdown() end
    if type(NoclipDisable) == "function" then NoclipDisable() end
    if type(FlyDisable) == "function" then FlyDisable() end
    if type(InvisibilityDisable) == "function" then InvisibilityDisable() end
    if type(InfStaminaDisable) == "function" then InfStaminaDisable() end
    if type(NoFallDamageDisable) == "function" then NoFallDamageDisable() end
    if type(AntiFlashbangDisable) == "function" then AntiFlashbangDisable() end
    if type(AntiSmokeDisable) == "function" then AntiSmokeDisable() end
    if type(AntiBarbwireDisable) == "function" then AntiBarbwireDisable() end
    if type(NoBarriersDisable) == "function" then NoBarriersDisable() end
    if type(PepperAuraDisable) == "function" then PepperAuraDisable() end
    if type(AutoRespawnDisable) == "function" then AutoRespawnDisable() end
    if type(AntiAFKDisable) == "function" then AntiAFKDisable() end
    if type(MeleeAuraDisable) == "function" then MeleeAuraDisable() end
    if type(FinishAuraDisable) == "function" then FinishAuraDisable() end
    if type(ToggleDemonCosmetics) == "function" then ToggleDemonCosmetics(false) end

    BunnyHopEnabled = false
    AutoStrafeEnabled = false
    AirControlEnabled = false
    PixelSurfEnabled = false
    MovementDriverEnabled = false
    if type(UpdateMovementAssistConnection) == "function" then UpdateMovementAssistConnection() end
    if type(ResetMovementDriver) == "function" then ResetMovementDriver() end

    if Configuration and Configuration.CharacterAddedConnection then Configuration.CharacterAddedConnection:Disconnect(); Configuration.CharacterAddedConnection = nil end
    if RespawnSafetyState then
        if RespawnSafetyState.RemovingConnection then RespawnSafetyState.RemovingConnection:Disconnect(); RespawnSafetyState.RemovingConnection = nil end
        if RespawnSafetyState.AddedConnection then RespawnSafetyState.AddedConnection:Disconnect(); RespawnSafetyState.AddedConnection = nil end
        if RespawnSafetyState.DiedConnection then RespawnSafetyState.DiedConnection:Disconnect(); RespawnSafetyState.DiedConnection = nil end
    end

    if VisualState.Connection then VisualState.Connection:Disconnect(); VisualState.Connection = nil end
    if VisualState.PlayerAddedConnection then VisualState.PlayerAddedConnection:Disconnect(); VisualState.PlayerAddedConnection = nil end
    if VisualState.PlayerRemovingConnection then VisualState.PlayerRemovingConnection:Disconnect(); VisualState.PlayerRemovingConnection = nil end
    if VisualState.WorldContainerConnection then VisualState.WorldContainerConnection:Disconnect(); VisualState.WorldContainerConnection = nil end
    if VisualState.WorldCharactersConnection then VisualState.WorldCharactersConnection:Disconnect(); VisualState.WorldCharactersConnection = nil end
    if VisualState.WorldRootConnection then VisualState.WorldRootConnection:Disconnect(); VisualState.WorldRootConnection = nil end
    DisconnectWorldOverrideSignals()
    if VisualState.Initialized and type(ShutdownPlayerVisualCache) == "function" then ShutdownPlayerVisualCache() end

    if Ragebot.Runtime and Ragebot.Runtime.ModeMoveState and type(Ragebot.RestoreModePosition) == "function" then
        Ragebot.RestoreModePosition(Ragebot.Runtime.ModeMoveState)
    end
    if Ragebot and type(Ragebot.DestroyTargetLine) == "function" then Ragebot.DestroyTargetLine() end
    if type(SafeFarmDisable) == "function" then SafeFarmDisable() end
    if type(AltFarmDisable) == "function" then AltFarmDisable() end
    if AtramentaFarmModule and type(AtramentaFarmModule.Destroy) == "function" then AtramentaFarmModule.Destroy() end
    if type(AutoATMDisable) == "function" then AutoATMDisable() end
    if Configuration.NoRecoil and Configuration.NoRecoil.Enabled and type(DisableGunMods) == "function" then DisableGunMods() end
    if type(SetHideHeadEnabled) == "function" and HideHeadEnabled then SetHideHeadEnabled(false) end
    if AntiAFKThread then task.cancel(AntiAFKThread); AntiAFKThread = nil end

    if BacktrackVisualState and type(BacktrackVisualState.Destroy) == "function" then BacktrackVisualState:Destroy() end
    ExtendedVisualState:Destroy()
    GameVisualState:Destroy()
    RestoreAtramentaPerformanceFlags()
end)

GameVisualState.OriginalUnload = Library.Unload
Library.Unload = function(...)
    if HeadHitbox and type(HeadHitbox.Disable) == "function" then HeadHitbox.Disable() end

    AtramentaRuntimeControl:Destroy()
    return GameVisualState.OriginalUnload(...)
end

BuildAtramentaMenu()
if Configuration.CharacterAddedConnection then Configuration.CharacterAddedConnection:Disconnect() end
if RespawnSafetyState.RemovingConnection then RespawnSafetyState.RemovingConnection:Disconnect() end
RespawnSafetyState.RemovingConnection = LocalPlayer.CharacterRemoving:Connect(function(Character)
    Internal.ClearRespawnTransientState(Character)
end)
Configuration.CharacterAddedConnection = LocalPlayer.CharacterAdded:Connect(function(Character)
    RespawnSafetyState.Generation += 1
    local Generation = RespawnSafetyState.Generation
    local Preserved = RespawnSafetyState.Preserved or {}
    RespawnSafetyState.Suspended = true
    RespawnSafetyState.CurrentCharacter = Character
    RespawnSafetyState.RespawnRequestedFor = nil
    Internal.BindRespawnSafety(Character)
    Internal.Call(function()
        if Configuration.NoRecoil and Configuration.NoRecoil.Enabled and type(BindGunCharacter) == "function" then BindGunCharacter(Character) end
    end)
    task.spawn(function()
        if not Character or not Character.Parent then return end

        local Humanoid = Character:FindFirstChildOfClass("Humanoid") or Character:WaitForChild("Humanoid", 8)
        local RootPart = Character:FindFirstChild("HumanoidRootPart") or Character:WaitForChild("HumanoidRootPart", 8)
        if not Humanoid or not RootPart or not Humanoid.Parent or not RootPart.Parent then return end

        local StartedAt = os.clock()
        while Generation == RespawnSafetyState.Generation and Character == LocalPlayer.Character and Character.Parent
            and (not Character:IsDescendantOf(workspace) or Humanoid.Parent and Humanoid.Health <= 0) and os.clock() - StartedAt < 8
        do
            task.wait(0.1)
        end

        task.wait(0.8)

        if not ( Generation == RespawnSafetyState.Generation and Character == LocalPlayer.Character and Character.Parent and Humanoid.Parent
            and RootPart.Parent and Humanoid.Health > 0 ) then
            return
        end

        RespawnSafetyState.Suspended = false
        RespawnSafetyState.Preserved = nil

        if Configuration.ChinaHat.Enabled then
            Internal.Call(function()
                CreateChinaHat(Character)
            end)
        end

        if Configuration.AngelWings.Enabled then
            Internal.Call(function()
                RebuildAngelWings()
            end)
        end

        if Configuration.Demon.Enabled then
            Internal.Call(function()
                CreateDemonCosmetics(Character)
            end)
        end

        if Preserved.World and WorldEffectsState.Enabled then Internal.Call(StartWorldEffects) end

        if Preserved.WeaponShader and WeaponShaderSettings.Enabled then
            Internal.Call(function()
                BindWeaponShaderLifecycle()
                EnsureWeaponShaderRender()
                RebindWeaponShadersAfterRespawn(Character)
            end)
        end

        task.wait(0.15)

        if not ( Generation == RespawnSafetyState.Generation ) then return end

        if Preserved.Arms then Internal.Call( ArmsChamsEnable) end

        if Preserved.Weapon then Internal.Call( WeaponChamsEnable) end

        if Preserved.Bunny or Preserved.Strafe or Preserved.Air then
            BunnyHopEnabled = Preserved.Bunny == true

            AutoStrafeEnabled = Preserved.Strafe == true

            AirControlEnabled = Preserved.Air == true

            Internal.Call( UpdateMovementAssistConnection)
        end

        task.wait(0.35)

        if not ( Generation == RespawnSafetyState.Generation ) then return end

        if Preserved.Noclip then Internal.Call( NoclipEnable) end

        if Preserved.Fly then Internal.Call( FlyEnable) end

        if Preserved.Invis then Internal.Call( InvisibilityEnable) end

        task.wait(0.35)

        if Generation == RespawnSafetyState.Generation then
            if Preserved.Stamina then Internal.Call( InfStaminaEnable) end

            if Preserved.NoFall then Internal.Call( NoFallDamageEnable) end

            if Preserved.Rage then
                Internal.Call(function()
                    Ragebot.Enable()
                end)
            end
        end
    end)
end)
if LocalPlayer.Character then
    RespawnSafetyState.Suspended = false
    Internal.BindRespawnSafety(LocalPlayer.Character)
end
